/* ===== Research Consultancy page (rc-) ===== */
.rc{--rc-ink:#07104F;--rc-brand:#0B22A8;--rc-bright:#1E6BFF;--rc-r:#1E5BFF;--rc-soft:#E6EDFF;--rc-line:#DDE2EC;--rc-muted:#525C78;--rc-amber:#E3A013;--rc-warn:#B4424B;--rc-warn-soft:#FBEEEF;--rc-paper:#F5F7FB;overflow-x:clip}
.rc .rc-ico{flex:none}
.rc-sec{padding:clamp(64px,8vw,112px) 0;position:relative}
.rc-sec--tint{background:#fff}
.rc-sec--ink{background:linear-gradient(165deg,#07104F 0%,#0B1A78 100%);color:#fff}
.rc-kicker{display:inline-flex;align-items:center;gap:8px;font:600 .78rem/1 var(--body);letter-spacing:.14em;text-transform:uppercase;color:var(--rc-r);margin-bottom:14px}
.rc-kicker:before{content:"";width:22px;height:2px;background:currentColor;border-radius:2px}
.rc-kicker--warn{color:var(--rc-warn)}
.rc-head{max-width:760px;margin-bottom:clamp(32px,4vw,52px)}
.rc-head h2{margin-bottom:.35em}
.rc-head--center{margin-inline:auto;text-align:center}
.rc-head--center .rc-kicker{justify-content:center}
.rc-head__intro{color:var(--rc-muted);font-size:1.08rem;margin:0}
.rc-head--light h2{color:#fff}.rc-head--light .rc-kicker{color:#9DB6FF}.rc-head--light .rc-head__intro{color:#C9D3F5}
.rc-lead{font-size:clamp(1.08rem,1.5vw,1.25rem);line-height:1.6;color:var(--rc-ink);font-weight:500;margin:0}
.rc-illus{display:inline-flex;align-items:center;gap:6px;font:600 .7rem/1 var(--body);letter-spacing:.06em;text-transform:uppercase;color:var(--rc-muted);background:var(--rc-paper);border:1px dashed #B9C2D3;border-radius:999px;padding:6px 10px;white-space:nowrap}
.rc-illus--light{color:#C9D3F5;background:#ffffff10;border-color:#ffffff40}
.rc-link{display:inline-flex;align-items:center;gap:6px;font-weight:600;color:var(--rc-r);text-decoration:none;font-size:.95rem}
.rc-link:hover{text-decoration:underline}
.rc-reveal{opacity:0;transform:translateY(18px);transition:opacity .7s ease,transform .7s cubic-bezier(.2,.7,.2,1);transition-delay:calc(var(--i,0)*80ms)}
.rc-reveal.is-in{opacity:1;transform:none}

/* hero */
.rc-hero{position:relative;background:radial-gradient(900px 520px at 78% 40%,#1438C8 0%,transparent 60%),linear-gradient(160deg,#07104F 0%,#0A1766 60%,#081257 100%);color:#fff;padding:clamp(40px,5vw,72px) 0 clamp(96px,10vw,140px);overflow:hidden}
.rc-hero__grid-bg{position:absolute;inset:0;background-image:linear-gradient(#ffffff0a 1px,transparent 1px),linear-gradient(90deg,#ffffff0a 1px,transparent 1px);background-size:44px 44px;mask-image:radial-gradient(ellipse at 70% 45%,#000 0%,transparent 70%);-webkit-mask-image:radial-gradient(ellipse at 70% 45%,#000 0%,transparent 70%)}
.rc-hero__in{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1.08fr);gap:clamp(24px,4vw,56px);align-items:center}
.rc-hero .crumbs{margin-bottom:28px}
.rc-hero__eyebrow{display:inline-flex;align-items:center;gap:10px;font:600 .8rem/1 var(--body);letter-spacing:.14em;text-transform:uppercase;color:#9DB6FF;margin-bottom:18px}
.rc-hero__eyebrow i{width:8px;height:8px;border-radius:50%;background:var(--rc-amber);box-shadow:0 0 0 4px #E3A01333}
.rc-hero h1{color:#fff;margin-bottom:.3em}
.rc-hero__sub{font:600 clamp(1.25rem,2vw,1.6rem)/1.35 var(--display);letter-spacing:-.015em;color:#fff;max-width:30ch;margin-bottom:18px}
.rc-hero__body{color:#C9D3F5;font-size:1.06rem;max-width:56ch;margin-bottom:30px}
.rc-hero__ctas{display:flex;flex-wrap:wrap;gap:12px}
.rc-net{width:100%;height:auto;display:block;overflow:visible}
.rc-net__lbl{font:700 10.5px var(--body);letter-spacing:.09em;fill:#E4EAFF}
.rc-net__core{font:800 13px var(--display);letter-spacing:.08em;fill:#fff}
.rc-net__mid{font:700 10.5px var(--body);letter-spacing:.1em;fill:#fff}
.rc-net__dec{font:800 12.5px var(--display);letter-spacing:.06em;fill:#07104F}
.rc-net__node{opacity:0;animation:rcFade .6s ease forwards}
.rc-flowline{animation:rcDash 2.4s linear infinite}
.rc-pulse{transform-box:fill-box;transform-origin:center;animation:rcPulse 3s ease-out infinite}
.rc-pulse2{animation:rcGlowA 3s ease-in-out infinite}
.rc-spin{transform-box:fill-box;transform-origin:center;animation:rcSpin 60s linear infinite}
@keyframes rcDash{to{stroke-dashoffset:-42}}
@keyframes rcFade{to{opacity:1}}
@keyframes rcPulse{0%{transform:scale(1);opacity:.6}100%{transform:scale(1.35);opacity:0}}
@keyframes rcGlowA{0%,100%{stroke-opacity:.25}50%{stroke-opacity:1}}
@keyframes rcSpin{to{transform:rotate(360deg)}}
.rc-netm{display:none}

/* strip */
.rc-strip{list-style:none;margin:-64px 0 0;padding:8px;display:grid;grid-template-columns:repeat(4,1fr);background:#fff;border-radius:20px;box-shadow:0 1px 2px #13213C10,0 24px 48px -24px #13213C40;position:relative;z-index:2}
.rc-strip li{display:flex;gap:14px;padding:20px 20px;align-items:flex-start}
.rc-strip li+li{border-left:1px solid var(--rc-line)}
.rc-strip__ico{width:40px;height:40px;border-radius:12px;display:grid;place-items:center;background:var(--rc-soft);color:var(--rc-r);flex:none}
.rc-strip strong{display:block;font:700 .98rem/1.3 var(--display);letter-spacing:-.01em;margin-bottom:4px}
.rc-strip li div>span{font-size:.88rem;color:var(--rc-muted);line-height:1.45;display:block}

/* sub nav */
.rc-subnav{position:sticky;top:var(--header-h);z-index:20;background:#F5F7FBEE;backdrop-filter:blur(10px);-webkit-backdrop-filter:blur(10px);border-bottom:1px solid var(--rc-line);margin-top:40px}
.rc-subnav__in{display:flex;gap:4px;overflow-x:auto;scrollbar-width:none;padding:10px 0}
.rc-subnav__in::-webkit-scrollbar{display:none}
.rc-subnav a{flex:none;text-decoration:none;font-weight:600;font-size:.9rem;color:var(--rc-muted);padding:8px 14px;border-radius:999px;transition:background .2s,color .2s}
.rc-subnav a:hover{color:var(--rc-ink)}
.rc-subnav a.is-on{background:var(--rc-ink);color:#fff}

/* problem */
.rc-prob{display:grid;grid-template-columns:minmax(0,.8fr) minmax(0,1.2fr);gap:clamp(28px,5vw,72px);align-items:center}
.rc-prob h2{font-size:clamp(2rem,4vw,3.2rem)}
.rc-prob__quote{font:500 clamp(1.1rem,1.6vw,1.3rem)/1.6 var(--body);color:var(--rc-ink);border-left:3px solid var(--rc-warn);padding-left:20px;margin:0}
.rc-break{background:#fff;border:1px solid var(--rc-line);border-radius:24px;padding:clamp(20px,3vw,32px)}
.rc-break__top{display:flex;justify-content:space-between;align-items:center;gap:12px;flex-wrap:wrap;margin-bottom:22px}
.rc-break__title{font:700 1.05rem var(--display)}
.rc-break__legend{font-size:.8rem;color:var(--rc-muted);display:flex;align-items:center;gap:8px}
.rc-break__legend i{width:28px;height:6px;border-radius:3px;background:linear-gradient(90deg,var(--rc-r),var(--rc-warn))}
.rc-break__chain{list-style:none;margin:0;padding:0;display:grid;grid-template-columns:repeat(7,1fr);gap:6px;position:relative}
.rc-break__chain li{display:flex;flex-direction:column;gap:8px;position:relative;opacity:0;transform:translateY(10px);transition:opacity .5s,transform .5s;transition-delay:calc(var(--i)*110ms)}
.rc-break.is-in li{opacity:1;transform:none}
.rc-break__chain li:not(:last-child):after{content:"";position:absolute;top:21px;left:46px;right:-6px;height:1px;background:repeating-linear-gradient(90deg,#C5CCDA 0 4px,transparent 4px 8px)}
.rc-break__ico{width:42px;height:42px;border-radius:12px;display:grid;place-items:center;background:var(--rc-warn-soft);color:var(--rc-warn);border:1px solid #F2D3D6}
.rc-break__chain li:first-child .rc-break__ico{background:var(--rc-soft);color:var(--rc-r);border-color:#CBD8FF}
.rc-break__n{font:700 .7rem var(--body);color:#97A0B5;letter-spacing:.08em}
.rc-break__t{font:600 .88rem/1.25 var(--display);color:var(--rc-ink);min-height:2.5em}
.rc-break__bar{height:6px;border-radius:3px;background:#EEF1F6;overflow:hidden}
.rc-break__bar b{display:block;height:100%;border-radius:3px;background:linear-gradient(90deg,var(--rc-r),var(--rc-warn));transform-origin:left;transform:scaleX(0);transition:transform .9s cubic-bezier(.2,.7,.2,1);transition-delay:calc(var(--i)*110ms + .3s)}
.rc-break.is-in .rc-break__bar b{transform:scaleX(1)}
.rc-break__foot{margin:22px 0 0;padding-top:16px;border-top:1px solid var(--rc-line);font-size:.92rem;color:var(--rc-muted)}

/* solution */
.rc-sec--sol{padding-top:clamp(84px,9vw,124px)}
.rc-turn{position:absolute;top:0;left:50%;transform:translate(-50%,-50%);z-index:2}
.rc-turn span{display:inline-flex;align-items:center;gap:10px;background:var(--rc-ink);color:#fff;font:600 .82rem var(--body);letter-spacing:.04em;padding:10px 18px;border-radius:999px;white-space:nowrap;box-shadow:0 10px 24px -10px #07104F80}
.rc-turn span:after{content:"↓";color:var(--rc-amber)}
.rc-solhead{display:grid;grid-template-columns:minmax(0,.7fr) minmax(0,1.3fr);gap:clamp(20px,5vw,72px);align-items:end;margin-bottom:clamp(36px,5vw,64px)}
.rc-solhead .rc-head{margin:0}
.rc-sol{display:grid;grid-template-columns:repeat(4,1fr);gap:clamp(14px,2vw,28px);position:relative}
.rc-sol__track{position:absolute;top:36px;left:36px;right:12%;height:2px;background:var(--rc-line)}
.rc-sol__track span{display:block;height:100%;background:linear-gradient(90deg,var(--rc-r),var(--rc-amber));transform-origin:left;transform:scaleX(0);transition:transform 1.6s cubic-bezier(.2,.7,.2,1)}
.rc-sol.is-in .rc-sol__track span{transform:scaleX(1)}
.rc-sol__step{position:relative;opacity:0;transform:translateY(14px);transition:opacity .6s,transform .6s;transition-delay:calc(var(--i)*.3s)}
.rc-sol.is-in .rc-sol__step{opacity:1;transform:none}
.rc-sol__dot{width:72px;height:72px;border-radius:22px;background:#fff;border:1px solid var(--rc-line);display:grid;place-items:center;color:var(--rc-r);box-shadow:0 12px 28px -16px #13213C55;margin-bottom:22px;position:relative}
.rc-sol__step:last-child .rc-sol__dot{background:var(--rc-ink);color:#fff;border-color:var(--rc-ink)}
.rc-sol__n{font:700 .72rem var(--body);letter-spacing:.12em;text-transform:uppercase;color:#97A0B5}
.rc-sol__step h3{font-size:clamp(1.4rem,2.2vw,1.9rem);margin:.25em 0 .4em}
.rc-sol__step p{color:var(--rc-muted);font-size:.98rem;margin:0}
.rc-sol__cap{margin:clamp(32px,4vw,48px) 0 0;text-align:center;font:600 1.05rem var(--display);color:var(--rc-ink)}
.rc-sol__cap:before,.rc-sol__cap:after{content:"";display:inline-block;width:40px;height:1px;background:var(--rc-line);vertical-align:middle;margin:0 14px}

/* framework */
.rc-fw{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:clamp(28px,5vw,72px);align-items:center}
.rc-fw__wheel svg{width:100%;max-width:520px;display:block;margin:auto;overflow:visible}
.rc-fw__q{cursor:pointer;outline:none}
.rc-fw__q path{fill:#fff;stroke:var(--rc-line);stroke-width:1.5;transition:fill .3s,stroke .3s}
.rc-fw__q:hover path{fill:var(--rc-soft)}
.rc-fw__q.is-on path{fill:var(--rc-r);stroke:var(--rc-r)}
.rc-fw__q:focus-visible path{stroke:var(--rc-amber);stroke-width:3}
.rc-fw__qn{font:700 12px var(--body);fill:#97A0B5;letter-spacing:.1em}
.rc-fw__qt{font:700 15px var(--display);fill:var(--rc-ink)}
.rc-fw__q.is-on .rc-fw__qn{fill:#C9D6FF}.rc-fw__q.is-on .rc-fw__qt{fill:#fff}
.rc-fw__core{font:800 11.5px var(--display);fill:#fff;letter-spacing:.1em}
.rc-fw__panel{background:#fff;border:1px solid var(--rc-line);border-radius:24px;padding:clamp(24px,3vw,40px);position:relative;animation:rcPanel .45s ease}
@keyframes rcPanel{from{opacity:0;transform:translateX(12px)}to{opacity:1;transform:none}}
.rc-fw__tabs{display:none}
.rc-fw__num{position:absolute;right:28px;top:14px;font:800 4.4rem/1 var(--display);color:var(--rc-soft);letter-spacing:-.04em}
.rc-fw__panel h3{display:flex;gap:10px;align-items:flex-start;font-size:clamp(1.25rem,2vw,1.55rem);position:relative;max-width:22ch;color:var(--rc-ink)}
.rc-fw__panel h3 .rc-ico{color:var(--rc-r);margin-top:4px}
.rc-fw__panel p{color:var(--rc-muted)}
.rc-fw__lbl{font:700 .72rem var(--body);letter-spacing:.12em;text-transform:uppercase;color:#97A0B5}
.rc-fw__panel ul{list-style:none;margin:12px 0 0;padding:0;display:grid;gap:8px}
.rc-fw__panel li{display:flex;gap:10px;align-items:center;padding:12px 14px;background:var(--rc-paper);border-radius:12px;font-weight:600;font-size:.96rem}
.rc-fw__panel li .rc-ico{color:var(--rc-r)}

/* services grid */
.rc-svc{display:grid;grid-template-columns:1.15fr 1fr 1fr;gap:16px;align-items:start}
.rc-svc__card{background:var(--rc-paper);border:1px solid var(--rc-line);border-radius:20px;padding:24px;display:flex;flex-direction:column;transition:transform .25s,box-shadow .25s,border-color .25s,background .25s;position:relative}
.rc-svc__card:hover{transform:translateY(-3px);box-shadow:0 20px 40px -24px #13213C60;border-color:#C5D3FF;background:#fff}
.rc-svc__card.rc-svc__card--advisory{grid-row:span 3;background:var(--rc-ink);color:#fff;border-color:var(--rc-ink);padding:32px;align-self:stretch}
.rc-svc__card.rc-svc__card--advisory:hover{background:#0A1766;border-color:#0A1766}
.rc-svc__card.rc-svc__card--advisory h3{font-size:clamp(1.4rem,2.2vw,1.9rem);color:#fff}
.rc-svc__card.rc-svc__card--advisory p{color:#C9D3F5;font-size:1.04rem;max-width:44ch}
.rc-svc__card.rc-svc__card--advisory .rc-svc__ico{background:#ffffff14;color:#fff}
.rc-svc__card.rc-svc__card--advisory .rc-svc__n{color:#7F8CC4}
.rc-svc__card.rc-svc__card--advisory .rc-svc__tog{color:#fff;border-color:#ffffff40}
.rc-svc__card.rc-svc__card--advisory li{color:#E4EAFF}
.rc-svc__card.rc-svc__card--advisory .rc-svc__more li .rc-ico{color:var(--rc-amber)}
.rc-svc__card--advisory:after{content:"";position:absolute;right:-40px;bottom:-40px;width:220px;height:220px;border-radius:50%;border:1px solid #ffffff1a;box-shadow:0 0 0 30px #ffffff06,0 0 0 60px #ffffff04;pointer-events:none}
.rc-svc__top{display:flex;justify-content:space-between;align-items:center;margin-bottom:18px}
.rc-svc__n{font:700 .8rem var(--body);letter-spacing:.1em;color:#97A0B5}
.rc-svc__ico{width:44px;height:44px;border-radius:12px;display:grid;place-items:center;background:var(--rc-soft);color:var(--rc-r)}
.rc-svc__card h3{font-size:1.1rem;margin-bottom:.4em}
.rc-svc__card p{font-size:.93rem;color:var(--rc-muted);margin:0 0 14px}
.rc-svc__more{margin-bottom:14px}
.rc-svc__more[hidden]{display:none}
.rc-svc__more ul{list-style:none;margin:0 0 12px;padding:12px 0 0;border-top:1px solid #0000001a;display:grid;gap:7px}
.rc-svc__card.rc-svc__card--advisory .rc-svc__more ul{border-color:#ffffff26}
.rc-svc__more li{display:flex;gap:8px;align-items:flex-start;font-size:.9rem;font-weight:500}
.rc-svc__more li .rc-ico{color:var(--rc-r);margin-top:3px}
.rc-svc__tog{margin-top:auto;align-self:flex-start;display:inline-flex;align-items:center;gap:6px;background:transparent;border:1px solid #C5CCDA;border-radius:999px;padding:7px 14px;font-size:.85rem;font-weight:600;color:var(--rc-ink)}
.rc-svc__tog .rc-ico{transition:transform .25s}
.rc-svc__tog .is-x{transform:rotate(45deg)}

/* deep dives */
.rc-sec--dd{background:linear-gradient(180deg,var(--rc-paper),#fff)}
.rc-dd{display:grid;gap:clamp(56px,7vw,96px)}
.rc-dd__row,.rc-dd__price{display:grid;grid-template-columns:minmax(0,.85fr) minmax(0,1.15fr);gap:clamp(28px,5vw,72px);align-items:center;scroll-margin-top:140px}
.rc-dd__row--flip>.rc-dd__copy{order:2}
.rc-dd__row--wide{grid-template-columns:minmax(0,.6fr) minmax(0,1.4fr)}
.rc-dd__band{background:var(--rc-ink);color:#fff;border-radius:28px;padding:clamp(32px,5vw,64px);scroll-margin-top:140px;overflow:hidden}
.rc-dd__band h3{color:#fff}.rc-dd__band .rc-dd__copy p{color:#C9D3F5}.rc-dd__band .rc-kicker{color:#9DB6FF}
.rc-dd__copy h3{font-size:clamp(1.5rem,2.6vw,2.1rem);margin-bottom:.45em}
.rc-dd__copy p{color:var(--rc-muted);font-size:1.02rem}
.rc-dd__copy--center{text-align:center;max-width:680px;margin:0 auto clamp(32px,4vw,48px)}
.rc-dd__copy--center .rc-kicker{justify-content:center}
.rc-chain{display:flex;flex-wrap:wrap;gap:6px;margin-top:18px}
.rc-chain span{font-size:.84rem;font-weight:600;padding:7px 12px;border-radius:999px;background:#fff;border:1px solid var(--rc-line);display:inline-flex;align-items:center;gap:6px}
.rc-chain span:not(:last-child):after{content:"→";color:var(--rc-r)}
.rc-chain span:last-child{background:var(--rc-ink);color:#fff;border-color:var(--rc-ink)}
.rc-viz{background:#fff;border:1px solid var(--rc-line);border-radius:22px;padding:clamp(18px,2.5vw,28px);box-shadow:0 24px 48px -36px #13213C60}
.rc-viz__bar{display:flex;justify-content:space-between;align-items:center;gap:10px;flex-wrap:wrap;margin-bottom:12px}
.rc-viz__bar>span:first-child{font:700 .98rem var(--display)}
.rc-viz svg{width:100%;height:auto;display:block;overflow:visible}
.rc-viz__axis{font:600 11.5px var(--body);fill:var(--rc-muted)}
.rc-viz__tag{font:700 11px var(--body);fill:var(--rc-r);letter-spacing:.04em}
.rc-viz__tag--amb{fill:#A87300}
.rc-viz__legend{display:flex;flex-wrap:wrap;gap:16px;font-size:.84rem;color:var(--rc-muted);margin-top:8px}
.rc-viz__legend span{display:inline-flex;align-items:center;gap:7px}
.rc-viz__legend i{width:14px;height:4px;border-radius:2px;background:var(--rc-r)}
.rc-viz__legend i.b{background:#A9B2C1}
.rc-viz__legend i.c1{background:#7FA6FF}.rc-viz__legend i.c2{background:var(--rc-ink)}.rc-viz__legend i.wtp{background:var(--rc-amber)}
.rc-viz__note{font-size:.82rem;color:var(--rc-muted);margin:12px 0 0}
.rc-radar__a{fill:#1E5BFF2e;stroke:var(--rc-r);stroke-width:2.5;stroke-linejoin:round}
.rc-radar__b{fill:none;stroke:#A9B2C1;stroke-width:2;stroke-dasharray:5 5}
.rc-radar__a,.rc-radar__b{transform-origin:200px 190px;transform:scale(.2);opacity:0;transition:transform 1s cubic-bezier(.2,.7,.2,1),opacity .6s}
.rc-radar.is-in .rc-radar__a,.rc-radar.is-in .rc-radar__b{transform:none;opacity:1}
.rc-radar.is-in .rc-radar__b{transition-delay:.2s}
.rc-scroll{overflow-x:auto;-webkit-overflow-scrolling:touch}
.rc-bench table{width:100%;border-collapse:separate;border-spacing:0;min-width:560px;font-size:.92rem}
.rc-bench th,.rc-bench td{padding:13px 14px;text-align:left;border-bottom:1px solid var(--rc-line)}
.rc-bench thead th{font:700 .76rem var(--body);letter-spacing:.06em;text-transform:uppercase;color:var(--rc-muted)}
.rc-bench tbody th{font-weight:600}
.rc-bench .is-you{background:var(--rc-soft)}
.rc-bench thead .is-you{color:var(--rc-r);border-radius:12px 12px 0 0}
.rc-bench tbody tr:last-child .is-you{border-radius:0 0 12px 12px}
.rc-dots{display:inline-flex;gap:4px}
.rc-dots i{width:9px;height:9px;border-radius:50%;background:#E3E7EF}
.rc-dots i.on{background:#7F8CC4}
.is-you .rc-dots i.on{background:var(--rc-r)}
.rc-npd{display:grid;grid-template-columns:repeat(6,1fr);gap:10px;position:relative}
.rc-npd__line{position:absolute;top:28px;left:8%;right:8%;height:2px;background:#ffffff26}
.rc-npd__line span{display:block;height:100%;background:linear-gradient(90deg,#7FA6FF,var(--rc-amber));transform-origin:left;transform:scaleX(0);transition:transform 2s cubic-bezier(.2,.7,.2,1)}
.rc-npd.is-in .rc-npd__line span{transform:scaleX(1)}
.rc-npd__s{display:flex;flex-direction:column;align-items:center;text-align:center;gap:8px;position:relative;opacity:0;transform:translateY(10px);transition:opacity .5s,transform .5s;transition-delay:calc(var(--i)*.28s)}
.rc-npd.is-in .rc-npd__s{opacity:1;transform:none}
.rc-npd__dot{width:56px;height:56px;border-radius:50%;display:grid;place-items:center;background:#0E1E86;border:1px solid #5F82FF;color:#fff}
.rc-npd__s:last-child .rc-npd__dot{background:var(--rc-amber);border-color:var(--rc-amber);color:var(--rc-ink)}
.rc-npd__gate{font:700 .68rem var(--body);letter-spacing:.12em;text-transform:uppercase;color:#7F8CC4}
.rc-npd__s strong{font:600 .98rem/1.25 var(--display)}
.rc-funnel{display:grid;gap:8px}
.rc-funnel__row{display:grid;grid-template-columns:1fr;justify-items:center;text-align:center}
.rc-funnel__bar{width:var(--w);display:flex;align-items:center;justify-content:center;gap:12px;padding:13px 18px;border-radius:12px;background:linear-gradient(90deg,#0B22A8,#1E5BFF);color:#fff;box-shadow:0 10px 20px -14px #0B22A8}
.rc-funnel__row:nth-child(even) .rc-funnel__bar{background:linear-gradient(90deg,#0F1D72,#1E46D8)}
.rc-funnel__row:last-child .rc-funnel__bar{background:var(--rc-ink);box-shadow:inset 0 0 0 2px var(--rc-amber)}
.rc-funnel__bar span{font:700 .72rem var(--body);opacity:.65;letter-spacing:.08em}
.rc-funnel__bar strong{font:600 1rem var(--display)}
.rc-funnel__row p{font-size:.84rem;color:var(--rc-muted);margin:4px 0 0}
.rc-dd__price{grid-template-columns:minmax(0,.8fr) minmax(0,1.2fr)}
.rc-dd__stack{display:grid;gap:14px}
.rc-tri{display:flex;align-items:stretch;gap:8px;margin-top:22px;flex-wrap:wrap}
.rc-tri>div{flex:1 1 120px;background:#fff;border:1px solid var(--rc-line);border-radius:14px;padding:14px;display:flex;flex-direction:column;gap:4px}
.rc-tri>div .rc-ico{color:var(--rc-r)}
.rc-tri>div:last-of-type{background:var(--rc-ink);color:#fff;border-color:var(--rc-ink)}
.rc-tri>div:last-of-type .rc-ico{color:var(--rc-amber)}
.rc-tri strong{font:700 .95rem var(--display)}
.rc-tri span{font-size:.8rem;color:var(--rc-muted)}
.rc-tri>div:last-of-type span{color:#C9D3F5}
.rc-tri__a{align-self:center;color:#97A0B5}
.rc-price__c1,.rc-price__c2,.rc-price__wtp{fill:none;stroke-width:2.5;stroke-dasharray:600;stroke-dashoffset:600;transition:stroke-dashoffset 1.8s ease}
.rc-price__c1{stroke:#7FA6FF}.rc-price__c2{stroke:var(--rc-ink)}.rc-price__wtp{stroke:var(--rc-amber);stroke-dasharray:6 6;stroke-dashoffset:0;opacity:0;transition:opacity 1s 1.2s}
.rc-price.is-in .rc-price__c1,.rc-price.is-in .rc-price__c2{stroke-dashoffset:0}
.rc-price.is-in .rc-price__wtp{opacity:1}
.rc-price__band{opacity:0;transition:opacity .8s 1s}.rc-price.is-in .rc-price__band{opacity:1}
.rc-price__opt{opacity:0;transition:opacity .5s 1.6s}.rc-price.is-in .rc-price__opt{opacity:1}
.rc-conj__row{display:grid;grid-template-columns:80px 1fr;gap:12px;align-items:center;margin-bottom:10px;font-size:.88rem;font-weight:600}
.rc-conj__row div{height:10px;background:#EEF1F6;border-radius:5px;overflow:hidden}
.rc-conj__row b{display:block;height:100%;width:var(--w);background:var(--rc-r);border-radius:5px;transform-origin:left;transform:scaleX(0);transition:transform 1s .2s cubic-bezier(.2,.7,.2,1)}
.rc-conj__row.is-in b{transform:scaleX(1)}
.rc-conj__row:first-of-type b{background:var(--rc-ink)}
.rc-seg{background:#fff;border:1px solid var(--rc-line);border-radius:22px;padding:clamp(18px,2.5vw,28px)}
.rc-seg__svg{width:100%;height:auto;display:block}
.rc-seg__core{font:800 13px var(--display);fill:#fff;letter-spacing:.1em}
.rc-seg__t{font:700 13px var(--display);fill:var(--rc-ink)}
.rc-seg__d{font:500 11.5px var(--body);fill:var(--rc-muted)}
.rc-seg__g{opacity:0;transition:opacity .6s;transition-delay:calc(var(--i)*.18s)}
.rc-seg.is-in .rc-seg__g{opacity:1}
.rc-seg__flow{display:grid;grid-template-columns:repeat(4,1fr);gap:6px;margin-top:14px}
.rc-seg__step{display:flex;flex-direction:column;gap:6px;padding:12px;border-radius:12px;background:var(--rc-paper);font:600 .84rem/1.25 var(--display);position:relative}
.rc-seg__step .rc-ico{color:var(--rc-r)}
.rc-seg__step.is-goal{background:var(--rc-ink);color:#fff}
.rc-seg__step.is-goal .rc-ico{color:var(--rc-amber)}

/* process */
.rc-proc{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:clamp(28px,5vw,72px);align-items:center}
.rc-proc__loop svg{width:100%;max-width:520px;display:block;margin:auto;overflow:visible}
.rc-proc__prog{transition:stroke-dasharray .6s cubic-bezier(.2,.7,.2,1)}
.rc-proc__node{cursor:pointer;outline:none}
.rc-proc__node circle{fill:#0E1A66;stroke:#5F82FF;stroke-width:1.5;transition:fill .3s,stroke .3s}
.rc-proc__node:hover circle{fill:#15258A}
.rc-proc__node.is-done circle{fill:#13238F;stroke:#1E6BFF}
.rc-proc__node.is-on circle{fill:#fff;stroke:var(--rc-amber);stroke-width:3}
.rc-proc__node:focus-visible circle{stroke:var(--rc-amber);stroke-width:3}
.rc-proc__n{font:800 13px var(--display);fill:#fff}
.rc-proc__k{font:600 9.5px var(--body);fill:#C9D3F5;letter-spacing:.02em}
.rc-proc__node.is-on .rc-proc__n{fill:var(--rc-ink)}.rc-proc__node.is-on .rc-proc__k{fill:var(--rc-brand)}
.rc-proc__ck{font:700 9.5px var(--body);fill:#7F8CC4;letter-spacing:.14em}
.rc-proc__core{font:700 19px var(--display);fill:#fff}
.rc-proc__panel{background:#ffffff0d;border:1px solid #ffffff22;border-radius:24px;padding:clamp(24px,3vw,40px)}
.rc-proc__meta{font:700 .74rem var(--body);letter-spacing:.14em;text-transform:uppercase;color:var(--rc-amber);margin-bottom:10px}
.rc-proc__panel h3{color:#fff;font-size:clamp(1.35rem,2.2vw,1.8rem);animation:rcPanel .4s ease}
.rc-proc__panel ul{list-style:none;padding:0;margin:20px 0 28px;display:grid;grid-template-columns:1fr 1fr;gap:10px}
.rc-proc__panel li{display:flex;gap:10px;align-items:center;padding:14px;border-radius:14px;background:#ffffff0f;color:#E4EAFF;font-weight:600;font-size:.95rem;animation:rcPanel .45s ease both;animation-delay:calc(var(--i)*70ms)}
.rc-proc__panel li .rc-ico{color:#7FA6FF}
.rc-proc__nav{display:flex;align-items:center;gap:14px}
.rc-proc__nav>button{width:44px;height:44px;border-radius:50%;border:1px solid #ffffff40;background:transparent;color:#fff;font-size:1.1rem}
.rc-proc__nav>button:hover{background:#ffffff14}
.rc-proc__pips{display:flex;gap:6px;flex:1;justify-content:center}
.rc-proc__pips button{width:24px;height:4px;border-radius:2px;border:0;padding:0;background:#ffffff30}
.rc-proc__pips button.is-on{background:var(--rc-amber)}
.rc-proc__acc{display:none}

/* methodology + toolkit */
.rc-mt{display:grid;grid-template-columns:1fr 1fr;gap:clamp(36px,6vw,88px)}
.rc-mt .rc-head{margin-bottom:28px}
.rc-venn svg{width:100%;max-width:440px;display:block;margin:0 auto 10px}
.rc-venn__c circle{mix-blend-mode:multiply;stroke-width:1.5}
.rc-venn__c0 circle{fill:#1E5BFF22;stroke:#1E5BFF}
.rc-venn__c1 circle{fill:#0B22A822;stroke:#0B22A8}
.rc-venn__c2 circle{fill:#E3A01324;stroke:#C48A0C}
.rc-venn__t{font:800 12px var(--display);letter-spacing:.1em;fill:var(--rc-ink)}
.rc-venn__d{font:500 11.5px var(--body);fill:var(--rc-muted)}
.rc-venn__core{font:800 8.6px var(--display);letter-spacing:.06em;fill:#fff}
.rc-venn__list{display:grid;gap:10px}
.rc-venn__item{display:grid;grid-template-columns:auto 1fr;column-gap:12px;padding:12px 16px;border-radius:14px;background:#fff;border:1px solid var(--rc-line);border-left:4px solid var(--rc-r)}
.rc-venn__item1{border-left-color:var(--rc-brand)}.rc-venn__item2{border-left-color:var(--rc-amber)}
.rc-venn__item strong{font:700 .95rem var(--display)}
.rc-venn__item span{font-size:.85rem;color:var(--rc-muted);align-self:center}
.rc-venn__item p{grid-column:1/-1;margin:4px 0 0;font-size:.86rem}
.rc-tk{display:grid;gap:10px}
.rc-tk__layer{display:grid;grid-template-columns:130px 1fr;gap:12px;align-items:stretch}
.rc-tk__lbl{font:700 .68rem var(--body);letter-spacing:.12em;text-transform:uppercase;color:#97A0B5;display:flex;flex-direction:column;justify-content:center;border-right:2px solid var(--rc-line);padding-right:12px}
.rc-tk__lbl strong{font:700 .92rem/1.25 var(--display);letter-spacing:0;text-transform:none;color:var(--rc-ink);margin-top:4px}
.rc-tk__mods{display:grid;grid-template-columns:repeat(3,1fr);gap:8px}
.rc-tk__mod{display:flex;flex-direction:column;gap:8px;padding:14px;border-radius:14px;background:#fff;border:1px solid var(--rc-line);font:600 .88rem/1.25 var(--display);transition:transform .2s,border-color .2s}
.rc-tk__mod:hover{transform:translateY(-2px);border-color:#9DB6FF}
.rc-tk__mod .rc-ico{color:var(--rc-r)}
.rc-tk__layer--last .rc-tk__mod{background:var(--rc-ink);color:#fff;border-color:var(--rc-ink);grid-column:span 3;flex-direction:row;align-items:center}
.rc-tk__layer--last .rc-tk__mod .rc-ico{color:var(--rc-amber)}
.rc-tk__base{margin-top:6px;padding:12px 16px;border-radius:12px;background:repeating-linear-gradient(135deg,#EEF1F6 0 8px,#F5F7FB 8px 16px);font-size:.84rem;font-weight:600;color:var(--rc-muted);text-align:center}

/* data to decision */
.rc-sec--d2d{background:radial-gradient(800px 400px at 50% 0%,#14309F 0%,transparent 70%),#07104F;color:#fff}
.rc-d2d{display:grid;grid-template-columns:repeat(7,1fr);gap:8px;position:relative;margin-bottom:clamp(56px,7vw,96px)}
.rc-d2d__line{position:absolute;top:28px;left:7%;right:7%;height:2px;background:#ffffff1f}
.rc-d2d__line span{display:block;height:100%;background:linear-gradient(90deg,#7FA6FF,var(--rc-amber));transform-origin:left;transform:scaleX(0);transition:transform 2.4s cubic-bezier(.2,.7,.2,1)}
.rc-d2d.is-in .rc-d2d__line span{transform:scaleX(1)}
.rc-d2d__s{display:flex;flex-direction:column;align-items:center;gap:12px;text-align:center;position:relative;opacity:.25;transition:opacity .5s;transition-delay:calc(var(--i)*.33s)}
.rc-d2d.is-in .rc-d2d__s{opacity:1}
.rc-d2d__dot{width:56px;height:56px;border-radius:16px;display:grid;place-items:center;background:#0E1A66;border:1px solid #5F82FF;color:#fff}
.rc-d2d__s.is-end .rc-d2d__dot{background:#fff;color:var(--rc-ink);border-color:var(--rc-amber);box-shadow:0 0 0 6px #E3A01333}
.rc-d2d__s strong{font:600 .92rem/1.25 var(--display)}
.rc-dashwrap{display:grid;grid-template-columns:minmax(0,.7fr) minmax(0,1.3fr);gap:clamp(28px,5vw,64px);align-items:center}
.rc-dashwrap__copy h3{color:#fff;font-size:clamp(1.4rem,2.4vw,1.9rem)}
.rc-dashwrap__copy p{color:#C9D3F5}
.rc-dashwrap__copy ul{list-style:none;padding:0;margin:0;display:grid;gap:10px}
.rc-dashwrap__copy li{display:flex;gap:10px;align-items:center;color:#E4EAFF;font-weight:500}
.rc-dashwrap__copy li .rc-ico{color:var(--rc-amber)}
.rc-dash{background:#0B1660;border:1px solid #ffffff24;border-radius:22px;padding:16px;box-shadow:0 40px 80px -40px #000;transform:perspective(1400px) rotateX(6deg) translateY(20px);opacity:0;transition:transform 1s cubic-bezier(.2,.7,.2,1),opacity .8s}
.rc-dash.is-in{transform:none;opacity:1}
.rc-dash__top{display:flex;align-items:center;gap:12px;padding:2px 4px 14px;flex-wrap:wrap}
.rc-dash__dots{display:flex;gap:5px}.rc-dash__dots i{width:9px;height:9px;border-radius:50%;background:#ffffff30}
.rc-dash__title{font:600 .86rem var(--display);color:#E4EAFF;flex:1}
.rc-dash__grid{display:grid;grid-template-columns:repeat(3,1fr);gap:10px}
.rc-dash__card{background:#ffffff0a;border:1px solid #ffffff14;border-radius:14px;padding:14px;min-width:0}
.rc-dash__card--wide{grid-column:span 2}

.rc-dash__h{display:block;font:600 .74rem var(--body);letter-spacing:.06em;text-transform:uppercase;color:#9DB6FF;margin-bottom:10px}
.rc-dash__area{width:100%;height:120px;display:block}
.rc-dash__line{stroke-dasharray:700;stroke-dashoffset:700;transition:stroke-dashoffset 2s .4s ease}
.rc-dash.is-in .rc-dash__line{stroke-dashoffset:0}
.rc-dash__leg{display:flex;gap:14px;font-size:.75rem;color:#C9D3F5;margin-top:6px}
.rc-dash__leg span{display:flex;align-items:center;gap:6px}
.rc-dash__leg i{width:12px;height:3px;border-radius:2px;background:#7FA6FF}.rc-dash__leg i.b{background:#A9B2C1}
.rc-dash__sbar{display:grid;grid-template-columns:72px 1fr;gap:8px;align-items:center;font-size:.76rem;color:#C9D3F5;margin-bottom:9px}
.rc-dash__sbar div{height:8px;border-radius:4px;background:#ffffff12;overflow:hidden}
.rc-dash__sbar b{display:block;height:100%;width:var(--w);border-radius:4px;background:#7FA6FF;transform-origin:left;transform:scaleX(0);transition:transform 1.2s .5s cubic-bezier(.2,.7,.2,1)}
.rc-dash__sbar:nth-of-type(2) b{background:var(--rc-amber)}
.rc-dash.is-in .rc-dash__sbar b{transform:scaleX(1)}
.rc-dash__mx,.rc-dash__trend{width:100%;height:auto;display:block}
.rc-dash__mx text{font:600 9px var(--body);fill:#9DB6FF}
.rc-dash__card--ins p{display:flex;gap:8px;align-items:flex-start;font-size:.86rem;color:#E4EAFF;margin:0 0 8px;line-height:1.45}
.rc-dash__card--ins .rc-ico{color:var(--rc-amber);margin-top:2px}

/* why */
.rc-why{display:grid;grid-template-columns:1fr minmax(200px,.75fr) 1fr;gap:clamp(16px,3vw,40px);align-items:center;position:relative}
.rc-why__col{display:grid;gap:14px}
.rc-why__col--1{grid-column:3;grid-row:1}
.rc-why__hub{grid-column:2;grid-row:1;display:grid;place-items:center}
.rc-why__ring{width:min(240px,100%);aspect-ratio:1;border-radius:50%;background:radial-gradient(circle,#0B22A8 0%,#07104F 70%);color:#fff;display:flex;flex-direction:column;align-items:center;justify-content:center;font:800 clamp(.95rem,1.4vw,1.2rem)/1.2 var(--display);letter-spacing:.14em;text-transform:uppercase;position:relative;box-shadow:0 0 0 14px #E6EDFF,0 0 0 15px #C8D5FF,0 0 0 34px #F1F5FF,0 0 0 35px #DCE4FA}
.rc-why__ring:before,.rc-why__ring:after{content:"";position:absolute;top:50%;width:clamp(16px,3vw,40px);height:1px;background:repeating-linear-gradient(90deg,#9DB6FF 0 4px,transparent 4px 8px)}
.rc-why__ring:before{right:calc(100% + 35px)}.rc-why__ring:after{left:calc(100% + 35px)}
.rc-why__mod{background:var(--rc-paper);border:1px solid var(--rc-line);border-radius:18px;padding:20px 22px;position:relative}
.rc-why__col--0 .rc-why__mod{text-align:right}
.rc-why__col--0 .rc-why__k{justify-content:flex-end}
.rc-why__k{display:flex;align-items:center;gap:8px;font:700 .72rem var(--body);letter-spacing:.12em;text-transform:uppercase;color:var(--rc-r);margin-bottom:8px}
.rc-why__mod h3{font-size:1.08rem;margin-bottom:.3em}
.rc-why__mod p{font-size:.92rem;color:var(--rc-muted);margin:0}

/* team */
.rc-teamwrap{display:grid;grid-template-columns:minmax(0,.75fr) minmax(0,1.25fr);gap:clamp(28px,5vw,72px);align-items:center}
.rc-teamwrap .rc-head{margin-bottom:18px}
.rc-team{background:#fff;border:1px solid var(--rc-line);border-radius:24px;padding:clamp(18px,2.5vw,28px)}
.rc-team__lanes{display:grid;grid-template-columns:1fr 1.3fr 1fr;gap:12px}
.rc-team__lane{display:flex;flex-direction:column;gap:8px;padding:14px;border-radius:16px;background:var(--rc-paper);position:relative}
.rc-team__lane:not(:last-child):after{content:"→";position:absolute;right:-12px;top:50%;transform:translateY(-50%);width:20px;height:20px;border-radius:50%;background:#fff;border:1px solid var(--rc-line);display:grid;place-items:center;font-size:.7rem;color:var(--rc-r);z-index:1}
.rc-team__stage{font:700 .7rem var(--body);letter-spacing:.12em;text-transform:uppercase;color:#97A0B5;margin-bottom:2px}
.rc-team__role{display:flex;gap:10px;align-items:center;background:#fff;border:1px solid var(--rc-line);border-radius:12px;padding:12px;font:600 .88rem/1.25 var(--display)}
.rc-team__role .rc-ico{color:var(--rc-r)}
.rc-team__pm{display:flex;flex-wrap:wrap;align-items:center;gap:10px;margin-top:12px;padding:14px 18px;border-radius:14px;background:var(--rc-ink);color:#fff}
.rc-team__pm .rc-ico{color:var(--rc-amber)}
.rc-team__pm strong{font:700 .95rem var(--display)}
.rc-team__pm span{color:#C9D3F5;font-size:.88rem}

/* capabilities + tech */
.rc-cap{display:grid;grid-template-columns:repeat(3,1fr);border:1px solid var(--rc-line);border-radius:22px;overflow:hidden;background:var(--rc-paper)}
.rc-cap__col{padding:clamp(22px,3vw,32px);position:relative}
.rc-cap__col+.rc-cap__col{border-left:1px solid var(--rc-line)}
.rc-cap__n{position:absolute;top:18px;right:22px;font:800 2.4rem/1 var(--display);color:#E3E8F3}
.rc-cap__col h3{display:flex;gap:10px;align-items:center}
.rc-cap__col h3 .rc-ico{color:var(--rc-r)}
.rc-cap__col ul{list-style:none;margin:14px 0 0;padding:0}
.rc-cap__col li{padding:10px 0;border-top:1px dashed #CDD4E1;font-weight:500;font-size:.96rem}
.rc-tech{display:flex;gap:20px;align-items:center;margin-top:28px;flex-wrap:wrap}
.rc-tech__lbl{font:700 .74rem var(--body);letter-spacing:.12em;text-transform:uppercase;color:#97A0B5}
.rc-tech__tiles{display:flex;flex-wrap:wrap;gap:8px;flex:1}
.rc-tech__tile{display:inline-flex;align-items:center;gap:8px;padding:10px 16px;border-radius:12px;border:1px solid var(--rc-line);background:#fff;text-decoration:none;color:var(--rc-ink)}
.rc-tech__tile strong{font:700 .9rem var(--display)}
.rc-tech__tile--own{background:var(--rc-ink);color:#fff;border-color:var(--rc-ink)}
.rc-tech__tile--own span{font-size:.72rem;color:var(--rc-amber);font-weight:700;letter-spacing:.06em;text-transform:uppercase}

/* industries */
.rc-ind{display:grid;grid-template-columns:repeat(auto-fill,minmax(180px,1fr));gap:10px}
.rc-ind__item{display:flex;align-items:center;gap:10px;padding:14px 16px;border-radius:14px;border:1px solid var(--rc-line);background:#fff;text-decoration:none;color:var(--rc-ink);font-weight:600;font-size:.92rem;transition:border-color .2s,transform .2s,box-shadow .2s}
.rc-ind__item svg{color:var(--rc-r);flex:none}
.rc-ind__item:hover{border-color:#9DB6FF;transform:translateY(-2px);box-shadow:0 12px 24px -18px #13213C80}
.rc-ind__item--x{animation:rcFade .4s ease both;opacity:0}
.rc-ind__more{border:1px dashed var(--rc-r);background:var(--rc-soft);color:var(--rc-r);border-radius:14px;padding:14px 16px;font-weight:700}

/* case */
.rc-case{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:clamp(28px,5vw,72px);background:var(--rc-paper);border:1px solid var(--rc-line);border-radius:28px;padding:clamp(24px,5vw,56px);align-items:center}
.rc-case h2{margin-bottom:.5em}
.rc-case__facts{display:grid;grid-template-columns:repeat(3,auto);justify-content:start;gap:clamp(16px,3vw,36px);margin:26px 0 28px}
.rc-case__facts strong{display:block;font:800 clamp(1.5rem,2.6vw,2rem)/1 var(--display);color:var(--rc-r);letter-spacing:-.02em}
.rc-case__facts span{font-size:.84rem;color:var(--rc-muted)}
.rc-case__tl{list-style:none;margin:0;padding:0 0 0 8px;position:relative}
.rc-case__tl:before{content:"";position:absolute;left:25px;top:20px;bottom:20px;width:2px;background:linear-gradient(var(--rc-r),var(--rc-amber))}
.rc-case__tl li{display:grid;grid-template-columns:36px 1fr;column-gap:16px;padding:10px 0;position:relative}
.rc-case__dot{grid-row:span 2;width:36px;height:36px;border-radius:50%;background:#fff;border:2px solid var(--rc-r);display:grid;place-items:center;color:var(--rc-r);position:relative;z-index:1}
.rc-case__tl li:last-child .rc-case__dot{background:var(--rc-ink);border-color:var(--rc-amber);color:#fff}
.rc-case__tl strong{font:700 1rem var(--display)}
.rc-case__tl span{font-size:.88rem;color:var(--rc-muted)}

/* responsive */
@media (max-width:1100px){
  .rc-svc{grid-template-columns:repeat(2,1fr)}
  .rc-svc__card.rc-svc__card--advisory{grid-row:auto;grid-column:1/-1}
  .rc-strip{grid-template-columns:repeat(2,1fr)}
  .rc-strip li:nth-child(3){border-left:0}
  .rc-strip li:nth-child(n+3){border-top:1px solid var(--rc-line)}
  .rc-mt{grid-template-columns:1fr}
  .rc-break__chain{grid-template-columns:repeat(4,1fr);row-gap:20px}
  .rc-break__chain li:nth-child(4):after{display:none}
  .rc-prob{grid-template-columns:1fr}
}
@media (max-width:900px){
  .rc-hero__in,.rc-fw,.rc-proc,.rc-dd__row,.rc-dd__row--wide,.rc-dd__price,.rc-dashwrap,.rc-teamwrap,.rc-case,.rc-solhead{grid-template-columns:1fr}
  .rc-dd__row--flip>.rc-dd__copy{order:0}
  .rc-hero__viz{max-width:620px}
  .rc-sol{grid-template-columns:1fr 1fr;row-gap:32px}
  .rc-sol__track{display:none}
  .rc-why{grid-template-columns:1fr 1fr}
  .rc-why__hub{grid-column:1/-1;grid-row:1}
  .rc-why__col--0{grid-column:1;grid-row:2}.rc-why__col--1{grid-column:2;grid-row:2}
  .rc-why__col--0 .rc-why__mod{text-align:left}.rc-why__col--0 .rc-why__k{justify-content:flex-start}
  .rc-why__ring:before,.rc-why__ring:after{display:none}
  .rc-why__ring{width:190px}
  .rc-proc__loop svg{max-width:420px}
  .rc-d2d{grid-template-columns:repeat(4,1fr);row-gap:28px}
  .rc-d2d__line{display:none}
}
@media (max-width:640px){
  .rc-net{display:none}
  .rc-netm{display:flex;flex-direction:column;align-items:center;gap:0;margin-top:8px;padding:20px 16px;border-radius:20px;background:#ffffff0a;border:1px solid #ffffff1f}
  .rc-netm__chips{display:flex;flex-wrap:wrap;justify-content:center;gap:6px}
  .rc-netm__chips span{font:700 .68rem var(--body);letter-spacing:.08em;text-transform:uppercase;padding:6px 10px;border-radius:999px;background:#0E1A66;border:1px solid #5F82FF99;color:#E4EAFF}
  .rc-netm__arrow{width:2px;height:22px;background:linear-gradient(#5F82FF,#fff);margin:6px 0;position:relative}
  .rc-netm__arrow:after{content:"";position:absolute;bottom:-3px;left:-4px;border:5px solid transparent;border-top-color:#fff;border-bottom:0}
  .rc-netm__core{padding:14px 22px;border-radius:999px;background:#0B22A8;border:1px solid #7FA6FF;font:800 .82rem var(--display);letter-spacing:.1em;text-transform:uppercase}
  .rc-netm__mid{font:700 .74rem var(--body);letter-spacing:.12em;text-transform:uppercase;padding:8px 16px;border-radius:999px;border:1px solid #9DB6FF}
  .rc-netm__dec{padding:12px 20px;border-radius:12px;background:#fff;color:var(--rc-ink);font:800 .82rem var(--display);letter-spacing:.08em;text-transform:uppercase;box-shadow:0 0 0 2px var(--rc-amber)}
  .rc-hero__ctas .btn{width:100%}
  .rc-strip{grid-template-columns:1fr;margin-top:-56px}
  .rc-strip li+li{border-left:0;border-top:1px solid var(--rc-line)}
  .rc-strip li{padding:16px}
  .rc-subnav{margin-top:28px}
  .rc-break__chain{grid-template-columns:1fr;gap:0}
  .rc-break__chain li{display:grid;grid-template-columns:42px 1fr 90px;column-gap:12px;align-items:center;padding:8px 0}
  .rc-break__chain li:after{display:none}
  .rc-break__chain li:not(:last-child):before{content:"";position:absolute;left:20px;top:50px;height:16px;width:2px;background:#E3E7EF}
  .rc-break__n{display:none}
  .rc-break__t{min-height:0}
  .rc-sol{grid-template-columns:1fr}
  .rc-sol__step{display:grid;grid-template-columns:60px 1fr;column-gap:16px}
  .rc-sol__dot{width:60px;height:60px;grid-row:span 3;margin:0}
  .rc-sol__step h3{margin:.1em 0 .2em}
  .rc-sol__cap:before,.rc-sol__cap:after{display:none}
  .rc-turn span{font-size:.74rem;padding:8px 14px}
  .rc-fw__wheel svg{max-width:300px}
  .rc-fw__tabs{display:flex;gap:6px;overflow-x:auto;margin:-4px -4px 18px;padding:4px;scrollbar-width:none}
  .rc-fw__tabs button{flex:none;border:1px solid var(--rc-line);background:#fff;border-radius:999px;padding:7px 12px;font-size:.8rem;font-weight:600;color:var(--rc-ink)}
  .rc-fw__tabs button.is-on{background:var(--rc-r);color:#fff;border-color:var(--rc-r)}
  .rc-fw__num{display:none}
  .rc-svc{grid-template-columns:1fr}
  .rc-svc__card.rc-svc__card--advisory{grid-column:auto;padding:24px}
  .rc-npd{grid-template-columns:1fr;gap:0}
  .rc-npd__line{display:none}
  .rc-npd__s{flex-direction:row;text-align:left;gap:14px;padding:8px 0}
  .rc-npd__dot{width:48px;height:48px;flex:none}
  .rc-npd__s strong{order:2}
  .rc-npd__gate{order:3;margin-left:auto}
  .rc-funnel__bar{width:calc(var(--w) + (100% - var(--w)) * .55)}
  .rc-seg__flow{grid-template-columns:1fr 1fr}
  .rc-proc__loop,.rc-proc__panel{display:none}
  .rc-proc__acc{display:block;list-style:none;margin:0;padding:0;border-left:2px solid #ffffff26;margin-left:16px}
  .rc-proc__acc>li{position:relative;padding:0 0 4px 22px}
  .rc-proc__acc>li>button{display:flex;gap:12px;align-items:center;width:100%;text-align:left;background:none;border:0;color:#fff;font:600 1rem/1.3 var(--display);padding:12px 0}
  .rc-proc__acc>li>button span{position:absolute;left:-17px;width:32px;height:32px;border-radius:50%;background:#0E1A66;border:1px solid #5F82FF;display:grid;place-items:center;font:800 .74rem var(--display)}
  .rc-proc__acc>li.is-on>button span{background:#fff;color:var(--rc-ink);border:2px solid var(--rc-amber)}
  .rc-proc__acc ul{list-style:none;padding:0;margin:0 0 12px;display:grid;gap:6px}
  .rc-proc__acc ul li{display:flex;gap:8px;align-items:center;padding:10px 12px;border-radius:10px;background:#ffffff0f;font-size:.9rem;color:#E4EAFF}
  .rc-proc__acc ul li .rc-ico{color:#7FA6FF}
  .rc-proc__accend{display:flex;gap:8px;align-items:center;color:var(--rc-amber);font-weight:600;font-size:.9rem;padding-top:10px!important}
  .rc-tk__layer{grid-template-columns:1fr}
  .rc-tk__lbl{border-right:0;padding:0;flex-direction:row;gap:8px;align-items:baseline}
  .rc-tk__mods{grid-template-columns:1fr 1fr}
  .rc-tk__layer--last .rc-tk__mod{grid-column:span 2}
  .rc-d2d{grid-template-columns:1fr;gap:0;justify-items:start;padding-left:4px}
  .rc-d2d__s{flex-direction:row;text-align:left;gap:14px;padding:6px 0}
  .rc-d2d__s:not(:last-child):after{content:"";position:absolute;left:27px;top:62px;width:2px;height:12px;background:#ffffff30}
  .rc-dash__grid{grid-template-columns:1fr}
  .rc-dash__card--wide{grid-column:auto}
  .rc-dash{transform:none}
  .rc-why{grid-template-columns:1fr}
  .rc-why__col--0,.rc-why__col--1{grid-column:1;grid-row:auto}
  .rc-team__lanes{grid-template-columns:1fr}
  .rc-team__lane:not(:last-child):after{content:"↓";right:50%;top:auto;bottom:-14px;transform:translateX(50%)}
  .rc-cap{grid-template-columns:1fr}
  .rc-cap__col+.rc-cap__col{border-left:0;border-top:1px solid var(--rc-line)}
  .rc-ind{grid-template-columns:1fr 1fr}
  .rc-ind__item{padding:12px;font-size:.86rem}
  .rc-case__facts{grid-template-columns:repeat(3,1fr);gap:12px}
  .rc-chain span{font-size:.78rem}
}
@media (prefers-reduced-motion:reduce){
  .rc *{animation:none!important;transition:none!important}
  .rc .rc-reveal,.rc-net__node,.rc-break__chain li,.rc-sol__step,.rc-npd__s,.rc-seg__g,.rc-dash,.rc-d2d__s{opacity:1!important;transform:none!important}
  .rc-break__bar b,.rc-sol__track span,.rc-npd__line span,.rc-d2d__line span,.rc-conj__row b,.rc-dash__sbar b{transform:none!important}
  .rc-price__c1,.rc-price__c2,.rc-dash__line{stroke-dashoffset:0!important}
  .rc-price__wtp,.rc-price__band,.rc-price__opt,.rc-radar__a,.rc-radar__b{opacity:1!important;transform:none!important}
  .rc-flowline,.rc-pulse,.rc-pulse2,.rc-spin{display:none}
}

.rc-svc__card.rc-svc__card--advisory .rc-svc__more ul{border-top:1px solid #ffffff26;gap:10px}
.rc-svc__card.rc-svc__card--advisory p{margin-bottom:6px}
@media (max-width:640px){.rc-svc__card.rc-svc__card--advisory .rc-svc__more ul{grid-template-columns:1fr}}
.rc-svc__card.rc-svc__card--advisory{align-self:stretch}
.rc-svc__qs{list-style:none;margin:auto 0 18px;padding:18px 0 0;display:grid;gap:8px}
.rc-svc__qs li{display:flex;align-items:center;gap:12px;padding:12px 14px;border-radius:12px;background:#ffffff0d;border:1px solid #ffffff1a;font:600 .95rem/1.3 var(--display);color:#fff}
.rc-svc__qs span{flex:none;width:30px;height:30px;border-radius:50%;display:grid;place-items:center;background:var(--rc-amber);color:var(--rc-ink);font:800 .72rem var(--display)}
.rc-svc__card.rc-svc__card--advisory .rc-svc__tog{margin-top:0}
.rc-venn__d{font-size:10.5px}
.rc-dd{grid-template-columns:minmax(0,1fr)}
.rc-dd__row>*,.rc-dd__price>*,.rc-dd__band>*,.rc-fw>*,.rc-proc>*,.rc-mt>*,.rc-dashwrap>*,.rc-teamwrap>*,.rc-case>*,.rc-prob>*,.rc-hero__in>*{min-width:0}
@media (max-width:640px){.rc-seg__svg{min-width:0}.rc-seg__t{font-size:14px}.rc-venn__t{font-size:13px}}
.rc-hero__grid-bg{pointer-events:none}
.rc-hero__in{position:relative;z-index:1}

/* ===== Online Data Collection page (od-) ===== */
.od{--od-navy:#07104F;--od-blue:#1E5BFF;--od-royal:#0B22A8;--od-sky:#E8EEFF;--od-teal:#0E9C88;--od-teal-soft:#E3F5F2;--od-line:#DDE2EC;--od-muted:#525C78;--od-paper:#F5F7FB}
.od-muted{color:var(--od-muted)}
.od-split{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:clamp(24px,5vw,72px);align-items:end;margin-bottom:clamp(36px,5vw,60px)}
.od-split .rc-head{margin:0}
.od-chips{list-style:none;margin:0;padding:0;display:flex;flex-wrap:wrap;gap:6px}
.od-chips li{font-size:.8rem;font-weight:600;padding:5px 10px;border-radius:999px;background:var(--od-paper);border:1px solid var(--od-line);color:var(--od-navy)}
.od-chips--lg li{font-size:.88rem;padding:8px 14px;background:#fff}
.od-ticks{list-style:none;padding:0;margin:0 0 18px;display:grid;grid-template-columns:1fr 1fr;gap:8px 18px}
.od-ticks li{display:flex;gap:10px;align-items:center;font-weight:600;font-size:.96rem}
.od-ticks li .rc-ico{color:var(--od-teal);background:var(--od-teal-soft);border-radius:50%;padding:3px;width:22px;height:22px}
.od-sec--navy{background:linear-gradient(170deg,#07104F,#0B1A78);color:#fff}

/* hero */
.od-hero{position:relative;background:radial-gradient(900px 500px at 80% 30%,#E3EAFF 0%,transparent 65%),linear-gradient(180deg,#FFFFFF 0%,#F3F6FC 100%);padding:clamp(36px,4vw,60px) 0 clamp(48px,6vw,80px);overflow:hidden;border-bottom:1px solid var(--od-line)}
.od-hero__in{display:grid;grid-template-columns:minmax(0,.92fr) minmax(0,1.08fr);gap:clamp(24px,4vw,56px);align-items:center}
.od-hero__in>*{min-width:0}
.od-crumbs{color:var(--od-muted)}
.od-crumbs a{color:var(--od-navy)}
.od-eyebrow{display:inline-flex;align-items:center;gap:10px;font:600 .8rem/1 var(--body);letter-spacing:.14em;text-transform:uppercase;color:var(--od-blue);margin-bottom:16px}
.od-eyebrow i{width:8px;height:8px;border-radius:50%;background:var(--od-teal);box-shadow:0 0 0 4px #0E9C8826}
.od-hero h1{font-size:clamp(2.1rem,4.2vw,3.5rem);color:var(--od-navy);margin-bottom:.35em;max-width:16ch}
.od-hero__pos{font:600 clamp(1.1rem,1.7vw,1.35rem)/1.4 var(--display);color:var(--od-royal);margin-bottom:14px}
.od-hero__body{color:var(--od-muted);font-size:1.04rem;max-width:58ch;margin-bottom:26px}
.od-hero__body strong{color:var(--od-navy)}
.od-hero__ctas{display:flex;flex-wrap:wrap;gap:12px}
.od .od-btn-main{background:var(--od-royal);color:#fff}
.od .od-btn-main:hover{background:var(--od-navy)}
.od-hero__trust{margin:22px 0 0;font-size:.8rem;font-weight:600;color:var(--od-muted);letter-spacing:.02em;display:flex;flex-wrap:wrap;align-items:center;gap:6px 10px}
.od-hero__trust i{width:4px;height:4px;border-radius:50%;background:#B9C2D3}
.od-hmap{position:relative;padding:28px 0}
.od-hmap>svg{width:100%;height:auto;display:block;overflow:visible}
.od-dots{fill:none;stroke:#9FB2E6;stroke-width:4.2;stroke-linecap:round;opacity:.75}
.od-dots--soft{stroke:#C3CEEA;opacity:.9}
.od-arc{fill:none;stroke:var(--od-blue);stroke-width:1.6;stroke-dasharray:4 6;opacity:0;animation:odArcIn 1.4s ease forwards,odDash 14s linear infinite}
@keyframes odArcIn{to{opacity:.75}}
@keyframes odDash{to{stroke-dashoffset:-200}}
.od-traveller{fill:var(--od-teal)}
.od-hub{opacity:0;animation:rcFade .8s ease forwards}
.od-hub__halo{fill:#1E5BFF1f;transform-box:fill-box;transform-origin:center;animation:odHalo 4s ease-in-out infinite}
@keyframes odHalo{0%,100%{transform:scale(.8);opacity:.9}50%{transform:scale(1.25);opacity:.4}}
.od-hub__dot{fill:var(--od-royal);stroke:#fff;stroke-width:2}
.od-hub__pill{fill:#fff;stroke:var(--od-line)}
.od-hub__lbl{font:700 15px var(--body);fill:var(--od-navy);letter-spacing:.02em}
.od-fcard{position:absolute;background:#fff;border:1px solid var(--od-line);border-radius:14px;padding:10px 14px;box-shadow:0 18px 36px -22px #0B22A866;display:flex;flex-direction:column;gap:2px;animation:odFloat 7s ease-in-out infinite}
.od-fcard strong{font:600 .86rem/1.25 var(--display);color:var(--od-navy)}
.od-fcard__tag{font:800 .7rem var(--body);letter-spacing:.12em;text-transform:uppercase;color:var(--od-blue)}
.od-fcard--b2b{left:0;top:-14px}
.od-fcard--b2c{left:6%;bottom:2%;animation-delay:-2.5s}
.od-fcard--b2c .od-fcard__tag{color:var(--od-teal)}
.od-fcard--hc{right:0;bottom:12%;animation-delay:-5s}
.od-fcard--hc .od-fcard__tag{color:#B07A00}
@keyframes odFloat{0%,100%{transform:translateY(0)}50%{transform:translateY(-6px)}}

/* trust */
.od-trust{background:#fff;border-bottom:1px solid var(--od-line)}
.od-msme{display:inline-flex;flex-direction:column;justify-content:center;padding:8px 16px;border:1px solid var(--od-line);border-radius:12px;background:var(--od-paper);line-height:1.2}
.od-msme strong{font:800 1rem var(--display);letter-spacing:.08em;color:var(--od-navy)}
.od-msme small{font-size:.72rem;color:var(--od-muted)}

/* glance */
.od-glance{background:#fff;border-bottom:1px solid var(--od-line);padding:clamp(28px,4vw,44px) 0}
.od-glance__grid{display:grid;grid-template-columns:1.1fr repeat(5,1fr);gap:0;align-items:stretch}
.od-glance__lbl{padding-right:20px}
.od-glance__lbl .rc-kicker{margin-bottom:8px}
.od-glance__lbl p{margin:0;font-size:.92rem;color:var(--od-muted)}
.od-glance__item{padding:4px 20px;border-left:1px solid var(--od-line);display:flex;flex-direction:column;gap:4px}
.od-count{font:800 clamp(1.8rem,3vw,2.5rem)/1 var(--display);letter-spacing:-.03em;color:var(--od-royal);font-variant-numeric:tabular-nums}
.od-glance__item:nth-child(3) .od-count{color:var(--od-teal)}
.od-glance__item:nth-child(4) .od-count,.od-glance__item:nth-child(5) .od-count,.od-glance__item:nth-child(6) .od-count{color:var(--od-navy)}
.od-glance__item span:last-child{font-size:.84rem;color:var(--od-muted);line-height:1.35}
.od-subnav{margin-top:0}

/* flow */
.od-flow{list-style:none;margin:0;padding:0;display:grid;grid-template-columns:repeat(8,1fr);gap:8px;position:relative}
.od-flow__track{position:absolute;top:27px;left:5%;right:5%;height:3px;border-radius:2px;background:#E3E7EF}
.od-flow__track span{display:block;height:100%;border-radius:2px;background:linear-gradient(90deg,var(--od-blue),var(--od-teal));transform-origin:left;transform:scaleX(0);transition:transform 2.6s cubic-bezier(.2,.7,.2,1)}
.od-flow.is-in .od-flow__track span{transform:scaleX(1)}
.od-flow li{display:flex;flex-direction:column;align-items:center;text-align:center;gap:8px;position:relative;opacity:.35;transition:opacity .5s;transition-delay:calc(var(--i)*.3s)}
.od-flow.is-in li{opacity:1}
.od-flow__dot{width:56px;height:56px;border-radius:16px;display:grid;place-items:center;background:#fff;border:1px solid var(--od-line);color:var(--od-blue);box-shadow:0 10px 24px -18px #0B22A8;transition:transform .2s}
.od-flow li:hover .od-flow__dot{transform:translateY(-2px)}
.od-flow li.is-end .od-flow__dot{background:var(--od-teal);border-color:var(--od-teal);color:#fff}
.od-flow__n{font:700 .7rem var(--body);letter-spacing:.1em;color:#97A0B5}
.od-flow strong{font:600 .9rem/1.25 var(--display);color:var(--od-navy)}

/* panels */
.od-panels{display:grid;grid-template-columns:repeat(3,1fr);gap:18px}
.od-panel{background:#fff;border:1px solid var(--od-line);border-radius:22px;padding:28px;display:flex;flex-direction:column;position:relative;overflow:hidden;transition:transform .25s,box-shadow .25s}
.od-panel:before{content:"";position:absolute;top:0;left:0;right:0;height:4px;background:var(--od-blue)}
.od-panel--b2c:before{background:var(--od-teal)}.od-panel--hc:before{background:#E3A013}
.od-panel:hover{transform:translateY(-4px);box-shadow:0 28px 50px -30px #0B22A880}
.od-panel__tag{display:inline-flex;align-items:center;gap:8px;font:700 .76rem var(--body);letter-spacing:.12em;text-transform:uppercase;color:var(--od-blue);background:var(--od-sky);padding:6px 12px;border-radius:999px}
.od-panel--b2c .od-panel__tag{color:#0A7C6C;background:var(--od-teal-soft)}
.od-panel--hc .od-panel__tag{color:#8A6000;background:#FBF1DC}
.od-panel__stat{margin:22px 0 14px;display:flex;flex-direction:column;gap:4px}
.od-panel__stat .od-count{font-size:clamp(2.4rem,4vw,3.2rem)}
.od-panel--b2c .od-count{color:var(--od-teal)}.od-panel--hc .od-count{color:#B07A00}
.od-panel__stat span:last-child{font-size:.9rem;color:var(--od-muted);font-weight:600}
.od-panel h3{font-size:1.25rem}
.od-panel p{color:var(--od-muted);font-size:.95rem}
.od-panel__lbl{font:700 .7rem var(--body);letter-spacing:.12em;text-transform:uppercase;color:#97A0B5;margin-bottom:10px}
.od-panel__cta{margin-top:auto;padding-top:22px;display:inline-flex;align-items:center;gap:8px;font-weight:700;color:var(--od-royal);text-decoration:none}
.od-panel__cta:hover{text-decoration:underline}

/* coverage */
.od-cov{display:grid;grid-template-columns:minmax(0,1.6fr) minmax(0,.8fr);gap:clamp(20px,3vw,40px);align-items:center}
.od-cov__map{background:#fff;border:1px solid var(--od-line);border-radius:24px;padding:clamp(14px,2.5vw,28px)}
.od-cov__map>svg{width:100%;height:auto;display:block;overflow:visible}
.od-cov__note{display:flex;gap:8px;align-items:center;margin:12px 0 0;font-size:.82rem;color:var(--od-muted)}
.od-mk{opacity:0;transform:translateY(-6px);transition:opacity .5s,transform .5s}
.od-cov.is-in .od-mk{opacity:1;transform:none}
.od-cov.is-in .od-mk.is-dim{opacity:.18}
.od-mk__ring{fill:currentColor;opacity:.16}
.od-mk__dot{fill:currentColor;stroke:#fff;stroke-width:2}
.od-mk--am{color:var(--od-blue)}.od-mk--eu{color:var(--od-royal)}.od-mk--apac{color:var(--od-teal)}.od-mk--mena{color:#C48A0C}
.od-mk__lbl{font:700 12px var(--body);fill:var(--od-navy);paint-order:stroke;stroke:#fff;stroke-width:4px}
.od-cov__list{display:grid;gap:10px}
.od-cov__reg{text-align:left;background:#fff;border:1px solid var(--od-line);border-radius:16px;padding:16px 18px;display:grid;grid-template-columns:12px 1fr;column-gap:12px;align-items:center;transition:border-color .2s,box-shadow .2s,transform .2s;color:var(--od-navy)}
.od-cov__reg:hover,.od-cov__reg.is-on{border-color:currentColor;box-shadow:0 14px 30px -22px #0B22A8;transform:translateX(3px)}
.od-cov__sw{width:12px;height:12px;border-radius:50%;background:var(--od-blue)}
.od-cov__reg--eu .od-cov__sw{background:var(--od-royal)}.od-cov__reg--apac .od-cov__sw{background:var(--od-teal)}.od-cov__reg--mena .od-cov__sw{background:#C48A0C}
.od-cov__reg strong{font:700 1rem var(--display)}
.od-cov__c{grid-column:2;font-size:.85rem;color:var(--od-muted);line-height:1.45;margin-top:2px}

/* why */
.od-why{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}
.od-why__card{background:#ffffff0a;border:1px solid #ffffff1f;border-radius:20px;padding:26px;transition:background .25s,transform .25s,border-color .25s}
.od-why__card:hover{background:#ffffff14;transform:translateY(-3px);border-color:#ffffff3a}
.od-why__top{display:flex;justify-content:space-between;align-items:center;margin-bottom:18px}
.od-why__ic{width:46px;height:46px;border-radius:14px;display:grid;place-items:center;background:#1E5BFF33;color:#BFD0FF}
.od-why__card:hover .od-why__ic{color:#fff}
.od-why__n{font:800 1.6rem var(--display);color:#ffffff26}
.od-why__card h3{color:#fff}
.od-why__card p{color:#C9D3F5;margin:0;font-size:.95rem}

/* infrastructure */
.od-infra{display:grid;grid-template-columns:minmax(0,.9fr) minmax(0,1.1fr);gap:clamp(28px,5vw,72px);align-items:center}
.od-infra>*{min-width:0}
.od-plat{list-style:none;padding:0;margin:24px 0 0;display:grid;gap:10px}
.od-plat a{display:grid;grid-template-columns:1fr auto;column-gap:12px;align-items:center;padding:14px 18px;border-radius:14px;border:1px solid var(--od-line);background:#fff;text-decoration:none;color:var(--od-navy);transition:border-color .2s,transform .2s}
.od-plat a:hover{border-color:var(--od-blue);transform:translateX(3px)}
.od-plat strong{font:700 1rem var(--display)}
.od-plat span{grid-column:1;font-size:.86rem;color:var(--od-muted)}
.od-plat .rc-ico{grid-row:1/span 2;grid-column:2;color:var(--od-blue)}
.od-infra__wheel>svg{width:100%;max-width:520px;margin:auto;display:block;overflow:visible}
.od-infra__ring{fill:none;stroke:var(--od-line);stroke-width:2}
.od-infra__ring2{fill:none;stroke:var(--od-blue);stroke-width:2;stroke-dasharray:3 9;opacity:.6;transform-origin:240px 240px;animation:rcSpin 80s linear infinite}
.od-infra__n circle{fill:#fff;stroke:var(--od-line);stroke-width:1.5;transition:fill .25s,stroke .25s}
.od-infra__n foreignObject{color:var(--od-blue);pointer-events:none}
.od-infra__n.is-on circle{fill:var(--od-blue);stroke:var(--od-blue)}
.od-infra__n.is-on foreignObject{color:#fff}
.od-infra__n:nth-child(9) circle,.od-infra__n:last-of-type circle{stroke:var(--od-teal)}
.od-infra__t{font:700 12px var(--display);fill:var(--od-navy)}
.od-infra__core{fill:var(--od-navy)}
.od-infra__ck{font:700 9.5px var(--body);letter-spacing:.14em;fill:#9DB6FF}
.od-infra__p{font:700 14px var(--display);fill:#fff}

/* recruitment */
.od-rec{display:grid;grid-template-columns:repeat(3,1fr);gap:14px}
.od-rec__tile{border:1px solid var(--od-line);border-radius:18px;padding:24px;background:var(--od-paper);transition:transform .2s,box-shadow .2s,background .2s}
.od-rec__tile:hover{transform:translateY(-3px);background:#fff;box-shadow:0 20px 40px -28px #0B22A880}
.od-rec__tile>.rc-ico{color:var(--od-blue);margin-bottom:14px}
.od-rec__tile3>.rc-ico{color:#B07A00}.od-rec__tile4>.rc-ico,.od-rec__tile5>.rc-ico{color:var(--od-teal)}
.od-rec__tile h3{font-size:1.06rem}
.od-rec__tile p{margin:0;color:var(--od-muted);font-size:.94rem}

/* registration */
.od-regwrap{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:clamp(28px,5vw,72px);align-items:center}
.od-regwrap>*{min-width:0}
.od-reg{background:linear-gradient(160deg,#E8EEFF,#F5F7FB);border-radius:28px;padding:clamp(20px,4vw,48px)}
.od-reg__bar{display:flex;align-items:center;gap:10px;background:#fff;border-radius:14px 14px 0 0;padding:12px 16px;border:1px solid var(--od-line);border-bottom:0;font-size:.82rem;font-weight:600;color:var(--od-muted)}
.od-reg__lock{width:24px;height:24px;border-radius:50%;display:grid;place-items:center;background:var(--od-teal-soft);color:var(--od-teal)}
.od-reg__body{background:#fff;border:1px solid var(--od-line);border-radius:0 0 14px 14px;padding:20px;box-shadow:0 30px 60px -40px #0B22A8}
.od-reg__steps{display:flex;gap:6px;margin-bottom:12px}
.od-reg__steps b{flex:1;height:4px;border-radius:2px;background:#E3E7EF}
.od-reg__steps b.on{background:var(--od-teal)}
.od-reg__h{display:block;font:700 .95rem var(--display);margin-bottom:12px;color:var(--od-navy)}
.od-reg__row{display:grid;grid-template-columns:34px 1fr 24px;gap:12px;align-items:center;padding:10px 12px;border:1px solid var(--od-line);border-radius:12px;margin-bottom:8px;opacity:0;transform:translateX(-8px);transition:opacity .4s,transform .4s;transition-delay:calc(var(--i)*.15s)}
.od-reg.is-in .od-reg__row{opacity:1;transform:none}
.od-reg__ic{width:34px;height:34px;border-radius:10px;display:grid;place-items:center;background:var(--od-sky);color:var(--od-blue)}
.od-reg__row strong{display:block;font-size:.88rem}
.od-reg__row div span{font-size:.76rem;color:var(--od-muted)}
.od-reg__ok{width:24px;height:24px;border-radius:50%;display:grid;place-items:center;background:var(--od-teal);color:#fff;transform:scale(0);transition:transform .35s cubic-bezier(.3,1.6,.5,1);transition-delay:calc(var(--i)*.15s + .3s)}
.od-reg.is-in .od-reg__ok{transform:scale(1)}
.od-reg__btn{margin-top:12px;text-align:center;padding:12px;border-radius:999px;background:var(--od-royal);color:#fff;font-weight:700;font-size:.9rem}

/* profiling */
.od-profwrap{display:grid;grid-template-columns:minmax(0,.85fr) minmax(0,1.15fr);gap:clamp(28px,5vw,72px);align-items:center;margin-bottom:clamp(64px,8vw,104px)}
.od-profwrap>*{min-width:0}
.od-prof{background:#fff;border:1px solid var(--od-line);border-radius:24px;padding:clamp(18px,2.5vw,28px);box-shadow:0 30px 60px -44px #0B22A8}
.od-prof__top{display:flex;align-items:center;gap:12px;padding-bottom:16px;margin-bottom:6px;border-bottom:1px solid var(--od-line);flex-wrap:wrap}
.od-prof__top>div{flex:1;min-width:160px}
.od-prof__top strong{display:block;font:700 1rem var(--display)}
.od-prof__top div span{font-size:.82rem;color:var(--od-muted)}
.od-prof__av{width:44px;height:44px;border-radius:50%;display:grid;place-items:center;background:var(--od-sky);color:var(--od-blue)}
.od-prof__g{padding:12px 0;border-bottom:1px dashed var(--od-line)}
.od-prof__g:last-child{border-bottom:0}
.od-prof__gh{display:grid;grid-template-columns:20px 120px 1fr;align-items:center;gap:8px;margin-bottom:8px}
.od-prof__gh .rc-ico{color:var(--od-blue)}
.od-prof__gh strong{font:700 .9rem var(--display)}
.od-prof__bar{height:6px;border-radius:3px;background:#EEF1F6;overflow:hidden}
.od-prof__bar b{display:block;height:100%;width:var(--w);border-radius:3px;background:linear-gradient(90deg,var(--od-blue),var(--od-teal));transform-origin:left;transform:scaleX(0);transition:transform 1.2s cubic-bezier(.2,.7,.2,1);transition-delay:calc(var(--i)*.15s)}
.od-prof.is-in .od-prof__bar b{transform:scaleX(1)}
.od-prof__g ul{list-style:none;margin:0;padding:0 0 0 28px;display:flex;flex-wrap:wrap;gap:6px}
.od-prof__g li{font-size:.8rem;font-weight:600;padding:4px 10px;border-radius:8px;background:var(--od-sky);color:var(--od-royal);opacity:0;transform:scale(.9);transition:opacity .35s,transform .35s;transition-delay:calc(var(--i)*.15s + .3s)}
.od-prof.is-in .od-prof__g li{opacity:1;transform:none}

/* attributes */
.od-attrwrap .rc-head{max-width:680px}
.od-attr__tabs{display:flex;flex-wrap:wrap;gap:8px;margin-bottom:20px}
.od-attr__tabs button{border:1px solid var(--od-line);background:#fff;border-radius:999px;padding:8px 16px;font-weight:600;font-size:.88rem;color:var(--od-navy);transition:all .2s}
.od-attr__tabs button.is-on{background:var(--od-navy);color:#fff;border-color:var(--od-navy)}
.od-attr__cloud{display:grid;grid-template-columns:repeat(5,1fr);gap:12px}
.od-attr__grp{background:#fff;border:1px solid var(--od-line);border-radius:18px;padding:18px;display:flex;flex-wrap:wrap;gap:6px;align-content:flex-start;transition:opacity .3s,transform .3s,box-shadow .3s,border-color .3s}
.od-attr__grp.is-dim{opacity:.32}
.od-attr__grp.is-focus{border-color:var(--od-blue);box-shadow:0 20px 40px -28px #0B22A8;transform:translateY(-3px)}
.od-attr__gl{width:100%;font:700 .74rem var(--body);letter-spacing:.12em;text-transform:uppercase;color:var(--od-blue);margin-bottom:6px}
.od-attr__grp1 .od-attr__gl{color:var(--od-royal)}.od-attr__grp2 .od-attr__gl{color:#5A3FE0}.od-attr__grp3 .od-attr__gl{color:var(--od-teal)}.od-attr__grp4 .od-attr__gl{color:#B07A00}
.od-attr__chip{font-size:.82rem;font-weight:500;padding:5px 10px;border-radius:8px;background:var(--od-paper);border:1px solid var(--od-line)}

/* quality */
.od-sec--q{background:linear-gradient(180deg,#fff 0%,var(--od-paper) 100%)}
.od-qc{display:grid;grid-template-columns:minmax(0,.8fr) minmax(0,1.2fr);gap:clamp(24px,5vw,64px);align-items:center}
.od-qc>*{min-width:0}
.od-qc__shield>svg{width:100%;max-width:400px;display:block;margin:auto}
.od-qc__l{stroke:#fff;stroke-width:2;cursor:pointer;transform-origin:170px 190px;transform:scale(.6);opacity:0;transition:transform .7s cubic-bezier(.2,.7,.2,1),opacity .5s,fill .25s;transition-delay:calc(var(--i)*.15s)}
.od-qc.is-in .od-qc__l{transform:none;opacity:1}
.od-qc__l0{fill:#DCE5FF}.od-qc__l1{fill:#BFD0FF}.od-qc__l2{fill:#93AEFF}.od-qc__l3{fill:#5F86FF}.od-qc__l4{fill:#2F5FF5}.od-qc__l5{fill:#0B22A8}
.od-qc__l.is-on{fill:var(--od-teal)}
.od-qc__core{color:#fff}
.od-qc__list{list-style:none;margin:0;padding:0;display:grid;grid-template-columns:1fr 1fr;gap:10px}
.od-qc__list li{display:flex;gap:14px;align-items:flex-start;padding:16px;border-radius:16px;border:1px solid var(--od-line);background:#fff;cursor:default;transition:border-color .2s,box-shadow .2s,transform .2s;outline:none}
.od-qc__list li.is-on{border-color:var(--od-teal);box-shadow:0 16px 32px -24px #0E9C88;transform:translateY(-2px)}
.od-qc__n{flex:none;width:36px;height:36px;border-radius:10px;display:grid;place-items:center;background:var(--od-sky);color:var(--od-royal);font:800 .8rem var(--display)}
.od-qc__list li.is-on .od-qc__n{background:var(--od-teal);color:#fff}
.od-qc__list strong{display:block;font:700 .96rem var(--display);margin-bottom:2px}
.od-qc__list span{font-size:.85rem;color:var(--od-muted);line-height:1.45}
.od-checks{margin-top:clamp(36px,5vw,56px);padding:clamp(20px,3vw,32px);border-radius:22px;background:var(--od-navy);color:#fff}
.od-checks__lead{font:600 1.02rem var(--display);margin:0 0 16px;color:#E4EAFF}
.od-checks ul{list-style:none;padding:0;margin:0;display:flex;flex-wrap:wrap;gap:8px}
.od-checks li{display:inline-flex;align-items:center;gap:8px;padding:9px 14px;border-radius:999px;background:#ffffff10;border:1px solid #ffffff22;font-size:.86rem;font-weight:600;transition:background .2s}
.od-checks li:hover{background:#ffffff1f}
.od-checks li .rc-ico{color:#6EE0CE}
.od-funwrap{margin-top:clamp(40px,5vw,64px)}
.od-funwrap h3{font-size:clamp(1.25rem,2vw,1.55rem);margin-bottom:20px}
.od-fun__svg{width:100%;height:clamp(110px,16vw,200px);display:block}
.od-fun__seg{transform-origin:left center;transform:scaleX(0);transition:transform .7s cubic-bezier(.2,.7,.2,1);transition-delay:calc(var(--i)*.22s)}
.od-fun.is-in .od-fun__seg{transform:none}
.od-fun__seg0{fill:#DCE5FF}.od-fun__seg1{fill:#BFD0FF}.od-fun__seg2{fill:#93AEFF}.od-fun__seg3{fill:#5F86FF}.od-fun__seg4{fill:#2F5FF5}.od-fun__seg5{fill:var(--od-teal)}
.od-fun__labels{list-style:none;padding:0;margin:14px 0 0;display:grid;grid-template-columns:repeat(6,1fr);gap:8px}
.od-fun__labels li{display:flex;flex-direction:column;gap:4px;opacity:0;transform:translateY(6px);transition:opacity .4s,transform .4s;transition-delay:calc(var(--i)*.22s + .3s)}
.od-fun.is-in .od-fun__labels li{opacity:1;transform:none}
.od-fun__n{font:800 1.3rem var(--display);color:var(--od-blue)}
.od-fun__labels li:last-child .od-fun__n{color:var(--od-teal)}
.od-fun__labels strong{font:600 .9rem/1.25 var(--display)}

/* survey */
.od-svwrap{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:clamp(28px,5vw,72px);align-items:center}
.od-svwrap>*{min-width:0}
.od-svwrap .od-chips{margin:10px 0 18px}
.od-svwrap a{color:var(--od-royal);font-weight:600}
.od-sv__steps{display:grid;grid-template-columns:repeat(4,1fr);gap:6px;margin-bottom:12px}
.od-sv__steps button{display:flex;align-items:center;gap:8px;justify-content:center;border:1px solid var(--od-line);background:#fff;border-radius:12px;padding:10px 6px;font-size:.82rem;font-weight:700;color:var(--od-muted);transition:all .25s}
.od-sv__steps button span{width:22px;height:22px;border-radius:50%;display:grid;place-items:center;background:var(--od-paper);font-size:.72rem}
.od-sv__steps button.is-done{color:var(--od-teal)}
.od-sv__steps button.is-done span{background:var(--od-teal-soft)}
.od-sv__steps button.is-on{background:var(--od-navy);color:#fff;border-color:var(--od-navy)}
.od-sv__steps button.is-on span{background:#ffffff22}
.od-sv__win{border:1px solid var(--od-line);border-radius:18px;overflow:hidden;background:#fff;box-shadow:0 30px 60px -44px #0B22A8}
.od-sv__chrome{display:flex;align-items:center;gap:6px;padding:10px 14px;background:var(--od-paper);border-bottom:1px solid var(--od-line);font-size:.76rem;color:var(--od-muted)}
.od-sv__chrome i{width:9px;height:9px;border-radius:50%;background:#D5DBE6}
.od-sv__chrome span{margin-left:8px}
.od-sv__body{padding:22px;min-height:300px}
.od-sv__prog{height:4px;border-radius:2px;background:#EEF1F6;margin-bottom:18px;overflow:hidden}
.od-sv__prog b{display:block;height:100%;background:var(--od-teal);transition:width .6s}
.od-sv__q{display:block;font:600 1.05rem/1.4 var(--display);color:var(--od-navy)}
.od-sv__hint{font-size:.8rem;color:var(--od-muted)}
.od-sv__opts{list-style:none;padding:0;margin:14px 0 0;display:grid;gap:8px}
.od-sv__opts li{display:flex;align-items:center;gap:10px;padding:10px 12px;border:1px solid var(--od-line);border-radius:10px;font-size:.92rem;transition:all .3s}
.od-sv__opts li.is-sel{border-color:var(--od-blue);background:var(--od-sky)}
.od-sv__box{width:20px;height:20px;border-radius:6px;border:1.5px solid #B9C2D3;display:grid;place-items:center;color:#fff;transition:all .3s}
.od-sv__opts li.is-sel .od-sv__box{background:var(--od-blue);border-color:var(--od-blue)}
.od-sv__val{display:flex;flex-wrap:wrap;gap:6px;margin-top:14px;animation:rcPanel .4s ease}
.od-sv__val span{display:inline-flex;align-items:center;gap:6px;padding:6px 10px;border-radius:999px;background:var(--od-teal-soft);color:#0A7C6C;font-size:.78rem;font-weight:700}
.od-sv__done{display:flex;flex-direction:column;align-items:center;text-align:center;gap:8px;padding:40px 10px;color:var(--od-teal);animation:rcPanel .4s ease}
.od-sv__done strong{font:700 1.1rem var(--display);color:var(--od-navy)}
.od-sv__done span{font-size:.88rem;color:var(--od-muted)}
.od-sv__cap{font-size:.76rem;color:#97A0B5;margin:10px 0 0;text-align:right}

/* fieldwork matrix */
.od-matrix{border:1px solid var(--od-line);border-radius:22px;overflow:hidden;background:#fff}
.od-matrix__row{display:grid;grid-template-columns:minmax(0,.9fr) minmax(0,1.1fr);border-top:1px solid var(--od-line);transition:background .2s}
.od-matrix__row:hover{background:var(--od-paper)}
.od-matrix__row--h{border-top:0;background:var(--od-navy)!important;color:#fff}
.od-matrix__row--h span{padding:14px 22px;font:700 .76rem var(--body);letter-spacing:.12em;text-transform:uppercase}
.od-matrix__req,.od-matrix__sup{display:flex;align-items:center;gap:12px;padding:16px 22px}
.od-matrix__req{font:700 1rem var(--display);color:var(--od-navy);border-right:1px solid var(--od-line)}
.od-matrix__req .rc-ico{color:var(--od-blue)}
.od-matrix__sup{color:var(--od-muted);font-weight:500}
.od-matrix__sup .rc-ico{color:var(--od-teal)}

/* how ring */
.od-how{display:grid;place-items:center}
.od-how>svg{width:100%;max-width:520px;overflow:visible}
.od-how__ring{fill:none;stroke:var(--od-line);stroke-width:10}
.od-how__prog{fill:none;stroke:var(--od-teal);stroke-width:4;stroke-linecap:round;transition:stroke-dasharray .6s cubic-bezier(.2,.7,.2,1)}
.od-how__n{cursor:pointer;outline:none}
.od-how__n circle{fill:#fff;stroke:var(--od-line);stroke-width:1.5;transition:fill .25s,stroke .25s}
.od-how__n text{font:700 12px var(--display);fill:var(--od-navy);pointer-events:none}
.od-how__n.is-done circle{stroke:var(--od-teal)}
.od-how__n.is-on circle{fill:var(--od-navy);stroke:var(--od-navy)}
.od-how__n.is-on text{fill:#fff}
.od-how__n:focus-visible circle{stroke:#E3A013;stroke-width:3}
.od-how__c{height:100%;display:flex;flex-direction:column;align-items:center;justify-content:center;text-align:center;animation:rcPanel .35s ease}
.od-how__c span{font:700 10px var(--body);letter-spacing:.14em;text-transform:uppercase;color:var(--od-teal)}
.od-how__c strong{font:800 22px var(--display);color:var(--od-navy);margin:2px 0 4px}
.od-how__c p{font-size:12.5px;line-height:1.45;color:var(--od-muted);margin:0}
.od-how__list{display:none}

/* methodologies */
.od-meth{display:grid;grid-template-columns:repeat(3,1fr);gap:14px}
.od-meth__card{display:flex;gap:16px;padding:22px;border-radius:18px;border:1px solid var(--od-line);background:#fff;transition:transform .2s,box-shadow .2s}
.od-meth__card:hover{transform:translateY(-3px);box-shadow:0 20px 40px -28px #0B22A880}
.od-meth__ic{flex:none;width:44px;height:44px;border-radius:12px;display:grid;place-items:center;background:var(--od-sky);color:var(--od-blue)}
.od-meth__card h3{font-size:1.04rem;margin-bottom:.3em}
.od-meth__card p{font-size:.92rem;color:var(--od-muted);margin:0 0 8px}

/* timeline */
.od-tl{list-style:none;margin:0;padding:0;display:grid;grid-template-columns:repeat(6,1fr);gap:14px;position:relative}
.od-tl:before{content:"";position:absolute;top:22px;left:22px;right:22px;height:2px;background:linear-gradient(90deg,#5F86FF,#6EE0CE)}
.od-tl li{position:relative}
.od-tl__dot{width:44px;height:44px;border-radius:50%;display:grid;place-items:center;background:#0E1A66;border:2px solid #5F86FF;color:#fff;position:relative;z-index:1;margin-bottom:14px}
.od-tl li:last-child .od-tl__dot{background:var(--od-teal);border-color:#6EE0CE}
.od-tl__n{display:block;font:700 .72rem var(--body);letter-spacing:.12em;color:#7F8CC4}
.od-tl strong{display:block;font:700 1rem var(--display);margin:4px 0 6px}
.od-tl p{font-size:.88rem;color:#C9D3F5;margin:0}

/* capabilities */
.od-cap{display:grid;grid-template-columns:repeat(6,1fr);gap:10px}
.od-cap__item{display:flex;flex-direction:column;gap:10px;padding:18px;border-radius:16px;background:var(--od-paper);border:1px solid var(--od-line);font:600 .9rem/1.25 var(--display);transition:transform .2s,background .2s}
.od-cap__item:hover{transform:translateY(-2px);background:#fff}
.od-cap__item .rc-ico{color:var(--od-blue)}
.od-cmp{margin-top:clamp(36px,5vw,56px)}
.od-cmp h3{font-size:1.3rem;margin-bottom:16px}
.od-cmp table{width:100%;min-width:520px;border-collapse:separate;border-spacing:0;background:#fff;border:1px solid var(--od-line);border-radius:18px;overflow:hidden}
.od-cmp th,.od-cmp td{padding:13px 18px;text-align:left;border-bottom:1px solid var(--od-line);font-size:.94rem}
.od-cmp tbody tr:last-child th,.od-cmp tbody tr:last-child td{border-bottom:0}
.od-cmp thead th{background:var(--od-paper);font:700 .76rem var(--body);letter-spacing:.12em;text-transform:uppercase;color:var(--od-muted)}
.od-cmp thead th:nth-child(n+2),.od-cmp td{text-align:center}
.od-cmp tbody th{font-weight:600}
.od-yes{display:inline-grid;place-items:center;width:26px;height:26px;border-radius:50%;background:var(--od-teal-soft);color:var(--od-teal)}
.od-part{display:inline-flex;align-items:center;gap:6px;font-size:.8rem;font-weight:600;color:#0A7C6C}
.od-no{color:#B9C2D3;font-weight:700}

/* use cases + scenarios */
.od-use{display:grid;grid-template-columns:repeat(3,1fr);gap:12px}
.od-use__card{display:flex;gap:14px;padding:20px;border-radius:16px;background:#fff;border:1px solid var(--od-line)}
.od-use__card>.rc-ico{color:var(--od-teal);margin-top:2px}
.od-use__card h3{font-size:1rem;margin-bottom:.25em}
.od-use__card p{font-size:.9rem;color:var(--od-muted);margin:0}
.od-scen{margin-top:clamp(56px,7vw,88px)}
.od-scen__grid{display:grid;grid-template-columns:repeat(4,1fr);gap:14px}
.od-scen__card{padding:24px;border-radius:20px;background:var(--od-navy);color:#fff;position:relative;overflow:hidden}
.od-scen__card:after{content:"";position:absolute;right:-30px;top:-30px;width:120px;height:120px;border-radius:50%;border:1px solid #ffffff1a}
.od-scen__n{font:800 .8rem var(--display);color:#6EE0CE;letter-spacing:.1em}
.od-scen__card h3{color:#fff;font-size:1.1rem;margin:10px 0 14px}
.od-scen__eq{display:flex;flex-wrap:wrap;align-items:center;gap:6px}
.od-scen__eq span{font-size:.8rem;font-weight:600;padding:5px 10px;border-radius:8px;background:#ffffff14;border:1px solid #ffffff22}
.od-scen__eq b{color:#6EE0CE;font-weight:700}

/* industries */
.od-ind{display:grid;grid-template-columns:repeat(4,1fr);gap:10px}
.od-ind__tile{display:flex;align-items:center;gap:12px;padding:16px 18px;border-radius:14px;border:1px solid var(--od-line);background:#fff;text-decoration:none;color:var(--od-navy);font-weight:600;font-size:.94rem;transition:border-color .2s,transform .2s}
.od-ind__tile svg{color:var(--od-blue);flex:none;transition:transform .2s}
.od-ind__tile:hover{border-color:var(--od-blue);transform:translateY(-2px)}
.od-ind__tile:hover svg{transform:scale(1.1)}

/* cta */
.od-cta{background:radial-gradient(700px 400px at 0% 0%,#14309F 0%,transparent 70%),var(--od-navy);color:#fff;padding:clamp(64px,8vw,104px) 0;scroll-margin-top:120px}
.od-cta__in{display:grid;grid-template-columns:minmax(0,.9fr) minmax(0,1.1fr);gap:clamp(28px,5vw,64px);align-items:start}
.od-cta__in>*{min-width:0}
.od-cta .rc-kicker{color:#6EE0CE}
.od-cta h2{color:#fff}
.od-cta__copy>p{color:#C9D3F5;font-size:1.05rem}
.od-cta__line{display:flex;flex-wrap:wrap;align-items:center;gap:8px 12px;font-weight:700;letter-spacing:.06em;color:#fff!important;font-size:.9rem!important}
.od-cta__line i{width:4px;height:4px;border-radius:50%;background:#6EE0CE}
.od-cta__btns{margin:18px 0 30px}
.od-cta h3{color:#fff;font-size:1rem}
.od-cta__rel{list-style:none;padding:0;margin:0;display:flex;flex-wrap:wrap;gap:8px}
.od-cta__rel a{display:inline-block;padding:7px 14px;border-radius:999px;border:1px solid #ffffff33;color:#E4EAFF;text-decoration:none;font-size:.86rem;font-weight:600}
.od-cta__rel a:hover{background:#ffffff14}
.od-cta .card-form{color:var(--od-navy)}

/* responsive */
@media (max-width:1100px){
  .od-glance__grid{grid-template-columns:repeat(3,1fr);row-gap:20px}
  .od-glance__lbl{grid-column:1/-1}
  .od-glance__item:nth-child(5){border-left:0}
  .od-flow{grid-template-columns:repeat(4,1fr);row-gap:28px}
  .od-flow__track{display:none}
  .od-attr__cloud{grid-template-columns:repeat(3,1fr)}
  .od-cap{grid-template-columns:repeat(4,1fr)}
  .od-tl{grid-template-columns:repeat(3,1fr);row-gap:28px}
  .od-tl:before{display:none}
  .od-scen__grid{grid-template-columns:1fr 1fr}
}
@media (max-width:900px){
  .od-hero__in,.od-split,.od-cov,.od-infra,.od-regwrap,.od-profwrap,.od-qc,.od-svwrap,.od-cta__in{grid-template-columns:1fr}
  .od-panels,.od-why,.od-rec,.od-meth,.od-use{grid-template-columns:1fr 1fr}
  .od-ind{grid-template-columns:repeat(3,1fr)}
  .od-fcard--b2b{top:-6px}
}
@media (max-width:640px){
  .od-hero h1{font-size:2rem}
  .od-hero__ctas .btn{width:100%}
  .od-hmap{padding:8px 0 0}
  .od-fcard{position:static;animation:none;display:inline-flex;margin:6px 6px 0 0;padding:8px 12px}
  .od-hub__lbl{font-size:18px}
  .od-hub__pill{display:none}
  .od-hub__lbl{paint-order:stroke;stroke:#fff;stroke-width:5px}
  .od-trust .trustbar__inner{gap:12px}
  .od-glance__grid{grid-template-columns:1fr 1fr}
  .od-glance__item{border-left:0;padding:12px 0;border-top:1px solid var(--od-line)}
  .od-glance__item:nth-child(6){grid-column:1/-1}
  .od-flow{grid-template-columns:1fr;gap:0}
  .od-flow li{flex-direction:row;text-align:left;gap:14px;padding:6px 0}
  .od-flow__dot{width:48px;height:48px}
  .od-flow__n{order:3;margin-left:auto}
  .od-panels,.od-why,.od-rec,.od-meth,.od-use,.od-scen__grid,.od-qc__list{grid-template-columns:1fr}
  .od-panel{padding:22px}
  .od-ticks{grid-template-columns:1fr}
  .od-attr__cloud{grid-template-columns:1fr}
  .od-attr__tabs{flex-wrap:nowrap;overflow-x:auto;scrollbar-width:none;margin-inline:-16px;padding-inline:16px}
  .od-attr__tabs button{flex:none}
  .od-qc__shield>svg{max-width:240px}
  .od-fun__svg{display:none}
  .od-fun__labels{grid-template-columns:1fr;gap:6px}
  .od-fun__labels li{flex-direction:row;align-items:center;gap:12px;padding:12px 14px;border-radius:12px;background:#fff;border:1px solid var(--od-line);margin-inline:calc(var(--i)*8px)}
  .od-fun__labels li:last-child{background:var(--od-teal);color:#fff;border-color:var(--od-teal)}
  .od-fun__labels li:last-child .od-fun__n{color:#fff}
  .od-sv__steps button{flex-direction:column;gap:4px;font-size:.72rem;padding:8px 4px}
  .od-sv__body{padding:16px;min-height:330px}
  .od-matrix__row{grid-template-columns:1fr}
  .od-matrix__row--h{display:none}
  .od-matrix__req{border-right:0;padding-bottom:4px}
  .od-matrix__sup{padding-top:0;padding-left:52px}
  .od-how>svg{display:none}
  .od-how__list{display:grid;list-style:none;padding:0;margin:0;gap:8px;width:100%}
  .od-how__list li{display:flex;gap:14px;padding:14px;border-radius:14px;background:#fff;border:1px solid var(--od-line)}
  .od-how__list span{flex:none;width:34px;height:34px;border-radius:50%;display:grid;place-items:center;background:var(--od-navy);color:#fff;font:800 .74rem var(--display)}
  .od-how__list strong{font:700 1rem var(--display)}
  .od-how__list p{margin:2px 0 0;font-size:.88rem;color:var(--od-muted)}
  .od-tl{grid-template-columns:1fr;gap:0;padding-left:4px}
  .od-tl li{display:grid;grid-template-columns:44px 1fr;column-gap:14px;padding-bottom:18px}
  .od-tl li:not(:last-child):after{content:"";position:absolute;left:21px;top:44px;bottom:0;width:2px;background:#5F86FF66}
  .od-tl__dot{grid-row:span 3;margin:0}
  .od-cap{grid-template-columns:1fr 1fr}
  .od-ind{grid-template-columns:1fr 1fr}
  .od-ind__tile{padding:12px;font-size:.84rem}
  .od-infra__wheel>svg{max-width:340px}
  .od-infra__t{font-size:14px}
}
@media (prefers-reduced-motion:reduce){
  .od *{animation:none!important;transition:none!important}
  .od-arc,.od-hub,.od-mk,.od-flow li,.od-reg__row,.od-prof__g li,.od-qc__l,.od-fun__labels li{opacity:1!important;transform:none!important}
  .od-flow__track span,.od-prof__bar b,.od-fun__seg,.od-reg__ok{transform:none!important}
  .od-traveller{display:none}
}
.od-cov__all{justify-self:start;border:1px solid var(--od-line);background:#fff;border-radius:999px;padding:8px 16px;font-weight:600;font-size:.86rem;color:var(--od-navy)}
.od-cov__all.is-on{background:var(--od-navy);color:#fff;border-color:var(--od-navy)}

/* ===== Consumer Panel page (cp-) ===== */
.cp{--od-navy:#07104F;--od-blue:#1E5BFF;--od-royal:#0B22A8;--od-sky:#E8EEFF;--od-teal:#0E9C88;--od-teal-soft:#E3F5F2;--od-line:#DDE2EC;--od-muted:#525C78;--od-paper:#F5F7FB;--cp-navy:#07104F;--cp-brand:#0B22A8;--cp-blue:#1E5BFF;--cp-teal:#0E9C88;--cp-amber:#E3A013;--cp-line:#DDE2EC;--cp-muted:#525C78;--cp-paper:#F5F7FB;--cp-sky:#E8EEFF}

/* hero */
.cp-hero{background:linear-gradient(180deg,#fff 0%,#F3F6FC 100%);padding:clamp(32px,4vw,56px) 0 clamp(36px,4vw,56px);border-bottom:1px solid var(--cp-line);overflow:hidden}
.cp-hero__in{display:grid;grid-template-columns:minmax(0,.9fr) minmax(0,1.1fr);gap:clamp(24px,4vw,56px);align-items:center}
.cp-hero__in>*{min-width:0}
.cp-hero h1{font-size:clamp(2.6rem,5.4vw,4.4rem);color:var(--cp-navy);margin-bottom:.25em}
.cp-hero__sub{font:600 clamp(1.15rem,1.8vw,1.45rem)/1.4 var(--display);color:var(--cp-brand);max-width:28ch;margin-bottom:14px}
.cp-hero__body{color:var(--cp-muted);font-size:1.05rem;max-width:54ch;margin-bottom:26px}
.cp-hero__link{display:inline-flex;align-items:center;gap:6px;margin-top:18px;font-weight:700;color:var(--cp-brand);text-decoration:none;border-bottom:1px solid #0B22A840;padding-bottom:2px}
.cp-hero__link:hover{border-color:var(--cp-brand)}
.cp-eco{position:relative;background:radial-gradient(600px 400px at 50% 40%,#13238F 0%,#07104F 70%);border-radius:28px;padding:20px 16px 18px;box-shadow:0 40px 80px -50px #07104F}
.cp-eco__svg{width:100%;height:auto;display:block;overflow:visible}
.cp-eco__orbit{fill:none;stroke:#ffffff26;stroke-dasharray:2 6;transform-origin:260px 235px;animation:rcSpin 90s linear infinite}
.cp-eco__orbit--in{stroke:#ffffff14;stroke-dasharray:none;animation:none}
.cp-eco__spoke{stroke:#7FA6FF;stroke-opacity:.35;stroke-dasharray:3 7;animation:rcDash 3s linear infinite}
.cp-eco__node{opacity:0;animation:rcFade .6s ease forwards}
.cp-eco__dot{fill:#0E1A66;stroke:#5F86FF;stroke-width:1.5}
.cp-eco__node foreignObject{color:#C9D6FF}
.cp-eco__lbl{font:600 12.5px var(--body);fill:#E4EAFF}
.cp-eco__core{fill:#fff}
.cp-eco__pulse{fill:none;stroke:#fff;stroke-opacity:.6;transform-box:fill-box;transform-origin:center;animation:rcPulse 3.2s ease-out infinite}
.cp-eco__person circle,.cp-eco__person path{fill:var(--cp-brand)}
.cp-eco__person:nth-of-type(odd) circle,.cp-eco__person:nth-of-type(odd) path{fill:#5F86FF}
.cp-eco__ct{font:800 11px var(--display);letter-spacing:.14em;fill:var(--cp-navy)}
.cp-eco__card{position:absolute;background:#fff;border-radius:14px;padding:10px 12px;box-shadow:0 18px 36px -18px #000;animation:odFloat 7s ease-in-out infinite}
.cp-eco__card--a{left:-22px;bottom:-16px}
.cp-eco__card--b{right:-18px;top:-18px;animation-delay:-3.5s}
.cp-eco__ck{display:block;font:800 .66rem var(--body);letter-spacing:.14em;text-transform:uppercase;color:var(--cp-teal);margin-bottom:6px}
.cp-eco__chips{display:flex;flex-direction:column;gap:4px}
.cp-eco__chips i{display:flex;align-items:center;gap:6px;font-style:normal;font-size:.76rem;font-weight:600;color:var(--cp-navy)}
.cp-eco__chips .rc-ico{color:var(--cp-teal)}
.cp-eco__flow{list-style:none;margin:6px 0 0;padding:0;display:flex;justify-content:center;flex-wrap:wrap;gap:6px}
.cp-eco__flow li{display:flex;align-items:center;gap:6px;font:700 .78rem var(--body);letter-spacing:.06em;text-transform:uppercase;color:#fff;padding:7px 12px;border-radius:999px;background:#ffffff14;border:1px solid #ffffff24;opacity:0;animation:rcFade .5s ease forwards;animation-delay:calc(.9s + var(--i)*.25s)}
.cp-eco__flow li:not(:last-child):after{content:"→";color:#6EE0CE;margin-left:6px}
.cp-eco__flow li:last-child{background:var(--cp-teal);border-color:var(--cp-teal)}
.cp-stats{list-style:none;margin:clamp(28px,4vw,44px) 0 0;padding:0;display:grid;grid-template-columns:repeat(5,1fr);background:#fff;border:1px solid var(--cp-line);border-radius:20px;overflow:hidden}
.cp-stats li{padding:20px 22px;display:flex;flex-direction:column;gap:4px}
.cp-stats li+li{border-left:1px solid var(--cp-line)}
.cp-stats .od-count{font-size:clamp(1.7rem,2.8vw,2.3rem);color:var(--cp-brand)}
.cp-stats li:nth-child(2) .od-count{color:var(--cp-teal)}
.cp-stats span:last-child{font-size:.86rem;color:var(--cp-muted)}

/* intro + why */
.cp-intro a,.cp a.inline{color:var(--cp-brand);font-weight:600}
.cp-why{display:grid;gap:14px}
.cp-why__row{display:grid;grid-template-columns:220px 1fr;gap:20px;align-items:center;padding:18px 22px;border-radius:20px;background:#FBEEEF;border:1px solid #F2D3D6}
.cp-why__row--good{background:var(--cp-sky);border-color:#CBD8FF}
.cp-why__tag{font:700 .76rem var(--body);letter-spacing:.12em;text-transform:uppercase;color:#B4424B}
.cp-why__row--good .cp-why__tag{color:var(--cp-brand)}
.cp-why ol{list-style:none;margin:0;padding:0;display:grid;grid-template-columns:repeat(3,1fr);gap:8px}
.cp-why li{display:flex;align-items:center;gap:12px;position:relative;opacity:0;transform:translateX(-10px);transition:opacity .5s,transform .5s;transition-delay:calc(var(--i)*.18s)}
.cp-why.is-in li{opacity:1;transform:none}
.cp-why li:not(:last-child):after{content:"→";position:absolute;right:6px;font-size:1.1rem;color:#C9858B}
.cp-why__row--good li:not(:last-child):after{color:var(--cp-blue)}
.cp-why__ic{width:44px;height:44px;border-radius:12px;display:grid;place-items:center;background:#fff;color:#B4424B;flex:none}
.cp-why__row--good .cp-why__ic{color:var(--cp-brand)}
.cp-why__row--good li:last-child .cp-why__ic{background:var(--cp-brand);color:#fff}
.cp-why strong{font:700 1rem var(--display);color:var(--cp-navy)}

/* provide */
.cp-prov{display:grid;grid-template-columns:repeat(4,1fr);gap:16px}
.cp-prov__card{background:#fff;border:1px solid var(--cp-line);border-radius:20px;padding:26px;display:flex;flex-direction:column}
.cp-prov__ic{width:52px;height:52px;border-radius:14px;display:grid;place-items:center;background:var(--cp-sky);color:var(--cp-brand);margin-bottom:18px}
.cp-prov__card h3{font-size:1.1rem}
.cp-prov__card p{color:var(--cp-muted);font-size:.94rem}
.cp-prov__card ul{list-style:none;padding:0;margin:auto 0 0;display:flex;flex-wrap:wrap;gap:6px}
.cp-prov__card li{font-size:.76rem;font-weight:600;padding:4px 10px;border-radius:999px;background:var(--cp-paper);border:1px solid var(--cp-line)}

/* panels ecosystem */
.cp-pan{display:grid;grid-template-columns:minmax(0,.9fr) 60px minmax(0,1.3fr);gap:0;align-items:center}
.cp-pan__sources{display:grid;gap:14px}
.cp-pan__src{display:grid;grid-template-columns:auto 1fr;column-gap:16px;row-gap:2px;align-items:center;padding:20px 22px;border-radius:20px;border:1px solid var(--cp-line);background:#fff;text-decoration:none;color:var(--cp-navy)}
.cp-pan__logo{grid-row:span 3;width:120px;height:72px;border-radius:16px;display:grid;place-items:center;background:#fff;border:1px solid var(--cp-line);overflow:hidden;padding:8px}
.cp-pan__logo .plogo,.cp-pan__logo img{max-width:100%!important;max-height:56px!important;width:auto!important;height:auto!important}
.cp-pan__name{font:800 1.2rem var(--display)}
.cp-pan__aud{font-size:.86rem;color:var(--cp-muted)}
.cp-pan__go{display:inline-flex;align-items:center;gap:6px;font-size:.84rem;font-weight:700;color:var(--cp-brand)}
.cp-pan__pipe{height:2px;background:#E3E7EF;position:relative;margin:0 6px}
.cp-pan__pipe span{position:absolute;inset:0;background:linear-gradient(90deg,var(--cp-blue),var(--cp-teal));transform-origin:left;transform:scaleX(0);transition:transform 1s}
.cp-pan.is-in .cp-pan__pipe span{transform:scaleX(1)}
.cp-pan__flow{list-style:none;margin:0;padding:22px;display:grid;grid-template-columns:repeat(5,1fr);gap:8px;background:var(--cp-navy);border-radius:24px;position:relative}
.cp-pan__flow li{display:flex;flex-direction:column;align-items:center;text-align:center;gap:8px;color:#fff;opacity:.25;transition:opacity .5s;transition-delay:calc(.6s + var(--i)*.3s);position:relative}
.cp-pan.is-in .cp-pan__flow li{opacity:1}
.cp-pan__flow li:not(:last-child):after{content:"";position:absolute;top:26px;left:calc(50% + 30px);right:calc(-50% + 30px);height:1px;background:repeating-linear-gradient(90deg,#7FA6FF 0 4px,transparent 4px 8px)}
.cp-pan__dot{width:52px;height:52px;border-radius:50%;display:grid;place-items:center;background:#ffffff12;border:1px solid #ffffff30;color:#C9D6FF}
.cp-pan__flow li:last-child .cp-pan__dot{background:var(--cp-teal);border-color:var(--cp-teal);color:#fff}
.cp-pan__n{font:700 .7rem var(--body);letter-spacing:.12em;color:#7F8CC4}
.cp-pan__flow strong{font:600 .9rem/1.25 var(--display)}

/* coverage */
.cp-cov{display:grid;grid-template-columns:minmax(0,.7fr) minmax(0,1.3fr);gap:clamp(24px,4vw,56px);align-items:center}
.cp-cov>*{min-width:0}
.cp-cov__stat .od-count{font-size:clamp(3.4rem,7vw,5.4rem);color:var(--cp-brand);display:block}
.cp-cov__stat>span{font:700 1.1rem var(--display);color:var(--cp-navy)}
.cp-cov__stat p{color:var(--cp-muted);margin:14px 0 18px}
.cp-cov__regs{display:flex;flex-wrap:wrap;gap:8px}
.cp-cov__reg{display:inline-flex;align-items:center;gap:8px;padding:8px 14px;border-radius:999px;border:1px solid var(--cp-line);background:#fff;font-weight:700;font-size:.88rem;color:var(--cp-navy);transition:all .2s}
.cp-cov__reg i{width:10px;height:10px;border-radius:50%;background:var(--cp-blue)}
.cp-cov__reg--eu i{background:var(--cp-brand)}.cp-cov__reg--mena i{background:var(--cp-amber)}.cp-cov__reg--apac i{background:var(--cp-teal)}
.cp-cov__reg.is-on,.cp-cov__reg:hover{border-color:var(--cp-navy);box-shadow:0 10px 20px -14px #07104F}
.cp-cov__map{position:relative;background:#fff;border:1px solid var(--cp-line);border-radius:24px;padding:clamp(14px,2.5vw,26px)}
.cp-cov__map>svg{width:100%;height:auto;display:block;overflow:visible}
.cp-cov__mk{color:var(--cp-blue);opacity:0;transition:opacity .6s}
.cp-cov.is-in .cp-cov__mk{opacity:1}
.cp-cov.is-in .cp-cov__mk.is-dim{opacity:.25}
.cp-cov__mk--eu{color:var(--cp-brand)}.cp-cov__mk--mena{color:#C48A0C}.cp-cov__mk--apac{color:var(--cp-teal)}
.cp-cov__halo{fill:currentColor;opacity:.09;transition:opacity .3s}
.cp-cov__mk.is-on .cp-cov__halo{opacity:.2}
.cp-cov__pt{fill:currentColor;stroke:#fff;stroke-width:3}
.cp-cov__ping{fill:none;stroke:currentColor;stroke-width:2;transform-box:fill-box;transform-origin:center;animation:cpPing 3s ease-out infinite}
@keyframes cpPing{0%{transform:scale(1);opacity:.8}100%{transform:scale(3.4);opacity:0}}
.cp-cov__lbl{font:800 17px var(--display);fill:var(--cp-navy);paint-order:stroke;stroke:#fff;stroke-width:5px}
.cp-cov__card{position:absolute;display:flex;align-items:center;gap:8px;padding:9px 14px;border-radius:12px;background:var(--cp-navy);color:#fff;font-size:.82rem;font-weight:700;box-shadow:0 14px 28px -16px #07104F;animation:odFloat 8s ease-in-out infinite}
.cp-cov__card .rc-ico{color:#6EE0CE}
.cp-cov__card--a{left:18px;bottom:16px}
.cp-cov__card--b{right:18px;top:16px;animation-delay:-4s}

/* profiling */
.cp-prof{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:clamp(24px,4vw,56px);align-items:center}
.cp-prof>*{min-width:0}
.cp-prof__chart{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:20px;align-items:center}
.cp-prof__chart svg{width:100%;max-width:340px;display:block}
.cp-prof__seg{cursor:pointer;outline:none;transform-origin:160px 160px;transform:scale(.6) rotate(-30deg);opacity:0;transition:transform .9s cubic-bezier(.2,.7,.2,1),opacity .6s,filter .2s;transition-delay:calc(var(--i)*.12s)}
.cp-prof.is-in .cp-prof__seg{transform:none;opacity:.55}
.cp-prof.is-in .cp-prof__seg.is-on{opacity:1;transform:scale(1.04)}
.cp-prof__seg:focus-visible{stroke:var(--cp-navy);stroke-width:3}
.cp-prof__big{font:800 48px var(--display);fill:var(--cp-navy)}
.cp-prof__sm{font:600 12px var(--body);fill:var(--cp-muted)}
.cp-prof__legend{list-style:none;margin:0;padding:0;display:grid;gap:6px}
.cp-prof__legend button{display:grid;grid-template-columns:12px 1fr auto;gap:10px;align-items:center;width:100%;text-align:left;border:1px solid transparent;background:transparent;border-radius:10px;padding:8px 10px;font-size:.9rem;font-weight:600;color:var(--cp-navy);transition:all .2s}
.cp-prof__legend button.is-on{background:#fff;border-color:var(--cp-line);box-shadow:0 10px 20px -16px #07104F}
.cp-prof__legend i{width:12px;height:12px;border-radius:3px}
.cp-prof__legend b{font:800 .9rem var(--display);color:var(--cp-muted)}
.cp-prof__panel{background:#fff;border:1px solid var(--cp-line);border-top:5px solid var(--c);border-radius:22px;padding:clamp(22px,3vw,34px);animation:rcPanel .4s ease}
.cp-prof__ic{width:50px;height:50px;border-radius:14px;display:grid;place-items:center;background:var(--cp-paper);color:var(--c);margin-bottom:14px}
.cp-prof__panel h3{font-size:1.4rem}
.cp-prof__panel p{color:var(--cp-muted)}
.cp-prof__panel ul{list-style:none;padding:0;margin:0;display:flex;flex-wrap:wrap;gap:8px}
.cp-prof__panel li{padding:8px 14px;border-radius:10px;background:var(--cp-paper);border:1px solid var(--cp-line);font-weight:600;font-size:.9rem;animation:rcPanel .4s ease both;animation-delay:calc(var(--i)*50ms)}
.cp-prof__acc{display:none}

/* quality */
.cp-qc{display:grid;grid-template-columns:repeat(4,1fr);gap:14px}
.cp-qc__col{background:#fff;border:1px solid var(--cp-line);border-radius:20px;overflow:hidden;display:flex;flex-direction:column}
.cp-qc__head{display:flex;align-items:center;gap:12px;width:100%;text-align:left;padding:20px 20px 0;background:none;border:0;color:var(--cp-navy);cursor:default}
.cp-qc__ic{width:46px;height:46px;border-radius:12px;display:grid;place-items:center;background:var(--cp-navy);color:#fff;flex:none}
.cp-qc__col:nth-child(2) .cp-qc__ic{background:var(--cp-brand)}.cp-qc__col:nth-child(3) .cp-qc__ic{background:var(--cp-blue)}.cp-qc__col:nth-child(4) .cp-qc__ic{background:var(--cp-teal)}
.cp-qc__t{display:flex;flex-direction:column;font:700 1rem/1.25 var(--display)}
.cp-qc__t small{font:700 .7rem var(--body);letter-spacing:.12em;color:#97A0B5}
.cp-qc__tog{display:none;margin-left:auto}
.cp-qc__body{padding:12px 20px 20px}
.cp-qc__body p{font-size:.88rem;color:var(--cp-muted);margin-bottom:12px}
.cp-qc__body ul{list-style:none;margin:0;padding:0;display:grid;gap:6px}
.cp-qc__body li{display:flex;align-items:center;gap:10px;padding:8px 10px;border-radius:10px;background:var(--cp-paper);font-size:.86rem;font-weight:600}
.cp-qc__body li .rc-ico{color:var(--cp-brand)}
.cp-scorewrap{margin-top:clamp(40px,5vw,64px);display:grid;grid-template-columns:minmax(0,.8fr) minmax(0,1.2fr);gap:clamp(24px,4vw,56px);align-items:center}
.cp-scorewrap>*{min-width:0}
.cp-scorewrap h3{font-size:clamp(1.3rem,2.2vw,1.7rem)}
.cp-scorewrap a{color:var(--cp-brand);font-weight:600}
.cp-score{background:#fff;border:1px solid var(--cp-line);border-radius:24px;padding:clamp(18px,3vw,30px);display:flex;flex-direction:column;align-items:center;gap:10px}
.cp-score__ins{display:flex;flex-wrap:wrap;align-items:center;justify-content:center;gap:6px}
.cp-score__in{display:flex;align-items:center;gap:8px;padding:10px 12px;border-radius:12px;background:var(--cp-sky);color:var(--cp-brand);font-size:.84rem;font-weight:700;opacity:0;transform:translateY(8px);transition:all .45s;transition-delay:calc(var(--i)*.15s)}
.cp-score.is-in .cp-score__in{opacity:1;transform:none}
.cp-score__plus{font:800 1.1rem var(--display);color:#97A0B5}
.cp-score__arrow{width:2px;height:26px;background:linear-gradient(var(--cp-blue),var(--cp-teal));position:relative}
.cp-score__arrow:after{content:"";position:absolute;bottom:-4px;left:-4px;border:5px solid transparent;border-top-color:var(--cp-teal);border-bottom:0}
.cp-score__mid{display:flex;flex-direction:column;align-items:center;text-align:center;gap:4px;padding:16px 24px;border-radius:16px;background:var(--cp-navy);color:#fff;min-width:min(340px,100%)}
.cp-score__mid .rc-ico{color:#6EE0CE}
.cp-score__mid strong{font:700 1rem var(--display)}
.cp-score__mid span{font-size:.8rem;color:#C9D3F5}
.cp-score__out{display:flex;align-items:center;gap:10px;padding:14px 20px;border-radius:16px;background:var(--cp-teal);color:#fff;font:700 .95rem var(--display);text-align:left}
.cp-score__note{display:flex;align-items:center;gap:10px;flex-wrap:wrap;justify-content:center;margin:6px 0 0;font-size:.8rem;color:var(--cp-muted)}

/* mid cta */
.cp-mid{background:linear-gradient(100deg,var(--cp-brand),#13238F);color:#fff;padding:clamp(28px,4vw,44px) 0}
.cp-mid__in{display:flex;align-items:center;justify-content:space-between;gap:24px;flex-wrap:wrap}
.cp-mid strong{display:block;font:700 clamp(1.2rem,2vw,1.5rem) var(--display);margin-bottom:4px}
.cp-mid span{color:#DCE4FF;max-width:62ch;display:block}

/* recruitment */
.cp-rec{list-style:none;margin:0;padding:0;display:grid;grid-template-columns:repeat(6,1fr);gap:12px;position:relative}
.cp-rec__line{position:absolute;top:30px;left:30px;right:30px;height:3px;border-radius:2px;background:#E3E7EF}
.cp-rec__line span{display:block;height:100%;border-radius:2px;background:linear-gradient(90deg,var(--cp-blue),var(--cp-teal));transform-origin:left;transform:scaleX(0);transition:transform 2.4s cubic-bezier(.2,.7,.2,1)}
.cp-rec.is-in .cp-rec__line span{transform:scaleX(1)}
.cp-rec li{position:relative;opacity:.3;transform:translateY(8px);transition:opacity .5s,transform .5s;transition-delay:calc(var(--i)*.35s)}
.cp-rec.is-in li{opacity:1;transform:none}
.cp-rec__dot{width:60px;height:60px;border-radius:50%;display:grid;place-items:center;background:#fff;border:2px solid var(--cp-blue);color:var(--cp-brand);position:relative;z-index:1;margin-bottom:14px;transition:transform .2s}
.cp-rec li:hover .cp-rec__dot{transform:scale(1.06)}
.cp-rec li:last-child .cp-rec__dot{background:var(--cp-teal);border-color:var(--cp-teal);color:#fff}
.cp-rec__n{display:block;font:700 .72rem var(--body);letter-spacing:.12em;color:#97A0B5}
.cp-rec strong{display:block;font:700 1rem var(--display);margin:2px 0 6px}
.cp-rec p{font-size:.88rem;color:var(--cp-muted);margin:0}
.cp-rew{margin-top:clamp(40px,5vw,64px);display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:clamp(24px,4vw,56px);align-items:center;padding:clamp(22px,3vw,36px);border-radius:24px;background:var(--cp-paper);border:1px solid var(--cp-line)}
.cp-rew>*{min-width:0}
.cp-rew h3{font-size:clamp(1.2rem,2vw,1.5rem)}
.cp-rew__flow{display:flex;flex-wrap:wrap;align-items:center;gap:8px;margin:14px 0}
.cp-rew__flow span{display:inline-flex;align-items:center;gap:6px;padding:8px 12px;border-radius:999px;background:#fff;border:1px solid var(--cp-line);font-weight:700;font-size:.86rem}
.cp-rew__flow span .rc-ico{color:var(--cp-teal)}
.cp-rew__arr{color:#97A0B5}
.cp-rew__methods{list-style:none;margin:0;padding:0;display:grid;grid-template-columns:1fr 1fr;gap:10px}
.cp-rew__methods li{display:grid;grid-template-columns:auto 1fr;column-gap:12px;align-items:center;padding:16px;border-radius:16px;background:#fff;border:1px solid var(--cp-line)}
.cp-rew__methods .rc-ico{grid-row:span 2;color:var(--cp-brand)}
.cp-rew__methods strong{font:700 .98rem var(--display)}
.cp-rew__methods span{font-size:.8rem;color:var(--cp-muted)}

/* workflow */
.cp-wf{position:relative}
.cp-wf__bar{position:absolute;top:21px;left:0;right:0;height:3px;border-radius:2px;background:#ffffff1a}
.cp-wf__bar span{display:block;height:100%;border-radius:2px;background:linear-gradient(90deg,#7FA6FF,#6EE0CE);transform-origin:left;transform:scaleX(0);transition:transform 2.8s cubic-bezier(.2,.7,.2,1)}
.cp-wf.is-in .cp-wf__bar span{transform:scaleX(1)}
.cp-wf ol{list-style:none;margin:0;padding:0;display:grid;grid-template-columns:repeat(7,1fr);gap:10px;position:relative}
.cp-wf li{padding:0 4px 18px;border-radius:16px;outline:none;opacity:.3;transition:opacity .5s,background .25s;transition-delay:calc(var(--i)*.35s),0s}
.cp-wf.is-in li{opacity:1}
.cp-wf__n{width:44px;height:44px;border-radius:50%;display:grid;place-items:center;background:#0E1A66;border:2px solid #5F86FF;color:#fff;font:800 .82rem var(--display);margin-bottom:14px;transition:all .25s}
.cp-wf li:last-child .cp-wf__n{background:var(--cp-teal);border-color:#6EE0CE}
.cp-wf li.is-on .cp-wf__n,.cp-wf li:focus-visible .cp-wf__n{background:#fff;color:var(--cp-navy);transform:scale(1.08)}
.cp-wf strong{display:block;color:#fff;font:700 1rem var(--display);margin-bottom:6px}
.cp-wf p{font-size:.86rem;color:#C9D3F5;margin:0}

/* comparison */
.cp-cmp{border:1px solid var(--cp-line);border-radius:22px;overflow:hidden;background:#fff}
.cp-cmp__row{display:grid;grid-template-columns:minmax(0,.8fr) minmax(0,1.2fr) minmax(0,.9fr);border-top:1px solid var(--cp-line);transition:background .2s}
.cp-cmp__row:hover{background:var(--cp-paper)}
.cp-cmp__row--h{border-top:0;background:var(--cp-navy)!important;color:#fff}
.cp-cmp__row--h span{padding:14px 22px;font:700 .76rem var(--body);letter-spacing:.12em;text-transform:uppercase}
.cp-cmp__need{display:flex;align-items:center;gap:12px;padding:16px 22px;font:700 1rem var(--display);color:var(--cp-navy);background:none;border:0;text-align:left;cursor:default}
.cp-cmp__need .rc-ico{color:var(--cp-brand)}
.cp-cmp__row>span{padding:16px 22px;color:var(--cp-muted);display:flex;align-items:center}
.cp-cmp__sig{font-weight:700;color:var(--cp-teal)!important}

/* team */
.cp-team{display:grid;grid-template-columns:minmax(0,.8fr) minmax(0,1.2fr);gap:clamp(28px,5vw,64px);align-items:start}
.cp-team>*{min-width:0}
.cp-team .rc-head{margin-bottom:16px}
.cp-tech{margin-top:28px}
.cp-roles{display:grid;grid-template-columns:repeat(3,1fr);gap:12px}
.cp-role{display:flex;flex-direction:column;gap:8px;padding:20px;border-radius:18px;background:var(--cp-paper);border:1px solid var(--cp-line)}
.cp-role .rc-ico{color:var(--cp-brand)}
.cp-role strong{font:700 .98rem/1.3 var(--display)}
.cp-role span{font-size:.84rem;color:var(--cp-muted)}

/* case */
.cp-case{display:grid;grid-template-columns:minmax(0,.6fr) minmax(0,1.4fr);gap:clamp(24px,4vw,56px);align-items:center;padding:clamp(24px,4vw,48px);border-radius:28px;background:var(--cp-paper);border:1px solid var(--cp-line)}
.cp-case>*{min-width:0}
.cp-case__steps{list-style:none;margin:0;padding:0;display:grid;grid-template-columns:repeat(4,1fr);gap:12px;counter-reset:s}
.cp-case__steps li{padding:20px;border-radius:18px;background:#fff;border:1px solid var(--cp-line);position:relative}
.cp-case__steps li:not(:last-child):after{content:"→";position:absolute;right:-12px;top:50%;transform:translateY(-50%);width:22px;height:22px;border-radius:50%;background:var(--cp-navy);color:#fff;font-size:.7rem;display:grid;place-items:center;z-index:1}
.cp-case__ic{width:38px;height:38px;border-radius:10px;display:grid;place-items:center;background:var(--cp-sky);color:var(--cp-brand);margin-bottom:12px}
.cp-case__steps strong{display:block;font:700 .78rem var(--body);letter-spacing:.12em;text-transform:uppercase;color:var(--cp-teal);margin-bottom:4px}
.cp-case__steps p{margin:0;font:600 .95rem/1.4 var(--display);color:var(--cp-navy)}

/* related */
.cp-rel__grid{display:grid;grid-template-columns:repeat(3,1fr);gap:12px}
.cp-rel__card{display:grid;grid-template-columns:1fr auto;column-gap:12px;align-items:center;padding:18px 20px;border-radius:16px;border:1px solid var(--cp-line);background:#fff;text-decoration:none;color:var(--cp-navy)}
.cp-rel__card strong{font:700 1rem var(--display)}
.cp-rel__card span{grid-column:1;font-size:.86rem;color:var(--cp-muted)}
.cp-rel__card .rc-ico{grid-row:1/span 2;grid-column:2;color:var(--cp-brand);transition:transform .2s}
.cp-rel__card:hover .rc-ico{transform:translateX(3px)}
.cp-rel__guide{margin-top:24px}
.cp-cta__pts{list-style:none;padding:0;margin:0 0 6px;display:grid;gap:8px}
.cp-cta__pts li{display:flex;align-items:center;gap:10px;color:#E4EAFF;font-weight:600}
.cp-cta__pts .rc-ico{color:#6EE0CE}

/* responsive */
@media (max-width:1100px){
  .cp-prov,.cp-qc{grid-template-columns:1fr 1fr}
  .cp-stats{grid-template-columns:repeat(3,1fr)}
  .cp-stats li:nth-child(4){border-left:0}
  .cp-stats li:nth-child(n+4){border-top:1px solid var(--cp-line)}
  .cp-pan{grid-template-columns:1fr;gap:16px}
  .cp-pan__pipe{display:none}
  .cp-rec{grid-template-columns:repeat(3,1fr);row-gap:28px}
  .cp-rec__line{display:none}
  .cp-wf ol{grid-template-columns:repeat(4,1fr);row-gap:24px}
  .cp-wf__bar{display:none}
  .cp-case__steps{grid-template-columns:1fr 1fr}
  .cp-case__steps li:after{display:none}
}
@media (max-width:900px){
  .cp-hero__in,.cp-cov,.cp-prof,.cp-scorewrap,.cp-rew,.cp-team,.cp-case{grid-template-columns:1fr}
  .cp-why__row{grid-template-columns:1fr}
  .cp-roles,.cp-rel__grid{grid-template-columns:1fr 1fr}
}
@media (max-width:640px){
  .cp-hero h1{font-size:2.6rem}
  .cp-hero .od-hero__ctas .btn{width:100%}
  .cp-eco{padding:12px 8px 14px;border-radius:22px}
  .cp-eco__lbl{font-size:17px}
  .cp-eco__card{display:none}
  .cp-stats{grid-template-columns:1fr 1fr}
  .cp-stats li{border-left:0!important;border-top:1px solid var(--cp-line)}
  .cp-stats li:nth-child(-n+2){border-top:0}
  .cp-stats li:last-child{grid-column:1/-1}
  .cp-why ol{grid-template-columns:1fr;gap:10px}
  .cp-why li:after{display:none}
  .cp-prov,.cp-roles,.cp-rel__grid,.cp-rew__methods,.cp-case__steps{grid-template-columns:1fr}
  .cp-pan__flow{grid-template-columns:1fr;gap:4px;padding:16px}
  .cp-pan__flow li{flex-direction:row;text-align:left;gap:14px}
  .cp-pan__flow li:after{display:none}
  .cp-pan__dot{width:44px;height:44px}
  .cp-pan__n{order:3;margin-left:auto}
  .cp-cov__card{display:none}
  .cp-cov__lbl{font-size:30px}
  .cp-prof__chart{grid-template-columns:1fr;justify-items:center}
  .cp-prof__chart svg{max-width:240px}
  .cp-prof__legend,.cp-prof__panel{display:none}
  .cp-prof__acc{display:grid;gap:8px}
  .cp-prof__acc details{border:1px solid var(--cp-line);border-radius:14px;background:#fff;overflow:hidden}
  .cp-prof__acc summary{display:grid;grid-template-columns:12px 1fr auto;gap:10px;align-items:center;padding:14px 16px;font-weight:700;cursor:pointer;list-style:none}
  .cp-prof__acc summary::-webkit-details-marker{display:none}
  .cp-prof__acc summary i{width:12px;height:12px;border-radius:3px}
  .cp-prof__acc ul{list-style:none;margin:0;padding:0 16px 16px;display:flex;flex-wrap:wrap;gap:6px}
  .cp-prof__acc li{padding:6px 10px;border-radius:8px;background:var(--cp-paper);font-size:.84rem;font-weight:600}
  .cp-qc{grid-template-columns:1fr;gap:8px}
  .cp-qc__head{padding:16px;cursor:pointer}
  .cp-qc__tog{display:block;transition:transform .25s}
  .cp-qc__col.is-open .cp-qc__tog{transform:rotate(45deg)}
  .cp-qc__body{display:none;padding:0 16px 16px}
  .cp-qc__col.is-open .cp-qc__body{display:block;animation:rcPanel .3s ease}
  .cp-rec{grid-template-columns:1fr;gap:0}
  .cp-rec li{display:grid;grid-template-columns:60px 1fr;column-gap:16px;padding-bottom:20px}
  .cp-rec li:not(:last-child):before{content:"";position:absolute;left:29px;top:60px;bottom:0;width:2px;background:#E3E7EF}
  .cp-rec__dot{grid-row:span 3;margin:0}
  .cp-wf ol{grid-template-columns:1fr;gap:0}
  .cp-wf li{display:grid;grid-template-columns:44px 1fr;column-gap:14px;padding-bottom:16px;position:relative}
  .cp-wf li:not(:last-child):before{content:"";position:absolute;left:21px;top:44px;bottom:0;width:2px;background:#ffffff22}
  .cp-wf__n{grid-row:span 2;margin:0}
  .cp-cmp{border:0;background:transparent;display:grid;gap:8px;border-radius:0}
  .cp-cmp__row--h{display:none!important}
  .cp-cmp__row{display:block!important;border:1px solid var(--cp-line);border-radius:14px;background:#fff}
  .cp-cmp__need{width:100%;cursor:pointer;padding:14px 16px}
  .cp-cmp__need:after{content:"+";margin-left:auto;font-weight:700;color:var(--cp-muted)}
  .cp-cmp__row.is-open .cp-cmp__need:after{content:"−"}
  .cp-cmp__row>span{display:none;padding:0 16px 12px 46px}
  .cp-cmp__row.is-open>span{display:block}
  .cp-cmp__row>span:before{content:attr(data-l);display:block;font:700 .68rem var(--body);letter-spacing:.12em;text-transform:uppercase;color:#97A0B5;margin-bottom:2px}
  .cp-mid__in .btn{width:100%}
}
@media (prefers-reduced-motion:reduce){
  .cp *{animation:none!important;transition:none!important}
  .cp-eco__node,.cp-eco__flow li,.cp-why li,.cp-pan__flow li,.cp-cov__mk,.cp-prof__seg,.cp-score__in,.cp-rec li,.cp-wf li{opacity:1!important;transform:none!important}
  .cp-rec__line span,.cp-wf__bar span,.cp-pan__pipe span{transform:none!important}
}

/* ===== Business Panel page (bp-) — slate + gold B2B language ===== */
.bp{--od-navy:#07104F;--od-blue:#1E5BFF;--od-royal:#0B22A8;--od-sky:#E8EEFF;--od-teal:#0E9C88;--od-teal-soft:#E3F5F2;--od-line:#DDE2EC;--od-muted:#525C78;--od-paper:#F5F7FB;
  --bp-slate:#1B2440;--bp-slate-2:#2A3558;--bp-ink:#07104F;--bp-brand:#0B22A8;--bp-gold:#C99A2E;--bp-gold-soft:#F7EFD9;--bp-warm:#F7F5F1;--bp-line:#E2E0DA;--bp-muted:#5B6275}
.bp-sec--slate{background:linear-gradient(165deg,var(--bp-slate),#121A33);color:#fff}
.bp-sec--warm{background:var(--bp-warm)}
.bp .rc-kicker{color:var(--bp-brand)}
.bp .rc-head--light .rc-kicker,.bp .bp-cta .rc-kicker{color:#E7C873}

/* hero */
.bp-hero{background:linear-gradient(180deg,#FBFAF7 0%,#F2F0EA 100%);padding:clamp(32px,4vw,56px) 0 clamp(36px,4vw,52px);border-bottom:1px solid var(--bp-line);overflow:hidden}
.bp-hero__in{display:grid;grid-template-columns:minmax(0,.85fr) minmax(0,1.15fr);gap:clamp(20px,3vw,48px);align-items:center}
.bp-hero__in>*{min-width:0}
.bp-eyebrow{display:inline-block;font:700 .78rem var(--body);letter-spacing:.16em;text-transform:uppercase;color:var(--bp-gold);padding-left:16px;border-left:3px solid var(--bp-gold);margin-bottom:16px}
.bp-hero h1{font-size:clamp(2.6rem,5.4vw,4.4rem);color:var(--bp-slate);margin-bottom:.25em}
.bp-hero__sub{font:600 clamp(1.15rem,1.8vw,1.45rem)/1.4 var(--display);color:var(--bp-ink);max-width:30ch;margin-bottom:14px}
.bp-hero__body{color:var(--bp-muted);font-size:1.05rem;max-width:54ch;margin-bottom:24px}
.bp .bp-btn{background:var(--bp-slate);color:#fff}
.bp .bp-btn:hover{background:var(--bp-brand)}
.bp-hero__link{display:inline-flex;align-items:center;gap:6px;margin-top:18px;font-weight:700;color:var(--bp-slate);text-decoration:none;border-bottom:2px solid var(--bp-gold);padding-bottom:2px}
.bp-net svg{width:100%;height:auto;display:block;overflow:visible}
.bp-net__ring{fill:none;stroke:#D7D3C8;stroke-dasharray:2 6}
.bp-net__ring--in{stroke:#E6E2D8;stroke-dasharray:none}
.bp-net__cross{fill:none;stroke:#C9C3B4;stroke-width:1;opacity:0;transition:opacity 1s;transition-delay:calc(1s + var(--i)*.08s)}
.bp-net.is-in .bp-net__cross{opacity:.55}
.bp-net__spoke{stroke:var(--bp-slate-2);stroke-opacity:.35;stroke-width:1.2;stroke-dasharray:1;stroke-dashoffset:1;transition:stroke-dashoffset .8s ease;transition-delay:calc(var(--i)*.07s)}
.bp-net.is-in .bp-net__spoke{stroke-dashoffset:0}
.bp-net__node{opacity:0;transition:opacity .5s;transition-delay:calc(.3s + var(--i)*.07s)}
.bp-net.is-in .bp-net__node{opacity:1}
.bp-net__dot{fill:#fff;stroke:var(--bp-slate);stroke-width:1.5;transition:fill .25s}
.bp-net__node:hover .bp-net__dot{fill:var(--bp-gold-soft);stroke:var(--bp-gold)}
.bp-net__node foreignObject{color:var(--bp-slate);pointer-events:none}
.bp-net__lbl{font:600 14px var(--body);fill:var(--bp-slate)}
.bp-net__pkt{fill:var(--bp-gold)}
.bp-net__pkt--b{fill:var(--bp-brand)}
.bp-net__core{fill:var(--bp-slate)}
.bp-net__ck{font:800 14px var(--display);letter-spacing:.14em;fill:#fff}
.bp-net__cs{font:600 10.5px var(--body);fill:#E7C873}
.bp-net__flow{list-style:none;margin:4px 0 0;padding:0;display:flex;justify-content:center;flex-wrap:wrap;gap:6px}
.bp-net__flow li{display:flex;align-items:center;gap:6px;font:700 .76rem var(--body);letter-spacing:.08em;text-transform:uppercase;color:var(--bp-slate);padding:7px 12px;border-radius:8px;background:#fff;border:1px solid var(--bp-line)}
.bp-net__flow li:not(:last-child):after{content:"→";color:var(--bp-gold);margin-left:6px}
.bp-net__flow li:last-child{background:var(--bp-slate);color:#fff;border-color:var(--bp-slate)}
.bp-stats{list-style:none;margin:clamp(24px,3vw,40px) 0 0;padding:0;display:grid;grid-template-columns:repeat(4,1fr);border-top:2px solid var(--bp-slate)}
.bp-stats li{padding:20px 22px 4px;display:flex;flex-direction:column;gap:4px}
.bp-stats li+li{border-left:1px solid var(--bp-line)}
.bp-stats .od-count{font-size:clamp(1.8rem,3vw,2.5rem);color:var(--bp-slate)}
.bp-stats li:first-child .od-count{color:var(--bp-brand)}
.bp-stats__w{font-size:clamp(1.3rem,2.2vw,1.7rem)!important}
.bp-stats span:last-child{font-size:.88rem;color:var(--bp-muted)}

/* problem */
.bp-ps{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:clamp(28px,5vw,72px);align-items:center}
.bp-ps>*{min-width:0}
.bp-need{list-style:none;margin:16px 0 0;padding:0;display:flex;flex-wrap:wrap;gap:8px}
.bp-need li{padding:7px 12px;border-radius:8px;background:var(--bp-warm);border:1px solid var(--bp-line);font-weight:600;font-size:.88rem;color:var(--bp-slate)}
.bp-prob__cascade{list-style:none;margin:0;padding:0;display:grid;gap:6px;justify-items:center}
.bp-prob__cascade li{width:var(--w);display:flex;align-items:center;justify-content:center;gap:10px;padding:12px;border-radius:10px;background:#F6E9EA;color:#7A2E36;font:600 .95rem var(--display);opacity:0;transform:translateY(-6px);transition:all .45s;transition-delay:calc(var(--i)*.15s)}
.bp-prob__cascade li span{font:700 .7rem var(--body);opacity:.6}
.bp-prob__cascade li:last-child{background:#B4424B;color:#fff}
.bp-prob.is-in .bp-prob__cascade li{opacity:1;transform:none}
.bp-prob__turn{display:flex;align-items:center;justify-content:center;gap:8px;margin:14px 0;font:700 .76rem var(--body);letter-spacing:.14em;text-transform:uppercase;color:var(--bp-gold)}
.bp-prob__fix{display:grid;grid-template-columns:auto 1fr;column-gap:14px;align-items:center;padding:18px 22px;border-radius:14px;background:var(--bp-slate);color:#fff;opacity:0;transition:opacity .6s 1s}
.bp-prob.is-in .bp-prob__fix{opacity:1}
.bp-prob__fix .rc-ico{grid-row:span 2;color:#E7C873}
.bp-prob__fix strong{font:700 1.05rem var(--display)}
.bp-prob__fix span{font-size:.88rem;color:#C7CCDB}

/* solution bullseye */
.bp-sol{display:grid;grid-template-columns:minmax(0,.9fr) minmax(0,1.1fr);gap:clamp(24px,4vw,60px);align-items:center}
.bp-sol>*{min-width:0}
.bp-sol__eye{width:100%;max-width:420px;margin:auto;display:block}
.bp-sol__ring{fill:#ffffff08;stroke:#ffffff26;stroke-width:1.5;cursor:pointer;transition:fill .3s,stroke .3s}
.bp-sol__ring.is-on{fill:#C99A2E2e;stroke:#E7C873}
.bp-sol__t{font:800 11px var(--display);letter-spacing:.16em;fill:#A9B2C9;pointer-events:none}
.bp-sol__t.is-on{fill:#fff}
.bp-sol__dot{fill:#E7C873}
.bp-sol__list{list-style:none;margin:0;padding:0;display:grid;gap:8px}
.bp-sol__list button{width:100%;display:grid;grid-template-columns:40px 110px 1fr;align-items:center;gap:12px;text-align:left;padding:14px 18px;border-radius:12px;border:1px solid #ffffff1f;background:transparent;color:#fff;transition:background .25s,border-color .25s}
.bp-sol__list li.is-on button{background:#ffffff10;border-color:#E7C873}
.bp-sol__n{font:800 .8rem var(--display);color:#E7C873}
.bp-sol__list strong{font:700 1.05rem var(--display)}
.bp-sol__q{font-size:.92rem;color:#C7CCDB}

/* who */
.bp-who__tabs{display:inline-flex;padding:4px;border-radius:12px;background:var(--bp-warm);border:1px solid var(--bp-line);margin-bottom:20px}
.bp-who__tabs button{display:flex;align-items:center;gap:8px;border:0;background:transparent;padding:10px 18px;border-radius:9px;font-weight:700;color:var(--bp-muted)}
.bp-who__tabs button b{font:700 .72rem var(--body);padding:2px 7px;border-radius:999px;background:#fff;color:var(--bp-slate)}
.bp-who__tabs button.is-on{background:var(--bp-slate);color:#fff}
.bp-who__grid{display:grid;grid-template-columns:repeat(4,1fr);gap:12px}
.bp-who__card{position:relative;padding:20px;border-radius:14px;background:#fff;border:1px solid var(--bp-line);outline:none;overflow:hidden;animation:rcPanel .4s ease both;animation-delay:calc(var(--i)*40ms);transition:transform .3s,box-shadow .3s,border-color .3s}
.bp-who__card:before{content:"";position:absolute;left:0;top:0;height:3px;width:100%;background:var(--bp-gold);transform:scaleX(0);transform-origin:left;transition:transform .35s}
.bp-who__card:is(:hover,:focus-visible){transform:translateY(-3px);box-shadow:0 18px 36px -26px #1B2440;border-color:#D8CFB8}
.bp-who__card:is(:hover,:focus-visible):before{transform:scaleX(1)}
.bp-who__ic{width:40px;height:40px;border-radius:10px;display:grid;place-items:center;background:var(--bp-warm);color:var(--bp-slate);margin-bottom:12px;transition:transform .3s,background .3s,color .3s}
.bp-who__card:is(:hover,:focus-visible) .bp-who__ic{transform:rotate(-6deg) scale(1.08);background:var(--bp-gold-soft);color:#8A6714}
.bp-who__card strong{display:block;font:700 1rem var(--display);color:var(--bp-slate)}
.bp-who__card p{margin:6px 0 0;font-size:.86rem;color:var(--bp-muted);max-height:0;opacity:0;overflow:hidden;transition:max-height .35s,opacity .3s}
.bp-who__card:is(:hover,:focus-visible) p{max-height:80px;opacity:1}
.bp-who__note{font-size:.82rem;color:var(--bp-muted);margin:14px 0 0}

/* builder */
.bp-build{display:grid;grid-template-columns:minmax(0,1.4fr) minmax(0,.6fr);gap:20px;align-items:start}
.bp-build>*{min-width:0}
.bp-build__grid{display:grid;grid-template-columns:repeat(3,1fr);gap:10px}
.bp-attr{position:relative;display:grid;grid-template-columns:36px 1fr;column-gap:12px;align-items:center;text-align:left;padding:14px 16px;border-radius:12px;border:1px solid var(--bp-line);background:#fff;color:var(--bp-slate);transition:border-color .2s,box-shadow .2s,background .2s}
.bp-attr:hover{border-color:var(--bp-slate-2);box-shadow:0 12px 24px -20px #1B2440}
.bp-attr__ic{grid-row:span 2;width:36px;height:36px;border-radius:9px;display:grid;place-items:center;background:var(--bp-warm)}
.bp-attr__t{font:700 .95rem var(--display)}
.bp-attr__d{font-size:.78rem;color:var(--bp-muted)}
.bp-attr__tick{position:absolute;top:10px;right:10px;width:20px;height:20px;border-radius:6px;display:grid;place-items:center;border:1px solid var(--bp-line);color:var(--bp-muted)}
.bp-attr.is-on{border-color:var(--bp-slate);background:#FBFAF7;box-shadow:inset 0 0 0 1px var(--bp-slate)}
.bp-attr.is-on .bp-attr__ic{background:var(--bp-slate);color:#fff}
.bp-attr.is-on .bp-attr__tick{background:var(--bp-gold);border-color:var(--bp-gold);color:#fff}
.bp-build__out{position:sticky;top:calc(var(--header-h) + 70px);padding:22px;border-radius:16px;background:var(--bp-slate);color:#fff}
.bp-build__k{font:700 .72rem var(--body);letter-spacing:.14em;text-transform:uppercase;color:#E7C873}
.bp-build__out p{margin:10px 0 12px;color:#DDE2EE}
.bp-build__out p strong{color:#fff}
.bp-build__chips{display:flex;flex-wrap:wrap;gap:6px;margin-bottom:16px}
.bp-build__chips span{display:inline-flex;align-items:center;gap:6px;padding:5px 6px 5px 10px;border-radius:999px;background:#ffffff14;font-size:.8rem;font-weight:600}
.bp-build__chips button{width:18px;height:18px;border-radius:50%;border:0;background:#ffffff22;color:#fff;display:grid;place-items:center;padding:0}
.bp .bp-build__cta{background:var(--bp-gold);color:var(--bp-slate);width:100%;white-space:normal;text-align:center}
.bp-build__fine{display:block;margin-top:10px;font-size:.74rem;color:#A9B2C9}
.bp-mxwrap{margin-top:clamp(36px,5vw,56px)}
.bp-mxwrap h3{font-size:1.3rem;margin-bottom:14px}
.bp-mx{display:grid;grid-template-columns:repeat(3,1fr);border-radius:16px;overflow:hidden;border:1px solid var(--bp-line);background:#fff}
.bp-mx__col+.bp-mx__col{border-left:1px solid var(--bp-line)}
.bp-mx__h{display:flex;align-items:center;gap:8px;padding:14px 18px;font:800 .82rem var(--display);letter-spacing:.14em;background:var(--bp-slate);color:#fff}
.bp-mx__col1 .bp-mx__h{background:var(--bp-slate-2)}
.bp-mx__col2 .bp-mx__h{background:#3A4670}
.bp-mx__cell{padding:13px 18px;border-top:1px solid var(--bp-line);font-weight:600;color:var(--bp-slate);transition:background .2s,color .2s,padding .2s}
.bp-mx__cell.is-row{background:var(--bp-gold-soft);padding-left:24px}
.bp-mx__line{margin:14px 0 0;font:600 1rem var(--display);color:var(--bp-slate)}

/* spectrum + dims + decision */
.bp-spec__row{display:grid;grid-template-columns:repeat(5,1fr);gap:12px;align-items:end}
.bp-spec__item{display:flex;flex-direction:column;align-items:center;text-align:center;gap:8px}
.bp-spec__item svg{width:80px;height:90px}
.bp-spec__b{fill:var(--bp-slate-2);transform-box:fill-box;transform-origin:bottom;transform:scaleY(0);transition:transform .6s cubic-bezier(.2,.7,.2,1);transition-delay:calc(var(--i)*.15s + var(--k)*.04s)}
.bp-spec__item:last-child .bp-spec__b{fill:var(--bp-gold)}
.bp-spec.is-in .bp-spec__b{transform:scaleY(1)}
.bp-spec__item strong{font:700 .92rem var(--display);color:var(--bp-slate)}
.bp-spec__axis{display:flex;justify-content:space-between;margin-top:14px;padding-top:10px;border-top:2px solid var(--bp-slate);font-size:.78rem;font-weight:700;letter-spacing:.08em;text-transform:uppercase;color:var(--bp-muted);position:relative}
.bp-spec__axis:after{content:"";position:absolute;right:-2px;top:-7px;border:6px solid transparent;border-left-color:var(--bp-slate);border-right:0}
.bp-spec__note{font-size:.8rem;color:var(--bp-muted);margin:8px 0 0}
.bp-dims{list-style:none;margin:22px 0 0;padding:0;display:flex;flex-wrap:wrap;gap:8px}
.bp-dims li{display:inline-flex;align-items:center;gap:8px;padding:9px 14px;border-radius:10px;background:var(--bp-warm);border:1px solid var(--bp-line);font-weight:600;font-size:.88rem;color:var(--bp-slate)}
.bp-decwrap{margin-top:clamp(48px,6vw,80px);display:grid;grid-template-columns:minmax(0,.7fr) minmax(0,1.3fr);gap:clamp(24px,4vw,56px);align-items:center}
.bp-decwrap>*{min-width:0}
.bp-dec{display:flex;flex-direction:column;align-items:center}
.bp-dec__top{display:inline-flex;align-items:center;gap:8px;padding:12px 22px;border-radius:12px;background:var(--bp-slate);color:#fff;font:700 1rem var(--display)}
.bp-dec__top .rc-ico{color:#E7C873}
.bp-dec__lines{width:72%;height:44px}
.bp-dec__lines path{fill:none;stroke:var(--bp-slate-2);stroke-width:2;vector-effect:non-scaling-stroke}
.bp-dec__cols{display:grid;grid-template-columns:repeat(3,1fr);gap:12px;width:100%}
.bp-dec__col{display:flex;flex-direction:column;align-items:center;opacity:0;transform:translateY(8px);transition:all .5s;transition-delay:calc(var(--i)*.15s)}
.bp-dec.is-in .bp-dec__col{opacity:1;transform:none}
.bp-dec__role{display:flex;align-items:center;gap:8px;padding:10px 14px;border-radius:10px;background:var(--bp-gold-soft);color:#7A5A10;font:700 .92rem var(--display)}
.bp-dec__arrow{width:2px;height:22px;background:var(--bp-line);position:relative}
.bp-dec__arrow:after{content:"";position:absolute;bottom:-4px;left:-4px;border:5px solid transparent;border-top-color:#C9C3B4;border-bottom:0}
.bp-dec__who{display:flex;flex-direction:column;align-items:center;text-align:center;gap:4px;padding:16px;border-radius:12px;border:1px solid var(--bp-line);background:#fff;width:100%}
.bp-dec__who .rc-ico{color:var(--bp-slate)}
.bp-dec__who strong{font:700 1rem var(--display);color:var(--bp-slate)}
.bp-dec__who span{font-size:.82rem;color:var(--bp-muted)}

/* use cases: border-animation hover, varied accents */
.bp-use{display:grid;grid-template-columns:repeat(4,1fr);gap:12px}
.bp-use__card{position:relative;padding:22px;border-radius:14px;background:#fff;border:1px solid var(--bp-line);transition:transform .3s,box-shadow .3s;--acc:var(--bp-brand)}
.bp-use__card1{--acc:#0E9C88}.bp-use__card2{--acc:var(--bp-gold)}.bp-use__card3{--acc:#5A3FE0}
.bp-use__card:after{content:"";position:absolute;inset:-1px;border-radius:inherit;border:2px solid var(--acc);clip-path:inset(0 100% 100% 0);transition:clip-path .5s ease;pointer-events:none}
.bp-use__card:hover{transform:translateY(-3px);box-shadow:0 18px 36px -28px #1B2440}
.bp-use__card:hover:after{clip-path:inset(0 0 0 0)}
.bp-use__card>.rc-ico{color:var(--acc);margin-bottom:12px;transition:transform .3s}
.bp-use__card:hover>.rc-ico{transform:translateX(3px)}
.bp-use__card h3{font-size:1.02rem;color:var(--bp-slate)}
.bp-use__card p{margin:0;font-size:.88rem;color:var(--bp-muted)}

/* process spine */
.bp-proc{list-style:none;margin:0 auto;padding:0;max-width:880px;position:relative;display:grid;gap:14px}
.bp-proc__spine{position:absolute;left:50%;top:0;bottom:0;width:3px;margin-left:-1.5px;background:var(--bp-line);border-radius:2px}
.bp-proc__spine span{display:block;width:100%;height:calc(var(--p)*100%);background:linear-gradient(var(--bp-brand),var(--bp-gold));border-radius:2px}
.bp-proc li{display:grid;grid-template-columns:1fr 56px 1fr;align-items:center;position:relative}
.bp-proc__dot{grid-column:2;justify-self:center;width:46px;height:46px;border-radius:50%;display:grid;place-items:center;background:#fff;border:2px solid var(--bp-line);color:var(--bp-muted);z-index:1;transition:all .4s}
.bp-proc li.is-on .bp-proc__dot{background:var(--bp-slate);border-color:var(--bp-slate);color:#fff}
.bp-proc li:last-child.is-on .bp-proc__dot{background:var(--bp-gold);border-color:var(--bp-gold)}
.bp-proc__card{padding:16px 20px;border-radius:14px;background:#fff;border:1px solid var(--bp-line);opacity:.35;transform:translateX(var(--dx,0));transition:opacity .5s,transform .5s,box-shadow .3s}
.bp-proc li.is-l .bp-proc__card{grid-column:1;grid-row:1;text-align:right;--dx:-14px}
.bp-proc li.is-r .bp-proc__card{grid-column:3;--dx:14px}
.bp-proc li.is-on .bp-proc__card{opacity:1;transform:none;box-shadow:0 16px 30px -26px #1B2440}
.bp-proc__n{font:800 .74rem var(--display);color:var(--bp-gold);letter-spacing:.1em}
.bp-proc__card strong{display:block;font:700 1.1rem var(--display);color:var(--bp-slate)}
.bp-proc__card p{margin:2px 0 0;font-size:.9rem;color:var(--bp-muted)}

/* quality gates */
.bp-qc{display:grid;grid-template-columns:repeat(3,1fr) auto;gap:14px;align-items:stretch;position:relative}
.bp-qc__pipe{position:absolute;left:0;right:0;top:50%;height:2px;background:#ffffff1a}
.bp-qc__pipe span{display:block;height:100%;background:linear-gradient(90deg,#5F86FF,#E7C873);transform-origin:left;transform:scaleX(0);transition:transform 1.6s}
.bp-qc.is-in .bp-qc__pipe span{transform:scaleX(1)}
.bp-qc__gate{position:relative;padding:20px;border-radius:16px;background:#141C36;border:1px solid #ffffff1f;border-top:3px solid var(--c);opacity:0;transform:translateY(10px);transition:all .5s;transition-delay:calc(var(--i)*.2s)}
.bp-qc.is-in .bp-qc__gate{opacity:1;transform:none}
.bp-qc__gate:hover{border-color:var(--c);box-shadow:0 0 0 1px var(--c),0 20px 40px -30px #000}
.bp-qc__head{display:flex;align-items:center;gap:12px;margin-bottom:14px}
.bp-qc__ic{width:44px;height:44px;border-radius:12px;display:grid;place-items:center;background:var(--c);color:#fff}
.bp-qc__head small{display:block;font:700 .7rem var(--body);letter-spacing:.14em;text-transform:uppercase;color:#A9B2C9}
.bp-qc__head strong{font:700 1.05rem var(--display)}
.bp-qc__gate ul{list-style:none;margin:0;padding:0;display:grid;gap:6px}
.bp-qc__gate li{display:flex;align-items:center;gap:10px;padding:8px 10px;border-radius:8px;background:#ffffff0a;font-size:.88rem;color:#DDE2EE}
.bp-qc__gate li .rc-ico{color:#9DB6FF}
.bp-qc__out{position:relative;align-self:center;display:flex;flex-direction:column;align-items:center;gap:8px;max-width:150px;text-align:center;padding:18px 14px;border-radius:16px;background:#0E9C88;font:700 .9rem/1.3 var(--display)}

/* coverage */
.bp-cov{display:grid;grid-template-columns:minmax(0,1.35fr) minmax(0,.65fr);gap:clamp(24px,4vw,56px);align-items:center}
.bp-cov>*{min-width:0}
.bp-cov__map{background:#fff;border:1px solid var(--bp-line);border-radius:20px;padding:clamp(14px,2.5vw,26px)}
.bp-cov__map svg{width:100%;height:auto;display:block;overflow:visible}
.bp-cov__arc{fill:none;stroke:var(--bp-slate-2);stroke-width:1.5;stroke-dasharray:1;stroke-dashoffset:1;opacity:.6;transition:stroke-dashoffset 1.2s ease;transition-delay:calc(.5s + var(--i)*.12s)}
.bp-cov.is-in .bp-cov__arc{stroke-dashoffset:0}
.bp-cov__hub{opacity:0;transition:opacity .5s;transition-delay:calc(var(--i)*.1s)}
.bp-cov.is-in .bp-cov__hub{opacity:1}
.bp-cov__glow{fill:var(--bp-gold);opacity:.16;transform-box:fill-box;transform-origin:center;animation:odHalo 4s ease-in-out infinite}
.bp-cov__case{fill:var(--bp-slate)}
.bp-cov__handle{fill:none;stroke:var(--bp-slate);stroke-width:2}
.bp-cov__stat .od-count{font-size:clamp(3.4rem,7vw,5.4rem);color:var(--bp-slate);display:block}
.bp-cov__stat>span{font:700 1.1rem var(--display);color:var(--bp-gold)}
.bp-cov__stat p{color:var(--bp-muted);margin-top:12px}

/* feasibility */
.bp-feas{background:linear-gradient(110deg,var(--bp-brand),#13238F 60%,var(--bp-slate));color:#fff;padding:clamp(40px,5vw,64px) 0}
.bp-feas__in{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:clamp(24px,4vw,56px);align-items:center}
.bp-feas__in>*{min-width:0}
.bp-feas h2{color:#fff}
.bp-feas p{color:#DCE4FF}
.bp-feas__fun{list-style:none;margin:0;padding:0;display:grid;gap:6px;justify-items:center}
.bp-feas__fun li{width:calc(100% - var(--i)*12%);padding:12px;border-radius:10px;text-align:center;background:#ffffff14;border:1px solid #ffffff26;font:700 .95rem var(--display)}
.bp-feas__fun li:last-child{background:var(--bp-gold);border-color:var(--bp-gold);color:var(--bp-slate)}

/* industries: industry-specific accent on hover */
.bp-ind__item{--acc:var(--bp-brand)}
.bp-ind__item1{--acc:#0E9C88}.bp-ind__item2{--acc:#C99A2E}.bp-ind__item3{--acc:#5A3FE0}.bp-ind__item4{--acc:#C2603F}.bp-ind__item5{--acc:#2F855A}
.bp .bp-ind__item:hover{border-color:var(--acc)!important;box-shadow:inset 3px 0 0 var(--acc),0 12px 24px -20px #1B2440}
.bp .bp-ind__item:hover svg{color:var(--acc)}
.bp-ind .rc-ind__more{text-decoration:none;display:grid;place-items:center}

/* why + tech */
.bp-why{display:grid;grid-template-columns:minmax(0,1.1fr) minmax(0,.9fr);gap:clamp(28px,5vw,72px);align-items:start}
.bp-why>*{min-width:0}
.bp-why__list{list-style:none;margin:0;padding:0;display:grid;grid-template-columns:1fr 1fr;gap:0}
.bp-why__list li{display:flex;gap:14px;padding:18px 0;border-top:1px solid var(--bp-line)}
.bp-why__list li:nth-child(odd){padding-right:18px}
.bp-why__list span{font:800 1.6rem/1 var(--display);color:var(--bp-gold)}
.bp-why__list strong{display:block;font:700 1rem var(--display);color:var(--bp-slate)}
.bp-why__list p{margin:4px 0 0;font-size:.88rem;color:var(--bp-muted)}
.bp-tech{position:relative;display:grid;place-items:center;padding:20px 0}
.bp-tech__hub{position:relative;z-index:1;width:200px;height:200px;border-radius:50%;display:flex;flex-direction:column;align-items:center;justify-content:center;text-align:center;gap:4px;padding:20px;background:var(--bp-slate);color:#fff;text-decoration:none;box-shadow:0 0 0 12px #fff,0 0 0 13px var(--bp-line),0 0 0 40px var(--bp-warm)}
.bp-tech__hub strong{font:800 1.3rem var(--display)}
.bp-tech__hub span{font-size:.76rem;color:#E7C873}
.bp-tech__ring{list-style:none;margin:28px 0 0;padding:0;display:flex;flex-wrap:wrap;justify-content:center;gap:8px}
.bp-tech__ring li{padding:8px 14px;border-radius:999px;background:#fff;border:1px solid var(--bp-line);font-weight:700;font-size:.86rem;color:#5A3FE0;transition:transform .2s,border-color .2s}
.bp-tech__ring li:hover{transform:translateY(-2px);border-color:#5A3FE0}

/* workflow + team */
.bp-flow{list-style:none;margin:0;padding:0;display:flex;flex-wrap:wrap;gap:8px;align-items:center}
.bp-flow li{display:inline-flex;align-items:center;gap:10px;padding:10px 14px 10px 10px;border-radius:12px;background:#fff;border:1px solid var(--bp-line);font:600 .92rem var(--display);color:var(--bp-slate)}
.bp-flow li span{width:32px;height:32px;border-radius:8px;display:grid;place-items:center;background:var(--bp-warm);color:var(--bp-slate)}
.bp-flow li:not(:last-child):after{content:"→";margin-left:4px;color:var(--bp-gold)}
.bp-flow li:last-child{background:var(--bp-slate);color:#fff;border-color:var(--bp-slate)}
.bp-flow li:last-child span{background:#0E9C88;color:#fff}
.bp-team{margin-top:clamp(36px,5vw,56px);display:grid;grid-template-columns:minmax(0,.6fr) minmax(0,1.4fr);gap:24px;align-items:center;padding:24px;border-radius:18px;background:var(--bp-warm);border:1px solid var(--bp-line)}
.bp-team h3{color:var(--bp-slate)}
.bp-team ul{list-style:none;margin:0;padding:0;display:grid;grid-template-columns:repeat(3,1fr);gap:8px}
.bp-team li{display:flex;align-items:center;gap:10px;padding:12px;border-radius:10px;background:#fff;border:1px solid var(--bp-line);font:600 .88rem/1.25 var(--display);color:var(--bp-slate)}
.bp-team li .rc-ico{color:var(--bp-gold);flex:none}

/* proof */
.bp-proof{display:grid;grid-template-columns:repeat(4,1fr);gap:0;border-top:1px solid #ffffff26}
.bp-proof div{padding:22px 20px 6px;display:flex;flex-direction:column;gap:6px}
.bp-proof div+div{border-left:1px solid #ffffff1a}
.bp-proof strong{font:800 clamp(2rem,3.4vw,2.8rem)/1 var(--display);color:#E7C873}
.bp-proof span{color:#C7CCDB;font-size:.92rem}
.bp-proof__more{margin:20px 0 0;color:#C7CCDB}
.bp-proof__more a{color:#fff;font-weight:700}

/* final cta */
.bp-cta{background:radial-gradient(700px 400px at 0% 0%,#2A3558 0%,transparent 70%),var(--bp-slate)!important}
.bp-micro{margin:18px 0;padding:16px 18px;border-radius:12px;border-left:3px solid #E7C873;background:#ffffff0d}
.bp-micro strong{display:block;font:700 1rem var(--display)}
.bp-micro span{font-size:.92rem;color:#C7CCDB}
.bp-cta__link{display:inline-flex;align-items:center;gap:6px;margin-top:16px;color:#E7C873;font-weight:700;text-decoration:none}
.bp-cta__fine{margin:10px 0 0;font-size:.86rem;color:#A9B2C9!important}

/* responsive */
@media (max-width:1100px){
  .bp-who__grid,.bp-use{grid-template-columns:repeat(3,1fr)}
  .bp-build{grid-template-columns:1fr}
  .bp-build__out{position:static}
  .bp-qc{grid-template-columns:1fr 1fr}
  .bp-qc__pipe{display:none}
  .bp-qc__out{max-width:none;flex-direction:row;justify-content:center}
}
@media (max-width:900px){
  .bp-hero__in,.bp-ps,.bp-sol,.bp-decwrap,.bp-cov,.bp-feas__in,.bp-why,.bp-team{grid-template-columns:1fr}
  .bp-stats{grid-template-columns:1fr 1fr}
  .bp-stats li:nth-child(3){border-left:0}
  .bp-build__grid{grid-template-columns:1fr 1fr}
  .bp-proof{grid-template-columns:1fr 1fr}
  .bp-proof div:nth-child(3){border-left:0}
}
@media (max-width:640px){
  .bp-hero h1{font-size:2.6rem}
  .bp-hero .od-hero__ctas .btn,.bp-feas .btn,.bp-cta .od-hero__ctas .btn{width:100%}
  .bp-net__lbl{font-size:19px}
  .bp-who__grid,.bp-use,.bp-build__grid,.bp-qc,.bp-why__list,.bp-team ul{grid-template-columns:1fr}
  .bp-who__card p{max-height:none;opacity:1}
  .bp-who__tabs{display:flex}
  .bp-who__tabs button{flex:1;justify-content:center}
  .bp-sol__list button{grid-template-columns:32px 1fr;row-gap:2px}
  .bp-sol__q{grid-column:2}
  .bp-mx{grid-template-columns:1fr}
  .bp-mx__col+.bp-mx__col{border-left:0}
  .bp-spec__row{grid-template-columns:1fr;gap:6px}
  .bp-spec__item{flex-direction:row;gap:14px;text-align:left}
  .bp-spec__item svg{width:56px;height:62px}
  .bp-spec__axis{display:none}
  .bp-dec__cols{grid-template-columns:1fr;gap:16px}
  .bp-dec__lines{display:none}
  .bp-dec__top{margin-bottom:12px}
  .bp-proc__spine{left:23px}
  .bp-proc li{grid-template-columns:46px 1fr;column-gap:14px}
  .bp-proc__dot{grid-column:1}
  .bp-proc li.is-l .bp-proc__card,.bp-proc li.is-r .bp-proc__card{grid-column:2;grid-row:1;text-align:left;--dx:10px}
  .bp-why__list li:nth-child(odd){padding-right:0}
  .bp-proof{grid-template-columns:1fr 1fr}
  .bp-flow li{width:100%}
  .bp-flow li:after{display:none}
}
@media (prefers-reduced-motion:reduce){
  .bp *{animation:none!important;transition:none!important}
  .bp-net__node,.bp-net__cross,.bp-prob__cascade li,.bp-prob__fix,.bp-dec__col,.bp-qc__gate,.bp-cov__hub,.bp-proc__card{opacity:1!important;transform:none!important}
  .bp-net__spoke,.bp-cov__arc{stroke-dashoffset:0!important}
  .bp-spec__b,.bp-qc__pipe span{transform:none!important}
  .bp-who__card p{max-height:none;opacity:1}
}

/* ===== Healthcare Panel page (hp-) — navy + muted teal + soft cyan ===== */
.hpg{--od-navy:#07104F;--od-blue:#1E5BFF;--od-royal:#0B22A8;--od-sky:#E8EEFF;--od-teal:#0E9C88;--od-teal-soft:#E3F5F2;--od-line:#DDE2EC;--od-muted:#525C78;--od-paper:#F5F7FB;
  --hp-navy:#0A1A4A;--hp-teal:#0E8A8A;--hp-teal-2:#12A3A3;--hp-cyan:#E2F4F6;--hp-mint:#F1F8F7;--hp-green:#2F855A;--hp-line:#D9E4E6;--hp-muted:#4F5D73;--hp-blue:#0B22A8}
.hpg .rc-kicker{color:var(--hp-teal)}
.hpg .rc-head--light .rc-kicker{color:#7FE0DA}
.hp-sec--mint{background:var(--hp-mint)}
.hp-sec--soft{background:#F7FAFB}
.hp-sec--navy{background:linear-gradient(165deg,var(--hp-navy),#081438);color:#fff}
.hp-sec--dark{background:#06122F;color:#fff}
.hp-note{font-size:.84rem;color:var(--hp-muted);margin:14px 0 0}
.hp-note a{color:var(--hp-teal);font-weight:600}
.hp-lead{font:500 clamp(1.08rem,1.5vw,1.25rem)/1.55 var(--display);color:var(--hp-navy)}

/* hero */
.hp-hero{background:radial-gradient(700px 420px at 85% 30%,#DDF3F4 0%,transparent 65%),linear-gradient(180deg,#fff,#F4FAFA);padding:clamp(32px,4vw,56px) 0 clamp(32px,4vw,48px);border-bottom:1px solid var(--hp-line);overflow:hidden}
.hp-hero__in{display:grid;grid-template-columns:minmax(0,.95fr) minmax(0,1.05fr);gap:clamp(24px,4vw,56px);align-items:center}
.hp-hero__in>*{min-width:0}
.hp-eyebrow{display:inline-flex;align-items:center;gap:8px;font:700 .78rem var(--body);letter-spacing:.14em;text-transform:uppercase;color:var(--hp-teal);margin-bottom:16px;padding:6px 12px;border-radius:999px;background:var(--hp-cyan)}
.hp-hero h1{font-size:clamp(2.6rem,5.4vw,4.4rem);color:var(--hp-navy);margin-bottom:.25em}
.hp-hero__sub{font:600 clamp(1.15rem,1.8vw,1.45rem)/1.4 var(--display);color:var(--hp-teal);max-width:30ch;margin-bottom:14px}
.hp-hero__body{color:var(--hp-muted);font-size:1.05rem;max-width:54ch;margin-bottom:24px}
.hpg .hp-btn{background:var(--hp-navy);color:#fff}
.hpg .hp-btn:hover{background:var(--hp-teal)}
.hp-stack{position:relative;min-height:420px;padding:20px 0 0}
.hp-stack__ecg{position:absolute;left:0;right:0;top:46%;width:100%;height:110px;opacity:.5}
.hp-stack__ecg path{fill:none;stroke:var(--hp-teal-2);stroke-width:2;stroke-dasharray:1400;stroke-dashoffset:1400;animation:hpEcg 4.5s ease-in-out infinite}
@keyframes hpEcg{0%{stroke-dashoffset:1400}60%,100%{stroke-dashoffset:0}}
.hp-card{position:relative;z-index:1;display:grid;grid-template-columns:42px 1fr auto;gap:12px;align-items:center;width:min(380px,92%);padding:14px 16px;margin-bottom:-6px;border-radius:16px;background:#fff;border:1px solid var(--hp-line);box-shadow:0 18px 40px -28px rgba(10,26,74,.5);opacity:0;animation:hpCard .7s cubic-bezier(.2,.7,.2,1) forwards;animation-delay:calc(.15s + var(--i)*.12s);margin-left:calc(var(--i)*7%)}
.hp-card:nth-child(odd){margin-left:calc(4% + var(--i)*5%)}
@keyframes hpCard{from{opacity:0;transform:translateX(24px)}to{opacity:1;transform:none}}
.hp-card__av{width:42px;height:42px;border-radius:12px;display:grid;place-items:center;background:var(--hp-cyan);color:var(--hp-teal)}
.hp-card--3 .hp-card__av,.hp-card--4 .hp-card__av{background:#EAF6EF;color:var(--hp-green)}
.hp-card strong{display:block;font:700 .98rem var(--display);color:var(--hp-navy)}
.hp-card div span{font-size:.8rem;color:var(--hp-muted)}
.hp-card__v{display:inline-flex;align-items:center;gap:4px;padding:4px 8px;border-radius:999px;background:#EAF6EF;color:var(--hp-green);font:700 .68rem var(--body);white-space:nowrap}
.hp-tags{position:absolute;right:0;top:8px;display:flex;flex-direction:column;align-items:flex-end;gap:8px;z-index:2}
.hp-tags span{padding:6px 12px;border-radius:999px;background:var(--hp-navy);color:#fff;font:600 .74rem var(--body);opacity:0;animation:rcFade .5s ease forwards,odFloat 7s ease-in-out infinite;animation-delay:calc(.9s + var(--i)*.15s),calc(var(--i)*-1.5s)}
.hp-tags span:nth-child(even){background:var(--hp-teal)}
.hp-stack__lbl{display:block;margin:18px 0 6px;font:700 .66rem var(--body);letter-spacing:.14em;text-transform:uppercase;color:#97A3B5}
.hp-stack__flow{list-style:none;margin:0;padding:0;display:flex;flex-wrap:wrap;gap:6px}
.hp-stack__flow li{padding:7px 12px;border-radius:999px;background:#fff;border:1px solid var(--hp-line);font:700 .78rem var(--body);color:var(--hp-navy)}
.hp-stack__flow li:not(:last-child):after{content:" →";color:var(--hp-teal)}
.hp-stack__flow li:last-child{background:var(--hp-teal);color:#fff;border-color:var(--hp-teal)}
.hp-trust{list-style:none;margin:clamp(24px,3vw,40px) 0 0;padding:0;display:grid;grid-template-columns:repeat(4,1fr);gap:10px}
.hp-trust li{display:flex;gap:12px;padding:16px;border-radius:16px;background:#fff;border:1px solid var(--hp-line)}
.hp-trust li>span{flex:none;width:40px;height:40px;border-radius:12px;display:grid;place-items:center;background:var(--hp-cyan);color:var(--hp-teal)}
.hp-trust strong{font:700 .95rem var(--display);color:var(--hp-navy)}
.hp-trust p{margin:2px 0 0;font-size:.82rem;color:var(--hp-muted);line-height:1.45}

/* challenge */
.hp-chwrap{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:clamp(28px,5vw,72px);align-items:center}
.hp-chwrap>*{min-width:0}
.hp-ch{list-style:none;margin:0;padding:0;position:relative}
.hp-ch:before{content:"";position:absolute;left:21px;top:22px;bottom:22px;width:2px;background:linear-gradient(var(--hp-teal),var(--hp-green));transform-origin:top;transform:scaleY(0);transition:transform 1.8s ease}
.hp-ch.is-in:before{transform:scaleY(1)}
.hp-ch li{display:flex;align-items:center;gap:16px;padding:8px 0;position:relative;opacity:.25;transition:opacity .5s;transition-delay:calc(var(--i)*.22s)}
.hp-ch.is-in li{opacity:1}
.hp-ch__dot{flex:none;width:44px;height:44px;border-radius:50%;display:grid;place-items:center;background:#fff;border:2px solid var(--hp-teal);color:var(--hp-teal);position:relative;z-index:1}
.hp-ch li:last-child .hp-ch__dot{background:var(--hp-green);border-color:var(--hp-green);color:#fff}
.hp-ch strong{font:600 1rem var(--display);color:var(--hp-navy);padding:10px 16px;border-radius:12px;background:var(--hp-mint);flex:1}

/* ecosystem */
.hp-eco{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:clamp(24px,4vw,60px);align-items:center}
.hp-eco>*{min-width:0}
.hp-eco__wheel svg{width:100%;max-width:440px;display:block;margin:auto;overflow:visible}
.hp-eco__seg{cursor:pointer;outline:none}
.hp-eco__seg path{fill:#fff;stroke:var(--hp-line);stroke-width:1.5;transition:fill .3s,stroke .3s}
.hp-eco__seg foreignObject{color:var(--c);pointer-events:none}
.hp-eco__seg text{font:700 12.5px var(--display);fill:var(--hp-navy);pointer-events:none}
.hp-eco__seg.is-on path{fill:var(--c);stroke:var(--c)}
.hp-eco__seg.is-on foreignObject{color:#fff}
.hp-eco__seg.is-on text{fill:#fff}
.hp-eco__seg:focus-visible path{stroke:#E3A013;stroke-width:3}
.hp-eco__core{fill:var(--hp-navy)}
.hp-eco__pulse{fill:none;stroke:var(--hp-teal-2);stroke-width:2;transform-box:fill-box;transform-origin:center;animation:rcPulse 3.2s ease-out infinite}
.hp-eco__ct{font:800 12px var(--display);letter-spacing:.12em;fill:#fff}
.hp-eco__panel{padding:clamp(22px,3vw,34px);border-radius:22px;background:#fff;border:1px solid var(--hp-line);border-left:5px solid var(--c);animation:rcPanel .4s ease}
.hp-eco__ic{width:48px;height:48px;border-radius:14px;display:grid;place-items:center;background:var(--hp-mint);color:var(--c);margin-bottom:12px}
.hp-eco__panel h3{font-size:1.4rem;color:var(--hp-navy)}
.hp-eco__panel ul{list-style:none;margin:0 0 14px;padding:0;display:grid;grid-template-columns:1fr 1fr;gap:8px}
.hp-eco__panel li{padding:10px 12px;border-radius:10px;background:var(--hp-mint);font-weight:600;font-size:.92rem;color:var(--hp-navy);animation:rcPanel .4s ease both;animation-delay:calc(var(--i)*50ms)}
.hp-eco__panel p{font-size:.82rem;color:var(--hp-muted);margin:0}
.hp-eco__acc{display:none}

/* profiling */
.hp-prof__tabs{display:flex;flex-wrap:wrap;gap:8px;margin-bottom:16px}
.hp-prof__tabs button{display:inline-flex;align-items:center;gap:8px;padding:10px 16px;border-radius:12px;border:1px solid var(--hp-line);background:#fff;font-weight:700;font-size:.9rem;color:var(--hp-muted);transition:all .25s}
.hp-prof__tabs button.is-on{background:var(--hp-teal);border-color:var(--hp-teal);color:#fff}
.hp-prof__card{padding:clamp(20px,3vw,30px);border-radius:20px;background:linear-gradient(135deg,#fff,var(--hp-mint));border:1px solid var(--hp-line);animation:rcPanel .4s ease}
.hp-prof__head{display:flex;align-items:center;gap:14px;flex-wrap:wrap;padding-bottom:16px;margin-bottom:16px;border-bottom:1px dashed var(--hp-line)}
.hp-prof__head>div{flex:1;min-width:160px}
.hp-prof__head strong{display:block;font:700 1.15rem var(--display);color:var(--hp-navy)}
.hp-prof__head div span{font-size:.84rem;color:var(--hp-muted)}
.hp-prof__av{width:50px;height:50px;border-radius:50%;display:grid;place-items:center;background:var(--hp-navy);color:#fff}
.hp-prof__card ul{list-style:none;margin:0;padding:0;display:grid;grid-template-columns:repeat(3,1fr);gap:8px}
.hp-prof__card li{display:flex;align-items:center;gap:8px;padding:12px 14px;border-radius:12px;background:#fff;border:1px solid var(--hp-line);font-weight:600;font-size:.9rem;color:var(--hp-navy);animation:rcPanel .4s ease both;animation-delay:calc(var(--i)*50ms)}
.hp-prof__card li .rc-ico{color:var(--hp-green)}
.hp-spec{margin-top:clamp(48px,6vw,80px)}
.hp-spec__grid{display:grid;grid-template-columns:repeat(5,1fr);gap:10px}
.hp-spec__card{--acc:var(--hp-teal);display:flex;align-items:center;gap:12px;padding:16px;border-radius:14px;background:#fff;border:1px solid var(--hp-line);font:600 .92rem var(--display);color:var(--hp-navy);outline:none;position:relative;overflow:hidden;transition:transform .3s,border-color .3s,box-shadow .3s}
.hp-spec__card1{--acc:var(--hp-blue)}.hp-spec__card2{--acc:var(--hp-green)}.hp-spec__card3{--acc:#5A3FE0}
.hp-spec__card .rc-ico{color:var(--acc);transition:transform .3s}
.hp-spec__card:after{content:"";position:absolute;left:0;bottom:0;height:3px;width:100%;background:var(--acc);transform:scaleX(0);transform-origin:left;transition:transform .35s}
.hp-spec__card:is(:hover,:focus-visible){transform:translateY(-3px);border-color:var(--acc);box-shadow:0 14px 28px -22px var(--acc)}
.hp-spec__card:is(:hover,:focus-visible):after{transform:scaleX(1)}
.hp-spec__card:is(:hover,:focus-visible) .rc-ico{transform:scale(1.15)}

/* methods */
.hp-meth{display:grid;grid-template-columns:repeat(3,1fr);gap:14px}
.hp-meth__card{padding:24px;border-radius:18px;background:#fff;border:1px solid var(--hp-line);--hov:var(--hp-teal);--hov-bg:#fff}
.hp-meth__ic{width:48px;height:48px;border-radius:14px;display:grid;place-items:center;background:var(--hp-cyan);color:var(--hp-teal);margin-bottom:14px}
.hp-meth__card h3{font-size:1.06rem;color:var(--hp-navy)}
.hp-meth__card p{font-size:.9rem;color:var(--hp-muted);margin-bottom:8px}

/* quality plates (layered, slight 3D) */
.hp-qc{display:grid;grid-template-columns:minmax(0,.85fr) minmax(0,1.15fr);gap:clamp(24px,4vw,56px);align-items:center}
.hp-qc>*{min-width:0}
.hp-qc__stack{position:relative;height:380px;perspective:900px}
.hp-qc__plate{position:absolute;left:10%;right:10%;height:96px;top:calc(var(--i)*52px);border-radius:18px;background:linear-gradient(135deg,rgba(18,163,163,.24),rgba(11,34,168,.18));border:1px solid rgba(127,224,218,.35);transform:rotateX(58deg) rotateZ(-8deg) translateY(30px);opacity:0;transition:transform .7s cubic-bezier(.2,.7,.2,1),opacity .6s,background .3s,border-color .3s;transition-delay:calc(var(--i)*.12s);display:flex;align-items:center;justify-content:flex-end;padding-right:20px;cursor:pointer}
.hp-qc.is-in .hp-qc__plate{transform:rotateX(58deg) rotateZ(-8deg);opacity:1}
.hp-qc__plate span{font:800 1.4rem var(--display);color:rgba(255,255,255,.55);transform:rotateZ(8deg)}
.hp-qc__plate.is-on{background:linear-gradient(135deg,#12A3A3,#2F855A);border-color:#7FE0DA;box-shadow:0 0 40px -6px rgba(18,163,163,.7)}
.hp-qc__plate.is-on span{color:#fff}
.hp-qc__list{list-style:none;margin:0;padding:0;display:grid;gap:8px}
.hp-qc__list>li{border-radius:14px;border:1px solid rgba(255,255,255,.14);background:rgba(255,255,255,.04);overflow:hidden;transition:border-color .3s,background .3s}
.hp-qc__list>li.is-on{border-color:#7FE0DA;background:rgba(18,163,163,.12)}
.hp-qc__list button{display:flex;align-items:baseline;gap:12px;width:100%;text-align:left;padding:14px 18px;border:0;background:none;color:#fff}
.hp-qc__n{font:700 .7rem var(--body);letter-spacing:.12em;text-transform:uppercase;color:#7FE0DA;flex:none;width:58px}
.hp-qc__list strong{font:700 1rem var(--display)}
.hp-qc__list ul{list-style:none;margin:0;padding:0 18px 14px 88px;display:none;flex-wrap:wrap;gap:6px}
.hp-qc__list>li.is-on ul{display:flex;animation:rcPanel .35s ease}
.hp-qc__list ul li{display:inline-flex;align-items:center;gap:6px;padding:6px 10px;border-radius:999px;background:rgba(255,255,255,.08);font-size:.82rem;color:#DDEFF0}
.hp-qc__list ul .rc-ico{color:#7FE0DA}
.hp-mid{background:linear-gradient(100deg,var(--hp-teal),#0B6F8A);color:#fff;padding:clamp(26px,4vw,40px) 0}
.hp-mid__in{display:flex;align-items:center;justify-content:space-between;gap:24px;flex-wrap:wrap}
.hp-mid strong{display:block;font:700 clamp(1.15rem,2vw,1.45rem) var(--display)}
.hp-mid span{color:#E0F6F6}

/* responsible */
.hp-resp{display:grid;grid-template-columns:minmax(0,.9fr) minmax(0,1.1fr);gap:clamp(28px,5vw,72px);align-items:start}
.hp-resp>*{min-width:0}
.hp-resp__cert{display:flex;gap:10px;align-items:flex-start;padding:14px 16px;border-radius:12px;background:var(--hp-mint);font-size:.9rem;color:var(--hp-navy);margin-top:16px}
.hp-resp__cert .rc-ico{color:var(--hp-teal);flex:none;margin-top:2px}
.hp-resp__list{list-style:none;margin:0;padding:0;display:grid;grid-template-columns:1fr 1fr;gap:0;border-top:1px solid var(--hp-line)}
.hp-resp__list li{display:flex;gap:12px;padding:16px 12px 16px 0;border-bottom:1px solid var(--hp-line)}
.hp-resp__list .rc-ico{color:var(--hp-teal);flex:none;margin-top:2px}
.hp-resp__list strong{display:block;font:700 .95rem var(--display);color:var(--hp-navy)}
.hp-resp__list span{font-size:.84rem;color:var(--hp-muted)}

/* coverage (dark map) */
.hp-cov{display:grid;grid-template-columns:minmax(0,1.4fr) minmax(0,.6fr);gap:clamp(24px,4vw,56px);align-items:center}
.hp-cov>*{min-width:0}
.hp-cov svg{width:100%;height:auto;display:block;overflow:visible}
.hp-cov__dots{fill:none;stroke:#21406E;stroke-width:4.2;stroke-linecap:round}
.hp-cov__arc{fill:none;stroke:#3FC7C2;stroke-width:1.4;stroke-dasharray:1;stroke-dashoffset:1;opacity:.75;transition:stroke-dashoffset 1.4s ease;transition-delay:calc(.4s + var(--i)*.12s)}
.hp-cov.is-in .hp-cov__arc{stroke-dashoffset:0}
.hp-cov__hub{opacity:0;transition:opacity .5s;transition-delay:calc(var(--i)*.1s)}
.hp-cov.is-in .hp-cov__hub{opacity:1}
.hp-cov__ring{fill:rgba(63,199,194,.18);stroke:#3FC7C2;stroke-width:1.5}
.hp-cov__plus{stroke:#fff;stroke-width:2.5;stroke-linecap:round}
.hp-cov__stats{display:grid;gap:0}
.hp-cov__stats>div{padding:16px 0;border-bottom:1px solid rgba(255,255,255,.12);display:flex;flex-direction:column;gap:2px}
.hp-cov__stats .od-count{font-size:clamp(2rem,3.4vw,2.8rem);color:#7FE0DA}
.hp-cov__stats>div:last-child .od-count{font-size:1.5rem;color:#fff}
.hp-cov__stats span:last-child{color:#B9C6DA;font-size:.9rem}

/* use cases */
.hp-use{display:grid;grid-template-columns:repeat(4,1fr);gap:12px}
.hp-use__card{--acc:var(--hp-teal);padding:20px;border-radius:16px;background:#fff;border:1px solid var(--hp-line);outline:none;transition:background .35s,border-color .35s,transform .35s,box-shadow .35s}
.hp-use__card1{--acc:var(--hp-blue)}.hp-use__card2{--acc:var(--hp-green)}.hp-use__card3{--acc:#5A3FE0}
.hp-use__card>.rc-ico{color:var(--acc);margin-bottom:10px}
.hp-use__card h3{font-size:1rem;color:var(--hp-navy)}
.hp-use__card p{margin:0;font-size:.86rem;color:var(--hp-muted)}
.hp-use__card:is(:hover,:focus-visible){background:color-mix(in srgb,var(--acc) 7%,#fff);border-color:var(--acc);transform:translateY(-3px);box-shadow:0 18px 36px -28px var(--acc)}
.hp-cmp{margin-top:clamp(48px,6vw,80px)}
.hp-cmp__t{border-radius:20px;overflow:hidden;border:1px solid var(--hp-line)}
.hp-cmp__r{display:grid;grid-template-columns:1fr 1fr;border-top:1px solid var(--hp-line)}
.hp-cmp__r--h{border-top:0}
.hp-cmp__r span{padding:15px 22px;display:flex;align-items:center;gap:10px}
.hp-cmp__r span:first-child{background:#F6F7F9;color:var(--hp-muted)}
.hp-cmp__r span:last-child{background:#fff;color:var(--hp-navy);font-weight:600}
.hp-cmp__r span:last-child .rc-ico{color:var(--hp-teal)}
.hp-cmp__r--h span{font:700 .78rem var(--body)!important;letter-spacing:.12em;text-transform:uppercase}
.hp-cmp__r--h span:last-child{background:var(--hp-teal)!important;color:#fff!important}
.hp-cmp__r--h span:first-child{background:#E8EBF0!important;color:var(--hp-muted)!important}
.hp-cmp__r:not(.hp-cmp__r--h):hover span:last-child{background:var(--hp-mint)}

/* process */
.hp-wf{position:relative}
.hp-wf__ecg{width:100%;height:56px;display:block;margin-bottom:6px}
.hp-wf__ecg path{fill:none;stroke:var(--hp-teal-2);stroke-width:2;stroke-dasharray:1;stroke-dashoffset:1;transition:stroke-dashoffset 3s ease;vector-effect:non-scaling-stroke}
.hp-wf.is-in .hp-wf__ecg path{stroke-dashoffset:0}
.hp-wf ol{list-style:none;margin:0;padding:0;display:grid;grid-template-columns:repeat(7,1fr);gap:10px}
.hp-wf li{padding:16px;border-radius:14px;background:#fff;border:1px solid var(--hp-line);opacity:.3;transform:translateY(8px);transition:opacity .5s,transform .5s,border-color .3s;transition-delay:calc(var(--i)*.38s),calc(var(--i)*.38s),0s}
.hp-wf.is-in li{opacity:1;transform:none}
.hp-wf li:hover{border-color:var(--hp-teal)}
.hp-wf__n{display:inline-grid;place-items:center;width:30px;height:30px;border-radius:50%;background:var(--hp-navy);color:#fff;font:800 .74rem var(--display);margin-bottom:10px}
.hp-wf li:last-child .hp-wf__n{background:var(--hp-green)}
.hp-wf strong{display:block;font:700 1rem var(--display);color:var(--hp-navy);margin-bottom:4px}
.hp-wf p{margin:0;font-size:.82rem;color:var(--hp-muted)}

/* why + own panel */
.hp-why{display:grid;grid-template-columns:repeat(3,1fr);gap:14px}
.hp-why__card{padding:22px;border-radius:18px;background:#fff;border:1px solid var(--hp-line);--hov:var(--hp-teal);--hov-bg:var(--hp-mint)}
.hp-why__card>span{width:42px;height:42px;border-radius:12px;display:grid;place-items:center;background:var(--hp-navy);color:#fff;margin-bottom:14px}
.hp-why__card h3{font-size:1.02rem;color:var(--hp-navy)}
.hp-why__card p{margin:0;font-size:.88rem;color:var(--hp-muted)}
.hp-own{margin-top:clamp(40px,5vw,64px);display:grid;grid-template-columns:minmax(0,.9fr) minmax(0,1.1fr);gap:clamp(20px,3vw,40px);align-items:center;padding:clamp(22px,3vw,36px);border-radius:24px;background:linear-gradient(135deg,var(--hp-navy),#0B2C5C);color:#fff}
.hp-own>*{min-width:0}
.hp-own__logo{display:inline-grid;place-items:center;padding:10px 16px;border-radius:12px;background:#fff;margin-bottom:14px}
.hp-own__logo img{max-height:44px;width:auto}
.hp-own__k{display:block;font:700 .72rem var(--body);letter-spacing:.14em;text-transform:uppercase;color:#7FE0DA}
.hp-own h3{color:#fff;font-size:1.5rem;margin:6px 0 8px}
.hp-own p{color:#C8D3E6}
.hp-own .rc-link{color:#7FE0DA}
.hp-own__flow{list-style:none;margin:0;padding:0;display:grid;grid-template-columns:repeat(3,1fr);gap:10px}
.hp-own__flow li{display:flex;flex-direction:column;align-items:center;gap:8px;padding:14px 8px;border-radius:14px;background:rgba(255,255,255,.06);border:1px solid rgba(255,255,255,.14);font:600 .9rem var(--display);text-align:center;animation:rcFade .6s ease both;animation-delay:calc(var(--i)*.1s)}
.hp-own__flow li span{width:40px;height:40px;border-radius:50%;display:grid;place-items:center;background:rgba(18,163,163,.25);color:#7FE0DA}
.hp-own__flow li:last-child span{background:var(--hp-green);color:#fff}

/* team + sectors */
.hp-team{display:grid;grid-template-columns:repeat(5,1fr);gap:12px}
.hp-team__card{display:flex;flex-direction:column;align-items:center;text-align:center;gap:8px;padding:22px 14px;border-radius:18px;background:#fff;border:1px solid var(--hp-line);text-decoration:none;color:var(--hp-navy)}
.hp-team__ph{width:72px;height:72px;border-radius:50%;display:grid;place-items:center;overflow:hidden;background:var(--hp-cyan);color:var(--hp-teal);box-shadow:0 0 0 4px #fff,0 0 0 5px var(--hp-line)}
.hp-team__ph img{width:100%;height:100%;object-fit:cover}
.hp-team__card strong{font:700 1rem var(--display)}
.hp-team__role{font-size:.84rem;color:var(--hp-muted)}
.hp-team__role--only{font:700 .95rem/1.3 var(--display);color:var(--hp-navy)}
.hp-sec2{margin-top:clamp(48px,6vw,80px)}
.hp-sectors{display:grid;grid-template-columns:repeat(3,1fr);gap:10px}
.hp-sectors__item{display:grid;grid-template-columns:auto 1fr auto;gap:12px;align-items:center;padding:18px;border-radius:14px;background:#fff;border:1px solid var(--hp-line);text-decoration:none;color:var(--hp-navy);font:600 .98rem var(--display);transition:border-color .3s,background .3s,transform .3s}
.hp-sectors__item>.rc-ico:first-child{color:var(--hp-teal)}
.hp-sectors__go{color:#9AA8BB;transition:transform .3s,color .3s}
.hp-sectors__item:hover{border-color:var(--hp-teal);background:var(--hp-mint);transform:translateY(-2px)}
.hp-sectors__item:hover .hp-sectors__go{transform:translateX(4px);color:var(--hp-teal)}

/* example */
.hp-ex{list-style:none;margin:0;padding:0;display:grid;grid-template-columns:repeat(6,1fr);gap:0;counter-reset:x;border-radius:20px;overflow:hidden;border:1px solid var(--hp-line)}
.hp-ex li{padding:20px 16px;background:#fff;position:relative}
.hp-ex li+li{border-left:1px solid var(--hp-line)}
.hp-ex li:nth-child(even){background:var(--hp-mint)}
.hp-ex span{font:800 1.4rem var(--display);color:var(--hp-teal)}
.hp-ex strong{display:block;font:700 1rem var(--display);color:var(--hp-navy);margin:6px 0 4px}
.hp-ex p{margin:0;font-size:.84rem;color:var(--hp-muted)}

/* insights */
.hp-ins{display:grid;grid-template-columns:repeat(4,1fr);gap:12px}
.hp-ins__card{display:flex;flex-direction:column;gap:8px;padding:20px;border-radius:16px;background:#fff;border:1px solid var(--hp-line);text-decoration:none;color:var(--hp-navy);transition:transform .3s,box-shadow .3s,border-color .3s}
.hp-ins__card:hover{transform:translateY(-3px);border-color:var(--hp-teal);box-shadow:0 18px 36px -28px var(--hp-navy)}
.hp-ins__card--lead{grid-row:span 2;background:linear-gradient(160deg,var(--hp-navy),#0B2C5C);color:#fff;border:0;justify-content:flex-end}
.hp-ins__k{font:700 .7rem var(--body);letter-spacing:.14em;text-transform:uppercase;color:var(--hp-teal)}
.hp-ins__card--lead .hp-ins__k{color:#7FE0DA}
.hp-ins__card strong{font:700 1rem/1.35 var(--display)}
.hp-ins__card--lead strong{font-size:1.3rem}
.hp-ins__go{margin-top:auto;display:inline-flex;align-items:center;gap:6px;font-size:.84rem;font-weight:700;color:var(--hp-teal)}
.hp-ins__card--lead .hp-ins__go{color:#7FE0DA}
.hp-cta{background:radial-gradient(700px 400px at 0% 0%,#0B4A5C 0%,transparent 70%),var(--hp-navy)!important}
.hp-cta .rc-kicker{color:#7FE0DA!important}
.hp-cta__micro{margin-top:12px;font-size:.88rem;color:#B9C6DA!important}

/* responsive */
@media (max-width:1100px){
  .hp-trust,.hp-use{grid-template-columns:1fr 1fr}
  .hp-spec__grid{grid-template-columns:repeat(3,1fr)}
  .hp-wf ol{grid-template-columns:repeat(4,1fr)}
  .hp-wf__ecg{display:none}
  .hp-team{grid-template-columns:repeat(3,1fr)}
  .hp-ex{grid-template-columns:repeat(3,1fr)}
  .hp-ex li:nth-child(4){border-left:0}
  .hp-ex li:nth-child(n+4){border-top:1px solid var(--hp-line)}
  .hp-ins{grid-template-columns:1fr 1fr}
}
@media (max-width:900px){
  .hp-hero__in,.hp-chwrap,.hp-eco,.hp-qc,.hp-resp,.hp-cov,.hp-own{grid-template-columns:1fr}
  .hp-meth,.hp-why,.hp-sectors{grid-template-columns:1fr 1fr}
  .hp-qc__stack{height:340px;max-width:420px;margin:auto;width:100%}
}
@media (max-width:640px){
  .hp-hero h1{font-size:2.6rem}
  .hp-hero .od-hero__ctas .btn,.hp-mid .btn,.hp-cta .od-hero__ctas .btn{width:100%}
  .hp-stack{min-height:0}
  .hp-tags{display:none}
  .hp-card{width:100%;margin-left:0!important;grid-template-columns:38px 1fr}
  .hp-card__v{grid-column:2;justify-self:start}
  .hp-trust,.hp-use,.hp-meth,.hp-why,.hp-sectors,.hp-team,.hp-ins,.hp-own__flow{grid-template-columns:1fr}
  .hp-own__flow{grid-template-columns:1fr 1fr}
  .hp-eco__wheel,.hp-eco__panel{display:none}
  .hp-eco__acc{display:grid;gap:8px}
  .hp-eco__acc details{border-radius:14px;background:#fff;border:1px solid var(--hp-line);border-left:4px solid var(--c);overflow:hidden}
  .hp-eco__acc summary{display:flex;align-items:center;gap:10px;padding:14px 16px;font:700 1rem var(--display);color:var(--hp-navy);cursor:pointer;list-style:none}
  .hp-eco__acc summary::-webkit-details-marker{display:none}
  .hp-eco__acc summary .rc-ico{color:var(--c)}
  .hp-eco__acc summary b{margin-left:auto;font-size:.8rem;color:var(--hp-muted)}
  .hp-eco__acc ul{list-style:none;margin:0;padding:0 16px 14px;display:flex;flex-wrap:wrap;gap:6px}
  .hp-eco__acc li{padding:6px 10px;border-radius:8px;background:var(--hp-mint);font-size:.86rem;font-weight:600}
  .hp-prof__card ul{grid-template-columns:1fr}
  .hp-prof__tabs{flex-wrap:nowrap;overflow-x:auto;margin-inline:-16px;padding:0 16px 4px;scrollbar-width:none}
  .hp-prof__tabs button{flex:none}
  .hp-spec__grid{grid-template-columns:1fr 1fr}
  .hp-qc__stack{height:260px}
  .hp-qc__plate{height:70px;top:calc(var(--i)*36px)}
  .hp-qc__list ul{padding-left:18px}
  .hp-resp__list{grid-template-columns:1fr}
  .hp-cmp__r{grid-template-columns:1fr}
  .hp-cmp__r--h{display:none}
  .hp-cmp__r span{padding:10px 16px}
  .hp-cmp__r span:before{content:attr(data-l);font:700 .66rem var(--body);letter-spacing:.12em;text-transform:uppercase;color:#97A3B5;margin-right:8px;flex:none;width:100%}
  .hp-cmp__r span{flex-wrap:wrap;gap:2px}
  .hp-wf ol{grid-template-columns:1fr;gap:8px}
  .hp-wf li{display:grid;grid-template-columns:30px 1fr;column-gap:12px}
  .hp-wf__n{grid-row:span 2;margin:0}
  .hp-ex{grid-template-columns:1fr}
  .hp-ex li{border-left:0!important;border-top:1px solid var(--hp-line)}
  .hp-ins__card--lead{grid-row:auto;min-height:180px}
}
@media (prefers-reduced-motion:reduce){
  .hpg *{animation:none!important;transition:none!important}
  .hp-card,.hp-tags span,.hp-ch li,.hp-qc__plate,.hp-cov__hub,.hp-wf li,.hp-own__flow li{opacity:1!important}
  .hp-qc__plate{transform:rotateX(58deg) rotateZ(-8deg)!important}
  .hp-ch:before{transform:none!important}
  .hp-cov__arc,.hp-wf__ecg path,.hp-stack__ecg path{stroke-dashoffset:0!important}
}
@media (max-width:640px){.hpg .hp-card--1,.hpg .hp-card--4{display:none}.hpg .hp-card{padding:12px 14px}}

/* ===== Research Design Cycle (rdc-) — deep navy, charcoal, soft blue, muted teal, one gold accent ===== */
.rdc{--od-navy:#07104F;--od-blue:#1E5BFF;--od-royal:#0B22A8;--od-sky:#E8EEFF;--od-teal:#0E9C88;--od-teal-soft:#E3F5F2;--od-line:#DDE2EC;--od-muted:#525C78;--od-paper:#F5F7FB;
  --r-navy:#07104F;--r-char:#1E2433;--r-blue:#0B22A8;--r-soft:#EEF2FB;--r-teal:#0E8A8A;--r-gold:#C99A2E;--r-line:#DDE2EC;--r-muted:#525C78}
.rdc .rc-kicker{color:var(--r-teal)}
.rdc .rc-head--light .rc-kicker{color:#7FE0DA}
.rdc-sec--navy{background:linear-gradient(165deg,#07104F,#0B1660);color:#fff}
.rdc-sec--soft{background:var(--r-soft)}
.rdc-lead{font:600 clamp(1.1rem,1.6vw,1.3rem)/1.5 var(--display);color:var(--r-navy)}
.rdc-note{font-size:.86rem;color:var(--r-muted);margin:14px 0 0}
.rdc-note a{color:var(--r-blue);font-weight:600}
.rdc-note--c{text-align:center}
.rdc-out{display:flex;gap:12px;align-items:baseline;padding:14px 18px;border-radius:12px;background:color-mix(in srgb,var(--c,#0E8A8A) 8%,#fff);border-left:4px solid var(--c,#0E8A8A);font:600 .96rem/1.45 var(--display);color:var(--r-navy)}
.rdc-out span{flex:none;font:800 .68rem var(--body);letter-spacing:.14em;text-transform:uppercase;color:var(--c,#0E8A8A)}
.rdc-out--wide{margin-top:clamp(24px,3vw,36px)}

/* hero */
.rdc-hero{background:radial-gradient(700px 480px at 82% 40%,#E6ECFB 0%,transparent 65%),linear-gradient(180deg,#fff,#F6F8FC);padding:clamp(32px,4vw,56px) 0 clamp(32px,4vw,48px);border-bottom:1px solid var(--r-line);overflow:hidden}
.rdc-hero__in{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:clamp(24px,4vw,56px);align-items:center}
.rdc-hero__in>*{min-width:0}
.rdc-eyebrow{display:inline-flex;align-items:center;gap:8px;font:700 .78rem var(--body);letter-spacing:.14em;text-transform:uppercase;color:var(--r-teal);margin-bottom:16px}
.rdc-hero h1{font-size:clamp(2.6rem,5.2vw,4.3rem);color:var(--r-navy);margin-bottom:.15em}
.rdc-hero__sub{font:700 clamp(1.25rem,2.2vw,1.75rem)/1.3 var(--display);color:var(--r-blue);margin-bottom:16px;background:linear-gradient(transparent 70%,rgba(201,154,46,.25) 70%);display:inline}
.rdc-hero__body{color:var(--r-muted);font-size:1.05rem;max-width:56ch;margin:18px 0 24px}
.rdc .rdc-btn{background:var(--r-navy);color:#fff}
.rdc .rdc-btn:hover{background:var(--r-blue)}
.rdc-hero__viz{max-width:520px;justify-self:center;width:100%}
.rdc-wheel{width:100%;height:auto;display:block;overflow:visible}
.rdc-wheel__outer{fill:none;stroke:#C9D2E6;stroke-dasharray:2 7;transform-origin:250px 250px;animation:rcSpin 120s linear infinite}
.rdc-wheel__arc{fill:none;stroke:#9DB0D8;stroke-width:2}
.rdc-wheel__arc--loop{stroke:var(--r-gold);stroke-width:2.5;stroke-dasharray:5 5;animation:rcDash 3s linear infinite}
.rdc-wheel__ah{fill:#9DB0D8}
.rdc-wheel__learn rect{fill:var(--r-gold)}
.rdc-wheel__learn text{font:800 10.5px var(--body);letter-spacing:.1em;fill:#fff}
.rdc-wheel__pkt{fill:var(--r-teal)}
.rdc-wheel__spoke{stroke:#DDE2EC;stroke-width:1;transition:stroke .3s,stroke-width .3s}
.rdc-wheel__spoke.is-on{stroke:var(--c);stroke-width:2.5}
.rdc-wheel__node{opacity:0;animation:rcFade .5s ease forwards;animation-delay:calc(.15s + var(--i)*.1s);outline:none}
.rdc-wheel__node circle{fill:#fff;stroke:var(--c);stroke-width:2;transition:fill .3s}
.rdc-wheel__n{font:800 13px var(--display);fill:var(--c)}
.rdc-wheel__k{font:600 10.5px var(--body);fill:var(--r-navy)}
.rdc-wheel__core{fill:var(--r-navy)}
.rdc-wheel__pulse{fill:none;stroke:#7FA6FF;stroke-width:2;transform-box:fill-box;transform-origin:center;animation:rcPulse 3.4s ease-out infinite}
.rdc-wheel__ct{font:800 14px var(--display);letter-spacing:.12em;fill:#fff}
.rdc-wheel--big .rdc-wheel__node{cursor:pointer}
.rdc-wheel--big .rdc-wheel__node:hover circle,.rdc-wheel--big .rdc-wheel__node.is-on circle{fill:var(--c)}
.rdc-wheel--big .rdc-wheel__node:hover text,.rdc-wheel--big .rdc-wheel__node.is-on text{fill:#fff}
.rdc-wheel--big .rdc-wheel__node:focus-visible circle{stroke:var(--r-gold);stroke-width:4}
.rdc-sec--navy .rdc-wheel__outer{stroke:#ffffff26}
.rdc-sec--navy .rdc-wheel__arc{stroke:#7F8CC4}
.rdc-sec--navy .rdc-wheel__ah{fill:#7F8CC4}
.rdc-sec--navy .rdc-wheel__spoke{stroke:#ffffff1a}
.rdc-sec--navy .rdc-wheel__core{fill:#fff}
.rdc-sec--navy .rdc-wheel__ct{fill:var(--r-navy)}
.rdc-sec--navy .rdc-wheel__node circle{fill:#0E1A66}
.rdc-sec--navy .rdc-wheel__k{fill:#E4EAFF}
.rdc-sec--navy .rdc-wheel__n{fill:#fff}
.rdc-strip{list-style:none;margin:clamp(24px,3vw,36px) 0 0;padding:0;display:grid;grid-template-columns:repeat(7,1fr);gap:6px}
.rdc-strip li{position:relative;display:flex;flex-direction:column;gap:4px;padding:14px;border-radius:14px;background:#fff;border:1px solid var(--r-line);border-top:3px solid var(--c);outline:none;cursor:default;transition:transform .3s,box-shadow .3s}
.rdc-strip__n{font:800 .74rem var(--display);color:var(--c)}
.rdc-strip__ic{position:absolute;top:12px;right:12px;color:var(--c);opacity:.7}
.rdc-strip strong{font:700 1rem var(--display);color:var(--r-navy)}
.rdc-strip__d{font-size:.78rem;line-height:1.4;color:var(--r-muted);max-height:0;opacity:0;overflow:hidden;transition:max-height .35s,opacity .3s}
.rdc-strip li:is(:hover,:focus-visible){transform:translateY(-3px);box-shadow:0 16px 30px -24px var(--c)}
.rdc-strip li:is(:hover,:focus-visible) .rdc-strip__d{max-height:60px;opacity:1}

/* intro + architecture */
.rdc-intro{display:grid;grid-template-columns:minmax(0,1.1fr) minmax(0,.9fr);gap:clamp(28px,5vw,72px);align-items:center}
.rdc-intro>*{min-width:0}
.rdc-intro a{color:var(--r-blue);font-weight:600}
.rdc-arch{padding:24px;border-radius:22px;background:var(--r-soft);border:1px solid var(--r-line)}
.rdc-arch__k{font:700 .72rem var(--body);letter-spacing:.14em;text-transform:uppercase;color:var(--r-teal)}
.rdc-arch ol{list-style:none;margin:12px 0 10px;padding:0;display:grid;gap:4px;justify-items:center}
.rdc-arch li{width:calc(100% - var(--i)*4%);text-align:center;padding:8px;border-radius:8px;font:600 .9rem var(--display);color:#fff;background:color-mix(in srgb,#0B22A8 calc(100% - var(--i)*7%),#0E8A8A);position:relative}
.rdc-arch li:last-child{background:var(--r-gold)}
.rdc-arch__note{font-size:.8rem;color:var(--r-muted)}

/* main cycle */
.rdc-cyc{display:grid;grid-template-columns:minmax(0,1.05fr) minmax(0,.95fr);gap:clamp(24px,4vw,56px);align-items:center}
.rdc-cyc>*{min-width:0}
.rdc-cyc__wheel{max-width:600px;width:100%;justify-self:center}
.rdc-cyc__panel{padding:clamp(24px,3vw,36px);border-radius:24px;background:#fff;color:var(--r-navy);border-top:5px solid var(--c);animation:rcPanel .4s ease}
.rdc-cyc__n{font:700 .74rem var(--body);letter-spacing:.14em;text-transform:uppercase;color:var(--c)}
.rdc-cyc__panel h3{display:flex;align-items:center;gap:10px;font-size:clamp(1.3rem,2.2vw,1.7rem);margin:10px 0}
.rdc-cyc__panel h3 .rc-ico{color:var(--c)}
.rdc-cyc__panel p{color:var(--r-muted)}
.rdc-cyc__nav{display:flex;align-items:center;justify-content:space-between;gap:12px;margin-top:20px}
.rdc-cyc__nav button{width:40px;height:40px;border-radius:50%;border:1px solid var(--r-line);background:#fff;color:var(--r-navy)}
.rdc-cyc__nav button:hover{border-color:var(--c);color:var(--c)}
.rdc-cyc__mob{display:none}

/* stages */
.rdc-stage{padding:clamp(64px,8vw,104px) 0;position:relative;scroll-margin-top:120px}
.rdc-stage:nth-of-type(even){background:#fff}
.rdc-stage__head{display:grid;grid-template-columns:auto minmax(0,1fr);gap:clamp(16px,3vw,36px);align-items:start;margin-bottom:clamp(28px,4vw,44px);max-width:900px}
.rdc-stage__num{font:800 clamp(3.4rem,7vw,5.6rem)/.85 var(--display);color:transparent;-webkit-text-stroke:2px var(--c);letter-spacing:-.04em}
.rdc-stage__k{display:inline-block;font:700 .76rem var(--body);letter-spacing:.14em;text-transform:uppercase;color:var(--c);margin-bottom:6px}
.rdc-stage h2{margin-bottom:.3em}
.rdc-stage__head p{color:var(--r-muted);margin:0;font-size:1.04rem}
.rdc-s1{display:grid;grid-template-columns:minmax(0,1.3fr) minmax(0,.7fr);gap:24px;align-items:center}
.rdc-s1>*,.rdc-s4>*{min-width:0}
.rdc-icons{list-style:none;margin:0;padding:0;display:grid;grid-template-columns:repeat(3,1fr);gap:8px}
.rdc-icons li{display:flex;align-items:center;gap:10px;padding:14px;border-radius:12px;background:#fff;border:1px solid var(--r-line);font:600 .9rem var(--display);color:var(--r-navy);transition:border-color .3s,transform .3s}
.rdc-icons li .rc-ico{color:var(--c)}
.rdc-icons li:hover{border-color:var(--c);transform:translateY(-2px)}
.rdc-icons--sm{grid-template-columns:repeat(5,1fr);margin:20px 0}
.rdc-icons--sm li{justify-content:center;text-align:center;padding:10px;font-size:.84rem}
.rdc-chain{list-style:none;margin:0;padding:0;display:flex;flex-wrap:wrap;gap:6px;align-items:center}
.rdc-s1 .rdc-chain{flex-direction:column;align-items:stretch}
.rdc-chain li{position:relative;padding:12px 16px;border-radius:10px;background:#fff;border:1px solid var(--r-line);font:700 .92rem var(--display);color:var(--r-navy);opacity:.2;transform:translateY(6px);transition:opacity .45s,transform .45s;transition-delay:calc(var(--i)*.16s)}
.rdc-chain.is-in li{opacity:1;transform:none}
.rdc-chain li:not(:last-child):after{content:"→";margin-left:10px;color:var(--c)}
.rdc-s1 .rdc-chain li{text-align:center}
.rdc-s1 .rdc-chain li:not(:last-child):after{content:"↓";position:absolute;left:50%;bottom:-17px;margin:0;transform:translateX(-50%);font-size:.85rem}
.rdc-s1 .rdc-chain{gap:14px}
.rdc-chain li:last-child{background:var(--c);color:#fff;border-color:var(--c)}
.rdc-bp{display:grid;place-items:center}
.rdc-bp__sheet{width:min(820px,100%);padding:26px;border-radius:18px;background:#0E2A6B;background-image:linear-gradient(rgba(255,255,255,.07) 1px,transparent 1px),linear-gradient(90deg,rgba(255,255,255,.07) 1px,transparent 1px);background-size:22px 22px;border:2px solid #3A62C9;color:#fff;box-shadow:0 30px 60px -40px #07104F}
.rdc-bp__title{display:block;font:800 .8rem var(--body);letter-spacing:.2em;text-transform:uppercase;color:#9DB6FF;border-bottom:1px dashed #6E8FE6;padding-bottom:10px;margin-bottom:16px}
.rdc-bp__grid{display:grid;grid-template-columns:repeat(4,1fr);gap:10px}
.rdc-bp__grid div{display:flex;align-items:center;gap:8px;padding:14px;border:1px dashed #6E8FE6;border-radius:8px;font:600 .92rem var(--display);animation:rcPanel .5s ease both;animation-delay:calc(var(--i)*.08s);transition:background .3s}
.rdc-bp__grid div:hover{background:rgba(255,255,255,.08)}
.rdc-bp__grid i{width:8px;height:8px;border-radius:50%;background:#7FE0DA;flex:none}

/* tree + matrix */
.rdc-tree{display:flex;flex-direction:column;align-items:center}
.rdc-tree__root{display:inline-flex;align-items:center;gap:8px;padding:12px 22px;border-radius:12px;background:var(--r-navy);color:#fff;font:700 1rem var(--display)}
.rdc-tree__lines{width:70%;height:40px}
.rdc-tree__lines path{fill:none;stroke:#9DB0D8;stroke-width:2;vector-effect:non-scaling-stroke}
.rdc-tree__br{display:grid;grid-template-columns:repeat(3,1fr);gap:12px;width:100%}
.rdc-tree__b{display:flex;flex-direction:column;gap:4px;text-align:left;padding:18px;border-radius:14px;border:1px solid var(--r-line);background:#fff;color:var(--r-navy);transition:all .3s}
.rdc-tree__k{font:800 .72rem var(--body);letter-spacing:.14em;text-transform:uppercase;color:var(--r-teal)}
.rdc-tree__b strong{font:700 1.1rem var(--display)}
.rdc-tree__d{font-size:.86rem;color:var(--r-muted)}
.rdc-tree__b.is-on{border-color:var(--r-teal);box-shadow:inset 0 0 0 1px var(--r-teal),0 16px 30px -26px var(--r-teal);background:#F2FAFA}
.rdc-tree__out{width:100%;margin-top:12px;padding:16px 18px;border-radius:12px;background:var(--r-soft);display:flex;flex-wrap:wrap;gap:10px;align-items:center;animation:rcPanel .35s ease}
.rdc-tree__out>span{font:700 .72rem var(--body);letter-spacing:.12em;text-transform:uppercase;color:var(--r-muted)}
.rdc-tree__out ul{list-style:none;margin:0;padding:0;display:flex;flex-wrap:wrap;gap:6px;flex:1}
.rdc-tree__out li{padding:6px 12px;border-radius:999px;background:#fff;border:1px solid var(--r-line);font-weight:600;font-size:.86rem}
.rdc-mx{margin-top:24px;border-radius:16px;overflow:hidden;border:1px solid var(--r-line)}
.rdc-mx__r{display:grid;grid-template-columns:1fr 1fr;border-top:1px solid var(--r-line);background:#fff}
.rdc-mx__r span{padding:13px 20px}
.rdc-mx__r span:last-child{font-weight:700;color:var(--r-teal)}
.rdc-mx__r--h{border-top:0;background:var(--r-char)}
.rdc-mx__r--h span{color:#fff!important;font:700 .76rem var(--body);letter-spacing:.12em;text-transform:uppercase}
.rdc-mx__r:not(.rdc-mx__r--h):hover{background:#F2FAFA}

/* decision flow */
.rdc-flow{padding:clamp(18px,3vw,28px);border-radius:22px;background:#fff;border:1px solid var(--r-line)}
.rdc-flow__cols{display:grid;grid-template-columns:repeat(4,1fr);gap:14px;position:relative}
.rdc-flow__col{padding:16px;border-radius:14px;background:var(--r-soft);position:relative}
.rdc-flow__col:not(:last-child):after{content:"→";position:absolute;right:-13px;top:22px;width:22px;height:22px;border-radius:50%;background:var(--r-navy);color:#fff;font-size:.72rem;display:grid;place-items:center;z-index:1}
.rdc-flow__step{font:700 .7rem var(--body);letter-spacing:.14em;text-transform:uppercase;color:var(--r-teal)}
.rdc-flow__col>strong{display:block;font:700 1rem var(--display);color:var(--r-navy);margin:4px 0 12px}
.rdc-flow__col [role=radiogroup]{display:flex;flex-direction:column;gap:6px}
.rdc-flow__col button{text-align:left;padding:9px 12px;border-radius:10px;border:1px solid var(--r-line);background:#fff;font-weight:600;font-size:.86rem;color:var(--r-navy);transition:all .2s}
.rdc-flow__col button:hover{border-color:var(--r-teal)}
.rdc-flow__col button.is-on{background:var(--r-navy);color:#fff;border-color:var(--r-navy)}
.rdc-flow__res{display:flex;flex-wrap:wrap;align-items:center;gap:14px;margin-top:16px;padding:16px 18px;border-radius:14px;background:linear-gradient(100deg,#FBF3DF,#fff);border:1px solid #EAD9A9}
.rdc-flow__res>.rc-ico{color:var(--r-gold)}
.rdc-flow__res>span{flex:1;min-width:220px;color:var(--r-navy)}
.rdc-flow__res b{color:var(--r-blue)}

/* stage 4 monitor */
.rdc-s4{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:clamp(24px,4vw,48px);align-items:start}
.rdc-ticks{list-style:none;margin:20px 0 0;padding:0;display:grid;grid-template-columns:1fr 1fr;gap:6px 16px}
.rdc-ticks li{display:flex;align-items:center;gap:8px;font-weight:600;font-size:.9rem;color:var(--r-navy)}
.rdc-ticks .rc-ico{color:var(--c)}
.rdc-mon{border-radius:20px;background:#0B1336;color:#fff;padding:16px;box-shadow:0 30px 60px -40px #07104F}
.rdc-mon__top{display:flex;justify-content:space-between;align-items:center;gap:10px;flex-wrap:wrap;margin-bottom:12px}
.rdc-mon__live{display:inline-flex;align-items:center;gap:8px;font:700 .84rem var(--display)}
.rdc-mon__live i{width:8px;height:8px;border-radius:50%;background:#2FD48A;box-shadow:0 0 0 0 #2FD48A;animation:rdcLive 2s infinite}
@keyframes rdcLive{0%{box-shadow:0 0 0 0 rgba(47,212,138,.6)}100%{box-shadow:0 0 0 10px rgba(47,212,138,0)}}
.rdc-mon__grid{display:grid;grid-template-columns:1fr 1fr;gap:10px}
.rdc-mon__card{padding:14px;border-radius:12px;background:rgba(255,255,255,.05);border:1px solid rgba(255,255,255,.1)}
.rdc-mon__card:first-child{grid-row:span 2}
.rdc-mon__card>span{display:block;font:700 .7rem var(--body);letter-spacing:.1em;text-transform:uppercase;color:#9DB6FF;margin-bottom:10px}
.rdc-mon__bar{margin-bottom:12px}
.rdc-mon__bar em{display:block;font-style:normal;font-size:.76rem;color:#C9D3F5;margin-bottom:4px}
.rdc-mon__bar b{display:block;height:8px;border-radius:4px;background:linear-gradient(90deg,#1E6BFF,#12A3A3);width:var(--w);transform-origin:left;transform:scaleX(0);transition:transform 1.4s cubic-bezier(.2,.7,.2,1)}
.rdc-mon.is-in .rdc-mon__bar b{transform:scaleX(1)}
.rdc-mon__card>svg{width:100%;height:auto}
.rdc-mon__line{fill:none;stroke:#7FE0DA;stroke-width:2.5;stroke-dasharray:300;stroke-dashoffset:300;transition:stroke-dashoffset 2s .3s}
.rdc-mon.is-in .rdc-mon__line{stroke-dashoffset:0}
.rdc-mon__card ul{list-style:none;margin:0;padding:0;display:grid;gap:6px}
.rdc-mon__card li{display:flex;align-items:center;gap:6px;font-size:.8rem;color:#DDE6FF}
.rdc-mon__card li .rc-ico{color:#2FD48A}

/* quant vs qual */
.rdc-qq{display:grid;grid-template-columns:1fr 1fr;gap:0;margin-top:24px;border-radius:20px;overflow:hidden;border:1px solid var(--r-line)}
.rdc-qq__side{padding:22px}
.rdc-qq__side--q{background:#fff}
.rdc-qq__side--l{background:#F4F1FD}
.rdc-qq__h span{display:block;font:800 1.15rem var(--display);color:var(--r-blue)}
.rdc-qq__side--l .rdc-qq__h span{color:#5A3FE0}
.rdc-qq__h em{font-style:normal;font-size:.82rem;color:var(--r-muted)}
.rdc-qq__vis{margin-top:14px;display:grid;gap:12px}
.rdc-qq__vis>svg{width:100%;max-width:340px}
.rdc-qq__bar{fill:#B9C8F2;transform-box:fill-box;transform-origin:bottom;transform:scaleY(0);transition:transform .8s cubic-bezier(.2,.7,.2,1);transition-delay:calc(var(--i)*.1s)}
.rdc-qq__bar:nth-child(3){fill:var(--r-blue)}
.rdc-qq.is-in .rdc-qq__bar{transform:scaleY(1)}
.rdc-qq__tl{fill:none;stroke:var(--r-gold);stroke-width:2.5;stroke-dasharray:300;stroke-dashoffset:300;transition:stroke-dashoffset 1.6s .5s}
.rdc-qq.is-in .rdc-qq__tl{stroke-dashoffset:0}
.rdc-qq__xt{width:100%;border-collapse:collapse;font-size:.76rem}
.rdc-qq__xt th,.rdc-qq__xt td{padding:6px 8px;border-bottom:1px solid var(--r-line);text-align:left;color:var(--r-muted)}
.rdc-qq__xt td i{display:block;height:7px;border-radius:4px;background:#B9C8F2;width:var(--w)}
.rdc-qq__themes{display:flex;flex-wrap:wrap;gap:8px}
.rdc-qq__themes span{padding:calc(4px + var(--s)*3px) calc(8px + var(--s)*4px);border-radius:999px;background:#fff;border:1px solid #D6CCF7;color:#5A3FE0;font-weight:700;font-size:calc(.72rem + var(--s)*.06rem)}
.rdc-qq__quote{margin:0;padding:14px 16px;border-radius:12px;background:#fff;border-left:3px solid #5A3FE0;font-size:.9rem;color:var(--r-navy)}
.rdc-qq__quote span{display:block;font:700 .66rem var(--body);letter-spacing:.12em;text-transform:uppercase;color:#5A3FE0;margin-bottom:4px}
.rdc-qq__note{grid-column:1/-1;margin:0;padding:10px 22px;background:var(--r-soft);font-size:.8rem;color:var(--r-muted);display:flex;align-items:center;gap:10px}

/* ladder */
.rdc-lad{list-style:none;margin:0;padding:0;display:grid;grid-template-columns:repeat(4,1fr);gap:0;position:relative}
.rdc-lad li{position:relative;padding:28px 22px 24px;background:#fff;border:1px solid var(--r-line);margin-left:-1px;opacity:0;transform:translateY(14px);transition:opacity .5s,transform .5s;transition-delay:calc(var(--i)*.2s)}
.rdc-lad li:first-child{border-radius:18px 0 0 18px;margin-left:0}
.rdc-lad li:last-child{border-radius:0 18px 18px 0;background:var(--r-navy);border-color:var(--r-navy);color:#fff}
.rdc-lad.is-in li{opacity:1;transform:none}
.rdc-lad li:not(:last-child):after{content:"";position:absolute;right:-14px;top:50%;width:26px;height:26px;margin-top:-13px;background:inherit;border-top:1px solid var(--r-line);border-right:1px solid var(--r-line);transform:rotate(45deg);z-index:1}
.rdc-lad__ic{width:46px;height:46px;border-radius:12px;display:grid;place-items:center;background:var(--r-soft);color:var(--r-blue);margin-bottom:14px}
.rdc-lad li:nth-child(2) .rdc-lad__ic{color:var(--r-teal)}
.rdc-lad li:nth-child(3) .rdc-lad__ic{color:var(--r-gold)}
.rdc-lad li:last-child .rdc-lad__ic{background:rgba(255,255,255,.12);color:#E7C873}
.rdc-lad strong{display:block;font:800 .86rem var(--body);letter-spacing:.14em}
.rdc-lad p{margin:6px 0 0;font:600 1.05rem/1.4 var(--display)}
.rdc-lad li:last-child p{color:#E4EAFF}

/* gate */
.rdc-gate{display:grid;grid-template-columns:minmax(0,1.2fr) minmax(0,.8fr);gap:clamp(20px,4vw,48px);align-items:center}
.rdc-gate>*{min-width:0}
.rdc-gate ol{list-style:none;margin:0;padding:0;display:grid;gap:6px;position:relative}
.rdc-gate li{display:flex;align-items:center;gap:14px;padding:13px 16px;border-radius:12px;background:#fff;border:1px solid var(--r-line);font:600 .98rem var(--display);color:var(--r-navy);opacity:.25;transform:translateX(-10px);transition:all .45s;transition-delay:calc(var(--i)*.18s)}
.rdc-gate.is-in li{opacity:1;transform:none}
.rdc-gate li span{width:26px;height:26px;border-radius:50%;display:grid;place-items:center;background:#EAF6EF;color:#2F855A;flex:none}
.rdc-gate__shield{display:flex;flex-direction:column;align-items:center;text-align:center;gap:10px;padding:30px 24px;border-radius:24px;background:linear-gradient(160deg,#EAF6EF,#fff);border:1px solid #CDE8D8;color:#2F855A}
.rdc-gate__shield strong{font:800 1.25rem var(--display);color:var(--r-navy)}
.rdc-gate__shield span{font-size:.9rem;color:var(--r-muted)}

/* deliverables */
.rdc-del{display:grid;grid-template-columns:repeat(3,1fr);gap:12px;margin-top:20px}
.rdc-del__card{display:flex;flex-direction:column;gap:6px;padding:20px;border-radius:16px;background:#fff;border:1px solid var(--r-line);--hov:var(--r-gold);--hov-bg:#FFFBF0}
.rdc-del__card .rc-ico{color:var(--r-gold)}
.rdc-del__card strong{font:700 1.02rem var(--display);color:var(--r-navy)}
.rdc-del__card span{font-size:.88rem;color:var(--r-muted)}

/* quality ring */
.rdc-qf{display:grid;grid-template-columns:minmax(0,.8fr) minmax(0,1.2fr);gap:clamp(24px,4vw,56px);align-items:center}
.rdc-qf>*{min-width:0}
.rdc-qf__ring{list-style:none;margin:0 auto;padding:0;position:relative;width:min(500px,100%);aspect-ratio:1;container-type:inline-size}
.rdc-qf__ring:before{content:"";position:absolute;inset:14%;border-radius:50%;border:2px dashed rgba(127,224,218,.35);animation:rcSpin 80s linear infinite}
.rdc-qf__ring li{position:absolute;left:50%;top:50%;width:132px;margin:-36px 0 0 -66px;transform:rotate(var(--a)) translateY(-37cqw) rotate(calc(var(--a) * -1));text-align:center;padding:10px;border-radius:12px;background:rgba(255,255,255,.06);border:1px solid rgba(255,255,255,.16);transition:background .3s,border-color .3s}
.rdc-qf__ring li:hover{background:rgba(127,224,218,.14);border-color:#7FE0DA}
.rdc-qf__ring li strong{display:block;font:800 .78rem var(--body);letter-spacing:.12em;color:#7FE0DA}
.rdc-qf__ring li span{font-size:.8rem;color:#DDE6FF}
.rdc-qf__ring .rdc-qf__core{width:96px;height:96px;margin:-48px 0 0 -48px;transform:none;border-radius:50%;display:grid;place-items:center;background:#fff;color:var(--r-navy);border:0;padding:0}

/* mid cta */
.rdc-mid{background:linear-gradient(100deg,var(--r-char),#0B22A8);color:#fff;padding:clamp(26px,4vw,40px) 0}
.rdc-mid__in{display:flex;align-items:center;justify-content:space-between;gap:24px;flex-wrap:wrap}
.rdc-mid strong{display:block;font:700 clamp(1.15rem,2vw,1.45rem) var(--display)}
.rdc-mid span{color:#DCE4FF}

/* selector */
.rdc-sel{display:grid;grid-template-columns:repeat(3,1fr);gap:14px}
.rdc-sel__card{--acc:var(--r-teal);padding:26px;border-radius:20px;background:#fff;border:1px solid var(--r-line);border-top:4px solid var(--acc);transition:transform .3s,box-shadow .3s}
.rdc-sel__card1{--acc:var(--r-blue)}.rdc-sel__card2{--acc:var(--r-gold)}
.rdc-sel__card:hover{transform:translateY(-4px);box-shadow:0 24px 44px -32px var(--acc)}
.rdc-sel__ic{width:50px;height:50px;border-radius:14px;display:grid;place-items:center;background:color-mix(in srgb,var(--acc) 12%,#fff);color:var(--acc);margin-bottom:14px}
.rdc-sel__card h3{font-size:1.2rem;color:var(--r-navy)}
.rdc-sel__l{font:700 .72rem var(--body);letter-spacing:.12em;text-transform:uppercase;color:var(--r-muted)}
.rdc-sel__card ul{list-style:none;margin:10px 0 16px;padding:0;display:flex;flex-wrap:wrap;gap:6px}
.rdc-sel__card li{padding:5px 10px;border-radius:999px;background:var(--r-soft);font-weight:600;font-size:.84rem}

/* loop */
.rdc-sec--loop{background:radial-gradient(700px 500px at 75% 50%,#E8EEFF 0%,transparent 65%),#fff}
.rdc-loopwrap{display:grid;grid-template-columns:minmax(0,.8fr) minmax(0,1.2fr);gap:clamp(24px,4vw,56px);align-items:center}
.rdc-loopwrap>*{min-width:0}
.rdc-loop svg{width:100%;max-width:600px;display:block;margin:auto;overflow:visible}
.rdc-loop__track{fill:none;stroke:#E3E8F3;stroke-width:16}
.rdc-loop__draw{fill:none;stroke:url(#none);stroke:var(--r-blue);stroke-width:4;stroke-linecap:round;stroke-dasharray:1;stroke-dashoffset:1;transition:stroke-dashoffset 3s cubic-bezier(.2,.7,.2,1)}
.rdc-loop.is-in .rdc-loop__draw{stroke-dashoffset:0}
.rdc-loop__pkt{fill:var(--r-gold)}
.rdc-loop__node{opacity:0;transition:opacity .5s;transition-delay:calc(.3s + var(--i)*.3s)}
.rdc-loop.is-in .rdc-loop__node{opacity:1}
.rdc-loop__node circle{fill:#fff;stroke:var(--r-blue);stroke-width:2}
.rdc-loop__node text{font:700 11px var(--display);fill:var(--r-navy)}
.rdc-loop__node.is-learn circle{fill:var(--r-gold);stroke:var(--r-gold)}
.rdc-loop__node.is-learn text{fill:#fff}
.rdc-loop__core circle{fill:var(--r-navy)}
.rdc-loop__core text{font:700 19px var(--display);fill:#fff}
.rdc-loop__core .rdc-loop__ck{font:800 10px var(--body);letter-spacing:.16em;fill:#E7C873}

/* why + capabilities */
.rdc-why{display:grid;grid-template-columns:repeat(3,1fr);gap:14px}
.rdc-why__card{padding:22px;border-radius:18px;background:#fff;border:1px solid var(--r-line)}
.rdc-why__card>span{width:42px;height:42px;border-radius:12px;display:grid;place-items:center;background:var(--r-navy);color:#fff;margin-bottom:14px}
.rdc-why__card h3{font-size:1.02rem;color:var(--r-navy)}
.rdc-why__card p{margin:0;font-size:.88rem;color:var(--r-muted)}
.rdc-cap{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin-top:clamp(36px,5vw,56px)}
.rdc-cap__col{display:flex;flex-direction:column;padding:20px;border-radius:16px;background:#fff;border:1px solid var(--r-line);text-decoration:none;color:var(--r-navy);--hov:var(--r-teal)}
.rdc-cap__h{display:flex;align-items:center;gap:8px;font:700 1.05rem var(--display);margin-bottom:10px}
.rdc-cap__h .rc-ico{color:var(--r-teal)}
.rdc-cap__col ul{list-style:none;margin:0 0 14px;padding:0}
.rdc-cap__col li{padding:6px 0;border-top:1px dashed var(--r-line);font-size:.9rem}
.rdc-cap__go{margin-top:auto;display:inline-flex;align-items:center;gap:6px;font-weight:700;font-size:.86rem;color:var(--r-blue)}

/* example */
.rdc-ex{margin-top:clamp(48px,6vw,80px)}
.rdc-ex ol{list-style:none;margin:0 0 20px;padding:0;display:grid;grid-template-columns:repeat(7,1fr);gap:8px}
.rdc-ex li{padding:16px;border-radius:14px;background:var(--r-soft);position:relative}
.rdc-ex li span{font:800 1.2rem var(--display);color:var(--r-teal)}
.rdc-ex li strong{display:block;font:700 .95rem var(--display);color:var(--r-navy);margin:4px 0}
.rdc-ex li p{margin:0;font-size:.82rem;color:var(--r-muted)}
.rdc-ex li:last-child{background:var(--r-navy)}
.rdc-ex li:last-child strong{color:#fff}.rdc-ex li:last-child p{color:#C9D3F5}.rdc-ex li:last-child span{color:#E7C873}

/* team + tech */
.rdc-team{display:grid;grid-template-columns:repeat(5,1fr);gap:12px}
.rdc-team__card{display:flex;flex-direction:column;align-items:center;text-align:center;gap:8px;padding:22px 14px;border-radius:18px;background:#fff;border:1px solid var(--r-line);text-decoration:none;color:var(--r-navy)}
.rdc-team__ph{width:72px;height:72px;border-radius:50%;display:grid;place-items:center;overflow:hidden;background:var(--r-soft);color:var(--r-blue);box-shadow:0 0 0 4px #fff,0 0 0 5px var(--r-line)}
.rdc-team__ph img{width:100%;height:100%;object-fit:cover}
.rdc-team__role{font-size:.84rem;color:var(--r-muted)}
.rdc-team__role--only{font:700 .95rem/1.3 var(--display);color:var(--r-navy)}
.rdc-tech{margin-top:28px}

/* insights */
.rdc-ins{display:grid;grid-template-columns:repeat(3,1fr);gap:12px;margin-bottom:clamp(40px,5vw,64px)}
.rdc-ins__card{display:flex;flex-direction:column;gap:8px;padding:20px;border-radius:16px;background:#fff;border:1px solid var(--r-line);text-decoration:none;color:var(--r-navy);transition:transform .3s,border-color .3s,box-shadow .3s}
.rdc-ins__card:hover{transform:translateY(-3px);border-color:var(--r-teal);box-shadow:0 18px 36px -28px var(--r-navy)}
.rdc-ins__card.is-lead{background:linear-gradient(160deg,var(--r-navy),#0B2C5C);color:#fff;border:0;justify-content:flex-end}
.rdc-ins__k{font:700 .7rem var(--body);letter-spacing:.14em;text-transform:uppercase;color:var(--r-teal)}
.rdc-ins__card.is-lead .rdc-ins__k{color:#7FE0DA}
.rdc-ins__card strong{font:700 1rem/1.35 var(--display)}
.rdc-ins__card.is-lead strong{font-size:1.35rem}
.rdc-ins__go{margin-top:auto;display:inline-flex;align-items:center;gap:6px;font-size:.84rem;font-weight:700;color:var(--r-blue)}
.rdc-ins__card.is-lead .rdc-ins__go{color:#7FE0DA}
.rdc-cta{background:radial-gradient(700px 400px at 0% 0%,#1A2A6E 0%,transparent 70%),var(--r-char)!important}
.rdc-cta .rc-kicker{color:#E7C873!important}

/* responsive */
@media (max-width:1100px){
  .rdc-strip{grid-template-columns:repeat(4,1fr)}
  .rdc-flow__cols{grid-template-columns:1fr 1fr}
  .rdc-flow__col:nth-child(2):after{display:none}
  .rdc-icons--sm{grid-template-columns:repeat(3,1fr)}
  .rdc-cap{grid-template-columns:1fr 1fr}
  .rdc-team{grid-template-columns:repeat(3,1fr)}
  .rdc-ex ol{grid-template-columns:repeat(4,1fr)}
  .rdc-bp__grid{grid-template-columns:repeat(2,1fr)}
}
@media (max-width:900px){
  .rdc-hero__in,.rdc-intro,.rdc-cyc,.rdc-s1,.rdc-s4,.rdc-gate,.rdc-qf,.rdc-loopwrap{grid-template-columns:1fr}
  .rdc-lad{grid-template-columns:1fr 1fr;gap:10px}
  .rdc-lad li{border-radius:16px!important;margin:0}
  .rdc-lad li:after{display:none}
  .rdc-sel,.rdc-why,.rdc-del{grid-template-columns:1fr 1fr}
  .rdc-ins{grid-template-columns:1fr 1fr}
}
@media (max-width:640px){
  .rdc-hero h1{font-size:2.5rem}
  .rdc-hero .od-hero__ctas .btn,.rdc-mid .btn,.rdc-cta .od-hero__ctas .btn{width:100%}
  .rdc-hero__viz{max-width:340px}
  .rdc-strip{grid-template-columns:none;grid-auto-flow:column;grid-auto-columns:62%;overflow-x:auto;scroll-snap-type:x mandatory;margin-inline:-16px;padding:0 16px 6px;scrollbar-width:none}
  .rdc-strip li{scroll-snap-align:start}
  .rdc-strip__d{max-height:none;opacity:1}
  .rdc-cyc__wheel,.rdc-cyc__panel{display:none}
  .rdc-cyc__mob{display:block;list-style:none;margin:0;padding:0 0 0 18px;border-left:2px solid rgba(255,255,255,.2)}
  .rdc-cyc__mob>li{position:relative;padding-bottom:6px}
  .rdc-cyc__mob button{display:flex;gap:12px;align-items:center;width:100%;text-align:left;padding:12px 0;border:0;background:none;color:#fff;font:600 1rem/1.3 var(--display)}
  .rdc-cyc__mob button span{position:absolute;left:-35px;width:32px;height:32px;border-radius:50%;display:grid;place-items:center;background:#0E1A66;border:2px solid var(--c);font:800 .74rem var(--display)}
  .rdc-cyc__mob li.is-on button span{background:var(--c)}
  .rdc-cyc__mob div{padding:0 0 10px;color:#C9D3F5}
  .rdc-cyc__mob p{font-size:.9rem}
  .rdc-cyc__loop{display:flex;gap:8px;align-items:center;color:#E7C873;font-weight:700;font-size:.9rem;padding-top:8px}
  .rdc-stage__head{grid-template-columns:1fr;gap:4px}
  .rdc-stage__num{font-size:3rem}
  .rdc-icons,.rdc-icons--sm{grid-template-columns:1fr 1fr}
  .rdc-chain{flex-direction:column;align-items:stretch}
  .rdc-chain li{text-align:center}
  .rdc-chain li:not(:last-child):after{content:"↓";position:absolute;left:50%;bottom:-16px;margin:0;transform:translateX(-50%);font-size:.85rem}
  .rdc-chain{gap:14px}
  .rdc-bp__grid{grid-template-columns:1fr 1fr}
  .rdc-tree__lines{display:none}
  .rdc-tree__br{grid-template-columns:1fr;margin-top:10px}
  .rdc-mx__r{grid-template-columns:1fr}
  .rdc-mx__r--h{display:none}
  .rdc-mx__r span{padding:8px 16px}
  .rdc-mx__r span:first-child{padding-bottom:0;font-weight:600}
  .rdc-flow__cols{grid-template-columns:1fr}
  .rdc-flow__col:after{display:none}
  .rdc-ticks{grid-template-columns:1fr}
  .rdc-mon__grid{grid-template-columns:1fr}
  .rdc-mon__card:first-child{grid-row:auto}
  .rdc-qq{grid-template-columns:1fr}
  .rdc-lad,.rdc-sel,.rdc-why,.rdc-del,.rdc-cap,.rdc-ins,.rdc-team{grid-template-columns:1fr}
  .rdc-ins__card.is-lead{min-height:170px}
  .rdc-qf__ring{aspect-ratio:auto;width:100%;display:grid;gap:8px}
  .rdc-qf__ring:before{display:none}
  .rdc-qf__ring li{position:static;width:auto;margin:0;transform:none;text-align:left;display:flex;gap:10px;align-items:baseline}
  .rdc-qf__ring .rdc-qf__core{display:none}
  .rdc-ex ol{grid-template-columns:1fr}
}
@media (prefers-reduced-motion:reduce){
  .rdc *{animation:none!important;transition:none!important}
  .rdc-wheel__node,.rdc-chain li,.rdc-lad li,.rdc-gate li,.rdc-loop__node{opacity:1!important;transform:none!important}
  .rdc-loop__draw,.rdc-mon__line,.rdc-qq__tl{stroke-dashoffset:0!important}
  .rdc-mon__bar b,.rdc-qq__bar{transform:none!important}
}
@media (max-width:640px){.rdc-cyc__mob .rdc-out{color:var(--r-navy)}}

/* ===== Service-specific Why us (wu-) ===== */
.wu{--wu:#0B22A8;padding:clamp(64px,8vw,104px) 0;background:linear-gradient(180deg,#fff 0%,color-mix(in srgb,var(--wu) 5%,#F7F8FB) 100%);scroll-margin-top:120px;position:relative;overflow:hidden}
.wu:before{content:"";position:absolute;right:-160px;top:-160px;width:420px;height:420px;border-radius:50%;border:1px solid color-mix(in srgb,var(--wu) 18%,transparent);box-shadow:0 0 0 50px color-mix(in srgb,var(--wu) 4%,transparent),0 0 0 100px color-mix(in srgb,var(--wu) 2%,transparent);pointer-events:none}
.wu__in{display:grid;grid-template-columns:minmax(0,.85fr) minmax(0,1.15fr);gap:clamp(28px,5vw,64px);align-items:start;position:relative}
.wu__in>*{min-width:0}
.wu__lead{position:sticky;top:calc(var(--header-h) + 80px)}
.wu__k{display:inline-flex;align-items:center;gap:8px;font:700 .76rem var(--body);letter-spacing:.14em;text-transform:uppercase;color:var(--wu)}
.wu__k:before{content:"";width:22px;height:2px;background:currentColor;border-radius:2px}
.wu h2{font-size:clamp(1.6rem,3vw,2.3rem);margin:.4em 0 .4em}
.wu__lead>p{color:var(--muted);font-size:1.05rem}
.wu__proof{list-style:none;margin:16px 0 0;padding:0;display:flex;flex-wrap:wrap;gap:8px}
.wu__proof li{display:inline-flex;align-items:center;gap:6px;padding:7px 12px;border-radius:999px;background:#fff;border:1px solid color-mix(in srgb,var(--wu) 30%,#DDE2EC);font-weight:700;font-size:.82rem;color:var(--ink)}
.wu__proof .rc-ico{color:var(--wu)}
.wu__focus{margin-top:24px;padding:22px;border-radius:18px;background:var(--wu);color:#fff;animation:rcPanel .35s ease;box-shadow:0 24px 44px -30px var(--wu)}
.wu__fn{font:800 2rem/1 var(--display);opacity:.5}
.wu__focus strong{display:block;font:700 1.15rem var(--display);margin:8px 0 6px}
.wu__focus p{margin:0;color:rgba(255,255,255,.85);font-size:.95rem}
.wu__grid{list-style:none;margin:0;padding:0;display:grid;grid-template-columns:1fr 1fr;gap:12px;counter-reset:wu}
.wu__card{position:relative;display:flex;flex-direction:column;gap:8px;padding:22px;border-radius:18px;background:#fff;border:1px solid #DDE2EC;outline:none;cursor:default;transition:transform .3s,border-color .3s,box-shadow .3s}
.wu__card:before{content:"";position:absolute;left:0;top:18px;bottom:18px;width:3px;border-radius:2px;background:var(--wu);transform:scaleY(0);transition:transform .3s}
.wu__card.is-on,.wu__card:focus-visible{border-color:color-mix(in srgb,var(--wu) 45%,#DDE2EC);transform:translateY(-3px);box-shadow:0 20px 40px -30px var(--wu)}
.wu__card.is-on:before{transform:scaleY(1)}
.wu__n{position:absolute;top:16px;right:18px;font:800 .78rem var(--display);color:#B9C2D3}
.wu__ic{width:42px;height:42px;border-radius:12px;display:grid;place-items:center;background:color-mix(in srgb,var(--wu) 10%,#fff);color:var(--wu);transition:transform .3s}
.wu__card.is-on .wu__ic{transform:scale(1.08)}
.wu__card strong{font:700 1rem/1.3 var(--display);color:var(--ink)}
.wu__d{font-size:.88rem;color:var(--muted);line-height:1.5}
.wu-tabs{margin-top:0;--rc-ink:#07104F;--rc-muted:#525C78;--rc-line:#DDE2EC}
.wu-tabs .wu-tabs__why:not(.is-on){color:var(--brand);font-weight:700}
@media (max-width:900px){.wu__in{grid-template-columns:1fr}.wu__lead{position:static}.wu__focus{display:none}}
@media (max-width:640px){.wu__grid{grid-template-columns:1fr}}
@media (prefers-reduced-motion:reduce){.wu *{animation:none!important;transition:none!important}}

/* template enquiry form: stop long select options widening the page on mobile */
.enquire>*{min-width:0}
.card-form .form>*,.card-form .form__row>*,.card-form .field>*{min-width:0}
.card-form select{min-width:0;max-width:100%;width:100%;text-overflow:ellipsis}

/* ===== Data Processing & Analytics (dpa-) ===== */
.dpa{--od-navy:#07104F;--od-blue:#1E5BFF;--od-royal:#0B22A8;--od-sky:#E8EEFF;--od-teal:#0E9C88;--od-teal-soft:#E3F5F2;--od-line:#DDE2EC;--od-muted:#525C78;--od-paper:#F5F7FB;
  --r-navy:#07104F;--r-char:#1E2433;--r-blue:#0B22A8;--r-soft:#EEF2FB;--r-teal:#0E8A8A;--r-gold:#C99A2E;--r-line:#DDE2EC;--r-muted:#525C78;
  --d-ink:#07104F;--d-char:#161B2B;--d-blue:#0B22A8;--d-vio:#5A3FE0;--d-teal:#0E8A8A;--d-gold:#C99A2E;--d-coral:#C2603F;--d-line:#DDE2EC;--d-muted:#525C78;--d-soft:#F3F4FA;--d-grey:#A9B2C6}
.dpa .rc-kicker{color:var(--d-vio)}
.dpa .rc-head--light .rc-kicker{color:#B9AEFF}
.dpa-sec--soft{background:var(--d-soft)}
.dpa-sec--ink{background:radial-gradient(800px 400px at 90% 0%,#1F2A6B 0%,transparent 60%),linear-gradient(165deg,#0A0F2E,#121A45);color:#fff}
.dpa-sec--ink .od-muted{color:#C9D0EA}
.dpa-h3{font-size:clamp(1.25rem,2vw,1.55rem);margin:0 0 .4em}
.dpa-illus{display:inline-block;font:600 .68rem var(--body);letter-spacing:.06em;text-transform:uppercase;color:#7A849E;background:#fff;border:1px dashed #C9D0DE;border-radius:999px;padding:3px 9px;white-space:nowrap}
.dpa-illus--light{background:transparent;color:#B9C2E0;border-color:#ffffff40}
.dpa-grid{stroke:#E6E9F1;stroke-width:1}
.dpa-axis{stroke:#B9C2D3;stroke-width:1}
.dpa .f1{fill:var(--d-blue)}.dpa .f2{fill:#8E9BCB}.dpa .f3{fill:var(--d-teal)}.dpa .fx{fill:var(--d-coral)}
.dpa .s1{fill:none;stroke:var(--d-blue);stroke-width:2.2;stroke-linecap:round;stroke-linejoin:round}
.dpa .s2{fill:none;stroke:#A9B2C6;stroke-width:1.6;stroke-linecap:round}
.dpa .a1{fill:#0B22A81f}
.dpa .p1{fill:var(--d-blue)}.dpa .p2{fill:#8E9BCB}.dpa .p3{fill:#D7DCEC}
.dpa .d1{stroke:var(--d-blue)}.dpa .d2{stroke:#8E9BCB}.dpa .d3{stroke:var(--d-teal)}
.dpa .ring{fill:none;stroke:var(--d-coral);stroke-width:1.5;stroke-dasharray:3 3}
.dpa-a{fill:#5A3FE01f}
.dpa-l{fill:none;stroke:var(--d-vio);stroke-width:2.4;stroke-linecap:round;stroke-linejoin:round;vector-effect:non-scaling-stroke}
.dpa-dots{fill:none;stroke:#C3CADB;stroke-width:4.2;stroke-linecap:round}
.dpa-ticks{list-style:none;margin:14px 0 0;padding:0;display:grid;gap:8px}
.dpa-ticks li{display:flex;align-items:center;gap:8px;font-weight:600;color:var(--d-ink)}
.dpa-ticks .rc-ico{color:var(--d-teal);flex:none}
.dpa-chips{display:flex;flex-wrap:wrap;gap:8px;align-items:center;margin-top:16px}
.dpa-chips__k{font:700 .72rem var(--body);letter-spacing:.12em;text-transform:uppercase;color:var(--d-muted);margin-right:4px}
.dpa-chips span:not(.dpa-chips__k){padding:6px 12px;border-radius:999px;background:#fff;border:1px solid var(--d-line);font-size:.86rem;font-weight:600;color:var(--d-ink)}
.dpa-blk{margin-top:clamp(48px,6vw,80px)}
.dpa-blk__h{display:grid;grid-template-columns:minmax(0,.8fr) minmax(0,1.2fr);gap:24px;align-items:end;margin-bottom:22px}
.dpa-blk__h h3{font-size:clamp(1.35rem,2.4vw,1.85rem);margin:0}
.dpa-blk__h p{margin:0;color:var(--d-muted)}
.dpa-two{display:grid;grid-template-columns:minmax(0,.85fr) minmax(0,1.15fr);gap:clamp(24px,4vw,56px);align-items:center}
.dpa-two>*{min-width:0}
.dpa-two+.dpa-two,.dpa-two+.dpa-blk{margin-top:clamp(48px,6vw,80px)}
.dpa-two--flip{grid-template-columns:minmax(0,1.15fr) minmax(0,.85fr)}
.dpa-quote{font:600 clamp(1.1rem,1.7vw,1.32rem)/1.5 var(--display);color:var(--d-ink);border-left:3px solid var(--d-coral);padding-left:18px;margin:0 0 16px}
.dpa-quote--sm{font-size:1.05rem;border-color:var(--d-vio)}

/* hero */
.dpa-hero{background:radial-gradient(760px 520px at 80% 30%,#ECE9FF 0%,transparent 62%),linear-gradient(180deg,#fff,#F6F7FC);padding:clamp(32px,4vw,56px) 0 clamp(28px,3vw,40px);border-bottom:1px solid var(--d-line);overflow:hidden}
.dpa-hero__in{display:grid;grid-template-columns:minmax(0,.95fr) minmax(0,1.05fr);gap:clamp(24px,4vw,56px);align-items:center}
.dpa-hero__in>*{min-width:0}
.dpa-eyebrow{display:inline-flex;align-items:center;gap:8px;font:700 .76rem var(--body);letter-spacing:.14em;text-transform:uppercase;color:var(--d-vio);margin-bottom:16px}
.dpa-hero h1{font-size:clamp(2.4rem,4.8vw,4rem);color:var(--d-ink);margin-bottom:.2em;line-height:1.05}
.dpa-hero__sub{font:700 clamp(1.2rem,2vw,1.6rem)/1.3 var(--display);color:var(--d-blue);margin:0 0 14px}
.dpa-hero__body{color:var(--d-muted);font-size:1.05rem;max-width:56ch;margin:0 0 24px}
.dpa .dpa-btn{background:var(--d-ink);color:#fff}
.dpa .dpa-btn:hover{background:var(--d-vio)}
.dpa-hero__viz{display:grid;gap:12px}
.dpa-hv{background:#fff;border:1px solid var(--d-line);border-radius:20px;padding:16px;box-shadow:0 30px 60px -44px #1E2A6B}
.dpa-hv__svg{width:100%;height:auto;display:block}
.dpa-hv__zone{fill:#F6F7FB;stroke:#E2E6EF;stroke-dasharray:4 4}
.dpa-hv__raw{fill:#A9B2C6;animation:dpaJit 3.6s ease-in-out infinite alternate;animation-delay:calc(var(--i)*-.4s)}
.dpa-hv__raw.is-b{fill:#E0A48F}
.dpa-hv__x{stroke:#C2603F;stroke-width:1.4;animation:dpaJit 3s ease-in-out infinite alternate;animation-delay:calc(var(--i)*-.3s)}
@keyframes dpaJit{to{transform:translate(2px,-2px)}}
.dpa-hv__in{fill:none;stroke:#C9CFE0;stroke-width:1.3;stroke-dasharray:4 6;animation:rcDash 2.4s linear infinite}
.dpa-hv__out{fill:none;stroke:#B6ABF5;stroke-width:1.3;stroke-dasharray:4 6;animation:rcDash 2.4s linear infinite}
.dpa-hv__core{fill:var(--d-ink)}
.dpa-hv__ct{fill:#fff;font:800 15px var(--display)}
.dpa-hv__cs{fill:#B9C2E0;font:600 9.5px var(--body);letter-spacing:.06em;text-transform:uppercase}
.dpa-hv__cell{transform-box:fill-box;transform-origin:center;animation:dpaPop .5s ease both;animation-delay:calc(var(--i)*60ms)}
@keyframes dpaPop{from{transform:scale(.3);opacity:0}}
.dpa-hv__lbl{font:700 10px var(--body);letter-spacing:.12em;text-transform:uppercase;fill:#7A849E}
.dpa-hv__st{list-style:none;margin:12px 0 0;padding:0;display:grid;grid-template-columns:repeat(8,1fr);gap:4px;counter-reset:hv}
.dpa-hv__st li{position:relative;text-align:center;font:700 .68rem var(--body);color:#8A93AA;padding:22px 2px 0;transition:color .3s}
.dpa-hv__st li:before{content:"";position:absolute;top:6px;left:50%;width:10px;height:10px;margin-left:-5px;border-radius:50%;background:#D7DCEA;transition:background .3s,box-shadow .3s}
.dpa-hv__st li:after{content:"";position:absolute;top:10px;left:calc(50% + 7px);right:calc(-50% + 7px);height:2px;background:#E2E6EF}
.dpa-hv__st li:last-child:after{display:none}
.dpa-hv__st li.is-done{color:var(--d-ink)}
.dpa-hv__st li.is-done:before{background:var(--d-vio)}
.dpa-hv__st li.is-done:after{background:#B6ABF5}
.dpa-hv__st li.is-cur:before{box-shadow:0 0 0 5px #5A3FE033}
.dpa-hv__end{margin-top:10px;display:flex;align-items:center;justify-content:center;gap:8px;padding:9px;border-radius:12px;background:#F1EFFD;color:var(--d-vio);font-size:.92rem;transition:background .4s,color .4s}
.dpa-hv__end.is-on{background:var(--d-vio);color:#fff}
.dpa-mini{background:var(--d-char);border-radius:18px;padding:12px;color:#fff}
.dpa-mini__head{display:flex;justify-content:space-between;align-items:center;margin-bottom:10px}
.dpa-mini__head>span:first-child{display:flex;gap:5px}
.dpa-mini__head>span:first-child i{width:8px;height:8px;border-radius:50%;background:#ffffff30}
.dpa-mini .dpa-illus{background:transparent;color:#B9C2E0;border-color:#ffffff38}
.dpa-mini__grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:8px}
.dpa-mini__t{background:#ffffff0d;border:1px solid #ffffff14;border-radius:10px;padding:8px 10px;min-height:78px;display:flex;flex-direction:column;gap:4px;min-width:0}
.dpa-mini__t>span{font:700 .64rem var(--body);letter-spacing:.1em;text-transform:uppercase;color:#9DA8CC}
.dpa-mini__kpi{gap:3px}
.dpa-mini__kpi>div{display:grid;grid-template-columns:36px 1fr 12px;align-items:center;gap:6px;font-size:.7rem;color:#C9D0EA}
.dpa-mini__kpi svg{width:100%;height:14px}
.dpa-mini__kpi path{fill:none;stroke:#B6ABF5;stroke-width:1.6}
.dpa-mini__kpi b,.dpa-desc__kpi b{font-size:.62rem}
.dpa-mini .is-up{color:#4FD1B5}.dpa-mini .is-dn{color:#F0A08A}
.dpa-mini__trend svg{width:100%;height:46px}
.dpa-mini .dpa-a{fill:#B6ABF52a}.dpa-mini .dpa-l{stroke:#B6ABF5}
.dpa-mini__bars>div{flex:1;display:flex;align-items:flex-end;gap:5px;height:46px}
.dpa-mini__bars i{flex:1;height:calc(var(--h)*100%);background:linear-gradient(#6E8BFF,#3B5BDB);border-radius:3px 3px 0 0;transform-origin:bottom;animation:dpaGrow .8s ease both;animation-delay:calc(var(--i)*90ms)}
@keyframes dpaGrow{from{transform:scaleY(0)}}
.dpa-mini__seg svg{width:48px;height:48px;align-self:center}
.dpa-mini__seg circle{fill:none;stroke-width:8}
.dpa-mini__seg circle:nth-child(1){stroke:#6E8BFF}.dpa-mini__seg circle:nth-child(2){stroke:#B6ABF5}.dpa-mini__seg circle:nth-child(3){stroke:#4FD1B5}
.dpa-mini__map svg{width:100%;height:auto}
.dpa-mini__map .dpa-dots{stroke:#ffffff45;stroke-width:6}
.dpa-mini__bub{fill:#B6ABF5;fill-opacity:.6;stroke:#fff;stroke-width:3}
.dpa-mini__q ul{list-style:none;margin:0;padding:0;display:grid;gap:3px;font-size:.72rem;color:#C9D0EA}
.dpa-mini__q li{display:flex;align-items:center;gap:5px}
.dpa-mini__q .rc-ico{color:#4FD1B5}
.dpa-strip{list-style:none;margin:clamp(24px,3vw,36px) 0 0;padding:0;display:grid;grid-template-columns:repeat(4,1fr);gap:10px}
.dpa-strip li{display:flex;align-items:center;gap:10px;padding:14px 16px;border-radius:14px;background:#fff;border:1px solid var(--d-line);font:700 .95rem var(--display);color:var(--d-ink)}
.dpa-strip li>span{width:36px;height:36px;border-radius:10px;display:grid;place-items:center;background:#F1EFFD;color:var(--d-vio);flex:none}
.dpa-strip__ok{color:var(--d-teal);flex:none}

/* problem */
.dpa-probwrap{display:grid;grid-template-columns:minmax(0,.9fr) minmax(0,1.1fr);gap:clamp(28px,5vw,64px);align-items:start}
.dpa-probwrap>*{min-width:0}
.dpa-prob{display:grid;gap:14px}
.dpa-prob__lane{border-radius:18px;padding:18px}
.dpa-prob__lane--bad{background:#FBF4F1;border:1px dashed #E4B7A7}
.dpa-prob__lane--good{background:var(--d-ink);color:#fff}
.dpa-prob__k{display:flex;align-items:center;gap:7px;font:700 .76rem var(--body);letter-spacing:.12em;text-transform:uppercase;margin-bottom:12px}
.dpa-prob__lane--bad .dpa-prob__k{color:var(--d-coral)}
.dpa-prob__lane--good .dpa-prob__k{color:#4FD1B5}
.dpa-prob ol{list-style:none;margin:0;padding:0;display:flex;flex-wrap:wrap;gap:8px 18px}
.dpa-prob__lane--bad li{position:relative;padding:6px 11px;border-radius:8px;background:#fff;border:1px solid #EBD0C6;font-size:.86rem;font-weight:600;color:#6B4A40;transform:rotate(var(--r));opacity:0;transition:opacity .4s,transform .4s;transition-delay:calc(var(--i)*70ms)}
.dpa-prob__lane--bad li:not(:last-child):after{content:"→";position:absolute;right:-15px;top:50%;transform:translateY(-50%);color:#D19A87;font-size:.8rem}
.dpa-prob__lane--bad li:last-child{background:var(--d-coral);color:#fff;border-color:var(--d-coral)}
.dpa-prob__lane--good ol{gap:8px}
.dpa-prob__lane--good li{display:flex;align-items:center;gap:6px;padding:7px 12px;border-radius:999px;background:#ffffff14;font:700 .88rem var(--display);opacity:0;transform:translateY(8px);transition:opacity .4s,transform .4s;transition-delay:calc(.5s + var(--i)*80ms)}
.dpa-prob__lane--good li span{font-size:.7rem;color:#B9AEFF}
.dpa-prob__lane--good li:last-child{background:#4FD1B5;color:var(--d-ink)}
.dpa-prob__lane--good li:last-child span{color:var(--d-ink)}
.dpa-prob.is-in li{opacity:1}
.dpa-prob.is-in .dpa-prob__lane--good li{transform:none}

/* solution */
.dpa-sol{list-style:none;margin:8px 0 0;padding:0;display:grid;grid-template-columns:repeat(8,minmax(0,1fr));gap:10px;position:relative}
.dpa-sol:before{content:"";position:absolute;left:4%;right:4%;top:66px;height:2px;background:linear-gradient(90deg,#B6ABF5,#4FD1B5);transform:scaleX(0);transform-origin:left;transition:transform 1.4s ease}
.dpa-sol.is-in:before{transform:scaleX(1)}
.dpa-sol li{position:relative;display:flex;flex-direction:column;align-items:center;text-align:center;gap:8px;opacity:0;transform:translateY(12px);transition:opacity .45s,transform .45s;transition-delay:calc(var(--i)*110ms)}
.dpa-sol.is-in li{opacity:1;transform:none}
.dpa-sol__n{font:800 1.5rem var(--display);color:#ffffff40}
.dpa-sol__ic{position:relative;z-index:1;width:48px;height:48px;border-radius:50%;display:grid;place-items:center;background:#161D4A;border:2px solid #B6ABF5;color:#fff}
.dpa-sol li:last-child .dpa-sol__ic{background:#4FD1B5;border-color:#4FD1B5;color:var(--d-ink)}
.dpa-sol strong{font:700 1rem var(--display)}
.dpa-sol__d{font-size:.8rem;color:#C9D0EA;line-height:1.4}

/* included */
.dpa-inc{display:grid;grid-template-columns:repeat(12,1fr);gap:14px}
.dpa-inc__m{border-radius:20px;padding:clamp(18px,2.4vw,26px);display:flex;flex-direction:column;gap:14px;min-width:0;position:relative}
.dpa-inc__m>.dpa-illus{align-self:flex-start}
.dpa-inc__m header{display:flex;gap:12px;align-items:flex-start}
.dpa-inc__m h3{margin:0 0 4px;font-size:1.15rem}
.dpa-inc__m header p{margin:0;font-size:.9rem;color:var(--d-muted)}
.dpa-inc__ic{width:42px;height:42px;border-radius:12px;display:grid;place-items:center;flex:none}
.dpa-inc__m--clean{grid-column:span 7;background:#fff;border:1px solid var(--d-line)}
.dpa-inc__m--clean .dpa-inc__ic{background:#E3F5F2;color:var(--d-teal)}
.dpa-inc__m--code{grid-column:span 5;background:#F1EFFD}
.dpa-inc__m--code .dpa-inc__ic{background:var(--d-vio);color:#fff}
.dpa-inc__m--wt{grid-column:span 5;background:var(--d-soft);border:1px solid var(--d-line)}
.dpa-inc__m--wt .dpa-inc__ic{background:#fff;color:var(--d-blue)}
.dpa-inc__m--drv{grid-column:span 7;background:var(--d-ink);color:#fff}
.dpa-inc__m--drv header p{color:#C9D0EA}
.dpa-inc__m--drv h3{color:#fff}
.dpa-inc__m--drv .dpa-inc__ic{background:#ffffff1a;color:#B6ABF5}
.dpa-inc__m--drv .dpa-illus{background:transparent;color:#B9C2E0;border-color:#ffffff40}
.dpa-inc__note{grid-column:1/-1}
.dpa-qc{border:1px solid var(--d-line);border-radius:12px;overflow:hidden;font-size:.85rem}
.dpa-qc__h,.dpa-qc__r{display:grid;grid-template-columns:1fr 1fr;padding:8px 14px}
.dpa-qc__h{background:var(--d-soft);font:700 .7rem var(--body);letter-spacing:.1em;text-transform:uppercase;color:var(--d-muted)}
.dpa-qc__r{border-top:1px solid #EEF0F5;font-family:ui-monospace,Menlo,monospace;color:var(--d-ink)}
.dpa-qc__r span:last-child{display:flex;align-items:center;gap:6px;font-family:var(--body);font-weight:600;color:var(--d-teal)}
.dpa-qc__r.is-bad{background:#FDF5F2}
.dpa-qc__r.is-bad span:first-child{text-decoration:line-through;color:#B79A90}
.dpa-qc__r.is-bad span:last-child{color:var(--d-coral)}
.dpa-code{display:grid;grid-template-columns:minmax(0,1.3fr) auto minmax(0,1fr);gap:10px;align-items:center}
.dpa-code ul{list-style:none;margin:0;padding:0;display:grid;gap:6px}
.dpa-code__v li{padding:7px 10px;border-radius:10px;background:#fff;font-size:.82rem;color:var(--d-ink);border-left:3px solid var(--c)}
.dpa-code__arrow{font-size:1.4rem;color:var(--d-vio)}
.dpa-code__c li{padding:9px 12px;border-radius:999px;background:var(--c);color:#fff;font:700 .84rem var(--display);text-align:center}
.dpa-code .c0{--c:#0B22A8}.dpa-code .c1{--c:#0E8A8A}.dpa-code .c2{--c:#C99A2E}
.dpa-wt{display:grid;grid-template-columns:repeat(4,1fr);gap:10px;align-items:end}
.dpa-wt__g{display:flex;flex-direction:column;align-items:center;gap:6px;font-size:.75rem;color:var(--d-muted);font-weight:600}
.dpa-wt__bars{position:relative;width:100%;height:110px;display:flex;align-items:flex-end;justify-content:center;gap:5px}
.dpa-wt__bars i{width:34%;height:calc(var(--h)*100%);border-radius:4px 4px 0 0}
.dpa-wt i.u{background:#C3CADB}.dpa-wt i.w{background:var(--d-blue)}
.dpa-wt__bars b{position:absolute;left:8%;right:8%;bottom:calc(var(--h)*100%);border-top:2px dashed var(--d-coral)}
.dpa-wt__lg{grid-column:1/-1;display:flex;gap:14px;flex-wrap:wrap;font-size:.76rem;color:var(--d-muted)}
.dpa-wt__lg span{display:flex;align-items:center;gap:5px}
.dpa-wt__lg i{width:10px;height:10px;border-radius:2px}
.dpa-wt__lg b{width:14px;border-top:2px dashed var(--d-coral)}
.dpa-drv{display:grid;gap:8px}
.dpa-drv__r{display:grid;grid-template-columns:130px 1fr;align-items:center;gap:10px;font-size:.86rem;color:#E4E8F7}
.dpa-drv__r i{height:12px;border-radius:6px;background:linear-gradient(90deg,#6E8BFF,#B6ABF5);width:calc(var(--w)*100%);transform-origin:left;animation:dpaGrowX 1s ease both;animation-delay:calc(var(--i)*100ms)}
@keyframes dpaGrowX{from{transform:scaleX(0)}}
.dpa-drv__ax{display:flex;justify-content:space-between;margin-left:140px;font-size:.7rem;color:#9DA8CC;text-transform:uppercase;letter-spacing:.08em}

/* pipeline */
.dpa-pipe{max-width:1100px;margin:0 auto}
.dpa-pipe__rail{list-style:none;margin:0;padding:0;display:grid;grid-template-columns:repeat(9,minmax(0,1fr));gap:6px}
.dpa-pipe__rail button{width:100%;display:flex;flex-direction:column;align-items:center;gap:6px;padding:12px 4px;border:0;background:none;cursor:pointer;color:var(--d-muted);text-align:center;border-radius:14px;transition:background .25s,color .25s}
.dpa-pipe__rail button:hover{background:#fff}
.dpa-pipe__rail button:focus-visible{outline:2px solid var(--d-vio);outline-offset:2px}
.dpa-pipe__dot{width:46px;height:46px;border-radius:14px;display:grid;place-items:center;background:#fff;border:1px solid var(--d-line);color:var(--d-blue);transition:all .25s}
.dpa-pipe__rail .is-past .dpa-pipe__dot{background:#E8E5FB;border-color:#D4CEF6;color:var(--d-vio)}
.dpa-pipe__rail .is-on .dpa-pipe__dot{background:var(--d-vio);border-color:var(--d-vio);color:#fff;transform:translateY(-3px);box-shadow:0 14px 26px -16px var(--d-vio)}
.dpa-pipe__n{font:700 .64rem var(--body);letter-spacing:.1em;text-transform:uppercase;color:#8A93AA}
.dpa-pipe__t{font:700 .84rem/1.25 var(--display);color:var(--d-ink)}
.dpa-pipe__bar{height:4px;border-radius:2px;background:#E2E6EF;margin:10px 0 18px;overflow:hidden}
.dpa-pipe__bar i{display:block;height:100%;background:linear-gradient(90deg,var(--d-blue),var(--d-vio));transition:width .45s ease}
.dpa-pipe__panel{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr) auto;gap:24px;align-items:center;background:#fff;border:1px solid var(--d-line);border-radius:20px;padding:clamp(20px,3vw,32px);animation:rcPanel .35s ease}
.dpa-pipe__pn{font:700 .72rem var(--body);letter-spacing:.12em;text-transform:uppercase;color:var(--d-vio)}
.dpa-pipe__panel h3{display:flex;align-items:center;gap:10px;margin:6px 0 8px;font-size:1.4rem}
.dpa-pipe__panel h3 .rc-ico{color:var(--d-vio)}
.dpa-pipe__panel p{margin:0;color:var(--d-muted)}
.dpa-pipe__panel ul{list-style:none;margin:0;padding:0;display:grid;gap:8px}
.dpa-pipe__panel li{display:flex;align-items:center;gap:8px;padding:9px 12px;border-radius:10px;background:var(--d-soft);font-weight:600;font-size:.92rem;animation:rcPanel .4s ease both;animation-delay:calc(var(--i)*60ms)}
.dpa-pipe__panel li .rc-ico{color:var(--d-teal)}
.dpa-pipe__nav{display:flex;flex-direction:column;gap:8px}
.dpa-pipe__nav button,.dpa-mat__panel button{width:40px;height:40px;border-radius:50%;border:1px solid var(--d-line);background:#fff;cursor:pointer;font-size:1rem;color:var(--d-ink)}
.dpa-pipe__nav button:hover{border-color:var(--d-vio);color:var(--d-vio)}

/* objectives */
.dpa-obj{list-style:none;margin:0 0 8px;padding:0;display:grid;grid-template-columns:repeat(6,1fr);gap:10px}
.dpa-obj li{display:flex;flex-direction:column;gap:8px;padding:14px;border-radius:14px;border:1px solid var(--d-line);font:700 .95rem var(--display);color:var(--d-ink);background:#fff}
.dpa-obj svg{width:30px;height:30px;fill:none;stroke:var(--d-vio);stroke-width:2;stroke-linecap:round;stroke-linejoin:round}

/* dashboard */
.dpa-dash{display:grid;grid-template-columns:190px minmax(0,1fr);gap:14px;background:#F7F8FC;border:1px solid var(--d-line);border-radius:22px;padding:14px}
.dpa-dash__f{background:#fff;border:1px solid var(--d-line);border-radius:16px;padding:14px;display:flex;flex-direction:column;gap:10px;align-items:flex-start}
.dpa-dash__fk{display:flex;align-items:center;gap:6px;font:700 .7rem var(--body);letter-spacing:.12em;text-transform:uppercase;color:var(--d-muted)}
.dpa-dash__fg{display:grid;gap:5px;width:100%}
.dpa-dash__fg--row{grid-template-columns:1fr 1fr}
.dpa-dash__f .dpa-illus{white-space:normal;margin-top:auto;line-height:1.4}
.dpa-dash__fg button,.dpa-geo__tabs button,.dpa-sp__tabs button,.dpa-exp__dims button{padding:8px 10px;border-radius:10px;border:1px solid var(--d-line);background:#fff;font:600 .84rem var(--body);color:var(--d-ink);cursor:pointer;text-align:left;transition:all .2s}
.dpa-dash__fg button:hover,.dpa-geo__tabs button:hover,.dpa-sp__tabs button:hover,.dpa-exp__dims button:hover{border-color:var(--d-vio)}
.dpa-dash__fg button.is-on,.dpa-geo__tabs button.is-on,.dpa-sp__tabs button.is-on,.dpa-exp__dims button.is-on{background:var(--d-ink);border-color:var(--d-ink);color:#fff}
.dpa-dash__main{display:grid;gap:12px;min-width:0}
.dpa-dash__kpis{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:10px}
.dpa-dash__kpi{background:#fff;border:1px solid var(--d-line);border-radius:14px;padding:10px 12px;display:grid;gap:4px}
.dpa-dash__kpi>span{font:700 .72rem var(--body);color:var(--d-muted)}
.dpa-dash__kpi svg{width:100%;height:24px}
.dpa-dash__kpi path{fill:none;stroke:var(--d-vio);stroke-width:1.8}
.dpa-dash__kpi b{font-size:.72rem}
.dpa-dash__kpi .is-up{color:var(--d-teal)}.dpa-dash__kpi .is-dn{color:var(--d-coral)}
.dpa-dash__row{display:grid;grid-template-columns:minmax(0,1.2fr) minmax(0,1fr);gap:12px}
.dpa-dash__card{background:#fff;border:1px solid var(--d-line);border-radius:14px;padding:12px 14px;min-width:0}
.dpa-dash__ct{display:block;font:700 .72rem var(--body);letter-spacing:.08em;text-transform:uppercase;color:var(--d-muted);margin-bottom:8px}
.dpa-dash__trend svg{width:100%;height:130px;display:block}
.dpa-dash__prev{fill:none;stroke:#B9C2D3;stroke-width:1.6;stroke-dasharray:5 4;vector-effect:non-scaling-stroke}
.dpa-draw{stroke-dasharray:1200;stroke-dashoffset:1200;animation:dpaDraw 1.2s ease forwards}
@keyframes dpaDraw{to{stroke-dashoffset:0}}
.dpa-anom{fill:none;stroke:var(--d-coral);stroke-width:2;vector-effect:non-scaling-stroke}
.dpa-dash__lg{display:flex;flex-wrap:wrap;gap:6px 14px;align-items:center;font-size:.76rem;color:var(--d-muted);margin-top:8px}
.dpa-dash__lg span{display:flex;align-items:center;gap:5px}
.dpa-dash__lg i{width:14px;height:3px;border-radius:2px}
.dpa-dash__lg i.cur{background:var(--d-vio)}.dpa-dash__lg i.prv{background:repeating-linear-gradient(90deg,#B9C2D3 0 4px,transparent 4px 7px)}
.dpa-dash__lg i.an{width:10px;height:10px;border-radius:50%;border:2px solid var(--d-coral)}
.dpa-dash__lg i.fc{background:repeating-linear-gradient(90deg,var(--d-vio) 0 4px,transparent 4px 7px)}
.dpa-dash__lg i.band{height:10px;background:#5A3FE026}
.dpa-dash__lg i.trd{background:var(--d-gold)}
.dpa-dash__bars{display:flex;align-items:flex-end;gap:8px;height:140px}
.dpa-dash__bars button{flex:1;height:100%;display:flex;flex-direction:column;justify-content:flex-end;align-items:center;gap:5px;background:none;border:0;padding:0;cursor:pointer}
.dpa-dash__bars i{width:100%;height:calc(var(--h)*100%);background:var(--d-blue);border-radius:6px 6px 0 0;transform-origin:bottom;animation:dpaGrow .6s ease both;animation-delay:calc(var(--i)*60ms);transition:background .2s}
.dpa-dash__bars button:hover i,.dpa-dash__bars button:focus-visible i{background:var(--d-vio)}
.dpa-dash__bars span{font-size:.72rem;color:var(--d-muted);font-weight:600}
.dpa-dash__drill{display:grid;gap:10px;animation:rcPanel .3s ease}
.dpa-dash__drill>div{display:grid;grid-template-columns:90px 1fr;align-items:center;gap:8px;font-size:.84rem;font-weight:600}
.dpa-dash__drill i{height:14px;border-radius:7px;background:linear-gradient(90deg,var(--d-vio),#B6ABF5);width:calc(var(--w)*100%);animation:dpaGrowX .6s ease both;transform-origin:left;animation-delay:calc(var(--i)*80ms)}
.dpa-dash__drill .rc-link{background:none;border:0;padding:0;cursor:pointer;justify-self:start;font-size:.86rem}
.dpa-heat{display:grid;gap:4px}
.dpa-heat__r{display:grid;grid-template-columns:70px repeat(6,1fr);gap:4px;align-items:center}
.dpa-heat__r>span{font-size:.74rem;color:var(--d-muted);font-weight:600}
.dpa-heat__r i{height:22px;border-radius:5px;background:color-mix(in srgb,var(--d-blue) calc(var(--v)*90% + 6%),#fff)}
.dpa-heat__x b{font:600 .7rem var(--body);color:#8A93AA;text-align:center}

/* gallery */
.dpa-princ{display:flex;align-items:center;gap:8px;font:700 1.05rem var(--display)!important;color:var(--d-vio)!important}
.dpa-gal{list-style:none;margin:0;padding:0;display:grid;grid-template-columns:repeat(3,1fr);gap:12px}
.dpa-gal li{display:grid;grid-template-columns:120px 1fr;grid-template-rows:auto auto;column-gap:14px;align-items:center;padding:14px;border-radius:16px;background:#fff;border:1px solid var(--d-line);outline:none;transition:border-color .25s,transform .25s,box-shadow .25s}
.dpa-gal li svg{grid-row:span 2;width:120px;height:70px}
.dpa-gal strong{font:700 1rem var(--display);color:var(--d-ink);align-self:end}
.dpa-gal li>span{font-size:.84rem;color:var(--d-muted);align-self:start}
.dpa-gal li.is-on{border-color:#B6ABF5;transform:translateY(-3px);box-shadow:0 18px 34px -26px var(--d-vio)}

/* geo */
.dpa-geo{background:#fff;border:1px solid var(--d-line);border-radius:22px;padding:14px}
.dpa-geo__tabs,.dpa-sp__tabs{display:flex;flex-wrap:wrap;gap:6px;margin-bottom:10px}
.dpa-geo__map svg{width:100%;height:auto;display:block}
.dpa-geo__b circle{fill:#5A3FE033;stroke:var(--d-vio);stroke-width:2;transform-box:fill-box;transform-origin:center;animation:dpaPop .5s ease both;animation-delay:calc(var(--i)*70ms)}
.dpa-geo__b text,.dpa-geo__o text{font:700 15px var(--body);fill:var(--d-ink)}
.dpa-geo__h{transform-box:fill-box;transform-origin:center;animation:dpaPop .6s ease both;animation-delay:calc(var(--i)*70ms)}
.dpa-geo__o rect{fill:color-mix(in srgb,var(--d-blue) calc(var(--v)*80% + 10%),#fff);animation:dpaPop .5s ease both;animation-delay:calc(var(--i)*70ms);transform-box:fill-box;transform-origin:center}
.dpa-geo__o text{fill:#fff;font-size:14px;paint-order:stroke;stroke:#0B22A855;stroke-width:2px}
.dpa-geo__lg{display:flex;align-items:center;gap:8px;flex-wrap:wrap;font-size:.76rem;color:var(--d-muted);margin-top:8px}
.dpa-geo__lg i{width:90px;height:8px;border-radius:4px;background:linear-gradient(90deg,#E3E7F4,var(--d-blue))}
.dpa-geo__lg .dpa-illus{margin-left:auto}

/* network */
.dpa-net{background:#0F1433;border-radius:22px;padding:14px;color:#fff}
.dpa-net svg{width:100%;height:auto;display:block}
.dpa-net__e{stroke:#ffffff26;stroke-width:1.2;transition:stroke .2s}
.dpa-net__e.is-bridge{stroke:#C99A2E99;stroke-width:2;stroke-dasharray:5 5;animation:rcDash 3s linear infinite}
.dpa-net__e.is-hot{stroke:#fff;stroke-width:2}
.dpa-net__n{stroke:#0F1433;stroke-width:2;transition:r .2s;cursor:default;outline:none}
.dpa-net__n.c0{fill:#6E8BFF}.dpa-net__n.c1{fill:#B6ABF5}.dpa-net__n.c2{fill:#4FD1B5}
.dpa-net__n.is-hub{stroke:#fff;stroke-width:2.5;cursor:pointer}
.dpa-net__n.is-on{stroke:#C99A2E;stroke-width:3}
.dpa-net__pulse{fill:none;stroke-width:1.5;transform-box:fill-box;transform-origin:center;animation:rcPulse 2.8s ease-out infinite;animation-delay:calc(var(--i)*.8s)}
.dpa-net__pulse.c0{stroke:#6E8BFF}.dpa-net__pulse.c1{stroke:#B6ABF5}.dpa-net__pulse.c2{stroke:#4FD1B5}
.dpa-net__lg{display:flex;flex-wrap:wrap;gap:6px 14px;align-items:center;font-size:.76rem;color:#C9D0EA;margin-top:6px}
.dpa-net__lg span{display:flex;align-items:center;gap:6px}
.dpa-net__lg i{display:inline-block}
.dpa-net__lg .hub{width:12px;height:12px;border-radius:50%;background:#6E8BFF;border:2px solid #fff}
.dpa-net__lg .nd{width:8px;height:8px;border-radius:50%;background:#B6ABF5}
.dpa-net__lg .ln{width:16px;height:2px;background:#ffffff60}
.dpa-net__lg .br{width:16px;border-top:2px dashed #C99A2E}
.dpa-net .dpa-illus{background:transparent;color:#B9C2E0;border-color:#ffffff40}

/* time series */
.dpa-ts{background:#fff;border:1px solid var(--d-line);border-radius:22px;padding:16px}
.dpa-ts svg{width:100%;height:auto;display:block}
.dpa-ts__hist{fill:none;stroke:var(--d-blue);stroke-width:2.4;stroke-linejoin:round;stroke-dasharray:1;stroke-dashoffset:1}
.dpa-ts.is-in .dpa-ts__hist{animation:dpaDrawP 1.6s ease forwards}
@keyframes dpaDrawP{to{stroke-dashoffset:0}}
.dpa-ts__fc{fill:none;stroke:var(--d-vio);stroke-width:2.4;stroke-dasharray:6 5;opacity:0;transition:opacity .6s 1.4s}
.dpa-ts.is-in .dpa-ts__fc,.dpa-ts.is-in .dpa-ts__band{opacity:1}
.dpa-ts__band{fill:#5A3FE01f;opacity:0;transition:opacity .6s 1.4s}
.dpa-ts__trend{stroke:var(--d-gold);stroke-width:1.6;stroke-dasharray:2 4;fill:none}
.dpa-ts__now{stroke:#B9C2D3;stroke-dasharray:3 3}
.dpa-ts__lab{font:700 11px var(--body);fill:var(--d-muted);letter-spacing:.04em}
.dpa-ts__ax{font:600 10px var(--body);fill:#8A93AA}
.dpa-ts__an circle{fill:none;stroke:var(--d-coral);stroke-width:2}
.dpa-ts__an text{font:700 11px var(--body);fill:var(--d-coral)}
.dpa-flow{list-style:none;margin:0 0 18px;padding:0;display:flex;flex-wrap:wrap;gap:8px}
.dpa-flow li{position:relative;padding:9px 16px;border-radius:999px;background:#fff;border:1px solid var(--d-line);font:700 .9rem var(--display);color:var(--d-ink);opacity:0;transform:translateX(-8px);transition:opacity .4s,transform .4s;transition-delay:calc(var(--i)*110ms)}
.dpa-flow li:not(:last-child){margin-right:18px}
.dpa-flow li:not(:last-child):after{content:"→";position:absolute;right:-19px;top:50%;transform:translateY(-50%);color:var(--d-vio)}
.dpa-flow li:last-child{background:var(--d-vio);border-color:var(--d-vio);color:#fff}
.dpa-flow.is-in li{opacity:1;transform:none}
.dpa-flow--v li:first-child{background:var(--d-coral);border-color:var(--d-coral);color:#fff}

/* story */
.dpa-story{background:linear-gradient(180deg,#FBFAF6,#fff)}
.dpa-story__in{display:grid;grid-template-columns:minmax(0,.8fr) minmax(0,1.2fr);gap:clamp(28px,5vw,64px);align-items:start}
.dpa-story__in>*{min-width:0}
.dpa-story__list{list-style:none;margin:0;padding:0;border-top:2px solid var(--d-ink)}
.dpa-story__list li{display:grid;grid-template-columns:80px 1fr;gap:16px;align-items:center;padding:16px 0;border-bottom:1px solid #E4E1D6}
.dpa-story__list span{font:300 2.6rem/1 var(--display);color:var(--d-gold)}
.dpa-story__list strong{display:block;font:700 1.2rem var(--display);color:var(--d-ink)}
.dpa-story__list em{font-style:normal;color:var(--d-muted);font-size:.95rem}
.dpa-story__list li:last-child strong{color:var(--d-vio)}

/* EDA */
.dpa-eda{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px;background:#11162E;border-radius:22px;padding:14px}
.dpa-eda__p{background:#ffffff0a;border:1px solid #ffffff14;border-radius:14px;padding:12px 14px;color:#fff}
.dpa-eda .dpa-dash__ct{color:#9DA8CC}
.dpa-eda svg{width:100%;height:auto;display:block}
.dpa-eda .dpa-axis{stroke:#ffffff30}
.dpa-pt{fill:#8E9BCB}
.dpa-eda .dpa-pt{fill:#6E8BFF;fill-opacity:.8}
.dpa-fit{stroke:#B6ABF5;stroke-width:1.8}
.dpa-out circle:first-child{fill:#F0A08A}
.dpa-out .ring{stroke:#F0A08A}
.dpa-bin{fill:#6E8BFF;fill-opacity:.75}
.dpa-bin.is-out{fill:#F0A08A}
.dpa-out__t{font:700 10px var(--body);fill:#F0A08A}
.dpa-cor{max-width:280px;margin:0 auto;display:grid;grid-template-columns:26px repeat(5,1fr);gap:3px;align-items:center}
.dpa-cor b{font:600 .66rem var(--body);color:#9DA8CC;text-align:center}
.dpa-cor i{aspect-ratio:1;border-radius:4px}
.dpa-cor i.pos{background:rgba(110,139,255,var(--v))}
.dpa-cor i.neg{background:rgba(240,160,138,var(--v))}
.dpa-cor__lg{display:flex;gap:12px;margin-top:8px;font-size:.72rem;color:#C9D0EA}
.dpa-cor__lg span{display:flex;align-items:center;gap:5px}
.dpa-cor__lg i{width:10px;height:10px;border-radius:2px}
.dpa-cor__lg i.pos{background:#6E8BFF}.dpa-cor__lg i.neg{background:#F0A08A}

/* explore */
.dpa-exp{display:grid;grid-template-columns:minmax(0,.8fr) minmax(0,1.2fr);gap:14px}
.dpa-exp__dims,.dpa-exp__out{background:#fff;border:1px solid var(--d-line);border-radius:20px;padding:18px;min-width:0}
.dpa-exp__dims>div{display:flex;flex-wrap:wrap;gap:6px}
.dpa-exp__dims button{display:inline-flex;align-items:center;gap:6px;border-radius:999px}
.dpa-exp__ops{list-style:none;margin:16px 0 0;padding:14px 0 0;border-top:1px solid var(--d-line);display:flex;flex-wrap:wrap;gap:6px}
.dpa-exp__ops li{font-size:.8rem;font-weight:600;color:var(--d-muted);padding:4px 10px;border-radius:999px;background:var(--d-soft)}
.dpa-exp__q{margin:0 0 12px;color:var(--d-muted)}
.dpa-exp__q strong{color:var(--d-vio)}
.dpa-exp__grid{display:grid;gap:4px;align-items:center;margin-bottom:10px}
.dpa-exp__grid b{font:600 .72rem var(--body);color:#8A93AA;text-align:center}
.dpa-exp__grid i{height:30px;border-radius:6px;background:color-mix(in srgb,var(--d-vio) calc(var(--v)*85% + 5%),#fff);animation:dpaPop .4s ease both;animation-delay:var(--d)}
.dpa-exp__more{font-size:.84rem;color:var(--d-muted);margin:0 0 8px}

/* custom */
.dpa-cust{display:grid;grid-template-columns:1fr 1fr 1fr;grid-template-rows:auto auto;gap:12px;position:relative}
.dpa-cust__hub{grid-column:2;grid-row:1/3;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:10px;text-align:center;border-radius:50%;aspect-ratio:1;max-width:240px;width:100%;justify-self:center;align-self:center;background:radial-gradient(circle,#fff 0 55%,#F1EFFD 56%);border:2px dashed #B6ABF5;color:var(--d-vio);font:700 1rem var(--display)}
.dpa-cust__hub strong{color:var(--d-ink)}
.dpa-cust__m{display:flex;flex-direction:column;gap:6px;padding:18px;border-radius:16px;background:#fff;border:1px solid var(--d-line)}
.dpa-cust__m .rc-ico{color:var(--d-vio)}
.dpa-cust__m strong{font:700 1rem var(--display);color:var(--d-ink)}
.dpa-cust__m span{font-size:.88rem;color:var(--d-muted)}
.dpa-cust__m0{grid-column:1;grid-row:1}.dpa-cust__m1{grid-column:3;grid-row:1}.dpa-cust__m2{grid-column:1;grid-row:2}.dpa-cust__m3{grid-column:3;grid-row:2}

/* maturity */
.dpa-mat{display:grid;grid-template-columns:minmax(0,1.5fr) minmax(0,.7fr);gap:24px;align-items:end}
.dpa-mat__stair{position:relative;display:grid;grid-template-columns:repeat(4,1fr);gap:10px;align-items:end;height:360px;padding:0 0 28px 28px;border-left:1px solid #ffffff30;border-bottom:1px solid #ffffff30}
.dpa-mat__y{position:absolute;left:-6px;top:50%;transform:translate(-50%,-50%) rotate(-90deg);font:700 .7rem var(--body);letter-spacing:.1em;text-transform:uppercase;color:#9DA8CC;white-space:nowrap}
.dpa-mat__x{position:absolute;right:0;bottom:4px;font:700 .7rem var(--body);letter-spacing:.1em;text-transform:uppercase;color:#9DA8CC}
.dpa-mat__step{height:0;display:flex;flex-direction:column;justify-content:flex-start;gap:6px;padding:16px;border:1px solid color-mix(in srgb,var(--c) 60%,#fff);border-radius:16px 16px 0 0;background:color-mix(in srgb,var(--c) 30%,#0A0F2E);color:#fff;text-align:left;cursor:pointer;transition:height .9s cubic-bezier(.2,.8,.2,1),background .25s,transform .25s;transition-delay:calc(var(--i)*120ms),0s,0s;overflow:hidden}
.dpa-mat.is-in .dpa-mat__step{height:var(--h)}
.dpa-mat__step:hover,.dpa-mat__step:focus-visible{background:color-mix(in srgb,var(--c) 55%,#0A0F2E)}
.dpa-mat__step.is-on{background:var(--c);box-shadow:0 20px 40px -24px var(--c)}
.dpa-mat__n{font:800 1.6rem var(--display);opacity:.55}
.dpa-mat__step strong{font:700 1.02rem/1.2 var(--display)}
.dpa-mat__step em{font-style:normal;font-size:.9rem;color:#E4E8F7}
.dpa-mat__panel{background:#fff;color:var(--d-ink);border-radius:20px;padding:22px;border-top:5px solid var(--c);animation:rcPanel .35s ease}
.dpa-mat__panel>span{font:700 .72rem var(--body);letter-spacing:.12em;text-transform:uppercase;color:var(--c)}
.dpa-mat__panel strong{display:block;font:700 1.6rem/1.2 var(--display);margin:8px 0}
.dpa-mat__panel p{color:var(--d-muted)}

/* descriptive */
.dpa-desc{display:grid;grid-template-columns:minmax(0,.8fr) minmax(0,1.2fr);gap:16px;align-items:start}
.dpa-desc__tabs{display:grid;gap:6px}
.dpa-desc__tab{border:1px solid var(--d-line);border-radius:14px;background:#fff;overflow:hidden;transition:border-color .2s}
.dpa-desc__tab.is-on{border-color:var(--d-blue)}
.dpa-desc__tab button{width:100%;display:flex;gap:10px;align-items:center;padding:12px 14px;background:none;border:0;font:700 .96rem var(--display);color:var(--d-ink);cursor:pointer;text-align:left}
.dpa-desc__tab button span{font-size:.72rem;color:var(--d-blue)}
.dpa-desc__tab ul{list-style:none;margin:0;padding:0 14px 14px 40px;display:flex;flex-wrap:wrap;gap:6px;animation:rcPanel .3s ease}
.dpa-desc__tab li{font-size:.82rem;padding:4px 10px;border-radius:999px;background:#EEF1FB;color:var(--d-blue);font-weight:600}
.dpa-desc__canvas{background:var(--d-soft);border:1px solid var(--d-line);border-radius:20px;padding:16px;position:sticky;top:calc(var(--header-h) + 80px)}
.dpa-desc__head{display:flex;justify-content:space-between;align-items:center;gap:10px;margin-bottom:12px}
.dpa-desc__head strong{font:700 1.3rem var(--display);color:var(--d-ink)}
.dpa-desc__grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:10px}
.dpa-desc__tile{background:#fff;border:1px solid var(--d-line);border-radius:14px;padding:12px;display:flex;flex-direction:column;gap:6px;min-height:110px;transition:border-color .25s,box-shadow .25s,transform .25s}
.dpa-desc__tile>span{font:700 .7rem var(--body);letter-spacing:.08em;text-transform:uppercase;color:var(--d-muted)}
.dpa-desc__tile>svg{width:100%;height:56px}
.dpa-desc__tile.is-on{border-color:var(--d-blue);box-shadow:0 16px 30px -22px var(--d-blue);transform:translateY(-2px)}
.dpa-desc__prof,.dpa-desc__kpi{display:grid;gap:4px;font-size:.78rem;font-weight:600;color:var(--d-ink)}
.dpa-desc__prof span,.dpa-desc__kpi span{display:flex;align-items:center;gap:5px}
.dpa-desc__prof .rc-ico{color:var(--d-teal)}
.dpa-desc__kpi .is-up{color:var(--d-teal)}.dpa-desc__kpi .is-dn{color:var(--d-coral)}

/* diagnostic */
.dpa-diag{display:grid;grid-template-columns:minmax(0,1.3fr) minmax(0,1fr);gap:16px;align-items:start}
.dpa-diag__dash{background:#fff;border:1px solid var(--d-line);border-radius:20px;padding:16px}
.dpa-tree svg{width:100%;height:auto;display:block}
.dpa-tree__l{fill:none;stroke:#C9CFE0;stroke-width:1.6;transition:stroke .25s}
.dpa-tree__l--root{stroke-dasharray:4 4;opacity:.2}
.dpa-tree__n rect{fill:#fff;stroke:#C9CFE0;stroke-width:1.4;transition:all .25s}
.dpa-tree__n text{font:700 13px var(--body);fill:var(--d-ink)}
.dpa-tree__n--s text{font-size:12px;font-weight:600}
.dpa-tree__n.is-out rect{fill:var(--d-coral);stroke:var(--d-coral)}
.dpa-tree__n.is-out text{fill:#fff}
.dpa-tree__n.is-act rect{fill:var(--d-ink);stroke:var(--d-ink)}
.dpa-tree__n.is-act text{fill:#fff}
.dpa-tree__n.is-act .k{font-size:10px;letter-spacing:.12em;fill:#4FD1B5}
.dpa-tree__br{outline:none;cursor:pointer}
.dpa-tree__br.is-on .dpa-tree__l{stroke:var(--d-vio);stroke-width:2.2}
.dpa-tree__br.is-on .dpa-tree__l--root{opacity:1}
.dpa-tree__br.is-on>.dpa-tree__n rect{stroke:var(--d-vio);fill:#F1EFFD}
.dpa-tree__br.is-on .is-root rect{fill:var(--d-vio);stroke:var(--d-vio)}
.dpa-tree__br.is-on .is-root text{fill:#fff}
.dpa-diag__svc{list-style:none;margin:0;padding:0;display:grid;grid-template-columns:1fr 1fr;gap:8px}
.dpa-diag__svc li{display:flex;gap:10px;align-items:flex-start;padding:12px;border-radius:14px;background:#fff;border:1px solid var(--d-line)}
.dpa-diag__svc .rc-ico{color:var(--d-vio);flex:none;margin-top:2px}
.dpa-diag__svc strong{display:block;font:700 .92rem var(--display);color:var(--d-ink)}
.dpa-diag__svc span{font-size:.8rem;color:var(--d-muted)}

/* prescriptive */
.dpa-pre{display:grid;grid-template-columns:1fr 24px 1fr 24px .8fr 24px 1fr;gap:8px;align-items:stretch;background:#fff;border:1px solid var(--d-line);border-radius:22px;padding:18px}
.dpa-pre__col{display:flex;flex-direction:column;gap:6px;min-width:0}
.dpa-pre__k{font:700 .7rem var(--body);letter-spacing:.12em;text-transform:uppercase;color:var(--d-muted);margin-bottom:4px}
.dpa-pre__sc>div{padding:8px 12px;border-radius:10px;background:var(--d-soft);font-weight:600;font-size:.88rem;border:1px solid var(--d-line)}
.dpa-pre__sc>div.is-best{border-color:var(--d-gold);background:#FBF5E6}
.dpa-pre__cn>div{display:flex;align-items:center;gap:6px;padding:8px 12px;border-radius:10px;border:1px dashed #C9CFE0;font-weight:600;font-size:.88rem}
.dpa-pre__cn .rc-ico{color:var(--d-muted)}
.dpa-pre__op{align-items:center;justify-content:center;text-align:center}
.dpa-pre__gear{width:84px;height:84px;border-radius:50%;display:grid;place-items:center;background:var(--d-ink);color:#B6ABF5}
.dpa-pre__gear .rc-ico{animation:rcSpin 12s linear infinite}
.dpa-pre__rec{justify-content:center;padding:16px;border-radius:16px;background:var(--d-gold);color:#fff}
.dpa-pre__rec .dpa-pre__k{color:#FFF3D6}
.dpa-pre__rec strong{font:800 1.4rem var(--display)}
.dpa-pre__arrow{align-self:center;height:2px;background:#C9CFE0;position:relative}
.dpa-pre__arrow:after{content:"";position:absolute;right:-2px;top:-4px;border:5px solid transparent;border-left:7px solid #C9CFE0}

/* text analytics */
.dpa-txt{display:grid;grid-template-columns:minmax(0,1fr) 80px minmax(0,1fr);gap:14px;align-items:center}
.dpa-txt__src{display:grid;gap:8px}
.dpa-txt__card{background:#fff;border:1px solid var(--d-line);border-radius:12px;padding:10px 12px;opacity:0;transform:translateX(-10px);transition:all .45s;transition-delay:calc(var(--i)*90ms)}
.dpa-txt.is-in .dpa-txt__card{opacity:1;transform:none}
.dpa-txt__card span{display:flex;align-items:center;gap:6px;font:700 .68rem var(--body);letter-spacing:.08em;text-transform:uppercase;color:var(--d-muted)}
.dpa-txt__card q{display:block;font-size:.9rem;color:var(--d-ink);margin-top:3px;quotes:none}
.dpa-txt__nlp{position:relative;height:100%;min-height:200px;display:grid;place-items:center}
.dpa-txt__nlp span{position:relative;z-index:1;width:64px;height:64px;border-radius:50%;display:grid;place-items:center;background:var(--d-vio);color:#fff;font:800 .95rem var(--display);box-shadow:0 0 0 8px #5A3FE01f}
.dpa-txt__nlp i{position:absolute;left:0;right:0;height:2px;background:repeating-linear-gradient(90deg,#B6ABF5 0 6px,transparent 6px 12px);animation:dpaSlide 1.2s linear infinite}
.dpa-txt__nlp i:nth-of-type(1){top:30%}.dpa-txt__nlp i:nth-of-type(2){top:50%}.dpa-txt__nlp i:nth-of-type(3){top:70%}
@keyframes dpaSlide{to{background-position:12px 0}}
.dpa-txt__res{display:grid;gap:10px}
.dpa-txt__blk{background:#fff;border:1px solid var(--d-line);border-radius:14px;padding:12px 14px}
.dpa-txt__tags{display:flex;flex-wrap:wrap;gap:6px;align-items:center}
.dpa-txt__tags span{padding:5px 11px;border-radius:999px;font-weight:700;font-size:calc(.72rem + var(--w)*.09rem)}
.t-pos{background:#E3F5F2;color:#0B6F6F}.t-neg{background:#FBEDE8;color:#A24A2E}.t-neu{background:#EEF0F5;color:#525C78}
.dpa-txt__sent{display:flex;gap:6px}
.dpa-txt__sent span{flex:1;text-align:center;padding:8px;border-radius:8px;font-weight:700;font-size:.82rem}
.dpa-txt__ins ul{list-style:none;margin:0;padding:0;display:grid;gap:6px;font-size:.88rem;font-weight:600}
.dpa-txt__ins li{display:flex;align-items:center;gap:7px}
.dpa-txt__ins li:first-child .rc-ico{color:var(--d-coral)}
.dpa-txt__ins li:last-child .rc-ico{color:var(--d-teal)}
.dpa-txt__res>.dpa-illus{justify-self:start}

/* mining */
.dpa-mine{display:grid;grid-template-columns:minmax(0,.8fr) 30px minmax(0,1.4fr) 30px minmax(0,.7fr);gap:10px;align-items:center;background:#fff;border:1px solid var(--d-line);border-radius:22px;padding:18px}
.dpa-mine__ds svg{width:100%;height:auto}
.dpa-mine__ar{height:2px;background:#C9CFE0;position:relative}
.dpa-mine__ar:after{content:"";position:absolute;right:-2px;top:-4px;border:5px solid transparent;border-left:7px solid #C9CFE0}
.dpa-mine__tech{display:grid;grid-template-columns:1fr 1fr;gap:8px}
.dpa-mine__tech>div{display:flex;flex-direction:column;align-items:center;gap:4px;padding:10px;border-radius:12px;background:var(--d-soft);text-align:center}
.dpa-mine__tech svg{width:70px;height:46px}
.dpa-mine__tech strong{font:700 .84rem var(--display);color:var(--d-ink)}
.dpa-mine__out{list-style:none;margin:0;padding:0;display:grid;gap:8px}
.dpa-mine__out li{display:flex;align-items:center;gap:8px;padding:12px;border-radius:12px;font:700 .9rem var(--display)}
.dpa-mine__out li:first-child{background:#F1EFFD;color:var(--d-vio)}
.dpa-mine__out li:last-child{background:var(--d-ink);color:#fff}

/* spatial */
.dpa-sp{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,.8fr);gap:16px;align-items:start}
.dpa-sp__map{background:#0F1433;border-radius:22px;padding:14px}
.dpa-sp__map svg{width:100%;height:auto;display:block}
.dpa-sp__map .dpa-illus{background:transparent;color:#B9C2E0;border-color:#ffffff40;margin-top:6px}
.dpa-sp__hex{fill:color-mix(in srgb,#4FD1B5 calc(var(--v)*90%),#1A2148);stroke:#0F1433;stroke-width:2;transition:fill .4s}
.dpa-sp__hex.t0{fill:#3B5BDB99}.dpa-sp__hex.t1{fill:#C99A2E99}
.dpa-sp__cl circle{fill:#B6ABF522;stroke:#B6ABF5;stroke-width:2;stroke-dasharray:6 5;animation:rcSpin 30s linear infinite;transform-box:fill-box;transform-origin:center}
.dpa-sp__cl text{font:700 12px var(--body);fill:#fff}
.dpa-sp__bd{stroke:#fff;stroke-width:3;stroke-dasharray:8 6}
.dpa-sp__rt path{fill:none;stroke:#fff;stroke-width:3;stroke-dasharray:10 7;animation:rcDash 1.6s linear infinite}
.dpa-sp__rt circle{fill:#C99A2E;stroke:#fff;stroke-width:2}
.dpa-sp__rt rect{fill:#fff}
.dpa-sp__side .dpa-sp__tabs{display:grid;grid-template-columns:1fr 1fr}

/* venn + BI */
.dpa-venn svg{width:100%;height:auto;display:block;max-width:560px;margin:0 auto}
.dpa-venn__a{fill:#0B22A814;stroke:var(--d-blue);stroke-width:2}
.dpa-venn__b{fill:#0E8A8A14;stroke:var(--d-teal);stroke-width:2}
.dpa-venn__h{font:800 15px var(--display);fill:var(--d-ink)}
.dpa-venn__t{font:600 11.5px var(--body);fill:var(--d-muted)}
.dpa-venn__c{font:800 14px var(--display);fill:var(--d-vio)}
.dpa-bi{margin-top:clamp(48px,6vw,80px)}
.dpa-bi ol{list-style:none;margin:0;padding:0;display:grid;grid-template-columns:repeat(6,minmax(0,1fr));gap:10px;position:relative}
.dpa-bi li{display:flex;flex-direction:column;align-items:center;text-align:center;gap:6px;padding:18px 10px;border-radius:16px;background:#fff;border:1px solid var(--d-line);position:relative}
.dpa-bi li:not(:last-child):after{content:"";position:absolute;right:-9px;top:42px;width:8px;height:2px;background:var(--d-vio)}
.dpa-bi li.is-core{background:#F1EFFD;border-color:#D4CEF6}
.dpa-bi__ic{width:44px;height:44px;border-radius:12px;display:grid;place-items:center;background:var(--d-soft);color:var(--d-blue)}
.dpa-bi li.is-core .dpa-bi__ic{background:var(--d-vio);color:#fff}
.dpa-bi strong{font:700 .95rem var(--display);color:var(--d-ink)}
.dpa-bi a,.dpa-bi em{font-size:.78rem;font-style:normal;font-weight:600}
.dpa-bi a{color:var(--d-blue)}
.dpa-bi em{color:var(--d-vio)}

/* scorecard */
.dpa-score{display:grid;grid-template-columns:minmax(0,.7fr) minmax(0,1.3fr);gap:clamp(24px,4vw,56px);align-items:center}
.dpa-score__ring{position:relative;max-width:300px;width:100%;justify-self:center}
.dpa-score__ring>svg{width:100%;transform:rotate(-90deg)}
.dpa-score__seg{fill:none;stroke:#ffffff1a;stroke-width:9;transition:stroke .4s;transition-delay:calc(var(--i)*150ms)}
.dpa-score.is-in .dpa-score__seg{stroke:#4FD1B5}
.dpa-score__ring>span{position:absolute;inset:18%;display:flex;flex-direction:column;align-items:center;justify-content:center;text-align:center;gap:4px;color:#4FD1B5}
.dpa-score__ring strong{font:800 1.2rem var(--display);color:#fff}
.dpa-score__ring em{font-style:normal;font-size:.8rem;color:#C9D0EA;line-height:1.35}
.dpa-score__list{list-style:none;margin:0;padding:0;display:grid;grid-template-columns:1fr 1fr;gap:8px}
.dpa-score__list li{display:grid;grid-template-columns:auto 1fr auto;gap:10px;align-items:center;padding:12px 14px;border-radius:14px;background:#ffffff0d;border:1px solid #ffffff1a;opacity:.35;transition:opacity .4s;transition-delay:calc(var(--i)*150ms)}
.dpa-score.is-in .dpa-score__list li{opacity:1}
.dpa-score__tick{width:26px;height:26px;border-radius:50%;display:grid;place-items:center;background:#4FD1B5;color:var(--d-ink)}
.dpa-score__list strong{display:block;font:700 .95rem var(--display)}
.dpa-score__list div span{font-size:.8rem;color:#C9D0EA}
.dpa-score__list em{font-style:normal;font:700 .66rem var(--body);letter-spacing:.1em;text-transform:uppercase;color:#4FD1B5}

/* how we work */
.dpa-how{list-style:none;margin:0;padding:0;display:grid;grid-template-columns:repeat(7,minmax(0,1fr));gap:8px}
.dpa-how li{display:flex;flex-direction:column;gap:6px;padding:16px 14px;border-radius:16px;background:var(--d-soft);border:1px solid transparent;position:relative}
.dpa-how li.is-core{background:var(--d-ink);color:#fff}
.dpa-how__n{font:800 1.4rem var(--display);color:#B9C2D3}
.dpa-how li.is-core .dpa-how__n{color:#B6ABF5}
.dpa-how strong{font:700 1rem var(--display)}
.dpa-how li>span:not(.dpa-how__n){font-size:.82rem;color:var(--d-muted)}
.dpa-how li.is-core>span:not(.dpa-how__n){color:#C9D0EA}
.dpa-how em{font-style:normal;font:700 .64rem var(--body);letter-spacing:.1em;text-transform:uppercase;color:#4FD1B5;margin-top:auto}

/* matrix */
.dpa-mx{border-radius:20px;overflow:hidden;border:1px solid var(--d-line);background:#fff}
.dpa-mx__r{display:grid;grid-template-columns:1fr 1fr 1.4fr;align-items:center;border-top:1px solid var(--d-line);transition:background .2s}
.dpa-mx__r>span{padding:16px 20px}
.dpa-mx__r--h{border-top:0;background:var(--d-ink);color:#fff;font:700 .74rem var(--body);letter-spacing:.12em;text-transform:uppercase}
.dpa-mx__r:not(.dpa-mx__r--h):hover{background:var(--d-soft)}
.dpa-mx__l{display:flex;align-items:center;gap:10px;font:700 1.05rem var(--display);color:var(--c);border-left:4px solid var(--c)}
.dpa-mx__r>span:nth-child(2){font:600 1rem var(--display);color:var(--d-ink)}
.dpa-mx__r>span:nth-child(3){color:var(--d-muted)}
.dpa-mx__r--h>span,.dpa-mx__r--h>span:nth-child(2),.dpa-mx__r--h>span:nth-child(3){color:#fff;font:inherit}
.dpa-tools{margin-top:clamp(36px,5vw,56px)}
.dpa-tools .rc-tech__tile span{display:block;font-size:.76rem;color:var(--d-muted);font-weight:500}

/* team ecosystem */
.dpa-team{display:grid;grid-template-columns:minmax(0,.8fr) minmax(0,1.2fr);gap:clamp(24px,4vw,56px);align-items:center}
.dpa-team>*{min-width:0}
.dpa-eco{position:relative;width:100%;max-width:440px;aspect-ratio:1;justify-self:center}
.dpa-eco__lines{position:absolute;inset:0;width:100%;height:100%}
.dpa-eco__lines line{stroke:#D4CEF6;stroke-width:1.5;stroke-dasharray:4 5;animation:rcDash 3s linear infinite}
.dpa-eco__lines circle{fill:none;stroke:#E6E9F1}
.dpa-eco__core{position:absolute;left:50%;top:50%;width:30%;aspect-ratio:1;transform:translate(-50%,-50%);border-radius:50%;background:var(--d-ink);color:#fff;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:6px;text-align:center;font:700 .92rem var(--display)}
.dpa-eco__core .rc-ico{color:#4FD1B5}
.dpa-eco__r{position:absolute;width:0;height:0;left:calc(50% + 37.5% * cos(var(--a)));top:calc(50% + 37.5% * sin(var(--a)))}
.dpa-eco__r>span{position:absolute;left:0;top:0;transform:translate(-50%,-50%);width:48px;height:48px;border-radius:50%;display:grid;place-items:center;background:#fff;border:2px solid #D4CEF6;color:var(--d-vio)}
.dpa-eco__r.is-core>span{background:var(--d-vio);border-color:var(--d-vio);color:#fff}
.dpa-eco__r>em{position:absolute;left:0;top:30px;transform:translateX(-50%);width:130px;text-align:center;font:700 .78rem/1.25 var(--display);font-style:normal;color:var(--d-ink)}

/* case */
.dpa-case{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:clamp(24px,4vw,56px);align-items:center}
.dpa-case>*{min-width:0}
.dpa-case__tl{list-style:none;margin:6px 0 22px;padding:0;display:flex;flex-wrap:wrap;gap:6px}
.dpa-case__tl li{padding:7px 12px;border-radius:8px;background:var(--d-soft);font:700 .84rem var(--display);color:var(--d-ink);position:relative}
.dpa-case__tl li.is-core{background:var(--d-vio);color:#fff}
.dpa-case__tl li:last-child{background:var(--d-ink);color:#fff}
.dpa-case__dash{background:var(--d-char);border-radius:22px;padding:14px;color:#fff}
.dpa-case__dash .dpa-illus{background:transparent;color:#B9C2E0;border-color:#ffffff38}
.dpa-case__g{display:grid;grid-template-columns:1fr 1fr;gap:10px}
.dpa-case__t{background:#ffffff0d;border:1px solid #ffffff14;border-radius:12px;padding:12px;display:flex;flex-direction:column;gap:8px;min-width:0}
.dpa-case__t>span{font:700 .66rem var(--body);letter-spacing:.1em;text-transform:uppercase;color:#9DA8CC}
.dpa-case__bar{display:grid;grid-template-columns:72px 1fr;align-items:center;gap:8px;font-size:.74rem;color:#C9D0EA}
.dpa-case__bar em{font-style:normal}
.dpa-case__bar i{height:8px;border-radius:4px;background:linear-gradient(90deg,#4FD1B5,#6E8BFF);transform-origin:left;animation:dpaGrowX 1.2s ease both;animation-delay:calc(var(--i)*150ms)}
.dpa-case__t>svg{width:100%;height:64px}
.dpa-case__t .f2{fill:#B6ABF5}
.dpa-case__t ul{list-style:none;margin:0;padding:0;display:grid;gap:5px;font-size:.78rem;color:#C9D0EA}
.dpa-case__t li{display:flex;align-items:center;gap:6px}
.dpa-case__t li .rc-ico{color:#4FD1B5}
.dpa-case__tbl{display:grid;grid-template-columns:repeat(5,1fr);gap:3px}
.dpa-case__tbl i{height:10px;border-radius:2px;background:#ffffff26}
.dpa-case__tbl i.h{background:#6E8BFF}
.dpa-case__cap{font-style:normal;font-size:.76rem;color:#C9D0EA}

/* guide + CTA + form */
.dpa-guide{display:grid;grid-template-columns:200px 1fr;gap:24px;align-items:center;padding:20px;border-radius:22px;background:linear-gradient(110deg,#F1EFFD,#fff);border:1px solid #DCD6F7;margin-bottom:clamp(40px,5vw,64px);color:inherit;text-decoration:none;transition:transform .25s,box-shadow .25s}
.dpa-guide:hover{transform:translateY(-3px);box-shadow:0 24px 40px -30px var(--d-vio)}
.dpa-guide__viz{background:#fff;border-radius:16px;padding:16px;display:block}
.dpa-guide__viz svg{width:100%;height:auto}
.dpa-guide__c{display:flex;flex-direction:column;gap:8px}
.dpa-guide__c strong{font:700 clamp(1.15rem,2vw,1.45rem)/1.3 var(--display);color:var(--d-ink)}
.dpa-cta{position:relative;overflow:hidden;background:radial-gradient(700px 400px at 0% 0%,#26206B 0%,transparent 70%),var(--d-char);color:#fff;padding:clamp(56px,7vw,96px) 0;text-align:center}
.dpa-cta__bg{position:absolute;inset:0;width:100%;height:100%;opacity:.28}
.dpa-cta__bg line{stroke:#B6ABF5;stroke-width:1}
.dpa-cta__bg circle{fill:#B6ABF5}
.dpa-cta__bg rect{fill:#4FD1B540}
.dpa-cta__in{position:relative;max-width:760px}
.dpa-cta h2{color:#fff;font-size:clamp(1.9rem,4vw,3rem);margin-bottom:.4em}
.dpa-cta p{color:#D6DBF0;font-size:1.08rem;margin:0 auto 26px;max-width:58ch}
.dpa-cta .od-hero__ctas{justify-content:center}
.dpa-priv{display:flex;align-items:center;gap:8px;font-size:.88rem;color:var(--d-muted)}
.dpa-priv .rc-ico{color:var(--d-teal);flex:none}

/* responsive */
@media (max-width:1100px){
  .dpa-sol{grid-template-columns:repeat(4,minmax(0,1fr));row-gap:28px}.dpa-sol:before{display:none}
  .dpa-pipe__rail{grid-template-columns:repeat(5,minmax(0,1fr))}
  .dpa-obj{grid-template-columns:repeat(3,1fr)}
  .dpa-gal{grid-template-columns:1fr 1fr}
  .dpa-how{grid-template-columns:repeat(4,minmax(0,1fr))}
  .dpa-bi ol{grid-template-columns:repeat(3,minmax(0,1fr))}.dpa-bi li:after{display:none}
  .dpa-mine{grid-template-columns:1fr;}.dpa-mine__ar{width:2px;height:20px;justify-self:center}.dpa-mine__ar:after{right:-4px;top:auto;bottom:-6px;border-left-color:transparent;border-top:7px solid #C9CFE0}
  .dpa-pre{grid-template-columns:1fr 1fr;row-gap:14px}.dpa-pre__arrow{display:none}
}
@media (max-width:900px){
  .dpa-hero__in,.dpa-probwrap,.dpa-two,.dpa-two--flip,.dpa-story__in,.dpa-exp,.dpa-mat,.dpa-desc,.dpa-diag,.dpa-sp,.dpa-score,.dpa-team,.dpa-case{grid-template-columns:1fr}
  .dpa-two--flip>:first-child{order:2}
  .dpa-strip{grid-template-columns:1fr 1fr}
  .dpa-blk__h{grid-template-columns:1fr;gap:8px}
  .dpa-inc__m{grid-column:1/-1!important}
  .dpa-pipe__panel{grid-template-columns:1fr}.dpa-pipe__nav{flex-direction:row}
  .dpa-dash{grid-template-columns:1fr}
  .dpa-dash__f{flex-direction:row;flex-wrap:wrap;align-items:center}
  .dpa-dash__fg{display:flex;flex-wrap:wrap;width:auto}
  .dpa-dash__row{grid-template-columns:1fr}
  .dpa-eda{grid-template-columns:1fr}
  .dpa-desc__canvas{position:static}
  .dpa-txt{grid-template-columns:1fr}.dpa-txt__nlp{min-height:90px}.dpa-txt__nlp i{display:none}
  .dpa-cust{grid-template-columns:1fr 1fr}.dpa-cust__hub{grid-column:1/-1;grid-row:auto;max-width:180px}.dpa-cust__m0,.dpa-cust__m1,.dpa-cust__m2,.dpa-cust__m3{grid-column:auto;grid-row:auto}
  .dpa-mat__stair{height:320px}
}
@media (max-width:640px){
  .dpa-ts,.dpa-geo__map{overflow-x:auto}
  .dpa-ts svg{min-width:640px}.dpa-ts--c svg{min-width:460px}
  .dpa-geo__map svg{min-width:620px}
  .dpa-hv__st{grid-template-columns:repeat(4,1fr);row-gap:10px}.dpa-hv__st li:nth-child(4):after{display:none}
  .dpa-mini__grid{grid-template-columns:1fr 1fr}
  .dpa-strip{grid-template-columns:1fr}
  .dpa-sol{grid-template-columns:1fr 1fr}
  .dpa-pipe__rail{grid-template-columns:repeat(3,minmax(0,1fr))}
  .dpa-obj{grid-template-columns:1fr 1fr}
  .dpa-gal{grid-template-columns:1fr}
  .dpa-dash__kpis{grid-template-columns:1fr 1fr}
  .dpa-heat__r{grid-template-columns:56px repeat(6,1fr)}
  .dpa-code{grid-template-columns:1fr}.dpa-code__arrow{transform:rotate(90deg);justify-self:center}
  .dpa-drv__r{grid-template-columns:100px 1fr}.dpa-drv__ax{margin-left:110px}
  .dpa-wt__bars{height:90px}
  .dpa-story__list li{grid-template-columns:52px 1fr}.dpa-story__list span{font-size:2rem}
  .dpa-mat__stair{grid-template-columns:1fr;height:auto;padding:0;border:0;gap:8px}
  .dpa-mat__step,.dpa-mat.is-in .dpa-mat__step{height:auto;border-radius:16px;margin-left:calc(var(--i)*14px)}
  .dpa-mat__y,.dpa-mat__x{display:none}
  .dpa-desc__grid{grid-template-columns:1fr 1fr}
  .dpa-diag__svc{grid-template-columns:1fr}
  .dpa-pre{grid-template-columns:1fr}
  .dpa-mine__tech{grid-template-columns:1fr 1fr}
  .dpa-score__list{grid-template-columns:1fr}
  .dpa-how{grid-template-columns:1fr}
  .dpa-how li{flex-direction:row;flex-wrap:wrap;align-items:baseline;column-gap:12px}
  .dpa-bi ol{grid-template-columns:1fr 1fr}
  .dpa-mx__r--h{display:none}
  .dpa-mx__r{grid-template-columns:1fr;padding:6px 0}
  .dpa-mx__r>span{padding:6px 16px}
  .dpa-mx__r>span[data-l]:before{content:attr(data-l);display:block;font:700 .66rem var(--body);letter-spacing:.1em;text-transform:uppercase;color:var(--d-muted)}
  .dpa-eco__r>em{width:96px;font-size:.7rem}
  .dpa-eco__r>span{width:40px;height:40px}
  .dpa-case__g{grid-template-columns:1fr}
  .dpa-guide{grid-template-columns:1fr}
  .dpa-cta .od-hero__ctas .btn,.dpa-hero .od-hero__ctas .btn{width:100%}
  .dpa-cust{grid-template-columns:1fr}
  .dpa-sp__side .dpa-sp__tabs{grid-template-columns:1fr 1fr}
}
@media (prefers-reduced-motion:reduce){
  .dpa *,.dpa *:before,.dpa *:after{animation:none!important;transition:none!important}
  .dpa-prob li,.dpa-sol li,.dpa-flow li,.dpa-txt__card,.dpa-score__list li{opacity:1!important;transform:none!important}
  .dpa-sol:before{transform:none!important}
  .dpa-mat__step{height:var(--h)!important}
  .dpa-ts__hist{stroke-dasharray:none!important}.dpa-ts__fc,.dpa-ts__band{opacity:1!important}
  .dpa-draw{stroke-dasharray:none!important;stroke-dashoffset:0!important}
  .dpa-score__seg{stroke:#4FD1B5!important}
}
@media (prefers-reduced-motion:reduce) and (max-width:640px){.dpa-mat__step{height:auto!important}}

/* ===== CATI (cti-): muted blue-grey / soft teal palette, distinct from other service pages ===== */
.cti{--od-navy:#0A1660;--od-blue:#1E5BFF;--od-royal:#0B22A8;--od-sky:#EAEEFF;--od-teal:#0E9C88;--od-teal-soft:#E3F5F2;--od-line:#DDE2EC;--od-muted:#525C78;--od-paper:#F5F7FB;
  --r-navy:#07104F;--r-char:#0A1660;--r-blue:#0B22A8;--r-soft:#EAEEFF;--r-teal:#0E9C88;--r-gold:#C99A2E;--r-line:#DDE2EC;--r-muted:#525C78;
  --c-ink:#07104F;--c-char:#0A1660;--c-deep:#0B22A8;--c-deep2:#1E5BFF;--c-blue:#1E5BFF;--c-teal:#0E9C88;--c-teal2:#6EE0CE;--c-amber:#C99A2E;--c-line:#DDE2EC;--c-muted:#525C78;--c-soft:#EAEEFF;
  background:linear-gradient(180deg,#F5F7FB 0%,#F0F3FA 50%,#F5F7FB 100%)}
.cti .rc-kicker{color:var(--c-teal)}
.cti .rc-head h2,.cti .split__title{color:var(--c-ink)}
.cti .rc-head--light h2{color:#fff}
.cti .rc-head--light .rc-head__intro{color:#CED8F7}
.cti .rc-head--light .rc-kicker{color:var(--c-teal2)}
.cti .rc-sec{background-image:radial-gradient(#07104F0d 1px,transparent 1px);background-size:22px 22px}
.cti-sec--soft{background-color:#EEF2FB}
.cti .cti-sec--ink{background:radial-gradient(700px 360px at 10% 0%,#1E6BFF 0%,transparent 60%),linear-gradient(165deg,#0F1D72,#07104F);color:#fff}
.cti-illus{display:inline-block;font:600 .66rem var(--body);letter-spacing:.06em;text-transform:uppercase;color:#6B7590;border:1px dashed #C3CBE0;border-radius:999px;padding:3px 9px;white-space:nowrap}
.cti-note{font-size:.88rem;color:var(--c-muted);margin:18px 0 0}
.cti-note a{color:var(--c-deep);font-weight:700;display:inline-flex;align-items:center;gap:4px}
.cti-note--light{color:#CED8F7;text-align:center}
.cti-note--light a{color:var(--c-teal2)}
.cti-note--c{text-align:center}
.cti-lead{font:600 clamp(1.08rem,1.6vw,1.28rem)/1.5 var(--display);color:var(--c-ink)}
.cti-h3{font-size:1.2rem;margin:clamp(36px,5vw,56px) 0 18px;color:var(--c-ink)}
.cti-ticks{list-style:none;margin:16px 0 0;padding:0;display:grid;gap:8px}
.cti-ticks li{display:flex;align-items:center;gap:8px;font-weight:600;color:var(--c-ink)}
.cti-ticks .rc-ico{color:var(--c-teal)}

/* hero: muted indigo with soft teal light, wave lines */
.cti-hero{position:relative;overflow:hidden;color:#fff;padding:clamp(32px,4vw,56px) 0 clamp(28px,3vw,40px);background:radial-gradient(640px 480px at 78% 40%,#1E6BFF66 0%,transparent 65%),radial-gradient(520px 380px at 0% 100%,#0E9C8838 0%,transparent 70%),linear-gradient(160deg,#0B22A8 0%,#0A1A7A 55%,#07104F 100%)}
.cti-hero__bg{position:absolute;inset:0;width:100%;height:100%;pointer-events:none}
.cti-hero__bg path{fill:none;stroke:#A9C1FF;stroke-opacity:.13;stroke-width:1.2;animation:ctiDrift 14s ease-in-out infinite alternate;animation-delay:calc(var(--i)*-2s)}
@keyframes ctiDrift{to{transform:translateY(-14px)}}
.cti-hero__in{position:relative;display:grid;grid-template-columns:minmax(0,.95fr) minmax(0,1.05fr);gap:clamp(24px,4vw,56px);align-items:center}
.cti-hero__in>*{min-width:0}
.cti-hero .crumbs a,.cti-hero .crumbs span{color:#CED8F7}
.cti-eyebrow{display:inline-flex;align-items:center;gap:8px;font:700 .76rem var(--body);letter-spacing:.14em;text-transform:uppercase;color:var(--c-teal2);margin-bottom:16px}
.cti-hero h1{font-size:clamp(2.2rem,4vw,3.3rem);line-height:1.05;color:#fff;margin-bottom:.35em;letter-spacing:-.01em}
.cti-hero__sub{font:600 clamp(1.1rem,1.8vw,1.38rem)/1.45 var(--display);color:#E1E8FF;margin:0 0 14px}
.cti-hero__body{color:#C9D3F5;font-size:1.03rem;max-width:56ch;margin:0 0 24px}
.cti .cti-btn{background:var(--c-teal2);color:var(--c-ink)}
.cti .cti-btn:hover{background:#fff;color:var(--c-ink)}
.cti-hero .btn--ghost{color:#fff;border-color:#ffffff70}
.cti-hero .btn--ghost:hover{background:#ffffff1a;color:#fff}
.cti-hv{position:relative;--mx:0;--my:0}
.cti-hv__stage{position:relative;aspect-ratio:520/400;border-radius:24px;background:linear-gradient(160deg,#ffffff14,#ffffff06);border:1px solid #ffffff22;box-shadow:inset 0 1px 0 #ffffff26,0 40px 70px -50px #050B38}
.cti-hv__svg{position:absolute;inset:0;width:100%;height:100%;transform:translate(calc(var(--mx)*-8px),calc(var(--my)*-6px));transition:transform .4s ease-out}
.cti-hv__orbit ellipse{fill:none;stroke:#BFD0FF;stroke-opacity:.22;stroke-dasharray:3 6;animation:rcDash 6s linear infinite}
.cti-hv__path{fill:none;stroke:#ffffff26;stroke-width:6;stroke-linecap:round}
.cti-hv__path2{fill:none;stroke-width:2;stroke-dasharray:6 8;animation:rcDash 1.6s linear infinite}
.cti-hv__pt{fill:#CFF5EE;filter:drop-shadow(0 0 4px #6EE0CE)}
.cti-hv__pt.is-b{fill:#F0D98F;filter:drop-shadow(0 0 4px #C99A2E)}
.cti-hv__node circle{fill:#ffffff1c;stroke:#ffffff55;stroke-width:1.5}
.cti-hv__node .cti-hv__ring{fill:none;stroke:#6EE0CE;stroke-opacity:.6;transform-box:fill-box;transform-origin:center;animation:rcPulse 2.6s ease-out infinite}
.cti-hv__node.is-r circle{fill:#6EE0CE2e;stroke:#6EE0CE}
.cti-hv__ic{fill:none;stroke:#fff;stroke-width:2;stroke-linecap:round;stroke-linejoin:round}
.cti-hv__sig{fill:none;stroke:#6EE0CE;stroke-width:2;stroke-linecap:round;opacity:0;animation:ctiSig 2.4s ease-out infinite;animation-delay:calc(var(--i)*.3s)}
@keyframes ctiSig{0%{opacity:0}30%{opacity:.9}100%{opacity:0}}
.cti-hv__lbl{font:700 12px var(--body);fill:#E1E8FF;letter-spacing:.04em}
.cti-hv__set{animation:ctiFloat 6s ease-in-out infinite}
@keyframes ctiFloat{50%{transform:translateY(-6px)}}
.cti-hv__shadow{fill:#050B38;opacity:.28;animation:ctiShadow 6s ease-in-out infinite;transform-box:fill-box;transform-origin:center}
@keyframes ctiShadow{50%{transform:scaleX(.9);opacity:.2}}
.cti-hv__micpulse{fill:none;stroke:#6EE0CE;stroke-width:1.5;transform-box:fill-box;transform-origin:center;animation:rcPulse 2s ease-out infinite}
.cti-hv__bars rect{fill:#6EE0CE;fill-opacity:.85;transform-box:fill-box;transform-origin:center;animation:ctiBar 1.1s ease-in-out infinite alternate;animation-delay:calc(var(--i)*-.12s)}
@keyframes ctiBar{from{transform:scaleY(.25)}to{transform:scaleY(1)}}
.cti-hv__tag{position:absolute;right:12px;bottom:10px;font:600 .62rem var(--body);letter-spacing:.08em;text-transform:uppercase;color:#C9D3F5;border:1px dashed #ffffff40;border-radius:999px;padding:2px 8px}
.cti-fc{position:absolute;background:#F7F9FBF2;color:var(--c-ink);border-radius:14px;box-shadow:0 18px 34px -20px #050B38,0 0 0 1px #ffffff80;padding:10px 12px;transform:translate(calc(var(--mx)*var(--d)*18px),calc(var(--my)*var(--d)*14px));transition:transform .35s ease-out;animation:ctiCard 7s ease-in-out infinite;animation-delay:calc(var(--d)*-2s)}
@keyframes ctiCard{50%{margin-top:-5px}}
.cti-fc__k{display:block;font:700 .6rem var(--body);letter-spacing:.1em;text-transform:uppercase;color:var(--c-teal)}
.cti-fc strong{display:block;font:700 .8rem/1.25 var(--display)}
.cti-fc--q{left:3%;top:6%;width:30%}
.cti-fc__opts{display:grid;gap:4px;margin:6px 0}
.cti-fc__opts i{height:7px;border-radius:4px;background:#DDE2EC;transition:background .3s}
.cti-fc__opts i.is-on{background:var(--c-teal)}
.cti-fc__route{font:700 .62rem var(--body);color:#9A7420}
.cti-fc--v{right:3%;top:8%;display:flex;gap:8px;align-items:center}
.cti-fc--v em{font-style:normal;font-size:.66rem;color:var(--c-muted)}
.cti-fc__tick{width:26px;height:26px;border-radius:50%;display:grid;place-items:center;background:var(--c-teal);color:#fff}
.cti-fc--l{left:38%;top:3%;display:flex;gap:4px;padding:6px 8px}
.cti-fc--l b{font:700 .62rem var(--body);padding:3px 6px;border-radius:6px;background:#EEF2FB;color:var(--c-muted);transition:all .3s}
.cti-fc--l b.is-on{background:var(--c-deep);color:#fff}
.cti-fc--r{right:4%;top:32%;display:flex;align-items:center;gap:6px;font:700 .68rem var(--body);padding:6px 10px}
.cti-fc__rec{width:8px;height:8px;border-radius:50%;background:#C2603F;animation:ctiBlink 1.4s ease-in-out infinite}
@keyframes ctiBlink{50%{opacity:.25}}
.cti-fc--d{left:3%;top:42%;width:24%}
.cti-fc__rows{display:grid;gap:4px;margin-top:6px}
.cti-fc__rows i{height:6px;border-radius:3px;background:linear-gradient(90deg,var(--c-teal) var(--f,0%),#DDE2EC var(--f,0%));animation:ctiFill 4s ease-in-out infinite;animation-delay:calc(var(--i)*.5s)}
@property --f{syntax:"<percentage>";inherits:false;initial-value:0%}
@keyframes ctiFill{0%{--f:0%}60%,100%{--f:100%}}
.cti-hv__chain{list-style:none;margin:12px 0 0;padding:0;display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:6px}
.cti-hv__chain li{position:relative;display:flex;flex-direction:column;align-items:center;gap:5px;text-align:center}
.cti-hv__chain li:not(:last-child):after{content:"";position:absolute;top:16px;left:calc(50% + 20px);right:calc(-50% + 20px);height:2px;background:#ffffff26}
.cti-hv__chain li.is-done:not(:last-child):after{background:var(--c-teal2)}
.cti-hv__chain span{width:34px;height:34px;border-radius:50%;display:grid;place-items:center;background:#ffffff14;border:1px solid #ffffff30;color:#E1E8FF;transition:all .3s}
.cti-hv__chain .is-done span{background:#6EE0CE33;border-color:var(--c-teal2);color:#fff}
.cti-hv__chain .is-cur span{background:var(--c-teal2);color:var(--c-ink);box-shadow:0 0 0 5px #6EE0CE30}
.cti-hv__chain em{font:700 .68rem/1.2 var(--body);font-style:normal;color:#C9D3F5}
.cti-hv__chain .is-done em{color:#fff}
.cti-strip{position:relative;list-style:none;margin:clamp(24px,3vw,36px) 0 0;padding:0;display:grid;grid-template-columns:repeat(4,1fr);gap:10px}
.cti-strip__i{display:grid;grid-template-columns:auto 1fr;grid-template-rows:auto auto;column-gap:12px;row-gap:2px;padding:16px;border-radius:14px;background:#ffffff12;border:1px solid #ffffff22;transition:transform .25s,background .25s}
.cti-strip__i:hover{transform:translateY(-3px);background:#ffffff1c}
.cti-strip__i>span{grid-row:span 2;width:40px;height:40px;border-radius:12px;display:grid;place-items:center;background:#ffffff18;color:var(--c-teal2)}
.cti-strip__i3>span{background:var(--c-teal2);color:var(--c-ink)}
.cti-strip__i strong{font:700 .98rem var(--display);color:#fff}
.cti-strip__i em{font-style:normal;font-size:.84rem;color:#C9D3F5}

/* facts band */
.cti-factsec{padding:clamp(22px,3vw,32px) 0;background:linear-gradient(90deg,#E8EEFF,#EEF2FB 60%,#E3F5F2)}
.cti-facts{list-style:none;margin:0;padding:0;display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:0}
.cti-facts li{display:flex;flex-direction:column;gap:4px;padding:6px 18px;border-left:1px solid #CDD5EA}
.cti-facts li:first-child{border-left:0;padding-left:0}
.cti-facts strong{font:800 clamp(1.7rem,3vw,2.3rem)/1 var(--display);color:var(--c-ink)}
.cti-facts strong small{font-size:.55em;font-weight:700;color:var(--c-teal)}
.cti-facts span{font-size:.82rem;color:var(--c-muted);line-height:1.35}

/* intro */
.cti-intro{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:clamp(24px,4vw,56px);align-items:start}
.cti-intro>*{min-width:0}
.cti-intro__box{background:#fff;border:1px solid var(--c-line);border-radius:20px;padding:clamp(18px,2.4vw,28px);box-shadow:0 24px 40px -36px #07104F}
.cti-intro__box>p{margin:0 0 16px;color:var(--c-ink)}
.cti-intro__box a{color:var(--c-deep);font-weight:600}
.cti-intro__box ul{list-style:none;margin:0;padding:0;display:grid;grid-template-columns:1fr 1fr;gap:10px}
.cti-intro__box li{display:flex;gap:8px;align-items:flex-start;padding:12px;border-radius:12px;background:var(--c-soft)}
.cti-intro__box li .rc-ico{color:var(--c-teal);flex:none;margin-top:3px}
.cti-intro__box li strong{display:block;font:700 .9rem var(--display);color:var(--c-ink)}
.cti-intro__box li span{font-size:.8rem;color:var(--c-muted)}

/* six-stage flow */
.cti-six{background:linear-gradient(160deg,#0F1D72,#0B22A8);border-radius:26px;padding:clamp(18px,3vw,32px);color:#fff;box-shadow:0 40px 70px -50px #07104F}
.cti-six__track{position:relative}
.cti-six__wave{position:absolute;left:4%;right:4%;top:6px;width:92%;height:56px;pointer-events:none}
.cti-six__wave path{fill:none;stroke:#ffffff24;stroke-width:2;vector-effect:non-scaling-stroke}
.cti-six__wave .cti-six__wave2{stroke:var(--c-teal2);stroke-width:3;stroke-dasharray:1;stroke-dashoffset:calc(1 - var(--p));transition:stroke-dashoffset .8s ease}
.cti-six ol{list-style:none;margin:0;padding:0;display:grid;grid-template-columns:repeat(6,minmax(0,1fr));gap:6px;position:relative}
.cti-six button{width:100%;display:flex;flex-direction:column;align-items:center;gap:6px;padding:0 4px 8px;background:none;border:0;cursor:pointer;color:#C9D3F5;text-align:center}
.cti-six button:focus-visible{outline:2px solid var(--c-teal2);outline-offset:4px;border-radius:12px}
.cti-six__dot{width:66px;height:66px;border-radius:50%;display:grid;place-items:center;background:#0A1660;border:2px solid #ffffff2e;color:#E1E8FF;transition:all .35s;box-shadow:inset 0 2px 0 #ffffff1a,0 10px 18px -12px #050B38}
.cti-six .is-past .cti-six__dot{border-color:var(--c-teal2);color:var(--c-teal2)}
.cti-six .is-on .cti-six__dot{background:var(--c-teal2);border-color:var(--c-teal2);color:var(--c-ink);transform:translateY(-4px) scale(1.06);box-shadow:0 0 0 8px #6EE0CE26,0 16px 26px -14px #050B38}
.cti-six__n{font:800 .7rem var(--display);color:#8FA2E0}
.cti-six__t{font:700 .9rem/1.25 var(--display);color:#fff}
.cti-six__panel{display:grid;grid-template-columns:minmax(0,1.1fr) minmax(0,.9fr);gap:20px;align-items:center;margin-top:18px;padding:clamp(16px,2.4vw,24px);border-radius:18px;background:#F7F9FB;color:var(--c-ink);animation:rcPanel .35s ease}
.cti-six__k{font:700 .7rem var(--body);letter-spacing:.12em;text-transform:uppercase;color:var(--c-teal)}
.cti-six__panel h3{margin:6px 0;font-size:1.4rem;color:var(--c-ink)}
.cti-six__panel p{margin:0 0 14px;color:var(--c-muted)}
.cti-six__prog{height:6px;border-radius:3px;background:#DDE2EC;overflow:hidden}
.cti-six__prog i{display:block;height:100%;background:linear-gradient(90deg,var(--c-deep2),var(--c-teal));transition:width .6s ease}
.cti-six__viz{max-width:380px;width:100%;justify-self:end;background:linear-gradient(160deg,#EAEEFF,#E3F5F2);border-radius:14px;padding:10px}
.cti-sv{width:100%;height:auto;display:block}
.cti-sv__f{fill:#B9C3E0;transform-origin:left;transform-box:fill-box;animation:dpaGrowX .6s ease both;animation-delay:calc(var(--i)*90ms)}
.cti-sv__o{fill:#CBD3EA}
.cti-sv__on{fill:var(--c-teal)}
.cti-sv__route{fill:none;stroke:var(--c-amber);stroke-width:2;stroke-dasharray:4 4}
.cti-sv__tgt{fill:none;stroke:var(--c-teal);stroke-width:2;stroke-dasharray:3 3;transform-box:fill-box;transform-origin:center;animation:rcSpin 10s linear infinite}
.cti-sv__node{fill:var(--c-deep)}
.cti-sv__bar{fill:var(--c-teal);transform-box:fill-box;transform-origin:center;animation:ctiBar 1s ease-in-out infinite alternate;animation-delay:calc(var(--i)*-.1s)}
.cti-sv__cell{fill:#DDE2EC}
.cti-sv__cell.is-f{fill:var(--c-deep2);animation:ctiCell .3s ease both;animation-delay:calc(var(--i)*70ms)}
@keyframes ctiCell{from{fill:#DDE2EC}}
.cti-sv__g{fill:none;stroke:#DDE2EC;stroke-width:12;stroke-linecap:round}
.cti-sv__gz{fill:none;stroke:var(--c-teal);stroke-width:12;stroke-linecap:round}
.cti-sv__needle{stroke:var(--c-ink);stroke-width:3;stroke-linecap:round;transform-origin:110px 96px;animation:ctiNeedle .9s cubic-bezier(.3,1.4,.5,1) both}
@keyframes ctiNeedle{from{transform:rotate(-90deg)}}
.cti-sv__t{font:700 9px var(--body);fill:var(--c-muted)}
.cti-sv__stack{fill:#fff;stroke:var(--c-deep2);stroke-width:1.5;animation:ctiStack .5s ease both;animation-delay:calc(var(--i)*120ms)}
@keyframes ctiStack{from{opacity:0;transform:translateY(-10px)}}
.cti-sv__chk{fill:none;stroke:#fff;stroke-width:2.5;stroke-linecap:round;stroke-linejoin:round}

/* dashboard */
.cti-dashsec{background-color:#EEF2FB}
.cti-dashwrap{display:grid;grid-template-columns:minmax(0,.7fr) minmax(0,1.3fr);gap:clamp(24px,4vw,56px);align-items:center}
.cti-dashwrap>*{min-width:0}
.cti-dash{background:linear-gradient(165deg,#0F1D72,#0A1660);border-radius:24px;padding:14px;color:#fff;box-shadow:0 40px 70px -50px #07104F;transform:perspective(1400px) rotateY(-4deg) rotateX(2deg);transition:transform .6s ease}
.cti-dash:hover{transform:none}
.cti-dash__head{display:flex;flex-wrap:wrap;align-items:center;gap:6px 10px;margin-bottom:12px}
.cti-dash__dots{display:flex;gap:5px}.cti-dash__dots i{width:8px;height:8px;border-radius:50%;background:#ffffff30}
.cti-dash__head strong{flex:1;font:700 .9rem var(--display)}
.cti-illus--d{color:#C9D3F5;border-color:#ffffff40}
.cti-dash__status{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:6px;margin-bottom:10px}
.cti-dash__st{position:relative;display:flex;flex-direction:column;gap:6px;padding:10px;border-radius:12px;background:#ffffff0d;border:1px solid #ffffff17}
.cti-dash__st>span{width:28px;height:28px;border-radius:8px;display:grid;place-items:center;background:#ffffff14;color:#E1E8FF}
.cti-dash__st em{font:700 .72rem/1.2 var(--body);font-style:normal;color:#E1E8FF}
.cti-dash__pulse{position:absolute;right:10px;top:12px;width:7px;height:7px;border-radius:50%;background:#8FA2E0}
.cti-dash__st.is-live .cti-dash__pulse{background:var(--c-teal2);box-shadow:0 0 0 0 #6EE0CE;animation:ctiPing 1.6s ease-out infinite}
.cti-dash__st.is-wait .cti-dash__pulse{background:var(--c-amber)}
.cti-dash__st.is-done .cti-dash__pulse{background:#fff}
@keyframes ctiPing{to{box-shadow:0 0 0 8px #6EE0CE00}}
.cti-dash__st b{display:block;height:4px;border-radius:2px;background:#ffffff1a;overflow:hidden}
.cti-dash__st b i{display:block;height:100%;width:0;background:var(--c-teal2);transition:width 1.2s ease;transition-delay:calc(var(--i)*120ms)}
.cti-dash.is-in .cti-dash__st b i{width:calc(35% + var(--i)*13%)}
.cti-dash__grid{display:grid;grid-template-columns:1fr 1fr;gap:8px}
.cti-dash__card{background:#ffffff0b;border:1px solid #ffffff17;border-radius:14px;padding:12px;min-width:0}
.cti-dash__ct{display:flex;align-items:center;gap:6px;font:700 .64rem var(--body);letter-spacing:.1em;text-transform:uppercase;color:#A9B8E8;margin-bottom:10px}
.cti-dash__q{display:grid;grid-template-columns:96px 1fr;gap:8px;align-items:center;font-size:.74rem;color:#E1E8FF;margin-bottom:8px}
.cti-dash__q>i{height:8px;border-radius:4px;background:#ffffff14;overflow:hidden}
.cti-dash__q b{display:block;height:100%;width:0;border-radius:4px;background:linear-gradient(90deg,#6E8BFF,var(--c-teal2));transition:width 1.4s cubic-bezier(.2,.8,.2,1);transition-delay:calc(var(--i)*150ms)}
.cti-dash.is-in .cti-dash__q b{width:calc(var(--w)*100%)}
.cti-dash__rings>div{display:flex;justify-content:space-around;gap:6px}
.cti-dash__rings figure{margin:0;display:flex;flex-direction:column;align-items:center;gap:6px}
.cti-dash__rings svg{width:64px;height:64px;transform:rotate(-90deg)}
.cti-dash__rb{fill:none;stroke:#ffffff17;stroke-width:7}
.cti-dash__rf{fill:none;stroke:var(--c);stroke-width:7;stroke-linecap:round;stroke-dasharray:0 100;transition:stroke-dasharray 1.5s ease;transition-delay:calc(var(--i)*200ms)}
.cti-dash.is-in .cti-dash__rf{stroke-dasharray:calc(var(--p)*100) 100}
.cti-dash__rings figcaption{font-size:.7rem;font-weight:600;color:#E1E8FF;text-align:center}
.cti-dash__gauge svg{width:100%;max-width:200px;display:block;margin:0 auto}
.cti-dash__ga{fill:none;stroke:#ffffff1a;stroke-width:12;stroke-linecap:round}
.cti-dash__gz{fill:none;stroke:var(--c-teal2);stroke-width:12;stroke-linecap:round}
.cti-dash__needle{stroke:#fff;stroke-width:3;stroke-linecap:round;transform-origin:80px 84px;transform:rotate(-80deg);transition:transform 1.4s cubic-bezier(.3,1.3,.5,1) .3s}
.cti-dash.is-in .cti-dash__needle{transform:rotate(48deg)}
.cti-dash__gauge circle{fill:#fff}
.cti-dash__gl{display:flex;justify-content:space-between;font-size:.66rem;font-weight:700;color:#A9B8E8;max-width:200px;margin:2px auto 0}
.cti-dash__live{width:7px;height:7px;border-radius:50%;background:#C2603F;animation:ctiBlink 1.4s ease-in-out infinite}
.cti-dash__wave{display:flex;align-items:center;gap:2px;height:38px;margin-bottom:10px}
.cti-dash__wave i{flex:1;height:calc(var(--h)*100%);border-radius:2px;background:var(--c-teal2);opacity:.85;transform-origin:center;animation:ctiBar 1s ease-in-out infinite alternate;animation-delay:calc(var(--i)*-.09s)}
.cti-dash__resp .cti-dash__ct{margin-bottom:6px}
.cti-dash__resp>div{display:flex;align-items:flex-end;gap:5px;height:40px}
.cti-dash__resp>div i{flex:1;height:calc(var(--h)*100%);border-radius:3px 3px 0 0;background:#6E8BFF;transform-origin:bottom;transform:scaleY(0);transition:transform .8s ease;transition-delay:calc(var(--i)*80ms)}
.cti-dash.is-in .cti-dash__resp>div i{transform:none}

/* technology chain: tiles with depth */
.cti-tech{position:relative;margin-bottom:20px;padding:22px 10px 8px;border-radius:22px;background:linear-gradient(170deg,#F7F9FB,#EAEEFF);border:1px solid var(--c-line)}
.cti-tech__rail{position:absolute;left:7%;right:7%;top:62px;height:2px;background:repeating-linear-gradient(90deg,#8FA2E0 0 6px,transparent 6px 12px);animation:ctiRail 1.2s linear infinite}
@keyframes ctiRail{to{background-position:12px 0}}
.cti-tech__rail i{position:absolute;top:-4px;left:0;width:10px;height:10px;border-radius:50%;background:var(--c-teal);box-shadow:0 0 10px var(--c-teal2);animation:ctiTravel 5s linear infinite}
@keyframes ctiTravel{to{left:calc(100% - 10px)}}
.cti-tech ol{list-style:none;margin:0;padding:0;display:grid;grid-template-columns:repeat(7,minmax(0,1fr));gap:8px;position:relative}
.cti-tech li{display:flex;flex-direction:column;align-items:center;gap:18px;text-align:center;opacity:0;transform:translateY(12px);transition:opacity .45s,transform .45s;transition-delay:calc(var(--i)*100ms)}
.cti-tech.is-in li{opacity:1;transform:none}
.cti-tech__tile{width:76px;height:76px;border-radius:18px;background:linear-gradient(160deg,#0B22A8,#0B22A8);box-shadow:0 8px 0 #0A1660,0 20px 26px -14px #07104F;display:grid;place-items:center;transition:transform .25s,box-shadow .25s}
.cti-tech__top{width:56px;height:56px;border-radius:14px;display:grid;place-items:center;background:linear-gradient(160deg,#ffffff2a,#ffffff0d);color:#E3F5F2}
.cti-tech li:nth-child(4) .cti-tech__tile{background:linear-gradient(160deg,#19B39C,#0E9C88);box-shadow:0 8px 0 #0A7A6A,0 20px 26px -14px #07104F}
.cti-tech li:hover .cti-tech__tile{transform:translateY(-4px);box-shadow:0 12px 0 #0A1660,0 26px 30px -14px #07104F}
.cti-tech em{font:700 .82rem/1.2 var(--display);font-style:normal;color:var(--c-ink)}

/* quality monitor strip */
.cti-qmon{margin-top:clamp(28px,4vw,44px);display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:10px}
.cti-qmon__i{display:flex;flex-direction:column;gap:10px;padding:16px;border-radius:18px;background:#fff;border:1px solid var(--c-line)}
.cti-qmon__k{display:flex;align-items:center;gap:7px;font:700 .68rem var(--body);letter-spacing:.1em;text-transform:uppercase;color:var(--c-muted)}
.cti-qmon__i>em{font-style:normal;font-size:.84rem;color:var(--c-muted)}
.cti-qmon__wave{display:flex;align-items:center;gap:3px;height:44px}
.cti-qmon__wave i{flex:1;height:calc(var(--h)*100%);border-radius:2px;background:var(--c-deep2);animation:ctiBar 1.1s ease-in-out infinite alternate;animation-delay:calc(var(--i)*-.1s)}
.cti-qmon__i ul{list-style:none;margin:0;padding:0;display:grid;gap:6px}
.cti-qmon__i li{display:flex;align-items:center;gap:8px;padding:7px 10px;border-radius:9px;font-weight:600;font-size:.84rem}
.cti-qmon__i li.is-0{background:#E3F5F2;color:#0A7A6A}
.cti-qmon__i li.is-1{background:#E8EEFF;color:var(--c-deep)}
.cti-qmon__i li.is-2{background:#FBF3DD;color:#8A6A1E}
.cti-qmon__flow{display:flex;align-items:center;gap:6px;height:44px}
.cti-qmon__flow span{width:38px;height:38px;border-radius:11px;display:grid;place-items:center;background:var(--c-deep);color:#E3F5F2;flex:none}
.cti-qmon__flow span:nth-of-type(2){background:var(--c-teal)}
.cti-qmon__flow i{flex:1;height:2px;background:repeating-linear-gradient(90deg,var(--c-teal) 0 6px,transparent 6px 11px);animation:ctiRail 1s linear infinite}

/* why cati */
.cti-whycati{display:grid;grid-template-columns:minmax(0,.7fr) minmax(0,1.3fr);gap:clamp(24px,4vw,56px);align-items:start}
.cti-whycati>*{min-width:0}
.cti-uses{list-style:none;margin:0;padding:0;display:grid;grid-template-columns:1fr 1fr;gap:0;border-top:1px solid #CFD6E3}
.cti-uses li{display:flex;gap:14px;padding:20px 18px 20px 0;border-bottom:1px solid #CFD6E3}
.cti-uses li:nth-child(odd){border-right:1px solid #CFD6E3}
.cti-uses li:nth-child(even){padding-left:18px}
.cti-uses__ic{width:40px;height:40px;border-radius:10px;display:grid;place-items:center;background:#fff;color:var(--c-teal);flex:none;box-shadow:0 0 0 1px var(--c-line)}
.cti-uses h3{font-size:1.02rem;margin:0 0 4px;color:var(--c-ink)}
.cti-uses p{margin:0;font-size:.88rem;color:var(--c-muted)}

/* capabilities */
.cti-cap{display:grid;grid-template-columns:repeat(3,1fr);gap:12px}
.cti-cap__card{display:flex;flex-direction:column;gap:8px;padding:22px;border-radius:18px;background:#fff;border:1px solid var(--c-line);position:relative;overflow:hidden}
.cti-cap__card:after{content:"";position:absolute;left:0;right:0;bottom:0;height:3px;background:linear-gradient(90deg,var(--c-blue),var(--c-teal));transform:scaleX(0);transform-origin:left;transition:transform .35s}
.cti-cap__card:hover:after{transform:scaleX(1)}
.cti-cap__ic{width:46px;height:46px;border-radius:13px;display:grid;place-items:center;background:#E3F5F2;color:var(--c-teal)}
.cti-cap__card:nth-child(-n+3) .cti-cap__ic{background:var(--c-ink);color:#6EE0CE}
.cti-cap__card h3{margin:4px 0 0;font-size:1.08rem;color:var(--c-ink)}
.cti-cap__card p{margin:0;font-size:.9rem;color:var(--c-muted);flex:1}
.cti-cap__card .rc-link{font-size:.86rem}
.cti-prog{margin-top:14px;display:grid;grid-template-columns:minmax(0,.7fr) minmax(0,2fr);gap:18px;align-items:center;padding:18px 20px;border-radius:18px;border:1px dashed #C3CBDA;background:#FAFBFC}
.cti-prog__h strong{display:block;font:700 1rem var(--display);color:var(--c-ink)}
.cti-prog__h span{font-size:.84rem;color:var(--c-muted)}
.cti-prog ul{list-style:none;margin:0;padding:0;display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:10px}
.cti-prog li{display:flex;gap:8px;align-items:flex-start}
.cti-prog li .rc-ico{color:var(--c-muted);flex:none;margin-top:2px}
.cti-prog li strong{display:block;font:700 .88rem var(--display);color:var(--c-ink)}
.cti-prog li span{font-size:.78rem;color:var(--c-muted)}
.cti-usecases{margin-top:28px;display:flex;flex-wrap:wrap;gap:8px;align-items:center}
.cti-usecases__k{font:700 .72rem var(--body);letter-spacing:.12em;text-transform:uppercase;color:var(--c-muted);margin-right:6px}
.cti-usecases ul{list-style:none;margin:0;padding:0;display:contents}
.cti-usecases li{padding:7px 13px;border-radius:999px;background:var(--c-soft);border:1px solid var(--c-line);font-weight:600;font-size:.86rem;color:var(--c-ink);transition:background .2s,color .2s}
.cti-usecases li:hover{background:var(--c-teal);color:#fff;border-color:var(--c-teal)}

/* audiences */
.cti-aud{display:grid;grid-template-columns:repeat(3,1fr);gap:0;border:1px solid #ffffff1f;border-radius:22px;overflow:hidden}
.cti-aud__col{padding:clamp(20px,2.6vw,32px);display:flex;flex-direction:column;gap:6px;transition:background .3s}
.cti-aud__col+.cti-aud__col{border-left:1px solid #ffffff1f}
.cti-aud__col:hover{background:#ffffff08}
.cti-aud__ic{width:48px;height:48px;border-radius:14px;display:grid;place-items:center;margin-bottom:6px}
.cti-aud__col0 .cti-aud__ic{background:#6E8BFF26;color:#9DB0FF}
.cti-aud__col1 .cti-aud__ic{background:#E7C87326;color:#E7C873}
.cti-aud__col2 .cti-aud__ic{background:#4FD1B526;color:#4FD1B5}
.cti-aud__k{font:800 2rem/1 var(--display);color:#fff}
.cti-aud__col h3{color:#C9D0EA;font-size:.95rem;font-weight:600;margin:0 0 10px}
.cti-aud__col ul{list-style:none;margin:0;padding:0;display:flex;flex-wrap:wrap;gap:6px}
.cti-aud__col li{padding:6px 11px;border-radius:999px;border:1px solid #ffffff2a;font-size:.84rem;font-weight:600;color:#E4E8F7}

/* languages */
.cti-langwrap{display:grid;grid-template-columns:minmax(0,.75fr) minmax(0,1.25fr);gap:clamp(24px,4vw,56px);align-items:center}
.cti-langwrap>*{min-width:0}
.cti-lang{display:grid;grid-template-columns:1fr 1fr;gap:12px}
.cti-lang__c{border-radius:20px;padding:18px;display:flex;flex-direction:column;gap:10px;border:1px solid var(--c-line);background:#fff}
.cti-lang__c2{grid-column:1/-1;background:var(--c-ink);border-color:var(--c-ink)}
.cti-lang__r{display:flex;align-items:center;gap:7px;font:700 .76rem var(--body);letter-spacing:.1em;text-transform:uppercase;color:var(--c-teal)}
.cti-lang__c2 .cti-lang__r{color:#6EE0CE}
.cti-lang ul{list-style:none;margin:0;padding:0;display:flex;flex-wrap:wrap;gap:6px}
.cti-lang button{padding:7px 12px;border-radius:10px;border:1px solid var(--c-line);background:var(--c-soft);font:700 .9rem var(--display);color:var(--c-ink);cursor:default;transition:all .2s}
.cti-lang__c2 button{background:#ffffff10;border-color:#ffffff24;color:#fff}
.cti-lang button.is-on{background:var(--c-teal);border-color:var(--c-teal);color:#fff;transform:translateY(-2px)}
.cti-lang button.is-dim{opacity:.4}
.cti-lang button:focus-visible{outline:2px solid var(--c-amber);outline-offset:2px}
.cti-lang__n{font-size:.76rem;color:var(--c-muted);margin-top:auto}
.cti-lang__c2 .cti-lang__n{color:#9DA8CC}

/* ops */
.cti-glance{list-style:none;margin:0 0 22px;padding:0;display:flex;flex-wrap:wrap;gap:6px}
.cti-glance li{display:flex;align-items:center;gap:7px;padding:7px 12px 7px 7px;border-radius:999px;background:#fff;border:1px solid var(--c-line);font-weight:600;font-size:.84rem;color:var(--c-ink)}
.cti-glance li span{width:22px;height:22px;border-radius:50%;display:grid;place-items:center;background:var(--c-ink);color:#fff;font-size:.7rem;font-weight:800}
.cti-ops{display:grid;grid-template-columns:minmax(0,.8fr) minmax(0,1.2fr);gap:16px;align-items:start}
.cti-ops__list{list-style:none;margin:0;padding:0;display:grid;gap:6px;position:relative}
.cti-ops__list:before{content:"";position:absolute;left:23px;top:18px;bottom:18px;width:2px;background:#D5DCE7}
.cti-ops__list button{position:relative;width:100%;display:grid;grid-template-columns:48px 1fr auto;align-items:center;gap:10px;padding:10px 14px 10px 0;border:1px solid transparent;border-radius:14px;background:none;cursor:pointer;text-align:left;color:var(--c-muted);transition:all .2s}
.cti-ops__list button:hover{background:#fff}
.cti-ops__list button:focus-visible{outline:2px solid var(--c-teal);outline-offset:2px}
.cti-ops__n{justify-self:center;width:30px;height:30px;border-radius:50%;display:grid;place-items:center;background:#fff;border:2px solid #D5DCE7;font:800 .72rem var(--display);color:#8A93AA;z-index:1;transition:all .2s}
.cti-ops__t{font:700 .96rem var(--display);color:var(--c-ink)}
.cti-ops__list .is-past .cti-ops__n{border-color:var(--c-teal);color:var(--c-teal)}
.cti-ops__list .is-on{background:#fff;border-color:var(--c-line);box-shadow:0 14px 28px -24px #07104F;color:var(--c-teal)}
.cti-ops__list .is-on .cti-ops__n{background:var(--c-teal);border-color:var(--c-teal);color:#fff}
.cti-ops__panel{position:sticky;top:calc(var(--header-h) + 80px);background:#fff;border:1px solid var(--c-line);border-radius:22px;padding:clamp(20px,3vw,32px);animation:rcPanel .35s ease}
.cti-ops__k{font:700 .72rem var(--body);letter-spacing:.12em;text-transform:uppercase;color:var(--c-teal)}
.cti-ops__panel h3{display:flex;align-items:center;gap:12px;font-size:1.5rem;margin:10px 0 8px;color:var(--c-ink)}
.cti-ops__panel h3>span{width:46px;height:46px;border-radius:13px;display:grid;place-items:center;background:var(--c-ink);color:#6EE0CE}
.cti-ops__panel>p{color:var(--c-muted);margin:0 0 16px}
.cti-ops__panel ul{list-style:none;margin:0;padding:0;display:grid;gap:8px}
.cti-ops__panel li{display:flex;align-items:center;gap:8px;padding:10px 12px;border-radius:10px;background:var(--c-soft);font-weight:600;font-size:.92rem;animation:rcPanel .4s ease both;animation-delay:calc(var(--i)*60ms)}
.cti-ops__panel li .rc-ico{color:var(--c-teal)}
.cti-ops__nav{display:flex;gap:8px;margin-top:18px}
.cti-ops__nav button{width:40px;height:40px;border-radius:50%;border:1px solid var(--c-line);background:#fff;cursor:pointer;font-size:1rem;color:var(--c-ink)}
.cti-ops__nav button:hover{border-color:var(--c-teal);color:var(--c-teal)}
.cti-bc{margin-top:18px;padding:16px;border-radius:14px;border:1px solid #BFE9E1;background:#F0FBF8}
.cti-bc__k{font:700 .72rem var(--body);letter-spacing:.1em;text-transform:uppercase;color:var(--c-teal)}
.cti-bc__bar{position:relative;height:10px;border-radius:5px;background:#E2E7F3;margin:14px 0 26px}
.cti-bc__bar i{position:absolute;left:30%;right:0;top:0;bottom:0;border-radius:5px;background:linear-gradient(90deg,#8FE5D6,var(--c-teal))}
.cti-bc__bar b{position:absolute;top:14px;transform:translateX(-50%);font:700 .76rem var(--body);color:var(--c-ink)}
.cti-bc__bar b:last-child{transform:translateX(-100%)}
.cti-bc__note{font-size:.82rem;color:var(--c-muted)}

/* mid cta */
.cti-mid{background:linear-gradient(100deg,#0B22A8,#0E9C88);color:#fff;padding:clamp(26px,4vw,40px) 0}
.cti-mid__in{display:flex;align-items:center;justify-content:space-between;gap:24px;flex-wrap:wrap}
.cti-mid strong{display:block;font:700 clamp(1.15rem,2vw,1.45rem) var(--display)}
.cti-mid span{color:#D6F5EF;max-width:62ch;display:block}

/* quality */
.cti-qc{display:grid;grid-template-columns:minmax(0,.7fr) minmax(0,1.3fr);gap:clamp(24px,4vw,56px);align-items:center}
.cti-qc__core{position:relative;max-width:300px;width:100%;justify-self:center}
.cti-qc__core>svg{width:100%;transform:rotate(-90deg)}
.cti-qc__seg{fill:none;stroke:#BFE9E1;stroke-width:14;transition:stroke .25s}
.cti-qc__seg.is-on{stroke:var(--c-amber)}
.cti-qc__core:hover .cti-qc__seg:not(.is-on){stroke:#BFE9E1}
.cti-qc__core>span{position:absolute;inset:20%;border-radius:50%;background:var(--c-ink);color:#6EE0CE;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:6px;text-align:center;padding:10px}
.cti-qc__core strong{font:700 .95rem/1.25 var(--display);color:#fff}
.cti-qc__list{list-style:none;margin:0;padding:0;display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:10px}
.cti-qc__list li{display:flex;flex-direction:column;gap:8px;padding:16px;border-radius:16px;background:#fff;border:1px solid var(--c-line);outline:none;transition:all .2s}
.cti-qc__list li>span{width:36px;height:36px;border-radius:10px;display:grid;place-items:center;background:#E3F5F2;color:var(--c-teal)}
.cti-qc__list li.is-on,.cti-qc__list li:focus-visible{border-color:var(--c-amber);transform:translateY(-2px);box-shadow:0 16px 28px -22px var(--c-amber)}
.cti-qc__list strong{display:block;font:700 .95rem var(--display);color:var(--c-ink)}
.cti-qc__list em{font-style:normal;font-size:.82rem;color:var(--c-muted)}
.cti-sec-block{margin-top:clamp(36px,5vw,56px);display:grid;grid-template-columns:minmax(0,.8fr) minmax(0,1.6fr);gap:20px;align-items:center;padding:clamp(18px,2.4vw,26px);border-radius:20px;background:var(--c-ink);color:#fff}
.cti-sec-block__h{display:flex;gap:12px;align-items:flex-start}
.cti-sec-block__h>.rc-ico{color:#6EE0CE;flex:none;margin-top:4px}
.cti-sec-block h3{color:#fff;margin:0 0 4px;font-size:1.2rem}
.cti-sec-block p{margin:0;color:#C9D0EA;font-size:.9rem}
.cti-sec-block ul{list-style:none;margin:0;padding:0;display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:8px}
.cti-sec-block li{display:flex;align-items:center;gap:8px;padding:10px 12px;border-radius:10px;background:#ffffff0d;border:1px solid #ffffff1a;font-weight:600;font-size:.86rem}
.cti-sec-block li .rc-ico{color:#6EE0CE;flex:none}

/* infrastructure */
.cti-inf.is-in .cti-inf__tiers{display:grid;grid-template-columns:repeat(3,minmax(0,1fr)) minmax(0,.8fr);gap:10px}
.cti-inf__tier{padding:18px;border-radius:18px;background:#fff;border:1px solid var(--c-line);border-top:4px solid var(--c-ink)}
.cti-inf__tier:nth-child(2){border-top-color:var(--c-teal)}
.cti-inf__tier:nth-child(3){border-top-color:var(--c-amber)}
.cti-inf__th{display:flex;align-items:center;gap:8px;font:700 .76rem var(--body);letter-spacing:.1em;text-transform:uppercase;color:var(--c-muted);margin-bottom:12px}
.cti-inf__tier ul{list-style:none;margin:0;padding:0;display:grid;gap:6px}
.cti-inf__tier li{display:flex;justify-content:space-between;gap:8px;align-items:baseline;padding:8px 10px;border-radius:8px;background:var(--c-soft);font-size:.86rem}
.cti-inf__tier li strong{font-weight:700;color:var(--c-ink)}
.cti-inf__tier li em{font-style:normal;font:700 .74rem var(--body);color:var(--c-teal);white-space:nowrap}
.cti-inf__partner{padding:18px;border-radius:18px;border:1px dashed #B9C2D3;background:transparent}
.cti-inf__partner p{margin:0;font-size:.86rem;color:var(--c-muted)}
.cti-tz{margin-top:clamp(36px,5vw,56px);display:grid;grid-template-columns:220px 1fr;gap:clamp(20px,4vw,48px);align-items:center;padding:clamp(18px,2.6vw,30px);border-radius:22px;background:#fff;border:1px solid var(--c-line)}
.cti-tz h3{margin:0 0 6px;font-size:1.35rem;color:var(--c-ink)}
.cti-tz p{color:var(--c-muted);margin:0 0 12px}
.cti-tz__lg{list-style:none;margin:0 0 12px;padding:0;display:flex;flex-wrap:wrap;gap:6px 16px;font-size:.84rem;font-weight:600;color:var(--c-ink)}
.cti-tz__lg li{display:flex;align-items:center;gap:6px}
.cti-tz__lg i{width:16px;height:5px;border-radius:3px}
.cti-tz__lg .a0,.cti-clock__a0{background:var(--c-teal);stroke:var(--c-teal)}
.cti-tz__lg .a1,.cti-clock__a1{background:var(--c-amber);stroke:var(--c-amber)}
.cti-tz__lg .a2,.cti-clock__a2{background:#6E8BFF;stroke:#6E8BFF}
.cti-clock{width:100%;max-width:220px}
.cti-clock__face{fill:var(--c-soft);stroke:var(--c-line)}
.cti-clock__tick{stroke:#9AA4B8;stroke-width:1.2}
.cti-clock__h{font:700 10px var(--body);fill:#7A849E}
.cti-clock__a{fill:none;stroke-width:7;stroke-linecap:round}
.cti-clock__c{font:800 18px var(--display);fill:var(--c-ink)}
.cti-clock__s{font:700 9px var(--body);fill:#7A849E;letter-spacing:.1em}

/* industries */
.cti-ind{list-style:none;margin:0;padding:0;display:grid;grid-template-columns:repeat(4,1fr);gap:10px}
.cti-ind li{display:flex;align-items:center;gap:12px;padding:14px;border-radius:14px;background:#fff;border:1px solid var(--c-line);font:700 .92rem/1.25 var(--display);color:var(--c-ink);transition:transform .2s,border-color .2s}
.cti-ind li:hover{transform:translateY(-2px);border-color:var(--c-teal)}
.cti-ind li>span{width:40px;height:40px;border-radius:11px;display:grid;place-items:center;background:var(--c-soft);color:var(--c-teal);flex:none;transition:background .2s,color .2s}
.cti-ind li:hover>span{background:var(--c-teal);color:#fff}

/* experience */
.cti-exphead{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,.8fr);gap:24px;align-items:end;margin-bottom:22px}
.cti-cred{display:grid;gap:8px}
.cti-cred>div{display:flex;gap:10px;align-items:flex-start;padding:12px 14px;border-radius:14px;background:#fff;border:1px solid var(--c-line)}
.cti-cred .rc-ico{color:var(--c-teal);flex:none;margin-top:3px}
.cti-cred p{margin:0;font-size:.9rem;color:var(--c-muted)}
.cti-cred strong{color:var(--c-ink)}
.cti-exp__f{display:flex;flex-wrap:wrap;gap:6px;margin-bottom:14px}
.cti-exp__f button{display:inline-flex;align-items:center;gap:8px;padding:8px 14px;border-radius:999px;border:1px solid var(--c-line);background:#fff;font:600 .88rem var(--body);color:var(--c-ink);cursor:pointer}
.cti-exp__f button span{font-size:.72rem;font-weight:800;padding:1px 7px;border-radius:999px;background:var(--c-soft)}
.cti-exp__f button.is-on{background:var(--c-ink);border-color:var(--c-ink);color:#fff}
.cti-exp__f button.is-on span{background:#ffffff26}
.cti-exp__grid{list-style:none;margin:0;padding:0;display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px}
.cti-exp__card{display:flex;flex-direction:column;gap:6px;padding:20px;border-radius:18px;background:#fff;border:1px solid var(--c-line);border-left:4px solid var(--c-teal)}
.cti-exp__card--b{border-left-color:var(--c-amber)}
.cti-exp__top{display:flex;justify-content:space-between;gap:8px;align-items:center}
.cti-exp__tag{font:700 .66rem var(--body);letter-spacing:.1em;text-transform:uppercase;color:var(--c-teal)}
.cti-exp__card--b .cti-exp__tag{color:#9A7420}
.cti-exp__m{font-size:.76rem;font-weight:600;color:var(--c-muted)}
.cti-exp__n{font:800 2.1rem/1 var(--display);color:var(--c-ink);margin-top:4px}
.cti-exp__n--t{font-size:1.25rem;line-height:1.2}
.cti-exp__who{font:700 .98rem var(--display);color:var(--c-ink)}
.cti-exp__card p{margin:0;font-size:.86rem;color:var(--c-muted);flex:1}
.cti-exp__mk{list-style:none;margin:6px 0 0;padding:0;display:flex;flex-wrap:wrap;gap:5px}
.cti-exp__mk li{font-size:.74rem;font-weight:700;padding:3px 9px;border-radius:999px;background:var(--c-soft);color:var(--c-ink)}
.cti-exp__more{margin-top:14px}

/* team */
.cti-team{display:flex;flex-direction:column;align-items:center;gap:0}
.cti-team__pm{display:flex;flex-direction:column;align-items:center;text-align:center;gap:6px;padding:20px 24px;border-radius:18px;background:var(--c-ink);color:#fff;max-width:340px;position:relative}
.cti-team__pm:after{content:"";position:absolute;left:50%;bottom:-28px;width:2px;height:28px;background:#C3CBDA}
.cti-team__pm>span{width:46px;height:46px;border-radius:50%;display:grid;place-items:center;background:#ffffff14;color:#6EE0CE}
.cti-team__pm strong{font:700 1.1rem var(--display)}
.cti-team__pm em,.cti-team li em{font-style:normal;font-size:.86rem;color:#C9D0EA}
.cti-team ul{list-style:none;margin:28px 0 0;padding:28px 0 0;display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px;width:100%;position:relative;border-top:2px solid #C3CBDA}
.cti-team li{position:relative;display:flex;flex-direction:column;align-items:center;text-align:center;gap:6px;padding:18px;border-radius:16px;background:#fff;border:1px solid var(--c-line)}
.cti-team li:before{content:"";position:absolute;left:50%;top:-30px;width:2px;height:28px;background:#C3CBDA}
.cti-team li>span{width:44px;height:44px;border-radius:50%;display:grid;place-items:center;background:#E3F5F2;color:var(--c-teal)}
.cti-team li strong{font:700 1rem var(--display);color:var(--c-ink)}
.cti-team li em{color:var(--c-muted)}

/* standards */
.cti-std__in{display:grid;grid-template-columns:minmax(0,.7fr) minmax(0,1.3fr);gap:clamp(24px,4vw,56px);align-items:center}
.cti-std__in>*{min-width:0}
.cti-std ul{list-style:none;margin:0;padding:0;display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:10px}
.cti-std li{display:flex;flex-direction:column;gap:4px;padding:16px;border-radius:14px;border:1px solid var(--c-line);background:#fff}
.cti-std li strong{font:800 1.02rem var(--display);color:var(--c-ink)}
.cti-std li span{font-size:.84rem;color:var(--c-muted)}
.cti-std li em{font-style:normal;font:700 .7rem var(--body);letter-spacing:.06em;text-transform:uppercase;color:var(--c-teal);margin-top:4px}

/* ecosystem */
.cti-eco{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:clamp(24px,4vw,56px);align-items:center}
.cti-eco>*{min-width:0}
.cti-secres{margin-top:18px;padding:18px;border-radius:18px;background:#fff;border:1px solid var(--c-line)}
.cti-secres strong{display:flex;align-items:center;gap:8px;font:700 1rem var(--display);color:var(--c-ink);margin-bottom:10px}
.cti-secres strong .rc-ico{color:var(--c-teal)}
.cti-secres ul{list-style:none;margin:0;padding:0;display:flex;flex-wrap:wrap;gap:6px}
.cti-secres li{font-size:.82rem;font-weight:600;padding:5px 11px;border-radius:999px;background:var(--c-soft);color:var(--c-ink)}
.cti-eco__map{position:relative;width:100%;max-width:440px;aspect-ratio:1;justify-self:center}
.cti-eco__map>svg{position:absolute;inset:0;width:100%;height:100%}
.cti-eco__map line{stroke:#8FE5D6;stroke-width:1.5;stroke-dasharray:4 5;animation:rcDash 3s linear infinite}
.cti-eco__map circle{fill:none;stroke:#DDE2EC}
.cti-eco__core{position:absolute;left:50%;top:50%;width:28%;aspect-ratio:1;transform:translate(-50%,-50%);border-radius:50%;background:var(--c-ink);color:#6EE0CE;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:4px;box-shadow:0 0 0 10px #0E8A8A1f}
.cti-eco__core strong{color:#fff;font:800 1.2rem var(--display)}
.cti-eco__n{position:absolute;width:0;height:0;left:calc(50% + 37.5% * cos(var(--a)));top:calc(50% + 37.5% * sin(var(--a)));text-decoration:none}
.cti-eco__n>span{position:absolute;transform:translate(-50%,-50%);white-space:nowrap;padding:8px 13px;border-radius:999px;background:#fff;border:1.5px solid var(--c-teal);font:700 .82rem var(--display);color:var(--c-ink);transition:all .2s}
.cti-eco__n:hover>span,.cti-eco__n:focus-visible>span{background:var(--c-teal);color:#fff}
.cti-eco__n--x>span{border-style:dashed;border-color:#B9C2D3;color:var(--c-muted)}

/* cta */
.cti-cta{background:radial-gradient(700px 400px at 0% 0%,#0E9C88 0%,transparent 70%),linear-gradient(160deg,#0B22A8,#0A1660)!important}
.cti-cta .rc-kicker{color:#6EE0CE!important}

/* responsive */
@media (max-width:1100px){
  .cti-prog{grid-template-columns:1fr}.cti-prog ul{grid-template-columns:1fr 1fr}
    .cti-inf__tiers{grid-template-columns:1fr 1fr}
  .cti-qc__list{grid-template-columns:1fr 1fr}
  .cti-ind{grid-template-columns:repeat(3,1fr)}
  .cti-std ul{grid-template-columns:1fr 1fr}
}
@media (max-width:900px){
  .cti-hero__in,.cti-intro,.cti-whycati,.cti-langwrap,.cti-ops,.cti-qc,.cti-sec-block,.cti-exphead,.cti-std__in,.cti-eco{grid-template-columns:1fr}
  .cti-strip{grid-template-columns:1fr 1fr}
  .cti-cap,.cti-exp__grid{grid-template-columns:1fr 1fr}
  .cti-aud{grid-template-columns:1fr}.cti-aud__col+.cti-aud__col{border-left:0;border-top:1px solid #ffffff1f}
  .cti-ops__panel{position:static}
  .cti-team ul{grid-template-columns:1fr 1fr;border-top:0}.cti-team li:before{display:none}
  .cti-sec-block ul{grid-template-columns:1fr 1fr}
}
@media (max-width:640px){
  .cti-strip,.cti-cap,.cti-exp__grid,.cti-qc__list,.cti-std ul,.cti-sec-block ul,.cti-prog ul,.cti-intro__box ul,.cti-lang{grid-template-columns:1fr}
  .cti-uses{grid-template-columns:1fr}.cti-uses li,.cti-uses li:nth-child(even){padding:16px 0;border-right:0}
    .cti-inf__tiers{grid-template-columns:1fr}
  .cti-tz{grid-template-columns:1fr;justify-items:center;text-align:center}.cti-tz__lg{justify-content:center}
  .cti-ind{grid-template-columns:1fr 1fr}
  .cti-ind li{font-size:.82rem;padding:10px;gap:8px}.cti-ind li>span{width:34px;height:34px}
  .cti-team ul{grid-template-columns:1fr}
  .cti-eco__map{max-width:340px}
  .cti-eco__n>span{font-size:.7rem;padding:6px 9px}
  .cti-hero .od-hero__ctas .btn,.cti-mid .btn,.cti-cta .od-hero__ctas .btn{width:100%}
  .cti-ops__list button{grid-template-columns:44px 1fr auto}
}
@media (prefers-reduced-motion:reduce){
  .cti *,.cti *:before,.cti *:after{animation:none!important;transition:none!important}
}

/* responsive: new components */
@media (max-width:1100px){
  .cti-facts{grid-template-columns:repeat(3,minmax(0,1fr));row-gap:16px}
  .cti-facts li:nth-child(4){border-left:0;padding-left:0}
  .cti-tech ol{grid-template-columns:repeat(4,minmax(0,1fr));row-gap:18px}.cti-tech__rail{display:none}
}
@media (max-width:900px){
  .cti-dashwrap,.cti-six__panel{grid-template-columns:1fr}
  .cti-dash{transform:none}
  .cti-six ol{grid-template-columns:repeat(3,minmax(0,1fr));row-gap:14px}.cti-six__wave{display:none}
  .cti-qmon{grid-template-columns:1fr}
  .cti-hv{max-width:560px;margin:0 auto;width:100%}
}
@media (max-width:640px){
  .cti-fc{padding:7px 9px;border-radius:10px}
  .cti-fc strong{font-size:.68rem}
  .cti-fc--q{width:40%}
  .cti-fc--d,.cti-fc--r{display:none}
  .cti-fc--l{display:none}
  .cti-hv__chain em{font-size:.6rem}
  .cti-hv__chain span{width:30px;height:30px}
  .cti-hv__chain li:not(:last-child):after{top:14px;left:calc(50% + 17px);right:calc(-50% + 17px)}
  .cti-facts{grid-template-columns:1fr 1fr}
  .cti-facts li,.cti-facts li:nth-child(4){border-left:0;padding:0}
  .cti-facts li:last-child{grid-column:1/-1}
  .cti-six ol{grid-template-columns:1fr 1fr}
  .cti-six__dot{width:54px;height:54px}
  .cti-dash__status{grid-template-columns:1fr 1fr}
  .cti-dash__status>:last-child{grid-column:1/-1}
  .cti-dash__grid{grid-template-columns:1fr}
  .cti-tech ol{grid-template-columns:1fr 1fr}
  .cti-tech__tile{width:64px;height:64px}.cti-tech__top{width:46px;height:46px}
}
@media (prefers-reduced-motion:reduce){
  .cti-tech li{opacity:1!important;transform:none!important}
  .cti-dash .cti-dash__q b{width:calc(var(--w)*100%)!important}
  .cti-dash .cti-dash__rf{stroke-dasharray:calc(var(--p)*100) 100!important}
  .cti-dash .cti-dash__needle{transform:rotate(48deg)!important}
  .cti-dash .cti-dash__resp>div i{transform:none!important}
  .cti-dash .cti-dash__st b i{width:calc(35% + var(--i)*13%)!important}
  .cti-fc,.cti-hv__svg{transform:none!important}
  .cti-hv__sig{opacity:.7!important}
  .cti-fc__rows i{--f:100%}
}
.cti-facts .od-count{font:inherit;color:inherit;letter-spacing:inherit}

/* ===== Offline / Face-to-Face Data Collection (ofc-) — site palette: navy, royal, teal, subtle green ===== */
.ofc{--od-navy:#07104F;--od-blue:#1E5BFF;--od-royal:#0B22A8;--od-sky:#E8EEFF;--od-teal:#0E9C88;--od-teal-soft:#E3F5F2;--od-line:#DDE2EC;--od-muted:#525C78;--od-paper:#F5F7FB;
  --r-navy:#07104F;--r-char:#0F1D72;--r-blue:#0B22A8;--r-soft:#EEF2FB;--r-teal:#0E9C88;--r-gold:#C99A2E;--r-line:#DDE2EC;--r-muted:#525C78;
  --f-ink:#07104F;--f-royal:#0B22A8;--f-bright:#1E5BFF;--f-teal:#0E9C88;--f-teal2:#6EE0CE;--f-green:#2F855A;--f-gold:#C99A2E;--f-line:#DDE2EC;--f-muted:#525C78;--f-soft:#F3F6FB}
.ofc .rc-kicker{color:var(--f-teal)}
.ofc .rc-head--light .rc-kicker{color:var(--f-teal2)}
.ofc-sec--soft{background:var(--f-soft)}
.ofc-sec--ink{background:radial-gradient(760px 380px at 85% 0%,#1E3BB8 0%,transparent 60%),radial-gradient(520px 320px at 0% 100%,#0E9C8833 0%,transparent 70%),linear-gradient(165deg,#0A1660,#07104F);color:#fff}
.ofc-lead{font:600 clamp(1.08rem,1.6vw,1.3rem)/1.5 var(--display);color:var(--f-ink)}
.ofc-h3{font-size:1.2rem;margin:clamp(40px,5vw,60px) 0 16px;color:var(--f-ink)}

/* hero */
.ofc-hero{position:relative;overflow:hidden;color:#fff;padding:clamp(32px,4vw,56px) 0 clamp(28px,3vw,40px);background:radial-gradient(640px 480px at 80% 30%,#1E6BFF55 0%,transparent 62%),radial-gradient(520px 380px at 0% 100%,#0E9C8838 0%,transparent 70%),linear-gradient(160deg,#0B22A8 0%,#0A1A7A 55%,#07104F 100%)}
.ofc-hero__in{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:clamp(24px,4vw,56px);align-items:center}
.ofc-hero__in>*{min-width:0}
.ofc-hero .crumbs a,.ofc-hero .crumbs span{color:#CED8F7}
.ofc-eyebrow{display:inline-flex;align-items:center;gap:8px;font:700 .76rem var(--body);letter-spacing:.14em;text-transform:uppercase;color:var(--f-teal2);margin-bottom:16px}
.ofc-hero h1{font-size:clamp(2.2rem,4.2vw,3.5rem);line-height:1.06;color:#fff;margin-bottom:.3em}
.ofc-hero__sub{font:700 clamp(1.2rem,2vw,1.6rem)/1.35 var(--display);color:#E1E8FF;margin:0 0 14px}
.ofc-hero__sub span{color:var(--f-teal2)}
.ofc-hero__body{color:#C9D3F5;font-size:1.03rem;max-width:58ch;margin:0 0 24px}
.ofc .ofc-btn{background:var(--f-teal2);color:var(--f-ink)}
.ofc .ofc-btn:hover{background:#fff;color:var(--f-ink)}
.ofc-hero .btn--ghost{color:#fff;border-color:#ffffff70}
.ofc-hero .btn--ghost:hover{background:#ffffff1a;color:#fff}
.ofc-art{position:relative;border-radius:26px;box-shadow:0 40px 70px -46px #000,0 0 0 1px #ffffff22}
.ofc-art__svg{display:block;width:100%;height:auto;border-radius:26px}
.ofc-art__city path{fill:none;stroke:#A9C1FF;stroke-opacity:.35;stroke-width:1.5;stroke-linejoin:round}
.ofc-art__floor{fill:#0E1F8C}
.ofc-art__chair path{fill:none;stroke:#3A55C9;stroke-width:7;stroke-linecap:round}
.ofc-art__shoe{stroke:#050B38;stroke-width:8;stroke-linecap:round}
.ofc-art__ground{stroke:#A9C1FF;stroke-opacity:.4;stroke-width:1.5}
.ofc-art__sun{fill:#6EE0CE;fill-opacity:.18}
.ofc-art__table{fill:#E1E8FF}
.ofc-art__leg,.ofc-art__leg2{stroke:#A9C1FF;stroke-opacity:.6;stroke-width:6;stroke-linecap:round}
.ofc-art__leg2{fill:none;stroke:#0A1660;stroke-opacity:1;stroke-width:13}
.ofc-art__head{fill:#E8C3A0}
.ofc-art__p--i .ofc-art__head{fill:#C99872}
.ofc-art__hair{fill:#2A2140}
.ofc-art__hair--i{fill:#1B1530}
.ofc-art__body{fill:#C99A2E}
.ofc-art__body--i{fill:#0E9C88}
.ofc-art__arm{fill:none;stroke:#E8C3A0;stroke-width:9;stroke-linecap:round}
.ofc-art__p--i .ofc-art__arm{stroke:#C99872}
.ofc-art__tab{stroke:#07104F;stroke-width:2}
.ofc-art__tl{fill:#0B22A8}.ofc-art__tl2{fill:#A9B8E8}.ofc-art__dot{fill:#0E9C88}
.ofc-art__talk{fill:none;stroke:#6EE0CE;stroke-width:1.5;stroke-dasharray:4 6;opacity:.7;animation:rcDash 2s linear infinite}
.ofc-art__pt{fill:#6EE0CE}
.ofc-art__p--r{animation:ofcNod 5s ease-in-out infinite;transform-origin:150px 300px}
@keyframes ofcNod{50%{transform:rotate(-1.2deg)}}
.ofc-chip{position:absolute;display:inline-flex;align-items:center;gap:6px;padding:7px 11px;border-radius:999px;background:#fff;color:var(--f-ink);font:700 .76rem var(--body);box-shadow:0 14px 26px -16px #000;animation:ofcFloat 6s ease-in-out infinite}
.ofc-chip .rc-ico{color:var(--f-teal)}
.ofc-chip--capi{left:4%;top:7%}
.ofc-chip--int{left:36%;top:4%;animation-delay:-1.5s}
.ofc-chip--val{right:4%;top:24%;animation-delay:-3s}
.ofc-chip--val .rc-ico{color:var(--f-green)}
.ofc-chip--gps{right:5%;bottom:8%;animation-delay:-4.5s}
@keyframes ofcFloat{50%{transform:translateY(-5px)}}
.ofc-art__tag{position:absolute;left:12px;bottom:10px;font:600 .62rem var(--body);letter-spacing:.08em;text-transform:uppercase;color:#CED8F7;border:1px dashed #ffffff40;border-radius:999px;padding:2px 8px}
.ofc-strip{list-style:none;margin:clamp(24px,3vw,36px) 0 0;padding:0;display:grid;grid-template-columns:repeat(6,minmax(0,1fr));gap:8px}
.ofc-strip li{display:flex;flex-direction:column;gap:6px;padding:14px;border-radius:14px;background:#ffffff12;border:1px solid #ffffff22;transition:transform .25s,background .25s}
.ofc-strip li:hover{transform:translateY(-3px);background:#ffffff1c}
.ofc-strip span{width:36px;height:36px;border-radius:10px;display:grid;place-items:center;background:#ffffff18;color:var(--f-teal2)}
.ofc-strip li:last-child span{background:var(--f-teal2);color:var(--f-ink)}
.ofc-strip strong{font:700 .9rem/1.25 var(--display)}
.ofc-strip em{font-style:normal;font-size:.78rem;color:#C9D3F5;line-height:1.35}

/* why face-to-face */
.ofc-why2{display:grid;grid-template-columns:minmax(0,.9fr) minmax(0,1.1fr);gap:clamp(28px,5vw,64px);align-items:start}
.ofc-why2>*{min-width:0}
.ofc-why2 .od-muted a{color:var(--f-royal);font-weight:600}
.ofc-vs{margin-top:22px;display:grid;grid-template-columns:1fr auto 1fr;gap:10px;align-items:stretch}
.ofc-vs__c{padding:16px;border-radius:16px;background:var(--f-soft);border:1px solid var(--f-line)}
.ofc-vs__c--f{background:var(--f-ink);color:#fff;border-color:var(--f-ink)}
.ofc-vs__k{display:flex;align-items:center;gap:7px;font:700 .74rem var(--body);letter-spacing:.1em;text-transform:uppercase;color:var(--f-royal);margin-bottom:10px}
.ofc-vs__c--f .ofc-vs__k{color:var(--f-teal2)}
.ofc-vs ul{list-style:none;margin:0;padding:0;display:grid;gap:6px;font-size:.9rem;font-weight:600}
.ofc-vs__x{align-self:center;width:34px;height:34px;border-radius:50%;display:grid;place-items:center;background:var(--f-teal);color:#fff;font:800 1.1rem var(--display)}
.ofc-ben{list-style:none;margin:0;padding:0;display:grid;grid-template-columns:1fr 1fr;gap:10px}
.ofc-ben li{display:flex;gap:12px;padding:16px;border-radius:16px;background:#fff;border:1px solid var(--f-line);transition:border-color .2s,transform .2s}
.ofc-ben li:hover{border-color:var(--f-teal);transform:translateY(-2px)}
.ofc-ben li>span{width:38px;height:38px;border-radius:11px;display:grid;place-items:center;background:#E3F5F2;color:var(--f-teal);flex:none}
.ofc-ben h3{font-size:.98rem;margin:0 0 4px;color:var(--f-ink)}
.ofc-ben p{margin:0;font-size:.85rem;color:var(--f-muted)}

/* methods */
.ofc-mth{display:grid;grid-template-columns:minmax(0,.7fr) minmax(0,1.3fr);gap:16px;align-items:stretch}
.ofc-mth__list{list-style:none;margin:0;padding:0;display:grid;gap:8px}
.ofc-mth__list button{width:100%;display:grid;grid-template-columns:28px 40px 1fr auto;align-items:center;gap:12px;padding:14px 16px;border-radius:16px;border:1px solid var(--f-line);background:#fff;cursor:pointer;text-align:left;transition:all .2s}
.ofc-mth__list button:hover{border-color:var(--f-bright)}
.ofc-mth__list button:focus-visible{outline:2px solid var(--f-teal);outline-offset:2px}
.ofc-mth__n{font:800 .74rem var(--display);color:#8A93AA}
.ofc-mth__ic{width:40px;height:40px;border-radius:12px;display:grid;place-items:center;background:#EEF2FB;color:var(--f-royal)}
.ofc-mth__k{font:700 1.02rem var(--display);color:var(--f-ink)}
.ofc-mth__go{color:#B9C2D3;transition:transform .2s}
.ofc-mth__list button.is-on{background:var(--f-ink);border-color:var(--f-ink);box-shadow:0 18px 30px -22px var(--f-ink)}
.ofc-mth__list button.is-on .ofc-mth__k{color:#fff}
.ofc-mth__list button.is-on .ofc-mth__n{color:var(--f-teal2)}
.ofc-mth__list button.is-on .ofc-mth__ic{background:var(--f-teal2);color:var(--f-ink)}
.ofc-mth__list button.is-on .ofc-mth__go{color:var(--f-teal2);transform:translateX(4px)}
.ofc-mth__mob{display:none}
.ofc-mth__panel{display:grid;grid-template-columns:minmax(0,.9fr) minmax(0,1.1fr);gap:22px;align-items:center;padding:clamp(20px,3vw,32px);border-radius:24px;background:#fff;border:1px solid var(--f-line);animation:rcPanel .35s ease}
.ofc-mth__art{border-radius:18px;background:linear-gradient(160deg,#EEF2FB,#E3F5F2);padding:16px}
.ofc-mth__art svg{width:100%;height:auto;display:block}
.ofc-ma__dev{fill:#07104F}.ofc-ma__scr{fill:#fff}.ofc-ma__ln{fill:#0B22A8}.ofc-ma__ln2{fill:#C9D3F5}
.ofc-ma__on{fill:#0E9C88}.ofc-ma__off{fill:#C9D3F5}.ofc-ma__onf{fill:#0E9C88;opacity:.5}.ofc-ma__offf{fill:#C9D3F5}
.ofc-ma__route{fill:none;stroke:#C99A2E;stroke-width:2;stroke-dasharray:4 4}
.ofc-ma__paper{fill:#fff;stroke:#A9B8E8;stroke-width:1.5}.ofc-ma__clip{fill:#0B22A8}
.ofc-ma__box{fill:#fff;stroke:#0B22A8;stroke-width:1.5}.ofc-ma__tick{fill:none;stroke:#0E9C88;stroke-width:2;stroke-linecap:round}
.ofc-ma__pen{fill:#C99A2E}
.ofc-ma__roof{fill:none;stroke:#0B22A8;stroke-width:5;stroke-linejoin:round;stroke-linecap:round}
.ofc-ma__wall{fill:#fff;stroke:#A9B8E8;stroke-width:1.5}.ofc-ma__door{fill:#0B22A8}.ofc-ma__win{fill:#E1E8FF}
.ofc-ma__tickw{fill:none;stroke:#fff;stroke-width:2.5;stroke-linecap:round}
.ofc-ma__desk{fill:#0B22A8}.ofc-ma__ground{stroke:#A9B8E8;stroke-width:2}
.ofc-ma__pin{fill:#A9B8E8;transform-box:fill-box;transform-origin:bottom;animation:ofcPin 2.4s ease-in-out infinite;animation-delay:calc(var(--i)*.4s)}
.ofc-ma__pin.is-on{fill:#0E9C88}
@keyframes ofcPin{50%{transform:translateY(-5px)}}
.ofc-ma__brief{fill:#C99A2E}
.ofc-mth__kk{font:700 .72rem var(--body);letter-spacing:.12em;text-transform:uppercase;color:var(--f-teal)}
.ofc-mth__body h3{font-size:1.45rem;margin:6px 0 8px;color:var(--f-ink)}
.ofc-mth__body>p{margin:0 0 14px;color:var(--f-muted)}
.ofc-mth__l{display:block;font:700 .7rem var(--body);letter-spacing:.1em;text-transform:uppercase;color:#8A93AA;margin-bottom:8px}
.ofc-mth__body ul{list-style:none;margin:0;padding:0;display:grid;grid-template-columns:1fr 1fr;gap:6px}
.ofc-mth__body li{display:flex;align-items:center;gap:7px;padding:8px 10px;border-radius:10px;background:var(--f-soft);font-weight:600;font-size:.86rem;color:var(--f-ink);animation:rcPanel .4s ease both;animation-delay:calc(var(--i)*50ms)}
.ofc-mth__body li .rc-ico,.ofc-mth__mob li .rc-ico{color:var(--f-teal);flex:none}

/* comparison table */
.ofc-cmp{overflow-x:auto;border-radius:20px;border:1px solid var(--f-line);background:#fff}
.ofc-cmp:focus-visible{outline:2px solid var(--f-teal)}
.ofc-cmp table{width:100%;border-collapse:collapse;min-width:560px}
.ofc-cmp th,.ofc-cmp td{padding:14px 20px;text-align:left;border-top:1px solid var(--f-line);font-size:.95rem}
.ofc-cmp thead th{border-top:0;background:var(--f-ink);color:#fff;font:700 .74rem var(--body);letter-spacing:.12em;text-transform:uppercase}
.ofc-cmp tbody th{font:700 1rem var(--display);color:var(--f-ink);display:flex;align-items:center;gap:10px}
.ofc-cmp td{color:var(--f-muted)}
.ofc-cmp tbody tr{transition:background .2s}
.ofc-cmp tbody tr.is-on{background:#EEF2FB}
.ofc-cmp__ic{width:32px;height:32px;border-radius:9px;display:grid;place-items:center;background:#EEF2FB;color:var(--f-royal)}
.ofc-cmp tr.is-on .ofc-cmp__ic{background:var(--f-royal);color:#fff}
.ofc-cmp__cap{display:inline-block;padding:5px 11px;border-radius:999px;font:700 .8rem var(--body)}
.ofc-cmp__cap--dig{background:#E3F5F2;color:#0A7A6A}
.ofc-cmp__cap--paper{background:#FBF3DD;color:#8A6A1E}
.ofc-cmp__cap--mix{background:#E8EEFF;color:var(--f-royal)}
.ofc-cmp__cap--loc{background:#E6F2EA;color:var(--f-green)}

/* audiences */
.ofc-aud{position:relative}
.ofc-aud__net{display:block;width:100%;height:90px}
.ofc-aud__net path{fill:none;stroke:#C9D3F5;stroke-width:2;stroke-dasharray:5 6;vector-effect:non-scaling-stroke;transition:stroke .25s}
.ofc-aud__net path.is-on{stroke:var(--f-teal);stroke-dasharray:none}
.ofc-aud__net circle{fill:var(--f-ink)}
.ofc-aud__hub{position:absolute;left:50%;top:-14px;transform:translateX(-50%);display:inline-flex;align-items:center;gap:7px;padding:8px 14px;border-radius:999px;background:var(--f-ink);color:#fff;font:700 .82rem var(--body);white-space:nowrap}
.ofc-aud__hub .rc-ico{color:var(--f-teal2)}
.ofc-aud__cols{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px}
.ofc-aud__col{display:flex;flex-direction:column;gap:6px;padding:clamp(18px,2.4vw,26px);border-radius:20px;background:#fff;border:1px solid var(--f-line);border-top:4px solid var(--c);transition:transform .25s,box-shadow .25s}
.ofc-aud__col0{--c:#1E5BFF}.ofc-aud__col1{--c:#0B22A8}.ofc-aud__col2{--c:#0E9C88}
.ofc-aud__col.is-on{transform:translateY(-4px);box-shadow:0 24px 40px -30px var(--c)}
.ofc-aud__ic{width:46px;height:46px;border-radius:13px;display:grid;place-items:center;background:color-mix(in srgb,var(--c) 12%,#fff);color:var(--c)}
.ofc-aud__k{font:800 1.9rem/1 var(--display);color:var(--f-ink);margin-top:6px}
.ofc-aud__col h3{font-size:.95rem;font-weight:600;color:var(--f-muted);margin:0 0 8px}
.ofc-aud__col ul{list-style:none;margin:0 0 10px;padding:0;display:flex;flex-wrap:wrap;gap:6px;flex:1;align-content:flex-start}
.ofc-aud__col li{padding:6px 11px;border-radius:999px;background:var(--f-soft);font-size:.84rem;font-weight:600;color:var(--f-ink)}
.ofc-aud__col .rc-link{font-size:.88rem}

/* hard to reach */
.ofc-htr{display:grid;grid-template-columns:minmax(0,.8fr) minmax(0,1.2fr);gap:clamp(24px,4vw,56px);align-items:center}
.ofc-htr>*{min-width:0}
.ofc-htr ul{list-style:none;margin:0;padding:0;display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:10px}
.ofc-htr li{display:flex;flex-direction:column;gap:6px;padding:18px;border-radius:18px;background:#ffffff0d;border:1px solid #ffffff1f;transition:background .25s,border-color .25s}
.ofc-htr li:hover{background:#ffffff17;border-color:var(--f-teal2)}
.ofc-htr li>span{width:40px;height:40px;border-radius:12px;display:grid;place-items:center;background:#6EE0CE22;color:var(--f-teal2);margin-bottom:4px}
.ofc-htr strong{font:700 1rem var(--display)}
.ofc-htr em{font-style:normal;font-size:.84rem;color:#C9D3F5}

/* geography */
.ofc-geo{display:grid;grid-template-columns:minmax(0,.75fr) minmax(0,1.25fr);gap:16px;align-items:stretch}
.ofc-geo__ctl{padding:20px;border-radius:22px;background:#fff;border:1px solid var(--f-line);display:flex;flex-direction:column;gap:12px}
.ofc-geo__k{font:700 .7rem var(--body);letter-spacing:.12em;text-transform:uppercase;color:var(--f-muted)}
.ofc-geo__lv{list-style:none;margin:0;padding:0;display:grid;gap:4px;position:relative}
.ofc-geo__lv:before{content:"";position:absolute;left:12px;top:14px;bottom:14px;width:2px;background:#DDE2EC}
.ofc-geo__lv button{position:relative;width:100%;display:flex;align-items:center;gap:12px;padding:7px 10px 7px 30px;border:0;border-radius:10px;background:none;font:600 .9rem var(--body);color:var(--f-muted);cursor:pointer;text-align:left}
.ofc-geo__lv button:before{content:"";position:absolute;left:7px;top:50%;width:12px;height:12px;margin-top:-6px;border-radius:50%;background:#fff;border:2px solid #C3CBE0}
.ofc-geo__lv button.is-past:before{border-color:var(--f-teal);background:var(--f-teal)}
.ofc-geo__lv button.is-on{background:#EEF2FB;color:var(--f-ink);font-weight:700}
.ofc-geo__lv button.is-on:before{border-color:var(--f-royal);background:var(--f-royal);box-shadow:0 0 0 4px #0B22A826}
.ofc-geo__f{display:flex;flex-wrap:wrap;gap:6px}
.ofc-geo__f button{display:inline-flex;align-items:center;gap:5px;padding:6px 11px;border-radius:999px;border:1px solid var(--f-line);background:#fff;font:600 .82rem var(--body);color:var(--f-ink);cursor:pointer;transition:all .2s}
.ofc-geo__f button.is-on{background:var(--f-teal);border-color:var(--f-teal);color:#fff}
.ofc-geo__f button:focus-visible,.ofc-geo__lv button:focus-visible{outline:2px solid var(--f-royal);outline-offset:2px}
.ofc-geo__map{padding:16px;border-radius:22px;background:linear-gradient(165deg,#0A1660,#07104F);display:flex;flex-direction:column;gap:10px}
.ofc-geo__map svg{width:100%;height:auto;display:block}
.ofc-geo__t{fill:#ffffff10;stroke:#ffffff14;transition:fill .35s,transform .35s;transform-box:fill-box;transform-origin:center}
.ofc-geo__t.is-on.ofc-geo__t--urban{fill:#1E6BFF}
.ofc-geo__t.is-on.ofc-geo__t--semiurban{fill:#0E9C88}
.ofc-geo__t.is-on.ofc-geo__t--rural{fill:#3FA36B}
.ofc-geo__t.is-on{transform:scale(.92)}
.ofc-geo__ring{fill:#6EE0CE14;stroke:#6EE0CE;stroke-width:2;stroke-dasharray:6 6;transition:r .5s ease;animation:rcDash 3s linear infinite}
.ofc-geo__core{fill:#fff}
.ofc-geo__lbl{font:700 13px var(--body);fill:#fff;letter-spacing:.06em;paint-order:stroke;stroke:#07104F;stroke-width:4px}
.ofc-geo__lg{display:flex;flex-wrap:wrap;gap:6px 16px;align-items:center;font-size:.8rem;color:#C9D3F5}
.ofc-geo__lg span{display:flex;align-items:center;gap:6px}
.ofc-geo__lg i{width:12px;height:12px;border-radius:3px}
.ofc-geo__lg i.u{background:#1E6BFF}.ofc-geo__lg i.s{background:#0E9C88}.ofc-geo__lg i.r{background:#3FA36B}
.ofc-geo__lg em{margin-left:auto;font-style:normal;font:600 .66rem var(--body);letter-spacing:.08em;text-transform:uppercase;border:1px dashed #ffffff40;border-radius:999px;padding:2px 8px}

/* process */
.ofc-proc__rail{list-style:none;margin:0;padding:0;display:grid;grid-template-columns:repeat(8,minmax(0,1fr));gap:6px;position:relative}
.ofc-proc__rail:before{content:"";position:absolute;left:6%;right:6%;top:30px;height:3px;border-radius:2px;background:linear-gradient(90deg,var(--f-royal),var(--f-teal));transform:scaleX(0);transform-origin:left;transition:transform 1.3s ease}
.ofc-proc.is-in .ofc-proc__rail:before{transform:scaleX(1)}
.ofc-proc__rail li{opacity:0;transform:translateY(10px);transition:opacity .4s,transform .4s;transition-delay:calc(var(--i)*90ms)}
.ofc-proc.is-in .ofc-proc__rail li{opacity:1;transform:none}
.ofc-proc__rail button{width:100%;display:flex;flex-direction:column;align-items:center;gap:6px;padding:0 4px 8px;border:0;background:none;cursor:pointer;text-align:center}
.ofc-proc__rail button:focus-visible{outline:2px solid var(--f-teal);outline-offset:4px;border-radius:12px}
.ofc-proc__dot{position:relative;z-index:1;width:60px;height:60px;border-radius:50%;display:grid;place-items:center;background:#fff;border:2px solid #C9D3F5;color:var(--f-royal);transition:all .3s}
.ofc-proc__rail .is-past .ofc-proc__dot{border-color:var(--f-teal);color:var(--f-teal)}
.ofc-proc__rail .is-on .ofc-proc__dot{background:var(--f-ink);border-color:var(--f-ink);color:var(--f-teal2);transform:scale(1.08);box-shadow:0 0 0 7px #0B22A81f}
.ofc-proc__n{font:800 .7rem var(--display);color:#8A93AA}
.ofc-proc__t{font:700 .88rem/1.25 var(--display);color:var(--f-ink)}
.ofc-proc__panel{margin-top:18px;display:grid;grid-template-columns:auto minmax(0,1fr) minmax(0,1fr);gap:24px;align-items:center;padding:clamp(18px,3vw,30px);border-radius:22px;background:var(--f-soft);border:1px solid var(--f-line);animation:rcPanel .35s ease}
.ofc-proc__big{font:800 clamp(3rem,6vw,4.6rem)/1 var(--display);color:transparent;-webkit-text-stroke:2px var(--f-royal)}
.ofc-proc__panel h3{margin:0 0 6px;font-size:1.4rem;color:var(--f-ink)}
.ofc-proc__panel p{margin:0;color:var(--f-muted)}
.ofc-proc__panel ul{list-style:none;margin:0;padding:0;display:flex;flex-wrap:wrap;gap:6px}
.ofc-proc__panel li{display:inline-flex;align-items:center;gap:6px;padding:7px 12px;border-radius:999px;background:#fff;border:1px solid var(--f-line);font-weight:600;font-size:.86rem;color:var(--f-ink);animation:rcPanel .4s ease both;animation-delay:calc(var(--i)*50ms)}
.ofc-proc__panel li .rc-ico{color:var(--f-teal)}

/* mid cta */
.ofc-mid{background:linear-gradient(100deg,#0B22A8,#0E9C88);color:#fff;padding:clamp(26px,4vw,40px) 0}
.ofc-mid__in{display:flex;align-items:center;justify-content:space-between;gap:24px;flex-wrap:wrap}
.ofc-mid strong{display:block;font:700 clamp(1.15rem,2vw,1.45rem) var(--display)}
.ofc-mid span{color:#DDF5F0;max-width:62ch;display:block}

/* quality */
.ofc-qc__pipe{display:grid;grid-template-columns:auto 1fr auto;gap:14px;align-items:center;margin-bottom:22px}
.ofc-qc__in,.ofc-qc__out{display:inline-flex;align-items:center;gap:8px;padding:10px 14px;border-radius:12px;font:700 .86rem var(--body);white-space:nowrap}
.ofc-qc__in{background:#ffffff14;border:1px solid #ffffff26;color:#E1E8FF}
.ofc-qc__out{background:var(--f-teal2);color:var(--f-ink)}
.ofc-qc__gates{position:relative;display:flex;justify-content:space-between;align-items:center;height:44px}
.ofc-qc__gates:before{content:"";position:absolute;left:0;right:0;top:50%;height:2px;background:repeating-linear-gradient(90deg,#ffffff40 0 6px,transparent 6px 12px)}
.ofc-qc__gates i{position:relative;width:14px;height:40px;border-radius:7px;background:#ffffff1f;border:1px solid #ffffff33;transition:all .3s}
.ofc-qc.is-in .ofc-qc__gates i{animation:ofcGate 8s linear infinite;animation-delay:calc(var(--i)*1s)}
@keyframes ofcGate{0%,10%{background:#6EE0CE;border-color:#6EE0CE}14%,100%{background:#ffffff1f;border-color:#ffffff33}}
.ofc-qc__gates i.is-on{background:var(--f-gold)!important;border-color:var(--f-gold)!important}
.ofc-qc__tok{position:absolute;top:50%;left:0;width:14px;height:14px;margin-top:-7px;border-radius:50%;background:#fff;box-shadow:0 0 12px #6EE0CE}
.ofc-qc.is-in .ofc-qc__tok{animation:ofcTok 8s linear infinite}
@keyframes ofcTok{to{left:calc(100% - 14px)}}
.ofc-qc__list{list-style:none;margin:0;padding:0;display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:10px}
.ofc-qc__list li{position:relative;display:flex;flex-direction:column;gap:6px;padding:18px;border-radius:18px;background:#ffffff0d;border:1px solid #ffffff1f;outline:none;opacity:0;transform:translateY(10px);transition:opacity .45s,transform .45s,background .25s,border-color .25s;transition-delay:calc(var(--i)*80ms),calc(var(--i)*80ms),0s,0s}
.ofc-qc.is-in .ofc-qc__list li{opacity:1;transform:none}
.ofc-qc__list li.is-on,.ofc-qc__list li:focus-visible{background:#ffffff17;border-color:var(--f-gold)}
.ofc-qc__n{font:800 .74rem var(--display);color:var(--f-teal2)}
.ofc-qc__ic{width:40px;height:40px;border-radius:12px;display:grid;place-items:center;background:#ffffff14;color:#fff}
.ofc-qc__list strong{font:700 1rem var(--display)}
.ofc-qc__list em{font-style:normal;font-size:.84rem;color:#C9D3F5}
.ofc-qc__ok{position:absolute;right:14px;top:14px;width:22px;height:22px;border-radius:50%;display:grid;place-items:center;background:var(--f-teal);color:#fff}

/* technology */
.ofc-tech{display:grid;grid-template-columns:1fr auto 1fr auto 1fr auto 1fr;align-items:center;gap:8px;padding:clamp(18px,3vw,28px);border-radius:24px;background:linear-gradient(160deg,#EEF2FB,#E3F5F2);border:1px solid var(--f-line);margin-bottom:16px}
.ofc-tech__node{display:flex;flex-direction:column;align-items:center;gap:6px;text-align:center;opacity:0;transform:translateY(10px);transition:all .45s}
.ofc-tech.is-in .ofc-tech__node{opacity:1;transform:none}
.ofc-tech__node:nth-child(3){transition-delay:.15s}.ofc-tech__node:nth-child(5){transition-delay:.3s}.ofc-tech__node:nth-child(7){transition-delay:.45s}
.ofc-tech__node>span{width:70px;height:70px;border-radius:20px;display:grid;place-items:center;background:#fff;color:var(--f-royal);box-shadow:0 14px 26px -18px var(--f-ink),0 0 0 1px var(--f-line)}
.ofc-tech__node--c>span{background:var(--f-royal);color:#fff}
.ofc-tech__node--o>span{background:var(--f-teal);color:#fff}
.ofc-tech__node strong{font:700 .95rem var(--display);color:var(--f-ink)}
.ofc-tech__node em{font-style:normal;font-size:.8rem;color:var(--f-muted)}
.ofc-tech__link{position:relative;width:clamp(40px,6vw,90px);height:2px;background:repeating-linear-gradient(90deg,var(--f-teal) 0 6px,transparent 6px 11px);animation:ofcLink 1s linear infinite}
@keyframes ofcLink{to{background-position:11px 0}}
.ofc-tech__link b{position:absolute;left:50%;top:-22px;transform:translateX(-50%);font:700 .66rem var(--body);letter-spacing:.08em;text-transform:uppercase;color:var(--f-teal)}
.ofc-tech__link i{position:absolute;top:-3px;left:0;width:8px;height:8px;border-radius:50%;background:var(--f-royal);animation:ofcTrav 1.8s linear infinite}
@keyframes ofcTrav{to{left:calc(100% - 8px)}}
.ofc-tcards{list-style:none;margin:0;padding:0;display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:10px}
.ofc-tcards li{display:flex;flex-direction:column;gap:6px;padding:16px;border-radius:16px;background:#fff;border:1px solid var(--f-line)}
.ofc-tcards li>span{width:38px;height:38px;border-radius:11px;display:grid;place-items:center;background:#EEF2FB;color:var(--f-royal)}
.ofc-tcards strong{font:700 .95rem var(--display);color:var(--f-ink)}
.ofc-tcards em{font-style:normal;font-size:.84rem;color:var(--f-muted)}

/* people + tech + quality */
.ofc-ptq{display:grid;grid-template-columns:1fr auto 1fr auto 1fr auto .9fr;gap:10px;align-items:center}
.ofc-ptq__c{display:flex;flex-direction:column;gap:8px;padding:20px;border-radius:20px;background:#fff;border:1px solid var(--f-line);border-top:4px solid var(--c);height:100%}
.ofc-ptq__c0{--c:#1E5BFF}.ofc-ptq__c1{--c:#0B22A8}.ofc-ptq__c2{--c:#0E9C88}
.ofc-ptq__c>span{width:44px;height:44px;border-radius:12px;display:grid;place-items:center;background:color-mix(in srgb,var(--c) 12%,#fff);color:var(--c)}
.ofc-ptq__c strong{font:800 1.2rem var(--display);color:var(--f-ink);text-transform:uppercase;letter-spacing:.04em}
.ofc-ptq__c ul{list-style:none;margin:0;padding:0;display:flex;flex-wrap:wrap;gap:5px}
.ofc-ptq__c li{font-size:.82rem;font-weight:600;padding:4px 10px;border-radius:999px;background:var(--f-soft);color:var(--f-ink)}
.ofc-ptq__op{font:800 1.8rem var(--display);color:var(--f-teal)}
.ofc-ptq__res{display:flex;flex-direction:column;align-items:center;justify-content:center;gap:8px;text-align:center;aspect-ratio:1;border-radius:50%;background:radial-gradient(circle at 35% 30%,#1E5BFF,#07104F);color:var(--f-teal2);box-shadow:0 0 0 10px #0E9C881f,0 24px 40px -24px var(--f-ink)}
.ofc-ptq__res strong{color:#fff;font:800 1.05rem/1.2 var(--display);padding:0 10px}

/* industries + research types + applications */
.ofc-ind{list-style:none;margin:0;padding:0;display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:10px}
.ofc-ind li{display:flex;align-items:center;gap:12px;padding:16px;border-radius:16px;background:#fff;border:1px solid var(--f-line);font:700 .95rem/1.25 var(--display);color:var(--f-ink);transition:transform .2s,border-color .2s}
.ofc-ind li:hover{transform:translateY(-3px);border-color:var(--f-royal)}
.ofc-ind li>span{width:44px;height:44px;border-radius:12px;display:grid;place-items:center;background:#EEF2FB;color:var(--f-royal);flex:none;transition:all .2s}
.ofc-ind li:hover>span{background:var(--f-royal);color:#fff}
.ofc-rt{margin-top:clamp(40px,5vw,60px);padding:clamp(18px,3vw,30px);border-radius:24px;background:var(--f-ink);color:#fff}
.ofc-rt__h{display:flex;justify-content:space-between;align-items:baseline;gap:16px;flex-wrap:wrap;margin-bottom:16px}
.ofc-rt__h h3{color:#fff;margin:0;font-size:1.35rem}
.ofc-rt__h p{margin:0;color:#C9D3F5;font-size:.92rem}
.ofc-rt ul{list-style:none;margin:0;padding:0;display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:8px}
.ofc-rt li{display:flex;flex-direction:column;gap:6px;padding:12px 14px;border-radius:12px;background:#ffffff0d;border:1px solid #ffffff1a;transition:background .2s}
.ofc-rt li:hover{background:#ffffff17}
.ofc-rt strong{font:700 .92rem var(--display)}
.ofc-rt li span{display:inline-flex;align-items:center;gap:5px;font:700 .66rem var(--body);letter-spacing:.06em;text-transform:uppercase;color:var(--f-teal2)}
.ofc-apps{margin-top:14px;display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:10px}
.ofc-apps__c{display:flex;flex-direction:column;gap:6px;padding:18px;border-radius:16px;background:#fff;border:1px solid var(--f-line)}
.ofc-apps__c>.rc-ico{color:var(--f-teal)}
.ofc-apps__c strong{font:700 1rem var(--display);color:var(--f-ink)}
.ofc-apps__c span{font-size:.86rem;color:var(--f-muted)}

/* why us */
.ofc-wy{list-style:none;margin:0;padding:0;display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:10px}
.ofc-wy li{position:relative;display:flex;flex-direction:column;gap:8px;padding:20px;border-radius:18px;background:#fff;border:1px solid var(--f-line);overflow:hidden}
.ofc-wy li:after{content:"";position:absolute;left:0;right:0;bottom:0;height:3px;background:linear-gradient(90deg,var(--f-royal),var(--f-teal));transform:scaleX(0);transform-origin:left;transition:transform .35s}
.ofc-wy li:hover:after{transform:scaleX(1)}
.ofc-wy__n{position:absolute;right:16px;top:14px;font:800 .78rem var(--display);color:#B9C2D3}
.ofc-wy__ic{width:42px;height:42px;border-radius:12px;display:grid;place-items:center;background:var(--f-ink);color:var(--f-teal2)}
.ofc-wy strong{font:700 1rem var(--display);color:var(--f-ink)}
.ofc-wy em{font-style:normal;font-size:.86rem;color:var(--f-muted)}

/* scenario + team */
.ofc-sc{display:grid;grid-template-columns:minmax(0,1.2fr) minmax(0,.8fr);gap:16px;align-items:stretch}
.ofc-sc>*{min-width:0}
.ofc-sc h2{font-size:clamp(1.4rem,2.4vw,1.8rem);margin:8px 0 6px;color:var(--f-ink)}
.ofc-sc__ex{padding:clamp(20px,3vw,32px);border-radius:24px;background:var(--f-soft);border:1px dashed #B9C3E0}
.ofc-sc__tag{display:inline-block;font:700 .66rem var(--body);letter-spacing:.1em;text-transform:uppercase;color:#8A6A1E;background:#FBF3DD;border-radius:999px;padding:4px 10px}
.ofc-sc__ex ol{list-style:none;margin:18px 0;padding:0;display:grid;grid-template-columns:repeat(6,minmax(0,1fr));gap:6px}
.ofc-sc__ex li{position:relative;display:flex;flex-direction:column;gap:6px;padding:12px 10px;border-radius:12px;background:#fff;border:1px solid var(--f-line);font:700 .84rem/1.25 var(--display);color:var(--f-ink)}
.ofc-sc__ex li span{font-size:.7rem;color:var(--f-teal)}
.ofc-sc__ex li:last-child{background:var(--f-teal);border-color:var(--f-teal);color:#fff}
.ofc-sc__ex li:last-child span{color:#DDF5F0}
.ofc-team{padding:clamp(20px,3vw,32px);border-radius:24px;background:var(--f-ink);color:#fff}
.ofc-team h2{color:#fff}
.ofc-team ul{list-style:none;margin:14px 0 16px;padding:0;display:grid;gap:8px}
.ofc-team li{display:flex;align-items:center;gap:10px;padding:10px 12px;border-radius:12px;background:#ffffff0d;border:1px solid #ffffff1a;font:700 .92rem var(--display)}
.ofc-team li span{width:34px;height:34px;border-radius:10px;display:grid;place-items:center;background:#6EE0CE22;color:var(--f-teal2)}
.ofc-team .rc-link{color:var(--f-teal2)}

/* related methods */
.ofc-rel{list-style:none;margin:0;padding:0;display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:10px}
.ofc-rel a,.ofc-rel__x{display:flex;align-items:center;gap:10px;padding:16px;border-radius:14px;background:#fff;border:1px solid var(--f-line);text-decoration:none;color:var(--f-ink);height:100%}
.ofc-rel a .rc-ico:first-child,.ofc-rel__x .rc-ico{color:var(--f-teal)}
.ofc-rel strong{font:700 .95rem var(--display);flex:1}
.ofc-rel a .rc-ico:last-child{color:#B9C2D3;transition:transform .2s,color .2s}
.ofc-rel a:hover .rc-ico:last-child{color:var(--f-royal);transform:translateX(3px)}
.ofc-rel__x{border-style:dashed;color:var(--f-muted)}

/* cta */
.ofc-cta{position:relative;overflow:hidden;text-align:center;color:#fff;padding:clamp(56px,7vw,96px) 0;background:radial-gradient(700px 400px at 100% 0%,#0E9C8855 0%,transparent 60%),linear-gradient(160deg,#0B22A8,#07104F)}
.ofc-cta__bg{position:absolute;inset:0;width:100%;height:100%;opacity:.18}
.ofc-cta__bg circle{fill:#A9C1FF}
.ofc-cta__in{position:relative;max-width:780px}
.ofc-cta .rc-kicker{color:var(--f-teal2)}
.ofc-cta h2{color:#fff;font-size:clamp(1.9rem,4vw,3rem);margin:.3em 0 .4em}
.ofc-cta p{color:#D6DEFA;font-size:1.06rem;margin:0 auto 26px;max-width:60ch}
.ofc-cta .od-hero__ctas{justify-content:center}

/* responsive */
@media (max-width:1100px){
  .ofc-strip{grid-template-columns:repeat(3,minmax(0,1fr))}
  .ofc-proc__rail{grid-template-columns:repeat(4,minmax(0,1fr));row-gap:18px}.ofc-proc__rail:before{display:none}
  .ofc-qc__list,.ofc-tcards,.ofc-wy,.ofc-rt ul,.ofc-rel{grid-template-columns:repeat(2,minmax(0,1fr))}
  .ofc-ptq{grid-template-columns:1fr auto 1fr auto 1fr}.ofc-ptq__res{grid-column:1/-1;aspect-ratio:auto;border-radius:20px;padding:20px;flex-direction:row}.ofc-ptq>.ofc-ptq__op:nth-last-child(2){grid-column:1/-1;justify-self:center}
  .ofc-sc__ex ol{grid-template-columns:repeat(3,minmax(0,1fr))}
  .ofc-tech{grid-template-columns:1fr auto 1fr;row-gap:24px}.ofc-tech__link:nth-child(4){display:none}
}
@media (max-width:900px){
  .ofc-hero__in,.ofc-why2,.ofc-htr,.ofc-geo,.ofc-sc,.ofc-mth{grid-template-columns:1fr}
  .ofc-art{max-width:560px;width:100%;margin:0 auto}
  .ofc-mth__panel{display:none}
  .ofc-mth__mob{display:block;padding:14px 16px 6px;animation:rcPanel .3s ease}
  .ofc-mth__mob p{margin:0 0 10px;color:var(--f-muted);font-size:.92rem}
  .ofc-mth__mob ul{list-style:none;margin:0;padding:0;display:grid;gap:6px}
  .ofc-mth__mob li{display:flex;align-items:center;gap:7px;font-size:.88rem;font-weight:600;color:var(--f-ink)}
  .ofc-aud__cols{grid-template-columns:1fr}.ofc-aud__net{display:none}.ofc-aud__hub{position:static;transform:none;margin-bottom:12px}
  .ofc-htr ul{grid-template-columns:1fr 1fr}
  .ofc-proc__panel{grid-template-columns:1fr;gap:10px}
  .ofc-ind,.ofc-apps{grid-template-columns:repeat(2,minmax(0,1fr))}
  .ofc-qc__pipe{grid-template-columns:1fr}.ofc-qc__in,.ofc-qc__out{justify-self:center}
}
@media (max-width:640px){
  .ofc-chip{font-size:.66rem;padding:5px 8px}
  .ofc-chip--int{display:none}
  .ofc-strip{grid-template-columns:1fr 1fr}
  .ofc-vs{grid-template-columns:1fr}.ofc-vs__x{justify-self:center}
  .ofc-ben,.ofc-htr ul,.ofc-qc__list,.ofc-tcards,.ofc-wy,.ofc-rel,.ofc-ind,.ofc-apps{grid-template-columns:1fr}
  .ofc-rt ul{grid-template-columns:1fr 1fr}.ofc-rt li{padding:10px}.ofc-rt strong{font-size:.84rem}
  .ofc-proc__rail{grid-template-columns:1fr 1fr}
  .ofc-proc__dot{width:52px;height:52px}
  .ofc-ptq{grid-template-columns:1fr}.ofc-ptq__op{justify-self:center}
  .ofc-sc__ex ol{grid-template-columns:1fr 1fr}
  .ofc-tech{grid-template-columns:1fr}.ofc-tech__link{width:2px;height:28px;justify-self:center;background:repeating-linear-gradient(180deg,var(--f-teal) 0 6px,transparent 6px 11px)}.ofc-tech__link:nth-child(4){display:block}.ofc-tech__link b{top:50%;left:12px;transform:translateY(-50%)}.ofc-tech__link i{display:none}
  .ofc-hero .od-hero__ctas .btn,.ofc-mid .btn,.ofc-cta .od-hero__ctas .btn{width:100%}
  .ofc-geo__lg em{margin-left:0}
}
@media (prefers-reduced-motion:reduce){
  .ofc *,.ofc *:before,.ofc *:after{animation:none!important;transition:none!important}
  .ofc-proc__rail li,.ofc-qc__list li,.ofc-tech__node{opacity:1!important;transform:none!important}
  .ofc-proc__rail:before{transform:none!important}
  .ofc-qc__tok{left:calc(100% - 14px)}
}

/* ===== Quantitative Research (qnt-) — site palette, editorial light hero ===== */
.qnt{--od-navy:#07104F;--od-blue:#1E5BFF;--od-royal:#0B22A8;--od-sky:#E8EEFF;--od-teal:#0E9C88;--od-teal-soft:#E3F5F2;--od-line:#DDE2EC;--od-muted:#525C78;--od-paper:#F5F7FB;
  --r-navy:#07104F;--r-char:#0F1D72;--r-blue:#0B22A8;--r-soft:#EEF2FB;--r-teal:#0E9C88;--r-gold:#C99A2E;--r-line:#DDE2EC;--r-muted:#525C78;
  --q-ink:#07104F;--q-royal:#0B22A8;--q-bright:#1E5BFF;--q-teal:#0E9C88;--q-teal2:#6EE0CE;--q-gold:#C99A2E;--q-coral:#C2603F;--q-line:#DDE2EC;--q-muted:#525C78;--q-soft:#F3F6FB}
.qnt .rc-kicker{color:var(--q-royal)}
.qnt .rc-head--light .rc-kicker{color:var(--q-teal2)}
.qnt-sec--soft{background:var(--q-soft)}
.qnt-sec--ink{background:radial-gradient(760px 380px at 15% 0%,#1E3BB8 0%,transparent 60%),radial-gradient(520px 320px at 100% 100%,#0E9C8833 0%,transparent 70%),linear-gradient(165deg,#0A1660,#07104F);color:#fff}
.qnt-h3{font-size:1.25rem;margin:0 0 6px;color:var(--q-ink)}
.qnt-quote{font:600 clamp(1.08rem,1.6vw,1.28rem)/1.5 var(--display);color:var(--q-ink);border-left:3px solid var(--q-coral);padding-left:18px;margin:0 0 16px}
.qnt-quote--sm{font-size:1.02rem;border-color:var(--q-royal)}
.qnt .od-muted a,.qnt .rdc-note a{color:var(--q-royal);font-weight:600}

/* hero: editorial light with grid paper */
.qnt-hero{position:relative;overflow:hidden;padding:clamp(32px,4vw,56px) 0 clamp(28px,3vw,40px);border-bottom:1px solid var(--q-line);background:linear-gradient(#0B22A80a 1px,transparent 1px) 0 0/28px 28px,linear-gradient(90deg,#0B22A80a 1px,transparent 1px) 0 0/28px 28px,radial-gradient(700px 480px at 85% 40%,#E3EAFF 0%,transparent 65%),#fff}
.qnt-hero__in{display:grid;grid-template-columns:minmax(0,.95fr) minmax(0,1.05fr);gap:clamp(24px,4vw,56px);align-items:center}
.qnt-hero__in>*{min-width:0}
.qnt-eyebrow{display:inline-flex;align-items:center;gap:8px;font:700 .76rem var(--body);letter-spacing:.14em;text-transform:uppercase;color:var(--q-teal);margin-bottom:16px}
.qnt-hero h1{font-size:clamp(2.6rem,5.4vw,4.4rem);line-height:1.02;color:var(--q-ink);margin-bottom:.15em;letter-spacing:-.02em}
.qnt-hero__sub{font:700 clamp(1.2rem,2.2vw,1.7rem)/1.3 var(--display);color:var(--q-royal);margin:0 0 16px;display:inline-block;background:linear-gradient(transparent 68%,#6EE0CE66 68%)}
.qnt-hero__body{color:var(--q-muted);font-size:1.04rem;max-width:58ch;margin:0 0 24px}
.qnt .qnt-btn{background:var(--q-ink);color:#fff}
.qnt .qnt-btn:hover{background:var(--q-royal)}
.qnt-hv{position:relative;padding:18px;border-radius:26px;background:linear-gradient(160deg,#0B22A8,#07104F);box-shadow:0 40px 70px -44px #07104F;color:#fff}
.qnt-hv__panels{display:grid;grid-template-columns:1.25fr 1fr;grid-template-rows:auto auto auto;gap:10px}
.qnt-hv__p{padding:12px 14px;border-radius:14px;background:#ffffff0d;border:1px solid #ffffff1c;opacity:.45;transition:opacity .45s,border-color .45s,background .45s}
.qnt-hv__p.is-on{opacity:1;border-color:#6EE0CE66;background:#ffffff14}
.qnt-hv__k{display:block;font:700 .62rem var(--body);letter-spacing:.12em;text-transform:uppercase;color:#A9B8E8;margin-bottom:6px}
.qnt-hv__q{grid-column:1/-1}
.qnt-hv__q strong{display:block;font:700 .98rem/1.35 var(--display);margin-bottom:10px}
.qnt-hv__scale{display:grid;grid-template-columns:repeat(5,1fr);gap:6px}
.qnt-hv__scale i{font-style:normal;text-align:center;padding:6px 0;border-radius:8px;border:1px solid #ffffff30;font:700 .8rem var(--body);color:#C9D3F5}
.qnt-hv__q.is-on .qnt-hv__scale i.is-sel{background:var(--q-teal2);border-color:var(--q-teal2);color:var(--q-ink)}
.qnt-hv__dots{display:grid;grid-template-columns:repeat(12,1fr);gap:5px}
.qnt-hv__dots i{aspect-ratio:1;border-radius:50%;background:#A9C1FF;opacity:.35;transition:opacity .3s;transition-delay:calc(var(--i)*14ms)}
.qnt-hv__dots i.b{background:#6EE0CE}.qnt-hv__dots i.h{background:#F0D98F}
.qnt-hv__r.is-on .qnt-hv__dots i{opacity:1}
.qnt-hv__grid{display:grid;grid-template-columns:repeat(6,1fr);gap:3px}
.qnt-hv__grid i{height:9px;border-radius:2px;background:#ffffff26;transition:background .3s;transition-delay:calc(var(--i)*18ms)}
.qnt-hv__d.is-on .qnt-hv__grid i{background:#6E8BFF}
.qnt-hv__a svg{width:100%;height:64px;display:block}
.qnt-hv__bar{fill:#6E8BFF;opacity:.5;transform-box:fill-box;transform-origin:bottom;transform:scaleY(.25);transition:transform .6s,opacity .6s;transition-delay:calc(var(--i)*60ms)}
.qnt-hv__a.is-on .qnt-hv__bar{transform:none;opacity:1}
.qnt-hv__curve{fill:none;stroke:#6EE0CE;stroke-width:2;stroke-dasharray:3 3}
.qnt-hv__x{display:flex;flex-direction:column;align-items:center;justify-content:center;gap:4px;text-align:center}
.qnt-hv__x .rc-ico{color:var(--q-teal2)}
.qnt-hv__x strong{font:800 1.05rem var(--display)}
.qnt-hv__x span{font-size:.72rem;color:#C9D3F5}
.qnt-hv__x.is-on{background:#6EE0CE22}
.qnt-hv__chain{list-style:none;margin:12px 0 0;padding:0;display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:4px}
.qnt-hv__chain li{position:relative;display:flex;flex-direction:column;align-items:center;gap:4px;font:700 .68rem var(--body);color:#A9B8E8;text-align:center}
.qnt-hv__chain li:not(:last-child):after{content:"";position:absolute;top:13px;left:calc(50% + 16px);right:calc(-50% + 16px);height:2px;background:#ffffff26}
.qnt-hv__chain li.is-done:not(:last-child):after{background:var(--q-teal2)}
.qnt-hv__chain span{width:28px;height:28px;border-radius:50%;display:grid;place-items:center;background:#ffffff14;border:1px solid #ffffff30;color:#E1E8FF;transition:all .3s}
.qnt-hv__chain .is-done{color:#fff}
.qnt-hv__chain .is-done span{border-color:var(--q-teal2)}
.qnt-hv__chain .is-cur span{background:var(--q-teal2);color:var(--q-ink)}
.qnt-hv__tag{position:absolute;right:14px;top:-11px;font:600 .62rem var(--body);letter-spacing:.08em;text-transform:uppercase;color:var(--q-muted);background:#fff;border:1px dashed #B9C3E0;border-radius:999px;padding:3px 9px}
.qnt-strip{list-style:none;margin:clamp(24px,3vw,36px) 0 0;padding:14px 0 0;display:flex;flex-wrap:wrap;gap:6px 28px;border-top:1px solid var(--q-line)}
.qnt-strip li{display:flex;align-items:baseline;gap:8px;font:700 .95rem var(--display);color:var(--q-ink)}
.qnt-strip span{font:800 .7rem var(--display);color:var(--q-teal)}

/* problem → solution */
.qnt-psw{display:grid;grid-template-columns:minmax(0,.85fr) minmax(0,1.15fr);gap:clamp(28px,5vw,64px);align-items:center}
.qnt-psw>*{min-width:0}
.qnt-ps{display:grid;gap:0}
.qnt-ps__row{padding:18px;border-radius:18px}
.qnt-ps__row--bad{background:#FBF4F1;border:1px dashed #E4B7A7}
.qnt-ps__row--good{background:var(--q-ink);color:#fff}
.qnt-ps__k{display:flex;align-items:center;gap:7px;font:700 .74rem var(--body);letter-spacing:.12em;text-transform:uppercase;margin-bottom:12px}
.qnt-ps__row--bad .qnt-ps__k{color:var(--q-coral)}
.qnt-ps__row--good .qnt-ps__k{color:var(--q-teal2)}
.qnt-ps ol{list-style:none;margin:0;padding:0;display:flex;flex-wrap:wrap;gap:8px 18px}
.qnt-ps li{position:relative;padding:7px 12px;border-radius:9px;font:600 .88rem var(--body);opacity:0;transform:translateY(6px);transition:opacity .4s,transform .4s;transition-delay:calc(var(--i)*80ms)}
.qnt-ps__row--good li{transition-delay:calc(.45s + var(--i)*80ms);background:#ffffff14;font-family:var(--display);font-weight:700}
.qnt-ps__row--bad li{background:#fff;border:1px solid #EBD0C6;color:#6B4A40}
.qnt-ps li:not(:last-child):after{content:"→";position:absolute;right:-15px;top:50%;transform:translateY(-50%);font-size:.8rem}
.qnt-ps__row--bad li:not(:last-child):after{color:#D19A87}
.qnt-ps__row--good li:not(:last-child):after{color:var(--q-teal2)}
.qnt-ps__row--bad li:last-child{background:var(--q-coral);color:#fff;border-color:var(--q-coral)}
.qnt-ps__row--good li:last-child{background:var(--q-teal2);color:var(--q-ink)}
.qnt-ps.is-in li{opacity:1;transform:none}
.qnt-ps__bridge{position:relative;height:46px;display:grid;place-items:center}
.qnt-ps__bridge:before{content:"";position:absolute;left:50%;top:0;bottom:0;width:2px;background:linear-gradient(var(--q-coral),var(--q-teal))}
.qnt-ps__bridge span{position:relative;padding:4px 12px;border-radius:999px;background:#fff;border:1px solid var(--q-line);font:700 .7rem var(--body);letter-spacing:.1em;text-transform:uppercase;color:var(--q-royal)}

/* sample to insight */
.qnt-s2i{list-style:none;margin:10px 0 0;padding:0;display:grid;grid-template-columns:repeat(7,minmax(0,1fr));gap:8px;position:relative;min-height:400px;align-items:start}
.qnt-s2i:before{content:"";position:absolute;left:3%;right:3%;top:196px;height:2px;background:linear-gradient(90deg,#6E8BFF,var(--q-teal2));transform:scaleX(0);transform-origin:left;transition:transform 1.4s ease}
.qnt-s2i.is-in:before{transform:scaleX(1)}
.qnt-s2i li{position:relative;display:grid;grid-template-rows:auto auto auto auto;justify-items:center;text-align:center;gap:6px;padding-top:0;opacity:0;transform:translateY(12px);transition:opacity .5s,transform .5s;transition-delay:calc(var(--i)*120ms)}
.qnt-s2i.is-in li{opacity:1;transform:none}
.qnt-s2i li.is-dn{padding-top:222px}
.qnt-s2i li:not(.is-dn){padding-top:0}
.qnt-s2i li:after{content:"";position:absolute;left:50%;width:2px;background:#ffffff30}
.qnt-s2i li:not(.is-dn):after{top:178px;height:18px}
.qnt-s2i li.is-dn:after{top:196px;height:22px}
.qnt-s2i__n{font:800 clamp(1.6rem,2.6vw,2.2rem)/1 var(--display);color:transparent;-webkit-text-stroke:1.5px var(--q-teal2)}
.qnt-s2i__ic{width:50px;height:50px;border-radius:15px;display:grid;place-items:center;background:#ffffff14;border:1px solid #ffffff2a;color:#fff}
.qnt-s2i li:last-child .qnt-s2i__ic{background:var(--q-teal2);color:var(--q-ink)}
.qnt-s2i strong{font:700 1.05rem var(--display)}
.qnt-s2i em{font-style:normal;font-size:.82rem;color:#C9D3F5;line-height:1.4;max-width:18ch}

/* approach */
.qnt-ap__tabs{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:8px;margin-bottom:12px}
.qnt-ap__tabs button{display:flex;align-items:center;gap:10px;padding:14px 16px;border-radius:14px;border:1px solid var(--q-line);background:#fff;font:700 .95rem var(--display);color:var(--q-ink);cursor:pointer;text-align:left;transition:all .2s}
.qnt-ap__tabs button span{font-size:.72rem;color:var(--q-teal)}
.qnt-ap__tabs button .rc-ico{color:var(--q-royal);flex:none}
.qnt-ap__tabs button:hover{border-color:var(--q-bright)}
.qnt-ap__tabs button.is-on{background:var(--q-ink);border-color:var(--q-ink);color:#fff}
.qnt-ap__tabs button.is-on .rc-ico,.qnt-ap__tabs button.is-on span{color:var(--q-teal2)}
.qnt-ap__tabs button:focus-visible{outline:2px solid var(--q-teal);outline-offset:2px}
.qnt-ap__panel{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:24px;align-items:center;padding:clamp(20px,3vw,32px);border-radius:24px;background:var(--q-soft);border:1px solid var(--q-line);animation:rcPanel .35s ease}
.qnt-ap__panel>*{min-width:0}
.qnt-ap__kk{font:700 .72rem var(--body);letter-spacing:.12em;text-transform:uppercase;color:var(--q-teal)}
.qnt-ap__copy h3{font-size:1.45rem;margin:6px 0 8px;color:var(--q-ink)}
.qnt-ap__copy>p{margin:0 0 14px;color:var(--q-muted)}
.qnt-ap__copy ul{list-style:none;margin:0;padding:0;display:grid;grid-template-columns:1fr 1fr;gap:6px}
.qnt-ap__copy li{display:flex;align-items:center;gap:7px;padding:8px 10px;border-radius:10px;background:#fff;font-weight:600;font-size:.86rem;color:var(--q-ink);animation:rcPanel .4s ease both;animation-delay:calc(var(--i)*45ms)}
.qnt-ap__copy li .rc-ico{color:var(--q-teal);flex:none}
.qnt-brief{display:grid;grid-template-columns:1fr 1fr;gap:8px;padding:16px;border-radius:18px;background:#fff;border:1px solid var(--q-line)}
.qnt-brief span{padding:12px;border-radius:10px;border:1px dashed #B9C3E0;font:700 .9rem var(--display);color:var(--q-ink);text-align:center;animation:rcPanel .4s ease both;animation-delay:calc(var(--i)*70ms)}
.qnt-brief span.is-root{grid-column:1/-1;background:var(--q-ink);border:0;color:#fff}
.qnt-logic{padding:18px;border-radius:18px;background:var(--q-ink);color:#fff}
.qnt-logic ol{list-style:none;margin:0 0 12px;padding:0;display:grid;grid-template-columns:repeat(6,minmax(0,1fr));gap:6px;position:relative}
.qnt-logic ol:before{content:"";position:absolute;left:8%;right:8%;top:19px;height:2px;background:repeating-linear-gradient(90deg,var(--q-teal2) 0 6px,transparent 6px 11px);animation:qntFlow 1.2s linear infinite}
@keyframes qntFlow{to{background-position:11px 0}}
.qnt-logic li{position:relative;display:flex;flex-direction:column;align-items:center;gap:6px;font:700 .74rem var(--body);color:#E1E8FF;text-align:center;animation:rcPanel .4s ease both;animation-delay:calc(var(--i)*80ms)}
.qnt-logic li span{width:40px;height:40px;border-radius:50%;display:grid;place-items:center;background:#0B22A8;border:2px solid var(--q-teal2);color:#fff}
.qnt-logic li:last-child span{background:var(--q-teal2);color:var(--q-ink)}
.qnt-logic__term,.qnt-logic__skip{display:flex;align-items:center;gap:7px;padding:8px 10px;border-radius:9px;font-size:.8rem;margin-top:6px}
.qnt-logic__term{background:#C2603F33;color:#F6C3B2}
.qnt-logic__skip{background:#ffffff12;color:#C9D3F5}
.qnt-tree{padding:16px;border-radius:18px;background:#fff;border:1px solid var(--q-line)}
.qnt-tree__root{display:flex;align-items:center;justify-content:center;gap:8px;margin:0 auto;width:max-content;max-width:100%;padding:10px 16px;border-radius:999px;background:var(--q-ink);color:#fff;font:700 .92rem var(--display)}
.qnt-tree__lines{display:block;width:100%;height:40px}
.qnt-tree__lines path{fill:none;stroke:#C9D3F5;stroke-width:2;vector-effect:non-scaling-stroke;transition:stroke .25s}
.qnt-tree__lines path.is-on{stroke:var(--q-teal)}
.qnt-tree__br{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:8px}
.qnt-tree__b{padding:10px;border-radius:12px;border:1px solid var(--q-line);border-top:3px solid var(--c);transition:transform .2s,box-shadow .2s}
.qnt-tree__b0{--c:#1E5BFF}.qnt-tree__b1{--c:#0B22A8}.qnt-tree__b2{--c:#0E9C88}
.qnt-tree__b.is-on{transform:translateY(-3px);box-shadow:0 14px 24px -18px var(--c)}
.qnt-tree__k{display:flex;align-items:center;gap:6px;font:800 .95rem var(--display);color:var(--c);margin-bottom:6px}
.qnt-tree__b ul{list-style:none;margin:0;padding:0;display:grid;gap:4px}
.qnt-tree__b li{font-size:.78rem;font-weight:600;color:var(--q-ink);padding:4px 7px;border-radius:6px;background:var(--q-soft)}
.qnt-tree__note{margin:10px 0 0;font-size:.76rem;color:var(--q-muted)}

/* methods */
.qnt-mt__cards{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:10px}
.qnt-mt__c{display:flex;flex-direction:column;gap:6px;padding:20px;border-radius:18px;background:#fff;border:1px solid var(--q-line);outline:none;transition:all .25s}
.qnt-mt__c.is-on,.qnt-mt__c:focus-visible{border-color:var(--q-royal);box-shadow:0 22px 36px -28px var(--q-royal);transform:translateY(-3px)}
.qnt-mt__ic{width:48px;height:48px;border-radius:14px;display:grid;place-items:center;background:#EEF2FB;color:var(--q-royal);transition:all .25s}
.qnt-mt__c.is-on .qnt-mt__ic{background:var(--q-royal);color:#fff}
.qnt-mt__c strong{font:800 1.4rem var(--display);color:var(--q-ink);margin-top:6px}
.qnt-mt__t{font:700 .8rem var(--body);color:var(--q-teal)}
.qnt-mt__c p{margin:0;font-size:.88rem;color:var(--q-muted);flex:1}
.qnt-mt__c .rc-link{font-size:.84rem}
.qnt-mt__sel{display:flex;flex-wrap:wrap;align-items:center;gap:6px 8px;margin:18px 0;padding:14px 18px;border-radius:16px;background:var(--q-ink);color:#fff}
.qnt-mt__selk{font:700 .7rem var(--body);letter-spacing:.12em;text-transform:uppercase;color:var(--q-teal2);margin-right:6px}
.qnt-mt__sel>span:not(.qnt-mt__selk){padding:6px 12px;border-radius:999px;background:#ffffff14;font:700 .86rem var(--display)}
.qnt-mt__sel b{color:var(--q-teal2)}
.qnt-mt__tbl{overflow-x:auto;border-radius:18px;border:1px solid var(--q-line);background:#fff}
.qnt-mt__tbl table{width:100%;border-collapse:collapse;min-width:520px}
.qnt-mt__tbl th,.qnt-mt__tbl td{padding:13px 18px;text-align:left;border-top:1px solid var(--q-line);font-size:.94rem}
.qnt-mt__tbl thead th{border-top:0;background:var(--q-soft);font:700 .72rem var(--body);letter-spacing:.12em;text-transform:uppercase;color:var(--q-muted)}
.qnt-mt__tbl tbody th{display:flex;align-items:center;gap:8px;font:700 1rem var(--display);color:var(--q-ink)}
.qnt-mt__tbl tbody th .rc-ico{color:var(--q-royal)}
.qnt-mt__tbl td{color:var(--q-muted)}
.qnt-mt__tbl tr.is-on{background:#EEF2FB}

/* quality funnel */
.qnt-qc{display:grid;grid-template-columns:minmax(0,.8fr) minmax(0,1.2fr);gap:clamp(24px,4vw,48px);align-items:center}
.qnt-qc__funnel{position:relative;display:flex;flex-direction:column;align-items:center;gap:6px;padding:20px;border-radius:24px;background:linear-gradient(165deg,#0B22A8,#07104F);overflow:hidden}
.qnt-qc__band{position:relative;width:var(--w);display:flex;justify-content:space-between;align-items:center;padding:14px 16px;border-radius:12px;background:#ffffff14;border:1px solid #ffffff22;color:#fff;font:700 .9rem var(--display);opacity:0;transform:scaleX(.9);transition:opacity .45s,transform .45s,background .25s,border-color .25s;transition-delay:calc(var(--i)*140ms),calc(var(--i)*140ms),0s,0s}
.qnt-qc.is-in .qnt-qc__band{opacity:1;transform:none}
.qnt-qc__band:last-of-type{background:var(--q-teal2);color:var(--q-ink);border-color:var(--q-teal2)}
.qnt-qc__band.is-on{border-color:var(--q-gold);background:#ffffff22}
.qnt-qc__flag{display:inline-flex;align-items:center;gap:4px;font:700 .62rem var(--body);font-style:normal;letter-spacing:.06em;text-transform:uppercase;color:#F6C3B2}
.qnt-qc__flow{position:absolute;inset:0;pointer-events:none}
.qnt-qc__flow i{position:absolute;top:-8px;left:var(--x);width:6px;height:6px;border-radius:50%;background:#A9C1FF;opacity:0;animation:qntDrop 5s linear infinite;animation-delay:calc(var(--i)*.5s)}
.qnt-qc__flow i.is-out{background:#F0A08A;animation-name:qntOut}
@keyframes qntDrop{0%{opacity:0;transform:translateY(0)}10%{opacity:.9}90%{opacity:.9}100%{opacity:0;transform:translateY(300px)}}
@keyframes qntOut{0%{opacity:0;transform:translate(0,0)}10%{opacity:.9}45%{opacity:.9;transform:translate(0,120px)}70%{opacity:0;transform:translate(60px,150px)}100%{opacity:0}}
.qnt-qc__stages{display:grid;grid-template-columns:1fr 1fr;gap:10px}
.qnt-qc__st{padding:16px;border-radius:16px;background:#fff;border:1px solid var(--q-line);transition:border-color .2s,box-shadow .2s}
.qnt-qc__st.is-on{border-color:var(--q-royal);box-shadow:0 18px 30px -26px var(--q-royal)}
.qnt-qc__st:last-child{background:var(--q-soft)}
.qnt-qc__h{display:flex;align-items:center;gap:8px;font:700 .98rem var(--display);color:var(--q-ink);margin-bottom:10px}
.qnt-qc__h span{width:30px;height:30px;border-radius:9px;display:grid;place-items:center;background:#EEF2FB;color:var(--q-royal)}
.qnt-qc__st ul{list-style:none;margin:0;padding:0;display:grid;gap:8px}
.qnt-qc__st li{display:flex;gap:8px;align-items:flex-start}
.qnt-qc__st li>.rc-ico{color:var(--q-teal);flex:none;margin-top:3px}
.qnt-qc__st strong{display:block;font:700 .88rem var(--display);color:var(--q-ink)}
.qnt-qc__st em{font-style:normal;font-size:.78rem;color:var(--q-muted)}

/* mid cta */
.qnt-mid{background:linear-gradient(100deg,#07104F,#0B22A8 60%,#0E9C88);color:#fff;padding:clamp(26px,4vw,40px) 0}
.qnt-mid__in{display:flex;align-items:center;justify-content:space-between;gap:24px;flex-wrap:wrap}
.qnt-mid strong{display:block;font:700 clamp(1.15rem,2vw,1.45rem) var(--display)}
.qnt-mid span{color:#DDE6FF;display:block}

/* processing transformation */
.qnt-tx{list-style:none;margin:0;padding:0;display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:12px;position:relative}
.qnt-tx li{position:relative;display:flex;flex-direction:column;align-items:center;gap:10px;text-align:center;opacity:0;transform:translateY(10px);transition:opacity .45s,transform .45s;transition-delay:calc(var(--i)*130ms)}
.qnt-tx.is-in li{opacity:1;transform:none}
.qnt-tx li:not(:last-child):after{content:"→";position:absolute;right:-12px;top:48px;color:var(--q-teal);font-weight:800}
.qnt-tx strong{font:700 .92rem var(--display);color:var(--q-ink)}
.qnt-tx__v{width:100%;height:110px;border-radius:14px;background:#fff;border:1px solid var(--q-line);padding:12px;display:flex;flex-direction:column;justify-content:center;gap:6px}
.qnt-tx__raw i{display:block;height:7px;border-radius:4px;background:#C9D3F5}
.qnt-tx__raw i.x{background:#F0B4A2}
.qnt-tx__clean{display:grid!important;grid-template-columns:repeat(5,1fr);gap:4px;align-content:center}
.qnt-tx__clean i{height:12px;border-radius:3px;background:#6E8BFF}
.qnt-tx__tab{display:grid!important;grid-template-columns:repeat(4,1fr);gap:4px;align-content:center}
.qnt-tx__tab b{height:10px;border-radius:2px;background:var(--q-ink)}
.qnt-tx__tab i{height:14px;border-radius:2px;background:rgba(11,34,168,var(--o))}
.qnt-tx__v svg{width:100%;height:100%}
.qnt-tx__ax{fill:none;stroke:#B9C3E0}
.qnt-tx__fit{stroke:var(--q-teal);stroke-width:2}
.qnt-tx__pt{fill:var(--q-royal)}
.qnt-tx__ins{background:var(--q-ink)!important;border-color:var(--q-ink)!important;align-items:flex-start}
.qnt-tx__ins span{color:var(--q-teal2)}
.qnt-tx__ins i{display:block;height:6px;border-radius:3px;background:#ffffff40;width:80%}
.qnt-tx__ins i:nth-of-type(2){width:60%}
.qnt-caps{list-style:none;margin:22px 0 0;padding:0;display:flex;flex-wrap:wrap;gap:6px}
.qnt-caps li{padding:7px 13px;border-radius:999px;background:#fff;border:1px solid var(--q-line);font:600 .86rem var(--body);color:var(--q-ink)}
.qnt-out{margin-top:clamp(40px,5vw,64px);display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:clamp(24px,4vw,56px);align-items:center}
.qnt-out>*{min-width:0}
.qnt-out h2{color:var(--q-ink);margin:.3em 0 .3em}
.qnt-out__list{list-style:none;margin:14px 0 0;padding:0;display:grid;grid-template-columns:1fr 1fr;gap:6px}
.qnt-out__list li{display:flex;align-items:center;gap:7px;font-weight:600;font-size:.9rem;color:var(--q-ink)}
.qnt-out__list .rc-ico{color:var(--q-teal)}
.qnt-stack{position:relative;height:320px}
.qnt-stack__s{position:absolute;width:58%;padding:14px 16px;border-radius:16px;background:#fff;border:1px solid var(--q-line);box-shadow:0 24px 40px -30px #07104F;display:grid;grid-template-columns:auto 1fr;align-items:center;gap:8px 10px;transition:transform .3s}
.qnt-stack__s span{grid-column:1/-1}
.qnt-stack__s .rc-ico{color:var(--q-royal)}
.qnt-stack__s strong{font:700 1rem var(--display);color:var(--q-ink)}
.qnt-stack__s span{display:grid;gap:4px}
.qnt-stack__s span i{display:block;height:6px;border-radius:3px;background:#DDE2EC}
.qnt-stack__s span i:nth-child(2){width:80%}.qnt-stack__s span i:nth-child(3){width:55%}
.qnt-stack__s0{left:0;top:0}
.qnt-stack__s1{left:10%;top:48px}
.qnt-stack__s2{left:20%;top:96px}
.qnt-stack__s3{left:30%;top:144px}
.qnt-stack__s4{left:40%;top:192px;background:var(--q-ink);border-color:var(--q-ink)}
.qnt-stack__s4 strong{color:#fff}.qnt-stack__s4 .rc-ico{color:var(--q-teal2)}.qnt-stack__s4 span i{background:#ffffff40}
.qnt-stack:hover .qnt-stack__s{transform:translateX(calc(var(--i)*10px))}

/* services ecosystem */
.qnt-eco{display:grid;grid-template-columns:minmax(0,1.1fr) minmax(0,.9fr);gap:clamp(24px,4vw,56px);align-items:center}
.qnt-eco>*{min-width:0}
.qnt-eco__map{position:relative;width:100%;max-width:480px;aspect-ratio:1;justify-self:center}
.qnt-eco__lines{position:absolute;inset:0;width:100%;height:100%}
.qnt-eco__lines circle{fill:none;stroke:#DDE2EC}
.qnt-eco__lines line{stroke:#C9D3F5;stroke-width:1.5;stroke-dasharray:4 5;transition:stroke .2s}
.qnt-eco__lines line.is-on{stroke:var(--q-teal);stroke-dasharray:none;stroke-width:2}
.qnt-eco__core{position:absolute;left:50%;top:50%;width:30%;aspect-ratio:1;transform:translate(-50%,-50%);border-radius:50%;background:radial-gradient(circle at 35% 30%,#1E5BFF,#07104F);color:var(--q-teal2);display:flex;flex-direction:column;align-items:center;justify-content:center;gap:4px;text-align:center;box-shadow:0 0 0 10px #0B22A814}
.qnt-eco__core strong{color:#fff;font:800 .92rem/1.2 var(--display);padding:0 10px}
.qnt-eco__n{position:absolute;width:0;height:0;padding:0;border:0;background:none;cursor:pointer;left:calc(50% + var(--r) * cos(var(--a)));top:calc(50% + var(--r) * sin(var(--a)))}
.qnt-eco__n>span{position:absolute;transform:translate(-50%,-50%);white-space:nowrap;padding:7px 12px;border-radius:999px;background:#fff;border:1.5px solid #C9D3F5;font:700 .82rem var(--display);color:var(--q-ink);transition:all .2s}
.qnt-eco__n.is-big>span{padding:10px 16px;font-size:.92rem;border-color:var(--q-royal)}
.qnt-eco__n.is-on>span,.qnt-eco__n:focus-visible>span{background:var(--q-ink);border-color:var(--q-ink);color:#fff}
.qnt-eco__n:focus-visible{outline:none}
.qnt-eco__panel{padding:clamp(20px,3vw,30px);border-radius:22px;background:var(--q-soft);border:1px solid var(--q-line);animation:rcPanel .35s ease}
.qnt-eco__k{font:700 .7rem var(--body);letter-spacing:.12em;text-transform:uppercase;color:var(--q-teal)}
.qnt-eco__panel h3{font-size:1.5rem;margin:6px 0 8px;color:var(--q-ink)}
.qnt-eco__panel p{color:var(--q-muted);margin:0 0 16px}
.qnt-eco__all{display:flex;flex-wrap:wrap;gap:6px}
.qnt-eco__all button{padding:6px 11px;border-radius:999px;border:1px solid var(--q-line);background:#fff;font:600 .8rem var(--body);color:var(--q-ink);cursor:pointer}
.qnt-eco__all button.is-on{background:var(--q-royal);border-color:var(--q-royal);color:#fff}

/* formats, tracking, global */
.qnt-fmt{list-style:none;margin:0 0 clamp(36px,5vw,56px);padding:0;display:grid;grid-template-columns:repeat(6,minmax(0,1fr));gap:8px}
.qnt-fmt a,.qnt-fmt span{display:flex;flex-direction:column;gap:8px;height:100%;padding:16px;border-radius:14px;background:#fff;border:1px solid var(--q-line);font:700 .92rem/1.25 var(--display);color:var(--q-ink);text-decoration:none;transition:border-color .2s,transform .2s}
.qnt-fmt .rc-ico:first-child{color:var(--q-royal)}
.qnt-fmt a .rc-ico:last-child{color:#B9C3E0;margin-top:auto}
.qnt-fmt a:hover{border-color:var(--q-royal);transform:translateY(-2px)}
.qnt-two{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:16px}
.qnt-two>div{padding:clamp(18px,2.6vw,26px);border-radius:22px;background:#fff;border:1px solid var(--q-line);min-width:0}
.qnt-waves{position:relative;display:grid;grid-template-columns:repeat(4,1fr);gap:8px;margin-top:20px;padding-top:6px}
.qnt-waves__line{position:absolute;left:6%;right:6%;top:14px;height:2px;background:linear-gradient(90deg,var(--q-royal),var(--q-teal));transform:scaleX(0);transform-origin:left;transition:transform 1.2s ease}
.qnt-waves.is-in .qnt-waves__line{transform:scaleX(1)}
.qnt-waves__w{position:relative;display:flex;flex-direction:column;align-items:center;gap:6px;opacity:0;transform:translateY(8px);transition:all .45s;transition-delay:calc(.2s + var(--i)*180ms)}
.qnt-waves.is-in .qnt-waves__w{opacity:1;transform:none}
.qnt-waves__dot{width:18px;height:18px;border-radius:50%;background:#fff;border:3px solid var(--q-royal)}
.qnt-waves__w:last-of-type .qnt-waves__dot{border-color:var(--q-teal)}
.qnt-waves__w strong{font:700 .86rem var(--display);color:var(--q-ink)}
.qnt-waves__card{width:100%;padding:8px;border-radius:10px;background:var(--q-soft);display:grid;gap:4px}
.qnt-waves__card i{height:6px;border-radius:3px;background:#C9D3F5}
.qnt-waves__card i:nth-child(1){background:var(--q-royal)}
.qnt-waves__same{grid-column:1/-1;display:flex;align-items:center;gap:7px;margin-top:8px;padding:9px 12px;border-radius:10px;background:#E3F5F2;color:#0A7A6A;font-weight:600;font-size:.84rem}
.qnt-gl{position:relative;margin-top:16px}
.qnt-gl svg{width:100%;height:auto;display:block;border-radius:14px;background:linear-gradient(165deg,#0B22A8,#07104F)}
.qnt-gl__dots{fill:none;stroke:#A9C1FF;stroke-opacity:.35;stroke-width:4.2;stroke-linecap:round}
.qnt-gl__arc{fill:none;stroke:#6EE0CE;stroke-width:2;stroke-dasharray:5 6;opacity:.85;animation:rcDash 2.4s linear infinite}
.qnt-gl__pt{fill:#fff}
.qnt-gl__core{fill:var(--q-teal2)}
.qnt-gl__ring{fill:none;stroke:var(--q-teal2);stroke-width:2;transform-box:fill-box;transform-origin:center;animation:rcPulse 2.6s ease-out infinite}
.qnt-gl__steps{list-style:none;margin:12px 0 0;padding:0;display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:6px}
.qnt-gl__steps li{display:flex;flex-direction:column;gap:3px;padding:8px;border-radius:10px;background:var(--q-soft);font:700 .76rem/1.25 var(--display);color:var(--q-ink)}
.qnt-gl__steps span{font-size:.66rem;color:var(--q-teal)}
.qnt-gl__tag{position:absolute;right:10px;top:10px;font:600 .6rem var(--body);letter-spacing:.08em;text-transform:uppercase;color:#C9D3F5;border:1px dashed #ffffff40;border-radius:999px;padding:2px 8px}

/* strengths */
.qnt-str{list-style:none;margin:0;padding:0;display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:0;border-top:1px solid #ffffff26}
.qnt-str li{display:flex;flex-direction:column;gap:6px;padding:22px 18px 22px 0;border-bottom:1px solid #ffffff26}
.qnt-str li:not(:nth-child(4n)){border-right:1px solid #ffffff1a;padding-right:18px}
.qnt-str li:not(:nth-child(4n+1)){padding-left:18px}
.qnt-str span{font:800 1.8rem/1 var(--display);color:transparent;-webkit-text-stroke:1.5px var(--q-teal2)}
.qnt-str strong{font:700 1.05rem var(--display)}
.qnt-str em{font-style:normal;font-size:.86rem;color:#C9D3F5}

/* panels + why */
.qnt-pan{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px}
.qnt-pan__c{position:relative;display:flex;flex-direction:column;gap:6px;padding:24px;border-radius:22px;text-decoration:none;color:#fff;overflow:hidden;transition:transform .25s,box-shadow .25s}
.qnt-pan__c:hover{transform:translateY(-4px);box-shadow:0 26px 40px -28px #07104F}
.qnt-pan__c0{background:linear-gradient(160deg,#1E5BFF,#0B22A8)}
.qnt-pan__c1{background:linear-gradient(160deg,#0B22A8,#07104F)}
.qnt-pan__c2{background:linear-gradient(160deg,#0E9C88,#0A6A5E)}
.qnt-pan__m{width:56px;height:56px;border-radius:16px;display:grid;place-items:center;background:#ffffff22;font:800 .95rem var(--display);margin-bottom:8px}
.qnt-pan__c strong{font:800 1.35rem var(--display)}
.qnt-pan__a{font:700 .74rem var(--body);letter-spacing:.06em;text-transform:uppercase;color:#E1E8FF}
.qnt-pan__c em{font-style:normal;font-size:.92rem;color:#E1E8FF;flex:1}
.qnt-pan__go{display:inline-flex;align-items:center;gap:6px;font-weight:700;font-size:.88rem;margin-top:8px}
.qnt-why{margin-top:clamp(40px,5vw,60px);display:grid;grid-template-columns:minmax(0,.6fr) minmax(0,1.4fr);gap:clamp(24px,4vw,48px);align-items:start;scroll-margin-top:140px}
.qnt-why h2{color:var(--q-ink);font-size:clamp(1.5rem,2.6vw,2rem);margin:0}
.qnt-why ul{list-style:none;margin:0;padding:0;display:grid;grid-template-columns:1fr 1fr;gap:0;border-top:1px solid var(--q-line)}
.qnt-why li{display:flex;gap:12px;padding:14px 12px 14px 0;border-bottom:1px solid var(--q-line)}
.qnt-why li:nth-child(even){padding-left:12px;border-left:1px solid var(--q-line)}
.qnt-why__n{font:800 .78rem var(--display);color:var(--q-teal);margin-top:3px}
.qnt-why strong{display:block;font:700 .96rem var(--display);color:var(--q-ink)}
.qnt-why em{font-style:normal;font-size:.84rem;color:var(--q-muted)}

/* team */
.qnt-team{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:clamp(24px,4vw,56px);align-items:start}
.qnt-team>*{min-width:0}
.qnt-team__roles{list-style:none;margin:0;padding:0;display:grid;grid-template-columns:1fr 1fr;gap:8px}
.qnt-team__roles li{display:flex;align-items:center;gap:10px;padding:14px;border-radius:14px;background:#fff;border:1px solid var(--q-line);font:700 .92rem var(--display);color:var(--q-ink)}
.qnt-team__roles span{width:30px;height:30px;border-radius:50%;display:grid;place-items:center;background:var(--q-ink);color:var(--q-teal2);font-size:.7rem;flex:none}
.qnt-team__side{padding:clamp(18px,2.6vw,26px);border-radius:22px;background:var(--q-ink);color:#fff;display:flex;flex-direction:column;gap:12px}
.qnt-team__k{font:700 .7rem var(--body);letter-spacing:.12em;text-transform:uppercase;color:var(--q-teal2)}
.qnt-team__skills{list-style:none;margin:0;padding:0;display:grid;grid-template-columns:1fr 1fr;gap:6px}
.qnt-team__skills li{display:flex;align-items:center;gap:7px;font-weight:600;font-size:.88rem}
.qnt-team__skills .rc-ico{color:var(--q-teal2)}
.qnt-team__tools{list-style:none;margin:0;padding:0;display:flex;flex-wrap:wrap;gap:6px}
.qnt-team__tools li{padding:6px 11px;border-radius:8px;border:1px solid #ffffff2a;font:700 .82rem var(--display)}
.qnt-team__tools a{color:var(--q-teal2)}

/* example */
.qnt-ex{margin-top:clamp(40px,5vw,60px);display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:clamp(24px,4vw,48px);align-items:center;padding:clamp(20px,3vw,32px);border-radius:24px;background:var(--q-soft);border:1px dashed #B9C3E0}
.qnt-ex>*{min-width:0}
.qnt-ex__tag{display:inline-block;font:700 .66rem var(--body);letter-spacing:.1em;text-transform:uppercase;color:#8A6A1E;background:#FBF3DD;border-radius:999px;padding:4px 10px}
.qnt-ex h2{color:var(--q-ink);margin:.4em 0 .5em;font-size:clamp(1.4rem,2.4vw,1.8rem)}
.qnt-ex ol{list-style:none;margin:0;padding:0;display:grid;gap:6px;position:relative}
.qnt-ex ol:before{content:"";position:absolute;left:17px;top:12px;bottom:12px;width:2px;background:#C9D3F5}
.qnt-ex li{position:relative;display:flex;align-items:center;gap:12px;font:700 .95rem var(--display);color:var(--q-ink)}
.qnt-ex li span{width:36px;height:36px;border-radius:50%;display:grid;place-items:center;background:#fff;border:2px solid var(--q-royal);font-size:.72rem;color:var(--q-royal);flex:none}
.qnt-ex li:last-child span{background:var(--q-teal);border-color:var(--q-teal);color:#fff}

/* guide */
.qnt-guidesec{padding-top:clamp(40px,5vw,64px);padding-bottom:clamp(40px,5vw,64px)}
.qnt-guide{position:relative;display:grid;grid-template-columns:minmax(0,1fr) 220px;grid-template-rows:auto auto auto;column-gap:30px;padding:clamp(24px,4vw,44px);border-radius:26px;background:linear-gradient(120deg,#07104F,#0B22A8);color:#fff;text-decoration:none;overflow:hidden;transition:transform .25s}
.qnt-guide:hover{transform:translateY(-3px)}
.qnt-guide__k{font:700 .72rem var(--body);letter-spacing:.14em;text-transform:uppercase;color:var(--q-teal2)}
.qnt-guide strong{font:700 clamp(1.3rem,2.6vw,2rem)/1.25 var(--display);margin:10px 0 16px;max-width:30ch}
.qnt-guide__go{display:inline-flex;align-items:center;gap:7px;font-weight:700;color:var(--q-teal2)}
.qnt-guide__art{grid-column:2;grid-row:1/4;align-self:end;width:100%}
.qnt-guide__art rect{fill:#6E8BFF;opacity:.55}

/* final cta */
.qnt-cta{position:relative;overflow:hidden;text-align:center;color:#fff;padding:clamp(56px,7vw,96px) 0;background:radial-gradient(700px 400px at 0% 0%,#1E5BFF55 0%,transparent 60%),linear-gradient(160deg,#0B22A8,#07104F)}
.qnt-cta__bg{position:absolute;inset:0;width:100%;height:100%;opacity:.12}
.qnt-cta__bg rect{fill:#A9C1FF}
.qnt-cta__in{position:relative;max-width:760px}
.qnt-cta h2{color:#fff;font-size:clamp(1.9rem,4vw,3rem);margin-bottom:.4em}
.qnt-cta p{color:#D6DEFA;font-size:1.06rem;margin:0 auto 26px;max-width:60ch}
.qnt-cta .od-hero__ctas{justify-content:center}

/* responsive */
@media (max-width:1100px){
  .qnt-s2i{grid-template-columns:repeat(4,minmax(0,1fr));min-height:0;row-gap:24px}.qnt-s2i:before,.qnt-s2i li:after{display:none}.qnt-s2i li.is-dn,.qnt-s2i li:not(.is-dn){padding-top:0}
  .qnt-mt__cards{grid-template-columns:1fr 1fr}
  .qnt-fmt{grid-template-columns:repeat(3,minmax(0,1fr))}
  .qnt-str{grid-template-columns:1fr 1fr}.qnt-str li{padding:18px!important;border-right:0!important}
  .qnt-tx{grid-template-columns:repeat(3,minmax(0,1fr));row-gap:20px}.qnt-tx li:after{display:none}
}
@media (max-width:900px){
  .qnt-hero__in,.qnt-psw,.qnt-ap__panel,.qnt-qc,.qnt-out,.qnt-eco,.qnt-two,.qnt-why,.qnt-team,.qnt-ex{grid-template-columns:1fr}
  .qnt-hv{max-width:560px;margin:0 auto;width:100%}
  .qnt-ap__tabs{grid-template-columns:1fr}
  .qnt-pan{grid-template-columns:1fr}
  .qnt-guide{grid-template-columns:1fr}.qnt-guide__art{display:none}
}
@media (max-width:640px){
  .qnt-hv__panels{grid-template-columns:1fr 1fr}
  .qnt-hv__chain li{font-size:.58rem}
  .qnt-strip{gap:6px 16px}
  .qnt-strip li{font-size:.86rem}
  .qnt-s2i{grid-template-columns:1fr;gap:0}
  .qnt-s2i li{grid-template-columns:auto auto 1fr;grid-template-rows:auto auto;justify-items:start;text-align:left;column-gap:12px;padding:12px 0!important;border-bottom:1px solid #ffffff1a}
  .qnt-s2i__n{grid-row:span 2;align-self:center;font-size:1.5rem}
  .qnt-s2i__ic{grid-row:span 2;width:42px;height:42px}
  .qnt-s2i em{max-width:none}
  .qnt-ap__copy ul,.qnt-out__list,.qnt-team__roles,.qnt-team__skills,.qnt-why ul,.qnt-qc__stages,.qnt-mt__cards{grid-template-columns:1fr}
  .qnt-why li:nth-child(even){padding-left:0;border-left:0}
  .qnt-logic ol{grid-template-columns:repeat(3,minmax(0,1fr));row-gap:12px}.qnt-logic ol:before{display:none}
  .qnt-tree__br{grid-template-columns:1fr}.qnt-tree__lines{display:none}.qnt-tree__root{margin-bottom:10px}
  .qnt-tx{grid-template-columns:1fr 1fr}
  .qnt-stack{height:300px}.qnt-stack__s{width:72%}.qnt-stack__s1{left:7%}.qnt-stack__s2{left:14%}.qnt-stack__s3{left:21%}.qnt-stack__s4{left:28%}
  .qnt-eco__n>span{font-size:.68rem;padding:5px 8px}.qnt-eco__n.is-big>span{font-size:.74rem;padding:6px 10px}
  .qnt-fmt{grid-template-columns:1fr 1fr}
  .qnt-str{grid-template-columns:1fr}
  .qnt-gl__steps{grid-template-columns:1fr 1fr}
  .qnt-waves__card{display:none}
  .qnt-mid .btn,.qnt-hero .od-hero__ctas .btn,.qnt-cta .od-hero__ctas .btn{width:100%}
}
@media (prefers-reduced-motion:reduce){
  .qnt *,.qnt *:before,.qnt *:after{animation:none!important;transition:none!important}
  .qnt-ps li,.qnt-s2i li,.qnt-qc__band,.qnt-tx li,.qnt-waves__w{opacity:1!important;transform:none!important}
  .qnt-s2i:before,.qnt-waves__line{transform:none!important}
  .qnt-hv__p{opacity:1}
  .qnt-qc__flow{display:none}
}

/* ===== Qualitative Research (qlt-) — site palette with a warm sand accent ===== */
.qlt{--od-navy:#07104F;--od-blue:#1E5BFF;--od-royal:#0B22A8;--od-sky:#E8EEFF;--od-teal:#0E9C88;--od-teal-soft:#E3F5F2;--od-line:#DDE2EC;--od-muted:#525C78;--od-paper:#F5F7FB;
  --r-navy:#07104F;--r-char:#0F1D72;--r-blue:#0B22A8;--r-soft:#EEF2FB;--r-teal:#0E9C88;--r-gold:#C99A2E;--r-line:#DDE2EC;--r-muted:#525C78;
  --l-ink:#07104F;--l-royal:#0B22A8;--l-bright:#1E5BFF;--l-teal:#0E9C88;--l-teal2:#6EE0CE;--l-sand:#C99A2E;--l-sand2:#F0D98F;--l-line:#DDE2EC;--l-muted:#525C78;--l-soft:#F5F4EF}
.qlt .rc-kicker{color:var(--l-teal)}
.qlt .rc-head--light .rc-kicker{color:var(--l-teal2)}
.qlt-sec--soft{background:var(--l-soft)}
.qlt-sec--ink{background:radial-gradient(760px 380px at 85% 0%,#1E3BB8 0%,transparent 60%),radial-gradient(520px 320px at 0% 100%,#C99A2E26 0%,transparent 70%),linear-gradient(165deg,#0A1660,#07104F);color:#fff}
.qlt-lead{font:600 clamp(1.1rem,1.7vw,1.35rem)/1.45 var(--display);color:var(--l-ink)}
.qlt .od-muted a,.qlt-lead a{color:var(--l-royal)}

/* hero */
.qlt-hero{position:relative;overflow:hidden;color:#fff;padding:clamp(32px,4vw,56px) 0 clamp(28px,3vw,40px);background:radial-gradient(620px 460px at 80% 40%,#1E6BFF4d 0%,transparent 62%),radial-gradient(520px 360px at 0% 100%,#C99A2E2e 0%,transparent 70%),linear-gradient(160deg,#0B22A8 0%,#0A1A7A 50%,#07104F 100%)}
.qlt-hero__in{display:grid;grid-template-columns:minmax(0,.9fr) minmax(0,1.1fr);gap:clamp(24px,4vw,56px);align-items:center}
.qlt-hero__in>*{min-width:0}
.qlt-hero .crumbs a,.qlt-hero .crumbs span{color:#CED8F7}
.qlt-eyebrow{display:inline-flex;align-items:center;gap:8px;font:700 .76rem var(--body);letter-spacing:.14em;text-transform:uppercase;color:var(--l-sand2);margin-bottom:16px}
.qlt-hero h1{font-size:clamp(2.6rem,5.4vw,4.4rem);line-height:1.02;color:#fff;margin-bottom:.2em;letter-spacing:-.02em}
.qlt-hero__sub{font:700 clamp(1.2rem,2.1vw,1.6rem)/1.35 var(--display);color:#E1E8FF;margin:0 0 16px}
.qlt-hero__body{color:#C9D3F5;font-size:1.03rem;max-width:58ch;margin:0 0 24px}
.qlt .qlt-btn{background:var(--l-sand2);color:var(--l-ink)}
.qlt .qlt-btn:hover{background:#fff;color:var(--l-ink)}
.qlt-hero .btn--ghost{color:#fff;border-color:#ffffff70}
.qlt-hero .btn--ghost:hover{background:#ffffff1a;color:#fff}
.qlt-hv{position:relative;padding:14px;border-radius:24px;background:#ffffff0a;border:1px solid #ffffff22}
.qlt-hv__svg{display:block;width:100%;height:auto}
.qlt-hv__head{fill:#E8C3A0}.qlt-hv__head--r{fill:#C99872}
.qlt-hv__body{fill:#6EE0CE}.qlt-hv__body--r{fill:#F0D98F}
.qlt-hv__t{font:700 11px var(--body);fill:#C9D3F5;letter-spacing:.04em}
.qlt-hv__t--w{fill:#07104F}
.qlt-hv__conv,.qlt-hv__link{fill:none;stroke:#ffffff30;stroke-width:2;stroke-dasharray:4 6;transition:stroke .4s}
.qlt-hv__conv.is-on,.qlt-hv__link.is-on{stroke:#6EE0CE;animation:rcDash 1.6s linear infinite}
.qlt-hv__tr g{opacity:.25;transition:opacity .4s;transition-delay:calc(var(--i)*120ms)}
.qlt-hv__tr.is-on g{opacity:1}
.qlt-hv__tr rect{fill:#F5F7FB}
.qlt-hv__tr text{font:500 10.5px var(--body);fill:#07104F;font-style:italic}
.qlt-hv__ctx{fill:none;stroke:#ffffff1a;stroke-width:1.5;stroke-dasharray:6 6;transition:stroke .4s}
.qlt-hv__ctx.is-on{stroke:#F0D98F}
.qlt-hv__ctxl{opacity:0;transition:opacity .4s}.qlt-hv__ctxl.is-on{opacity:1;fill:#F0D98F}
.qlt-hv__th g{opacity:.25;transition:opacity .4s;transition-delay:calc(var(--i)*140ms)}
.qlt-hv__th.is-on g{opacity:1}
.qlt-hv__tl{fill:none;stroke:#ffffff40;stroke-width:1.5}
.qlt-hv__cl--a circle{fill:#6EE0CE}.qlt-hv__cl--b circle{fill:#A9C1FF}.qlt-hv__cl--c circle{fill:#F0D98F}
.qlt-hv__in{opacity:.3;transition:opacity .45s}
.qlt-hv__in.is-on{opacity:1}
.qlt-hv__in rect{fill:#F0D98F}
.qlt-hv__bulb{fill:none;stroke:#07104F;stroke-width:2;stroke-linecap:round}
.qlt-hv__chain{list-style:none;margin:8px 0 0;padding:0;display:grid;grid-template-columns:repeat(5,1fr);gap:4px}
.qlt-hv__chain li{position:relative;text-align:center;padding-top:16px;font:700 .72rem var(--body);color:#A9B8E8;letter-spacing:.06em;text-transform:uppercase;transition:color .3s}
.qlt-hv__chain li:before{content:"";position:absolute;top:4px;left:50%;width:8px;height:8px;margin-left:-4px;border-radius:50%;background:#ffffff30;transition:all .3s}
.qlt-hv__chain li.is-done{color:#fff}
.qlt-hv__chain li.is-done:before{background:#6EE0CE}
.qlt-hv__chain li.is-cur:before{background:#F0D98F;box-shadow:0 0 0 4px #F0D98F33}
.qlt-hv__tag{position:absolute;right:12px;top:-11px;font:600 .6rem var(--body);letter-spacing:.08em;text-transform:uppercase;color:#C9D3F5;background:#0A1A7A;border:1px dashed #ffffff40;border-radius:999px;padding:3px 9px}
.qlt-strip{list-style:none;margin:clamp(24px,3vw,36px) 0 0;padding:16px 0 0;display:flex;flex-wrap:wrap;gap:8px 26px;border-top:1px solid #ffffff22}
.qlt-strip li{display:inline-flex;align-items:center;gap:8px;font:700 .92rem var(--display);color:#E1E8FF}
.qlt-strip .rc-ico{color:var(--l-sand2)}

/* why */
.qlt-why{display:grid;grid-template-columns:minmax(0,.9fr) minmax(0,1.1fr);gap:clamp(24px,4vw,56px);align-items:end;margin-bottom:clamp(28px,4vw,44px)}
.qlt-why>*{min-width:0}
.qlt-tags{list-style:none;margin:14px 0 0;padding:0;display:flex;flex-wrap:wrap;gap:6px}
.qlt-tags li{padding:6px 12px;border-radius:999px;border:1px solid var(--l-line);font:600 .84rem var(--body);color:var(--l-ink);background:#fff}
.qlt-path{list-style:none;margin:0;padding:0;display:grid;grid-template-columns:repeat(6,minmax(0,1fr));gap:0;position:relative}
.qlt-path:before{content:"";position:absolute;left:8%;right:8%;top:30px;height:2px;background:linear-gradient(90deg,var(--l-royal),var(--l-teal),var(--l-sand));transform:scaleX(0);transform-origin:left;transition:transform 1.4s ease}
.qlt-path.is-in:before{transform:scaleX(1)}
.qlt-path li{position:relative;display:flex;flex-direction:column;align-items:center;gap:10px;text-align:center;font:700 .92rem/1.25 var(--display);color:var(--l-ink);padding:0 6px;opacity:0;transform:translateY(8px);transition:all .45s;transition-delay:calc(var(--i)*130ms)}
.qlt-path.is-in li{opacity:1;transform:none}
.qlt-path li span{width:60px;height:60px;border-radius:50%;display:grid;place-items:center;background:#fff;border:2px solid var(--l-line);color:var(--l-royal);position:relative;z-index:1}
.qlt-path li:last-child span{background:var(--l-sand2);border-color:var(--l-sand2);color:var(--l-ink)}

/* capabilities */
.qlt-cap{display:grid;grid-template-columns:minmax(0,.75fr) minmax(0,1.25fr);gap:16px;align-items:start}
.qlt-cap__nav{list-style:none;margin:0;padding:0;display:grid;gap:4px;border-left:2px solid var(--l-line)}
.qlt-cap__nav button{width:100%;display:flex;align-items:center;gap:10px;padding:12px 14px;margin-left:-2px;border:0;border-left:2px solid transparent;background:none;font:700 .95rem var(--display);color:var(--l-muted);cursor:pointer;text-align:left;transition:all .2s}
.qlt-cap__nav button span{font-size:.7rem;color:#9AA4B8}
.qlt-cap__nav button .rc-ico{flex:none}
.qlt-cap__nav button:hover{color:var(--l-ink)}
.qlt-cap__nav button.is-on{border-left-color:var(--l-sand);color:var(--l-ink);background:#fff}
.qlt-cap__nav button.is-on .rc-ico{color:var(--l-sand)}
.qlt-cap__nav button:focus-visible{outline:2px solid var(--l-teal);outline-offset:-2px}
.qlt-cap__panel{position:relative;padding:clamp(22px,3vw,34px);border-radius:22px;background:#fff;border:1px solid var(--l-line);animation:rcPanel .35s ease;min-height:100%}
.qlt-cap__art{float:right;width:min(42%,240px);margin:0 0 12px 18px;padding:12px;border-radius:16px;background:linear-gradient(160deg,#EEF2FB,#F5F4EF)}
.qlt-cap__art svg{display:block;width:100%;height:auto}
.qa-h{fill:#0E9C88}.qa-h--r{fill:#C99A2E}
.qa-b{fill:#6EE0CE}.qa-b--r{fill:#F0D98F}
.qa-t{fill:#0B22A8}.qa-t2{fill:none;stroke:#0B22A8;stroke-width:4;stroke-linejoin:round}
.qa-talk{fill:none;stroke:#1E5BFF;stroke-width:2;stroke-dasharray:4 4}
.qa-scr{fill:#fff;stroke:#A9B8E8;stroke-width:1.5}
.qa-g{stroke:#A9B8E8;stroke-width:2}
.qa-wall{fill:#fff;stroke:#A9B8E8;stroke-width:1.5}
.qa-win{fill:#E1E8FF}
.qa-route{fill:none;stroke:#C99A2E;stroke-width:2.5;stroke-dasharray:5 5}
.qa-eye{fill:#fff;stroke:#0B22A8;stroke-width:2}
.qa-brief{fill:#C99A2E}
.qa-pin{fill:#0B22A8}
.qa-tx{font:700 9px var(--body);fill:#525C78}
.qlt-cap__k{font:700 .72rem var(--body);letter-spacing:.12em;text-transform:uppercase;color:var(--l-sand)}
.qlt-cap__panel h3{font-size:1.5rem;margin:6px 0 8px;color:var(--l-ink)}
.qlt-cap__panel>p{color:var(--l-muted);margin:0 0 14px}
.qlt-cap__l{display:block;clear:both;font:700 .7rem var(--body);letter-spacing:.1em;text-transform:uppercase;color:#8A93AA;margin:10px 0 8px}
.qlt-cap__panel>ul{list-style:none;margin:0;padding:0;display:flex;flex-wrap:wrap;gap:6px}
.qlt-cap__panel>ul li{padding:6px 11px;border-radius:8px;background:var(--l-soft);font:600 .86rem var(--body);color:var(--l-ink);animation:rcPanel .4s ease both;animation-delay:calc(var(--i)*35ms)}
.qlt-msj{list-style:none;margin:0 0 6px;padding:0;display:flex;flex-wrap:wrap;gap:6px 16px}
.qlt-msj li{position:relative;padding:6px 10px;border-radius:999px;background:var(--l-ink);color:#fff;font:700 .78rem var(--body)}
.qlt-msj li:not(:last-child):after{content:"→";position:absolute;right:-13px;color:var(--l-sand)}
.qlt-ctx5{display:flex;flex-wrap:wrap;gap:0;margin-bottom:6px}
.qlt-ctx5 span{padding:8px 14px;margin-right:-8px;border-radius:999px;border:1.5px solid var(--l-teal);background:#E3F5F2cc;font:700 .8rem var(--display);color:#0A7A6A}
.qlt-selwrap{margin-top:clamp(36px,5vw,56px)}
.qlt-selwrap h3{font-size:clamp(1.25rem,2.2vw,1.6rem);color:var(--l-ink);margin:0 0 14px}
.qlt-sel{display:grid;grid-template-columns:minmax(0,1.2fr) minmax(0,.8fr);gap:12px;align-items:stretch}
.qlt-sel__q,.qlt-sel__a{padding:20px;border-radius:20px;min-width:0}
.qlt-sel__q{background:#fff;border:1px solid var(--l-line)}
.qlt-sel__q>div{display:flex;flex-wrap:wrap;gap:6px}
.qlt-sel__q button{padding:9px 13px;border-radius:12px;border:1px solid var(--l-line);background:#fff;font:600 .88rem var(--body);color:var(--l-ink);cursor:pointer;text-align:left;transition:all .2s}
.qlt-sel__q button:hover{border-color:var(--l-royal)}
.qlt-sel__q button.is-on{background:var(--l-royal);border-color:var(--l-royal);color:#fff}
.qlt-sel__q button:focus-visible{outline:2px solid var(--l-teal);outline-offset:2px}
.qlt-sel__k{display:block;font:700 .7rem var(--body);letter-spacing:.12em;text-transform:uppercase;color:#8A93AA;margin-bottom:10px}
.qlt-sel__a{background:var(--l-ink);color:#fff;display:flex;flex-direction:column;gap:8px;animation:rcPanel .35s ease}
.qlt-sel__a .qlt-sel__k{color:var(--l-teal2)}
.qlt-sel__a strong{display:flex;align-items:center;gap:10px;font:800 1.25rem/1.25 var(--display)}
.qlt-sel__a strong .rc-ico{color:var(--l-sand2);flex:none}
.qlt-sel__a p{margin:0;color:#C9D3F5;font-size:.92rem}
.qlt-sel__a .rc-link{color:var(--l-teal2);margin-top:auto}
.qlt-sel__note{font-style:normal;font-size:.76rem;color:#A9B8E8}

/* recruitment */
.qlt-rec{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px}
.qlt-rec__c{padding:clamp(18px,2.4vw,24px);border-radius:20px;background:#fff;border:1px solid var(--l-line);border-top:5px solid var(--c);display:flex;flex-direction:column;gap:10px}
.qlt-rec__c0{--c:#1E5BFF}.qlt-rec__c1{--c:#0B22A8}.qlt-rec__c2{--c:#0E9C88}
.qlt-rec__h{display:flex;align-items:center;gap:10px;font:800 1.15rem var(--display);color:var(--l-ink)}
.qlt-rec__h>span{width:42px;height:42px;border-radius:12px;display:grid;place-items:center;background:color-mix(in srgb,var(--c) 12%,#fff);color:var(--c)}
.qlt-rec__k{font:700 .68rem var(--body);letter-spacing:.1em;text-transform:uppercase;color:#8A93AA}
.qlt-rec__c ul{list-style:none;margin:0;padding:0;display:flex;flex-wrap:wrap;gap:5px}
.qlt-rec__c li{padding:5px 10px;border-radius:999px;border:1px solid color-mix(in srgb,var(--c) 30%,#fff);font:600 .8rem var(--body);color:var(--l-ink)}
.qlt-scr{margin-top:clamp(40px,5vw,64px);display:grid;grid-template-columns:minmax(0,.8fr) minmax(0,1.2fr);gap:clamp(24px,4vw,56px);align-items:center}
.qlt-scr>*{min-width:0}
.qlt-scr h2{color:var(--l-ink);margin:.3em 0 .4em}
.qlt-fun{display:grid;grid-template-columns:minmax(0,1.3fr) minmax(0,.7fr);gap:12px;align-items:center}
.qlt-fun__bars{list-style:none;margin:0;padding:0;display:flex;flex-direction:column;align-items:center;gap:5px}
.qlt-fun__bars li{width:var(--w);opacity:0;transform:scaleX(.9);transition:all .45s;transition-delay:calc(var(--i)*90ms)}
.qlt-fun.is-in .qlt-fun__bars li{opacity:1;transform:none}
.qlt-fun__bars button{width:100%;display:flex;align-items:center;gap:8px;padding:9px 12px;border:0;border-radius:10px;background:color-mix(in srgb,#0B22A8 calc(14% + var(--i)*10%),#fff);color:#07104F;font:700 .82rem var(--display);cursor:pointer;text-align:left;transition:transform .2s,box-shadow .2s}
.qlt-fun__bars li:nth-child(n+5) button{color:#fff}
.qlt-fun__bars li:last-child button{background:var(--l-teal);color:#fff}
.qlt-fun__bars button span{font-size:.66rem;opacity:.7}
.qlt-fun__bars button.is-on{box-shadow:0 0 0 2px var(--l-sand);transform:scale(1.02)}
.qlt-fun__bars button:focus-visible{outline:2px solid var(--l-sand);outline-offset:2px}
.qlt-fun__d{padding:18px;border-radius:16px;background:var(--l-soft);animation:rcPanel .3s ease}
.qlt-fun__d span{font:700 .68rem var(--body);letter-spacing:.1em;text-transform:uppercase;color:var(--l-sand)}
.qlt-fun__d strong{display:block;font:700 1.05rem var(--display);color:var(--l-ink);margin:4px 0}
.qlt-fun__d p{margin:0;font-size:.88rem;color:var(--l-muted)}
.qlt-val{margin-top:clamp(36px,5vw,56px);display:grid;grid-template-columns:minmax(0,.6fr) minmax(0,1.4fr);gap:16px;align-items:stretch}
.qlt-val>*{min-width:0}
.qlt-val__core{display:flex;flex-direction:column;justify-content:center;gap:10px;padding:24px;border-radius:22px;background:var(--l-ink);color:#fff}
.qlt-val__core .rc-ico{color:var(--l-teal2)}
.qlt-val__core strong{font:800 1.25rem/1.25 var(--display)}
.qlt-val__core em{font-style:normal;font-size:.84rem;color:#C9D3F5;border-top:1px solid #ffffff26;padding-top:10px}
.qlt-val ul{list-style:none;margin:0;padding:0;display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:10px}
.qlt-val li{display:flex;flex-direction:column;gap:8px;padding:16px;border-radius:16px;background:#fff;border:1px solid var(--l-line)}
.qlt-val li>span{width:36px;height:36px;border-radius:10px;display:grid;place-items:center;background:#E3F5F2;color:var(--l-teal)}
.qlt-val strong{font:700 .95rem var(--display);color:var(--l-ink)}
.qlt-val em{font-style:normal;font-size:.83rem;color:var(--l-muted)}
.qlt-val li strong,.qlt-val li em{display:block}
.qlt-val .qlt-val__core strong{color:#fff}
.qlt-val .qlt-val__core em{color:#C9D3F5}

/* 11-step process */
.qlt-proc{display:grid;grid-template-columns:1.6fr .8fr 1.1fr;gap:12px}
.qlt-proc__ph{padding:18px;border-radius:20px;background:#ffffff0b;border:1px solid #ffffff1c}
.qlt-proc__ph:nth-child(2){background:#C99A2E1f;border-color:#C99A2E55}
.qlt-proc__k{display:block;font:700 .7rem var(--body);letter-spacing:.12em;text-transform:uppercase;color:var(--l-teal2);margin-bottom:12px}
.qlt-proc__ph:nth-child(2) .qlt-proc__k{color:var(--l-sand2)}
.qlt-proc ol{list-style:none;margin:0;padding:0;display:grid;gap:6px}
.qlt-proc li{display:flex;align-items:center;gap:10px;padding:10px 12px;border-radius:12px;background:#ffffff0f;font:700 .92rem var(--display)}
.qlt-proc li span{font-size:.72rem;color:#A9B8E8;min-width:20px}

/* IDI / FGD */
.qlt-wf__tabs{display:flex;gap:6px;margin-bottom:14px}
.qlt-wf__tabs button{display:inline-flex;align-items:center;gap:8px;padding:10px 16px;border-radius:999px;border:1px solid var(--l-line);background:#fff;font:700 .92rem var(--display);color:var(--l-ink);cursor:pointer}
.qlt-wf__tabs button.is-on{background:var(--l-ink);border-color:var(--l-ink);color:#fff}
.qlt-wf__tabs button:focus-visible{outline:2px solid var(--l-teal);outline-offset:2px}
.qlt-idi{list-style:none;margin:0;padding:0;display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:8px;counter-reset:x}
.qlt-idi li{border-radius:14px;background:#fff;border:1px solid var(--l-line);overflow:hidden;animation:rcPanel .35s ease both;animation-delay:calc(var(--i)*30ms)}
.qlt-idi button{width:100%;display:flex;align-items:center;gap:10px;padding:13px 14px;border:0;background:none;font:700 .9rem var(--display);color:var(--l-ink);cursor:pointer;text-align:left}
.qlt-idi button span{font-size:.72rem;color:var(--l-sand)}
.qlt-idi button .rc-ico{margin-left:auto;color:#9AA4B8;transition:transform .2s}
.qlt-idi li.is-open{border-color:var(--l-royal)}
.qlt-idi li.is-open button .rc-ico{transform:rotate(45deg);color:var(--l-royal)}
.qlt-idi p{margin:0;padding:0 14px 14px;font-size:.84rem;color:var(--l-muted)}
.qlt-idi button:focus-visible{outline:2px solid var(--l-teal);outline-offset:-2px}
.qlt-fgd{display:grid;grid-template-columns:minmax(0,1.4fr) minmax(0,.6fr);gap:16px;align-items:center}
.qlt-fgd>*{min-width:0}
.qlt-fgd ol{list-style:none;margin:0;padding:0;display:flex;flex-wrap:wrap;gap:8px 20px}
.qlt-fgd li{position:relative;display:inline-flex;align-items:center;gap:7px;padding:8px 12px;border-radius:10px;background:#fff;border:1px solid var(--l-line);font:700 .86rem var(--display);color:var(--l-ink);animation:rcPanel .35s ease both;animation-delay:calc(var(--i)*35ms)}
.qlt-fgd li span{font-size:.68rem;color:var(--l-sand)}
.qlt-fgd li:not(:last-child):after{content:"→";position:absolute;right:-16px;color:#B9C3E0}
.qlt-fgd li.is-key{background:var(--l-sand2);border-color:var(--l-sand2)}
.qlt-fgd__comp{display:flex;flex-direction:column;gap:10px;padding:18px;border-radius:18px;background:var(--l-ink);color:#fff}
.qlt-fgd__comp svg{width:140px;align-self:center}
.qlt-fgd__comp strong{font:700 1rem var(--display)}
.qlt-fgd__comp p{margin:4px 0 0;font-size:.85rem;color:#C9D3F5}

/* mystery shopping route */
.qlt-ms{position:relative;padding:10px 0}
.qlt-ms__route{position:absolute;left:0;right:0;top:50%;width:100%;height:120px;transform:translateY(-50%)}
.qlt-ms__route path{fill:none;stroke:var(--l-sand);stroke-width:3;stroke-dasharray:8 8;vector-effect:non-scaling-stroke;animation:rcDash 2s linear infinite}
.qlt-ms ol{list-style:none;margin:0;padding:0;display:grid;grid-template-columns:repeat(10,minmax(0,1fr));gap:6px;position:relative;min-height:260px;align-items:start}
.qlt-ms li{display:flex;flex-direction:column;align-items:center;gap:4px;text-align:center;opacity:0;transform:translateY(8px);transition:all .45s;transition-delay:calc(var(--i)*90ms)}
.qlt-ms.is-in li{opacity:1;transform:none}
.qlt-ms li.is-dn{padding-top:140px}
.qlt-ms__pin{width:38px;height:38px;border-radius:50%;display:grid;place-items:center;background:#fff;border:2px solid var(--l-sand);color:var(--l-sand)}
.qlt-ms li:last-child .qlt-ms__pin{background:var(--l-ink);border-color:var(--l-ink);color:var(--l-sand2)}
.qlt-ms li b{font:800 .72rem var(--display);color:var(--l-sand)}
.qlt-ms li em{font-style:normal;font:700 .84rem/1.25 var(--display);color:var(--l-ink)}

/* ethnography + diary */
.qlt-ed{display:grid;grid-template-columns:1fr 1fr;gap:16px}
.qlt-ed__c{padding:clamp(20px,3vw,30px);border-radius:24px;background:#fff;border:1px solid var(--l-line);min-width:0}
.qlt-ed__k{display:inline-flex;align-items:center;gap:7px;font:700 .72rem var(--body);letter-spacing:.12em;text-transform:uppercase;color:var(--l-teal)}
.qlt-ed__c h3{font-size:1.35rem;color:var(--l-ink);margin:8px 0 16px}
.qlt-ring{position:relative;width:min(100%,300px);aspect-ratio:1;margin:0 auto 18px;border-radius:50%;background:radial-gradient(circle,#F5F4EF 0 30%,transparent 31%),repeating-radial-gradient(circle,#E3F5F2 0 1px,transparent 1px 22px)}
.qlt-ring span{position:absolute;left:calc(50% + 38% * cos(var(--a)));top:calc(50% + 38% * sin(var(--a)));transform:translate(-50%,-50%);padding:7px 12px;border-radius:999px;background:#fff;border:1.5px solid var(--l-teal);font:700 .8rem var(--display);color:var(--l-ink);white-space:nowrap;opacity:0;transition:opacity .4s;transition-delay:calc(var(--i)*120ms)}
.qlt-ed.is-in .qlt-ring span{opacity:1}
.qlt-ring b{position:absolute;left:50%;top:50%;transform:translate(-50%,-50%);width:36%;aspect-ratio:1;border-radius:50%;display:grid;place-items:center;text-align:center;background:var(--l-ink);color:#fff;font:800 .82rem/1.2 var(--display);padding:8px}
.qlt-chain{list-style:none;margin:0;padding:0;display:flex;flex-wrap:wrap;gap:6px 16px}
.qlt-chain li{position:relative;padding:6px 10px;border-radius:8px;background:var(--l-soft);font:600 .8rem var(--body);color:var(--l-ink)}
.qlt-chain li:not(:last-child):after{content:"→";position:absolute;right:-13px;color:var(--l-teal)}
.qlt-chain li:last-child{background:var(--l-teal);color:#fff}
.qlt-days{display:grid;grid-template-columns:repeat(6,1fr);gap:6px;margin-bottom:18px;position:relative}
.qlt-days:before{content:"";position:absolute;left:4%;right:4%;top:32px;height:2px;background:linear-gradient(90deg,var(--l-royal),var(--l-teal));transform:scaleX(0);transform-origin:left;transition:transform 1.2s}
.qlt-ed.is-in .qlt-days:before{transform:scaleX(1)}
.qlt-days div{display:flex;flex-direction:column;align-items:center;gap:6px;text-align:center}
.qlt-days span{font:700 .7rem var(--body);color:var(--l-royal)}
.qlt-days i{width:14px;height:14px;border-radius:50%;background:#fff;border:3px solid var(--l-teal);position:relative;z-index:1}
.qlt-days em{font-style:normal;font:600 .72rem/1.25 var(--body);color:var(--l-muted);padding:8px 4px;border-radius:8px;background:var(--l-soft);width:100%}

/* moderation + session QC */
.qlt-mod{display:grid;grid-template-columns:minmax(0,1.1fr) minmax(0,.9fr);gap:clamp(24px,4vw,56px);align-items:start}
.qlt-mod>*{min-width:0}
.qlt-mod__ladder{list-style:none;margin:0 0 18px;padding:0;display:grid;gap:6px}
.qlt-mod__ladder li{display:flex;align-items:center;gap:12px;padding:12px 16px;border-radius:12px;background:#fff;border:1px solid var(--l-line);margin-left:calc(var(--i)*18px);font:700 1rem var(--display);color:var(--l-ink)}
.qlt-mod__ladder li span{width:26px;height:26px;border-radius:50%;display:grid;place-items:center;background:var(--l-sand2);color:var(--l-ink);font-size:.74rem;flex:none}
.qlt-mod__ladder li:last-child{background:var(--l-ink);color:#fff;border-color:var(--l-ink)}
.qlt-mod__lang{padding:16px;border-radius:16px;background:#fff;border:1px dashed #C3CBE0}
.qlt-mod__lang strong{font:700 .95rem var(--display);color:var(--l-ink)}
.qlt-mod__lang ul{list-style:none;margin:8px 0;padding:0;display:flex;flex-wrap:wrap;gap:6px}
.qlt-mod__lang li{padding:5px 10px;border-radius:999px;background:var(--l-soft);font:600 .8rem var(--body)}
.qlt-mod__lang em{font-style:normal;font-size:.82rem;color:var(--l-muted)}
.qlt-sqc{padding:clamp(20px,3vw,28px);border-radius:22px;background:var(--l-ink);color:#fff}
.qlt-sqc__k{display:flex;align-items:center;gap:8px;font:700 .72rem var(--body);letter-spacing:.12em;text-transform:uppercase;color:var(--l-teal2);margin-bottom:14px}
.qlt-sqc__k i{width:8px;height:8px;border-radius:50%;background:#C2603F;animation:ctiBlink 1.4s ease-in-out infinite}
@keyframes ctiBlink{50%{opacity:.25}}
.qlt-sqc ul{list-style:none;margin:0;padding:0;display:grid;grid-template-columns:1fr 1fr;gap:6px}
.qlt-sqc li{display:flex;align-items:center;gap:8px;padding:9px 10px;border-radius:10px;background:#ffffff0d;font:600 .86rem var(--body)}
.qlt-sqc li .rc-ico{color:var(--l-teal2);flex:none}
.qlt-sqc p{margin:14px 0 0;font-size:.84rem;color:#C9D3F5}

/* QA architecture */
.qlt-qa{display:grid;grid-template-columns:minmax(0,.8fr) minmax(0,1.2fr);gap:clamp(24px,4vw,56px);align-items:center}
.qlt-qa>*{min-width:0}
.qlt-qa__life{display:flex;gap:6px;margin-top:10px}
.qlt-qa__life span{padding:6px 12px;border-radius:999px;font:700 .76rem var(--body)}
.qlt-qa__life .b{background:#6EE0CE26;color:var(--l-teal2)}
.qlt-qa__life .d{background:#F0D98F26;color:var(--l-sand2)}
.qlt-qa__life .a{background:#A9C1FF26;color:#C9D3F5}
.qlt-qa__stack{list-style:none;margin:0;padding:0;display:flex;flex-direction:column;align-items:center;gap:5px}
.qlt-qa__stack li{width:var(--w);display:flex;align-items:center;gap:12px;padding:12px 16px;border-radius:12px;font:700 .95rem var(--display);border:1px solid #ffffff1f}
.qlt-qa__stack li span{font-size:.72rem;opacity:.7}
.qlt-qa__stack li em{margin-left:auto;font-style:normal;font:700 .62rem var(--body);letter-spacing:.1em;text-transform:uppercase;padding:3px 8px;border-radius:999px}
.qlt-qa__stack li.is-before{background:#6EE0CE14}.qlt-qa__stack li.is-before em{background:#6EE0CE26;color:var(--l-teal2)}
.qlt-qa__stack li.is-during{background:#F0D98F1a}.qlt-qa__stack li.is-during em{background:#F0D98F26;color:var(--l-sand2)}
.qlt-qa__stack li.is-after{background:#A9C1FF1a}.qlt-qa__stack li.is-after em{background:#A9C1FF26;color:#E1E8FF}

/* philosophy stairs */
.qlt-phil{background:linear-gradient(180deg,#fff,#F5F4EF)}
.qlt-stairs{list-style:none;margin:0;padding:0;display:grid;grid-template-columns:repeat(7,minmax(0,1fr));gap:6px;align-items:end;min-height:240px}
.qlt-stairs li{display:flex;align-items:flex-start;justify-content:center;text-align:center;padding:14px 8px;height:calc(var(--h) + 40px);border-radius:14px 14px 0 0;background:color-mix(in srgb,#0B22A8 calc(10% + var(--i)*13%),#fff);color:#07104F}
.qlt-stairs li:nth-child(n+4){color:#fff}
.qlt-stairs li:last-child{background:var(--l-sand2);color:var(--l-ink)}
.qlt-stairs strong{font:800 .95rem/1.2 var(--display)}

/* deliverables + apps */
.qlt-del{display:grid;grid-template-columns:1.1fr 1.2fr .8fr;gap:12px}
.qlt-del__c{padding:20px;border-radius:20px;background:#fff;border:1px solid var(--l-line)}
.qlt-del__c2{background:var(--l-ink);color:#fff;border-color:var(--l-ink)}
.qlt-del__h{display:flex;align-items:center;gap:8px;font:800 1.05rem var(--display);color:var(--l-ink);margin-bottom:12px}
.qlt-del__c2 .qlt-del__h{color:#fff}
.qlt-del__h .rc-ico{color:var(--l-sand)}
.qlt-del__c ul{list-style:none;margin:0;padding:0;display:grid;gap:6px}
.qlt-del__c li{display:flex;align-items:center;gap:8px;font:600 .9rem var(--body);padding-bottom:6px;border-bottom:1px dashed var(--l-line)}
.qlt-del__c2 li{border-color:#ffffff26}
.qlt-del__c li:before{content:"";width:6px;height:6px;border-radius:50%;background:var(--l-teal);flex:none}
.qlt-apps{margin-top:18px;display:flex;flex-wrap:wrap;gap:8px;align-items:center}
.qlt-apps>span{font:700 .72rem var(--body);letter-spacing:.12em;text-transform:uppercase;color:#8A93AA;margin-right:6px}
.qlt-apps ul{list-style:none;margin:0;padding:0;display:contents}
.qlt-apps li{padding:6px 12px;border-radius:999px;background:#fff;border:1px solid var(--l-line);font:600 .84rem var(--body);color:var(--l-ink)}

/* audiences + htr */
.qlt-aud{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:0;border-radius:22px;overflow:hidden;margin-bottom:clamp(28px,4vw,40px)}
.qlt-aud__c{display:flex;flex-direction:column;gap:8px;padding:clamp(20px,3vw,30px);text-decoration:none;color:#fff;transition:filter .2s}
.qlt-aud__c:hover{filter:brightness(1.08)}
.qlt-aud__c0{background:#1E5BFF}.qlt-aud__c1{background:#0B22A8}.qlt-aud__c2{background:#0E9C88}
.qlt-aud__c strong{font:800 1.8rem var(--display)}
.qlt-aud__c span{color:#E1E8FF;font-size:.92rem;flex:1}
.qlt-aud__c em{font-style:normal;display:inline-flex;align-items:center;gap:6px;font-weight:700;font-size:.86rem}
.qlt-htr{display:grid;grid-template-columns:minmax(0,.8fr) minmax(0,1.2fr);gap:20px;align-items:center;padding:clamp(18px,3vw,28px);border-radius:22px;background:var(--l-soft);margin-bottom:clamp(40px,5vw,60px)}
.qlt-htr>*{min-width:0}
.qlt-htr h3{margin:.3em 0;color:var(--l-ink)}
.qlt-htr ul{list-style:none;margin:0;padding:0;display:flex;flex-wrap:wrap;gap:6px}
.qlt-htr li{padding:8px 13px;border-radius:10px;background:#fff;border:1px solid var(--l-line);font:700 .88rem var(--display);color:var(--l-ink)}

/* pillars + team */
.qlt-pil{list-style:none;margin:0;padding:0;display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:0;border-top:1px solid #DED9C9}
.qlt-pil li{display:flex;flex-direction:column;gap:8px;padding:22px 20px 22px 0;border-bottom:1px solid #DED9C9}
.qlt-pil li:not(:nth-child(3n)){border-right:1px solid #DED9C9}
.qlt-pil li:not(:nth-child(3n+1)){padding-left:20px}
.qlt-pil li>span{width:42px;height:42px;border-radius:12px;display:grid;place-items:center;background:var(--l-ink);color:var(--l-sand2)}
.qlt-pil strong{font:700 1.05rem var(--display);color:var(--l-ink)}
.qlt-pil em{font-style:normal;font-size:.88rem;color:var(--l-muted)}
.qlt-team{margin-top:clamp(36px,5vw,56px);display:grid;grid-template-columns:1fr 1fr;gap:16px}
.qlt-team>div{padding:clamp(18px,2.6vw,26px);border-radius:20px;background:#fff;border:1px solid var(--l-line);min-width:0}
.qlt-team h3{margin:0 0 12px;color:var(--l-ink)}
.qlt-team__r{list-style:none;margin:0;padding:0;display:grid;grid-template-columns:1fr 1fr;gap:6px}
.qlt-team__r li{padding:10px 12px;border-radius:10px;background:var(--l-soft);font:700 .88rem var(--display);color:var(--l-ink)}
.qlt-team__k{display:block;font:700 .7rem var(--body);letter-spacing:.12em;text-transform:uppercase;color:#8A93AA;margin:0 0 8px}
.qlt-team__s{list-style:none;margin:0 0 14px;padding:0;display:grid;grid-template-columns:1fr 1fr;gap:5px}
.qlt-team__s li{display:flex;align-items:center;gap:6px;font:600 .86rem var(--body);color:var(--l-ink)}
.qlt-team__s .rc-ico{color:var(--l-teal)}
.qlt-team__t{list-style:none;margin:0;padding:0;display:flex;flex-wrap:wrap;gap:6px}
.qlt-team__t li{padding:5px 10px;border-radius:8px;border:1px solid var(--l-line);font:700 .8rem var(--display);color:var(--l-ink)}
.qlt-team__t a{color:var(--l-royal)}

/* example + guide + cta */
.qlt-ex{max-width:880px;text-align:center}
.qlt-ex__tag{display:inline-block;font:700 .66rem var(--body);letter-spacing:.1em;text-transform:uppercase;color:#8A6A1E;background:#FBF3DD;border-radius:999px;padding:4px 10px}
.qlt-ex__q{font:600 clamp(1.05rem,1.8vw,1.3rem)/1.55 var(--display);color:var(--l-ink);margin:14px 0}
.qlt-guidesec{padding-top:clamp(40px,5vw,64px);padding-bottom:clamp(40px,5vw,64px)}
.qlt-guide{position:relative;display:flex;flex-direction:column;gap:10px;padding:clamp(24px,4vw,44px);padding-left:clamp(80px,9vw,120px);border-radius:24px;background:#fff;border:1px solid var(--l-line);border-left:6px solid var(--l-sand);text-decoration:none;color:var(--l-ink);transition:transform .25s,box-shadow .25s}
.qlt-guide:hover{transform:translateY(-3px);box-shadow:0 24px 40px -30px var(--l-ink)}
.qlt-guide__q{position:absolute;left:clamp(22px,3vw,40px);top:clamp(24px,4vw,44px);color:var(--l-sand)}
.qlt-guide__k{font:700 .72rem var(--body);letter-spacing:.14em;text-transform:uppercase;color:var(--l-teal)}
.qlt-guide strong{font:700 clamp(1.25rem,2.4vw,1.8rem)/1.3 var(--display);max-width:34ch}
.qlt-guide__go{display:inline-flex;align-items:center;gap:7px;font-weight:700;color:var(--l-royal)}
.qlt-cta{text-align:center;color:#fff;padding:clamp(56px,7vw,96px) 0;background:radial-gradient(700px 400px at 100% 0%,#C99A2E40 0%,transparent 60%),linear-gradient(160deg,#0A1660,#07104F)}
.qlt-cta__in{max-width:760px}
.qlt-cta h2{color:#fff;font-size:clamp(1.9rem,4vw,3rem);margin-bottom:.4em}
.qlt-cta p{color:#D6DEFA;font-size:1.06rem;margin:0 auto 26px;max-width:60ch}
.qlt-cta .od-hero__ctas{justify-content:center}

/* responsive */
@media (max-width:1100px){
  .qlt-path{grid-template-columns:repeat(3,minmax(0,1fr));row-gap:22px}.qlt-path:before{display:none}
  .qlt-idi{grid-template-columns:repeat(3,minmax(0,1fr))}
  .qlt-ms ol{grid-template-columns:repeat(5,minmax(0,1fr));min-height:0;row-gap:20px}.qlt-ms li.is-dn{padding-top:0}.qlt-ms__route{display:none}
  .qlt-val ul{grid-template-columns:1fr 1fr}
  .qlt-stairs{grid-template-columns:repeat(4,minmax(0,1fr));min-height:0}.qlt-stairs li{height:auto;border-radius:14px}
}
@media (max-width:900px){
  .qlt-hero__in,.qlt-why,.qlt-cap,.qlt-sel,.qlt-scr,.qlt-fun,.qlt-val,.qlt-proc,.qlt-fgd,.qlt-ed,.qlt-mod,.qlt-qa,.qlt-del,.qlt-htr,.qlt-team{grid-template-columns:1fr}
  .qlt-hv{max-width:600px;margin:0 auto;width:100%}
  .qlt-rec,.qlt-aud{grid-template-columns:1fr}
  .qlt-cap__nav{display:flex;overflow-x:auto;border-left:0;border-bottom:2px solid var(--l-line);gap:0;scrollbar-width:none}
  .qlt-cap__nav li{flex:none}
  .qlt-cap__nav button{margin:0 0 -2px;border-left:0;border-bottom:2px solid transparent;white-space:nowrap}
  .qlt-cap__nav button.is-on{border-bottom-color:var(--l-sand)}
  .qlt-pil{grid-template-columns:1fr 1fr}.qlt-pil li{padding:18px!important;border-right:0!important}
}
@media (max-width:640px){
  .qlt-hv__chain li{font-size:.56rem}
  .qlt-strip{gap:8px 16px}.qlt-strip li{font-size:.84rem}
  .qlt-path{grid-template-columns:1fr 1fr}
  .qlt-cap__art{float:none;width:100%;margin:0 0 12px}
  .qlt-idi{grid-template-columns:1fr}
  .qlt-ms ol{grid-template-columns:1fr 1fr}
  .qlt-val ul,.qlt-sqc ul,.qlt-pil,.qlt-team__r,.qlt-team__s{grid-template-columns:1fr}
  .qlt-days{grid-template-columns:repeat(3,1fr);row-gap:12px}.qlt-days:before{display:none}
  .qlt-ring span{font-size:.68rem;padding:5px 8px}
  .qlt-mod__ladder li{margin-left:calc(var(--i)*8px);font-size:.92rem}
  .qlt-stairs{grid-template-columns:1fr 1fr}
  .qlt-qa__stack li{width:100%!important;font-size:.88rem}
  .qlt-guide{padding-left:clamp(24px,4vw,44px)}.qlt-guide__q{display:none}
  .qlt-hero .od-hero__ctas .btn,.qlt-cta .od-hero__ctas .btn{width:100%}
}
@media (prefers-reduced-motion:reduce){
  .qlt *,.qlt *:before,.qlt *:after{animation:none!important;transition:none!important}
  .qlt-path li,.qlt-fun__bars li,.qlt-ms li,.qlt-ring span{opacity:1!important;transform:none!important}
  .qlt-path:before,.qlt-days:before{transform:none!important}
}

/* ===== Reporting & Insights (ri-) — site palette, terracotta accent ===== */
.ri{--ri-ink:#07104F;--ri-royal:#0B22A8;--ri-bright:#1E5BFF;--ri-teal:#0E9C88;--ri-gold:#C99A2E;--ri-terra:#C2603F;--ri-terra2:#F4DED5;--ri-paper:#F5F7FB;--ri-warm:#F7F5F1;--ri-line:#DDE2EC;--ri-muted:#525C78;
  --od-navy:#07104F;--od-blue:#1E5BFF;--od-royal:#0B22A8;--od-sky:#E8EEFF;--od-teal:#0E9C88;--od-teal-soft:#E3F5F2;--od-line:#DDE2EC;--od-muted:#525C78;--od-paper:#F5F7FB}
.ri .rc-kicker{color:var(--ri-terra)}
.ri .rc-head--light .rc-kicker{color:#F2B9A4}
.ri-sec--soft{background:var(--ri-warm)}
.ri-lead{font:600 clamp(1.08rem,1.6vw,1.3rem)/1.5 var(--display);color:var(--ri-ink);margin:0 0 14px}
.ri .od-muted a,.ri-note a{color:var(--ri-royal);font-weight:600}
.ri-h3{font:800 clamp(1.18rem,1.8vw,1.45rem)/1.25 var(--display);color:var(--ri-ink);margin:0 0 10px;letter-spacing:-.01em}
.ri-h3--c{text-align:center;margin:clamp(40px,5vw,56px) 0 18px}
.ri-tag{display:inline-flex;align-items:center;gap:6px;padding:4px 10px;border-radius:999px;background:#fff;border:1px dashed #C9CFDE;font:700 .68rem var(--body);letter-spacing:.08em;text-transform:uppercase;color:var(--ri-muted)}
.ri-tag--light{background:#ffffff10;border-color:#ffffff40;color:#D5DCF5}
.ri-tag--gold{background:#FBF3E0;border-color:#E3C886;color:#7A5A12}
.ri-note{margin:14px 0 0;font-size:.9rem;color:var(--ri-muted)}

/* chips */
.ri-chips{list-style:none;margin:16px 0 0;padding:0;display:flex;flex-wrap:wrap;gap:8px}
.ri-chips li{padding:6px 12px;border-radius:999px;background:#fff;border:1px solid var(--ri-line);font:600 .82rem var(--body);color:var(--ri-ink)}
.ri-chips--soft li{background:var(--ri-paper)}
.ri-chips--line li{background:transparent}
.ri-chips--dark li{background:#ffffff0d;border-color:#ffffff26;color:#E3E8FA}

/* hero */
.ri-hero{position:relative;overflow:hidden;background:linear-gradient(180deg,#fff 0%,var(--ri-paper) 100%);padding:clamp(28px,4vw,52px) 0 clamp(24px,3vw,36px);border-bottom:1px solid var(--ri-line)}
.ri-hero::before{content:"";position:absolute;inset:0;background-image:linear-gradient(#07104F08 1px,transparent 1px),linear-gradient(90deg,#07104F08 1px,transparent 1px);background-size:40px 40px;-webkit-mask-image:radial-gradient(70% 80% at 80% 40%,#000,transparent);mask-image:radial-gradient(70% 80% at 80% 40%,#000,transparent);pointer-events:none}
.ri-hero__in{position:relative;display:grid;grid-template-columns:minmax(0,.92fr) minmax(0,1.08fr);gap:clamp(24px,4vw,56px);align-items:center}
.ri-hero__in>*{min-width:0}
.ri-eyebrow{display:inline-flex;align-items:center;gap:8px;font:700 .76rem var(--body);letter-spacing:.14em;text-transform:uppercase;color:var(--ri-terra);margin-bottom:14px}
.ri-hero h1{font-size:clamp(2.5rem,5.2vw,4.2rem);line-height:1.02;color:var(--ri-ink);margin:0 0 .22em;letter-spacing:-.025em}
.ri-hero__sub{font:700 clamp(1.18rem,2vw,1.55rem)/1.35 var(--display);color:var(--ri-royal);margin:0 0 16px}
.ri-hero__body{color:var(--ri-muted);font-size:1.03rem;line-height:1.7;max-width:58ch;margin:0 0 24px}
.ri-strip{list-style:none;margin:clamp(24px,3vw,36px) 0 0;padding:0;display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px}
.ri-strip li{display:flex;align-items:center;gap:12px;padding:14px 16px;border-radius:16px;background:#fff;border:1px solid var(--ri-line);font:700 .92rem var(--display);color:var(--ri-ink)}
.ri-strip span{flex:none;width:38px;height:38px;border-radius:11px;display:grid;place-items:center;background:var(--ri-terra2);color:var(--ri-terra)}

/* hero visual */
.ri-hv{position:relative;padding:18px 18px 14px;border-radius:26px;background:#fff;border:1px solid var(--ri-line);box-shadow:0 30px 60px -40px #07104F55}
.ri-hv__tag{position:absolute;top:-11px;right:18px;padding:3px 10px;border-radius:999px;background:#fff;border:1px dashed #C9CFDE;font:700 .64rem var(--body);letter-spacing:.08em;text-transform:uppercase;color:var(--ri-muted)}
.ri-hv__svg{display:block;width:100%;height:auto}
.ri-hv__card{fill:var(--ri-paper);stroke:var(--ri-line)}
.ri-hv__k{font:800 10px var(--body);letter-spacing:.12em;fill:var(--ri-muted)}
.ri-hv__k--w{fill:#F2B9A4}
.ri-hv__z{opacity:.45;transition:opacity .5s,transform .5s;transform-box:fill-box}
.ri-hv__z.is-on{opacity:1}
.ri-hv__cells rect{fill:var(--ri-royal)}
.ri-hv__th{fill:var(--ri-ink)}
.ri-hv__row{fill:#C9D1E3}
.ri-hv__val{fill:#AFBBD8}
.ri-hv__val--hi{fill:var(--ri-terra)}
.ri-hv__colhi{fill:none;stroke:var(--ri-terra);stroke-width:1.6;stroke-dasharray:4 4;opacity:0;transition:opacity .4s .3s}
.ri-hv__z2.is-on .ri-hv__colhi{opacity:1}
.ri-hv__bar{fill:#B9C4E2;transform-origin:bottom;transform-box:fill-box;transform:scaleY(.25);transition:transform .6s cubic-bezier(.2,.7,.2,1);transition-delay:calc(var(--i)*70ms)}
.ri-hv__z3.is-on .ri-hv__bar{transform:none}
.ri-hv__bar--hi{fill:var(--ri-royal)}
.ri-hv__trend{fill:none;stroke:var(--ri-terra);stroke-width:2.4;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:200;stroke-dashoffset:200;transition:stroke-dashoffset .9s .3s}
.ri-hv__z3.is-on .ri-hv__trend{stroke-dashoffset:0}
.ri-hv__ins{fill:var(--ri-ink)}
.ri-hv__bulb{fill:#F2B9A4}
.ri-hv__bulbl{stroke:var(--ri-ink);stroke-width:2;stroke-linecap:round}
.ri-hv__tl{fill:#ffffffd0}.ri-hv__tl--s{fill:#ffffff40}
.ri-hv__act{opacity:0;transform:translateY(6px);transition:opacity .4s,transform .4s;transform-box:fill-box}
.ri-hv__act.is-on{opacity:1;transform:none}
.ri-hv__pill{fill:var(--ri-terra)}
.ri-hv__pt{font:800 11px var(--body);fill:#fff}
.ri-hv__ln{fill:none;stroke:#C9CFDE;stroke-width:2;stroke-dasharray:5 5;transition:stroke .4s}
.ri-hv__ln.is-on{stroke:var(--ri-terra);animation:rcDash 1.4s linear infinite}
.ri-hv__ah{fill:#C9CFDE}
.ri-hv__steps{list-style:none;margin:10px 0 0;padding:0;display:flex;justify-content:space-between;gap:6px}
.ri-hv__steps li{display:flex;align-items:center;gap:6px;font:700 .72rem var(--body);letter-spacing:.06em;text-transform:uppercase;color:#9AA3BC;transition:color .3s}
.ri-hv__steps span{width:8px;height:8px;border-radius:50%;background:#D5DBE8;transition:background .3s}
.ri-hv__steps li.is-on{color:var(--ri-ink)}
.ri-hv__steps li.is-on span{background:var(--ri-terra)}

/* problem */
.ri-prob{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:clamp(24px,5vw,64px);align-items:center}
.ri-prob>*{min-width:0}
.ri-prob h2{font:800 clamp(1.9rem,3.4vw,2.7rem)/1.12 var(--display);color:var(--ri-ink);margin:8px 0 16px;letter-spacing:-.02em}
.ri-pile{display:grid;grid-template-columns:minmax(0,1.2fr) auto minmax(0,.9fr);gap:14px;align-items:center;padding:22px;border-radius:24px;background:var(--ri-warm);border:1px solid #ECE6DA}
.ri-pile__in{display:flex;flex-wrap:wrap;gap:7px;transform:rotate(-2deg)}
.ri-pile__in span{padding:8px 11px;border-radius:9px;background:#fff;border:1px solid var(--ri-line);font:600 .8rem var(--body);color:var(--ri-muted);box-shadow:0 6px 12px -10px #07104F66;transform:rotate(calc((var(--i) - 3.5) * 1.6deg))}
.ri-pile__arrow{color:var(--ri-terra)}
.ri-pile__out{display:flex;flex-direction:column;gap:6px;padding:18px;border-radius:18px;background:var(--ri-ink);color:#fff}
.ri-pile__out .rc-ico,.ri-pile__out svg{color:#F2B9A4}
.ri-pile__out strong{font:800 1.08rem var(--display)}
.ri-pile__out em{font-style:normal;font-size:.84rem;color:#C9D3F5}

.ri-flow4{list-style:none;margin:clamp(40px,5vw,60px) 0 0;padding:0;display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:18px;position:relative}
.ri-flow4::before{content:"";position:absolute;left:6%;right:6%;top:46px;height:2px;background:repeating-linear-gradient(90deg,var(--ri-terra) 0 8px,transparent 8px 14px);opacity:.5}
.ri-flow4 li{position:relative;padding:22px 20px;border-radius:20px;background:#fff;border:1px solid var(--ri-line);transition:transform .3s,box-shadow .3s,border-color .3s}
.ri-flow4 li:hover{transform:translateY(-4px);border-color:#E9C2B3;box-shadow:0 20px 40px -28px #07104F55}
.ri-flow4 li:last-child{background:var(--ri-ink);border-color:var(--ri-ink)}
.ri-flow4 li:last-child h3{color:#fff}.ri-flow4 li:last-child p{color:#C9D3F5}
.ri-flow4__n{position:absolute;top:18px;right:18px;font:800 .8rem var(--display);color:#B5BDD2}
.ri-flow4__ic{position:relative;z-index:1;display:grid;place-items:center;width:48px;height:48px;border-radius:14px;background:var(--ri-terra2);color:var(--ri-terra);margin-bottom:14px;box-shadow:0 0 0 6px #fff}
.ri-flow4 li:last-child .ri-flow4__ic{background:var(--ri-terra);color:#fff;box-shadow:0 0 0 6px var(--ri-ink)}
.ri-flow4 h3{font:800 1.12rem var(--display);color:var(--ri-ink);margin:0 0 6px}
.ri-flow4 p{margin:0;font-size:.92rem;line-height:1.6;color:var(--ri-muted)}
.ri-journey{display:flex;flex-wrap:wrap;justify-content:center;gap:6px 0;margin:28px 0 0}
.ri-journey span{position:relative;padding:7px 22px 7px 14px;font:700 .78rem var(--body);color:var(--ri-ink);background:#E6EAF3;clip-path:polygon(0 0,calc(100% - 10px) 0,100% 50%,calc(100% - 10px) 100%,0 100%,10px 50%);margin-left:-4px}
.ri-journey span:first-child{clip-path:polygon(0 0,calc(100% - 10px) 0,100% 50%,calc(100% - 10px) 100%,0 100%);margin-left:0}
.ri-journey span.is-end{background:var(--ri-terra);color:#fff}
.ri-vs{display:grid;grid-template-columns:minmax(0,1fr) auto minmax(0,1fr);gap:16px;align-items:stretch;margin-top:clamp(32px,4vw,48px)}
.ri-vs>div{padding:20px 22px;border-radius:18px;border:1px solid var(--ri-line);background:#fff}
.ri-vs>div.is-here{border-color:var(--ri-terra);background:#FFF9F6}
.ri-vs__k{display:block;font:800 1rem var(--display);color:var(--ri-ink);margin-bottom:6px}
.ri-vs p{margin:0 0 10px;font-size:.92rem;color:var(--ri-muted)}
.ri-vs a{font:700 .86rem var(--body);color:var(--ri-royal)}
.ri-vs__mid{align-self:center;color:var(--ri-terra)}
.ri-vs__here{display:inline-block;padding:3px 10px;border-radius:999px;background:var(--ri-terra);color:#fff;font:700 .72rem var(--body)}

/* tabs */
.ri-tabs{border-radius:24px;background:#fff;border:1px solid var(--ri-line);overflow:hidden;margin-bottom:clamp(36px,5vw,56px)}
.ri-tabs__list{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));border-bottom:1px solid var(--ri-line)}
.ri-tabs__list button{display:flex;align-items:center;gap:10px;padding:16px 20px;border:0;background:transparent;font:700 .95rem var(--display);color:var(--ri-muted);cursor:pointer;text-align:left;border-bottom:3px solid transparent;transition:color .2s,background .2s,border-color .2s}
.ri-tabs__list button+button{border-left:1px solid var(--ri-line)}
.ri-tabs__list button:hover{background:var(--ri-paper);color:var(--ri-ink)}
.ri-tabs__list button.is-on{color:var(--ri-ink);border-bottom-color:var(--ri-terra);background:#FFF9F6}
.ri-tabs__list button:focus-visible{outline:2px solid var(--ri-royal);outline-offset:-3px}
.ri-tabs__panel{display:grid;grid-template-columns:minmax(0,1.15fr) minmax(0,.85fr);gap:clamp(20px,3vw,40px);padding:clamp(22px,3vw,34px);animation:riIn .4s ease both}
.ri-tabs__panel>*{min-width:0}
.ri-tabs__copy h4{font:800 1.2rem var(--display);color:var(--ri-ink);margin:0 0 6px}
.ri-tabs__copy>p{margin:0;color:var(--ri-muted)}
@keyframes riIn{from{opacity:0;transform:translateY(8px)}to{opacity:1;transform:none}}
.ri-tv{border-radius:18px;background:var(--ri-paper);border:1px solid var(--ri-line);padding:18px;display:flex;flex-direction:column;justify-content:center;gap:10px}
.ri-tv em{font-style:normal;font:700 .66rem var(--body);letter-spacing:.08em;text-transform:uppercase;color:#9AA3BC;text-align:center}
.ri-tv--tab{flex-direction:row;align-items:center;gap:8px}
.ri-mt{flex:1;min-width:0;display:flex;flex-direction:column;gap:6px}
.ri-mt span{font:700 .7rem var(--body);color:var(--ri-muted);text-align:center}
.ri-mt svg{width:100%;height:auto;background:#fff;border-radius:10px;border:1px solid var(--ri-line)}
.ri-mt .h{fill:var(--ri-ink)}.ri-mt .r{fill:#C9D1E3}.ri-mt .v{fill:#AFBBD8}.ri-mt .hi{fill:var(--ri-terra)}
.ri-tv--fun>div{width:var(--w);margin:0 auto;padding:9px 12px;border-radius:10px;background:linear-gradient(90deg,var(--ri-royal),#3155E0);color:#fff;font:700 .8rem var(--body);text-align:center;opacity:calc(1 - var(--i)*.1)}
.ri-tv--drv .ri-ch{max-width:280px;margin:0 auto}

/* abstract charts */
.ri-ch{display:block;width:100%;height:auto}
.ri-ch .a{fill:var(--ri-royal)}.ri-ch .b{fill:#C9D1E3}.ri-ch .c{fill:var(--ri-terra)}
.ri-ch .o{opacity:.75}
.ri-ch .ring{fill:none;stroke-width:12}.ri-ch .ring.a{stroke:var(--ri-royal)}.ri-ch .ring.b{stroke:#DCE2EE}.ri-ch .ring.c{stroke:var(--ri-terra)}
.ri-ch .ln{fill:none;stroke-width:2.6;stroke-linecap:round;stroke-linejoin:round}
.ri-ch .ln.a{stroke:var(--ri-royal)}.ri-ch .ln.c{stroke:var(--ri-terra)}.ri-ch .ln.d{stroke:var(--ri-terra);stroke-dasharray:4 4;stroke-width:1.6}
.ri-ch .ax{fill:none;stroke:#B5BDD2;stroke-width:1.2}.ri-ch .ax.d{stroke-dasharray:3 3}
.ri-ch .area{fill:#1E5BFF1f;stroke:none}
.ri-ch .card{fill:#fff;stroke:#DDE2EC}

/* qualitative */
.ri-qual{display:grid;grid-template-columns:minmax(0,1.1fr) minmax(0,.9fr);gap:clamp(24px,4vw,48px);align-items:start;margin-bottom:clamp(36px,5vw,56px)}
.ri-qual>*{min-width:0}
.ri-said{list-style:none;margin:0;padding:0;display:flex;flex-direction:column;gap:10px}
.ri-said li{display:flex;gap:14px;align-items:center;padding:16px 18px;border-radius:16px;background:#fff;border:1px solid var(--ri-line);position:relative}
.ri-said li:not(.ri-said__note)+li:not(.ri-said__note)::before{content:"";position:absolute;left:37px;top:-11px;width:2px;height:10px;background:var(--ri-terra)}
.ri-said li>span{flex:none;width:40px;height:40px;border-radius:12px;display:grid;place-items:center;background:var(--ri-terra2);color:var(--ri-terra)}
.ri-said li:nth-child(3)>span{background:var(--ri-ink);color:#F2B9A4}
.ri-said strong{display:block;font:800 1rem var(--display);color:var(--ri-ink)}
.ri-said em{display:block;font-style:normal;font-size:.86rem;color:var(--ri-muted)}
.ri-said__note{background:transparent!important;border-style:dashed!important;font-size:.86rem;color:var(--ri-muted)}

/* open-ends */
.ri-oewrap{padding:clamp(22px,3vw,34px);border-radius:24px;background:#fff;border:1px solid var(--ri-line);margin-bottom:clamp(36px,5vw,56px)}
.ri-oewrap__head{max-width:860px}
.ri-oe{margin-top:22px}
.ri-oe__line{list-style:none;margin:0 0 18px;padding:0;display:grid;grid-template-columns:repeat(7,minmax(0,1fr));gap:6px;counter-reset:none}
.ri-oe__line li{position:relative;display:flex;flex-direction:column;gap:6px;padding:12px 10px;border-radius:12px;background:var(--ri-paper);font:700 .8rem/1.3 var(--body);color:var(--ri-ink);opacity:.4;transform:translateY(6px);transition:opacity .4s,transform .4s,background .4s;transition-delay:calc(var(--i)*90ms)}
.ri-oe.is-in .ri-oe__line li{opacity:1;transform:none}
.ri-oe__line li:last-child{background:var(--ri-ink);color:#fff}
.ri-oe__line span{font:800 .7rem var(--display);color:var(--ri-terra)}
.ri-oe__demo{position:relative;display:grid;grid-template-columns:minmax(0,1.3fr) auto minmax(0,.9fr) auto minmax(0,1fr);gap:12px;align-items:center;padding:22px 18px 18px;border-radius:18px;border:1px dashed #C9CFDE;background:var(--ri-warm)}
.ri-oe__demo>.ri-tag{position:absolute;top:-11px;left:16px}
.ri-oe__col{display:flex;flex-direction:column;gap:8px;min-width:0}
.ri-oe__h{font:800 .68rem var(--body);letter-spacing:.12em;text-transform:uppercase;color:var(--ri-muted)}
.ri-oe__q{margin:0;padding:9px 12px;border-radius:12px 12px 12px 4px;background:#fff;border:1px solid var(--ri-line);font-size:.84rem;font-style:italic;color:var(--ri-ink)}
.ri-oe__arrow{color:var(--ri-terra)}
.ri-oe__code{padding:9px 12px;border-radius:10px;font:700 .8rem var(--body);border:1px solid}
.ri-oe__code--a{background:#E8EEFF;border-color:#C9D6FB;color:var(--ri-royal)}
.ri-oe__code--b{background:#E3F5F2;border-color:#B6E3DA;color:#0B7A6A}
.ri-oe__code--c{background:var(--ri-terra2);border-color:#EBC2B2;color:#9A4528}
.ri-oe__th{padding:10px 12px;border-radius:12px;background:#fff;border:1px solid var(--ri-line);border-left:4px solid}
.ri-oe__th--a{border-left-color:var(--ri-royal)}.ri-oe__th--b{border-left-color:var(--ri-teal)}.ri-oe__th--c{border-left-color:var(--ri-terra)}
.ri-oe__th strong{display:block;font:800 .88rem var(--display);color:var(--ri-ink)}
.ri-oe__th span{display:flex;gap:4px;margin-top:6px}
.ri-oe__th i{width:10px;height:10px;border-radius:50%;background:#AFBBD8}

/* segmentation */
.ri-segwrap{display:grid;grid-template-columns:minmax(0,.9fr) minmax(0,1.1fr);gap:clamp(24px,4vw,48px);align-items:center;margin-bottom:clamp(36px,5vw,56px)}
.ri-segwrap>*{min-width:0}
.ri-seg{position:relative;padding:22px;border-radius:22px;background:#fff;border:1px solid var(--ri-line)}
.ri-seg>.ri-tag{margin-top:14px}
.ri-seg__grid{display:grid;grid-template-columns:auto repeat(4,minmax(0,1fr));gap:10px 10px;align-items:center}
.ri-seg__grid strong{font:800 .78rem/1.25 var(--display);color:var(--ri-ink);text-align:center;padding:8px 4px;border-radius:10px;background:var(--ri-paper)}
.ri-seg__grid strong.is-total{background:var(--ri-ink);color:#fff}
.ri-seg__grid em{font-style:normal;font:700 .78rem var(--body);color:var(--ri-muted);white-space:nowrap}
.ri-seg__cell{display:block;height:14px;border-radius:7px;background:var(--ri-paper);overflow:hidden}
.ri-seg__cell i{display:block;height:100%;width:0;border-radius:7px;background:var(--ri-terra);transition:width .9s cubic-bezier(.2,.7,.2,1)}
.ri-seg__cell.is-total i{background:var(--ri-ink)}
.ri-seg.is-in .ri-seg__cell i{width:var(--w)}

/* trends */
.ri-trendwrap{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:clamp(24px,4vw,48px);align-items:center}
.ri-trendwrap>*{min-width:0}
.ri-trend{padding:20px;border-radius:22px;background:#fff;border:1px solid var(--ri-line)}
.ri-trend svg{display:block;width:100%;height:auto;overflow:visible}
.ri-trend__g{stroke:#E5E9F2;stroke-width:1}
.ri-trend__x{font:700 10px var(--body);fill:var(--ri-muted)}
.ri-trend__l{fill:none;stroke-width:3;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:300;stroke-dashoffset:300;transition:stroke-dashoffset 1.2s ease}
.ri-trend.is-in .ri-trend__l{stroke-dashoffset:0}
.ri-trend__l.a{stroke:var(--ri-royal)}.ri-trend__l.c{stroke:var(--ri-terra)}.ri-trend__l.b{stroke:#9AA3BC;stroke-dasharray:6 5;stroke-dashoffset:0}
.ri-trend__lab{font:700 9.5px var(--body);fill:var(--ri-ink)}
.ri-trend>.ri-tag{margin-top:10px}

/* process */
.ri-proc{display:grid;grid-template-columns:minmax(0,.9fr) minmax(0,1.1fr);gap:clamp(20px,3vw,40px);align-items:start}
.ri-proc>*{min-width:0}
.ri-proc__rail{list-style:none;margin:0;padding:0;display:flex;flex-direction:column;gap:6px;position:relative}
.ri-proc__rail::before{content:"";position:absolute;left:27px;top:20px;bottom:20px;width:2px;background:var(--ri-line)}
.ri-proc__rail button{position:relative;display:flex;align-items:center;gap:14px;width:100%;padding:10px 14px 10px 8px;border:1px solid transparent;border-radius:14px;background:transparent;text-align:left;cursor:pointer;transition:background .2s,border-color .2s}
.ri-proc__rail button:hover{background:var(--ri-paper)}
.ri-proc__rail button:focus-visible{outline:2px solid var(--ri-royal);outline-offset:1px}
.ri-proc__n{position:relative;z-index:1;flex:none;width:40px;height:40px;border-radius:12px;display:grid;place-items:center;background:#fff;border:1.5px solid var(--ri-line);font:800 .82rem var(--display);color:var(--ri-muted);transition:background .25s,color .25s,border-color .25s}
.ri-proc__t{font:700 .98rem var(--display);color:var(--ri-muted);transition:color .25s}
.ri-proc__rail li.is-done .ri-proc__n{border-color:var(--ri-terra);color:var(--ri-terra)}
.ri-proc__rail li.is-on button{background:#fff;border-color:var(--ri-line);box-shadow:0 12px 24px -20px #07104F66}
.ri-proc__rail li.is-on .ri-proc__n{background:var(--ri-terra);border-color:var(--ri-terra);color:#fff}
.ri-proc__rail li.is-on .ri-proc__t{color:var(--ri-ink)}
.ri-proc__m{display:none}
.ri-proc__panel{position:sticky;top:120px;padding:clamp(24px,3vw,36px);border-radius:24px;background:var(--ri-ink);color:#fff;animation:riIn .35s ease both}
.ri-proc__ic{display:grid;place-items:center;width:54px;height:54px;border-radius:16px;background:#ffffff14;color:#F2B9A4;margin-bottom:16px}
.ri-proc__k{display:block;font:700 .72rem var(--body);letter-spacing:.14em;text-transform:uppercase;color:#F2B9A4;margin-bottom:6px}
.ri-proc__panel strong{display:block;font:800 clamp(1.3rem,2vw,1.6rem)/1.2 var(--display);margin-bottom:8px}
.ri-proc__panel>p{margin:0 0 18px;color:#C9D3F5}
.ri-proc__panel ul{list-style:none;margin:0;padding:0;display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px}
.ri-proc__panel li{display:flex;align-items:center;gap:8px;padding:9px 12px;border-radius:10px;background:#ffffff0d;border:1px solid #ffffff1c;font:600 .86rem var(--body);animation:riIn .4s ease both;animation-delay:calc(var(--i)*40ms)}
.ri-proc__panel li svg{color:#6EE0CE;flex:none}
.ri-proc__nav{display:flex;align-items:center;gap:12px;margin-top:22px}
.ri-proc__nav button{width:38px;height:38px;border-radius:50%;border:1px solid #ffffff40;background:transparent;color:#fff;font-size:1.2rem;cursor:pointer}
.ri-proc__nav button:hover{background:#ffffff1a}
.ri-proc__nav button:focus-visible{outline:2px solid #F2B9A4;outline-offset:2px}
.ri-proc__nav i{flex:1;height:4px;border-radius:2px;background:#ffffff1f;position:relative;overflow:hidden}
.ri-proc__nav i::after{content:"";position:absolute;inset:0;transform-origin:left;transform:scaleX(var(--p));background:var(--ri-terra);transition:transform .4s}

/* quality chain */
.ri-qa{display:grid;grid-template-columns:minmax(0,.7fr) minmax(0,1.3fr);gap:clamp(20px,3vw,40px);align-items:center;margin-top:clamp(40px,5vw,60px);padding:clamp(22px,3vw,32px);border-radius:24px;background:var(--ri-warm);border:1px solid #ECE6DA}
.ri-qa>*{min-width:0}
.ri-qa__chain{list-style:none;margin:0;padding:0;display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:10px}
.ri-qa__chain li{display:flex;align-items:center;gap:10px;padding:12px;border-radius:12px;background:#fff;border:1px solid var(--ri-line);font:700 .84rem/1.25 var(--body);color:var(--ri-ink)}
.ri-qa__chain span{flex:none;width:26px;height:26px;border-radius:50%;display:grid;place-items:center;background:var(--ri-ink);color:#fff;font:800 .74rem var(--display)}
.ri-qa__chain li:last-child span{background:var(--ri-terra)}

/* ink section */
.ri-sec--ink{background:radial-gradient(700px 360px at 90% 0%,#1E3BB866 0%,transparent 60%),radial-gradient(520px 320px at 0% 100%,#C2603F2a 0%,transparent 70%),linear-gradient(165deg,#0A1660,#07104F);color:#fff}
.ri .ri-sec--ink .rc-head--light h2{color:#fff}
.ri-viz{display:grid;grid-template-columns:minmax(0,.75fr) minmax(0,1.25fr);gap:clamp(24px,4vw,48px);align-items:center}
.ri-viz>*{min-width:0}
.ri-viz h3,.ri-exec h3,.ri-rec h3{font:800 clamp(1.3rem,2.2vw,1.75rem)/1.2 var(--display);color:#fff;margin:0 0 12px;letter-spacing:-.01em}
.ri-viz p,.ri-exec p,.ri-rec>p{color:#C9D3F5;margin:0 0 16px}
.ri-gal{list-style:none;margin:0;padding:0;display:grid;grid-template-columns:repeat(7,minmax(0,1fr));gap:10px}
.ri-gal li{display:flex;flex-direction:column;gap:6px;padding:10px 8px 9px;border-radius:14px;background:#fff;transition:transform .3s}
.ri-gal li:hover{transform:translateY(-4px) rotate(-1deg)}
.ri-gal span{font:700 .7rem/1.25 var(--body);color:var(--ri-ink);text-align:center}
.ri-oip{position:relative;margin-top:clamp(44px,6vw,72px);padding-top:16px}
.ri-oip>.ri-tag{position:absolute;top:0;left:0;z-index:1}
.ri-oip ol{list-style:none;margin:0;padding:0;display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:0;border-radius:24px;overflow:hidden;border:1px solid #ffffff22}
.ri-oip li{position:relative;padding:28px 26px 26px;background:#ffffff08}
.ri-oip li+li{border-left:1px solid #ffffff22}
.ri-oip li:nth-child(3){background:#C2603F26}
.ri-oip li+li::before{content:"";position:absolute;left:-12px;top:34px;width:22px;height:22px;border-radius:50%;background:var(--ri-terra);box-shadow:0 0 0 4px #0A1660;z-index:1}
.ri-oip__n{font:800 .8rem var(--display);color:#F2B9A4;letter-spacing:.1em}
.ri-oip h3{font:800 1.3rem var(--display);color:#fff;margin:6px 0 4px}
.ri-oip strong{display:block;font:600 .95rem var(--body);color:#E3E8FA;margin-bottom:14px}
.ri-oip p{margin:0;padding:14px;border-radius:12px;background:#ffffff10;border-left:3px solid var(--ri-terra);color:#fff;font-size:.92rem;line-height:1.6}
.ri-exec{display:grid;grid-template-columns:minmax(0,.8fr) minmax(0,1.2fr);gap:clamp(24px,4vw,48px);align-items:center;margin-top:clamp(48px,6vw,80px)}
.ri-exec>*{min-width:0}
.ri-exec__vs{display:flex;flex-direction:column;gap:8px}
.ri-exec__vs span{display:flex;align-items:center;gap:8px;font:700 .86rem var(--body);color:#E3E8FA}
.ri-exec__vs svg{color:#F2B9A4}
.ri-doc{border-radius:20px;background:#fff;color:var(--ri-ink);overflow:hidden;box-shadow:0 30px 60px -30px #000a;transform:rotate(-.6deg)}
.ri-doc__bar{display:flex;align-items:center;gap:6px;padding:10px 16px;background:var(--ri-paper);border-bottom:1px solid var(--ri-line)}
.ri-doc__bar i{width:9px;height:9px;border-radius:50%;background:#D5DBE8}
.ri-doc__bar span{margin-left:8px;font:800 .72rem var(--body);letter-spacing:.12em;text-transform:uppercase;color:var(--ri-muted)}
.ri-doc__grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:0}
.ri-doc__grid div{padding:16px 16px 18px;border-right:1px solid var(--ri-line);border-bottom:1px solid var(--ri-line)}
.ri-doc__grid div:nth-child(3n){border-right:0}
.ri-doc__grid div:nth-child(n+4){border-bottom:0}
.ri-doc__grid div:nth-child(6){background:#FFF6F2}
.ri-doc__grid h4{font:800 .92rem var(--display);color:var(--ri-ink);margin:0 0 6px;padding-top:8px;border-top:3px solid var(--ri-terra);display:inline-block}
.ri-doc__grid p{margin:0;font-size:.82rem;line-height:1.55;color:var(--ri-muted)}
.ri-rec{margin-top:clamp(48px,6vw,80px);padding:clamp(22px,3vw,34px);border-radius:24px;background:#ffffff08;border:1px solid #ffffff1f}
.ri-rec>p{max-width:72ch}
.ri-rec__lanes{list-style:none;margin:0 0 18px;padding:0;display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:10px}
.ri-rec__lanes li{display:flex;flex-direction:column;gap:4px;padding:16px 18px;border-radius:14px;background:#ffffff0d;border:1px solid #ffffff22;clip-path:polygon(0 0,calc(100% - 14px) 0,100% 50%,calc(100% - 14px) 100%,0 100%)}
.ri-rec__lanes li:nth-child(3){background:#C2603F33;border-color:#C2603F80}
.ri-rec__lanes svg{color:#F2B9A4;margin-bottom:4px}
.ri-rec__lanes strong{font:800 1rem var(--display);color:#fff}
.ri-rec__lanes em{font-style:normal;font-size:.86rem;color:#C9D3F5;padding-right:14px}

/* formats */
.ri-fmt{list-style:none;margin:0;padding:0;display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:14px}
.ri-fmt li{display:flex;flex-direction:column;gap:12px;padding:18px;border-radius:20px;background:#fff;border:1px solid var(--ri-line);transition:transform .3s,box-shadow .3s,border-color .3s}
.ri-fmt li:hover{transform:translateY(-4px);border-color:#E9C2B3;box-shadow:0 20px 40px -28px #07104F55}
.ri-fmt li.is-wide{grid-column:span 2;flex-direction:row;align-items:center;background:var(--ri-warm);border-color:#ECE6DA}
.ri-fmt li.is-wide .ri-fa{max-width:180px}
.ri-fmt h3{font:800 1.02rem var(--display);color:var(--ri-ink);margin:0 0 4px}
.ri-fmt p{margin:0;font-size:.86rem;line-height:1.55;color:var(--ri-muted)}
.ri-fa{width:100%;max-width:150px;height:auto;flex:none}
.ri-fa .pg{fill:var(--ri-paper);stroke:var(--ri-line)}
.ri-fa .tx{fill:#C9D1E3}.ri-fa .tx2{fill:var(--ri-ink)}.ri-fa .ac{fill:var(--ri-terra)}.ri-fa .ac2{fill:var(--ri-royal)}
.ri-fa .ln{fill:none;stroke:var(--ri-terra);stroke-width:2.4;stroke-linecap:round;stroke-linejoin:round}
.ri-meth{display:grid;grid-template-columns:minmax(0,.8fr) minmax(0,1.2fr);gap:clamp(24px,4vw,48px);align-items:center;margin-top:clamp(40px,5vw,60px);padding:clamp(22px,3vw,34px);border-radius:24px;background:var(--ri-paper);border:1px solid var(--ri-line)}
.ri-meth>*{min-width:0}
.ri-meth blockquote{margin:0;padding:0 0 0 16px;border-left:3px solid var(--ri-terra);font:600 1.02rem/1.6 var(--display);color:var(--ri-ink)}
.ri-meth__list{list-style:none;margin:0;padding:0;display:flex;flex-wrap:wrap;gap:8px}
.ri-meth__list a,.ri-meth__list span{display:inline-flex;align-items:center;gap:6px;padding:8px 13px;border-radius:999px;font:700 .84rem var(--body);border:1px solid var(--ri-line);background:#fff;color:var(--ri-ink);text-decoration:none}
.ri-meth__list a{border-color:#C9D6FB;color:var(--ri-royal);transition:background .2s,color .2s}
.ri-meth__list a:hover{background:var(--ri-royal);color:#fff}
.ri-meth__list a:focus-visible{outline:2px solid var(--ri-royal);outline-offset:2px}

/* why */
.ri-why{list-style:none;margin:0;padding:0;display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:0;border-top:1px solid #E4DED2;border-left:1px solid #E4DED2}
.ri-why li{position:relative;padding:26px 24px;border-right:1px solid #E4DED2;border-bottom:1px solid #E4DED2;background:transparent;transition:background .3s}
.ri-why li:hover{background:#fff}
.ri-why__n{position:absolute;top:22px;right:22px;font:800 .8rem var(--display);color:#C2603F99}
.ri-why__ic{display:grid;place-items:center;width:42px;height:42px;border-radius:12px;background:var(--ri-ink);color:#F2B9A4;margin-bottom:14px}
.ri-why h3{font:800 1.08rem var(--display);color:var(--ri-ink);margin:0 0 6px}
.ri-why p{margin:0;font-size:.9rem;line-height:1.6;color:var(--ri-muted)}
.ri-team{display:grid;grid-template-columns:minmax(0,1.3fr) minmax(0,.7fr);gap:16px;margin-top:clamp(36px,5vw,52px)}
.ri-team>*{min-width:0}
.ri-team>div{padding:22px 24px;border-radius:20px;background:#fff;border:1px solid var(--ri-line)}
.ri-team h3{font:800 1.2rem var(--display);color:var(--ri-ink);margin:0 0 6px}
.ri-team__r{list-style:none;margin:14px 0 0;padding:0;display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px}
.ri-team__r li{display:flex;align-items:center;gap:8px;padding:10px 12px;border-radius:10px;background:var(--ri-paper);font:600 .88rem var(--body);color:var(--ri-ink)}
.ri-team__r svg{color:var(--ri-terra);flex:none}
.ri-team__env{display:flex;flex-direction:column;gap:8px;background:var(--ri-ink)!important;border-color:var(--ri-ink)!important;color:#fff}
.ri-team__env svg{color:#F2B9A4}
.ri-team__env strong{font:800 1.02rem var(--display)}
.ri-team__env p{margin:0;color:#C9D3F5;font-size:.92rem}
.ri-ex{margin-top:clamp(40px,5vw,60px);padding:clamp(22px,3vw,32px);border-radius:24px;background:#fff;border:1px dashed #D9C08A}
.ri-ex__head{display:flex;flex-wrap:wrap;align-items:center;gap:10px 16px;margin-bottom:18px}
.ri-ex__head h3{font:800 1.2rem var(--display);color:var(--ri-ink);margin:0}
.ri-ex ol{list-style:none;margin:0;padding:0;display:grid;grid-template-columns:repeat(6,minmax(0,1fr));gap:10px}
.ri-ex li{position:relative;display:flex;flex-direction:column;gap:6px;padding:14px;border-radius:14px;background:var(--ri-paper)}
.ri-ex li+li::before{content:"";position:absolute;left:-9px;top:26px;width:8px;height:2px;background:var(--ri-terra)}
.ri-ex li>span{width:34px;height:34px;border-radius:10px;display:grid;place-items:center;background:#fff;color:var(--ri-terra);border:1px solid var(--ri-line)}
.ri-ex li:last-child{background:var(--ri-ink)}
.ri-ex li:last-child strong{color:#fff}.ri-ex li:last-child em{color:#C9D3F5}
.ri-ex strong{font:800 .9rem/1.25 var(--display);color:var(--ri-ink)}
.ri-ex em{font-style:normal;font-size:.8rem;line-height:1.5;color:var(--ri-muted)}

/* guide + enquiry */
.ri-guidesec{padding-block:clamp(36px,4vw,56px)}
.ri-guide{display:grid;gap:8px;padding:26px 28px;border-radius:22px;background:#fff;border:1px solid var(--ri-line);border-left:5px solid var(--ri-terra);text-decoration:none;max-width:880px;margin:0 auto;transition:transform .3s,box-shadow .3s}
.ri-guide:hover{transform:translateY(-3px);box-shadow:0 20px 40px -28px #07104F55}
.ri-guide__k{font:700 .72rem var(--body);letter-spacing:.14em;text-transform:uppercase;color:var(--ri-terra)}
.ri-guide strong{font:800 clamp(1.1rem,2vw,1.45rem)/1.3 var(--display);color:var(--ri-ink)}
.ri-guide__go{display:inline-flex;align-items:center;gap:6px;font:700 .9rem var(--body);color:var(--ri-royal)}
.ri-enq{background:var(--ri-warm)}
.ri-enq__intro h2{font-size:clamp(1.8rem,3.2vw,2.5rem);letter-spacing:-.02em}
.ri-enq__ctas{display:flex;flex-wrap:wrap;gap:10px;margin:6px 0 26px}

/* responsive */
@media (max-width:1100px){
  .ri-gal{grid-template-columns:repeat(5,minmax(0,1fr))}
  .ri-ex ol{grid-template-columns:repeat(3,minmax(0,1fr))}
