  .ri-oe__line{grid-template-columns:repeat(4,minmax(0,1fr))}
  .ri-qa__chain{grid-template-columns:repeat(2,minmax(0,1fr))}
  .ri-fmt{grid-template-columns:repeat(3,minmax(0,1fr))}
  .ri-fmt li.is-wide{grid-column:span 3}
}
@media (max-width:900px){
  .ri-hero__in,.ri-prob,.ri-qual,.ri-segwrap,.ri-trendwrap,.ri-viz,.ri-exec,.ri-meth,.ri-qa,.ri-team,.ri-tabs__panel{grid-template-columns:1fr}
  .ri-strip{grid-template-columns:repeat(2,minmax(0,1fr))}
  .ri-flow4{grid-template-columns:repeat(2,minmax(0,1fr))}
  .ri-flow4::before{display:none}
  .ri-vs{grid-template-columns:1fr}
  .ri-vs__mid{justify-self:center;transform:rotate(90deg)}
  .ri-proc{grid-template-columns:1fr}
  .ri-proc__panel{display:none}
  .ri-proc__m{display:block;margin:6px 0 10px 62px}
  .ri-proc__m[hidden]{display:none}
  .ri-proc__m p{margin:0 0 10px;color:var(--ri-muted);font-size:.92rem}
  .ri-proc__m ul{list-style:none;margin:0;padding:0;display:flex;flex-wrap:wrap;gap:6px}
  .ri-proc__m li{display:inline-flex;align-items:center;gap:6px;padding:6px 10px;border-radius:999px;background:var(--ri-paper);border:1px solid var(--ri-line);font:600 .8rem var(--body);color:var(--ri-ink)}
  .ri-proc__m li svg{color:var(--ri-teal)}
  .ri-oip ol{grid-template-columns:1fr}
  .ri-oip li+li{border-left:0;border-top:1px solid #ffffff22}
  .ri-oip li+li::before{left:26px;top:-12px}
  .ri-rec__lanes{grid-template-columns:1fr}
  .ri-rec__lanes li{clip-path:none}
  .ri-why{grid-template-columns:repeat(2,minmax(0,1fr))}
  .ri-oe__demo{grid-template-columns:1fr;padding-top:30px}
  .ri-oe__arrow{justify-self:center;transform:rotate(90deg)}
}
@media (max-width:640px){
  .ri-strip{grid-template-columns:1fr 1fr;gap:8px}
  .ri-strip li{padding:10px 11px;font-size:.82rem;gap:9px}
  .ri-strip span{width:32px;height:32px}
  .ri-hv{padding:14px 10px 10px}
  .ri-hv__steps li{font-size:.62rem;gap:4px}
  .ri-pile{grid-template-columns:1fr;justify-items:center}
  .ri-pile__in{justify-content:center}
  .ri-pile__arrow{transform:rotate(90deg)}
  .ri-pile__out{width:100%}
  .ri-flow4{grid-template-columns:1fr}
  .ri-journey{justify-content:flex-start}
  .ri-tabs__list{grid-template-columns:1fr}
  .ri-tabs__list button+button{border-left:0;border-top:1px solid var(--ri-line)}
  .ri-tabs__list button{border-bottom:0;border-left:3px solid transparent!important}
  .ri-tabs__list button.is-on{border-left-color:var(--ri-terra)!important}
  .ri-tv--tab{flex-direction:column}
  .ri-mt{width:100%;max-width:240px}
  .ri-oe__line{grid-template-columns:repeat(2,minmax(0,1fr))}
  .ri-oe__line li:last-child{grid-column:1/-1}
  .ri-seg{padding:16px 12px}
  .ri-seg__grid{gap:8px 6px}
  .ri-seg__grid strong{font-size:.66rem;padding:6px 2px}
  .ri-seg__grid em{font-size:.68rem}
  .ri-gal{grid-template-columns:repeat(3,minmax(0,1fr));gap:8px}
  .ri-gal span{font-size:.66rem}
  .ri-doc{transform:none}
  .ri-doc__grid{grid-template-columns:1fr}
  .ri-doc__grid div{border-right:0!important;border-bottom:1px solid var(--ri-line)!important}
  .ri-doc__grid div:last-child{border-bottom:0!important}
  .ri-qa__chain{grid-template-columns:1fr}
  .ri-fmt{grid-template-columns:1fr}
  .ri-fmt li.is-wide{grid-column:auto;flex-direction:column;align-items:flex-start}
  .ri-fmt li{flex-direction:row;align-items:center}
  .ri-fa{max-width:96px}
  .ri-why{grid-template-columns:1fr}
  .ri-team__r{grid-template-columns:1fr}
  .ri-ex ol{grid-template-columns:1fr}
  .ri-proc__m{margin-left:8px}
}
@media (prefers-reduced-motion:reduce){
  .ri *,.ri *::before,.ri *::after{animation:none!important;transition-duration:.01ms!important;transition-delay:0s!important}
  .ri-hv__z{opacity:1}.ri-hv__bar{transform:none}.ri-hv__trend{stroke-dashoffset:0}.ri-hv__act{opacity:1;transform:none}
  .ri-oe__line li{opacity:1;transform:none}.ri-seg__cell i{width:var(--w)}.ri-trend__l{stroke-dashoffset:0}
}

/* ===== Leadership section — site palette (navy · royal · bright · teal) ===== */
.ldr{--lv-ink:#07104F;--lv-royal:#0B22A8;--lv-bright:#1E5BFF;--lv-sky:#8FB0FF;--lv-teal:#0E9C88;--lv-teal2:#6EE0CE;--lv-soft:#C9D3F5;--lv-mute:#9AA8D6;
  position:relative;overflow:hidden;isolation:isolate;color:#fff;padding-block:clamp(72px,9vw,128px);
  background:radial-gradient(760px 520px at 88% 8%,#1E6BFF40 0%,transparent 62%),radial-gradient(620px 420px at 0% 100%,#0E9C8826 0%,transparent 70%),linear-gradient(160deg,#0B22A8 0%,#0A1A7A 42%,#07104F 100%)}
.ldr *{box-sizing:border-box}
.ldr__in{position:relative;z-index:1}

/* background: live globe, perspective floor, flowing lines */
.ldr__bg{position:absolute;inset:0;z-index:0;pointer-events:none}
.ldr__bg::before{content:"";position:absolute;inset:0;background-image:radial-gradient(#ffffff14 1px,transparent 1.3px);background-size:24px 24px;-webkit-mask-image:linear-gradient(180deg,#000 0%,transparent 45%);mask-image:linear-gradient(180deg,#000 0%,transparent 45%)}
.ldr__globe{position:absolute;width:min(620px,48vw);aspect-ratio:1;right:-9%;top:-7%;opacity:.5;will-change:transform}
.ldr__globe .hg-canvas{display:block;width:100%;height:100%}
.ldr__floor{position:absolute;left:-10%;right:-10%;bottom:-6%;height:46%;perspective:600px;-webkit-mask-image:linear-gradient(0deg,#000 10%,transparent 90%);mask-image:linear-gradient(0deg,#000 10%,transparent 90%);opacity:.5}
.ldr__floor span{position:absolute;inset:0;transform:rotateX(68deg);transform-origin:50% 100%;
  background-image:linear-gradient(#5D86FF33 1px,transparent 1px),linear-gradient(90deg,#5D86FF33 1px,transparent 1px);background-size:64px 64px;}
@keyframes ldrFloor{to{background-position:0 64px,0 0}}
.ldr__lines{position:absolute;inset:0;width:100%;height:100%}
.ldr__lines path{fill:none;stroke:#6EE0CE;stroke-width:1.2;opacity:.28;stroke-dasharray:6 10;animation:ldrDash 20s linear infinite}
.ldr__lines .ldr__lines2{stroke:#8FB0FF;opacity:.22;animation-duration:28s}
@keyframes ldrDash{to{stroke-dashoffset:-320}}

/* reveal */
.ldr-rv{opacity:0;transform:translateY(28px);transition:opacity .8s cubic-bezier(.2,.7,.2,1) var(--d),transform .8s cubic-bezier(.2,.7,.2,1) var(--d)}
.ldr.is-in .ldr-rv{opacity:1;transform:none}

/* head */
.ldr__head{max-width:760px;margin:0 0 clamp(40px,5vw,64px)}
.ldr__kicker{display:inline-flex;align-items:center;gap:10px;font:700 .76rem var(--body);letter-spacing:.18em;text-transform:uppercase;color:var(--lv-teal2);margin-bottom:14px}
.ldr__kicker i{width:30px;height:2px;border-radius:2px;background:linear-gradient(90deg,var(--lv-teal2),var(--lv-bright))}
.ldr__head h2{margin:0 0 12px;font:800 clamp(2rem,3.8vw,3rem)/1.1 var(--display);letter-spacing:-.02em;color:#fff}
.ldr__head p{margin:0;font-size:1.06rem;color:var(--lv-soft)}

.ldr-label{display:block;font:700 .74rem var(--body);letter-spacing:.16em;text-transform:uppercase;color:var(--lv-teal2)}

/* portrait frame */
.ldr-pf{--rx:0deg;--ry:0deg;--mx:0;--my:0;perspective:1100px;width:100%}
.ldr-pf__stage{position:relative;aspect-ratio:1;transform-style:preserve-3d;transform:rotateX(var(--rx)) rotateY(var(--ry));transition:transform .5s cubic-bezier(.2,.7,.2,1)}
.ldr-pf:hover .ldr-pf__stage{transition:transform .12s linear}
.ldr-pf__grid{position:absolute;inset:0;border-radius:26px;transform:translate3d(22px,22px,-60px) translate(calc(var(--mx)*-14px),calc(var(--my)*-14px));
  border:1px solid #5D86FF66;background-image:linear-gradient(#5D86FF26 1px,transparent 1px),linear-gradient(90deg,#5D86FF26 1px,transparent 1px);background-size:22px 22px;transition:transform .3s}
.ldr-pf__glass{position:absolute;inset:0;border-radius:26px;transform:translate3d(-16px,-16px,-30px) translate(calc(var(--mx)*-8px),calc(var(--my)*-8px));background:linear-gradient(140deg,#ffffff1f,#ffffff05);border:1px solid #ffffff26;transition:transform .3s}
.ldr-pf__img{position:absolute;inset:0;border-radius:24px;overflow:hidden;transform:translateZ(20px);background:#0A1A7A;box-shadow:0 40px 70px -30px #000000b0,0 0 0 1px #ffffff2e}
.ldr-pf__img img{display:block;width:100%;height:100%;object-fit:cover;object-position:50% 38%;transform:scale(1.01);transition:transform .9s cubic-bezier(.2,.7,.2,1)}
.ldr-pf:hover .ldr-pf__img img{transform:scale(1.05)}
.ldr-pf__img::after{content:"";position:absolute;inset:0;background:linear-gradient(180deg,transparent 58%,#07104F99 100%);pointer-events:none}
.ldr-pf__sheen{position:absolute;inset:0;background:linear-gradient(115deg,transparent 35%,#ffffff2e 50%,transparent 65%);background-size:260% 100%;background-position:130% 0;transition:background-position 1s;pointer-events:none;z-index:1}
.ldr-pf:hover .ldr-pf__sheen{background-position:-30% 0}
.ldr-pf__brk{position:absolute;inset:-12px;width:calc(100% + 24px);height:calc(100% + 24px);transform:translateZ(44px);overflow:visible}
.ldr-pf__brk path{fill:none;stroke:var(--lv-teal2);stroke-width:1.6;vector-effect:non-scaling-stroke;stroke-linecap:round;stroke-dasharray:60;stroke-dashoffset:60;transition:stroke-dashoffset 1.2s .5s cubic-bezier(.2,.7,.2,1)}
.ldr.is-in .ldr-pf__brk path{stroke-dashoffset:0}
.ldr-pf__chip{position:absolute;left:-18px;bottom:28px;transform:translateZ(70px) translate(calc(var(--mx)*10px),calc(var(--my)*10px));display:inline-flex;align-items:center;gap:10px;padding:12px 16px;border-radius:14px;
  background:#07104FE6;border:1px solid #ffffff2e;font:700 .92rem var(--display);color:#fff;box-shadow:0 20px 40px -18px #000000a0;transition:transform .3s;white-space:nowrap}
.ldr-pf__chip svg{color:var(--lv-teal2)}
.ldr-pf--sm .ldr-pf__grid{transform:translate3d(10px,10px,-40px);border-radius:18px;background-size:14px 14px}
.ldr-pf--sm .ldr-pf__glass{transform:translate3d(-8px,-8px,-20px);border-radius:18px}
.ldr-pf--sm .ldr-pf__img{border-radius:16px}
.ldr-pf--sm .ldr-pf__brk{inset:-7px;width:calc(100% + 14px);height:calc(100% + 14px)}

/* CEO */
.ldr-ceo{display:grid;grid-template-columns:minmax(0,.82fr) minmax(0,1.18fr);gap:clamp(36px,6vw,88px);align-items:center}
.ldr-ceo>*{min-width:0}
.ldr-ceo__art{padding:24px 24px 24px 18px;max-width:470px}
.ldr-qm{display:block;width:52px;height:44px;margin:18px 0}
.ldr-qm path{fill:var(--lv-bright)}
.ldr-ceo__q{margin:0;padding:0;border:0}
.ldr-ceo__q p{margin:0 0 18px;font-size:1.06rem;line-height:1.8;color:var(--lv-soft);max-width:62ch}
.ldr-ceo__q .ldr-ceo__lead{font:600 clamp(1.2rem,1.9vw,1.55rem)/1.5 var(--display);color:#fff;letter-spacing:-.01em}
.ldr-ceo__q .ldr-ceo__close{color:#fff;font-weight:600}
.ldr-sig{display:flex;align-items:center;justify-content:space-between;gap:20px;flex-wrap:wrap;margin-top:28px;padding-top:24px;border-top:1px solid #ffffff1f}
.ldr-sig h3{margin:0 0 4px;font:800 1.5rem var(--display);color:#fff}
.ldr-sig__role{display:block;font:700 .9rem var(--body);color:var(--lv-teal2);margin-bottom:4px}
.ldr-sig__mail{font:600 .88rem var(--body);color:var(--lv-sky);text-decoration:none}
.ldr-sig__mail:hover,.ldr-dir__mail:hover{text-decoration:underline;color:#fff}

/* contact dock */
.ldr-dock{display:flex;gap:10px}
.ldr-dock a{display:grid;place-items:center;width:44px;height:44px;border-radius:14px;color:#fff;background:#ffffff12;border:1px solid #ffffff2e;text-decoration:none;
  transition:transform .3s cubic-bezier(.2,.7,.2,1),background .25s,border-color .25s,box-shadow .25s}
.ldr-dock a:hover{transform:translateY(-3px);background:var(--lv-bright);border-color:var(--lv-bright);box-shadow:0 14px 26px -12px #1E5BFFcc}
.ldr-dock a:nth-child(2):hover{background:#0A66C2;border-color:#0A66C2}
.ldr-dock a:focus-visible,.ldr-sig__mail:focus-visible,.ldr-dir__mail:focus-visible{outline:2px solid var(--lv-teal2);outline-offset:3px}

/* directors */
.ldr-dirs{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:clamp(18px,2.4vw,28px);margin-top:clamp(56px,7vw,96px)}
.ldr-dir{position:relative;display:flex;flex-direction:column;gap:18px;padding:clamp(24px,3vw,34px);border-radius:26px;background:linear-gradient(160deg,#ffffff12,#ffffff06);border:1px solid #ffffff1f;
  overflow:hidden;transition:opacity .8s cubic-bezier(.2,.7,.2,1) var(--d),transform .8s cubic-bezier(.2,.7,.2,1) var(--d),border-color .35s,box-shadow .35s}
.ldr.is-in .ldr-dir:hover{transform:translateY(-6px);transition-delay:0s;border-color:#ffffff3d;box-shadow:0 40px 70px -40px #000000b0}
.ldr-dir__edge{position:absolute;left:0;right:0;top:0;height:3px;background:linear-gradient(90deg,transparent,var(--lv-teal2),var(--lv-bright),transparent);background-size:200% 100%;animation:ldrEdge 6s linear infinite}
@keyframes ldrEdge{0%{background-position:100% 0}100%{background-position:-100% 0}}
.ldr-dir__top{display:grid;grid-template-columns:132px minmax(0,1fr);gap:24px;align-items:center}
.ldr-dir__top .ldr-pf{padding:8px}
.ldr-dir__id{display:flex;flex-direction:column;align-items:flex-start;gap:8px;min-width:0}
.ldr-dir__id h3{margin:0;font:800 1.38rem/1.2 var(--display);color:#fff}
.ldr-dir__role{display:inline-flex;align-items:center;gap:8px;padding:6px 12px;border-radius:999px;background:#0E9C8826;border:1px solid #6EE0CE4d;font:700 .82rem/1.3 var(--body);color:#DDFBF5}
.ldr-dir__role svg{color:var(--lv-teal2);flex:none}
.ldr-dir__id .ldr-dock{margin-top:4px}
.ldr-dir__id .ldr-dock a{width:38px;height:38px;border-radius:12px}
.ldr-dir__q{margin:0;padding:0 0 0 18px;border:0;border-left:2px solid var(--lv-bright)}
.ldr-dir__q p{margin:0;font-size:1.05rem;line-height:1.8;color:var(--lv-soft)}
.ldr-dir__q strong{display:block;margin-bottom:8px;font:600 1.16rem/1.5 var(--display);color:#fff}
.ldr-keys{list-style:none;margin:4px 0 0;padding:0;display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}
.ldr-keys li{display:flex;align-items:center;gap:10px;padding:12px 14px;border-radius:14px;background:#ffffff0a;border:1px solid #ffffff1a;font:700 .88rem var(--body);color:#fff;opacity:0;transform:translateY(8px);transition:opacity .6s,transform .6s,background .25s,border-color .25s;transition-delay:calc(var(--j)*100ms + .7s)}
.ldr.is-in .ldr-keys li{opacity:1;transform:none}
.ldr-keys li:hover{background:#1E5BFF26;border-color:#5D86FF80}
.ldr-keys svg{flex:none;color:var(--lv-teal2)}
.ldr-dir__mail{margin-top:auto;font:600 .84rem var(--body);color:var(--lv-sky);text-decoration:none;overflow-wrap:anywhere}

/* perspective points */
.ldr-pts{list-style:none;margin:0;padding:0;position:relative;display:flex;flex-direction:column;gap:4px}
.ldr-pts::before{content:"";position:absolute;left:19px;top:20px;bottom:20px;width:2px;background:#ffffff1a}
.ldr-pts::after{content:"";position:absolute;left:19px;top:20px;width:2px;height:0;background:linear-gradient(var(--lv-teal2),var(--lv-bright));transition:height 1.6s .7s cubic-bezier(.2,.7,.2,1)}
.ldr.is-in .ldr-pts::after{height:calc(100% - 40px)}
.ldr-pts li{position:relative;display:grid;grid-template-columns:40px minmax(0,1fr);gap:14px;align-items:start;padding:8px 10px 8px 0;border-radius:14px;opacity:0;transform:translateX(-10px);transition:opacity .6s,transform .6s,background .25s;transition-delay:calc(var(--j)*110ms + .6s)}
.ldr.is-in .ldr-pts li{opacity:1;transform:none}
.ldr-pts li:hover{background:#ffffff08}
.ldr-pts__ic{position:relative;z-index:1;display:grid;place-items:center;width:40px;height:40px;border-radius:12px;background:#0A1A7A;border:1px solid #5D86FF66;color:var(--lv-teal2);box-shadow:0 0 0 4px #0B1A70}
.ldr-pts li:first-child .ldr-pts__ic{background:var(--lv-bright);border-color:var(--lv-bright);color:#fff}
.ldr-pts p{margin:0;padding-top:8px;font-size:.98rem;line-height:1.65;color:var(--lv-soft)}
.ldr-pts li:first-child p{font:600 1.08rem/1.5 var(--display);color:#fff;padding-top:6px}

/* responsive */
@media (max-width:1024px){
  .ldr-dirs{grid-template-columns:1fr}
  .ldr-ceo{grid-template-columns:minmax(0,.9fr) minmax(0,1.1fr);gap:40px}
}
@media (max-width:820px){
  .ldr-ceo{grid-template-columns:1fr}
  .ldr-ceo__art{max-width:380px;margin:0 auto;width:100%}
  .ldr__globe{width:110vw;right:-50%;top:-6%;opacity:.3}
}
@media (max-width:640px){
  .ldr{padding-block:64px}
  .ldr-ceo__art{max-width:300px;padding:18px 18px 18px 14px}
  .ldr-pf__grid{transform:translate3d(14px,14px,-40px)}
  .ldr-pf__glass{transform:translate3d(-10px,-10px,-20px)}
  .ldr-pf__chip{left:-8px;bottom:18px;padding:9px 12px;font-size:.8rem}
  .ldr-ceo__q p{font-size:1rem}
  .ldr-sig h3{font-size:1.3rem}
  .ldr-dir{padding:22px 18px}
  .ldr-dir__top{grid-template-columns:96px minmax(0,1fr);gap:16px}
  .ldr-dir__id h3{font-size:1.18rem}
  .ldr-dir__role{font-size:.74rem;padding:5px 10px}
  .ldr-pts li{grid-template-columns:36px minmax(0,1fr);gap:12px}
  .ldr-pts__ic{width:36px;height:36px}
  .ldr-pts::before,.ldr-pts::after{left:17px}
  .ldr-pts p{font-size:.94rem}
}
@media (max-width:380px){
  .ldr-dir__top{grid-template-columns:1fr}
  .ldr-dir__top .ldr-pf{max-width:150px}
}
@media (hover:none){.ldr-pf__stage{transform:none}}
@media (prefers-reduced-motion:reduce){
  .ldr *,.ldr *::before,.ldr *::after{animation:none!important;transition-duration:.01ms!important;transition-delay:0s!important}
  .ldr-rv{opacity:1;transform:none;filter:none}
  .ldr-pts li,.ldr-keys li{opacity:1;transform:none}
  .ldr-pts::after{height:calc(100% - 40px)}
  .ldr-pf__brk path{stroke-dashoffset:0}
  .ldr-pf__stage{transform:none!important}
}

/* ===== Leadership deck: equal frames, testimonial-style carousel ===== */
.ldr--deck .ldr__in{position:relative}
.ldr-pick{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:10px;max-width:980px;margin:0 auto 26px}
.ldr-pick__b{position:relative;display:flex;align-items:center;gap:12px;padding:10px 14px;border-radius:16px;border:1px solid #ffffff22;background:#ffffff0a;color:#fff;text-align:left;cursor:pointer;overflow:hidden;transition:background .3s,border-color .3s,translate .3s}
.ldr-pick__b:hover{background:#ffffff14;translate:0 -2px}
.ldr-pick__b img{flex:none;width:48px;height:48px;border-radius:14px;object-fit:cover;object-position:50% 30%;box-shadow:0 0 0 2px #ffffff33}
.ldr-pick__b b{display:block;font:800 .95rem var(--display)}
.ldr-pick__b small{display:block;font-size:.76rem;color:#C9D3F5;line-height:1.3}
.ldr-pick__b.is-on{background:#ffffff1c;border-color:#6EE0CE88;box-shadow:0 14px 30px -18px #6EE0CE}
.ldr-pick__b.is-on img{box-shadow:0 0 0 2px #6EE0CE}
.ldr-pick__t{position:absolute;left:0;bottom:0;height:3px;width:100%;background:#6EE0CE;transform-origin:left;animation:ldrT 9s linear}
@keyframes ldrT{from{scale:0 1}}
.ldr-deck{position:relative;height:560px}
.ldr-card{position:absolute;left:50%;top:0;width:min(1000px,92%);height:540px;display:grid;grid-template-columns:330px minmax(0,1fr);gap:36px;align-items:center;padding:34px;border-radius:30px;background:linear-gradient(160deg,#0F1F86ee,#0A1766f2 60%,#07104Ff5);border:1px solid #ffffff24;box-shadow:0 50px 90px -50px #000,inset 0 1px 0 #ffffff22;color:#fff;transform:translateX(calc(-50% + var(--off)*64%)) scale(calc(1 - var(--abs)*.16));opacity:calc(1 - var(--abs)*.6);z-index:calc(10 - var(--abs));transition:transform .9s cubic-bezier(.2,.7,.2,1),opacity .9s;cursor:pointer;overflow:hidden}
.ldr-card.is-front{cursor:default}
.ldr-card__edge{position:absolute;left:0;top:0;right:0;height:4px;background:linear-gradient(90deg,#1E5BFF,#6EE0CE,#F0D98F)}
.ldr-card__art{padding:14px}
.ldr-pf--eq{max-width:300px;margin:0 auto}
.ldr-card__body{display:flex;flex-direction:column;height:100%;min-height:0;position:relative}
.ldr-card .ldr-qm{position:absolute;right:0;top:-4px;width:64px;opacity:.14;z-index:0;pointer-events:none}
.ldr-card .ldr-qm path{fill:#6EE0CE}
.ldr-card__msg,.ldr-card .ldr-label{position:relative;z-index:1}
.ldr-card__msg{flex:1;min-height:0;overflow:auto;padding-right:6px;margin:12px 0 16px;scrollbar-width:thin;scrollbar-color:#ffffff33 transparent}
.ldr-card:not(.is-front) .ldr-card__msg{overflow:hidden}
.ldr-q{margin:0}
.ldr-q p{margin:0 0 12px;font-size:1.04rem;line-height:1.7;color:#E1E7FF}
.ldr-q p.ldr-q__lead{font:700 clamp(1.1rem,1.6vw,1.3rem)/1.5 var(--display);color:#fff}
.ldr-q strong{color:#fff}
.ldr-card.is-front .ldr-card__msg>*{animation:ldrIn .7s cubic-bezier(.2,.7,.2,1) both .15s}
@keyframes ldrIn{from{opacity:0;translate:0 14px}}
.ldr-card .ldr-sig{margin-top:auto;padding-top:16px;border-top:1px solid #ffffff1f;display:flex;justify-content:space-between;align-items:center;gap:12px}
.ldr-card .ldr-sig h3{margin:0;font:800 1.3rem var(--display);color:#fff}
.ldr-card .ldr-sig__role{display:inline-flex;align-items:center;gap:6px;margin-top:4px;font:700 .86rem var(--display);color:#6EE0CE}
.ldr-card .ldr-pts{margin:0;padding:0;list-style:none;display:grid;gap:8px}
.ldr-card .ldr-pts li{display:flex;gap:10px;align-items:flex-start}
.ldr-card .ldr-pts p{margin:0;font-size:.95rem;line-height:1.55;color:#E1E7FF}
.ldr-nav{display:flex;justify-content:center;align-items:center;gap:16px;margin-top:6px}
.ldr-round{width:46px;height:46px;border-radius:50%;border:1px solid #ffffff33;background:#ffffff0d;color:#fff;font-size:1.4rem;cursor:pointer;transition:background .25s}
.ldr-round:hover{background:#ffffff26}
.ldr-dots{display:flex;gap:0}
/* build 74: each dot keeps its 10px look but is a 24px tap target (the padding is transparent) */
.ldr-dots button{width:24px;height:24px;padding:7px;border:0;border-radius:999px;background:#ffffff40;background-clip:content-box;cursor:pointer;transition:width .35s,background .3s}
.ldr-dots button.is-on{width:50px;background:#6EE0CE;background-clip:content-box}
@media (max-width:1000px){
  .ldr-card{grid-template-columns:220px minmax(0,1fr);gap:22px;padding:24px}
}
