  .ldr-pick{grid-template-columns:1fr;gap:6px}
  .ldr-deck{height:auto;display:grid}
  .ldr-card{position:relative;grid-area:1/1;left:auto;width:100%;height:auto;grid-template-columns:1fr;gap:10px;padding:20px;transform:none;filter:none;opacity:0;visibility:hidden;transition:opacity .5s}
  .ldr-card.is-front{opacity:1;visibility:visible}
  .ldr-card__art{width:100%;max-width:240px;margin:0 auto}
  .ldr-card__msg{overflow:visible;max-height:none}
