}


.ldr-crumbs{margin-bottom:16px}.ldr-crumbs a,.ldr-crumbs span{color:#C9D6FF}
.ldr__h1{margin:.2em 0 .25em;font-size:clamp(2rem,4.2vw,3.2rem);line-height:1.08;letter-spacing:-.025em;color:#fff}

/* ===== Brand layer: logo, panels, affiliations ===== */
.br-sheen{position:absolute;inset:0;pointer-events:none;-webkit-mask-size:100% 100%;mask-size:100% 100%;-webkit-mask-repeat:no-repeat;mask-repeat:no-repeat;
  background:linear-gradient(105deg,transparent 0 40%,#ffffffd9 48%,#ffffff 50%,#ffffffd9 52%,transparent 60% 100%);background-size:300% 100%;background-position:150% 0;animation:brSweep 6.5s cubic-bezier(.4,0,.2,1) infinite;mix-blend-mode:screen;opacity:.75}
@keyframes brSweep{0%,55%{background-position:150% 0}85%,100%{background-position:-50% 0}}

/* header lockup */
.br-lock{position:relative;display:inline-block;line-height:0;height:58px;transition:transform .35s cubic-bezier(.2,.7,.2,1)}
.br-lock img{display:block;height:100%;width:auto}
a:hover>.br-lock,.br-lock:hover{transform:translateY(-1px)}
a:hover>.br-lock .br-sheen,.br-lock:hover .br-sheen{animation-duration:2.2s}
.br-node{position:absolute;width:6px;height:6px;margin:-3px 0 0 -3px;border-radius:50%;pointer-events:none}
.br-node::before,.br-node::after{content:"";position:absolute;inset:0;border-radius:50%}
.br-node::before{background:#7FB0FF;box-shadow:0 0 6px 2px #1E5BFFb3;opacity:0;animation:brGlow 3.6s ease-in-out infinite;animation-delay:calc(var(--i)*.55s)}
.br-node::after{border:1.4px solid #1E5BFF;opacity:0;animation:brPing 3.6s ease-out infinite;animation-delay:calc(var(--i)*.55s)}
@keyframes brGlow{0%,100%{opacity:0}18%{opacity:.95}40%{opacity:0}}
@keyframes brPing{0%{transform:scale(.6);opacity:.9}45%{transform:scale(3.2);opacity:0}100%{opacity:0}}
.br-run{position:absolute;height:2px;margin-top:-1px;pointer-events:none;border-radius:2px;overflow:hidden}
.br-run::after{content:"";position:absolute;top:0;bottom:0;width:22%;left:-22%;background:linear-gradient(90deg,transparent,#1E5BFF,#7FE0DA,transparent);animation:brRun 4.8s ease-in-out infinite}
@keyframes brRun{0%{left:-22%}60%,100%{left:100%}}

/* footer full logo on plate */
.br-full{display:inline-block;padding:14px 18px;border-radius:18px;background:#fff;box-shadow:0 18px 40px -24px #000000a0,0 0 0 1px #ffffff26;transition:transform .35s cubic-bezier(.2,.7,.2,1),box-shadow .35s}
.br-full:hover{transform:translateY(-3px);box-shadow:0 26px 50px -24px #1E5BFF80,0 0 0 1px #ffffff40}
.br-full__in{position:relative;display:block;line-height:0;width:min(270px,100%)}
.br-full__in img{display:block;width:100%;height:auto}
.br-full .br-node{width:7px;height:7px;margin:-3.5px 0 0 -3.5px}
a:has(>.br-full){display:inline-block}

/* chat avatar */
.chat__avatar img{animation:brFloat 5s ease-in-out infinite}

/* ISO seals */
.br-seal{position:relative;display:grid;place-items:center;flex:none;line-height:0;border-radius:50%;animation:brFloat 5.5s ease-in-out infinite}
.br-cert:nth-child(2) .br-seal{animation-delay:-1.8s}.br-cert:nth-child(3) .br-seal{animation-delay:-3.6s}
.br-seal img{display:block;border-radius:50%;background:#fff}
.br-seal .br-sheen{border-radius:50%}
.br-seal__ring{position:absolute;inset:-5px;border-radius:50%;border:1.5px dashed #1E5BFF66;animation:brSpin 18s linear infinite}
.br-seal__ring::after{content:"";position:absolute;top:-3px;left:50%;width:6px;height:6px;margin-left:-3px;border-radius:50%;background:#0E9C88;box-shadow:0 0 8px #6EE0CE}
.cert--dark .br-seal__ring,.badges--dark .br-seal__ring{border-color:#7FB0FF66}
.br-cert:hover .br-seal{animation-play-state:paused;transform:scale(1.06)}
.br-cert:hover .br-seal__ring{animation-duration:4s}
@keyframes brSpin{to{transform:rotate(360deg)}}
@keyframes brFloat{0%,100%{transform:translateY(0)}50%{transform:translateY(-4px)}}
.ca-card__badge .br-seal img{width:72px;height:72px}
.ca-card__badge .br-cert{padding:0!important;background:transparent!important;border:0!important;width:72px;height:72px}
.ca-card__badge .br-seal{width:72px;height:72px}
.br-seal img{flex:none}

/* ESOMAR + MSME */
.br-aff{position:relative;display:inline-flex;align-items:center;justify-content:center;line-height:0;transition:transform .35s cubic-bezier(.2,.7,.2,1),box-shadow .35s}
.br-aff:hover{transform:translateY(-3px);box-shadow:0 16px 30px -18px #07104F80}
.br-aff .br-sheen{inset:auto;width:var(--w,100%);height:var(--h,100%)}
.esomar.br-aff img{height:52px;width:auto;display:block}
.esomar.br-aff>.br-sheen{position:absolute;top:50%;left:50%;width:149px;height:52px;transform:translate(-50%,-50%)}
.br-msme{padding:6px 14px;border-radius:16px;background:#fff;border:1px solid var(--line,#DDE2EC)}
.br-msme img{height:52px;width:auto;display:block}
.br-msme>.br-sheen{position:absolute;top:50%;left:50%;width:143px;height:52px;transform:translate(-50%,-50%)}
.badges .br-msme,.badges .esomar.br-aff{background:#fff}
.br-msme--dark{border-color:#ffffff24}

/* panel logos */
.br-pl__in{position:relative;display:block;height:100%;line-height:0}
.br-pl__in img{height:100%;width:auto;max-width:100%;display:block;object-fit:contain}
.br-pl{transition:transform .35s cubic-bezier(.2,.7,.2,1)}
a:hover .br-pl,.br-pl:hover{transform:translateY(-2px) scale(1.02)}
.br-pl .br-sheen{animation-duration:7s}
.br-pl--turn2opinion .br-sheen{animation-delay:-1s}
.br-pl--myfrequentrewards .br-sheen{animation-delay:-3s}
.br-pl--myhealthopinions .br-pl__in{animation:brBeat 2.8s ease-in-out infinite;transform-origin:12% 50%}
@keyframes brBeat{0%,100%{transform:scale(1)}8%{transform:scale(1.035)}16%{transform:scale(1)}24%{transform:scale(1.025)}32%{transform:scale(1)}}
.br-pl--turn2opinion .br-pl__in::after{content:"";position:absolute;left:23%;top:46%;width:25%;aspect-ratio:1;transform:translate(-50%,-50%);border-radius:50%;border:2px solid transparent;border-top-color:#1E6BFF99;border-right-color:#1E6BFF33;animation:brSpin 3.2s linear infinite;pointer-events:none}
.br-pl--myfrequentrewards .br-pl__in::after{content:"";position:absolute;left:20.1%;top:23%;width:7px;height:7px;margin:-3.5px;border-radius:50%;background:#FFC24A;box-shadow:0 0 10px 3px #FFB020;opacity:0;animation:brTwinkle 3s ease-in-out infinite;pointer-events:none}
@keyframes brTwinkle{0%,100%{opacity:0;transform:scale(.4)}20%{opacity:1;transform:scale(1.2)}40%{opacity:0;transform:scale(.4)}}
.footer__panel .plogo{height:32px;padding:0;background:transparent;margin:0}
.footer__panel .br-pl__in img{height:32px}
.qnt-pan__m.br-pan{display:block;width:auto;height:auto;background:transparent;border-radius:0;padding:0;box-shadow:none}
.qnt-pan__m.br-pan .plogo{height:52px;padding:8px 12px;background:#fff;border-radius:12px;margin:0}

@media (max-width:900px){.br-lock{height:46px}}
@media (max-width:380px){.br-lock{height:40px}}
@media (prefers-reduced-motion:reduce){
  .br-sheen,.br-node::before,.br-node::after,.br-run::after,.br-seal,.br-seal__ring,.br-pl__in,.br-pl__in::after,.chat__avatar img{animation:none!important}
  .br-sheen{opacity:0}
}
.ca-esomar__logos{display:flex;flex-wrap:wrap;gap:10px;margin:4px 0 10px}
.ca-esomar__logos .ca-esomar__logo{margin:0;display:flex;align-items:center}
.ca-esomar__logo .br-msme{border:0;padding:0;background:transparent}
.ca-esomar__logo .esomar.br-aff,.ca-esomar__logo .br-msme{padding:0;background:transparent}
.ca-esomar__logo .br-aff img{height:44px}
.ca-esomar__logo .esomar.br-aff>.br-sheen{width:126px;height:44px}
.ca-esomar__logo .br-msme>.br-sheen{width:121px;height:44px}

.chat__avatar{width:auto!important;height:auto!important;border-radius:10px!important;padding:4px 7px}.chat__avatar img{width:78px!important;height:auto;display:block}
.br-lock{height:62px}.br-lock img{border-radius:6px}

/* Safari/macOS-safe header + footer logo: fixed box, no blend-mode inside the blurred header */
.header__logo{flex:none;display:inline-flex;align-items:center}
.br-lock{height:62px;width:153px;flex:none}
.br-lock img{width:100%;height:100%;object-fit:contain;-webkit-user-drag:none}
.br-lock .br-sheen,.br-full .br-sheen{display:none}
