/* ===== Blog visual system (bv-) ===== */
.bv .bv-tx{font-family:var(--display,"Manrope"),system-ui,sans-serif}
.bv .bv-pn{fill:#ffffff12;stroke:#ffffff33;stroke-width:1.5}
.bv *{transform-box:fill-box;transform-origin:center}
.bv .bv-motif *{animation-play-state:paused}
.bv.is-on .bv-motif *,.bv.is-on .bv-copy *{animation-play-state:running}
.bv .bv-copy *{animation-play-state:paused}

/* motion vocabulary */
.bv-float{animation:bvFloat 6s ease-in-out infinite;animation-delay:var(--d,0s)}
@keyframes bvFloat{0%,100%{translate:0 0}50%{translate:0 -10px}}
.bv-pulse{animation:bvPulse 3.2s ease-in-out infinite;animation-delay:var(--d,0s)}
@keyframes bvPulse{0%,100%{scale:1}50%{scale:1.06}}
.bv-flow{fill:none;stroke-width:3;stroke-dasharray:8 10;stroke-linecap:round;opacity:.75;animation:bvFlow 2.4s linear infinite}
.bv-flow-s{animation:bvFlow 3s linear infinite}
@keyframes bvFlow{to{stroke-dashoffset:-36}}
.bv-pop{animation:bvPop 5s cubic-bezier(.2,.7,.2,1) infinite;animation-delay:var(--d,0s)}
@keyframes bvPop{0%{opacity:0;scale:.85}10%,85%{opacity:1;scale:1}100%{opacity:1}}
.bv-pick{animation:bvPick 4s ease infinite;animation-delay:var(--d,0s);opacity:0}
@keyframes bvPick{0%,15%{opacity:0;scale:.3}25%,90%{opacity:1;scale:1}100%{opacity:0}}
.bv-off{opacity:0}
.bv-ring{fill:none;animation:bvRing 2.6s ease-out infinite;animation-delay:var(--d,0s);opacity:0}
@keyframes bvRing{0%{opacity:.8;scale:.7}100%{opacity:0;scale:1.4}}
.bv-drop{animation:bvDrop 5s cubic-bezier(.3,1.4,.5,1) infinite;animation-delay:var(--d,0s)}
@keyframes bvDrop{0%{opacity:0;translate:0 -30px}12%,90%{opacity:1;translate:0 0}100%{opacity:1}}
.bv-ecg{stroke-dasharray:640;stroke-dashoffset:640;animation:bvEcg 3s linear infinite}
@keyframes bvEcg{0%{stroke-dashoffset:640}70%,100%{stroke-dashoffset:0}}
.bv-draw{stroke-dasharray:900;stroke-dashoffset:900;animation:bvDraw 5s ease-out infinite}
@keyframes bvDraw{0%{stroke-dashoffset:900}45%,100%{stroke-dashoffset:0}}
.bv-grow{transform-origin:bottom;animation:bvGrow 5s cubic-bezier(.2,.7,.2,1) infinite;animation-delay:var(--d,0s)}
@keyframes bvGrow{0%{scale:1 .1}25%,100%{scale:1 1}}
.bv-grow-x{transform-origin:left;animation:bvGrowX 5s cubic-bezier(.2,.7,.2,1) infinite;animation-delay:var(--d,0s)}
@keyframes bvGrowX{0%{scale:.05 1}30%,100%{scale:1 1}}
.bv-blink{animation:bvBlink 2s ease-in-out infinite;animation-delay:var(--d,0s)}
@keyframes bvBlink{0%,100%{opacity:1}50%{opacity:.25}}
.bv-spin{animation:bvSpin 6s linear infinite}
.bv-spin--slow{animation-duration:16s}
@keyframes bvSpin{from{rotate:0deg}to{rotate:360deg}}
.bv-type{clip-path:inset(0 100% 0 0);animation:bvType 6s steps(24) infinite}
@keyframes bvType{0%{clip-path:inset(0 100% 0 0)}40%,100%{clip-path:inset(0 0 0 0)}}
.bv-rise{animation:bvRise 6s cubic-bezier(.2,.7,.2,1) infinite}
@keyframes bvRise{0%,30%{translate:0 216px}55%,100%{translate:0 0}}
.bv-cursor{animation:bvCursor 4s ease-in-out infinite}
@keyframes bvCursor{0%{translate:60px 90px}40%,70%{translate:0 0}100%{translate:60px 90px}}
.bv-cursor2{animation:bvCursor2 7s ease-in-out infinite}
@keyframes bvCursor2{0%,100%{translate:0 0}30%{translate:-230px -180px}60%{translate:-120px -40px}}
.bv-heart{animation:bvHeart 3s ease-out infinite;animation-delay:var(--d,0s);opacity:0}
@keyframes bvHeart{0%{opacity:0;translate:0 0;scale:.6}20%{opacity:1}100%{opacity:0;translate:0 -140px;scale:1.1}}
.bv-prog{transform-origin:left;animation:bvGrowX 6s linear infinite}
.bv-env{offset-rotate:0deg;animation:bvEnv 4s ease-in-out infinite}
@keyframes bvEnv{0%{offset-distance:0%;opacity:0}10%{opacity:1}90%{opacity:1}100%{offset-distance:100%;opacity:0}}
.bv-star{animation:bvStar 4s ease infinite;animation-delay:var(--d,0s);opacity:.25}
@keyframes bvStar{0%{opacity:.25;scale:.8}20%,85%{opacity:1;scale:1}100%{opacity:.25}}
.bv-build{animation:bvBuild 6s cubic-bezier(.2,.7,.2,1) infinite;animation-delay:var(--d,0s)}
@keyframes bvBuild{0%{opacity:0;translate:0 14px}12%,88%{opacity:1;translate:0 0}100%{opacity:0}}
.bv-packet{animation:bvPacket 2.8s ease-in-out infinite;animation-delay:var(--d,0s)}
@keyframes bvPacket{0%{transform:translate(230px,205px);opacity:0}15%{opacity:1}85%{opacity:1}100%{transform:translate(calc(230px + var(--x)),calc(205px + var(--y)));opacity:0}}
.bv-signal{stroke:#6EE0CE;stroke-opacity:.9;stroke-dasharray:14 200;animation:bvSig 2.4s linear infinite;animation-delay:var(--d,0s)}
@keyframes bvSig{from{stroke-dashoffset:214}to{stroke-dashoffset:0}}
.bv-scan{animation:bvScan 3s ease-in-out infinite}
@keyframes bvScan{0%,100%{translate:0 0}50%{translate:0 280px}}
.bv-tick{stroke-dasharray:40;stroke-dashoffset:40;animation:bvTick 5s ease infinite;animation-delay:var(--d,0s)}
@keyframes bvTick{0%,10%{stroke-dashoffset:40}25%,90%{stroke-dashoffset:0}100%{stroke-dashoffset:40}}
.bv-row{animation:bvBuild 6s ease infinite;animation-delay:var(--d,0s)}
.bv-stamp{animation:bvStamp 5s cubic-bezier(.3,1.5,.5,1) infinite}
@keyframes bvStamp{0%,30%{opacity:0;scale:1.6;rotate:-20deg}45%,92%{opacity:1;scale:1;rotate:-8deg}100%{opacity:0}}
.bv-coin{animation:bvCoin 3.6s ease-in-out infinite;animation-delay:var(--d,0s)}
@keyframes bvCoin{0%,100%{translate:0 0}50%{translate:0 -8px}}
.bv-cone{animation:bvBlink 4s ease-in-out infinite}
.bv-step{animation:bvPop 6s cubic-bezier(.2,.7,.2,1) infinite;animation-delay:var(--d,0s)}
.bv-bar{transform-origin:left;animation:bvGrowX 6s cubic-bezier(.2,.7,.2,1) infinite}

/* ----- in-article: process ----- */
.bfig.bv-proc,.bfig.bv-cmp{border:0;padding:0;background:none}
.bv-fk{display:inline-flex;align-items:center;gap:6px;margin-right:10px;padding:4px 10px;border-radius:999px;background:var(--tone-soft,#E8EEFF);color:var(--tone,#0B22A8);font:700 .68rem var(--body);letter-spacing:.1em;text-transform:uppercase;vertical-align:middle}
.bv-proc figcaption,.bv-cmp figcaption{font:800 1.05rem/1.4 var(--display);color:var(--ink,#07104F);margin-bottom:16px}
.bv-proc ol{list-style:none;margin:0;padding:22px 18px;display:grid;grid-template-columns:repeat(var(--n),minmax(0,1fr));gap:10px;position:relative;border-radius:22px;background:linear-gradient(160deg,#07104F,#0B22A8);overflow:hidden}
.bv-proc ol::before{content:"";position:absolute;left:40px;right:40px;top:50px;height:2px;background:#ffffff26}
.bv-proc ol::after{content:"";position:absolute;left:40px;right:40px;top:50px;height:2px;background:linear-gradient(90deg,#6EE0CE,#7FB0FF);transform-origin:left;transform:scaleX(0);transition:transform 1.4s cubic-bezier(.2,.7,.2,1) .2s}
.bv-proc.is-in ol::after{transform:none}
.bv-proc li{position:relative;z-index:1;display:flex;flex-direction:column;align-items:center;text-align:center;gap:8px;opacity:0;transform:translateY(12px);transition:opacity .5s,transform .5s;transition-delay:calc(var(--i)*120ms + .2s)}
.bv-proc.is-in li{opacity:1;transform:none}
.bv-proc__ic{display:grid;place-items:center;width:58px;height:58px;border-radius:18px;background:#0A1A7A;border:1.5px solid #5D86FF80;color:#6EE0CE;box-shadow:0 0 0 6px #0A1A7A;transition:transform .3s,background .3s}
.bv-proc li:last-child .bv-proc__ic{background:#6EE0CE;color:#07104F;border-color:#6EE0CE}
.bv-proc li:hover .bv-proc__ic{transform:translateY(-4px) scale(1.05);background:#1E5BFF;color:#fff}
.bv-proc__n{font:800 .7rem var(--display);letter-spacing:.1em;color:#7FB0FF}
.bv-proc li strong{font:700 .86rem/1.3 var(--body);color:#fff}

/* ----- comparison ----- */
.bv-cmp__t{border-radius:20px;overflow:hidden;border:1px solid var(--line,#DDE2EC);background:#fff}
.bv-cmp__t>div{display:grid;grid-template-columns:minmax(0,.8fr) minmax(0,1fr) minmax(0,1fr);border-top:1px solid var(--line,#DDE2EC);opacity:0;transform:translateX(-8px);transition:opacity .45s,transform .45s,background .25s;transition-delay:calc(var(--i,0)*80ms + .15s)}
.bv-cmp.is-in .bv-cmp__t>div{opacity:1;transform:none}
.bv-cmp__t>div:first-child{border-top:0}
.bv-cmp__t>div:not(.bv-cmp__h):hover{background:#F5F7FB}
.bv-cmp__t>div>*{padding:13px 16px;font-size:.92rem;line-height:1.5;color:var(--muted,#525C78)}
.bv-cmp__t strong{display:flex;align-items:flex-start;gap:8px;font:700 .9rem/1.4 var(--body);color:var(--ink,#07104F)}
.bv-cmp__t strong svg{flex:none;margin-top:2px;color:#1E5BFF}
.bv-cmp__h{background:#07104F}
.bv-cmp__h>span{font:800 .9rem var(--display)!important;color:#fff!important}
.bv-cmp__a{background:linear-gradient(135deg,#0B22A8,#1E5BFF)}
.bv-cmp__b{background:linear-gradient(135deg,#0B7A6A,#0E9C88)}
.bv-cmp__t>div:not(.bv-cmp__h)>span:nth-child(2){border-left:3px solid #1E5BFF26}
.bv-cmp__t>div:not(.bv-cmp__h)>span:nth-child(3){border-left:3px solid #0E9C8826}

/* ----- lists ----- */
.bv-list{list-style:none;padding:0;display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px;margin:18px 0}
.bv-list li{display:flex;gap:12px;align-items:flex-start;padding:14px 14px 14px 12px!important;border-radius:16px;background:#F5F7FB;border:1px solid #E6EAF3;line-height:1.55;opacity:0;transform:translateY(10px);transition:opacity .45s,transform .45s,border-color .25s,background .25s;transition-delay:calc(var(--i)*60ms)}
.bv-list li::before{display:none!important}
.bv-list.is-in li{opacity:1;transform:none}
.bv-list li:hover{background:#fff;border-color:#C9D6FB}
.bv-list__ic{flex:none;display:grid;place-items:center;width:34px;height:34px;border-radius:10px;background:#E8EEFF;color:#0B22A8;margin-top:1px}
.bv-list li:nth-child(3n+2) .bv-list__ic{background:#E3F5F2;color:#0B7A6A}
.bv-list li:nth-child(3n) .bv-list__ic{background:#FBF3E0;color:#8A6513}

/* ----- takeaways ----- */
.bv-take{border-radius:24px!important;padding:24px!important;background:linear-gradient(160deg,#07104F,#0B22A8)!important;color:#fff;border:0!important}
.bv-take h2{display:flex;align-items:center;gap:10px;color:#fff!important;margin-top:0}
.bv-take h2 svg{color:#F0D98F}
.bv-take ol{list-style:none;margin:0;padding:0;display:grid;gap:10px}
.bv-take li{display:grid;grid-template-columns:auto auto minmax(0,1fr);align-items:center;gap:12px;padding:12px 14px;border-radius:14px;background:#ffffff0d;border:1px solid #ffffff1c;opacity:0;transform:translateX(-10px);transition:opacity .5s,transform .5s;transition-delay:calc(var(--i)*90ms)}
.bv-take.is-in li{opacity:1;transform:none}
.bv-take__n{font:800 1.3rem var(--display);color:#6EE0CE;min-width:1.2em;text-align:center}
.bv-take__ic{display:grid;place-items:center;width:34px;height:34px;border-radius:10px;background:#ffffff14;color:#F0D98F}
.bv-take p{margin:0;color:#E3E8FA;font-size:.96rem;line-height:1.55}

/* ----- real media ----- */
.bv-media img,.bv-media video{display:block;width:100%;height:auto;border-radius:18px;background:#EEF2FB}
.bv-media figcaption{margin-top:8px;font-size:.86rem;color:var(--muted,#525C78)}

@media (max-width:760px){
  .bv-proc ol{grid-template-columns:1fr;padding:18px}
  .bv-proc ol::before,.bv-proc ol::after{left:46px;right:auto;top:30px;bottom:30px;width:2px;height:auto}
  .bv-proc ol::after{transform-origin:top;transform:scaleY(0)}
  .bv-proc.is-in ol::after{transform:none}
  .bv-proc li{flex-direction:row;text-align:left;gap:14px}
  .bv-proc__ic{width:48px;height:48px;flex:none}
  .bv-proc__n{order:3;margin-left:auto}
  .bv-cmp__t>div{grid-template-columns:1fr 1fr}
  .bv-cmp__t>div>strong,.bv-cmp__h>span:first-child{grid-column:1/-1}
  .bv-cmp__h>span:first-child{display:none}
  .bv-cmp__t>div>strong{background:#F5F7FB;padding-bottom:8px}
  .bv-list{grid-template-columns:1fr}
}
@media (prefers-reduced-motion:reduce){
  .bv *{animation:none!important}
  .bv-pick,.bv-heart,.bv-ring{opacity:1}
  .bv-ecg,.bv-draw,.bv-tick{stroke-dashoffset:0}
  .bv-type{clip-path:none}
  .bv-proc li,.bv-cmp__t>div,.bv-list li,.bv-take li{opacity:1;transform:none;transition:none}
  .bv-proc ol::after{transform:none;transition:none}
}
.bv-gauge{stroke-dasharray:0 500;animation:bvGauge 5s cubic-bezier(.2,.7,.2,1) infinite}
@keyframes bvGauge{0%{stroke-dasharray:0 500}40%,100%{stroke-dasharray:330 500}}
.bv-scanx{animation:bvScanx 6s ease-in-out infinite}
@keyframes bvScanx{0%,100%{translate:0 0}33%{translate:-120px -80px}66%{translate:-60px 60px}}
.bv-arrow{animation:bvArrow 4s cubic-bezier(.3,1.4,.5,1) infinite}
@keyframes bvArrow{0%,15%{translate:80px -80px;opacity:0}35%,90%{translate:0 0;opacity:1}100%{opacity:0}}
.bv-tilt{transform-origin:50% 0;transform-box:fill-box;animation:bvTilt 5s ease-in-out infinite}
@keyframes bvTilt{0%,100%{rotate:-4deg}50%{rotate:4deg}}
.bv-fall{animation:bvFall 2.4s ease-in infinite;animation-delay:var(--d,0s)}
@keyframes bvFall{0%{translate:0 -170px;opacity:0}20%{opacity:1}100%{translate:0 0;opacity:1}}
.bv-drag{animation:bvDrag 5s ease-in-out infinite}
@keyframes bvDrag{0%,100%{translate:0 0}40%,60%{translate:220px -120px}}
.bv-attract{animation:bvAttract 3s ease-in infinite;animation-delay:var(--d,0s)}
@keyframes bvAttract{0%{translate:0 0;opacity:1}80%{translate:-140px 20px;opacity:.2}100%{translate:-150px 20px;opacity:0}}
.bv-codeln{animation:bvBuild 6s ease infinite;animation-delay:var(--d,0s)}
.bv-launch{animation:bvLaunch 4s ease-in-out infinite}
@keyframes bvLaunch{0%,100%{translate:0 0}50%{translate:0 -18px}}
.bv-gauge2{animation:bvGauge2 5s cubic-bezier(.2,.7,.2,1) infinite}
@keyframes bvGauge2{0%{stroke-dasharray:0 480}40%,100%{stroke-dasharray:380 480}}
.bv-gauge3{animation:bvGauge3 5s cubic-bezier(.2,.7,.2,1) infinite}
@keyframes bvGauge3{0%{stroke-dasharray:0 600}40%,100%{stroke-dasharray:380 600}}
.bv-needle{transform-box:fill-box;transform-origin:50% 100%;animation:bvNeedle 5s cubic-bezier(.2,.7,.2,1) infinite}
@keyframes bvNeedle{0%{rotate:-90deg}40%,100%{rotate:40deg}}
.bv-dealL{animation:bvDealL 5s ease-in-out infinite}.bv-dealR{animation:bvDealR 5s ease-in-out infinite}
@keyframes bvDealL{0%,100%{translate:0 0}45%,60%{translate:30px 0}}
@keyframes bvDealR{0%,100%{translate:0 0}45%,60%{translate:-30px 0}}

/* ===== MyHealthOpinions (mho-) — healthcare palette on the site system ===== */
.mho{--h-ink:#0A1A4F;--h-navy:#07104F;--h-blue:#2563EB;--h-soft:#EAF2FF;--h-teal:#0E9C88;--h-teal2:#6EE0CE;--h-mint:#E6F6F2;--h-char:#1F2937;--h-muted:#55607A;--h-line:#DCE4EE;--h-off:#F7FAFC;--h-warm:#F4A261;
  color:var(--h-char)}
.mho .sr-only{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0 0 0 0);white-space:nowrap}
.mho-sec{padding-block:clamp(56px,7vw,96px)}
.mho-sec--soft{background:var(--h-off)}
.mho-sec--ink{background:radial-gradient(700px 360px at 90% 0%,#2563EB40 0%,transparent 60%),radial-gradient(520px 320px at 0% 100%,#0E9C8833 0%,transparent 70%),linear-gradient(165deg,#0B1F6B,#07104F);color:#fff}
.mho-sec--teal{background:linear-gradient(160deg,#0B5E57,#0A3D5C 70%,#0A2A5C);color:#fff}
.mho h2{font:800 clamp(1.8rem,3.2vw,2.6rem)/1.15 var(--display);letter-spacing:-.02em;color:var(--h-ink);margin:8px 0 14px}
.mho-sec--ink h2,.mho-sec--teal h2,.mho-cta h2{color:#fff}
.mho h3{font:800 1.12rem/1.3 var(--display);color:var(--h-ink);margin:0 0 6px}
.mho-k{display:inline-flex;align-items:center;gap:8px;font:700 .74rem var(--body);letter-spacing:.16em;text-transform:uppercase;color:var(--h-teal)}
.mho-k::before{content:"";width:22px;height:2px;border-radius:2px;background:currentColor}
.mho-k--light,.mho-head--light .mho-k{color:var(--h-teal2)}
.mho-head{max-width:760px;margin-bottom:clamp(28px,4vw,44px)}
.mho-head p{margin:0;color:var(--h-muted);font-size:1.04rem;line-height:1.65}
.mho-head--light p{color:#C9D3F5}
.mho-lead{font-size:1.06rem;line-height:1.7;color:var(--h-muted);margin:0 0 14px}
.mho-lead--light{color:#D6E4F5}
.mho-note{font-size:.88rem;color:var(--h-muted);margin:12px 0 0}
.mho-note a,.mho-why__note a,.mho-lead a{color:var(--h-blue);font-weight:600}
.mho-note--light{color:#B9C8E8}.mho-note--light a{color:#9EE7DA}
.mho-split{display:grid;grid-template-columns:minmax(0,.9fr) minmax(0,1.1fr);gap:clamp(28px,5vw,72px);align-items:center}
.mho-split>*{min-width:0}
.mho-ctas{display:flex;flex-wrap:wrap;gap:12px;margin:24px 0}
.mho-ctas--c{justify-content:center}
.mho .btn--primary{background:var(--h-teal);border-color:var(--h-teal)}
.mho .btn--primary:hover{background:#0B7F6F;border-color:#0B7F6F}

/* hero */
.mho-hero{position:relative;overflow:hidden;padding:clamp(28px,4vw,52px) 0 clamp(36px,5vw,64px);background:radial-gradient(800px 420px at 85% 30%,#DDEBFF 0%,transparent 65%),radial-gradient(520px 320px at 10% 100%,#E3F6F1 0%,transparent 70%),#fff;border-bottom:1px solid var(--h-line)}
.mho-hero__in{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:clamp(24px,4vw,56px);align-items:center}
.mho-hero__in>*{min-width:0}
.mho-crumbs a,.mho-crumbs span{color:var(--h-muted)}
.mho-brand{display:flex;align-items:center;gap:14px;flex-wrap:wrap;margin:14px 0 10px}
.mho-brand .plogo{height:58px;padding:8px 14px;background:#fff;border-radius:14px;box-shadow:0 0 0 1px var(--h-line),0 10px 24px -18px #0A1A4F66;margin:0}
.mho-brand__by{font:700 .8rem var(--body);letter-spacing:.06em;color:var(--h-muted)}
.mho-hero h1{font:800 clamp(2rem,4vw,3.15rem)/1.08 var(--display);letter-spacing:-.025em;color:var(--h-ink);margin:0 0 16px}
.mho-hero__lead{font-size:1.06rem;line-height:1.7;color:var(--h-muted);margin:0;max-width:60ch}
.mho-btn-ghost{color:var(--h-ink);border-color:#B8C5DB}
.mho-chips{list-style:none;margin:0;padding:0;display:flex;flex-wrap:wrap;gap:8px}
.mho-chips li{display:inline-flex;align-items:center;gap:7px;padding:7px 12px;border-radius:999px;background:#fff;border:1px solid var(--h-line);font:700 .82rem var(--body);color:var(--h-ink)}
.mho-chips svg{color:var(--h-teal)}

.mho-art{position:relative;max-width:560px;margin-left:auto;width:100%}
.mho-art__svg{display:block;width:100%;height:auto;overflow:visible}
.mho-art__orbit{fill:none;stroke:#C9D8F0;stroke-width:1.5;stroke-dasharray:3 7}
.mho-art__orbit--in{stroke:#B6E3DA}
.mho-art__link{fill:none;stroke:#9DB7E8;stroke-width:2;stroke-dasharray:5 7;opacity:0;transition:opacity .6s;transition-delay:calc(var(--i)*120ms + .3s)}
.mho-art.is-in .mho-art__link{opacity:1;animation:rcDash 2s linear infinite}
.mho-art__dot{fill:var(--h-teal);offset-rotate:0deg;opacity:0;animation:mhoTravel 3.2s ease-in-out infinite;animation-delay:calc(var(--i)*.6s)}
@keyframes mhoTravel{0%{offset-distance:0%;opacity:0}10%{opacity:1}85%{opacity:1}100%{offset-distance:100%;opacity:0}}
.mho-art__pulse{fill:none;stroke:#2563EB;stroke-width:2;transform-box:fill-box;transform-origin:center;animation:mhoPing 2.8s ease-out infinite}
@keyframes mhoPing{0%{opacity:.7;scale:1}100%{opacity:0;scale:1.6}}
.mho-art__ecg{stroke-dasharray:120;stroke-dashoffset:120;animation:mhoEcg 2.8s linear infinite}
@keyframes mhoEcg{0%{stroke-dashoffset:120}60%,100%{stroke-dashoffset:0}}
.mho-art__hubt{font:800 13px var(--display);fill:#fff;letter-spacing:.04em}
.mho-art__node{opacity:0;transform-box:fill-box;transform-origin:center;transition:opacity .5s,scale .5s;scale:.8;transition-delay:calc(var(--i)*100ms)}
.mho-art.is-in .mho-art__node{opacity:1;scale:1}
.mho-art__nc{fill:#fff;stroke:#C9D8F0;stroke-width:1.5;filter:drop-shadow(0 10px 14px #0A1A4F1f)}
.mho-art__node:nth-child(even) .mho-art__nc{stroke:#B6E3DA}
.mho-art__ic{fill:none;stroke:#0E9C88;stroke-width:2;stroke-linecap:round;stroke-linejoin:round}
.mho-art__tag{fill:#0A1A4F}
.mho-art__tt{font:700 11px var(--body);fill:#fff}
.mho-art__card{position:absolute;display:inline-flex;align-items:center;gap:8px;padding:9px 13px;border-radius:12px;background:#fff;box-shadow:0 14px 30px -18px #0A1A4F80,0 0 0 1px var(--h-line);font:700 .8rem var(--body);color:var(--h-ink);animation:mhoFloat 6s ease-in-out infinite}
.mho-art__card svg{color:var(--h-teal)}
.mho-art__card--a{left:-2%;top:44%}
.mho-art__card--b{right:-2%;top:6%;animation-delay:-2s}
.mho-art__card--c{right:4%;bottom:-2%;animation-delay:-4s;background:var(--h-ink);color:#fff}
.mho-art__card--c svg{color:#F0D98F}
.mho-art__card--c i{display:inline-block;width:5px;border-radius:2px;background:var(--h-teal2);margin-left:2px}
.mho-art__card--c i:nth-of-type(1){height:8px}.mho-art__card--c i:nth-of-type(2){height:13px}.mho-art__card--c i:nth-of-type(3){height:18px}
@keyframes mhoFloat{0%,100%{translate:0 0}50%{translate:0 -8px}}

/* subnav tint */
.mho-subnav .rc-subnav__in a.is-on{background:var(--h-ink)}

/* topics */
.mho-topics{list-style:none;margin:0;padding:0;display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px}
.mho-topics li{display:flex;flex-direction:column;gap:12px;padding:20px;border-radius:18px;background:var(--h-off);border:1px solid var(--h-line);transition:transform .3s,background .3s,border-color .3s}
.mho-topics li:hover{transform:translateY(-4px);background:#fff;border-color:#B6E3DA}
.mho-topics li>span{width:44px;height:44px;border-radius:14px;display:grid;place-items:center;background:var(--h-mint);color:var(--h-teal)}
.mho-topics li:nth-child(even)>span{background:var(--h-soft);color:var(--h-blue)}
.mho-topics strong{font:800 .98rem/1.3 var(--display);color:var(--h-ink)}

/* steps */
.mho-steps{list-style:none;margin:0;padding:0;display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:16px;position:relative}
.mho-steps::before{content:"";position:absolute;left:8%;right:8%;top:58px;height:2px;background:var(--h-line)}
.mho-steps::after{content:"";position:absolute;left:8%;right:8%;top:58px;height:2px;background:linear-gradient(90deg,var(--h-teal),var(--h-blue));transform-origin:left;transform:scaleX(0);transition:transform 1.6s cubic-bezier(.2,.7,.2,1) .2s}
.mho-steps.is-in::after{transform:none}
.mho-steps li{position:relative;z-index:1;display:flex;flex-direction:column;align-items:center;text-align:center;gap:8px;opacity:0;translate:0 14px;transition:opacity .5s,translate .5s;transition-delay:calc(var(--i)*130ms + .2s)}
.mho-steps.is-in li{opacity:1;translate:0 0}
.mho-steps__n{font:800 .78rem var(--display);letter-spacing:.1em;color:var(--h-teal)}
.mho-steps__ic{display:grid;place-items:center;width:64px;height:64px;border-radius:50%;background:#fff;border:2px solid #B6E3DA;color:var(--h-teal);box-shadow:0 0 0 8px var(--h-off);transition:background .3s,color .3s}
.mho-steps li:last-child .mho-steps__ic{background:var(--h-teal);border-color:var(--h-teal);color:#fff}
.mho-steps li:hover .mho-steps__ic{background:var(--h-blue);border-color:var(--h-blue);color:#fff}
.mho-steps h3{font-size:1rem;margin:6px 0 0}
.mho-steps p{margin:0;font-size:.9rem;line-height:1.55;color:var(--h-muted)}

/* why */
.mho-why{list-style:none;margin:0;padding:0;display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:0;border-top:1px solid #ffffff22}
.mho-why li{padding:26px 22px 4px;border-right:1px solid #ffffff1a}
.mho-why li:last-child{border-right:0}
.mho-why li>span{display:grid;place-items:center;width:50px;height:50px;border-radius:14px;background:#ffffff12;border:1px solid #ffffff26;color:var(--h-teal2);margin-bottom:16px}
.mho-why h3{color:#fff}
.mho-why p{margin:0;color:#C9D3F5;font-size:.94rem;line-height:1.6}
.mho-why__note{margin:28px 0 0;color:#B9C8E8;font-size:.9rem}
.mho-why__note a{color:#9EE7DA}

/* community */
.mho-tri{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:16px}
.mho-tri__c{position:relative;padding:26px;border-radius:22px;background:#fff;border:1px solid var(--h-line);overflow:hidden}
.mho-tri__c::before{content:"";position:absolute;left:0;right:0;top:0;height:4px;background:var(--h-teal)}
.mho-tri__c:nth-child(2)::before{background:var(--h-blue)}.mho-tri__c:nth-child(3)::before{background:var(--h-warm)}
.mho-tri__c>span{display:grid;place-items:center;width:52px;height:52px;border-radius:16px;background:var(--h-mint);color:var(--h-teal);margin-bottom:14px}
.mho-tri__c:nth-child(2)>span{background:var(--h-soft);color:var(--h-blue)}.mho-tri__c:nth-child(3)>span{background:#FDF0E5;color:#B5651D}
.mho-tri__c p{margin:0;color:var(--h-muted);font-size:.94rem;line-height:1.6}
.mho-eco{list-style:none;margin:28px 0 0;padding:0;display:flex;flex-wrap:wrap;justify-content:center;gap:6px 0}
.mho-eco li{padding:10px 26px 10px 18px;background:var(--h-soft);font:700 .86rem var(--body);color:var(--h-ink);clip-path:polygon(0 0,calc(100% - 12px) 0,100% 50%,calc(100% - 12px) 100%,0 100%,12px 50%);margin-left:-6px}
.mho-eco li:first-child{clip-path:polygon(0 0,calc(100% - 12px) 0,100% 50%,calc(100% - 12px) 100%,0 100%);margin-left:0}
.mho-eco li:nth-child(even){background:var(--h-mint)}

/* rewards */
.mho-rw{display:grid;grid-template-columns:minmax(0,1.1fr) minmax(0,.9fr);gap:clamp(24px,4vw,48px);align-items:stretch}
.mho-rw>*{min-width:0}
.mho-pay{list-style:none;margin:18px 0 0;padding:0;display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}
.mho-pay li{display:flex;align-items:center;gap:12px;padding:16px;border-radius:16px;background:#fff;border:1px solid var(--h-line);font:800 1rem var(--display);color:var(--h-ink);transition:transform .3s,border-color .3s,box-shadow .3s}
.mho-pay li:hover{transform:translateY(-3px);border-color:#B6E3DA;box-shadow:0 16px 30px -22px #0A1A4F66}
.mho-pay li>span{display:grid;place-items:center;width:42px;height:42px;border-radius:12px;background:var(--h-soft);color:var(--h-blue)}
.mho-benefit{margin-top:22px;padding:16px 18px;border-radius:16px;border:1px dashed #B6E3DA;background:#fff}
.mho-benefit__k{display:block;font:700 .7rem var(--body);letter-spacing:.14em;text-transform:uppercase;color:var(--h-teal);margin-bottom:8px}
.mho-benefit>div{display:flex;gap:12px;align-items:flex-start;color:var(--h-teal)}
.mho-benefit strong{display:block;font:800 .98rem var(--display);color:var(--h-ink)}
.mho-benefit em{display:block;font-style:normal;font-size:.86rem;color:var(--h-muted)}
.mho-rw__side{padding:clamp(22px,3vw,32px);border-radius:24px;background:var(--h-ink);color:#fff}
.mho-rw__side h3{color:#fff;font-size:1.4rem}
.mho-rw__side>p{color:#C9D3F5;margin:0 0 18px;font-size:.95rem;line-height:1.6}
.mho-notify{list-style:none;margin:0;padding:0;display:grid;gap:10px}
.mho-notify li{display:flex;gap:14px;align-items:flex-start;padding:12px 14px;border-radius:14px;background:#ffffff0d;border:1px solid #ffffff1c}
.mho-notify__ic{position:relative;flex:none;display:grid;place-items:center;width:40px;height:40px;border-radius:12px;background:#ffffff14;color:var(--h-teal2)}
.mho-notify__ic i{position:absolute;top:-3px;right:-3px;width:10px;height:10px;border-radius:50%;background:var(--h-warm);box-shadow:0 0 0 3px var(--h-ink);animation:mhoBadge 3.2s ease-in-out infinite;animation-delay:calc(var(--i)*.8s)}
@keyframes mhoBadge{0%,70%,100%{scale:1}80%{scale:1.4}}
.mho-notify strong{display:block;font:800 .96rem var(--display);color:#fff}
.mho-notify em{display:block;font-style:normal;font-size:.86rem;color:#C9D3F5}

/* categories */
.mho-cat__bar{display:flex;flex-wrap:wrap;gap:12px;align-items:center;justify-content:space-between;margin-bottom:12px}
.mho-cat__tabs{display:flex;flex-wrap:wrap;gap:8px}
.mho-cat__tabs button{display:inline-flex;align-items:center;gap:7px;padding:9px 14px;border-radius:999px;border:1px solid var(--h-line);background:#fff;font:700 .84rem var(--body);color:var(--h-ink);cursor:pointer;transition:background .2s,color .2s,border-color .2s}
.mho-cat__tabs button svg{color:var(--h-teal)}
.mho-cat__tabs button.is-on{background:var(--h-ink);border-color:var(--h-ink);color:#fff}
.mho-cat__tabs button.is-on svg{color:var(--h-teal2)}
.mho-cat__tabs button:focus-visible,.mho-search input:focus-visible,.mho-use__tabs button:focus-visible{outline:2px solid var(--h-blue);outline-offset:2px}
.mho-search{display:flex;align-items:center;gap:8px;padding:0 14px;height:44px;border-radius:999px;border:1px solid var(--h-line);background:#fff;color:var(--h-muted);min-width:220px}
.mho-search input{border:0;outline:none;background:transparent;font:500 .92rem var(--body);color:var(--h-ink);width:100%;min-width:0}
.mho-search--light{background:#ffffff14;border-color:#ffffff30;color:#C9D3F5;margin-bottom:14px}
.mho-search--light input{color:#fff}.mho-search--light input::placeholder{color:#B9C8E8}
.mho-cat__count{margin:0 0 14px;font-size:.84rem;color:var(--h-muted)}
.mho-cat__list{list-style:none;margin:0;padding:0;display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:8px}
.mho-cat__i{display:flex;align-items:center;gap:10px;padding:12px 14px;border-radius:14px;background:var(--h-off);border:1px solid var(--h-line);font:700 .9rem/1.3 var(--body);color:var(--h-ink);animation:mhoIn .35s ease both;animation-delay:calc(var(--i)*25ms)}
.mho-cat__i>span{flex:none;display:grid;place-items:center;width:32px;height:32px;border-radius:10px;background:var(--h-mint);color:var(--h-teal)}
.mho-cat__i--pharmacy>span{background:#FDF0E5;color:#B5651D}
.mho-cat__i--hospital>span{background:var(--h-soft);color:var(--h-blue)}
.mho-cat__i--allied>span{background:#EEF0FB;color:#4B4FA8}
.mho-cat__none{padding:14px;color:var(--h-muted)}
@keyframes mhoIn{from{opacity:0;translate:0 6px}to{opacity:1;translate:0 0}}

/* specialties */
.mho-split--spec{align-items:start}
.mho-spec__grid{list-style:none;margin:0;padding:0;display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}
.mho-spec__grid li{display:flex;align-items:center;gap:12px;padding:14px;border-radius:16px;background:#ffffff10;border:1px solid #ffffff22;animation:mhoIn .4s ease both;animation-delay:calc(var(--i)*40ms);transition:background .25s,border-color .25s,transform .25s}
.mho-spec__grid li:hover{background:#ffffff1c;border-color:#6EE0CE80;transform:translateY(-2px)}
.mho-spec__ic{flex:none;display:grid;place-items:center;width:44px;height:44px;border-radius:14px;background:#ffffff14;color:var(--h-teal2)}
.mho-spec__grid strong{font:700 .95rem/1.3 var(--display);color:#fff}

/* patients & caregivers */
.mho-pc__art svg{display:block;width:100%;max-width:420px;margin:0 auto}
.mho-pc__c1{fill:#EAF2FF}.mho-pc__c2{fill:#E6F6F2;mix-blend-mode:multiply}
.mho-pc__p{fill:#2563EB}.mho-pc__q{fill:#0E9C88}
.mho-pc__h{fill:var(--h-warm);transform-box:fill-box;transform-origin:center;animation:mhoBeat 2.4s ease-in-out infinite}
@keyframes mhoBeat{0%,100%{scale:1}10%{scale:1.2}20%{scale:1}30%{scale:1.12}40%{scale:1}}
.mho-pc__t{font:800 14px var(--display);fill:#0A1A4F}
.mho-ticks{list-style:none;margin:6px 0 0;padding:0;display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px 16px}
.mho-ticks li{display:flex;gap:8px;align-items:flex-start;font:600 .92rem/1.45 var(--body);color:var(--h-ink)}
.mho-ticks svg{color:var(--h-teal);flex:none;margin-top:3px}

/* quality */
.mho-qflow{list-style:none;margin:0 0 28px;padding:0;display:grid;grid-template-columns:repeat(6,minmax(0,1fr));gap:8px}
.mho-qflow li{position:relative;display:flex;align-items:center;gap:10px;padding:14px;border-radius:14px;background:#fff;border:1px solid var(--h-line);font:700 .88rem/1.25 var(--body);color:var(--h-ink);opacity:0;translate:-8px 0;transition:opacity .45s,translate .45s;transition-delay:calc(var(--i)*110ms)}
.mho-qflow.is-in li{opacity:1;translate:0 0}
.mho-qflow li span{flex:none;display:grid;place-items:center;width:28px;height:28px;border-radius:50%;background:var(--h-teal);color:#fff;font:800 .78rem var(--display)}
.mho-qflow li:not(:last-child)::after{content:"";position:absolute;right:-8px;top:50%;width:8px;height:2px;background:var(--h-teal)}
.mho-qual{list-style:none;margin:0;padding:0;display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:16px}
.mho-qual li{padding:24px;border-radius:20px;background:#fff;border:1px solid var(--h-line)}
.mho-qual li>span{display:grid;place-items:center;width:46px;height:46px;border-radius:14px;background:var(--h-soft);color:var(--h-blue);margin-bottom:12px}
.mho-qual p{margin:0;color:var(--h-muted);font-size:.93rem;line-height:1.6}

/* researchers */
.mho-res{display:grid;grid-template-columns:minmax(0,1.15fr) minmax(0,.85fr);gap:clamp(24px,4vw,56px);align-items:start}
.mho-res>*{min-width:0}
.mho-res__aud{list-style:none;margin:8px 0 0;padding:0;display:flex;flex-wrap:wrap;gap:8px}
.mho-res__aud li{padding:7px 13px;border-radius:999px;background:#ffffff12;border:1px solid #ffffff2a;font:700 .84rem var(--body);color:#fff}
.mho-res__use{padding:clamp(20px,3vw,28px);border-radius:22px;background:#ffffff0d;border:1px solid #ffffff22}
.mho-res__use h3{color:#fff}
.mho-use__tabs{display:flex;flex-wrap:wrap;gap:6px;margin:10px 0 14px}
.mho-use__tabs button{padding:8px 13px;border-radius:999px;border:1px solid #ffffff30;background:transparent;color:#D6E4F5;font:700 .82rem var(--body);cursor:pointer}
.mho-use__tabs button.is-on{background:var(--h-teal2);border-color:var(--h-teal2);color:#07104F}
.mho-use__list{list-style:none;margin:0;padding:0;display:grid;gap:8px}
.mho-use__list li{display:flex;align-items:center;gap:10px;padding:11px 13px;border-radius:12px;background:#ffffff0d;font:600 .92rem var(--body);color:#fff;animation:mhoIn .35s ease both;animation-delay:calc(var(--i)*50ms)}
.mho-use__list svg{color:var(--h-teal2)}
.mho-res__use .mho-note{color:#B9C8E8}

/* other panels */
.mho-other{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px}
.mho-other__c{display:flex;flex-direction:column;gap:8px;padding:24px;border-radius:22px;background:#fff;border:1px solid var(--h-line);text-decoration:none;transition:transform .3s,box-shadow .3s,border-color .3s}
.mho-other__c:hover{transform:translateY(-4px);border-color:#B8C5DB;box-shadow:0 22px 40px -28px #0A1A4F80}
.mho-other__c .plogo{height:56px;padding:0;margin:0 0 6px;background:transparent}
.mho-other__a{font:700 .74rem var(--body);letter-spacing:.12em;text-transform:uppercase;color:var(--h-teal)}
.mho-other__t{font:600 1rem/1.5 var(--body);color:var(--h-ink)}
.mho-other__go{display:inline-flex;align-items:center;gap:6px;margin-top:auto;font:700 .88rem var(--body);color:var(--h-blue)}

/* final CTA */
.mho-cta{position:relative;overflow:hidden;padding-block:clamp(64px,8vw,104px);text-align:center;color:#fff;background:radial-gradient(600px 300px at 50% 0%,#2563EB55 0%,transparent 70%),linear-gradient(160deg,#0B5E57,#0A1F5C 60%,#07104F)}
.mho-cta__in{max-width:760px}
.mho-cta p{color:#D6E4F5;font-size:1.06rem;margin:0}
.mho-cta__links{list-style:none;margin:10px 0 0;padding:0;display:flex;flex-wrap:wrap;justify-content:center;gap:8px 22px}
.mho-cta__links a{color:#B9E9E0;font:600 .9rem var(--body)}

/* responsive */
@media (max-width:1100px){
  .mho-qflow{grid-template-columns:repeat(3,minmax(0,1fr))}
  .mho-qflow li:nth-child(3)::after{display:none}
  .mho-why{grid-template-columns:repeat(2,minmax(0,1fr))}
  .mho-why li:nth-child(2){border-right:0}
}
@media (max-width:900px){
  .mho-hero__in,.mho-split,.mho-rw,.mho-res{grid-template-columns:1fr}
  .mho-art{margin:0 auto;max-width:480px}
  .mho-steps{grid-template-columns:1fr;gap:0}
  .mho-steps::before,.mho-steps::after{left:31px;right:auto;top:30px;bottom:30px;width:2px;height:auto}
  .mho-steps::after{transform-origin:top;transform:scaleY(0)}
  .mho-steps.is-in::after{transform:none}
  .mho-steps li{display:grid;grid-template-columns:64px minmax(0,1fr);grid-template-rows:auto auto auto;column-gap:16px;text-align:left;align-items:start;padding-bottom:18px}
  .mho-steps__ic{grid-row:1/4;grid-column:1}
  .mho-steps__n,.mho-steps li h3,.mho-steps li p{grid-column:2}
  .mho-steps li h3{margin:0}
  .mho-tri,.mho-qual{grid-template-columns:1fr}
  .mho-cat__list{grid-template-columns:repeat(2,minmax(0,1fr))}
  .mho-pc__art{order:2}
}
@media (max-width:640px){
  .mho-hero h1{font-size:1.85rem}
  .mho-art__card{font-size:.72rem;padding:7px 10px}
  .mho-art__card--a,.mho-art__card--b{display:none}
  .mho-art{padding-bottom:34px}
  .mho-art__card--c{right:50%;translate:50% 0;bottom:0;animation:none}
  .mho-topics{grid-template-columns:1fr 1fr}
  .mho-topics li{padding:16px}
  .mho-why{grid-template-columns:1fr}
  .mho-why li{border-right:0;border-bottom:1px solid #ffffff1a;padding:20px 0}
  .mho-pay,.mho-spec__grid,.mho-ticks,.mho-other,.mho-cat__list{grid-template-columns:1fr}
  .mho-qflow{grid-template-columns:1fr 1fr}
  .mho-qflow li::after{display:none}
  .mho-cat__tabs{flex-wrap:nowrap;overflow-x:auto;padding-bottom:4px;margin-inline:-16px;padding-inline:16px;scrollbar-width:none}
  .mho-cat__tabs button{flex:none}
  .mho-search{min-width:0;width:100%}
  .mho-eco li{font-size:.78rem;padding:9px 20px 9px 14px}
  .mho-ctas .btn{width:100%;justify-content:center}
}
@media (prefers-reduced-motion:reduce){
  .mho *,.mho *::before,.mho *::after{animation:none!important;transition:none!important}
  .mho-art__link,.mho-art__node,.mho-steps li,.mho-qflow li{opacity:1!important;translate:none!important;scale:none!important}
  .mho-art__dot{display:none}
  .mho-art__ecg{stroke-dashoffset:0}
  .mho-steps::after{transform:none}
}

/* ===== Turn2Opinion (t2o-) — builds on the mho- layout with a Turn2Opinion blue palette ===== */
.t2o{--h-teal:#1E5BFF;--h-teal2:#8FB0FF;--h-mint:#E8EEFF;--h-blue:#0B22A8;--h-soft:#EEF2FF;--h-warm:#F5A524;--h-ink:#07104F}
.t2o .btn--primary{background:#1E5BFF;border-color:#1E5BFF}
.t2o .btn--primary:hover{background:#0B22A8;border-color:#0B22A8}
.t2o-hero{background:radial-gradient(800px 440px at 85% 35%,#DCE6FF 0%,transparent 65%),radial-gradient(520px 320px at 5% 100%,#FFF3DE 0%,transparent 70%),#fff}
.t2o-h1{display:flex;flex-direction:column;gap:6px}
.t2o-h1 span{font:700 clamp(1.05rem,1.6vw,1.3rem)/1.3 var(--display);letter-spacing:.01em;color:#1E5BFF}
.t2o-claim{font:800 clamp(1.25rem,2.1vw,1.6rem)/1.3 var(--display);color:var(--h-ink);margin:0 0 12px;letter-spacing:-.01em}
.t2o-c{text-align:center}

/* hero art */
.t2o-art{position:relative;max-width:580px;width:100%;margin-left:auto}
.t2o-art__svg{display:block;width:100%;height:auto;overflow:visible}
.t2o-art__path{fill:none;stroke:#B9CBFB;stroke-width:2.5;stroke-dasharray:6 8}
.t2o-art__path--b{stroke:#F7D69B}
.t2o-art.is-in .t2o-art__path{animation:rcDash 2.2s linear infinite}
.t2o-art__dot{fill:#1E5BFF;offset-rotate:0deg;opacity:0;animation:mhoTravel 3.6s ease-in-out infinite;animation-delay:calc(var(--i)*1.2s)}
.t2o-art__dot--b{fill:#F5A524}
.t2o-art__grp{opacity:0;translate:0 10px;transition:opacity .6s,translate .6s;transition-delay:calc(var(--i)*160ms)}
.t2o-art.is-in .t2o-art__grp{opacity:1;translate:0 0}
.t2o-art__lab{font:700 12px var(--body);fill:#55607A;letter-spacing:.04em}
.t2o-art__lab--s{font-size:11px}
.t2o-art__bub{fill:#1E5BFF}
.t2o-art__card{fill:#fff;stroke:#C9D6FB;stroke-width:1.5;filter:drop-shadow(0 12px 18px #07104F1a)}
.t2o-art__pick{fill:#1E5BFF;opacity:0;animation:t2oPick 4s ease infinite;animation-delay:calc(var(--r)*.6s)}
@keyframes t2oPick{0%,15%{opacity:0}25%,90%{opacity:1}100%{opacity:0}}
.t2o-art__hub{fill:#07104F}
.t2o-art__ring{fill:none;stroke:#1E5BFF;stroke-width:2;transform-box:fill-box;transform-origin:center;animation:mhoPing 2.8s ease-out infinite}
.t2o-art__tick{stroke-dasharray:60;stroke-dashoffset:60;animation:t2oTick 3.2s ease infinite}
@keyframes t2oTick{0%,20%{stroke-dashoffset:60}45%,100%{stroke-dashoffset:0}}
.t2o-art__gift{animation:mhoFloat 5s ease-in-out infinite}

/* trust strip */
.t2o-trust{padding:clamp(28px,4vw,44px) 0;background:#07104F;color:#fff}
.t2o-trust__h{font:800 1rem var(--display)!important;letter-spacing:.14em;text-transform:uppercase;color:#8FB0FF!important;margin:0 0 18px!important}
.t2o-trust ul{list-style:none;margin:0;padding:0;display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:0}
.t2o-trust li{display:flex;gap:14px;align-items:flex-start;padding:4px 20px;border-left:1px solid #ffffff22}
.t2o-trust li:first-child{padding-left:0;border-left:0}
.t2o-trust li>span{flex:none;display:grid;place-items:center;width:42px;height:42px;border-radius:12px;background:#ffffff12;color:#F5A524}
.t2o-trust strong{display:block;font:800 1rem var(--display);color:#fff}
.t2o-trust em{display:block;font-style:normal;font-size:.88rem;line-height:1.5;color:#C9D3F5}

/* what is */
.t2o-eco{list-style:none;margin:0;padding:0;display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px;counter-reset:e}
.t2o-eco li{display:flex;align-items:center;gap:12px;padding:16px;border-radius:16px;background:var(--h-off);border:1px solid var(--h-line);font:700 .95rem/1.35 var(--display);color:var(--h-ink)}
.t2o-eco li>span{flex:none;display:grid;place-items:center;width:40px;height:40px;border-radius:12px;background:#E8EEFF;color:#1E5BFF}
.t2o-eco li:nth-child(6)>span{background:#FFF3DE;color:#B9780A}

/* two paths */
.t2o-paths{display:grid;grid-template-columns:minmax(0,1fr) auto minmax(0,1fr);gap:18px;align-items:stretch}
.t2o-path{padding:24px;border-radius:22px;background:#fff;border:1px solid var(--h-line)}
.t2o-path__h{display:flex;gap:14px;align-items:center;margin-bottom:16px}
.t2o-path__h>span{display:grid;place-items:center;width:50px;height:50px;border-radius:16px;background:#E8EEFF;color:#1E5BFF}
.t2o-path--b .t2o-path__h>span{background:#FFF3DE;color:#B9780A}
.t2o-path__h h3{margin:0}
.t2o-path__h em{font-style:normal;font-size:.84rem;color:var(--h-muted)}
.t2o-path ul{list-style:none;margin:0;padding:0;display:flex;flex-wrap:wrap;gap:8px}
.t2o-path li{padding:7px 12px;border-radius:999px;background:var(--h-off);border:1px solid var(--h-line);font:600 .84rem var(--body);color:var(--h-ink)}
.t2o-path__mid{position:relative;display:grid;place-items:center;width:64px}
.t2o-path__mid::before{content:"";position:absolute;top:10%;bottom:10%;left:50%;width:2px;background:linear-gradient(#1E5BFF,#F5A524)}
.t2o-path__mid span{position:relative;writing-mode:vertical-rl;transform:rotate(180deg);padding:14px 8px;border-radius:999px;background:#07104F;color:#fff;font:800 .8rem var(--display);letter-spacing:.1em}

/* journey */
.t2o-journey{list-style:none;margin:0 0 40px;padding:28px 24px;display:grid;grid-template-columns:repeat(7,minmax(0,1fr));gap:8px;position:relative;border-radius:24px;background:linear-gradient(160deg,#07104F,#0B22A8);overflow:hidden}
.t2o-journey::before{content:"";position:absolute;left:7%;right:7%;top:56px;height:2px;background:#ffffff26}
.t2o-journey::after{content:"";position:absolute;left:7%;right:7%;top:56px;height:2px;background:linear-gradient(90deg,#8FB0FF,#F5A524);transform-origin:left;transform:scaleX(0);transition:transform 1.8s cubic-bezier(.2,.7,.2,1) .2s}
.t2o-journey.is-in::after{transform:none}
.t2o-journey li{position:relative;z-index:1;display:flex;flex-direction:column;align-items:center;gap:10px;text-align:center;opacity:0;translate:0 10px;transition:opacity .5s,translate .5s;transition-delay:calc(var(--i)*140ms + .2s)}
.t2o-journey.is-in li{opacity:1;translate:0 0}
.t2o-journey__ic{display:grid;place-items:center;width:56px;height:56px;border-radius:50%;background:#0A1A7A;border:2px solid #5D86FF80;color:#8FB0FF;box-shadow:0 0 0 6px #0A1A7A}
.t2o-journey li:last-child .t2o-journey__ic{background:#F5A524;border-color:#F5A524;color:#07104F}
.t2o-journey strong{font:700 .84rem/1.3 var(--body);color:#fff}
.t2o-steps .mho-steps__ic{border-color:#C9D6FB}

/* why */
.t2o-why{list-style:none;margin:0;padding:0;display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:0;border-top:1px solid #ffffff22;border-left:1px solid #ffffff22}
.t2o-why li{display:flex;gap:14px;padding:24px;border-right:1px solid #ffffff22;border-bottom:1px solid #ffffff22}
.t2o-why li>span{flex:none;display:grid;place-items:center;width:46px;height:46px;border-radius:14px;background:#ffffff12;color:#F5A524}
.t2o-why h3{color:#fff}
.t2o-why p{margin:0;color:#C9D3F5;font-size:.92rem;line-height:1.55}

/* topics */
.t2o-topics{list-style:none;margin:0;padding:0;display:flex;flex-wrap:wrap;gap:12px}
.t2o-topics li{display:inline-flex;align-items:center;gap:10px;padding:14px 18px;border-radius:999px;background:#fff;border:1px solid var(--h-line);font:700 .98rem var(--display);color:var(--h-ink);box-shadow:0 10px 24px -20px #07104F80;transition:transform .3s,border-color .3s}
.t2o-topics li:hover{transform:translateY(-3px);border-color:#9DB7FF}
.t2o-topics li svg{color:#1E5BFF}
.t2o-topics li:nth-child(3n) svg{color:#B9780A}

/* matching */
.t2o-match{list-style:none;margin:0 0 30px;padding:0;display:grid;grid-template-columns:repeat(6,minmax(0,1fr));gap:12px}
.t2o-match li{position:relative;display:flex;flex-direction:column;align-items:center;gap:10px;text-align:center;font:700 .9rem var(--body);color:var(--h-ink);opacity:0;translate:0 10px;transition:opacity .45s,translate .45s;transition-delay:calc(var(--i)*120ms)}
.t2o-match.is-in li{opacity:1;translate:0 0}
.t2o-match li>span{display:grid;place-items:center;width:58px;height:58px;border-radius:18px;background:#fff;border:1.5px solid #C9D6FB;color:#1E5BFF;box-shadow:0 12px 24px -18px #07104F80}
.t2o-match li:last-child>span{background:#F5A524;border-color:#F5A524;color:#07104F}
.t2o-match li:not(:last-child)::after{content:"";position:absolute;top:29px;left:calc(50% + 36px);right:calc(-50% + 36px);height:2px;background:repeating-linear-gradient(90deg,#9DB7FF 0 6px,transparent 6px 11px)}
.t2o-mp{display:grid;grid-template-columns:minmax(0,.85fr) minmax(0,1.15fr);gap:18px}
.t2o-mp>*{min-width:0}
.t2o-factors,.t2o-profile{padding:24px;border-radius:22px;background:#fff;border:1px solid var(--h-line)}
.t2o-factors ul{list-style:none;margin:12px 0 0;padding:0;display:grid;gap:8px}
.t2o-factors li{display:flex;align-items:center;gap:10px;font:600 .92rem var(--body);color:var(--h-ink)}
.t2o-factors li svg{color:#1E5BFF}
.t2o-profile{display:grid;grid-template-columns:150px minmax(0,1fr);gap:20px;align-items:center}
.t2o-profile p{margin:0 0 12px;color:var(--h-muted);font-size:.94rem}
.t2o-profile__ring svg{display:block;width:100%}
.t2o-profile__seg{fill:none;stroke:#1E5BFF;stroke-width:14;stroke-linecap:round;opacity:.25;animation:t2oSeg 7s ease-in-out infinite;animation-delay:calc(var(--i)*.5s)}
.t2o-profile__seg:nth-child(even){stroke:#F5A524}
@keyframes t2oSeg{0%,100%{opacity:.25}20%,60%{opacity:1}}
.t2o-profile__u{fill:#07104F}
.t2o-chips{list-style:none;margin:0;padding:0;display:flex;flex-wrap:wrap;gap:6px}
.t2o-chips li{padding:5px 10px;border-radius:999px;background:var(--h-off);border:1px solid var(--h-line);font:600 .8rem var(--body);color:var(--h-ink)}

/* quality */
.t2o-qflow li span{background:#1E5BFF}
.t2o-qflow li:not(:last-child)::after{background:#1E5BFF}
.t2o-q{display:grid;grid-template-columns:minmax(0,1.1fr) minmax(0,.9fr);gap:18px}
.t2o-q>*{min-width:0}
.t2o-q>div{padding:24px;border-radius:22px;background:var(--h-off);border:1px solid var(--h-line)}
.t2o-layers{list-style:none;margin:14px 0 0;padding:0;display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px}
.t2o-layers li{position:relative;display:flex;align-items:center;gap:10px;padding:12px;border-radius:12px;background:#fff;border:1px solid var(--h-line);font:700 .9rem/1.3 var(--body);color:var(--h-ink)}
.t2o-layers li>span{flex:none;display:grid;place-items:center;width:34px;height:34px;border-radius:10px;background:#E8EEFF;color:#1E5BFF}
.t2o-ready{background:#07104F!important;border-color:#07104F!important}
.t2o-ready h3{color:#fff}
.t2o-ready ul{list-style:none;margin:12px 0 0;padding:0;display:grid;gap:8px}
.t2o-ready li{display:flex;align-items:center;gap:10px;font:600 .92rem var(--body);color:#fff}
.t2o-ready li svg{color:#F5A524}
.t2o-ready .mho-note{color:#C9D3F5}.t2o-ready .mho-note a{color:#8FB0FF}

/* privacy */
.t2o-priv{display:grid;grid-template-columns:minmax(0,1.3fr) minmax(0,.7fr);gap:clamp(24px,4vw,56px);align-items:start}
.t2o-priv>*{min-width:0}
.t2o-priv__list{list-style:none;margin:8px 0 0;padding:0;display:grid;gap:10px}
.t2o-priv__list li{display:flex;gap:10px;align-items:flex-start;font-size:1rem;line-height:1.55;color:#E3E8FA}
.t2o-priv__list svg{flex:none;margin-top:4px;color:#F5A524}
.t2o-priv__links{padding:24px;border-radius:22px;background:#ffffff0d;border:1px solid #ffffff22}
.t2o-priv__links h3{color:#fff}
.t2o-priv__links ul{list-style:none;margin:10px 0 0;padding:0;display:grid;gap:2px}
.t2o-priv__links a{display:block;padding:10px 0;border-bottom:1px solid #ffffff1a;color:#C9D6FF;font:600 .94rem var(--body);text-decoration:none}
.t2o-priv__links a:hover{color:#fff}
.t2o-priv__links a:focus-visible,.t2o .mho-note a:focus-visible{outline:2px solid #F5A524;outline-offset:2px}

/* rewards */
.t2o-pay{grid-template-columns:1fr!important}
.t2o-vary{list-style:none;margin:6px 0 0;padding:0;display:flex;flex-wrap:wrap;gap:8px}
.t2o-vary li{padding:8px 13px;border-radius:999px;background:#ffffff12;border:1px solid #ffffff26;font:700 .86rem var(--body);color:#fff}

/* researchers */
.t2o-res__top{display:grid;grid-template-columns:minmax(0,1.3fr) minmax(0,.7fr);gap:24px;align-items:end;margin-bottom:28px}
.t2o-res__top>*{min-width:0}
.t2o-res__top .mho-ctas{flex-direction:column;align-items:stretch}
.t2o-value{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px}
.t2o-value__c{padding:22px;border-radius:20px;background:#ffffff0d;border:1px solid #ffffff22}
.t2o-value__ic{display:grid;place-items:center;width:46px;height:46px;border-radius:14px;background:#ffffff14;color:#F5A524;margin-bottom:12px}
.t2o-value__c h3{color:#fff;margin:0}
.t2o-value__c em{display:block;font-style:normal;font-size:.82rem;color:#8FB0FF;margin:2px 0 10px}
.t2o-value__c ul{list-style:none;margin:0;padding:0;display:flex;flex-wrap:wrap;gap:6px}
.t2o-value__c li{padding:5px 10px;border-radius:999px;background:#ffffff10;font:600 .8rem var(--body);color:#E3E8FA}
.t2o-sub{color:#fff!important;margin:36px 0 14px!important}
.t2o-pillars{list-style:none;margin:0;padding:0;display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px 24px}
.t2o-pillars li{display:flex;gap:12px;align-items:flex-start;color:#F5A524}
.t2o-pillars strong{display:block;font:800 .96rem var(--display);color:#fff}
.t2o-pillars em{display:block;font-style:normal;font-size:.88rem;line-height:1.5;color:#C9D3F5}
.t2o-spec{display:flex;align-items:center;justify-content:space-between;gap:20px;flex-wrap:wrap;margin-top:36px;padding:24px 26px;border-radius:22px;background:linear-gradient(120deg,#1E5BFF,#0B22A8);border:1px solid #ffffff33}
.t2o-spec h3{color:#fff;margin:0 0 6px}
.t2o-spec p{margin:0;max-width:70ch;color:#E3E8FA;font-size:.94rem}

/* who */
.t2o-who{display:grid;grid-template-columns:minmax(0,.6fr) minmax(0,1.4fr);gap:clamp(24px,4vw,56px);align-items:center}
.t2o-who>*{min-width:0}
.t2o-who__logo{padding:24px;border-radius:24px;background:#fff;border:1px solid var(--h-line);box-shadow:0 20px 40px -30px #07104F66}
.t2o-who__logo img{display:block;width:100%;height:auto}
.t2o-who .mho-lead a{color:#1E5BFF}

/* final */
.t2o-cta{background:radial-gradient(600px 300px at 50% 0%,#1E5BFF66 0%,transparent 70%),linear-gradient(160deg,#0B22A8,#07104F)}
.t2o-cta__res{margin-top:6px!important;font-size:.95rem}
.t2o-cta__res a{color:#F5C26B;font-weight:700}

@media (max-width:1100px){
  .t2o-trust ul{grid-template-columns:repeat(2,minmax(0,1fr));gap:18px 0}
  .t2o-trust li:nth-child(3){padding-left:0;border-left:0}
  .t2o-match{grid-template-columns:repeat(3,minmax(0,1fr));row-gap:22px}
  .t2o-match li:nth-child(3)::after{display:none}
  .t2o-journey{grid-template-columns:repeat(4,minmax(0,1fr));row-gap:22px}
  .t2o-journey::before,.t2o-journey::after{display:none}
}
@media (max-width:900px){
  .t2o-paths,.t2o-mp,.t2o-q,.t2o-priv,.t2o-res__top,.t2o-who{grid-template-columns:1fr}
  .t2o-path__mid{width:auto;height:48px}
  .t2o-path__mid::before{top:50%;bottom:auto;left:10%;right:10%;width:auto;height:2px}
  .t2o-path__mid span{writing-mode:horizontal-tb;transform:none;padding:8px 16px}
  .t2o-why,.t2o-value,.t2o-pillars{grid-template-columns:1fr 1fr}
  .t2o-who__logo{max-width:320px}
}
@media (max-width:640px){
  .t2o-trust ul{grid-template-columns:1fr}
  .t2o-trust li{padding-left:0;border-left:0}
  .t2o-eco,.t2o-layers,.t2o-why,.t2o-value,.t2o-pillars{grid-template-columns:1fr}
  .t2o-journey{grid-template-columns:1fr;padding:20px}
  .t2o-journey li{flex-direction:row;text-align:left;gap:14px}
  .t2o-journey__ic{width:46px;height:46px;flex:none}
  .t2o-match{grid-template-columns:1fr 1fr}
  .t2o-match li::after{display:none}
  .t2o-profile{grid-template-columns:1fr}
  .t2o-profile__ring{max-width:150px}
  .t2o-topics li{padding:11px 14px;font-size:.9rem}
}
@media (prefers-reduced-motion:reduce){
  .t2o *{animation:none!important;transition:none!important}
  .t2o-art__grp,.t2o-journey li,.t2o-match li{opacity:1!important;translate:none!important}
  .t2o-journey::after{transform:none}
  .t2o-art__tick{stroke-dashoffset:0}.t2o-art__pick{opacity:1}.t2o-art__dot{display:none}
}
.t2o .mho-rw{align-items:start}

/* ===== MyFrequentRewards (mfr-) — navy + amber identity on the mho/t2o system ===== */
.mfr{--h-teal:#C46A0A;--h-teal2:#FFC27A;--h-mint:#FFF1E0;--h-blue:#13306E;--h-soft:#EEF2FA;--h-warm:#F28C28;--h-ink:#0B1E4F;--m-or:#F28C28;--m-or2:#FFB347;--m-navy:#0B1E4F}
.mfr .btn--primary{background:var(--m-navy);border-color:var(--m-navy)}
.mfr .btn--primary:hover{background:#13306E;border-color:#13306E}
.mfr .mho-k{color:#B45F08}
.mfr .mho-k--light,.mfr .mho-head--light .mho-k{color:var(--m-or2)}
.mfr .t2o-h1 span{color:#B45F08}
.mfr-hero{background:radial-gradient(760px 420px at 85% 30%,#FFE9D1 0%,transparent 62%),radial-gradient(560px 360px at 5% 100%,#E6ECFA 0%,transparent 70%),#fff}
.mfr-hero__res{display:flex;align-items:center;gap:8px;margin:0;font:600 .92rem var(--body);color:var(--h-muted)}
.mfr-hero__res svg{color:var(--m-navy)}
.mfr-hero__res a{color:var(--m-navy);font-weight:700}

/* hero art */
.mfr-art{position:relative;width:100%;max-width:520px;aspect-ratio:520/440;margin-left:auto}
.mfr-art__path{position:absolute;inset:0;width:100%;height:100%;overflow:visible}
.mfr-art__path path{fill:none;stroke:#F7C38A;stroke-width:2.5;stroke-dasharray:6 8;vector-effect:non-scaling-stroke}
.mfr-art.is-in .mfr-art__path path{animation:rcDash 2.2s linear infinite}
.mfr-art__dot{fill:var(--m-or);offset-rotate:0deg;opacity:0;animation:mhoTravel 4.2s ease-in-out infinite;animation-delay:calc(var(--i)*1.4s)}
.mfr-card{position:absolute;padding:14px 16px;border-radius:18px;background:#fff;border:1px solid #E4E9F2;box-shadow:0 20px 40px -26px #0B1E4F80;opacity:0;translate:0 14px;transition:opacity .6s,translate .6s;transition-delay:calc(var(--i)*180ms)}
.mfr-art.is-in .mfr-card{opacity:1;translate:0 0}
.mfr-card__k{display:block;font:700 .66rem var(--body);letter-spacing:.14em;text-transform:uppercase;color:#7B8499;margin-bottom:8px}
.mfr-ln{display:block;height:7px;border-radius:4px;background:#D9E0EE;width:110px;margin-bottom:6px}
.mfr-ln--s{width:70px;background:#E8ECF4}
.mfr-card--profile{left:0;top:2%;width:48%}
.mfr-card__row{display:flex;gap:10px;align-items:center;margin-bottom:10px}
.mfr-av{flex:none;width:38px;height:38px;border-radius:50%;background:radial-gradient(circle at 50% 38%,#fff 0 7px,transparent 8px),radial-gradient(circle at 50% 100%,#fff 0 13px,transparent 14px),var(--m-navy)}
.mfr-card__chips{display:flex;flex-wrap:wrap;gap:5px}
.mfr-card__chips b{padding:3px 8px;border-radius:999px;background:#FFF1E0;color:#9A5108;font:700 .66rem var(--body)}
.mfr-card__chips b:nth-child(2){background:#E6ECFA;color:var(--m-navy)}
.mfr-card--invite{right:0;top:28%;width:46%;display:flex;gap:10px;align-items:center}
.mfr-card__ic{flex:none;display:grid;place-items:center;width:38px;height:38px;border-radius:12px;background:var(--m-navy);color:#fff}
.mfr-card--invite .mfr-card__k{margin-bottom:6px}
.mfr-card__ping{position:absolute;top:-5px;right:-5px;width:14px;height:14px;border-radius:50%;background:var(--m-or);box-shadow:0 0 0 4px #fff;animation:mhoBadge 2.8s ease-in-out infinite}
.mfr-card--survey{left:4%;top:52%;width:50%}
.mfr-q{margin-bottom:8px}
.mfr-q>div{display:flex;gap:8px}
.mfr-q span{width:14px;height:14px;border-radius:50%;border:2px solid #C9D3E6}
.mfr-q span.is-on{background:var(--m-navy);border-color:var(--m-navy);animation:t2oPick 4s ease infinite;animation-delay:calc(var(--q)*.8s)}
.mfr-prog{height:6px;border-radius:3px;background:#E8ECF4;overflow:hidden}
.mfr-prog span{display:block;height:100%;width:70%;background:linear-gradient(90deg,var(--m-navy),var(--m-or));transform-origin:left;animation:mfrProg 5s ease-in-out infinite}
@keyframes mfrProg{0%{scale:.1 1}60%,100%{scale:1 1}}
.mfr-card--reward{right:2%;bottom:0;width:50%;display:flex;gap:12px;align-items:center;background:var(--m-navy);border-color:var(--m-navy);color:#fff}
.mfr-card--reward svg{flex:none;width:52px;height:52px}
.mfr-ring{fill:none;stroke:#ffffff26;stroke-width:6}
.mfr-ring--on{stroke:var(--m-or2);stroke-linecap:round;stroke-dasharray:151;stroke-dashoffset:151;transform:rotate(-90deg);transform-origin:center;animation:mfrRing 5s ease-in-out infinite}
@keyframes mfrRing{0%{stroke-dashoffset:151}55%,100%{stroke-dashoffset:30}}
.mfr-card--reward .mfr-card__k{color:#AFC0E6}
.mfr-card--reward strong{font:800 .95rem var(--display)}
.mfr-card__gift{margin-left:auto;color:var(--m-or2)}

/* strip */
.mfr-strip{background:var(--m-navy);padding:18px 0}
.mfr-strip ul{list-style:none;margin:0;padding:0;display:flex;flex-wrap:wrap;justify-content:space-between;gap:10px 22px}
.mfr-strip li{display:flex;align-items:center;gap:9px;font:700 .92rem var(--body);color:#fff}
.mfr-strip li svg{color:var(--m-or2)}

/* core diagram */
.mfr-core{list-style:none;margin:clamp(30px,4vw,48px) 0 0;padding:0;display:grid;grid-template-columns:repeat(5,minmax(0,1fr));position:relative}
.mfr-core::before{content:"";position:absolute;left:10%;right:10%;top:44px;height:3px;border-radius:2px;background:#E4E9F2}
.mfr-core::after{content:"";position:absolute;left:10%;right:10%;top:44px;height:3px;border-radius:2px;background:linear-gradient(90deg,var(--m-navy),var(--m-or));transform-origin:left;transform:scaleX(0);transition:transform 1.8s cubic-bezier(.2,.7,.2,1) .2s}
.mfr-core.is-in::after{transform:none}
.mfr-core li{position:relative;z-index:1;display:flex;flex-direction:column;align-items:center;gap:10px;opacity:0;translate:0 12px;transition:opacity .5s,translate .5s;transition-delay:calc(var(--i)*150ms + .2s)}
.mfr-core.is-in li{opacity:1;translate:0 0}
.mfr-core__ic{display:grid;place-items:center;width:90px;height:90px;border-radius:28px;background:#fff;border:2px solid #E4E9F2;color:var(--m-navy);box-shadow:0 0 0 8px #fff,0 22px 40px -28px #0B1E4F80;transition:transform .3s,background .3s,color .3s}
.mfr-core li:hover .mfr-core__ic{transform:translateY(-4px);background:var(--m-navy);color:#fff}
.mfr-core li:nth-child(4) .mfr-core__ic{color:#B45F08}
.mfr-core li:last-child .mfr-core__ic{background:var(--m-or);border-color:var(--m-or);color:#fff}
.mfr-core strong{font:800 1.12rem var(--display);color:var(--m-navy)}
.mfr-core em{font-style:normal;font:700 .74rem var(--display);letter-spacing:.12em;color:#9AA3BC}
.mfr .mho-steps__ic{border-color:#F7C38A;color:var(--m-navy)}
.mfr .mho-steps li:last-child .mho-steps__ic{background:var(--m-or);border-color:var(--m-or);color:#fff}
.mfr .mho-steps::after{background:linear-gradient(90deg,var(--m-navy),var(--m-or))}
.mfr .mho-steps__n{color:#B45F08}

/* matching */
.mfr-match{display:grid;grid-template-columns:minmax(0,1.25fr) auto minmax(0,.85fr);gap:24px;align-items:center}
.mfr-match>*{min-width:0}
.mfr-match__col{padding:22px;border-radius:22px;background:var(--h-off);border:1px solid var(--h-line)}
.mfr-match__col h3{display:flex;align-items:center;gap:8px;font-size:1rem}
.mfr-match__col h3 svg{color:#B45F08}
.mfr-match__h2{margin-top:16px!important}
.mfr-match__col ul{list-style:none;margin:8px 0 0;padding:0;display:flex;flex-wrap:wrap;gap:6px}
.mfr-match__col li{padding:5px 10px;border-radius:999px;background:#fff;border:1px solid var(--h-line);font:600 .8rem var(--body);color:var(--h-ink)}
.mfr-match__engine{display:flex;flex-direction:column;align-items:center;gap:4px;width:170px;text-align:center}
.mfr-match__engine svg{width:150px;height:150px}
.mfr-eng__o{fill:none;stroke:#F7C38A;stroke-width:2;stroke-dasharray:4 7;transform-box:fill-box;transform-origin:center;animation:bvSpin 20s linear infinite}
.mfr-eng__m{fill:#FFF1E0}
.mfr-eng__c{fill:var(--m-navy)}
.mfr-eng__t{fill:none;stroke:#fff;stroke-width:5;stroke-linecap:round;stroke-linejoin:round}
.mfr-match__engine strong{font:800 1rem var(--display);color:var(--m-navy)}
.mfr-match__engine em{font-style:normal;font-size:.8rem;color:var(--h-muted)}
.mfr-match__out{padding:22px;border-radius:22px;background:var(--m-navy);color:#fff}
.mfr-match__k{display:block;font:700 .7rem var(--body);letter-spacing:.14em;text-transform:uppercase;color:var(--m-or2);margin-bottom:10px}
.mfr-inv{display:flex;gap:12px;align-items:flex-start;padding:14px;border-radius:14px;background:#ffffff12;color:var(--m-or2)}
.mfr-inv strong{display:block;font:800 .96rem var(--display);color:#fff}
.mfr-inv em{display:block;font-style:normal;font-size:.84rem;color:#C9D3F5}
.mfr-match__out .mho-note{color:#C9D3F5}

/* topics */
.mfr-topics li svg{color:var(--m-navy)!important}
.mfr-topics li:nth-child(3n) svg{color:#B45F08!important}
.mfr-topics li:hover{border-color:#F7C38A}

/* rewards */
.mfr-rw{align-items:start}
.mfr-rwsteps{list-style:none;margin:10px 0 0;padding:0;display:grid;gap:10px;counter-reset:none}
.mfr-rwsteps li{display:flex;gap:14px;align-items:center;padding:12px 14px;border-radius:14px;border:1px solid var(--h-line);background:#fff;font:600 .96rem var(--body);color:var(--h-ink)}
.mfr-rwsteps span{flex:none;display:grid;place-items:center;width:30px;height:30px;border-radius:50%;background:var(--m-navy);color:#fff;font:800 .82rem var(--display)}
.mfr-rwsteps li:last-child span{background:var(--m-or)}
.mfr-rw__side{padding:clamp(22px,3vw,30px);border-radius:24px;background:#FFF7EE;border:1px solid #F7D9B5}
.mfr-pay{list-style:none;margin:12px 0 16px;padding:0;display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}
.mfr-pay li{display:flex;align-items:center;gap:10px;padding:14px;border-radius:14px;background:#fff;border:1px solid #F7D9B5;font:800 .96rem var(--display);color:var(--m-navy)}
.mfr-pay li>span{flex:none;display:grid;place-items:center;width:38px;height:38px;border-radius:11px;background:#FFF1E0;color:#B45F08}
.mfr-thr{display:flex;gap:10px;align-items:flex-start;margin:0;padding:12px 14px;border-radius:14px;background:var(--m-navy);color:#E3E8FA;font-size:.9rem;line-height:1.5}
.mfr-thr svg{flex:none;margin-top:2px;color:var(--m-or2)}
.mfr-thr strong{color:#fff}

/* claim journey */
.mfr-claimsec{background:radial-gradient(640px 320px at 85% 0%,#F28C2833 0%,transparent 60%),linear-gradient(165deg,#13306E,#0B1E4F)}
.mfr-claim{list-style:none;margin:0;padding:0;display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:14px;position:relative}
.mfr-claim::before{content:"";position:absolute;left:8%;right:8%;top:30px;height:2px;background:#ffffff26}
.mfr-claim::after{content:"";position:absolute;left:8%;right:8%;top:30px;height:2px;background:linear-gradient(90deg,#AFC0E6,var(--m-or2));transform-origin:left;transform:scaleX(0);transition:transform 1.6s cubic-bezier(.2,.7,.2,1) .2s}
.mfr-claim.is-in::after{transform:none}
.mfr-claim li{position:relative;z-index:1;opacity:0;translate:0 12px;transition:opacity .5s,translate .5s;transition-delay:calc(var(--i)*140ms + .2s)}
.mfr-claim.is-in li{opacity:1;translate:0 0}
.mfr-claim__ic{display:grid;place-items:center;width:60px;height:60px;border-radius:18px;background:#13306E;border:1.5px solid #ffffff33;color:var(--m-or2);box-shadow:0 0 0 6px #0F2660;margin-bottom:14px}
.mfr-claim li:last-child .mfr-claim__ic{background:var(--m-or);border-color:var(--m-or);color:var(--m-navy)}
.mfr-claim h3{color:#fff}
.mfr-claim p{margin:0;color:#C9D3F5;font-size:.92rem;line-height:1.55}

/* why */
.mfr-why{list-style:none;margin:0;padding:0;display:grid;grid-template-columns:repeat(3,minmax(0,1fr));border-top:1px solid var(--h-line);border-left:1px solid var(--h-line)}
.mfr-why li{padding:26px 24px;border-right:1px solid var(--h-line);border-bottom:1px solid var(--h-line);transition:background .25s}
.mfr-why li:hover{background:var(--h-off)}
.mfr-why li>span{display:grid;place-items:center;width:46px;height:46px;border-radius:14px;background:#FFF1E0;color:#B45F08;margin-bottom:12px}
.mfr-why li:nth-child(even)>span{background:#E6ECFA;color:var(--m-navy)}
.mfr-why p{margin:0;color:var(--h-muted);font-size:.93rem;line-height:1.6}

/* quality */
.mfr-qflow li span{background:var(--m-navy)!important}
.mfr-qflow li:not(:last-child)::after{background:var(--m-or)!important}
.mfr-prac{list-style:none;margin:0;padding:0;display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:8px}
.mfr-prac li{display:flex;align-items:center;gap:8px;padding:12px;border-radius:12px;background:#fff;border:1px solid var(--h-line);font:600 .86rem/1.3 var(--body);color:var(--h-ink)}
.mfr-prac svg{flex:none;color:#B45F08}
.mfr .t2o-priv__list svg{color:var(--m-or2)}
.mfr .t2o-priv__links a{color:#E3E8FA}

/* two communities */
.mfr-two{display:grid;grid-template-columns:minmax(0,1fr) auto minmax(0,1fr);gap:18px;align-items:stretch}
.mfr-two__c{display:flex;flex-direction:column;gap:10px;padding:26px;border-radius:24px;background:#fff;border:1px solid var(--h-line);border-top:4px solid var(--m-navy)}
.mfr-two__c--b{border-top-color:var(--m-or)}
.mfr-two__ic{display:grid;place-items:center;width:52px;height:52px;border-radius:16px;background:#E6ECFA;color:var(--m-navy)}
.mfr-two__c--b .mfr-two__ic{background:#FFF1E0;color:#B45F08}
.mfr-two__c p{margin:0;color:var(--h-muted)}
.mfr-two__c ul{list-style:none;margin:0 0 8px;padding:0;display:flex;flex-wrap:wrap;gap:6px;flex:1;align-content:flex-start}
.mfr-two__c li{padding:6px 11px;border-radius:999px;background:var(--h-off);border:1px solid var(--h-line);font:600 .84rem var(--body);color:var(--h-ink)}
.mfr-two__c .btn{align-self:flex-start}
.mfr-two__link{display:flex;flex-direction:column;align-items:center;justify-content:center;gap:10px;color:#B45F08}
.mfr-two__link span{width:2px;flex:1;max-height:80px;background:repeating-linear-gradient(#F7C38A 0 5px,transparent 5px 10px)}

/* researchers */
.mfr-res{position:relative;padding-block:clamp(56px,7vw,96px);background:linear-gradient(160deg,#0B1E4F,#07104F);color:#fff;border-top:6px solid var(--m-or)}
.mfr-res h2{color:#fff}
.mfr-res__top{display:grid;grid-template-columns:minmax(0,1.3fr) minmax(0,.7fr);gap:clamp(24px,4vw,56px);align-items:center;margin-bottom:clamp(30px,4vw,48px)}
.mfr-res__top>*{min-width:0}
.mfr-res__feat{list-style:none;margin:12px 0 0;padding:0;display:flex;flex-wrap:wrap;gap:8px}
.mfr-res__feat li{display:inline-flex;align-items:center;gap:7px;padding:7px 12px;border-radius:999px;background:#ffffff12;border:1px solid #ffffff26;font:700 .84rem var(--body);color:#fff}
.mfr-res__feat svg{color:var(--m-or2)}
.mfr-res__cta{display:flex;flex-direction:column;gap:12px;padding:24px;border-radius:22px;background:#ffffff0d;border:1px solid #ffffff22}
.mfr-res__cta .btn{justify-content:center}
.mfr-res__cta p{margin:0;font-size:.88rem;color:#C9D3F5}
.mfr-res__cta a:not(.btn),.mfr-res__note a{color:var(--m-or2);font-weight:700}
.mfr-res__grid{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:18px}
.mfr-res__grid>div{padding:26px;border-radius:22px;background:#ffffff0a;border:1px solid #ffffff1c}
.mfr-res__grid h3{color:#fff}
.mfr-res__grid>div>p{margin:0 0 16px;color:#C9D3F5;font-size:.93rem}
.mfr-ppipe{list-style:none;margin:0 0 16px;padding:0;display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:8px}
.mfr-ppipe li{display:flex;align-items:center;gap:8px;padding:10px;border-radius:12px;background:#ffffff10;font:700 .84rem/1.25 var(--body);color:#fff;opacity:0;translate:0 8px;transition:opacity .45s,translate .45s;transition-delay:calc(var(--i)*110ms)}
.mfr-ppipe.is-in li{opacity:1;translate:0 0}
.mfr-ppipe span{flex:none;display:grid;place-items:center;width:24px;height:24px;border-radius:50%;background:var(--m-or);color:var(--m-navy);font:800 .74rem var(--display)}
.mfr-pm{list-style:none;margin:0;padding:0;display:flex;flex-wrap:wrap;gap:6px}
.mfr-pm li{padding:5px 10px;border-radius:999px;border:1px solid #ffffff2a;font:600 .8rem var(--body);color:#E3E8FA}
.mfr-rflow{list-style:none;margin:6px 0 0;padding:0;display:grid;gap:6px;position:relative}
.mfr-rflow::before{content:"";position:absolute;left:19px;top:16px;bottom:16px;width:2px;background:#ffffff26}
.mfr-rflow li{position:relative;display:flex;align-items:center;gap:14px;padding:6px 0;font:700 .95rem var(--body);color:#fff;opacity:0;translate:-8px 0;transition:opacity .45s,translate .45s;transition-delay:calc(var(--i)*100ms)}
.mfr-rflow.is-in li{opacity:1;translate:0 0}
.mfr-rflow span{position:relative;z-index:1;flex:none;display:grid;place-items:center;width:40px;height:40px;border-radius:12px;background:#13306E;border:1px solid #ffffff33;color:var(--m-or2);font:800 .8rem var(--display)}
.mfr-rflow li:last-child span{background:var(--m-or);color:var(--m-navy);border-color:var(--m-or)}
.mfr-res__note{margin:14px 0 0;font-size:.86rem;color:#C9D3F5}

/* final */
.mfr-cta{background:radial-gradient(600px 300px at 50% 0%,#F28C2840 0%,transparent 70%),linear-gradient(160deg,#13306E,#0B1E4F)}
.mfr .t2o-cta__res a{color:var(--m-or2)}
.mfr-cta__s{margin-top:18px!important;font-size:.85rem!important;color:#AFC0E6!important}
.mfr-cta__s a{color:#fff}

@media (max-width:1100px){
  .mfr-prac{grid-template-columns:repeat(3,minmax(0,1fr))}
  .mfr-claim{grid-template-columns:repeat(3,minmax(0,1fr));row-gap:24px}
  .mfr-claim::before,.mfr-claim::after{display:none}
}
@media (max-width:900px){
  .mfr-match,.mfr-res__top,.mfr-res__grid{grid-template-columns:1fr}
  .mfr-match__engine{width:auto;margin:0 auto}
  .mfr-two{grid-template-columns:1fr}
  .mfr-two__link{flex-direction:row;height:40px}
  .mfr-two__link span{width:auto;height:2px;flex:1;max-height:none;max-width:80px;background:repeating-linear-gradient(90deg,#F7C38A 0 5px,transparent 5px 10px)}
  .mfr-why{grid-template-columns:1fr 1fr}
  .mfr-art{max-width:460px;margin:0 auto}
}
@media (max-width:640px){
  .mfr-strip ul{justify-content:flex-start}
  .mfr-core{grid-template-columns:1fr;gap:12px}
  .mfr-core::before,.mfr-core::after{left:44px;right:auto;top:20px;bottom:20px;width:3px;height:auto}
  .mfr-core::after{transform-origin:top;transform:scaleY(0)}
  .mfr-core.is-in::after{transform:none}
  .mfr-core li{flex-direction:row;gap:16px}
  .mfr-core__ic{width:72px;height:72px;border-radius:22px;flex:none}
  .mfr-core em{margin-left:auto}
  .mfr-pay,.mfr-why,.mfr-prac,.mfr-ppipe,.mfr-claim{grid-template-columns:1fr}
  .mfr-card{padding:10px 12px}
  .mfr-ln{width:80px}
  .mfr-card--reward strong{font-size:.82rem}
  .mfr-card__k{font-size:.58rem}
}
@media (prefers-reduced-motion:reduce){
  .mfr *{animation:none!important;transition:none!important}
  .mfr-card,.mfr-core li,.mfr-claim li,.mfr-ppipe li,.mfr-rflow li{opacity:1!important;translate:none!important}
  .mfr-core::after,.mfr-claim::after{transform:none}
  .mfr-ring--on{stroke-dashoffset:30}
  .mfr-art__dot{display:none}
}

/* ===== About page redesign (ab-) ===== */
.ab{--a-ink:#07104F;--a-royal:#0B22A8;--a-bright:#1E5BFF;--a-teal:#0E9C88;--a-teal2:#6EE0CE;--a-gold:#C99A2E;--a-gold2:#F0D98F;--a-line:#DDE2EC;--a-muted:#525C78;--a-paper:#F5F7FB;
  position:relative;padding-block:clamp(64px,8vw,112px);color:var(--a-ink)}
.ab .sr-only{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0 0 0 0)}
.ab-head{max-width:820px;margin-bottom:clamp(32px,4vw,52px)}
.ab-k{display:inline-flex;align-items:center;gap:10px;font:700 .76rem var(--body);letter-spacing:.18em;text-transform:uppercase;color:var(--a-teal);margin-bottom:12px}
.ab-k i{width:28px;height:2px;border-radius:2px;background:linear-gradient(90deg,var(--a-teal),var(--a-bright))}
.ab-k--light{color:var(--a-teal2)}
.ab h2{font:800 clamp(1.9rem,3.6vw,2.9rem)/1.12 var(--display);letter-spacing:-.02em;margin:0 0 14px;color:var(--a-ink)}
.ab h3{font:800 1.2rem/1.3 var(--display);margin:0 0 8px;color:var(--a-ink)}
.ab-lead{font-size:1.08rem;line-height:1.7;color:var(--a-muted);margin:0}
.ab-lead strong{color:var(--a-ink)}
.ab-tile__k{display:block;font:700 .7rem var(--body);letter-spacing:.16em;text-transform:uppercase;color:var(--a-teal);margin-bottom:8px}
.ab-links{font-size:.9rem;color:var(--a-muted)}
.ab-links a{color:var(--a-royal);font-weight:700}

/* bento */
.ab-ov{background:linear-gradient(180deg,#fff 0%,var(--a-paper) 100%)}
.ab-bento{display:grid;grid-template-columns:repeat(12,minmax(0,1fr));gap:16px}
.ab-tile{position:relative;overflow:hidden;padding:24px;border-radius:24px;background:#fff;border:1px solid var(--a-line);box-shadow:0 20px 40px -34px #07104F66;opacity:0;translate:0 18px;transition:opacity .7s,translate .7s,box-shadow .3s}
.ab-ov.is-in .ab-tile{opacity:1;translate:0 0}
.ab-tile:nth-child(2){transition-delay:.1s}.ab-tile:nth-child(3){transition-delay:.2s}.ab-tile:nth-child(4){transition-delay:.3s}
.ab-tile:hover{box-shadow:0 30px 50px -30px #07104F80}
.ab-tile--year{grid-column:span 3;background:linear-gradient(160deg,#0B22A8,#07104F);color:#fff;border:0}
.ab-tile--year .ab-tile__k{color:var(--a-teal2)}
.ab-tile--year p{margin:8px 0 0;color:#C9D3F5;font-size:.92rem}
.ab-year{display:flex;gap:4px;font:800 clamp(2.6rem,4.4vw,3.6rem)/1 var(--display);letter-spacing:-.02em}
.ab-year span{display:inline-block;min-width:.6em;padding:6px 4px;border-radius:10px;background:#ffffff14;text-align:center}
.ab-tile--globe{grid-column:span 5;display:grid;grid-template-columns:150px minmax(0,1fr);gap:18px;align-items:center;background:#07104F;color:#fff;border:0}
.ab-globe{width:150px;aspect-ratio:1;border-radius:50%;overflow:hidden}
.ab-globe .hg-canvas{display:block;width:100%;height:100%}
.ab-tile--globe .ab-tile__k{color:var(--a-teal2)}
.ab-tile--globe strong{display:block;font:800 1.25rem/1.25 var(--display)}
.ab-tile--globe p{margin:8px 0 0;color:#C9D3F5;font-size:.92rem}
.ab-tile--globe b{color:var(--a-gold2)}
.ab-tile--full{grid-column:span 4}
.ab-pill3{list-style:none;margin:6px 0 0;padding:0;display:grid;gap:10px}
.ab-pill3 li{position:relative;display:flex;align-items:center;gap:12px;padding:12px 14px;border-radius:14px;background:var(--a-paper);font:800 1rem var(--display);overflow:hidden}
.ab-pill3 li>span{display:grid;place-items:center;width:36px;height:36px;border-radius:11px;background:#E8EEFF;color:var(--a-royal)}
.ab-pill3 li:nth-child(2)>span{background:#E3F5F2;color:var(--a-teal)}.ab-pill3 li:nth-child(3)>span{background:#FBF3E0;color:#8A6513}
.ab-pill3 li i{position:absolute;left:0;bottom:0;height:3px;width:100%;background:linear-gradient(90deg,var(--a-bright),var(--a-teal2));transform-origin:left;scale:0 1;transition:scale 1s cubic-bezier(.2,.7,.2,1);transition-delay:calc(var(--i)*.2s + .5s)}
.ab-ov.is-in .ab-pill3 li i{scale:1 1}
.ab-tile--iso{grid-column:span 12}
.ab-seals{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:16px}
.ab-seals figure{margin:0;display:flex;align-items:center;gap:14px}
.ab-seals figcaption{display:flex;flex-direction:column;font-size:.86rem;color:var(--a-muted)}
.ab-seals figcaption strong{font:800 1rem var(--display);color:var(--a-ink)}
.ab-seal{position:relative;flex:none;display:grid;place-items:center;width:68px;height:68px}
.ab-seal img{width:100%;height:100%;border-radius:50%;background:#fff}
.ab-seal i{position:absolute;inset:-6px;border-radius:50%;border:1.5px dashed #1E5BFF55;animation:abSpin 16s linear infinite}
.ab-seal i::after{content:"";position:absolute;top:-3px;left:50%;width:6px;height:6px;margin-left:-3px;border-radius:50%;background:var(--a-teal);box-shadow:0 0 8px var(--a-teal2)}
.ab-seal--lg{width:96px;height:96px}
@keyframes abSpin{to{rotate:360deg}}

/* converge */
.ab-row{display:grid;grid-template-columns:minmax(0,.8fr) minmax(0,1.2fr);gap:clamp(24px,4vw,56px);align-items:center;margin-top:clamp(48px,6vw,80px)}
.ab-row>*{min-width:0}
.ab-row__copy p{color:var(--a-muted);font-size:1rem;line-height:1.7;margin:0}
.ab-conv{display:grid;grid-template-columns:minmax(0,1fr) 110px minmax(0,.8fr);align-items:center}
.ab-conv__in{list-style:none;margin:0;padding:0;display:grid;gap:10px}
.ab-conv__in li{display:flex;align-items:center;gap:10px;padding:12px 14px;border-radius:14px;background:#fff;border:1px solid var(--a-line);font:700 .9rem/1.3 var(--body);opacity:0;translate:-12px 0;transition:opacity .5s,translate .5s;transition-delay:calc(var(--i)*.12s)}
.ab-conv.is-in .ab-conv__in li{opacity:1;translate:0 0}
.ab-conv__in li>span{flex:none;display:grid;place-items:center;width:32px;height:32px;border-radius:10px;background:#E8EEFF;color:var(--a-royal)}
.ab-conv__svg{width:100%;height:260px}
.ab-conv__p{fill:none;stroke:#B9CBFB;stroke-width:2;stroke-dasharray:4 6;vector-effect:non-scaling-stroke}
.ab-conv.is-in .ab-conv__p{animation:rcDash 1.6s linear infinite}
.ab-conv__d{fill:var(--a-bright);offset-rotate:0deg;opacity:0;animation:abTravel 3s ease-in-out infinite;animation-delay:calc(var(--i)*.5s)}
@keyframes abTravel{0%{offset-distance:0%;opacity:0}10%,85%{opacity:1}100%{offset-distance:100%;opacity:0}}
.ab-conv__out{display:flex;flex-direction:column;align-items:center;gap:12px;text-align:center;padding:24px 18px;border-radius:24px;background:linear-gradient(160deg,#0B22A8,#07104F);color:#fff;box-shadow:0 30px 60px -30px #0B22A8aa}
.ab-conv__core{position:relative;display:grid;place-items:center;width:64px;height:64px;border-radius:50%;background:#ffffff14;color:var(--a-gold2)}
.ab-conv__core::after{content:"";position:absolute;inset:0;border-radius:50%;border:2px solid var(--a-gold2);animation:abPing 2.6s ease-out infinite}
@keyframes abPing{0%{opacity:.8;scale:1}100%{opacity:0;scale:1.7}}
.ab-conv__out strong{font:800 1.02rem/1.35 var(--display)}

/* triad */
.ab-triad{display:grid;grid-template-columns:repeat(3,minmax(0,1fr)) auto minmax(0,1.1fr);gap:12px;align-items:stretch;margin-top:clamp(36px,5vw,56px)}
.ab-triad>*{min-width:0}
.ab-triad__in{display:flex;flex-direction:column;gap:10px;justify-content:center;padding:18px;border-radius:18px;background:#fff;border:1px solid var(--a-line);font:800 .98rem/1.3 var(--display);color:var(--a-ink)}
.ab-triad__in svg{color:var(--a-teal)}
.ab-triad__in+.ab-triad__in{position:relative}
.ab-triad__in+.ab-triad__in::before{content:"+";position:absolute;left:-12px;top:50%;translate:-50% -50%;width:22px;height:22px;display:grid;place-items:center;border-radius:50%;background:var(--a-ink);color:#fff;font:800 .9rem var(--display)}
.ab-triad__eq{align-self:center;font:800 1.8rem var(--display);color:var(--a-bright)}
.ab-triad__out{padding:18px 20px;border-radius:18px;background:#07104F;color:#fff}
.ab-triad__out span{display:block;font:700 .74rem var(--body);letter-spacing:.14em;text-transform:uppercase;color:var(--a-teal2);margin-bottom:8px}
.ab-triad__out ul{list-style:none;margin:0;padding:0;display:flex;flex-wrap:wrap;gap:8px}
.ab-triad__out li{display:inline-flex;align-items:center;gap:6px;padding:6px 12px;border-radius:999px;background:#ffffff14;font:800 .92rem var(--display);animation:abGlow 3s ease-in-out infinite;animation-delay:calc(var(--i)*1s)}
.ab-triad__out li svg{color:var(--a-gold2)}
@keyframes abGlow{0%,100%{background:#ffffff14}30%{background:#1E5BFF66}}

/* lifecycle */
.ab-block{margin-top:clamp(48px,6vw,80px)}
.ab-block__h{display:flex;flex-wrap:wrap;align-items:baseline;justify-content:space-between;gap:8px 24px;margin-bottom:18px}
.ab-block__h p{margin:0;color:var(--a-muted)}
.ab-life{position:relative;padding:28px 22px;border-radius:26px;background:linear-gradient(160deg,#07104F,#0B22A8);overflow:hidden}
.ab-life ol{list-style:none;margin:0;padding:0;display:grid;grid-template-columns:repeat(8,minmax(0,1fr));gap:8px;position:relative}
.ab-life ol::before{content:"";position:absolute;left:5%;right:5%;top:28px;height:2px;background:#ffffff26}
.ab-life ol::after{content:"";position:absolute;left:5%;right:5%;top:28px;height:2px;background:linear-gradient(90deg,var(--a-teal2),var(--a-gold2));transform-origin:left;scale:0 1;transition:scale 2s cubic-bezier(.2,.7,.2,1) .2s}
.ab-life.is-in ol::after{scale:1 1}
.ab-life li{position:relative;z-index:1;display:flex;flex-direction:column;align-items:center;gap:6px;text-align:center;opacity:0;translate:0 10px;transition:opacity .5s,translate .5s;transition-delay:calc(var(--i)*.14s + .2s)}
.ab-life.is-in li{opacity:1;translate:0 0}
.ab-life__ic{display:grid;place-items:center;width:56px;height:56px;border-radius:50%;background:#0A1A7A;border:2px solid #5D86FF80;color:var(--a-teal2);box-shadow:0 0 0 6px #0A1A7A;transition:background .3s,transform .3s}
.ab-life li:hover .ab-life__ic{transform:translateY(-4px);background:var(--a-bright);color:#fff}
.ab-life li:last-child .ab-life__ic{background:var(--a-gold2);border-color:var(--a-gold2);color:#07104F}
.ab-life__n{font:800 .7rem var(--display);letter-spacing:.1em;color:#8FB0FF}
.ab-life strong{font:700 .86rem/1.3 var(--body);color:#fff}
.ab-life__pulse{position:absolute;top:56px;left:5%;width:10px;height:10px;margin:-5px 0 0 -5px;border-radius:50%;background:#fff;box-shadow:0 0 14px 4px #6EE0CE;opacity:0}
.ab-life.is-in .ab-life__pulse{animation:abRun 6s ease-in-out 2.2s infinite}
@keyframes abRun{0%{left:5%;opacity:0}8%{opacity:1}90%{opacity:1}100%{left:95%;opacity:0}}

/* matrix + beyond */
.ab-split2{display:grid;grid-template-columns:minmax(0,1.1fr) minmax(0,.9fr);gap:clamp(20px,3vw,40px);margin-top:clamp(48px,6vw,80px);align-items:start}
.ab-split2>*{min-width:0}
.ab-split2>div>p{color:var(--a-muted);margin:0 0 16px}
.ab-mx{border-radius:20px;background:#fff;border:1px solid var(--a-line);overflow:hidden}
.ab-mx>div{display:grid;grid-template-columns:minmax(0,1.1fr) repeat(3,minmax(0,1fr));border-top:1px solid var(--a-line)}
.ab-mx>div:first-child{border-top:0}
.ab-mx>div>*{padding:14px;display:flex;align-items:center;justify-content:center;text-align:center}
.ab-mx__h span{font:700 .78rem/1.3 var(--body);color:var(--a-muted);background:var(--a-paper)}
.ab-mx strong{justify-content:flex-start!important;gap:8px;font:800 .98rem var(--display)}
.ab-mx strong svg{color:var(--a-royal)}
.ab-mx__dot{display:grid;place-items:center;width:30px;height:30px;border-radius:50%;background:var(--a-teal);color:#fff;scale:0;transition:scale .45s cubic-bezier(.3,1.5,.5,1);transition-delay:calc(var(--i)*.08s + .2s)}
.ab-mx.is-in .ab-mx__dot{scale:1}
.ab-beyond{padding:24px;border-radius:24px;background:linear-gradient(160deg,#F5F7FB,#EAF0FF);border:1px solid var(--a-line)}
.ab-beyond__flow{display:grid;grid-template-columns:auto 60px minmax(0,1fr);align-items:center;gap:6px;margin-top:12px}
.ab-beyond__src{display:grid;gap:40px}
.ab-beyond__src span{display:flex;align-items:center;gap:8px;padding:10px 12px;border-radius:12px;background:#07104F;color:#fff;font:800 .88rem var(--display)}
.ab-beyond__src svg{color:var(--a-gold2)}
.ab-beyond__svg{width:60px;height:150px}
.ab-beyond__svg path{fill:none;stroke:#9DB7FF;stroke-width:2;stroke-dasharray:4 5;animation:rcDash 1.8s linear infinite}
.ab-beyond__out{list-style:none;margin:0;padding:0;display:grid;gap:10px}
.ab-beyond__out li{display:flex;align-items:center;gap:8px;padding:10px 12px;border-radius:12px;background:#fff;border:1px solid var(--a-line);font:700 .86rem/1.3 var(--body)}
.ab-beyond__out svg{flex:none;color:var(--a-teal)}

/* ---------- Mission & Vision ---------- */
.ab-mv{overflow:hidden;color:#fff;background:radial-gradient(700px 420px at 15% 20%,#1E5BFF33 0%,transparent 60%),radial-gradient(600px 400px at 90% 90%,#0E9C882e 0%,transparent 60%),linear-gradient(160deg,#0B22A8,#07104F 70%);transition:background .6s}
.ab-mv--vision{background:radial-gradient(700px 420px at 15% 20%,#C99A2E30 0%,transparent 60%),radial-gradient(600px 400px at 90% 90%,#5A3FE033 0%,transparent 60%),linear-gradient(160deg,#1A1466,#07104F 70%)}
.ab-mv h2{color:#fff}
.ab-mv__bg span{position:absolute;border-radius:50%;border:1px solid #ffffff12;pointer-events:none}
.ab-mv__bg span:nth-child(1){width:900px;height:900px;right:-300px;top:-300px}
.ab-mv__bg span:nth-child(2){width:600px;height:600px;left:-220px;bottom:-260px}
.ab-mv .container{position:relative;z-index:1}
.ab-mv__top{display:flex;flex-wrap:wrap;align-items:flex-end;justify-content:space-between;gap:20px;margin-bottom:clamp(28px,4vw,44px)}
.ab-mv__toggle{position:relative;display:grid;grid-template-columns:1fr 1fr;padding:6px;border-radius:20px;background:#ffffff12;border:1px solid #ffffff26;min-width:min(420px,100%)}
.ab-mv__toggle button{position:relative;z-index:1;display:flex;flex-direction:column;align-items:flex-start;gap:2px;padding:12px 18px;border:0;border-radius:15px;background:transparent;color:#C9D3F5;cursor:pointer;text-align:left;transition:color .3s}
.ab-mv__toggle button strong{font:800 1.05rem var(--display)}
.ab-mv__toggle button em{font-style:normal;font-size:.8rem;opacity:.85}
.ab-mv__toggle button.is-on{color:#07104F}
.ab-mv__toggle button:focus-visible{outline:2px solid var(--a-gold2);outline-offset:2px}
.ab-mv__thumb{position:absolute;top:6px;bottom:6px;left:6px;width:calc(50% - 6px);border-radius:15px;background:#fff;transition:translate .45s cubic-bezier(.2,.7,.2,1),background .45s}
.ab-mv--vision .ab-mv__thumb{translate:100% 0;background:var(--a-gold2)}
.ab-mv__stage{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:clamp(24px,4vw,56px);align-items:center}
.ab-mv__stage>*{min-width:0}
.ab-orbit{position:relative;width:100%;max-width:520px;aspect-ratio:1;margin:0 auto}
.ab-orbit__plane{position:absolute;inset:6%;perspective:900px}
.ab-orbit__plane span{position:absolute;inset:0;border-radius:50%;border:1.5px solid #ffffff22}
.ab-orbit__plane span:nth-child(1){animation:abTilt 14s linear infinite}
.ab-orbit__plane span:nth-child(2){inset:12%;border-style:dashed;border-color:#6EE0CE55;animation:abTilt 20s linear infinite reverse}
.ab-orbit__plane span:nth-child(3){inset:-4%;border-color:#ffffff10}
.ab-mv--vision .ab-orbit__plane span:nth-child(2){border-color:#F0D98F66}
@keyframes abTilt{from{transform:rotateX(64deg) rotateZ(0)}to{transform:rotateX(64deg) rotateZ(360deg)}}
.ab-orbit__lines{position:absolute;inset:0;width:100%;height:100%}
.ab-orbit__lines line{stroke:#ffffff1f;stroke-width:.4;stroke-dasharray:1 1.5;transition:stroke .3s}
.ab-orbit__lines line.is-on{stroke:var(--a-teal2);stroke-width:.6;stroke-dasharray:none}
.ab-mv--vision .ab-orbit__lines line.is-on{stroke:var(--a-gold2)}
.ab-orbit__core{position:absolute;left:50%;top:50%;translate:-50% -50%;z-index:2;display:flex;flex-direction:column;align-items:center;justify-content:center;width:34%;aspect-ratio:1;border-radius:50%;background:radial-gradient(circle at 35% 30%,#3A6BFF,#0B22A8 60%,#07104F);box-shadow:0 0 0 10px #ffffff0d,0 0 0 22px #ffffff08,0 30px 60px -20px #000a;transition:background .5s}
.ab-mv--vision .ab-orbit__core{background:radial-gradient(circle at 35% 30%,#F6E2A6,#C99A2E 55%,#6B4E10)}
.ab-orbit__core strong{font:800 clamp(1.2rem,2.2vw,1.6rem) var(--display);color:#fff}
.ab-orbit__core em{font-style:normal;font:700 .74rem var(--body);letter-spacing:.16em;text-transform:uppercase;color:#ffffffc0}
.ab-orbit__core::after{content:"";position:absolute;inset:-6px;border-radius:50%;border:2px solid #ffffff40;animation:abPing 3s ease-out infinite}
.ab-orbit__n{position:absolute;z-index:3;translate:-50% -50%;display:flex;flex-direction:column;align-items:center;gap:6px;border:0;background:none;cursor:pointer;color:#fff;padding:0;opacity:0;scale:.6;transition:opacity .5s,scale .5s;transition-delay:calc(var(--i)*.1s)}
.ab-mv.is-in .ab-orbit__n{opacity:1;scale:1}
.ab-orbit__n span{display:grid;place-items:center;width:58px;height:58px;border-radius:18px;background:#ffffff14;border:1.5px solid #ffffff33;color:var(--a-teal2);transition:background .3s,transform .3s,box-shadow .3s,color .3s}
.ab-mv--vision .ab-orbit__n span{color:var(--a-gold2)}
.ab-orbit__n em{font-style:normal;font:700 .8rem var(--body);color:#C9D3F5;white-space:nowrap}
.ab-orbit__n.is-on span{background:#fff;color:#0B22A8;transform:scale(1.15);box-shadow:0 0 0 8px #ffffff1a,0 16px 30px -10px #000a}
.ab-mv--vision .ab-orbit__n.is-on span{background:var(--a-gold2);color:#3A2C06}
.ab-orbit__n.is-on em{color:#fff}
.ab-orbit__n:focus-visible span{outline:2px solid var(--a-gold2);outline-offset:3px}
.ab-mv__card{position:relative;padding:clamp(24px,3vw,34px);border-radius:28px;background:#ffffff0f;border:1px solid #ffffff24;animation:abIn .5s cubic-bezier(.2,.7,.2,1) both}
@keyframes abIn{from{opacity:0;translate:0 14px}to{opacity:1;translate:0 0}}
.ab-mv__num{position:absolute;top:24px;right:26px;font:800 1.4rem var(--display);color:#ffffff40}
.ab-mv__num i{font-style:normal;font-size:.9rem}
.ab-mv__ic{display:grid;place-items:center;width:64px;height:64px;border-radius:20px;background:linear-gradient(135deg,#1E5BFF,#0E9C88);color:#fff;margin-bottom:18px}
.ab-mv--vision .ab-mv__ic{background:linear-gradient(135deg,#C99A2E,#5A3FE0)}
.ab-mv__card h3{color:#fff;font-size:clamp(1.3rem,2vw,1.6rem)}
.ab-mv__card>p{margin:0 0 20px;color:#D6DEF7;font-size:1.06rem;line-height:1.65}
.ab-mv__prog{display:flex;gap:6px;margin-bottom:18px}
.ab-mv__prog i{flex:1;height:4px;border-radius:2px;background:#ffffff22;overflow:hidden;position:relative}
.ab-mv__prog i.is-done{background:#ffffff66}
.ab-mv__prog i.is-on::after{content:"";position:absolute;inset:0;background:var(--a-teal2);transform-origin:left;animation:abBar 3.6s linear forwards}
.ab-mv--vision .ab-mv__prog i.is-on::after{background:var(--a-gold2)}
@keyframes abBar{from{scale:0 1}to{scale:1 1}}
.ab-mv__all{list-style:none;margin:0;padding:0;display:grid;gap:4px}
.ab-mv__all button{width:100%;text-align:left;padding:8px 10px;border:0;border-radius:10px;background:transparent;color:#AFC0E6;font:600 .9rem var(--body);cursor:pointer;transition:background .2s,color .2s}
.ab-mv__all li.is-on button{background:#ffffff14;color:#fff}
.ab-mv__all button:focus-visible{outline:2px solid var(--a-gold2)}

/* ---------- What makes us different ---------- */
.ab-diff{color:#fff;background:radial-gradient(800px 420px at 85% 10%,#1E6BFF33 0%,transparent 60%),linear-gradient(170deg,#07104F,#0A1660 60%,#07104F);overflow:hidden}
.ab-diff h2,.ab-diff h3{color:#fff}
.ab-align{display:grid;grid-template-columns:minmax(0,.9fr) minmax(0,1.1fr);gap:clamp(24px,4vw,56px);align-items:center}
.ab-align>*{min-width:0}
.ab-align__steps{list-style:none;margin:0;padding:0;display:grid;gap:14px}
.ab-align__steps li{display:flex;gap:14px;align-items:flex-start;padding:18px;border-radius:18px;background:#ffffff0d;border:1px solid #ffffff1f}
.ab-align__steps span{flex:none;display:grid;place-items:center;width:36px;height:36px;border-radius:50%;background:var(--a-gold2);color:#07104F;font:800 .95rem var(--display)}
.ab-align__steps strong{display:block;font:800 1.08rem var(--display)}
.ab-align__steps em{display:block;font-style:normal;color:#C9D3F5;font-size:.94rem}
.ab-align__viz{position:relative;height:340px}
.ab-align__viz>svg{position:absolute;inset:0;width:100%;height:100%}
.ab-align__viz>svg circle{fill:none;stroke:#ffffff26;stroke-width:.4;stroke-dasharray:1 1.6;vector-effect:non-scaling-stroke}
.ab-align__core{position:absolute;left:50%;top:50%;translate:-50% -50%;z-index:2;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:6px;width:150px;height:150px;border-radius:50%;background:radial-gradient(circle at 35% 30%,#3A6BFF,#0B22A8 60%,#07104F);box-shadow:0 0 0 12px #ffffff0a,0 30px 60px -20px #000a;text-align:center;color:var(--a-gold2)}
.ab-align__core strong{font:800 .95rem/1.25 var(--display);color:#fff;padding:0 10px}
.ab-align__core::after{content:"";position:absolute;inset:-8px;border-radius:50%;border:2px solid #F0D98F55;animation:abPing 3s ease-out infinite}
.ab-align__sat{position:absolute;z-index:3;display:flex;align-items:center;gap:8px;padding:10px 14px;border-radius:14px;background:#fff;color:#07104F;font:800 .86rem var(--display);box-shadow:0 18px 30px -18px #000a;white-space:nowrap;transition:left 1.1s cubic-bezier(.2,.7,.2,1),top 1.1s cubic-bezier(.2,.7,.2,1),opacity .8s;transition-delay:calc(var(--i)*.12s)}
.ab-align__sat svg{position:static;width:18px;height:18px;flex:none;color:var(--a-teal)}
.ab-align__sat--0{left:2%;top:0}.ab-align__sat--1{left:68%;top:4%}.ab-align__sat--2{left:4%;top:84%}.ab-align__sat--3{left:62%;top:86%}
.ab-align.is-in .ab-align__sat--0{left:50%;top:10%;translate:-50% 0}
.ab-align.is-in .ab-align__sat--1{left:84%;top:46%;translate:-50% 0}
.ab-align.is-in .ab-align__sat--2{left:50%;top:80%;translate:-50% 0}
.ab-align.is-in .ab-align__sat--3{left:16%;top:46%;translate:-50% 0}
.ab-align__sat{opacity:.45}.ab-align.is-in .ab-align__sat{opacity:1}

.ab-team{display:grid;grid-template-columns:minmax(0,1.4fr) minmax(0,.6fr);gap:16px;margin-top:clamp(40px,5vw,64px)}
.ab-team>*{min-width:0}
.ab-team__people{padding:24px;border-radius:22px;background:#ffffff0a;border:1px solid #ffffff1f}
.ab-team__people ul{list-style:none;margin:14px 0 0;padding:0;display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:10px;position:relative}
.ab-team__people ul::before{content:"";position:absolute;left:10%;right:10%;top:28px;height:2px;background:repeating-linear-gradient(90deg,#6EE0CE88 0 6px,transparent 6px 12px);animation:abSlide 2s linear infinite}
@keyframes abSlide{to{background-position:24px 0}}
.ab-team__people li{position:relative;display:flex;flex-direction:column;align-items:center;gap:8px;text-align:center;font:700 .86rem/1.3 var(--body);color:#E3E8FA}
.ab-team__people li>span{display:grid;place-items:center;width:56px;height:56px;border-radius:50%;background:#0A1A7A;border:2px solid #6EE0CE80;color:var(--a-teal2);box-shadow:0 0 0 6px #0A1660;animation:abBob 4s ease-in-out infinite;animation-delay:calc(var(--i)*.4s)}
@keyframes abBob{0%,100%{translate:0 0}50%{translate:0 -5px}}
.ab-team__proc{padding:24px;border-radius:22px;background:linear-gradient(160deg,#C99A2E26,#ffffff08);border:1px solid #F0D98F40}
.ab-team__proc .ab-tile__k{color:var(--a-gold2)}
.ab-team__proc ul{list-style:none;margin:0;padding:0;display:grid;gap:8px}
.ab-team__proc li{display:flex;align-items:center;gap:8px;font:700 .92rem var(--body);color:#fff}
.ab-team__proc li svg{color:var(--a-gold2)}

.ab-dx{margin-top:clamp(40px,5vw,64px)}
.ab-dx__h{margin-bottom:16px!important}
.ab-dx__in{display:grid;grid-template-columns:minmax(0,.75fr) minmax(0,1.25fr);gap:18px;align-items:stretch}
.ab-dx__in>*{min-width:0}
.ab-dx__list{display:grid;gap:8px}
.ab-dx__list button{position:relative;display:flex;align-items:center;gap:12px;padding:14px 16px;border-radius:16px;border:1px solid #ffffff1f;background:#ffffff08;color:#C9D3F5;font:800 .98rem var(--display);text-align:left;cursor:pointer;overflow:hidden;transition:background .3s,color .3s,border-color .3s}
.ab-dx__list button>span{flex:none;display:grid;place-items:center;width:38px;height:38px;border-radius:12px;background:#ffffff12;color:var(--a-teal2);transition:background .3s,color .3s}
.ab-dx__list button.is-on{background:#fff;color:#07104F;border-color:#fff}
.ab-dx__list button.is-on>span{background:#07104F;color:var(--a-gold2)}
.ab-dx__list button i{position:absolute;left:0;bottom:0;height:3px;width:100%;background:linear-gradient(90deg,var(--a-teal),var(--a-bright));transform-origin:left;scale:0 1}
.ab-dx__list button.is-on i{animation:abBar 5.2s linear forwards}
.ab-dx__list button:focus-visible{outline:2px solid var(--a-gold2);outline-offset:2px}
.ab-dx__panel{position:relative;padding:clamp(24px,3vw,34px);border-radius:24px;background:linear-gradient(160deg,#ffffff14,#ffffff06);border:1px solid #ffffff26;animation:abIn .5s cubic-bezier(.2,.7,.2,1) both}
.ab-dx__n{position:absolute;top:20px;right:24px;font:800 3rem/1 var(--display);color:#ffffff14}
.ab-dx__panel h4{display:flex;align-items:center;gap:10px;font:800 1.4rem var(--display);margin:0 0 8px;color:#fff}
.ab-dx__panel h4 svg{color:var(--a-gold2)}
.ab-dx__panel>p{margin:0 0 18px;color:#C9D3F5}
.ab-dv{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:18px;align-items:center}
.ab-dv>*{min-width:0}
.ab-dv svg{width:100%;max-width:240px;margin:0 auto;display:block}
.ab-dv ul{list-style:none;margin:0;padding:0;display:grid;gap:8px}
.ab-dv ul li{display:flex;align-items:center;gap:10px;padding:10px 14px;border-radius:12px;background:#ffffff0f;border:1px solid #ffffff1f;font:700 .92rem var(--body);color:#fff;opacity:0;translate:10px 0;animation:abInR .45s ease forwards;animation-delay:calc(var(--k)*.12s + .15s)}
.ab-dv ul li::before{content:"";width:8px;height:8px;border-radius:50%;background:var(--a-teal2)}
@keyframes abInR{to{opacity:1;translate:0 0}}
.ab-gear circle{fill:none;stroke:var(--a-teal2);stroke-width:10;stroke-dasharray:8 6}
.ab-gear circle.h{fill:#ffffff14;stroke:none}
.ab-gear--a{transform-box:fill-box;transform-origin:center;animation:abSpin 8s linear infinite}
.ab-gear--b{transform-box:fill-box;transform-origin:center;animation:abSpin 6s linear infinite reverse}
.ab-gear--b circle{stroke:var(--a-gold2)}
.ab-dv text{font:700 11px var(--body);fill:#C9D3F5}
.ab-dv--globe .o{fill:#0A1A7A;stroke:#7FB0FF66}
.ab-dv--globe .g{fill:none;stroke:#ffffff22}
.ab-dv--globe .ab-spin{transform-box:fill-box;transform-origin:center;animation:abSpinY 8s linear infinite}
@keyframes abSpinY{from{scale:1 1}50%{scale:.2 1}to{scale:1 1}}
.ab-dv--globe .arc{fill:none;stroke:var(--a-teal2);stroke-width:1.5;stroke-dasharray:4 5;animation:rcDash 1.6s linear infinite}
.ab-dv--globe .n{fill:var(--a-gold2);transform-box:fill-box;transform-origin:center;animation:abNode 2.4s ease-in-out infinite;animation-delay:calc(var(--k)*.3s)}
@keyframes abNode{0%,100%{scale:1}50%{scale:1.5}}
.ab-dv--pipe{grid-template-columns:1fr}
.ab-dv--pipe ol{list-style:none;margin:0;padding:0;display:grid;grid-template-columns:repeat(7,minmax(0,1fr));gap:6px;position:relative}
.ab-dv--pipe ol::before{content:"";position:absolute;left:6%;right:6%;top:18px;height:2px;background:linear-gradient(90deg,var(--a-teal2),var(--a-gold2));transform-origin:left;animation:abBar 1.6s ease forwards}
.ab-dv--pipe li{position:relative;display:flex;flex-direction:column;align-items:center;gap:6px;text-align:center;font:700 .76rem/1.25 var(--body);color:#E3E8FA;opacity:0;animation:abInR .4s ease forwards;animation-delay:calc(var(--k)*.15s)}
.ab-dv--pipe li span{display:grid;place-items:center;width:36px;height:36px;border-radius:50%;background:#0A1A7A;border:2px solid var(--a-teal2);font:800 .8rem var(--display);color:#fff}
.ab-dv--shield .ring{fill:none;stroke:var(--a-teal2);stroke-width:2;opacity:.25;transform-box:fill-box;transform-origin:center;animation:abRing 3s ease-in-out infinite;animation-delay:calc(var(--k)*.4s)}
@keyframes abRing{0%,100%{opacity:.2;scale:.96}50%{opacity:.8;scale:1}}
.ab-dv--shield .sh{fill:#1E5BFF;stroke:#fff;stroke-width:2}
.ab-dv--shield .tk{fill:none;stroke:#fff;stroke-width:5;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:40;stroke-dashoffset:40;animation:abTick 1s .3s ease forwards}
@keyframes abTick{to{stroke-dashoffset:0}}
.ab-dv--stairs{grid-template-columns:repeat(3,minmax(0,1fr));align-items:end;height:200px}
.ab-dv--stairs>div{display:flex;flex-direction:column;justify-content:flex-end;gap:8px;height:100%}
.ab-dv--stairs i{display:block;border-radius:12px 12px 4px 4px;background:linear-gradient(180deg,var(--a-teal2),#0E9C88);height:calc(35% + var(--k)*28%);transform-origin:bottom;scale:1 0;animation:abGrow .8s cubic-bezier(.2,.7,.2,1) forwards;animation-delay:calc(var(--k)*.18s)}
.ab-dv--stairs>div:nth-child(3) i{background:linear-gradient(180deg,var(--a-gold2),#C99A2E)}
@keyframes abGrow{to{scale:1 1}}
.ab-dv--stairs span{font:700 .84rem/1.3 var(--body);color:#fff;text-align:center}
.ab-dv--time{grid-template-columns:1fr}
.ab-dv--time .l{stroke:#ffffff33;stroke-width:2;stroke-dasharray:4 6;animation:rcDash 1.6s linear infinite}
.ab-dv--time .n{fill:var(--a-gold2)}
.ab-dv--time .p{fill:none;stroke:var(--a-gold2);stroke-width:2;transform-box:fill-box;transform-origin:center;animation:abPing 2.4s ease-out infinite;animation-delay:calc(var(--k)*.6s)}
.ab-dv--time ul{grid-template-columns:repeat(4,minmax(0,1fr))}
.ab-dv--time ul li{justify-content:center;text-align:center}
.ab-dv--time ul li::before{display:none}

.ab-close{display:grid;grid-template-columns:minmax(0,1.1fr) 80px minmax(0,.9fr);gap:18px;align-items:center;margin-top:clamp(40px,5vw,64px);padding:clamp(20px,3vw,30px);border-radius:24px;background:#ffffff08;border:1px solid #ffffff1f}
.ab-close>*{min-width:0}
.ab-close__needs .ab-tile__k{color:var(--a-teal2)}
.ab-close__needs ul{list-style:none;margin:0;padding:0;display:flex;flex-wrap:wrap;gap:8px}
.ab-close__needs li{padding:8px 13px;border-radius:999px;background:#ffffff12;border:1px solid #ffffff26;font:700 .86rem var(--body);color:#fff;animation:abGlow 6s ease-in-out infinite;animation-delay:calc(var(--i)*1s)}
.ab-close__arrow{width:80px;height:40px}
.ab-close__arrow path{fill:none;stroke:var(--a-gold2);stroke-width:3;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:6 6;animation:rcDash 1.2s linear infinite}
.ab-close__triad{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:10px}
.ab-close__triad>div{display:flex;flex-direction:column;align-items:center;gap:8px;padding:16px 8px;border-radius:18px;background:#fff;color:#07104F;font:800 .96rem var(--display);text-align:center;animation:abBob 4s ease-in-out infinite;animation-delay:calc(var(--i)*.5s)}
.ab-close__triad span{display:grid;place-items:center;width:44px;height:44px;border-radius:14px;background:#07104F;color:var(--a-gold2)}
.ab-tagline{margin:clamp(32px,4vw,48px) 0 0;text-align:center;font:800 clamp(1.3rem,2.6vw,2.1rem)/1.3 var(--display);letter-spacing:-.01em}
.ab-tagline span{background:linear-gradient(90deg,#fff,#fff) no-repeat left bottom/0 3px;padding-bottom:4px;transition:background-size .8s;color:#fff}
.ab-diff.is-in .ab-tagline span{background-size:100% 3px}
.ab-tagline span:nth-child(1){background-image:linear-gradient(90deg,var(--a-teal2),var(--a-teal2));transition-delay:.6s}
.ab-tagline span:nth-child(2){background-image:linear-gradient(90deg,#7FB0FF,#7FB0FF);transition-delay:1s}
.ab-tagline span:nth-child(3){background-image:linear-gradient(90deg,var(--a-gold2),var(--a-gold2));transition-delay:1.4s}

/* ---------- Quality ---------- */
.ab-q{background:var(--a-paper)}
.ab-q__grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:16px}
.ab-q__c{position:relative;display:flex;flex-direction:column;gap:6px;padding:26px;border-radius:24px;background:#fff;border:1px solid var(--a-line);opacity:0;translate:0 16px;transition:opacity .6s,translate .6s,box-shadow .3s;transition-delay:calc(var(--i)*.12s)}
.ab-q.is-in .ab-q__c{opacity:1;translate:0 0}
.ab-q__c:hover{box-shadow:0 26px 50px -30px #07104F80}
.ab-q__c .ab-seal{margin-bottom:10px}
.ab-q__ok{position:absolute;top:22px;right:22px;display:inline-flex;align-items:center;gap:5px;padding:4px 10px;border-radius:999px;background:#E3F5F2;color:#0B7A6A;font:700 .74rem var(--body)}
.ab-q__c h3{margin:0;font-size:1.25rem}
.ab-q__c strong{font:700 .9rem var(--body);color:var(--a-teal)}
.ab-q__c p{margin:4px 0 0;color:var(--a-muted);font-size:.93rem;line-height:1.6}
.ab-q__layers{display:grid;grid-template-columns:200px minmax(0,1fr);gap:28px;align-items:center;margin-top:24px;padding:26px;border-radius:24px;background:#07104F;color:#fff}
.ab-q__shield svg{width:100%}
.ab-q__shield circle{fill:none;stroke:var(--a-teal2);stroke-width:2;transform-box:fill-box;transform-origin:center;animation:abRing 3s ease-in-out infinite;animation-delay:calc(var(--k)*.4s)}
.ab-q__shield path{fill:#1E5BFF;stroke:#fff;stroke-width:2}
.ab-q__layers ul{list-style:none;margin:0;padding:0;display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}
.ab-q__layers li{display:flex;gap:12px;align-items:flex-start;padding:12px;border-radius:14px;background:#ffffff0d;border:1px solid #ffffff1c;opacity:0;translate:0 10px;transition:opacity .5s,translate .5s;transition-delay:calc(var(--i)*.1s + .3s)}
.ab-q.is-in .ab-q__layers li{opacity:1;translate:0 0}
.ab-q__layers li>span{flex:none;display:grid;place-items:center;width:36px;height:36px;border-radius:11px;background:#ffffff14;color:var(--a-teal2)}
.ab-q__layers strong{display:block;font:800 .96rem var(--display)}
.ab-q__layers em{display:block;font-style:normal;font-size:.86rem;color:#C9D3F5}
.ab-q__aff{display:flex;flex-wrap:wrap;align-items:center;justify-content:space-between;gap:16px;margin-top:20px;padding:20px 24px;border-radius:20px;background:#fff;border:1px solid var(--a-line)}
.ab-q__aff .ab-tile__k{margin:0}
.ab-q__aff>div{display:flex;flex-wrap:wrap;gap:12px}

/* responsive */
@media (max-width:1100px){
  .ab-tile--year{grid-column:span 4}.ab-tile--globe{grid-column:span 8}.ab-tile--full{grid-column:span 12}
  .ab-pill3{grid-template-columns:repeat(3,minmax(0,1fr))}
  .ab-life ol{grid-template-columns:repeat(4,minmax(0,1fr));row-gap:22px}
  .ab-life ol::before,.ab-life ol::after,.ab-life__pulse{display:none}
  .ab-triad{grid-template-columns:repeat(3,minmax(0,1fr))}
  .ab-triad__eq{grid-column:1/-1;justify-self:center}
  .ab-triad__out{grid-column:1/-1}
  .ab-team__people ul{grid-template-columns:repeat(3,minmax(0,1fr))}
  .ab-team__people ul::before{display:none}
  .ab-dv--pipe ol{grid-template-columns:repeat(4,minmax(0,1fr));row-gap:12px}
  .ab-dv--pipe ol::before{display:none}
}
@media (max-width:900px){
  .ab-row,.ab-split2,.ab-align,.ab-team,.ab-dx__in,.ab-close,.ab-mv__stage{grid-template-columns:1fr}
  .ab-close__arrow{transform:rotate(90deg);justify-self:center}
  .ab-q__grid{grid-template-columns:1fr}
  .ab-q__layers{grid-template-columns:1fr}
  .ab-q__shield{max-width:160px;margin:0 auto}
  .ab-dx__list{grid-template-columns:repeat(2,minmax(0,1fr))}
  .ab-orbit{max-width:420px}
}
@media (max-width:640px){
  .ab-tile--year,.ab-tile--globe{grid-column:span 12}
  .ab-tile--globe{grid-template-columns:110px minmax(0,1fr)}
  .ab-globe{width:110px}
  .ab-pill3,.ab-seals{grid-template-columns:1fr}
  .ab-conv{grid-template-columns:1fr}
  .ab-conv__svg{display:none}
  .ab-conv__out{margin-top:12px}
  .ab-triad{grid-template-columns:1fr}
  .ab-triad__in+.ab-triad__in::before{left:50%;top:-12px;translate:-50% -50%}
  .ab-life ol{grid-template-columns:1fr 1fr}
  .ab-mx>div{grid-template-columns:minmax(0,.9fr) repeat(3,minmax(0,1fr))}
  .ab-mx>div>*{padding:10px 6px}
  .ab-mx__h span{font-size:.68rem}
  .ab-mx strong{font-size:.86rem}
  .ab-beyond__flow{grid-template-columns:1fr}
  .ab-beyond__svg{display:none}
  .ab-beyond__src{grid-template-columns:1fr 1fr;gap:8px}
  .ab-mv__toggle{min-width:0;width:100%}
  .ab-orbit__n span{width:46px;height:46px;border-radius:14px}
  .ab-orbit__n em{font-size:.7rem}
  .ab-align__viz{height:300px}
  .ab-align__sat{font-size:.74rem;padding:8px 10px}
  .ab-align__viz{height:340px}
  .ab-align__core{width:124px;height:124px}.ab-align__core strong{font-size:.84rem}
  .ab-align.is-in .ab-align__sat--0{left:50%;top:2%}
  .ab-align.is-in .ab-align__sat--2{left:50%;top:86%}
  .ab-align.is-in .ab-align__sat--1{left:76%;top:20%}
  .ab-align.is-in .ab-align__sat--3{left:24%;top:70%}
  .ab-team__people ul{grid-template-columns:repeat(2,minmax(0,1fr))}
  .ab-dx__list{grid-template-columns:1fr}
  .ab-dv{grid-template-columns:1fr}
  .ab-dv--pipe ol{grid-template-columns:repeat(2,minmax(0,1fr))}
  .ab-dv--time ul{grid-template-columns:1fr 1fr}
  .ab-close__triad{grid-template-columns:repeat(3,minmax(0,1fr))}
  .ab-q__layers ul{grid-template-columns:1fr}
  .ab-q__aff{flex-direction:column;align-items:flex-start}
}
@media (prefers-reduced-motion:reduce){
  .ab *,.ab *::before,.ab *::after{animation:none!important;transition:none!important}
  .ab-tile,.ab-conv__in li,.ab-life li,.ab-q__c,.ab-q__layers li,.ab-orbit__n,.ab-dv ul li,.ab-dv--pipe li{opacity:1!important;translate:none!important;scale:none!important}
  .ab-mx__dot{scale:1}.ab-life ol::after,.ab-pill3 li i{scale:1 1}
  .ab-dv--stairs i{scale:1 1}.ab-dv--shield .tk{stroke-dashoffset:0}
  .ab-conv__d,.ab-life__pulse{display:none}
  .ab-tagline span{background-size:100% 3px}
}

/* ---------- About hero: background options ---------- */
.abh{isolation:isolate;padding:clamp(52px,6vw,92px) 0 clamp(48px,5.5vw,80px);background:linear-gradient(160deg,#07104F,#0A1766 55%,#0C1D7A);min-height:clamp(520px,44vw,620px)}
.abh:after{display:none}
.abh__bgwrap{position:absolute;inset:0;z-index:-1;pointer-events:none}
.abh__bgwrap:after{content:"";position:absolute;inset:0;background:linear-gradient(90deg,#07104F 0%,#07104Fe6 28%,#07104F55 52%,transparent 70%)}
.abh-bg{position:absolute;inset:0;width:100%;height:100%;display:block}
.abh__copy{position:relative}
.abh__copy>*{max-width:620px}
.abh .abh__title{margin:0 0 18px;color:#fff;font:800 clamp(2.1rem,4.2vw,3.5rem)/1.06 var(--display);letter-spacing:-.025em;max-width:17ch}
.abh .page-hero__intro{max-width:50ch}
.abh__label{position:absolute;top:14px;right:16px;z-index:2;padding:6px 12px;border-radius:999px;background:#F0D98F;color:#07104F;font:800 .78rem var(--display)}
/* pillar links */
.abh__pillars{list-style:none;margin:28px 0 0;padding:0;display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px;max-width:560px}
.abh__pillars a{display:flex;gap:12px;align-items:center;height:100%;padding:12px 14px;border-radius:14px;background:#07104F99;backdrop-filter:blur(6px);border:1px solid #ffffff1f;color:#fff;text-decoration:none;position:relative;overflow:hidden;transition:background .3s,border-color .3s,translate .3s}
.abh__pillars a:after{content:"";position:absolute;left:0;top:0;bottom:0;width:3px;background:var(--c);opacity:.8}
.abh__pillars a:hover{background:#0B1A6Ecc;border-color:color-mix(in srgb,var(--c) 55%,transparent);translate:0 -2px}
.abh__pillars a:focus-visible{outline:2px solid var(--c);outline-offset:2px}
.abh__pillars i{flex:none;display:grid;place-items:center;width:34px;height:34px;border-radius:10px;font:800 .78rem var(--display);font-style:normal;color:var(--c);background:color-mix(in srgb,var(--c) 14%,transparent);border:1px solid color-mix(in srgb,var(--c) 35%,transparent)}
.abh__pillars strong{display:block;font:800 .95rem var(--display)}
.abh__pillars em{display:block;font-style:normal;font-size:.82rem;color:#C9D3F5;line-height:1.35}
/* A — silk streams */
.abh-silk__line{fill:none;stroke-width:1.1}
.abh-silk{contain:strict;overflow:hidden}
.abh-silk>svg{position:absolute;inset:0;width:100%;height:100%;display:block}
.abh-silk__static,.abh-silk__live{will-change:transform}
.abh-silk__dot{filter:none}
@keyframes abhPulse{from{stroke-dashoffset:0}to{stroke-dashoffset:1}}
.abh-silk__bundle{}
@keyframes abhSway{50%{translate:0 7px}}
.abh-silk__ring{fill:none;stroke:#fff;stroke-opacity:.6;transform-box:fill-box;transform-origin:center;animation:abhRing 3.6s ease-out infinite}
.abh-silk__ring--2{animation-delay:1.8s}
@keyframes abhRing{0%{scale:.6;opacity:1}100%{scale:3;opacity:0}}
.abh-silk__tag text{font:700 12px var(--display)}
/* B / C canvases sit in their own layer */
.abh-land,.abh-topo{opacity:.95}
@media (max-width:900px){
  .abh{min-height:0}
  .abh__bgwrap:after{background:linear-gradient(180deg,#07104Fd9 0%,#07104Fb3 60%,#07104F66 100%)}
  .abh-silk__tag{display:none}
  .abh--a .abh__bgwrap:after{background:linear-gradient(180deg,#07104Fb3 0%,#07104F8c 55%,#07104F33 100%)}
  .abh--a .abh-silk__line{stroke-width:1.4}
  .abh-land,.abh-topo{opacity:.7}
}
@media (max-width:640px){
  .abh__pillars{gap:8px}
  .abh__pillars a{padding:10px 12px;gap:10px}
  .abh__pillars i{width:30px;height:30px}
}
@media (prefers-reduced-motion:reduce){
  .abh *{animation:none!important;transition:none!important}
  .abh-silk__dot{display:none}
}

/* Regions & countries we cover (rg-) */
.rg{position:relative;overflow:hidden;color:#fff;background:radial-gradient(60% 70% at 70% 40%,#12309E 0%,transparent 70%),linear-gradient(170deg,#050C3F,#07104F 45%,#0A1766);padding-bottom:0}
.rg__stars{position:absolute;inset:0;pointer-events:none;background-image:radial-gradient(1px 1px at 20% 30%,#ffffff55 50%,transparent 51%),radial-gradient(1px 1px at 70% 15%,#ffffff44 50%,transparent 51%),radial-gradient(1.5px 1.5px at 85% 60%,#6EE0CE55 50%,transparent 51%),radial-gradient(1px 1px at 40% 80%,#ffffff33 50%,transparent 51%),radial-gradient(1px 1px at 10% 70%,#F0D98F44 50%,transparent 51%);background-size:420px 300px;opacity:.8}
@keyframes rgDrift{to{background-position:420px 300px}}
.rg .container{position:relative}
.rg-top{display:flex;justify-content:space-between;align-items:flex-end;gap:24px;flex-wrap:wrap}
.rg-top .in-head{margin-bottom:22px}
.rg-total{display:flex;align-items:baseline;gap:8px;margin-bottom:26px;padding:14px 20px;border-radius:18px;background:#ffffff0b;border:1px solid #ffffff1f}
.rg-total b{font:800 2.6rem/1 var(--display);background:linear-gradient(135deg,#fff,#6EE0CE);-webkit-background-clip:text;background-clip:text;color:transparent}
.rg-total span{font:700 .86rem var(--display);color:#C9D3F5}
.rg-total i{width:1px;height:30px;background:#ffffff33;margin:0 10px;align-self:center}

/* tabs */
.rg-tabs{display:grid;grid-template-columns:repeat(6,minmax(0,1fr));gap:10px;margin-bottom:18px}
.rg-tab{position:relative;overflow:hidden;display:flex;flex-direction:column;align-items:flex-start;gap:2px;padding:12px 14px;border-radius:16px;border:1px solid #ffffff1f;background:#ffffff08;color:#fff;cursor:pointer;text-align:left;transition:background .3s,border-color .3s,translate .3s}
.rg-tab:hover{translate:0 -2px;border-color:color-mix(in srgb,var(--c,#6EE0CE) 60%,transparent)}
.rg-tab__n{font:800 1.6rem/1 var(--display);color:var(--c,#fff)}
.rg-tab__t{font:700 .84rem var(--display);color:#E7ECFF}
.rg-tab__bar{display:block;width:100%;height:4px;margin-top:8px;border-radius:3px;background:#ffffff14;overflow:hidden}
.rg-tab__bar i{display:block;height:100%;background:var(--c);border-radius:3px;transform-origin:left;scale:0 1;transition:scale 1.2s cubic-bezier(.4,0,.2,1)}
.rg.is-in .rg-tab__bar i{scale:1 1}
.rg-tab.is-on{background:color-mix(in srgb,var(--c,#6EE0CE) 18%,#07104F);border-color:var(--c,#6EE0CE);box-shadow:0 14px 30px -18px var(--c,#6EE0CE)}
.rg-tab--all.is-on{background:#ffffff1a;border-color:#ffffff66}
.rg-tab__timer{position:absolute;left:0;bottom:0;height:2px;width:100%;background:var(--c);transform-origin:left;animation:rgTimer 5.2s linear}
@keyframes rgTimer{from{scale:0 1}}

/* stage */
.rg-stage{display:grid;grid-template-columns:minmax(0,1.7fr) minmax(0,1fr);gap:18px;align-items:stretch}
.rg-map{position:relative;display:flex;flex-direction:column;justify-content:center;border-radius:24px;background:radial-gradient(80% 90% at 50% 40%,#0E2490 0%,#081556 70%);border:1px solid #ffffff1a;overflow:hidden;perspective:1400px;box-shadow:inset 0 0 80px #000a,0 40px 80px -50px #000}
.rg-map__tilt{position:relative;transform:rotateX(14deg) scale(1.02);transform-origin:50% 60%;transition:transform 1s}
.rg-map:hover .rg-map__tilt{transform:rotateX(6deg) scale(1.02)}
.rg-map__svg{display:block;width:100%;height:auto}
.rg-map__zoom{transition:transform 1.1s cubic-bezier(.65,0,.35,1)}
.rg-land{fill:#1B2C86;stroke:#3A4BA8;stroke-width:.4;vector-effect:non-scaling-stroke;transition:fill .6s,opacity .6s}
.rg-land.is-cov{fill:color-mix(in srgb,var(--c) 45%,#1B2C86);stroke:var(--c);stroke-opacity:.6}
.rg-land.is-on{fill:var(--c);fill-opacity:.85;filter:drop-shadow(0 0 6px color-mix(in srgb,var(--c) 70%,transparent))}
.rg-land.is-dim{opacity:.45}
.rg.is-in .rg-land.is-cov{animation:rgLandIn .8s both;animation-delay:var(--d)}
@keyframes rgLandIn{from{opacity:0}}
.rg-hubglow{animation:rgBreath 3s ease-in-out infinite}
@keyframes rgBreath{50%{opacity:.5}}
.rg-arc{fill:none;stroke:var(--c);stroke-width:1.4;stroke-linecap:round;stroke-dasharray:1;stroke-dashoffset:1;animation:rgDraw .9s forwards;animation-delay:calc(var(--i)*.06s);opacity:.85}
@keyframes rgDraw{to{stroke-dashoffset:0}}
.rg-arc__dot{filter:drop-shadow(0 0 4px #fff)}
.rg-pins{position:absolute;inset:0}
.rg-pin{position:absolute;translate:-50% -50%;width:14px;height:14px;padding:0;border:0;background:none;cursor:pointer;transition:left 1.1s cubic-bezier(.65,0,.35,1),top 1.1s cubic-bezier(.65,0,.35,1),opacity .5s;opacity:.35;z-index:1}
.rg-pin i{position:absolute;inset:3px;border-radius:50%;background:var(--c);box-shadow:0 0 0 2px #07104F,0 0 10px var(--c)}
.rg-pin i:after{content:"";position:absolute;inset:-5px;border-radius:50%;border:1.5px solid var(--c);opacity:0}
.rg-pin.is-on{opacity:1}
.rg-stage.is-zoom .rg-pin.is-on i:after{animation:rgPing 2.6s ease-out infinite;animation-delay:var(--d)}
@keyframes rgPing{0%{scale:.4;opacity:.9}100%{scale:2.4;opacity:0}}
.rg-pin.is-hov,.rg-pin:hover{z-index:5}
.rg-pin.is-hov i{scale:1.5}
.rg-pin--hq i{inset:0;background:#fff;box-shadow:0 0 0 3px #F0D98F,0 0 16px #F0D98F}
.rg-tip{position:absolute;left:50%;bottom:calc(100% + 8px);translate:-50% 0;display:flex;align-items:center;gap:8px;padding:7px 10px;border-radius:12px;background:#fff;color:#07104F;white-space:nowrap;box-shadow:0 14px 30px -10px #000a;animation:rgTip .2s both;pointer-events:none}
.rg-tip b{font:800 .84rem var(--display)}
.rg-tip em{font-style:normal;font-size:.72rem;color:#525C78}
.rg-tip:after{content:"";position:absolute;left:50%;top:100%;translate:-50% 0;border:6px solid transparent;border-top-color:#fff}
@keyframes rgTip{from{opacity:0;translate:-50% 6px}}
.rg-hq{position:absolute;translate:-50% 14px;padding:3px 8px;border-radius:999px;background:#F0D98F;color:#07104F;font:800 .66rem var(--display);letter-spacing:.06em;pointer-events:none;opacity:0;transition:opacity .5s}
.rg-map:not(:hover) .rg-hq{opacity:0}

/* flags */
.rg-flag{display:block;object-fit:cover;border-radius:4px;box-shadow:0 0 0 1px #ffffff2a,0 6px 14px -8px #000}
.rg-flag--md{width:40px;height:30px}
.rg-flag--sm{width:24px;height:18px;border-radius:3px}
.rg-flag--xs{width:20px;height:15px;border-radius:2px}

/* side panel */
.rg-panel{padding:18px;border-radius:24px;background:#ffffff0b;border:1px solid #ffffff1f;animation:rgPanel .5s both;max-height:520px;overflow:auto;scrollbar-width:thin}
@keyframes rgPanel{from{opacity:0;translate:12px 0}}
.rg-panel__head{display:flex;align-items:center;gap:14px;margin-bottom:14px;padding-bottom:14px;border-bottom:1px solid #ffffff1a}
.rg-panel__head b{display:grid;place-items:center;width:58px;height:58px;border-radius:18px;background:var(--c);color:#07104F;font:800 1.6rem var(--display);box-shadow:0 12px 26px -12px var(--c)}
.rg-panel__head strong{display:block;font:800 1.2rem var(--display)}
.rg-panel__head span{font-size:.84rem;color:#C9D3F5}
.rg-sub h3{display:flex;align-items:center;gap:8px;margin:6px 0 8px;font:800 .76rem var(--display);letter-spacing:.14em;text-transform:uppercase;color:#F0D98F}
.rg-sub h3 i{font-style:normal;padding:1px 7px;border-radius:999px;background:#F0D98F26}
.rg-sub+.rg-sub{margin-top:12px}
.rg-flags{list-style:none;margin:0;padding:0;display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px}
.rg-flags li{display:flex;align-items:center;gap:10px;padding:8px 10px;border-radius:12px;background:#ffffff0a;border:1px solid #ffffff14;font:700 .84rem var(--display);perspective:400px;animation:rgFlip .5s both;animation-delay:calc(var(--i)*.04s);transition:background .25s,border-color .25s,translate .25s}
.rg-flags li .rg-flag{transition:transform .5s}
.rg-flags li:hover,.rg-flags li.is-hov{background:#ffffff1a;border-color:#ffffff40;translate:0 -2px}
.rg-flags li:hover .rg-flag{transform:rotateY(180deg) rotateY(180deg) scale(1.1)}
@keyframes rgFlip{from{opacity:0;transform:rotateX(-70deg);transform-origin:top}}
.rg-overview{list-style:none;margin:0;padding:0;display:grid;gap:8px}
.rg-overview button{display:grid;grid-template-columns:auto 1fr auto;align-items:center;gap:12px;width:100%;padding:12px 14px;border-radius:14px;border:1px solid #ffffff1a;background:#ffffff08;color:#fff;cursor:pointer;text-align:left;border-left:3px solid var(--c);animation:rgPanel .5s both;animation-delay:calc(var(--i)*.07s);transition:background .25s}
.rg-overview button:hover{background:#ffffff16}
.rg-overview__flags{display:flex}
.rg-overview__flags .rg-flag{margin-left:-6px}
.rg-overview__flags .rg-flag:first-child{margin-left:0}
.rg-overview__t{font:800 .92rem var(--display)}
.rg-overview b{font:800 1.3rem var(--display);color:var(--c)}

/* mix bar */
.rg-mix{display:flex;align-items:center;gap:14px;margin:20px 0 0}
.rg-mix__label{flex:none;font:800 .72rem var(--display);letter-spacing:.14em;text-transform:uppercase;color:#C9D3F5}
.rg-mix__bar{flex:1;display:flex;height:40px;border-radius:12px;overflow:hidden;background:#ffffff0a;gap:2px}
.rg-mix__bar button{position:relative;flex:0 0 var(--w);display:flex;align-items:center;justify-content:space-between;gap:6px;padding:0 10px;border:0;background:var(--c);color:#07104F;font:800 .76rem var(--display);cursor:pointer;transform-origin:left;scale:0 1;transition:scale .9s cubic-bezier(.4,0,.2,1),filter .25s;transition-delay:calc(var(--i)*.15s);white-space:nowrap;overflow:hidden;min-width:0}
.rg.is-in .rg-mix__bar button{scale:1 1}
.rg-mix__bar button span{overflow:hidden;text-overflow:ellipsis}
.rg-mix__bar button:hover,.rg-mix__bar button.is-on{filter:brightness(1.15) saturate(1.2)}
.rg-mix__bar button.is-on:after{content:"";position:absolute;inset:0;box-shadow:inset 0 0 0 2px #fff}

/* ticker */
.rg-ticker{margin-top:clamp(30px,4vw,48px);padding:14px 0;border-top:1px solid #ffffff14;background:#00000022;overflow:hidden;mask-image:linear-gradient(90deg,transparent,#000 8%,#000 92%,transparent)}
.rg-ticker__track{display:flex;width:max-content;animation:rgTick 70s linear infinite}
.rg-ticker:hover .rg-ticker__track{animation-play-state:paused}
.rg-ticker__set{display:flex;gap:26px;padding-right:26px}
.rg-ticker__item{display:inline-flex;align-items:center;gap:8px;font:700 .84rem var(--display);color:#C9D3F5;white-space:nowrap}
@keyframes rgTick{to{translate:-50% 0}}

@media (max-width:1100px){
  .rg-tabs{grid-template-columns:repeat(3,minmax(0,1fr))}
  .rg-stage{grid-template-columns:1fr}
  .rg-panel{max-height:none}
  .rg-flags{grid-template-columns:repeat(3,minmax(0,1fr))}
}
@media (max-width:640px){
  .rg-tabs{display:flex;overflow-x:auto;scroll-snap-type:x mandatory;padding-bottom:6px}
  .rg-tab{flex:0 0 132px;scroll-snap-align:start}
  .rg-map__tilt{transform:none}
  .rg-pin{width:10px;height:10px}
  .rg-flags{grid-template-columns:1fr 1fr}
  .rg-flags li{font-size:.78rem;padding:7px 8px;gap:8px}
  .rg-flag--md{width:32px;height:24px}
  .rg-mix{flex-direction:column;align-items:stretch}
  .rg-mix__bar button span{display:none}
  .rg-mix__bar button{justify-content:center}
  .rg-total b{font-size:2rem}
}
@media (prefers-reduced-motion:reduce){
  .rg *,.rg *:before,.rg *:after,.rg__stars{animation:none!important;transition:none!important}
  .rg-tab__bar i,.rg-mix__bar button{scale:1 1}
  .rg-arc{stroke-dashoffset:0}
}

/* Industries & Case Studies (in-) */
.in{--n:#07104F;--r:#0B22A8;--b:#1E5BFF;--t:#0E9C88;--t2:#6EE0CE;--gd:#C99A2E;--g2:#F0D98F;--ink:#14193D;--mu:#525C78;--ln:#DDE2EC;--pp:#F6F7FB}
.in-sec{position:relative}
.in-head{max-width:760px;margin-bottom:clamp(22px,3vw,36px)}
.in-head h2{margin:6px 0 8px;font:800 clamp(1.7rem,3vw,2.4rem)/1.12 var(--display);letter-spacing:-.02em;color:var(--n)}
.in-head p{margin:0;color:var(--mu);font-size:1.05rem}
.in-head--center{margin-inline:auto;text-align:center}
.in-head--light h2{color:#fff}.in-head--light p{color:#C9D3F5}
.in-kicker{display:inline-flex;align-items:center;gap:10px;font:800 .74rem var(--display);letter-spacing:.16em;text-transform:uppercase;color:var(--t)}
.in-kicker:before{content:"";width:22px;height:2px;background:currentColor}
.in-head--light .in-kicker{color:var(--t2)}

/* heroes */
.in-hero,.in-ihero,.in-chero{isolation:isolate;background:linear-gradient(160deg,#07104F,#0A1766 55%,#0C1D7A)}
.in-hero:after,.in-ihero:after,.in-chero:after{display:none}
.in-hero__bg{position:absolute;inset:0;z-index:-1;pointer-events:none}
.in-hero__bg .abh-silk>svg{opacity:.45}
.in-hero__bg .abh-silk__tag{display:none}
.in-hero__bg:after{content:"";position:absolute;inset:0;background:linear-gradient(90deg,#07104F 0%,#07104Fcc 35%,#07104F33 70%,transparent)}
.in-hero__grid{display:grid;grid-template-columns:minmax(0,1.05fr) minmax(0,.95fr);gap:clamp(24px,4vw,56px);align-items:center}
.in-hero h1,.in-ihero h1,.in-chero h1{color:#fff;margin:14px 0 14px;font:800 clamp(2.1rem,4.4vw,3.6rem)/1.05 var(--display);letter-spacing:-.025em}
.in-chero h1{font-size:clamp(1.8rem,3.4vw,2.8rem);max-width:24ch}
.in-stats{list-style:none;margin:24px 0 0;padding:0;display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:10px;max-width:640px}
.in-stats--3{grid-template-columns:repeat(3,minmax(0,1fr));max-width:480px}
.in-stats li{padding:12px 14px;border-radius:14px;background:#ffffff0d;border:1px solid #ffffff1f;animation:inUp .6s both;animation-delay:calc(var(--i,0)*.1s + .2s)}
.in-stats b{display:block;font:800 1.8rem/1 var(--display);color:#fff}
.in-stats span{display:block;margin-top:6px;font-size:.78rem;color:#C9D3F5;line-height:1.3}
@keyframes inUp{from{opacity:0;translate:0 12px}}

/* sector wheel */
.in-wheel{position:relative;max-width:470px;width:100%;justify-self:center;aspect-ratio:1}
.in-wheel__svg{position:absolute;inset:0;width:100%;height:100%;overflow:visible}
.in-wheel__orbit{fill:none;stroke:#ffffff1c;stroke-dasharray:2 7;transform-origin:220px 220px}
.in-wheel__orbit--2{animation-direction:reverse;animation-duration:60s}
@keyframes inSpin{to{rotate:360deg}}
.in-wheel__arc{cursor:pointer;transition:opacity .3s}
.in-wheel__arc path{fill:var(--c);fill-opacity:.22;stroke:var(--c);stroke-opacity:.6;transition:fill-opacity .3s;animation:inArc .8s both;animation-delay:calc(var(--i)*.08s)}
@keyframes inArc{from{opacity:0}}
.in-wheel__arc.is-on path{fill-opacity:.85}
.in-wheel__arc.is-dim{opacity:.35}
.in-wheel__dot{fill:var(--c)}
@keyframes inTw{50%{opacity:.25}}
.in-wheel__core{position:absolute;left:50%;top:50%;translate:-50% -50%;width:56%;aspect-ratio:1;border-radius:50%;background:radial-gradient(circle at 35% 30%,#2A55F0,#0B22A8 60%,#07104F);box-shadow:0 0 0 10px #ffffff08,0 30px 60px -20px #000a;display:flex;flex-direction:column;align-items:center;justify-content:center;text-align:center;padding:16px;color:#fff}
.in-wheel__core b{font:800 clamp(2.4rem,4.4vw,3.4rem)/1 var(--display)}
.in-wheel__core em{font-style:normal;font-size:.82rem;color:#C9D3F5;max-width:16ch;margin-top:6px}
.in-wheel__ic{margin-bottom:4px}

/* explorer */
.in-tools{display:grid;gap:14px;margin-bottom:22px}
.in-search{display:flex;align-items:center;gap:10px;max-width:520px;padding:12px 16px;border-radius:14px;border:1px solid var(--ln);background:#fff;color:var(--mu);box-shadow:0 8px 20px -16px #07104F55}
.in-search input{flex:1;border:0;outline:0;font:500 1rem var(--body);background:none;color:var(--ink)}
.in-search:focus-within{border-color:var(--r)}
.in-groups{display:flex;flex-wrap:wrap;gap:8px}
.in-groups button{display:inline-flex;align-items:center;gap:7px;padding:8px 12px;border-radius:999px;border:1px solid var(--ln);background:#fff;font:700 .84rem var(--display);color:var(--n);cursor:pointer;transition:all .25s}
.in-groups button svg{color:var(--c,var(--r))}
.in-groups button i{font-style:normal;font-size:.72rem;padding:1px 7px;border-radius:999px;background:var(--pp);color:var(--mu)}
.in-groups button:hover{border-color:var(--c,var(--r))}
.in-groups button.is-on{background:var(--c,var(--n));border-color:var(--c,var(--n));color:#fff}
.in-groups button.is-on svg{color:#fff}
.in-groups button.is-on i{background:#ffffff33;color:#fff}
.in-groups--mk{margin-bottom:20px}
.in-empty{color:var(--mu)}
.in-tiles{list-style:none;margin:0;padding:0;display:grid;grid-template-columns:repeat(auto-fill,minmax(210px,1fr));gap:12px}
.in-tiles li{animation:inUp .5s both;animation-delay:calc(var(--i)*.03s)}
.in-tile{display:block;position:relative;height:150px;perspective:900px;text-decoration:none}
.in-tile__face,.in-tile__back{position:absolute;inset:0;border-radius:18px;padding:16px;display:flex;flex-direction:column;backface-visibility:hidden;transition:transform .6s cubic-bezier(.2,.7,.2,1)}
.in-tile__face{background:#fff;border:1px solid var(--ln);color:var(--n)}
.in-tile__face:before{content:"";position:absolute;left:16px;right:16px;top:0;height:3px;border-radius:0 0 3px 3px;background:var(--c)}
.in-tile__ic{display:grid;place-items:center;width:44px;height:44px;border-radius:13px;background:color-mix(in srgb,var(--c) 10%,#fff);color:var(--c)}
.in-tile__face strong{margin-top:auto;font:800 1rem/1.2 var(--display)}
.in-tile__face small{margin-top:4px;font-size:.78rem;color:var(--mu)}
.in-tile__face small.has{color:var(--c);font-weight:700}
.in-tile__back{background:linear-gradient(160deg,var(--c),#07104F);color:#fff;transform:rotateY(180deg);gap:8px}
.in-tile__back b{font:800 .7rem var(--display);letter-spacing:.12em;text-transform:uppercase;color:var(--lt)}
.in-tile__back>span{display:flex;flex-wrap:wrap;gap:4px}
.in-tile__back em{font-style:normal;font-size:.74rem;font-weight:600;padding:3px 8px;border-radius:999px;background:#ffffff1f}
.in-tile__back i{margin-top:auto;font-style:normal;font:800 .82rem var(--display);color:var(--lt)}
.in-tile:hover .in-tile__face,.in-tile:focus-visible .in-tile__face{transform:rotateY(-180deg)}
.in-tile:hover .in-tile__back,.in-tile:focus-visible .in-tile__back{transform:rotateY(0)}
.in-tiles--sm .in-tile{height:130px}

/* glance */
.in-glance{background:radial-gradient(50% 70% at 85% 20%,#13309C,transparent 70%),linear-gradient(160deg,#07104F,#0A1766);color:#fff}
.in-glance__grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px}
.in-panel{margin:0;padding:20px;border-radius:20px;background:#ffffff0b;border:1px solid #ffffff1c}
.in-panel--wide{grid-column:span 2}
.in-panel figcaption{font:800 .78rem var(--display);letter-spacing:.1em;text-transform:uppercase;color:#C9D3F5;margin-bottom:14px}
.in-bars{list-style:none;margin:0;padding:0;display:grid;gap:9px}
.in-bars li{display:grid;grid-template-columns:minmax(120px,1.1fr) 1.4fr 28px;gap:10px;align-items:center;font-size:.84rem;color:#E7ECFF}
.in-panel--wide .in-bars li{grid-template-columns:minmax(200px,.9fr) 1.6fr 28px}
.in-bars i{height:10px;border-radius:6px;background:#ffffff12;position:relative;overflow:hidden}
.in-bars i:after{content:"";position:absolute;inset:0;width:var(--w);border-radius:6px;background:var(--c);transform-origin:left;scale:0 1;transition:scale 1.1s cubic-bezier(.4,0,.2,1);transition-delay:calc(var(--i)*.08s)}
.in-bars li.is-in i:after{scale:1 1}
.in-bars b{font:800 .9rem var(--display);color:#fff;text-align:right}
.in-ring{display:flex;align-items:center;gap:16px}
.in-ring svg{width:110px;height:110px;rotate:-90deg;flex:none}
.in-ring circle{fill:none;stroke-width:10}
.in-ring .bg{stroke:#ffffff14}
.in-ring .fg{stroke:var(--t2);stroke-linecap:round;stroke-dasharray:var(--p) 100;transition:stroke-dasharray 1.4s cubic-bezier(.4,0,.2,1)}
.in-ring b{display:block;font:800 2.2rem/1 var(--display)}
.in-ring span{font-size:.86rem;color:#C9D3F5}
.in-panel__foot{margin:14px 0 0;font-size:.84rem;color:#C9D3F5}
.in-panel__foot b{color:#fff}
.in-mk{list-style:none;margin:0;padding:0;display:grid;grid-template-columns:1fr 1fr;gap:6px}
.in-mk li{display:flex;align-items:center;gap:6px;padding:6px 8px;border-radius:10px;background:#ffffff0a;font-size:.8rem;color:#E7ECFF}
.in-mk li b{margin-left:auto;font:800 .8rem var(--display);color:var(--g2)}
.in-mk .flag-img,.in-flags .flag-img,.in-groups .flag-img{width:18px;height:auto;border-radius:2px}

/* featured */
.in-feat{display:grid;grid-template-columns:260px minmax(0,1fr);gap:18px;align-items:start}
.in-feat__rail{display:grid;gap:8px}
.in-feat__rail button{position:relative;display:flex;align-items:center;gap:10px;padding:12px 14px;border-radius:14px;border:1px solid var(--ln);background:#fff;font:700 .9rem var(--display);color:var(--n);cursor:pointer;text-align:left;overflow:hidden;transition:all .25s}
.in-feat__rail button svg{color:var(--c)}
.in-feat__rail button.is-on{background:var(--n);color:#fff;border-color:var(--n)}
.in-feat__rail button.is-on svg{color:var(--t2)}
.in-feat__timer{position:absolute;left:0;bottom:0;height:3px;width:100%;background:var(--t2);transform-origin:left;animation:inTimer 7s linear}
@keyframes inTimer{from{scale:0 1}}
.in-feat__card{padding:clamp(20px,3vw,32px);border-radius:24px;background:#fff;border:1px solid var(--ln);box-shadow:0 30px 60px -36px #07104F66;position:relative;overflow:hidden;animation:inUp .45s both}
.in-feat__card:before{content:"";position:absolute;left:0;top:0;right:0;height:4px;background:linear-gradient(90deg,var(--c),var(--lt))}
.in-feat__top{display:flex;flex-wrap:wrap;align-items:center;justify-content:space-between;gap:10px}
.in-feat__ind{display:inline-flex;align-items:center;gap:6px;padding:5px 10px;border-radius:999px;background:color-mix(in srgb,var(--c) 10%,#fff);color:var(--c);font:800 .8rem var(--display)}
.in-feat__card h3{margin:14px 0 14px;font:800 clamp(1.25rem,2.2vw,1.6rem)/1.2 var(--display)}
.in-feat__card h3 a{color:var(--n);text-decoration:none}
.in-feat__card h3 a:hover{color:var(--r)}
.in-facts{list-style:none;margin:0 0 16px;padding:0;display:flex;flex-wrap:wrap;gap:8px}
.in-facts li{display:flex;gap:8px;align-items:flex-start;padding:8px 12px;border-radius:12px;background:var(--pp);font-size:.86rem}
.in-facts svg{color:var(--t);flex:none;margin-top:2px}
.in-facts b{display:block;font:800 .68rem var(--display);letter-spacing:.08em;text-transform:uppercase;color:var(--mu)}
.in-facts--grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr))}
.in-link{display:inline-block;margin-top:14px;font:800 .92rem var(--display);color:var(--r)}

/* story flow (tabs) */
.in-flow__tabs{display:flex;flex-wrap:wrap;gap:6px}
.in-flow__tabs button{display:inline-flex;align-items:center;gap:6px;padding:7px 12px;border-radius:10px;border:1px solid var(--ln);background:#fff;font:700 .82rem var(--display);color:var(--mu);cursor:pointer;transition:all .2s}
.in-flow__tabs button svg{color:var(--sc)}
.in-flow__tabs button.is-on{background:var(--sc);border-color:var(--sc);color:#fff}
.in-flow__tabs button.is-on svg{color:#fff}
.in-flow__bar{height:3px;border-radius:3px;background:var(--ln);margin:10px 0 12px;overflow:hidden}
.in-flow__bar i{display:block;height:100%;background:linear-gradient(90deg,#C99A2E,#1E5BFF,#0E9C88,#5A3FE0);transition:width .5s}
.in-flow__text{margin:0;color:var(--ink);line-height:1.65;animation:inUp .35s both}
.in-flow--compact .in-flow__text{font-size:.94rem}

/* markets */
.in-mkts__grid{display:grid;grid-template-columns:minmax(0,1.2fr) minmax(0,.8fr);gap:clamp(20px,4vw,48px);align-items:center}
.in-regions{display:flex;flex-wrap:wrap;gap:8px;margin-bottom:16px}
.in-regions button{display:inline-flex;align-items:center;gap:8px;padding:9px 14px;border-radius:12px;border:1px solid var(--ln);background:#fff;font:700 .88rem var(--display);color:var(--n);cursor:pointer;transition:all .25s}
.in-regions button i{font-style:normal;font-size:.72rem;padding:1px 7px;border-radius:999px;background:var(--pp)}
.in-regions button.is-on{background:var(--n);color:#fff;border-color:var(--n)}
.in-regions button.is-on i{background:#ffffff26}
.in-flags{list-style:none;margin:0;padding:0;display:grid;grid-template-columns:repeat(auto-fill,minmax(190px,1fr));gap:8px}
.in-flags li{display:flex;align-items:center;gap:10px;padding:12px 14px;border-radius:14px;background:#fff;border:1px solid var(--ln);animation:inUp .4s both;animation-delay:calc(var(--i)*.05s)}
.in-flags li>span{font-size:1.3rem;line-height:1}
.in-flags b{font:800 .92rem var(--display);color:var(--n)}
.in-flags em{margin-left:auto;font-style:normal;font-size:.72rem;font-weight:700;color:var(--t);white-space:nowrap}
.in-mkts__globe{position:relative;aspect-ratio:1;max-width:400px;width:100%;justify-self:center;border-radius:50%;background:radial-gradient(circle,#0B22A8 0%,#07104F 70%);box-shadow:0 40px 80px -40px #07104F,inset 0 0 0 1px #ffffff1a;overflow:hidden}
.in-mkts__globe-in{position:absolute;inset:6%}

/* method */
.in-method__line{list-style:none;margin:0;padding:0;display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:14px;position:relative}
.in-method__line:before{content:"";position:absolute;left:12%;right:12%;top:34px;height:3px;border-radius:3px;background:linear-gradient(90deg,#C99A2E,#1E5BFF,#0E9C88,#5A3FE0);transform-origin:left;scale:0 1;transition:scale 1.6s cubic-bezier(.4,0,.2,1)}
.in-method.is-in .in-method__line:before{scale:1 1}
.in-method__line li{position:relative;text-align:center;display:flex;flex-direction:column;align-items:center;opacity:0;translate:0 14px;transition:opacity .5s,translate .5s;transition-delay:calc(var(--i)*.3s)}
.in-method.is-in .in-method__line li{opacity:1;translate:0 0}
.in-method__n{display:grid;place-items:center;width:68px;height:68px;border-radius:20px;background:#fff;border:2px solid var(--sc);color:var(--sc);box-shadow:0 12px 26px -16px #07104F88;transition:background .3s,color .3s,rotate .3s}
.in-method__line li:hover .in-method__n{background:var(--sc);color:#fff;rotate:-6deg}
.in-method__line b{margin-top:12px;font:800 1.05rem var(--display);color:var(--n)}
.in-method__line p{margin:4px 0 0;font-size:.9rem;color:var(--mu);max-width:24ch}

/* industry hero orbit */
.in-ihero__grid{display:grid;grid-template-columns:minmax(0,1.15fr) minmax(0,.85fr);gap:clamp(24px,4vw,56px);align-items:center}
.in-ihero__grp{display:inline-flex;align-items:center;gap:6px;margin-top:14px;padding:5px 12px;border-radius:999px;background:#ffffff14;border:1px solid #ffffff26;color:var(--lt);font:800 .78rem var(--display)}
.in-ihero h1{margin-top:10px}
.in-orbit{position:relative;aspect-ratio:1;max-width:400px;width:100%;justify-self:center}
.in-orbit__core{position:absolute;left:50%;top:50%;translate:-50% -50%;width:34%;aspect-ratio:1;border-radius:30%;display:grid;place-items:center;color:#fff;background:linear-gradient(145deg,var(--lt),var(--c));box-shadow:0 0 0 12px #ffffff0d,0 30px 60px -20px #000a;animation:inFloat 6s ease-in-out infinite;rotate:45deg}
.in-orbit__core svg{rotate:-45deg}
@keyframes inFloat{50%{translate:-50% -56%}}
.in-orbit__ring{position:absolute;inset:8%;border-radius:50%;border:1px dashed #ffffff33;animation:inSpin 50s linear infinite}
.in-orbit__ring--2{inset:22%;border-style:solid;border-color:#ffffff14;animation-direction:reverse;animation-duration:30s}
.in-orbit__pill{position:absolute;left:calc(50% + var(--dx) * 1%);top:calc(50% + var(--dy) * 1%);translate:-50% -50%;padding:7px 12px;border-radius:999px;background:#07104Fcc;border:1px solid color-mix(in srgb,var(--lt) 55%,transparent);color:#fff;font:700 .8rem var(--display);white-space:nowrap;backdrop-filter:blur(4px);animation:inUp .6s both,inBob 5s ease-in-out infinite;animation-delay:calc(var(--i)*.15s + .3s),calc(var(--i)*.7s)}
@keyframes inBob{50%{translate:-50% -62%}}

/* topics */
.in-topics{list-style:none;margin:0;padding:0;display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px}
.in-topics li{position:relative;padding:20px 18px;border-radius:18px;background:#fff;border:1px solid var(--ln);overflow:hidden;animation:inUp .5s both;animation-delay:calc(var(--i)*.1s);transition:translate .3s,box-shadow .3s}
.in-topics li:hover{translate:0 -3px;box-shadow:0 20px 36px -24px #07104F66}
.in-topics span{font:800 .78rem var(--display);color:var(--c)}
.in-topics b{display:block;margin-top:8px;font:800 1.05rem/1.25 var(--display);color:var(--n)}
.in-topics i{position:absolute;right:-24px;bottom:-24px;width:80px;height:80px;border-radius:50%;border:12px solid color-mix(in srgb,var(--c) 10%,transparent);transition:scale .4s}
.in-topics li:hover i{scale:1.3}

/* case cards */
.in-cases{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px}
.in-case{display:flex;flex-direction:column;padding:22px;border-radius:22px;background:#fff;border:1px solid var(--ln);animation:inUp .5s both;animation-delay:calc(var(--i)*.06s);transition:box-shadow .3s,border-color .3s}
.in-case:hover{box-shadow:0 26px 50px -32px #07104F77;border-color:color-mix(in srgb,var(--c) 35%,var(--ln))}
.in-case__head{display:flex;gap:14px;align-items:flex-start;margin-bottom:14px}
.in-case__n{flex:none;display:grid;place-items:center;width:40px;height:40px;border-radius:12px;background:var(--n);color:var(--t2);font:800 .82rem var(--display)}
.in-case__head h3{margin:0 0 8px;font:800 1.12rem/1.3 var(--display)}
.in-case__head h3 a{color:var(--n);text-decoration:none}
.in-case__head h3 a:hover{color:var(--r)}
.in-case .in-facts{margin-bottom:12px}
.in-case__chips{display:flex;flex-wrap:wrap;gap:6px;margin:0 0 14px}
.in-chip{padding:4px 10px;border-radius:999px;font:700 .74rem var(--display)}
.in-chip--s{background:#EEF2FF;color:var(--r)}
.in-chip--m{background:#E3F6F2;color:#0A7A6A}
.in-case__actions{display:flex;flex-wrap:wrap;gap:8px;margin-top:auto;padding-top:16px}
.in-loading{display:grid;grid-template-columns:repeat(3,1fr);gap:12px}
.in-loading i{height:160px;border-radius:18px;background:linear-gradient(90deg,#EEF1F7 30%,#F7F8FC 50%,#EEF1F7 70%);background-size:200% 100%;animation:inShim 1.4s linear infinite}
@keyframes inShim{to{background-position:-200% 0}}
.in-emptycard{display:flex;gap:14px;align-items:flex-start;padding:22px;border-radius:18px;background:#fff;border:1px dashed #B8C0D6;color:var(--r)}
.in-emptycard p{margin:4px 0 0;color:var(--mu)}
.in-emptycard strong{color:var(--n)}

/* case page */
.in-chero__kicker{display:inline-flex;align-items:center;gap:8px;margin:16px 0 0;padding:5px 12px;border-radius:999px;background:#ffffff14;border:1px solid #ffffff26;color:var(--lt);font:800 .82rem var(--display)}
.in-chero .mkts li{color:#fff}
.in-chero__steps{list-style:none;margin:18px 0 0;padding:0;display:flex;flex-wrap:wrap;gap:0}
.in-chero__steps li{display:flex;align-items:center;animation:inUp .5s both;animation-delay:calc(var(--i)*.15s + .3s)}
.in-chero__steps li+li:before{content:"";width:22px;height:2px;background:#ffffff33}
.in-chero__steps a{display:inline-flex;align-items:center;gap:6px;padding:7px 12px;border-radius:999px;border:1px solid color-mix(in srgb,var(--sc) 70%,transparent);color:#fff;font:700 .82rem var(--display);text-decoration:none;background:color-mix(in srgb,var(--sc) 18%,transparent)}
.in-chero__steps a:hover{background:var(--sc)}
.in-clayout{display:grid;grid-template-columns:minmax(0,1fr) 340px;gap:clamp(24px,4vw,48px);align-items:start}
.in-story{position:relative;padding-left:64px}
.in-story__rail{position:absolute;left:21px;top:10px;bottom:10px;width:3px;border-radius:3px;background:var(--ln);overflow:hidden}
.in-story__rail i{display:block;width:100%;background:linear-gradient(180deg,#C99A2E,#1E5BFF,#0E9C88,#5A3FE0);transition:height .2s}
.in-story__part{position:relative;margin-bottom:22px;padding:22px 24px;border-radius:20px;background:#fff;border:1px solid var(--ln);border-top:3px solid var(--sc)}
.in-story__node{position:absolute;left:-64px;top:18px;display:grid;place-items:center;width:46px;height:46px;border-radius:14px;background:var(--sc);color:#fff;box-shadow:0 10px 20px -10px var(--sc)}
.in-story__k{font:800 .74rem var(--display);color:var(--sc);letter-spacing:.1em}
.in-story__part h2{margin:4px 0 8px;font:800 1.4rem var(--display);color:var(--n)}
.in-story__part p{margin:0;line-height:1.7;color:var(--ink)}
.in-confidential{display:flex;gap:8px;align-items:center;font-size:.86rem;color:var(--mu)}
.in-snap{position:sticky;top:calc(var(--header-h) + 18px);padding:22px;border-radius:22px;background:linear-gradient(170deg,#07104F,#0B1A6E);color:#fff;box-shadow:0 30px 60px -30px #07104F}
.in-snap h2{margin:0 0 14px;font:800 1.15rem var(--display);color:#fff}
.in-snap h3{margin:14px 0 8px;font:800 .72rem var(--display);letter-spacing:.12em;text-transform:uppercase;color:#C9D3F5}
.in-snap ul{list-style:none;margin:0;padding:0;display:grid;gap:10px}
.in-snap li{display:flex;gap:10px;align-items:flex-start;font-size:.9rem;color:#E7ECFF}
.in-snap li>span{flex:none;display:grid;place-items:center;width:34px;height:34px;border-radius:10px;background:#ffffff14;color:var(--t2)}
.in-snap li b{display:block;font:800 .68rem var(--display);letter-spacing:.1em;text-transform:uppercase;color:#8E9AC6}
.in-snap .in-chip--s{background:#ffffff1a;color:#fff}
.in-snap .in-chip--m{background:#0E9C8833;color:var(--t2)}
.in-snap .btn{margin-top:8px}
.in-more{list-style:none;margin:0 0 18px;padding:0;display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px}
.in-more a{display:flex;flex-direction:column;gap:8px;height:100%;padding:20px;border-radius:18px;background:#fff;border:1px solid var(--ln);text-decoration:none;color:var(--n);transition:translate .3s,box-shadow .3s}
.in-more a:hover{translate:0 -3px;box-shadow:0 22px 40px -26px #07104F66}
.in-more__client{font:800 .72rem var(--display);letter-spacing:.08em;text-transform:uppercase;color:var(--t)}
.in-more b{font:800 1rem/1.3 var(--display)}
.in-more i{margin-top:auto;font-style:normal;font:800 .86rem var(--display);color:var(--r)}

/* responsive */
@media (max-width:1100px){
  .in-glance__grid{grid-template-columns:1fr 1fr}
  .in-topics{grid-template-columns:repeat(2,minmax(0,1fr))}
  .in-clayout{grid-template-columns:1fr}
  .in-snap{position:static}
}
@media (max-width:900px){
  .in-hero__grid,.in-ihero__grid,.in-mkts__grid,.in-feat{grid-template-columns:1fr}
  .in-hero__bg:after{background:linear-gradient(180deg,#07104Fcc,#07104F99)}
  .in-wheel{max-width:360px}
  .in-orbit{max-width:340px}
  .in-feat__rail{display:flex;overflow-x:auto;padding-bottom:4px}
  .in-feat__rail button{flex:none}
  .in-cases,.in-more{grid-template-columns:1fr}
  .in-mkts__globe{max-width:300px}
}
@media (max-width:640px){
  .in-stats{grid-template-columns:1fr 1fr}
  .in-stats--3{grid-template-columns:repeat(3,minmax(0,1fr))}
  .in-stats b{font-size:1.5rem}
  .in-glance__grid{grid-template-columns:1fr}
  .in-panel--wide{grid-column:auto}
  .in-bars li,.in-panel--wide .in-bars li{grid-template-columns:1fr 28px;row-gap:4px}
  .in-bars li i{grid-column:1/-1;grid-row:2}
  .in-tiles{grid-template-columns:1fr 1fr}
  .in-tile{height:140px}
  .in-tile__face strong{font-size:.9rem}
  .in-method__line{grid-template-columns:1fr 1fr;row-gap:24px}
  .in-method__line:before{display:none}
  .in-facts--grid{grid-template-columns:1fr}
  .in-orbit__pill{font-size:.68rem;padding:5px 9px;left:calc(50% + var(--dx) * .6%);white-space:normal;max-width:130px;text-align:center}
  .in-story{padding-left:0}
  .in-story__rail{display:none}
  .in-story__node{position:static;margin-bottom:10px}
  .in-mk{grid-template-columns:1fr}
  .in-loading{grid-template-columns:1fr}
}
@media (prefers-reduced-motion:reduce){
  .in *,.in *:before,.in *:after{animation:none!important;transition:none!important}
  .in-method__line li{opacity:1;translate:none}
  .in-bars i:after{scale:1 1}
}

/* Home redesign (hm-) */
.hm-partner,.hm-testi,.hm-svc,.hm-panels,.hm-why{--n:#07104F;--r:#0B22A8;--t2:#6EE0CE;--g2:#F0D98F;--mu:#525C78;--ln:#DDE2EC;--pp:#F6F7FB;position:relative}
.hm-head{max-width:720px;margin-bottom:clamp(20px,3vw,32px)}
.hm-head h2{margin:6px 0 8px;font:800 clamp(1.7rem,3vw,2.5rem)/1.12 var(--display);letter-spacing:-.02em;color:var(--n)}
.hm-head p{margin:0;color:var(--mu);font-size:1.06rem}
.hm-head--light h2{color:#fff}.hm-head--light p{color:#C9D3F5}
.hm-head--center{margin-inline:auto;text-align:center}
.hm-kicker{display:inline-flex;align-items:center;gap:10px;font:800 .74rem var(--display);letter-spacing:.16em;text-transform:uppercase;color:#0E9C88}
.hm-kicker:before{content:"";width:22px;height:2px;background:currentColor}
.hm-head--light .hm-kicker{color:var(--t2)}
.hm-head--center .hm-kicker:after{content:"";width:22px;height:2px;background:currentColor}

/* ---------- 1. partner ---------- */
.hm-partner__grid{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:clamp(24px,4vw,56px);align-items:center}
.hm-partner__q{margin:0 0 12px;font:700 .92rem var(--display);color:var(--n)}
.hm-needs{list-style:none;margin:0;padding:0;display:flex;flex-wrap:wrap;gap:8px}
.hm-needs li{opacity:0;translate:0 10px;transition:opacity .5s,translate .5s;transition-delay:calc(var(--i)*.07s)}
.hm-partner.is-in .hm-needs li{opacity:1;translate:0 0}
.hm-needs button{display:inline-flex;align-items:center;gap:8px;padding:9px 12px;border-radius:12px;border:1px solid var(--ln);background:#fff;font:700 .88rem var(--display);color:var(--n);cursor:pointer;transition:all .3s}
.hm-needs button svg{color:var(--c)}
.hm-needs button em{font-style:normal;font-size:.68rem;padding:2px 7px;border-radius:999px;background:color-mix(in srgb,var(--c) 12%,#fff);color:var(--c);max-width:0;overflow:hidden;opacity:0;transition:max-width .35s,opacity .35s,padding .35s;padding-inline:0}
.hm-needs button.is-on{background:var(--c);border-color:var(--c);color:#fff;box-shadow:0 12px 24px -14px var(--c)}
.hm-needs button.is-on svg{color:#fff}
.hm-needs button.is-on em{max-width:90px;opacity:1;padding-inline:7px;background:#ffffff2a;color:#fff}
.hm-hub{position:relative;aspect-ratio:1.15;max-width:520px;width:100%;justify-self:center}
.hm-hub__lines{position:absolute;inset:0;width:100%;height:100%}
.hm-hub__lines line{stroke:#B8C3E6;stroke-width:.5;stroke-dasharray:1.5 1.5;vector-effect:non-scaling-stroke;transition:stroke .4s,stroke-width .4s}
.hm-hub__lines line.is-on{stroke:var(--c);stroke-width:3;stroke-dasharray:none}
.hm-hub__ring{fill:none;stroke:#DDE2EC;stroke-width:1;vector-effect:non-scaling-stroke;rx:8}
.hm-hub__core{position:absolute;left:50%;top:50%;translate:-50% -50%;width:34%;aspect-ratio:1;border-radius:50%;display:flex;flex-direction:column;align-items:center;justify-content:center;text-align:center;background:radial-gradient(circle at 35% 30%,#2A55F0,#0B22A8 60%,#07104F);color:#fff;box-shadow:0 0 0 12px #0B22A80f,0 0 0 26px #0B22A808,0 30px 60px -24px #07104F;z-index:2}
.hm-hub__core:after{content:"";position:absolute;inset:-10px;border-radius:50%;border:1.5px solid #6EE0CE66;animation:hmPing 3s ease-out infinite}
@keyframes hmPing{0%{scale:.9;opacity:1}100%{scale:1.35;opacity:0}}
.hm-hub__core span{font:700 .7rem var(--display);letter-spacing:.1em;text-transform:uppercase;color:#C9D3F5}
.hm-hub__core b{font:800 clamp(1.8rem,3.4vw,2.6rem)/1 var(--display)}
.hm-hub__core em{font-style:normal;font-size:.72rem;color:var(--t2)}
.hm-hub__node{position:absolute;translate:-50% -50%;display:flex;flex-direction:column;align-items:center;gap:8px;text-align:center;z-index:2;transition:opacity .4s,scale .4s}
.hm-hub__node b{font:800 .88rem var(--display);color:var(--n);max-width:12ch}
.hm-hub__ic{display:grid;place-items:center;width:62px;height:62px;border-radius:20px;background:#fff;border:2px solid color-mix(in srgb,var(--c) 30%,#fff);color:var(--c);box-shadow:0 16px 30px -18px var(--c);transition:all .4s;animation:hmBob 5s ease-in-out infinite}
.hm-hub__node:nth-of-type(2n) .hm-hub__ic{animation-delay:-2.5s}
@keyframes hmBob{50%{translate:0 -6px}}
.hm-hub__node.is-on{scale:1.1}
.hm-hub__node.is-on .hm-hub__ic{background:var(--c);color:#fff;border-color:var(--c);box-shadow:0 0 0 8px color-mix(in srgb,var(--c) 18%,transparent),0 20px 36px -16px var(--c)}
.hm-hub__node.is-dim{opacity:.4}
.hm-hub__pulse{position:absolute;left:50%;top:50%;width:8px;height:8px;margin:-4px;border-radius:50%;background:var(--c);box-shadow:0 0 10px var(--c);animation:hmTravel 2.4s cubic-bezier(.5,0,.5,1) infinite;animation-delay:var(--d);opacity:0;z-index:1}
@keyframes hmTravel{0%{left:calc(50% + var(--x)*1%);top:calc(50% + var(--y)*1%);opacity:0}15%{opacity:1}85%{opacity:1}100%{left:50%;top:50%;opacity:0}}
.hm-pillars{list-style:none;margin:clamp(28px,4vw,44px) 0 0;padding:0;display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:14px}
.hm-pillars>li{opacity:0;translate:0 20px;transition:opacity .6s,translate .6s;transition-delay:calc(var(--i)*.12s)}
.hm-partner.is-in .hm-pillars>li{opacity:1;translate:0 0}
.hm-pillar{position:relative;display:flex;flex-direction:column;height:100%;padding:20px;border-radius:22px;background:#fff;border:1px solid var(--ln);text-decoration:none;color:inherit;overflow:hidden;transition:translate .35s,box-shadow .35s,border-color .35s}
.hm-pillar:before{content:"";position:absolute;inset:0 0 auto 0;height:4px;background:linear-gradient(90deg,var(--c),var(--lt));transform-origin:left;scale:.25 1;transition:scale .5s}
.hm-pillar:after{content:"";position:absolute;right:-40px;bottom:-40px;width:130px;height:130px;border-radius:50%;background:radial-gradient(circle,color-mix(in srgb,var(--lt) 30%,transparent),transparent 70%);transition:scale .5s}
.hm-pillar:hover,.hm-pillars li.is-on .hm-pillar{translate:0 -6px;box-shadow:0 28px 50px -30px var(--c);border-color:color-mix(in srgb,var(--c) 40%,var(--ln))}
.hm-pillar:hover:before,.hm-pillars li.is-on .hm-pillar:before{scale:1 1}
.hm-pillar:hover:after{scale:1.6}
.hm-pillar__top{display:flex;justify-content:space-between;align-items:flex-start}
.hm-pillar__ic{display:grid;place-items:center;width:46px;height:46px;border-radius:14px;background:color-mix(in srgb,var(--c) 10%,#fff);color:var(--c)}
.hm-pillar__n{display:flex;flex-direction:column;align-items:flex-end;font:800 1.8rem/1 var(--display);color:var(--c)}
.hm-pillar__n small{font:700 .66rem var(--display);letter-spacing:.08em;text-transform:uppercase;color:var(--mu)}
.hm-pillar h3{margin:14px 0 6px;font:800 1.15rem var(--display);color:var(--n)}
.hm-pillar p{margin:0 0 14px;font-size:.9rem;color:var(--mu)}
.hm-flow{list-style:none;margin:auto 0 12px;padding:0;display:flex;flex-wrap:wrap;align-items:center;gap:0}
.hm-flow li{display:flex;align-items:center;font:800 .74rem var(--display);color:var(--c);padding:4px 8px;border-radius:8px;background:color-mix(in srgb,var(--c) 8%,#fff);animation:hmStep 3.6s infinite;animation-delay:calc(var(--k)*.6s)}
.hm-flow li+li{margin-left:18px;position:relative}
.hm-flow li+li:before{content:"";position:absolute;left:-15px;width:12px;height:2px;background:var(--c);opacity:.5}
@keyframes hmStep{0%,100%{background:color-mix(in srgb,var(--c) 8%,#fff);color:var(--c)}15%,35%{background:var(--c);color:#fff}}
.hm-pillar__go{font:800 .84rem var(--display);color:var(--c)}

/* ---------- 2. testimonials ---------- */
.hm-testi{overflow:hidden;background:radial-gradient(60% 80% at 80% 10%,#13309C,transparent 70%),linear-gradient(170deg,#07104F,#0A1766);color:#fff}
.hm-testi__glow{position:absolute;left:-10%;bottom:-40%;width:60%;height:80%;border-radius:50%;background:radial-gradient(circle,#0E9C8833,transparent 70%);pointer-events:none}
.hm-testi__top{display:flex;justify-content:space-between;align-items:flex-end;gap:20px;flex-wrap:wrap}
.hm-testi__filters{display:flex;flex-wrap:wrap;gap:6px;margin-bottom:28px}
.hm-testi__filters button{display:inline-flex;align-items:center;gap:6px;padding:8px 12px;border-radius:999px;border:1px solid #ffffff26;background:#ffffff0a;color:#E7ECFF;font:700 .82rem var(--display);cursor:pointer;transition:all .25s}
.hm-testi__filters button svg{color:var(--c,#6EE0CE)}
.hm-testi__filters button i{font-style:normal;font-size:.7rem;padding:1px 6px;border-radius:999px;background:#ffffff1a}
.hm-testi__filters button.is-on{background:#fff;color:#07104F;border-color:#fff}
.hm-testi__filters button.is-on svg{color:#0B22A8}
.hm-deck{position:relative;height:340px;margin-top:6px}
.hm-tcard{position:absolute;left:50%;top:0;width:min(600px,86%);height:310px;margin:0;padding:28px 30px;border-radius:26px;background:linear-gradient(160deg,#ffffff,#F3F6FF);color:#14193D;box-shadow:0 40px 80px -40px #000;transform:translateX(calc(-50% + var(--off)*58%)) scale(calc(1 - var(--abs)*.14));opacity:calc(1 - var(--abs)*.55);z-index:calc(10 - var(--abs));transition:transform .8s cubic-bezier(.2,.7,.2,1),opacity .8s;cursor:pointer;display:flex;flex-direction:column;overflow:hidden}
.hm-tcard:not(.is-front) blockquote,.hm-tcard:not(.is-front) figcaption{opacity:.5}
.hm-tcard.is-front{cursor:default}
.hm-tcard:before{content:"";position:absolute;inset:0 0 auto 0;height:5px;background:linear-gradient(90deg,var(--c),var(--lt))}
.hm-tcard__q{position:absolute;right:22px;top:-18px;font:800 9rem/1 var(--display);color:color-mix(in srgb,var(--c) 14%,transparent);pointer-events:none}
.hm-tcard__top{display:flex;justify-content:space-between;align-items:center;gap:10px}
.hm-stars{display:flex;gap:3px}
.hm-stars i{width:16px;height:16px;background:#DDE2EC;clip-path:polygon(50% 0,61% 35%,98% 35%,68% 57%,79% 91%,50% 70%,21% 91%,32% 57%,2% 35%,39% 35%)}
.hm-stars i.on{background:#E3A013}
.hm-tcard.is-front .hm-stars i.on{animation:hmStar .5s both;animation-delay:calc(var(--s)*.1s + .3s)}
@keyframes hmStar{from{scale:0;rotate:-90deg}}
.hm-tcard__pill{display:inline-flex;align-items:center;gap:5px;padding:4px 10px;border-radius:999px;background:color-mix(in srgb,var(--c) 10%,#fff);color:var(--c);font:800 .74rem var(--display)}
.hm-tcard blockquote{margin:18px 0 auto;font:600 clamp(1rem,1.6vw,1.16rem)/1.55 var(--body);color:#14193D}
.hm-tcard.is-front blockquote{animation:hmFade .6s both .2s}
@keyframes hmFade{from{opacity:0;translate:0 8px}}
.hm-tcard figcaption{display:flex;align-items:center;gap:12px;margin-top:16px;padding-top:16px;border-top:1px solid #E3E8F4}
.hm-tcard__av{display:grid;place-items:center;width:46px;height:46px;border-radius:50%;background:linear-gradient(135deg,var(--c),var(--lt));color:#fff;font:800 .9rem var(--display);box-shadow:0 0 0 3px #fff,0 0 0 5px color-mix(in srgb,var(--c) 30%,transparent)}
.hm-tcard figcaption strong{display:block;font:800 .95rem var(--display);color:#07104F}
.hm-tcard figcaption small{font-size:.82rem;color:#525C78}
.hm-testi__nav{display:flex;justify-content:center;align-items:center;gap:16px;margin-top:8px}
.hm-round{width:44px;height:44px;border-radius:50%;border:1px solid #ffffff33;background:#ffffff0d;color:#fff;font-size:1.4rem;line-height:1;cursor:pointer;transition:background .25s}
.hm-round:hover{background:#ffffff26}
.hm-dots{display:flex;gap:8px}
.hm-dots button{position:relative;width:10px;height:10px;padding:0;border-radius:999px;border:0;background:#ffffff40;cursor:pointer;overflow:hidden;transition:width .4s,background .3s}
.hm-dots button.is-on{width:42px;background:#ffffff33}
.hm-dots button i{position:absolute;inset:0;background:var(--t2);transform-origin:left;animation:hmTimer 6s linear}
@keyframes hmTimer{from{scale:0 1}}
.hm-testi__note{margin:16px 0 0;text-align:center;font-size:.8rem;color:#8E9AC6}

/* ---------- 3. services ---------- */
.hm-svc{background:var(--pp)}
.hm-svc__top{display:flex;justify-content:space-between;align-items:flex-end;gap:20px;flex-wrap:wrap}
.hm-svc__total{display:flex;align-items:baseline;gap:10px;margin-bottom:28px;padding:12px 18px;border-radius:16px;background:#fff;border:1px solid var(--ln)}
.hm-svc__total b{font:800 2.4rem/1 var(--display);background:linear-gradient(135deg,#0B22A8,#0E9C88);-webkit-background-clip:text;background-clip:text;color:transparent}
.hm-svc__total span{font:700 .86rem var(--display);color:var(--mu)}
.hm-search{display:flex;align-items:center;gap:10px;max-width:560px;margin-bottom:18px;padding:12px 16px;border-radius:14px;border:1px solid var(--ln);background:#fff;color:var(--mu);box-shadow:0 8px 20px -16px #07104F55}
.hm-search:focus-within{border-color:var(--r)}
.hm-search input{flex:1;border:0;outline:0;background:none;font:500 1rem var(--body);color:#14193D}
.hm-search button{border:0;background:var(--pp);width:26px;height:26px;border-radius:50%;cursor:pointer;color:var(--mu)}
.hm-svc__grid{display:grid;grid-template-columns:300px minmax(0,1fr);gap:18px;align-items:start}
.hm-svc__teams{display:grid;gap:10px;position:sticky;top:calc(var(--header-h) + 16px)}
.hm-svc__teams button{position:relative;display:grid;grid-template-columns:auto 1fr auto;align-items:center;gap:12px;padding:14px;border-radius:16px;border:1px solid var(--ln);background:#fff;text-align:left;cursor:pointer;overflow:hidden;transition:all .3s}
.hm-svc__teams button:hover{border-color:var(--c);translate:4px 0}
.hm-svc__tic{display:grid;place-items:center;width:42px;height:42px;border-radius:12px;background:color-mix(in srgb,var(--c) 10%,#fff);color:var(--c);transition:all .3s}
.hm-svc__tt b{display:block;font:800 .95rem var(--display);color:#07104F}
.hm-svc__tt small{font-size:.74rem;color:var(--mu)}
.hm-svc__tn{font:800 1.4rem var(--display);color:var(--c)}
.hm-svc__tbar{position:absolute;left:0;bottom:0;height:3px;background:var(--c);opacity:.35;transition:opacity .3s}
.hm-svc__teams button.is-on{background:linear-gradient(135deg,var(--c),#07104F);border-color:transparent;box-shadow:0 18px 34px -20px var(--c)}
.hm-svc__teams button.is-on .hm-svc__tic{background:#ffffff26;color:#fff}
.hm-svc__teams button.is-on b,.hm-svc__teams button.is-on .hm-svc__tn{color:#fff}
.hm-svc__teams button.is-on small{color:#E1E7FF}
.hm-svc__teams button.is-on .hm-svc__tbar{opacity:1;background:var(--lt)}
.hm-svc__panel{padding:20px;border-radius:22px;background:#fff;border:1px solid var(--ln);animation:hmFade .4s both}
.hm-svc__intro{margin:0 0 16px;padding-left:12px;border-left:3px solid var(--c);color:#14193D}
.hm-tiles{list-style:none;margin:0;padding:0;display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:8px}
.hm-tiles>li{position:relative;animation:hmFade .4s both;animation-delay:calc(var(--k)*.03s)}
.hm-tiles>li.is-open{grid-column:span 2;grid-row:span 2}
.hm-tile{display:flex;align-items:center;gap:10px;width:100%;height:100%;min-height:58px;padding:10px 12px;border-radius:14px;border:1px solid var(--ln);background:var(--pp);text-align:left;cursor:pointer;transition:all .25s}
.hm-tile:hover{border-color:var(--c)}
.hm-tile__n{flex:none;display:grid;place-items:center;width:30px;height:30px;border-radius:9px;background:#fff;color:var(--c);font:800 .72rem var(--display);border:1px solid color-mix(in srgb,var(--c) 30%,#fff)}
.hm-tile b{font:800 .86rem/1.25 var(--display);color:#07104F}
.hm-tiles>li.is-open .hm-tile{height:auto;background:var(--c);border-color:var(--c);border-radius:14px 14px 0 0}
.hm-tiles>li.is-open .hm-tile b{color:#fff}
.hm-tiles>li.is-open .hm-tile__n{background:#ffffff26;color:#fff;border-color:transparent}
.hm-tile__more{padding:12px 14px 14px;border:1px solid var(--c);border-top:0;border-radius:0 0 14px 14px;background:#fff;animation:hmFade .3s both}
.hm-tile__more p{margin:0 0 8px;font-size:.88rem;color:#14193D}
.hm-tile__more ul{margin:0 0 10px;padding:0;list-style:none;display:grid;gap:4px}
.hm-tile__more li{font-size:.82rem;color:var(--mu);padding-left:16px;position:relative}
.hm-tile__more li:before{content:"";position:absolute;left:0;top:.5em;width:8px;height:8px;border-radius:2px;background:var(--c);rotate:45deg}
.hm-tile__more a{font:800 .84rem var(--display);color:var(--c)}
.hm-svc__all{display:inline-block;margin-top:16px;font:800 .9rem var(--display);color:var(--c)}

/* ---------- 4. panels ---------- */
.hm-value{display:grid;grid-template-columns:200px minmax(0,1fr) 200px;align-items:center;gap:10px;max-width:860px;margin:0 auto 28px}
.hm-value__side{display:flex;flex-direction:column;align-items:center;text-align:center;gap:4px;padding:14px;border-radius:16px;background:#fff;border:1px solid var(--ln);color:#0B22A8}
.hm-value__side b{font:800 .95rem var(--display);color:#07104F}
.hm-value__side span{font-size:.78rem;color:var(--mu)}
.hm-value__mid{position:relative;height:60px}
.hm-value__mid svg{position:absolute;inset:0;width:100%;height:100%}
.hm-value__line{stroke:#B8C3E6;stroke-width:2;stroke-dasharray:4 6;fill:none;vector-effect:non-scaling-stroke;animation:hmDash 1.2s linear infinite}
@keyframes hmDash{to{stroke-dashoffset:-20}}
.hm-value__mid i{position:absolute;top:50%;left:0;width:10px;height:10px;margin-top:-5px;border-radius:50%;background:#0E9C88;box-shadow:0 0 10px #0E9C88;animation:hmRun 2.8s linear infinite;animation-delay:var(--d)}
.hm-value__mid i:nth-child(odd){background:#F28C28;box-shadow:0 0 10px #F28C28;animation-direction:reverse}
@keyframes hmRun{from{left:0}to{left:calc(100% - 10px)}}
.hm-value__core{position:absolute;left:50%;top:50%;translate:-50% -50%;padding:8px 14px;border-radius:999px;background:#07104F;color:#fff;font:800 .8rem var(--display);box-shadow:0 0 0 6px #07104F14}
.hm-pcards{list-style:none;margin:0;padding:0;display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:16px;perspective:1200px}
.hm-pcards>li{opacity:0;translate:0 20px;transition:opacity .6s,translate .6s;transition-delay:calc(var(--i)*.15s)}
.hm-panels.is-in .hm-pcards>li{opacity:1;translate:0 0}
.hm-pcard{--rx:0deg;--ry:0deg;position:relative;display:flex;flex-direction:column;gap:10px;height:100%;padding:22px;border-radius:24px;background:#fff;border:1px solid var(--ln);text-decoration:none;color:inherit;transform:rotateX(var(--rx)) rotateY(var(--ry));transform-style:preserve-3d;transition:transform .25s,box-shadow .35s,border-color .35s;overflow:hidden}
.hm-pcard:before{content:"";position:absolute;inset:-40% -40% auto auto;width:220px;height:220px;border-radius:50%;background:radial-gradient(circle,color-mix(in srgb,var(--c) 20%,transparent),transparent 70%);transition:scale .5s}
.hm-pcard:hover,.hm-pcards li.is-on .hm-pcard{border-color:color-mix(in srgb,var(--c) 45%,var(--ln));box-shadow:0 30px 60px -34px var(--c)}
.hm-pcard:hover:before{scale:1.4}
.hm-pcard__logo{position:relative;transform:translateZ(30px)}
.hm-pcard__aud{position:relative;font:800 .72rem var(--display);letter-spacing:.08em;text-transform:uppercase;color:var(--c)}
.hm-pcard__tag{position:relative;font:800 1.12rem/1.3 var(--display);color:#07104F}
.hm-pcard__chips{position:relative;display:flex;flex-wrap:wrap;gap:5px}
.hm-pcard__chips em{font-style:normal;font-size:.74rem;font-weight:700;padding:3px 9px;border-radius:999px;background:color-mix(in srgb,var(--c) 9%,#fff);color:var(--c)}
.hm-pcard__go{position:relative;margin-top:auto;font:800 .86rem var(--display);color:var(--c)}
.hm-journey{margin-top:22px;padding:18px 20px;border-radius:20px;background:#fff;border:1px solid var(--ln);animation:hmFade .4s both}
.hm-journey__label{display:block;margin-bottom:12px;font:800 .72rem var(--display);letter-spacing:.12em;text-transform:uppercase;color:var(--mu)}
.hm-journey ol{list-style:none;margin:0;padding:0;display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:8px;position:relative}
.hm-journey ol:before{content:"";position:absolute;left:8%;right:8%;top:16px;height:2px;background:linear-gradient(90deg,var(--c),color-mix(in srgb,var(--c) 30%,#fff))}
.hm-journey li{position:relative;display:flex;flex-direction:column;align-items:center;text-align:center;gap:8px;animation:hmFade .4s both;animation-delay:calc(var(--k)*.12s)}
.hm-journey li span{display:grid;place-items:center;width:34px;height:34px;border-radius:50%;background:var(--c);color:#fff;font:800 .82rem var(--display);box-shadow:0 0 0 5px #fff}
.hm-journey li b{font:800 .84rem var(--display);color:#07104F}

/* ---------- 5. why ---------- */
.hm-why{background:radial-gradient(60% 80% at 20% 0,#13309C,transparent 70%),linear-gradient(170deg,#07104F,#0A1766);color:#fff;overflow:hidden}
.hm-why__grid{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:clamp(24px,4vw,56px);align-items:center}
.hm-toggle{position:relative;display:inline-grid;grid-template-columns:1fr 1fr;padding:4px;border-radius:14px;background:#ffffff12;border:1px solid #ffffff22;margin-bottom:16px}
.hm-toggle button{position:relative;z-index:1;padding:10px 16px;border:0;background:none;color:#C9D3F5;font:800 .86rem var(--display);cursor:pointer;transition:color .3s;white-space:nowrap}
.hm-toggle button.is-on{color:#07104F}
.hm-toggle i{position:absolute;left:4px;top:4px;bottom:4px;width:calc(50% - 4px);border-radius:10px;background:#fff;transition:translate .5s cubic-bezier(.2,.7,.2,1)}
.hm-cmp{list-style:none;margin:0;padding:0;display:grid;gap:8px;max-width:420px}
.hm-cmp li{display:flex;align-items:center;gap:10px;padding:10px 14px;border-radius:12px;font:700 .92rem var(--display);animation:hmFade .4s both;animation-delay:calc(var(--k)*.1s)}
.hm-cmp li.bad{background:#ffffff08;border:1px dashed #ffffff33;color:#C9D3F5}
.hm-cmp li.bad svg{color:#F28C8C}
.hm-cmp li.good{background:#6EE0CE1a;border:1px solid #6EE0CE55;color:#fff}
.hm-cmp li.good svg{color:var(--t2)}
.hm-silo{position:relative;aspect-ratio:1.2;max-width:500px;width:100%;justify-self:center}
.hm-silo>svg{position:absolute;inset:0;width:100%;height:100%}
.hm-silo__l{stroke:#ffffff;stroke-opacity:.12;stroke-width:1;stroke-dasharray:3 5;vector-effect:non-scaling-stroke;transition:stroke-opacity .6s}
.hm-silo.is-one .hm-silo__l{stroke-opacity:0}
.hm-silo__core{position:absolute;left:50%;top:50%;translate:-50% -50%;display:grid;place-items:center;width:44%;aspect-ratio:1;border-radius:50%;background:radial-gradient(circle at 35% 30%,#2A55F0,#0B22A8 60%,#07104F);font:800 1.1rem var(--display);box-shadow:0 0 0 14px #ffffff08,0 30px 60px -20px #000;scale:.3;opacity:0;transition:scale .7s cubic-bezier(.2,.8,.2,1),opacity .5s}
.hm-silo.is-one .hm-silo__core{scale:1;opacity:1}
.hm-silo__core:after{content:"";position:absolute;inset:-8px;border-radius:50%;border:2px dashed #6EE0CE77;animation:hmSpin 20s linear infinite}
@keyframes hmSpin{to{rotate:360deg}}
.hm-silo__n{position:absolute;left:var(--x);top:var(--y);translate:-50% -50%;display:flex;flex-direction:column;align-items:center;gap:6px;padding:14px 16px;border-radius:18px;background:#ffffff0d;border:1px dashed #ffffff40;color:var(--lt);transition:left .8s cubic-bezier(.65,0,.35,1),top .8s cubic-bezier(.65,0,.35,1),background .5s,border-color .5s,box-shadow .5s;transition-delay:calc(var(--k)*.06s)}
.hm-silo__n b{font:800 .8rem var(--display);color:#fff}
.hm-silo:not(.is-one) .hm-silo__n{animation:hmJit 3s ease-in-out infinite;animation-delay:calc(var(--k)*-.7s)}
@keyframes hmJit{50%{translate:-50% -58%}}
.hm-silo.is-one .hm-silo__n{left:var(--x1);top:var(--y1);background:var(--c);border:1px solid var(--lt);color:#fff;box-shadow:0 0 24px -6px var(--lt)}
.hm-reasons{list-style:none;margin:clamp(30px,4vw,48px) 0 0;padding:0;display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px}
.hm-reasons li{position:relative;padding:22px;border-radius:22px;background:#ffffff0a;border:1px solid #ffffff1c;overflow:hidden;opacity:0;translate:0 18px;transition:opacity .6s,translate .6s,background .3s,border-color .3s;transition-delay:calc(var(--k)*.1s),calc(var(--k)*.1s),0s,0s}
.hm-why.is-in .hm-reasons li{opacity:1;translate:0 0}
.hm-reasons li:hover{background:#ffffff14;border-color:#6EE0CE66}
.hm-reasons li:before{content:"";position:absolute;inset:0;background:linear-gradient(120deg,transparent 40%,#ffffff10 50%,transparent 60%);translate:-100% 0;transition:translate .8s}
.hm-reasons li:hover:before{translate:100% 0}
.hm-reasons__ic{display:grid;place-items:center;width:48px;height:48px;border-radius:15px;background:linear-gradient(135deg,#0E9C88,#1E5BFF);color:#fff;box-shadow:0 14px 28px -14px #1E5BFF;transition:rotate .4s}
.hm-reasons li:hover .hm-reasons__ic{rotate:-10deg}
.hm-reasons__n{position:absolute;right:18px;top:16px;font:800 2.2rem/1 var(--display);color:#ffffff14}
.hm-reasons h3{margin:14px 0 6px;font:800 1.1rem var(--display);color:#fff}
.hm-reasons p{margin:0;font-size:.92rem;color:#C9D3F5}

/* responsive */
@media (max-width:1100px){
  .hm-pillars{grid-template-columns:repeat(2,minmax(0,1fr))}
  .hm-svc__grid{grid-template-columns:1fr}
  .hm-svc__teams{position:static;grid-template-columns:repeat(2,minmax(0,1fr))}
  .hm-tiles{grid-template-columns:repeat(2,minmax(0,1fr))}
}
@media (max-width:900px){
  .hm-partner__grid,.hm-why__grid{grid-template-columns:1fr}
  .hm-pcards{grid-template-columns:1fr}
  .hm-reasons{grid-template-columns:1fr 1fr}
  .hm-value{grid-template-columns:1fr 1fr 1fr}
  .hm-journey ol{grid-template-columns:repeat(3,minmax(0,1fr));row-gap:16px}
  .hm-journey ol:before{display:none}
  .hm-deck{height:380px}
  .hm-tcard{height:350px}
}
@media (max-width:640px){
  .hm-pillars,.hm-reasons,.hm-svc__teams,.hm-tiles{grid-template-columns:1fr}
  .hm-tiles>li.is-open{grid-column:auto;grid-row:auto}
  .hm-hub{aspect-ratio:1}
  .hm-hub__ic{width:48px;height:48px;border-radius:15px}
  .hm-hub__node b{font-size:.74rem}
  .hm-hub__core{width:38%}
  .hm-hub__core em{display:none}
  .hm-deck{height:430px}
  .hm-tcard{width:90%;height:410px;padding:22px;transform:translateX(calc(-50% + var(--off)*104%))}
  .hm-value{grid-template-columns:1fr;gap:6px}
  .hm-value__mid{height:40px}
  .hm-journey ol{grid-template-columns:1fr 1fr}
  .hm-toggle button{padding:9px 10px;font-size:.78rem}
  .hm-silo{aspect-ratio:1}
}
@media (prefers-reduced-motion:reduce){
  .hm-partner *,.hm-testi *,.hm-svc *,.hm-panels *,.hm-why *{animation:none!important;transition:none!important}
  .hm-needs li,.hm-pillars>li,.hm-pcards>li,.hm-reasons li{opacity:1!important;translate:none!important}
}

/* ---------- 6. industries ---------- */
.hm-ind{--n:#07104F;--mu:#525C78;--ln:#DDE2EC;position:relative;overflow:hidden;background:radial-gradient(50% 60% at 80% 40%,#E6EDFF,transparent 70%),linear-gradient(180deg,#fff,#F4F7FE)}
.hm-ind__grid{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:clamp(24px,4vw,56px);align-items:center}
.hm-ind__stats{list-style:none;margin:0 0 18px;padding:0;display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:8px}
.hm-ind__stats li{padding:12px;border-radius:14px;background:#fff;border:1px solid var(--ln);box-shadow:0 10px 24px -20px #07104F}
.hm-ind__stats b{display:block;font:800 1.7rem/1 var(--display);background:linear-gradient(135deg,#0B22A8,#0E9C88);-webkit-background-clip:text;background-clip:text;color:transparent}
.hm-ind__stats span{font:700 .74rem var(--display);color:var(--mu)}
.hm-ind__map{position:relative;margin-bottom:20px;padding:12px 12px 30px;border-radius:20px;background:linear-gradient(160deg,#07104F,#0B1A6E);overflow:hidden}
.hm-ind__map svg{display:block;width:100%;height:auto}
.hm-ind__map path{fill:#ffffff14;stroke:#ffffff10;stroke-width:.5}
.hm-ind__map path.on{fill:#6EE0CE55}
.hm-ind__pin{position:absolute;translate:-50% -50%;margin:6px 0 0 12px;line-height:0;animation:hmPinIn .5s both;animation-delay:var(--d)}
.hm-ind__pin:after{content:"";position:absolute;left:50%;top:50%;width:26px;height:26px;margin:-13px;border-radius:50%;border:1.5px solid #6EE0CE;animation:hmPinPing 2.6s ease-out infinite;animation-delay:var(--d)}
.hm-ind__pin .rg-flag{max-width:none}
@keyframes hmPinIn{from{scale:0}}
@keyframes hmPinPing{0%{scale:.3;opacity:1}100%{scale:1.6;opacity:0}}
.hm-ind__map em{position:absolute;left:14px;bottom:10px;font-style:normal;font:800 .74rem var(--display);letter-spacing:.06em;color:#C9D3F5}
.hm-ind__ctas{display:flex;flex-wrap:wrap;align-items:center;gap:14px}
.hm-ind__hint{display:inline-flex;align-items:center;gap:6px;font:700 .8rem var(--display);color:var(--mu)}
.hm-sphere{position:relative;aspect-ratio:1;max-width:540px;width:100%;justify-self:center;touch-action:none;cursor:grab;user-select:none}
.hm-sphere:active{cursor:grabbing}
.hm-sphere__core{position:absolute;left:50%;top:50%;translate:-50% -50%;width:30%;aspect-ratio:1;border-radius:50%;display:flex;flex-direction:column;align-items:center;justify-content:center;background:radial-gradient(circle at 35% 30%,#2A55F0,#0B22A8 60%,#07104F);color:#fff;box-shadow:0 0 0 14px #0B22A80d,0 0 0 30px #0B22A808,0 30px 60px -20px #07104F;z-index:62;pointer-events:none}
.hm-sphere__core b{font:800 clamp(2rem,3.6vw,2.8rem)/1 var(--display)}
.hm-sphere__core span{font:700 .76rem var(--display);color:#6EE0CE;letter-spacing:.08em;text-transform:uppercase}
.hm-sphere__ring{position:absolute;inset:6%;border-radius:50%;border:1px dashed #0B22A833;pointer-events:none}
.hm-sphere__n{position:absolute;left:50%;top:50%;display:inline-flex;align-items:center;gap:6px;padding:6px 11px;border-radius:999px;background:#fff;border:1px solid color-mix(in srgb,var(--c) 30%,#DDE2EC);color:#07104F;font:700 .8rem var(--display);white-space:nowrap;text-decoration:none;box-shadow:0 8px 18px -12px #07104F;will-change:transform,opacity;transition:background .2s,color .2s,box-shadow .2s}
.hm-sphere__n svg{color:var(--c);flex:none}
.hm-sphere__n.is-back{pointer-events:none}
.hm-sphere__n.is-back span{display:none}
.hm-sphere__n.is-back{padding:6px}
.hm-sphere__n:hover,.hm-sphere__n:focus-visible{background:var(--c);color:#fff;border-color:var(--c);box-shadow:0 12px 26px -10px var(--c);z-index:200!important}
.hm-sphere__n:hover svg{color:#fff}
.hm-marq{margin-top:clamp(28px,4vw,44px);display:grid;gap:10px;mask-image:linear-gradient(90deg,transparent,#000 6%,#000 94%,transparent)}
.hm-marq__row{overflow:hidden}
.hm-marq__track{display:flex;width:max-content;animation:hmMarq 40s linear infinite}
.hm-marq__row--rev .hm-marq__track{animation-direction:reverse;animation-duration:46s}
.hm-marq:hover .hm-marq__track{animation-play-state:paused}
.hm-marq__set{display:flex;gap:10px;padding-right:10px}
@keyframes hmMarq{to{translate:-50% 0}}
.hm-marq__pill{display:inline-flex;align-items:center;gap:8px;padding:10px 16px;border-radius:14px;background:#fff;border:1px solid #DDE2EC;color:#07104F;font:800 .9rem var(--display);white-space:nowrap;text-decoration:none;transition:all .25s}
.hm-marq__pill svg{color:var(--c)}
.hm-marq__pill:hover{background:var(--c);color:#fff;border-color:var(--c);translate:0 -2px}
.hm-marq__pill:hover svg{color:#fff}
.hm-marq__pill--more{background:#07104F;color:#fff;border-color:#07104F}
@media (max-width:900px){
  .hm-ind__grid{grid-template-columns:1fr}
  .hm-sphere{max-width:420px;order:-1}
}
@media (max-width:640px){
  .hm-ind__stats{grid-template-columns:1fr 1fr}
  .hm-sphere__n{font-size:.68rem;padding:4px 8px}
  .hm-sphere__n svg{width:12px;height:12px}
  .hm-sphere__n.is-mid span{display:none}
  .hm-sphere__n.is-mid{padding:5px}
}
@media (prefers-reduced-motion:reduce){
  .hm-ind *{animation:none!important}
}

/* Home hero slider + business challenge (hh-) */
.hh{--mx:0;--my:0;position:relative;isolation:isolate;overflow:hidden;color:#fff;background:linear-gradient(160deg,#050C3F,#07104F 45%,#0A1766);min-height:max(660px,calc(100vh - var(--header-h)));display:flex;flex-direction:column}
.hh__bg{position:absolute;inset:0;z-index:-1;pointer-events:none}
.hh__bg .abh-silk>svg{opacity:.5}
.hh__bg .abh-silk__tag{display:none}
.hh__grid{position:absolute;inset:0;background-image:linear-gradient(#ffffff08 1px,transparent 1px),linear-gradient(90deg,#ffffff08 1px,transparent 1px);background-size:56px 56px;mask-image:radial-gradient(70% 70% at 70% 45%,#000,transparent);transform:perspective(900px) rotateX(55deg) translateY(30%) scale(1.6);transform-origin:50% 100%}
@keyframes hhGrid{to{background-position:0 56px,56px 0}}
.hh__glow{position:absolute;right:-10%;top:5%;width:70%;height:90%;border-radius:50%;background:radial-gradient(circle,color-mix(in srgb,var(--c) 45%,transparent),transparent 65%);transition:background 1s}
.hh__inner{position:relative;flex:1;display:flex;flex-direction:column;justify-content:center;padding-top:clamp(36px,5vw,64px);padding-bottom:22px}
.hh__slides{display:grid;flex:1}
.hh-slide{grid-area:1/1;display:grid;grid-template-columns:minmax(0,1.02fr) minmax(0,.98fr);gap:clamp(20px,4vw,56px);align-items:center;opacity:0;visibility:hidden;transition:opacity .6s,visibility 0s .6s}
.hh-slide.is-on{opacity:1;visibility:visible;transition:opacity .6s}
.hh-copy>*{opacity:0;translate:0 24px}
.hh-slide.is-on .hh-copy>*{animation:hhIn .8s cubic-bezier(.2,.7,.2,1) forwards}
.hh-slide.is-on .hh-copy>*:nth-child(2){animation-delay:.1s}
.hh-slide.is-on .hh-copy>*:nth-child(3){animation-delay:.2s}
.hh-slide.is-on .hh-copy>*:nth-child(4){animation-delay:.3s}
.hh-slide.is-on .hh-copy>*:nth-child(5){animation-delay:.4s}
.hh-slide.is-on .hh-copy>*:nth-child(6){animation-delay:.5s}
@keyframes hhIn{to{opacity:1;translate:0 0}}
.hh-kicker{display:flex;flex-wrap:wrap;gap:6px 14px;margin:0 0 16px;font:800 .82rem var(--display);letter-spacing:.04em}
.hh-kicker span{display:inline-flex;align-items:center;gap:7px;color:#E7ECFF}
.hh-kicker span:before{content:"";width:8px;height:8px;border-radius:50%;background:var(--c);box-shadow:0 0 10px var(--c)}
.hh-kicker--one{align-items:center;gap:10px;color:var(--lt);text-transform:uppercase;letter-spacing:.12em}
.hh-kicker__ic{display:grid;place-items:center;width:32px;height:32px;border-radius:10px;background:color-mix(in srgb,var(--c) 40%,transparent);border:1px solid color-mix(in srgb,var(--lt) 50%,transparent);color:#fff}
.hh-kicker--one:before{display:none}
.hh-kicker em{font-style:normal;color:#8E9AC6;letter-spacing:.06em}
.hh-title{margin:0 0 16px;font:800 clamp(2.3rem,4.8vw,4.2rem)/1.02 var(--display);letter-spacing:-.03em;color:#fff;max-width:15ch}
h2.hh-title{font-size:clamp(2rem,4vw,3.4rem);background:linear-gradient(120deg,#fff 30%,var(--lt));-webkit-background-clip:text;background-clip:text;color:transparent}
.hh-title span{display:block;margin-top:8px;font-size:.6em;background:linear-gradient(90deg,#6EE0CE,#9DB8FF,#F0D98F,#6EE0CE);background-size:300% 100%;-webkit-background-clip:text;background-clip:text;color:transparent;animation:hhShine 8s linear infinite}
@keyframes hhShine{to{background-position:300% 0}}
.hh-lead{margin:0 0 24px;font:700 clamp(1.05rem,1.6vw,1.3rem)/1.45 var(--display);color:#E1E7FF;max-width:34ch}
.hh-text{margin:0 0 16px;font-size:1.05rem;color:#C9D3F5;max-width:52ch}
.hh-flow{list-style:none;margin:0 0 16px;padding:0;display:flex;flex-wrap:wrap;align-items:center}
.hh-flow li{display:flex;align-items:center;padding:6px 12px;border-radius:999px;border:1px solid color-mix(in srgb,var(--lt) 45%,transparent);font:800 .84rem var(--display);color:var(--lt);background:#ffffff08;animation:hhFlow 3s infinite;animation-delay:calc(var(--n)*.5s + 1s)}
.hh-flow li+li{margin-left:26px;position:relative}
.hh-flow li+li:before{content:"";position:absolute;left:-22px;width:18px;height:2px;background:linear-gradient(90deg,transparent,var(--lt))}
@keyframes hhFlow{0%,100%{background:#ffffff08;color:var(--lt)}12%,30%{background:var(--lt);color:#07104F}}
.hh-svcs{list-style:none;margin:0 0 24px;padding:0;display:flex;flex-wrap:wrap;gap:8px;max-width:600px}
.hh-svcs a{display:inline-block;padding:7px 12px;border-radius:10px;background:#ffffff0f;border:1px solid #ffffff22;color:#fff;font:700 .84rem var(--display);text-decoration:none;transition:all .25s}
.hh-svcs a:hover{background:var(--c);border-color:var(--lt);translate:0 -2px}
.hh-svcs__more{color:var(--lt)!important;border-style:dashed!important}
.hh-ctas{display:flex;flex-wrap:wrap;gap:12px}
.hh-brand{margin:22px 0 0;font:normal 600 1.05rem var(--display);color:#C9D3F5;display:flex;align-items:center;gap:12px}
.hh-brand:before{content:"";width:36px;height:1px;background:#C9D3F5}

/* scenes */
.hh-scene{position:relative;height:clamp(380px,40vw,500px);perspective:1200px}
.hh-scene>*{transform:rotateY(calc(var(--mx)*12deg)) rotateX(calc(var(--my)*-10deg));transition:transform .3s ease-out;transform-style:preserve-3d}
.hh-slide.is-on .hh-scene>*{animation:hhScene 1s cubic-bezier(.2,.7,.2,1) both}
@keyframes hhScene{from{opacity:0;scale:.9}}
.hh-sc{position:absolute;inset:0}
.hh-card{position:absolute;border-radius:20px;background:linear-gradient(160deg,#1A2C9Ef2,#0C1A72f2);border:1px solid #ffffff2e;backdrop-filter:blur(10px);box-shadow:0 30px 60px -30px #000c,inset 0 1px 0 #ffffff33;padding:16px}
.hh-card__k{display:block;margin-bottom:10px;font:800 .7rem var(--display);letter-spacing:.12em;text-transform:uppercase;color:var(--lt)}
.hh-card small{position:absolute;right:12px;bottom:8px;font-size:.6rem;color:#8E9AC6;letter-spacing:.04em}
.hh-float{animation:hhFloat 6s ease-in-out infinite}
.hh-float--2{animation-delay:-3s;animation-duration:7s}
@keyframes hhFloat{50%{translate:0 -12px}}

/* intro: cube + flag orbits */
.hh-intro{position:absolute;inset:0;display:grid;place-items:center}
.hh-cubewrap{position:relative;width:200px;height:200px;perspective:900px}
.hh-cube{position:absolute;inset:0;transform-style:preserve-3d;will-change:transform;animation:hhCube 16s cubic-bezier(.65,0,.35,1) infinite}
@keyframes hhCube{0%,18%{transform:rotateX(-14deg) rotateY(-20deg)}25%,43%{transform:rotateX(-14deg) rotateY(-110deg)}50%,68%{transform:rotateX(-14deg) rotateY(-200deg)}75%,93%{transform:rotateX(-14deg) rotateY(-290deg)}100%{transform:rotateX(-14deg) rotateY(-380deg)}}
.hh-face{position:absolute;inset:0;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:8px;border-radius:26px;background:linear-gradient(150deg,color-mix(in srgb,var(--lt) 70%,#fff 10%),var(--c) 55%,#07104F);border:1px solid #ffffff55;box-shadow:inset 0 0 40px #ffffff22,0 0 40px -10px var(--lt);backface-visibility:hidden;text-align:center;color:#fff}
.hh-face b{font:800 1.15rem/1.15 var(--display);max-width:9ch}
.hh-face em{font-style:normal;font:700 .78rem var(--display);padding:3px 10px;border-radius:999px;background:#07104F55}
.hh-face--0{transform:translateZ(100px)}
.hh-face--1{transform:rotateY(90deg) translateZ(100px)}
.hh-face--2{transform:rotateY(180deg) translateZ(100px)}
.hh-face--3{transform:rotateY(270deg) translateZ(100px)}
.hh-face--top{transform:rotateX(90deg) translateZ(100px);background:linear-gradient(135deg,#1E5BFF,#07104F);border-radius:26px}
.hh-face--bottom{transform:rotateX(-90deg) translateZ(100px);background:#07104F}
.hh-cubeshadow{position:absolute;left:50%;bottom:-70px;width:220px;height:40px;translate:-50% 0;border-radius:50%;background:radial-gradient(closest-side,#000a,transparent);animation:hhShadow 4s ease-in-out infinite}
@keyframes hhShadow{50%{scale:.85;opacity:.7}}
.hh-orbit{position:absolute;left:50%;top:50%;width:420px;height:420px;margin:-210px 0 0 -210px;border-radius:50%;animation:hhSpin 40s linear infinite;will-change:transform}
.hh-intro:before,.hh-intro:after{content:"";position:absolute;left:50%;top:50%;width:420px;height:420px;margin:-210px 0 0 -210px;border-radius:50%;border:1px dashed #ffffff26}
.hh-intro:after{width:520px;height:520px;margin:-260px 0 0 -260px;border-color:#6EE0CE22}
.hh-orbit--b{width:520px;height:520px;margin:-260px 0 0 -260px;animation-duration:60s;animation-direction:reverse}
.hh-orbit span{position:absolute;left:50%;top:50%;width:0;height:0;transform:rotate(var(--a)) translateX(210px)}
.hh-orbit--b span{transform:rotate(var(--a)) translateX(260px)}
.hh-orbit span .rg-flag{position:absolute;max-width:none;translate:-50% -50%;width:30px;height:22px;animation:hhSpin 40s linear infinite reverse;box-shadow:0 0 0 2px #ffffff33;will-change:transform}
.hh-orbit--b span .rg-flag{animation-duration:60s;animation-direction:normal}
@keyframes hhSpin{to{rotate:360deg}}
.hh-chip{position:absolute;display:flex;align-items:baseline;gap:6px;padding:10px 14px;border-radius:14px;background:#07104Fcc;border:1px solid #ffffff2e;backdrop-filter:blur(8px);box-shadow:0 20px 40px -20px #000;animation:hhFloat 6s ease-in-out infinite}
.hh-chip b{font:800 1.5rem var(--display);color:#6EE0CE}
.hh-chip span{font:700 .78rem var(--display);color:#E7ECFF}
.hh-chip--1{left:2%;top:14%}
.hh-chip--2{right:0;top:40%;animation-delay:-2s}.hh-chip--2 b{color:#F0D98F}
.hh-chip--3{left:8%;bottom:8%;animation-delay:-4s}.hh-chip--3 b{color:#A8B6FF}

/* research */
.hh-map{left:0;top:6%;width:92%;padding:12px;aspect-ratio:2/1.05}
.hh-map svg{width:100%;height:auto;display:block}
.hh-map path{fill:#ffffff14;stroke:#ffffff10;stroke-width:.5}
.hh-map path.on{fill:color-mix(in srgb,var(--lt) 45%,transparent)}
.hh-pin{position:absolute;line-height:0;translate:-50% -50%;margin-left:12px;margin-top:6px;animation:hhPop .5s both;animation-delay:var(--d)}
.hh-pin:after{content:"";position:absolute;left:50%;top:50%;width:30px;height:30px;margin:-15px;border-radius:50%;border:1.5px solid var(--lt);animation:hhPing 2.4s ease-out infinite;animation-delay:var(--d)}
@keyframes hhPop{from{scale:0}}
@keyframes hhPing{0%{scale:.3;opacity:1}100%{scale:1.6;opacity:0}}
.hh-survey{right:0;bottom:4%;width:260px}
.hh-bar{display:grid;grid-template-columns:96px 1fr;align-items:center;gap:8px;margin-bottom:8px;font-size:.74rem;color:#E7ECFF}
.hh-bar i{height:8px;border-radius:5px;background:#ffffff14;position:relative;overflow:hidden}
.hh-bar i:after{content:"";position:absolute;inset:0;width:var(--w);border-radius:5px;background:linear-gradient(90deg,var(--c),var(--lt));transform-origin:left;animation:hhGrow 1.2s cubic-bezier(.2,.7,.2,1) both;animation-delay:calc(var(--i)*.15s + .5s)}
@keyframes hhGrow{from{scale:0 1}}
.hh-quota{left:6%;bottom:0;display:flex;align-items:center;gap:12px}
.hh-quota svg{width:56px;height:56px;rotate:-90deg}
.hh-quota circle{fill:none;stroke-width:5}
.hh-quota .bg{stroke:#ffffff1a}
.hh-quota .fg{stroke:var(--lt);stroke-linecap:round;stroke-dasharray:0 100;animation:hhRing 4s ease-in-out infinite}
@keyframes hhRing{0%{stroke-dasharray:0 100}60%,100%{stroke-dasharray:82 100}}
.hh-quota b{display:block;font:800 .95rem var(--display)}
.hh-quota span{font-size:.74rem;color:#C9D3F5}

/* digital */
.hh-growth{left:0;top:4%;width:88%}
.hh-growth svg{width:100%;height:auto;display:block;overflow:visible}
.hh-line{fill:none;stroke:var(--lt);stroke-width:3;stroke-linecap:round;stroke-dasharray:1;stroke-dashoffset:1;animation:hhDraw 2s cubic-bezier(.4,0,.2,1) .3s forwards}
@keyframes hhDraw{to{stroke-dashoffset:0}}
.hh-area{opacity:0;animation:hhFade 1s 1.4s forwards}
@keyframes hhFade{to{opacity:1}}
.hh-dot{fill:#fff;filter:drop-shadow(0 0 8px var(--lt));animation:hhPop .4s 2.2s both}
.hh-serp{right:2%;top:46%;width:230px}
.hh-serp__row{display:flex;align-items:center;gap:8px;height:28px;margin-bottom:6px;padding:0 10px;border-radius:8px;background:#ffffff0d;font:800 .78rem var(--display)}
.hh-serp__row i{width:10px;height:10px;border-radius:3px;background:#ffffff33}
.hh-serp__row span{flex:1;height:6px;border-radius:3px;background:#ffffff22}
.hh-serp__row.is-you{background:var(--c);box-shadow:0 0 0 1px var(--lt),0 10px 24px -10px var(--lt);animation:hhRank 1s cubic-bezier(.2,.7,.2,1) 1s both}
.hh-serp__row.is-you i{background:#fff}
@keyframes hhRank{from{translate:0 68px;opacity:.6}}
.hh-funnel{left:6%;bottom:0;width:200px;display:grid;gap:6px;justify-items:center}
.hh-funnel div{width:calc(100% - var(--k)*40px);padding:7px;border-radius:10px;text-align:center;font:800 .76rem var(--display);background:color-mix(in srgb,var(--lt) calc(30% + var(--k)*25%),transparent);color:#fff;animation:hhPop .5s both;animation-delay:calc(var(--k)*.2s + .6s)}

/* tech */
.hh-code{left:0;top:6%;width:78%;padding:0 0 14px;font:600 .9rem/1.9 ui-monospace,Menlo,Consolas,monospace;overflow:hidden}
.hh-code__bar{display:flex;align-items:center;gap:6px;padding:10px 14px;margin-bottom:10px;border-bottom:1px solid #ffffff1a;font:700 .74rem var(--display);color:#C9D3F5}
.hh-code__bar i{width:10px;height:10px;border-radius:50%;background:#EF4F5A}.hh-code__bar i:nth-child(2){background:#E3A013}.hh-code__bar i:nth-child(3){background:#0E9C88}
.hh-code__bar span{margin-left:8px}
.hh-code__ln{padding:0 16px;white-space:nowrap;overflow:hidden;width:0;animation:hhType .7s steps(24) forwards;animation-delay:calc(var(--k)*.6s + .3s)}
@keyframes hhType{to{width:100%}}
.hh-code__ln em{font-style:normal;color:#5C6A9E;margin-right:12px}
.hh-code__ln b{color:var(--lt)}
.hh-code__ln span{color:#F0D98F}
.hh-code__ln u{text-decoration:none;color:#6EE0CE}
.hh-caret{display:inline-block;width:8px;height:16px;margin-left:16px;background:var(--lt);animation:hhBlink 1s steps(1) infinite}
@keyframes hhBlink{50%{opacity:0}}
.hh-phone{right:4%;top:20%;width:130px;height:240px;border-radius:26px;padding:26px 12px 12px}
.hh-phone__notch{position:absolute;left:50%;top:8px;width:40px;height:6px;margin-left:-20px;border-radius:3px;background:#ffffff33}
.hh-phone__row{height:36px;margin-bottom:10px;border-radius:10px;background:linear-gradient(90deg,color-mix(in srgb,var(--lt) 40%,transparent),#ffffff10);animation:hhPop .4s both;animation-delay:calc(var(--k)*.25s + 1s)}
.hh-phone__row:first-of-type{height:70px;background:linear-gradient(135deg,var(--c),var(--lt))}
.hh-nodes{left:10%;bottom:0;display:flex;align-items:center;gap:10px}
.hh-nodes svg{width:110px;height:72px}
.hh-nodes path{fill:none;stroke:var(--lt);stroke-width:1.5;stroke-dasharray:4 4;animation:hhDash 1.2s linear infinite}
@keyframes hhDash{to{stroke-dashoffset:-16}}
.hh-nodes circle{fill:var(--c);stroke:#fff;stroke-width:1.5}
.hh-nodes span{font:800 .86rem var(--display)}

/* finance */
.hh-ledger{left:0;top:8%;width:70%;height:240px}
.hh-cols{display:flex;align-items:flex-end;gap:12px;height:170px;padding-top:10px;border-bottom:1px solid #ffffff22}
.hh-cols i{flex:1;height:var(--h);border-radius:8px 8px 2px 2px;background:linear-gradient(180deg,var(--lt),var(--c));transform-origin:bottom;animation:hhGrowY 1s cubic-bezier(.2,.7,.2,1) both;animation-delay:calc(var(--k)*.12s + .3s)}
@keyframes hhGrowY{from{scale:1 0}}
.hh-pie{right:6%;top:6%;display:flex;flex-direction:column;align-items:center;gap:6px}
.hh-pie svg{width:110px;height:110px;rotate:-90deg;animation:hhSpin 20s linear infinite}
.hh-pie circle{fill:none;stroke-width:8}
.hh-pie .s1{stroke:var(--lt);stroke-dasharray:45 100}
.hh-pie .s2{stroke:#6EE0CE;stroke-dasharray:30 100;stroke-dashoffset:-46}
.hh-pie .s3{stroke:#A8B6FF;stroke-dasharray:23 100;stroke-dashoffset:-77}
.hh-pie span{font:800 .86rem var(--display)}
.hh-checks{right:2%;bottom:6%;display:grid;gap:8px;width:190px}
.hh-checks div{display:flex;align-items:center;gap:8px;padding:8px 10px;border-radius:10px;background:#ffffff0d;font:800 .84rem var(--display);animation:hhPop .4s both;animation-delay:calc(var(--k)*.3s + .8s)}
.hh-checks svg{color:#07104F;background:var(--lt);border-radius:50%;padding:2px}
.hh-coins{position:absolute;left:12%;bottom:4%;width:90px;height:110px}
.hh-coins i{position:absolute;left:0;bottom:calc(var(--k)*16px);width:80px;height:22px;border-radius:50%;background:linear-gradient(180deg,#FFF3C4,#C99A2E);box-shadow:inset 0 -4px 0 #9A6B12,0 6px 12px -6px #000;animation:hhCoin .6s cubic-bezier(.3,1.4,.5,1) both;animation-delay:calc(var(--k)*.15s + .6s)}
@keyframes hhCoin{from{translate:0 -140px;opacity:0}}

/* nav */
.hh-nav{display:flex;align-items:center;gap:12px;margin-top:24px}
.hh-arrow{flex:none;width:44px;height:44px;border-radius:50%;border:1px solid #ffffff33;background:#ffffff0d;color:#fff;font-size:1.4rem;cursor:pointer;transition:background .25s}
.hh-arrow:hover{background:#ffffff26}
.hh-tabs{flex:1;display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:8px}
.hh-tab{position:relative;display:flex;align-items:center;gap:8px;padding:10px 12px 14px;border-radius:14px;border:1px solid #ffffff1f;background:#ffffff08;color:#C9D3F5;cursor:pointer;text-align:left;transition:all .3s;overflow:hidden}
.hh-tab:hover{background:#ffffff12;color:#fff}
.hh-tab__ic{display:grid;place-items:center;width:30px;height:30px;border-radius:9px;background:#ffffff12;color:var(--c);flex:none}
.hh-tab__t{font:800 .82rem/1.2 var(--display)}
.hh-tab__bar{position:absolute;left:12px;right:12px;bottom:6px;height:3px;border-radius:2px;background:#ffffff14;overflow:hidden}
.hh-tab__bar b{position:absolute;inset:0;background:var(--c);transform-origin:left;animation:hhProg linear forwards}
.hh-tab__bar b.is-paused{animation-play-state:paused}
@keyframes hhProg{from{scale:0 1}}
.hh-tab.is-on{background:#ffffff1a;border-color:color-mix(in srgb,var(--c) 60%,transparent);color:#fff;box-shadow:0 12px 30px -16px var(--c)}
.hh-tab.is-on .hh-tab__ic{background:var(--c);color:#07104F}

/* ---------- business challenge ---------- */
.hh-final{position:relative;isolation:isolate;overflow:hidden;padding:clamp(56px,7vw,96px) 0;color:#fff;background:radial-gradient(60% 80% at 15% 20%,#13309C,transparent 70%),linear-gradient(160deg,#050C3F,#07104F 50%,#0A1766)}
.hh-final__bg{position:absolute;inset:0;z-index:-1;pointer-events:none}
.hh-final__beam{position:absolute;left:-20%;top:30%;width:140%;height:2px;background:linear-gradient(90deg,transparent,#6EE0CE,transparent);opacity:.4;rotate:-8deg;animation:hhBeam 6s linear infinite}
.hh-final__beam--2{top:70%;rotate:6deg;background:linear-gradient(90deg,transparent,#F0D98F,transparent);animation-delay:-3s}
@keyframes hhBeam{from{translate:-30% 0}to{translate:30% 0}}
.hh-final__in{display:grid;grid-template-columns:minmax(0,.9fr) minmax(0,1.1fr);gap:clamp(24px,4vw,56px);align-items:center}
.hh-final h2{margin:8px 0 18px;font:800 clamp(2.2rem,4.4vw,3.6rem)/1.04 var(--display);letter-spacing:-.03em;color:#fff}
.hh-type{display:flex;flex-wrap:wrap;align-items:baseline;gap:10px;min-height:2.8em;padding:16px 18px;border-radius:16px;background:#ffffff0b;border:1px solid #ffffff22;font:800 clamp(1.05rem,1.8vw,1.35rem)/1.3 var(--display)}
.hh-type__label{color:#8E9AC6;font-size:.8em}
.hh-type b{color:#6EE0CE}
.hh-type i{width:3px;height:1.1em;background:#6EE0CE;align-self:center;animation:hhBlink 1s steps(1) infinite}
.hh-final__sub{margin:16px 0 0;color:#C9D3F5;font-size:1.05rem}
.hh-doors{list-style:none;margin:0;padding:0;display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px;perspective:1200px}
.hh-doors li{opacity:0;translate:0 24px;transition:opacity .6s,translate .6s;transition-delay:calc(var(--n)*.1s)}
.hh-final.is-in .hh-doors li{opacity:1;translate:0 0}
.hh-door--main{grid-column:1/-1}
.hh-door{position:relative;display:grid;grid-template-columns:auto 1fr auto;grid-template-areas:"ic need go" "ic t go";align-items:center;column-gap:14px;padding:16px 18px;border-radius:18px;border:1px solid #ffffff22;background:#ffffff09;color:#fff;text-decoration:none;overflow:hidden;transition:transform .4s cubic-bezier(.2,.7,.2,1),background .3s,border-color .3s,box-shadow .3s}
.hh-door:before{content:"";position:absolute;inset:0;background:linear-gradient(120deg,transparent 30%,#ffffff1a 50%,transparent 70%);translate:-120% 0;transition:translate .8s}
.hh-door__ic{grid-area:ic;display:grid;place-items:center;width:48px;height:48px;border-radius:15px;background:color-mix(in srgb,var(--c) 35%,transparent);border:1px solid color-mix(in srgb,var(--lt) 50%,transparent);color:#fff;transition:all .3s}
.hh-door__need{grid-area:need;font-size:.8rem;color:#8E9AC6}
.hh-door b{grid-area:t;font:800 1.02rem var(--display)}
.hh-door__go{grid-area:go;display:grid;place-items:center;width:36px;height:36px;border-radius:50%;border:1px solid #ffffff33;font-size:1.1rem;transition:all .3s}
.hh-doors li.is-on .hh-door,.hh-door:hover{transform:translateY(-4px) rotateX(4deg);background:linear-gradient(135deg,color-mix(in srgb,var(--c) 55%,#07104F),#0B1A6E);border-color:var(--lt);box-shadow:0 24px 50px -24px var(--lt)}
.hh-doors li.is-on .hh-door:before,.hh-door:hover:before{translate:120% 0}
.hh-doors li.is-on .hh-door__ic{background:var(--lt);color:#07104F}
.hh-doors li.is-on .hh-door__need{color:#E1E7FF}
.hh-doors li.is-on .hh-door__go{background:#fff;color:#07104F;border-color:#fff}
.hh-door--main .hh-door{background:#fff;color:#07104F;border-color:#fff}
.hh-door--main .hh-door__ic{background:#0B22A8;color:#fff;border:0}
.hh-door--main .hh-door__need{color:#525C78}
.hh-door--main .hh-door__go{background:#0B22A8;color:#fff;border:0;animation:hhNudge 1.6s ease-in-out infinite}
@keyframes hhNudge{50%{translate:5px 0}}
.hh-doors li.hh-door--main.is-on .hh-door{background:#fff;color:#07104F;box-shadow:0 24px 50px -24px #fff}

