main{overflow-x:clip}

/* intro: live 3D globe (replaces the cube) */
.hh-globe{position:relative;width:310px;height:310px;z-index:2}
.hh-globe__halo{position:absolute;inset:-40px;border-radius:50%;background:radial-gradient(circle,rgba(30,91,255,.45) 0%,rgba(30,91,255,.15) 45%,transparent 70%);animation:hhHalo 5s ease-in-out infinite;will-change:transform,opacity}
@keyframes hhHalo{50%{transform:scale(1.08);opacity:.75}}
.hh-globe__cv{position:absolute;inset:0;border-radius:50%;box-shadow:inset -18px -22px 50px rgba(4,10,51,.65),inset 10px 14px 40px rgba(110,160,255,.25),0 0 0 1px rgba(159,180,255,.25),0 30px 70px -20px rgba(0,0,0,.6)}
.hh-globe__cv .hg-canvas,.hh-globe__cv canvas{display:block;width:100%;height:100%;border-radius:50%}
.hh-globe__cv::after{content:"";position:absolute;inset:0;border-radius:50%;background:radial-gradient(circle at 32% 26%,rgba(255,255,255,.22),transparent 38%);pointer-events:none}
.hh-globe__lbl{position:absolute;left:50%;top:50%;translate:-50% -50%;display:flex;flex-direction:column;align-items:center;gap:6px;text-align:center;color:#fff;animation:hhLbl .6s cubic-bezier(.2,.8,.2,1)}
@keyframes hhLbl{from{opacity:0;transform:translateY(10px) scale(.95)}}
.hh-globe__ic{width:52px;height:52px;border-radius:16px;display:flex;align-items:center;justify-content:center;background:linear-gradient(135deg,var(--lt),var(--c));box-shadow:0 10px 26px -6px var(--c),inset 0 1px 0 rgba(255,255,255,.4)}
.hh-globe__lbl b{font:700 1.1rem/1.15 var(--display);max-width:10ch;text-shadow:0 2px 12px rgba(4,10,51,.8)}
.hh-globe__lbl em{font-style:normal;font:600 .74rem var(--body);padding:3px 10px;border-radius:999px;background:rgba(7,16,79,.65);border:1px solid color-mix(in srgb,var(--lt) 50%,transparent);color:var(--lt)}
.hh-globe__dots{position:absolute;left:50%;bottom:-34px;translate:-50% 0;display:flex;gap:7px}
.hh-globe__dots i{width:7px;height:7px;border-radius:999px;background:rgba(255,255,255,.25);transition:width .3s,background .3s}
.hh-globe__dots i.is-on{width:22px;background:var(--lt)}
.hh-globe__shadow{position:absolute;left:50%;bottom:-74px;width:240px;height:34px;translate:-50% 0;border-radius:50%;background:radial-gradient(closest-side,rgba(0,0,0,.55),transparent)}
@media (max-width:640px){.hh-globe{width:210px;height:210px}.hh-globe__ic{width:40px;height:40px}.hh-globe__lbl b{font-size:.9rem}}
@media (prefers-reduced-motion:reduce){.hh-globe__halo,.hh-globe__lbl{animation:none}}
@media (max-width:640px){.hh-globe__dots{display:none}}

/* Our Team (ot-) */
.ot-hero{isolation:isolate;background:linear-gradient(160deg,#050C3F,#07104F 50%,#0A1766);padding:clamp(48px,6vw,84px) 0 clamp(48px,6vw,80px)}
.ot-hero:after{display:none}
.ot-hero__bg{position:absolute;inset:0;z-index:-1;pointer-events:none}
.ot-hero__bg .abh-silk>svg{opacity:.5}
.ot-hero__bg .abh-silk__tag{display:none}
.ot-hero__grid{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:clamp(24px,4vw,56px);align-items:center}
.ot-hero h1{color:#fff;margin:14px 0 14px;font:800 clamp(2.2rem,4.4vw,3.6rem)/1.04 var(--display);letter-spacing:-.025em;max-width:14ch}
.ot-disc{list-style:none;margin:26px 0 0;padding:0;display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px;max-width:560px}
.ot-disc li{opacity:0;translate:0 14px;transition:opacity .5s,translate .5s;transition-delay:calc(var(--i)*.1s + .2s)}
.ot-hero.is-in .ot-disc li{opacity:1;translate:0 0}
.ot-disc a{display:flex;align-items:center;gap:12px;padding:12px 14px;border-radius:16px;background:#ffffff0a;border:1px solid #ffffff1f;color:#fff;text-decoration:none;transition:all .3s}
.ot-disc__ic{flex:none;display:grid;place-items:center;width:38px;height:38px;border-radius:12px;background:color-mix(in srgb,var(--c) 35%,transparent);border:1px solid color-mix(in srgb,var(--lt) 45%,transparent);color:#fff;transition:all .3s}
.ot-disc b{display:block;font:800 .95rem var(--display)}
.ot-disc small{display:block;font-size:.76rem;color:#C9D3F5}
.ot-disc li.is-on a,.ot-disc a:hover{background:#ffffff16;border-color:var(--lt);box-shadow:0 14px 30px -18px var(--lt)}
.ot-disc li.is-on .ot-disc__ic{background:var(--lt);color:#07104F}

.ot-stage{position:relative;aspect-ratio:1.05;max-width:520px;width:100%;justify-self:center;perspective:1200px}
.ot-stage__ring{position:absolute;inset:4%;border-radius:50%;border:1px dashed #ffffff26;will-change:transform}
.ot-stage__ring--2{inset:18%;border-style:solid;border-color:#6EE0CE22;animation-duration:40s;animation-direction:reverse}
@keyframes otSpin{to{rotate:360deg}}
.ot-fan{position:absolute;left:50%;top:50%;width:46%;aspect-ratio:.8;translate:-50% -50%;transform-style:preserve-3d}
.ot-fan__card{position:absolute;inset:0;margin:0;border-radius:22px;overflow:hidden;background:#0A1A7A;border:1px solid #ffffff33;box-shadow:0 30px 60px -24px #000c;transition:transform .7s cubic-bezier(.2,.7,.2,1)}
.ot-fan__card img{display:block;width:100%;height:100%;object-fit:cover;object-position:50% 30%;max-width:none}
.ot-fan__card figcaption{position:absolute;left:0;right:0;bottom:0;padding:26px 12px 10px;background:linear-gradient(180deg,transparent,#07104Fee);text-align:center}
.ot-fan__card b{display:block;font:800 .92rem var(--display);color:#fff}
.ot-fan__card span{display:block;font-size:.66rem;color:#6EE0CE;line-height:1.3}
.ot-fan__card--0{transform:translateZ(40px);z-index:3}
.ot-fan__card--1{transform:translateX(-62%) rotateY(28deg) scale(.86);z-index:2;filter:brightness(.8)}
.ot-fan__card--2{transform:translateX(62%) rotateY(-28deg) scale(.86);z-index:2;filter:brightness(.8)}
.ot-stage:hover .ot-fan__card--1{transform:translateX(-78%) rotateY(18deg) scale(.9);filter:none}
.ot-stage:hover .ot-fan__card--2{transform:translateX(78%) rotateY(-18deg) scale(.9);filter:none}
.ot-hero.is-in .ot-fan{animation:otFan 1s cubic-bezier(.2,.7,.2,1) both .2s}
@keyframes otFan{from{opacity:0;scale:.8}}
.ot-orb{position:absolute;display:inline-flex;align-items:center;gap:7px;padding:8px 12px;border-radius:999px;background:#07104Fd9;border:1px solid color-mix(in srgb,var(--lt) 45%,transparent);color:#fff;font:800 .8rem var(--display);white-space:nowrap;backdrop-filter:blur(6px);z-index:5;transition:all .35s;animation:otBob 5s ease-in-out infinite}
.ot-orb svg{color:var(--lt)}
.ot-orb.is-on{background:var(--c);border-color:var(--lt);box-shadow:0 0 0 6px color-mix(in srgb,var(--lt) 20%,transparent),0 14px 30px -12px var(--lt);scale:1.08}
.ot-orb.is-on svg{color:#fff}
.ot-orb--0{left:2%;top:10%}
.ot-orb--1{right:0;top:16%;animation-delay:-1.2s}
.ot-orb--2{left:0;bottom:16%;animation-delay:-2.4s}
.ot-orb--3{right:2%;bottom:10%;animation-delay:-3.6s}
@keyframes otBob{50%{translate:0 -8px}}
.ot-stage__total{position:absolute;left:50%;bottom:-2%;translate:-50% 0;display:flex;align-items:baseline;gap:8px;padding:8px 14px;border-radius:14px;background:#ffffff12;border:1px solid #ffffff26;font:700 .78rem var(--display);color:#C9D3F5;white-space:nowrap;z-index:6}
.ot-stage__total b{font:800 1.4rem var(--display);color:#F0D98F}

/* how teams work together */
.ot-ways{--n:#07104F;background:linear-gradient(180deg,#F6F7FB,#fff)}
.ot-flow{display:flex;align-items:center;justify-content:center;flex-wrap:nowrap;gap:0;margin:0 auto 30px;max-width:1120px}
.ot-flow__node{flex:none;display:flex;flex-direction:column;align-items:center;gap:6px;padding:16px 14px;min-width:126px;border-radius:18px;background:#fff;border:1px solid #DDE2EC;text-align:center;color:#0B22A8;box-shadow:0 14px 30px -24px #07104F;opacity:0;scale:.9;transition:opacity .5s,scale .5s}
.ot-flow__node b{font:800 .86rem/1.2 var(--display);color:#07104F}
.ot-flow__node small{font-size:.72rem;color:#0E9C88;font-weight:700}
.ot-flow__node--lead{background:#07104F;border-color:#07104F;color:#6EE0CE}
.ot-flow__node--lead b{color:#fff}
.ot-flow__node--out{background:linear-gradient(135deg,#0E9C88,#1E5BFF);border:0;color:#fff}
.ot-flow__node--out b{color:#fff}
.ot-ways.is-in .ot-flow>*{opacity:1;scale:1}
.ot-ways.is-in .ot-flow>*:nth-child(1){transition-delay:0s}.ot-ways.is-in .ot-flow>*:nth-child(3){transition-delay:.3s}.ot-ways.is-in .ot-flow>*:nth-child(5){transition-delay:.6s}.ot-ways.is-in .ot-flow>*:nth-child(7){transition-delay:.9s}.ot-ways.is-in .ot-flow>*:nth-child(9){transition-delay:1.2s}
.ot-flow__link{position:relative;flex:1;min-width:24px;max-width:70px;height:2px;background:#C9D1EA}
.ot-flow__link b{position:absolute;top:-3px;left:0;width:8px;height:8px;border-radius:50%;background:#0E9C88;box-shadow:0 0 8px #0E9C88;animation:otRun 1.8s linear infinite}
@keyframes otRun{from{left:0}to{left:calc(100% - 8px)}}
.ot-flow__teams{flex:none;display:grid;grid-template-columns:1fr 1fr;gap:6px;padding:12px;border-radius:20px;background:#fff;border:1.5px dashed #B8C3E6;position:relative;opacity:0;scale:.9;transition:opacity .5s .6s,scale .5s .6s}
.ot-flow__teams span{display:inline-flex;align-items:center;gap:6px;padding:7px 10px;border-radius:10px;background:color-mix(in srgb,var(--c) 9%,#fff);color:var(--c);font:800 .74rem var(--display);white-space:nowrap;animation:otPulse 4s infinite;animation-delay:calc(var(--i)*1s)}
@keyframes otPulse{0%,100%{box-shadow:none}10%,20%{box-shadow:0 0 0 2px var(--c)}}
.ot-flow__teams em{grid-column:1/-1;text-align:center;font-style:normal;font:800 .68rem var(--display);letter-spacing:.1em;text-transform:uppercase;color:#525C78}
.ot-cards{list-style:none;margin:0;padding:0;display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:12px}
.ot-cards li{position:relative;padding:20px 18px 22px;border-radius:20px;background:#fff;border:1px solid #DDE2EC;overflow:hidden;cursor:default;transition:translate .35s,box-shadow .35s,border-color .35s,background .35s;opacity:0;translate:0 18px}
.ot-ways.is-in .ot-cards li{opacity:1;translate:0 0;transition:opacity .5s calc(var(--i)*.1s + .4s),translate .5s calc(var(--i)*.1s + .4s),box-shadow .35s,border-color .35s,background .35s}
.ot-cards__ic{display:grid;place-items:center;width:46px;height:46px;border-radius:14px;background:#EEF2FF;color:#0B22A8;transition:all .35s}
.ot-cards__n{position:absolute;right:16px;top:14px;font:800 1.8rem/1 var(--display);color:#E6EAF5}
.ot-cards h3{margin:14px 0 6px;font:800 1.02rem var(--display);color:#07104F}
.ot-cards p{margin:0;font-size:.86rem;color:#525C78}
.ot-cards__bar{position:absolute;left:0;bottom:0;height:4px;width:100%;background:linear-gradient(90deg,#1E5BFF,#0E9C88);transform-origin:left;scale:0 1;transition:scale .5s}
.ot-cards li.is-on{border-color:#0B22A855;box-shadow:0 24px 44px -28px #0B22A8;translate:0 -6px}
.ot-cards li.is-on .ot-cards__ic{background:#0B22A8;color:#fff;rotate:-8deg}
.ot-cards li.is-on .ot-cards__bar{scale:1 1}

/* room to grow */
.ot-grow{background:#fff}
.ot-grow__in{display:grid;grid-template-columns:260px minmax(0,1fr);gap:clamp(24px,4vw,56px);align-items:center;padding:clamp(24px,3vw,36px);border-radius:28px;background:radial-gradient(60% 90% at 0 50%,#E6EDFF,transparent 70%),#F6F7FB;border:1px solid #DDE2EC}
.ot-grow h2{margin:8px 0 8px;font:800 clamp(1.6rem,2.8vw,2.2rem) var(--display);color:#07104F}
.ot-grow p{margin:0 0 18px;color:#525C78;font-size:1.05rem}
.ot-grow__art{position:relative;height:180px;display:flex;align-items:flex-end;gap:12px;padding:0 10px}
.ot-grow__art i{flex:1;height:calc(26% + var(--i)*17%);border-radius:10px 10px 4px 4px;background:linear-gradient(180deg,#5B8CFF,#0B22A8);transform-origin:bottom;scale:1 0;transition:scale .8s cubic-bezier(.2,.7,.2,1);transition-delay:calc(var(--i)*.12s)}
.ot-grow__art i:nth-child(odd){background:linear-gradient(180deg,#6EE0CE,#0E9C88)}
.ot-grow.is-in .ot-grow__art i{scale:1 1}
.ot-grow__art span{position:absolute;right:0;top:0;display:grid;place-items:center;width:52px;height:52px;border-radius:16px;background:#F0D98F;color:#07104F;box-shadow:0 14px 26px -14px #C99A2E;animation:otBob 4s ease-in-out infinite}

@media (max-width:1100px){
  .ot-flow{flex-wrap:wrap;gap:10px}
  .ot-flow__link{display:none}
  .ot-cards{grid-template-columns:repeat(3,minmax(0,1fr))}
}
@media (max-width:900px){
  .ot-hero__grid{grid-template-columns:1fr}
  .ot-stage{max-width:400px}
  .ot-grow__in{grid-template-columns:1fr}
  .ot-grow__art{height:120px}
}
@media (max-width:640px){
  .ot-disc{grid-template-columns:1fr}
  .ot-cards{grid-template-columns:1fr}
  .ot-orb{display:none}
  .ot-stage{aspect-ratio:1.25}
  .ot-fan{width:44%}
  .ot-flow__node{min-width:0;flex:1 1 40%}
  .ot-flow__teams{flex:1 1 100%}
}
@media (prefers-reduced-motion:reduce){
  .ot *{animation:none!important;transition:none!important}
  .ot-disc li,.ot-flow>*,.ot-cards li{opacity:1!important;translate:none!important;scale:1!important}
  .ot-grow__art i{scale:1 1}
}

/* ===== Meet our Team (tm-) ===== */
.tm-kick{display:inline-flex;align-items:center;gap:8px;font-size:.8rem;font-weight:700;letter-spacing:.12em;text-transform:uppercase;color:#6EE0CE;margin:14px 0 4px}
.tm-kick__dot{width:8px;height:8px;border-radius:50%;background:#6EE0CE;box-shadow:0 0 0 0 rgba(110,224,206,.6);animation:tmPing 2.2s ease-out infinite}
@keyframes tmPing{70%{box-shadow:0 0 0 10px rgba(110,224,206,0)}100%{box-shadow:0 0 0 0 rgba(110,224,206,0)}}

/* hero */
.tm-hero{position:relative;overflow:hidden;padding-bottom:clamp(40px,6vw,80px)}
.tm-hero__bg{position:absolute;inset:0;pointer-events:none}
.tm-hero__grid{position:relative;display:grid;grid-template-columns:1fr 1.05fr;gap:30px;align-items:center}
.tm-hero h1{font-size:clamp(2.6rem,5.6vw,4.3rem);line-height:1.02;letter-spacing:-.03em;margin:.15em 0 .3em}
.tm-stats{list-style:none;margin:24px 0 26px;padding:0;display:grid;grid-template-columns:repeat(4,auto);gap:10px;justify-content:start}
.tm-stats li{display:grid;grid-template-columns:auto 1fr;grid-template-rows:auto auto;column-gap:9px;align-items:center;padding:10px 14px 10px 10px;border-radius:16px;background:rgba(255,255,255,.07);border:1px solid rgba(255,255,255,.15);opacity:0;transform:translateY(12px);transition:opacity .5s,transform .5s;transition-delay:calc(var(--i)*90ms + 200ms)}
.tm-hero.is-in .tm-stats li{opacity:1;transform:none}
.tm-stats__ic,.tm-stats li>img{grid-row:1/3}
.tm-stats__ic{width:36px;height:36px;border-radius:11px;display:flex;align-items:center;justify-content:center;background:linear-gradient(135deg,#1E5BFF,#0E9C88);color:#fff}
.tm-stats li>img{width:34px;height:25px;border-radius:4px;box-shadow:0 0 0 2px rgba(255,255,255,.8);object-fit:cover;max-width:none}
.tm-stats b{font-size:1.35rem;font-weight:800;color:#F0D98F;line-height:1}
.tm-stats__hq b{font-size:1rem;color:#fff}
.tm-stats small{font-size:.74rem;color:#BFD0FF}
.tm-hero__cta{display:flex;flex-wrap:wrap;gap:12px}
.tm-ghost{color:#fff!important;border-color:rgba(255,255,255,.4)!important;display:inline-flex;align-items:center;gap:8px}

.tm-stage{position:relative;height:470px;perspective:1300px;--R:330px;--cw:104px;--ch:136px}
.tm-stage__glow{position:absolute;left:50%;top:44%;width:420px;height:420px;margin:-210px 0 0 -210px;border-radius:50%;background:radial-gradient(circle,rgba(30,91,255,.45),rgba(30,91,255,0) 65%)}
.tm-ring{position:absolute;left:50%;top:44%;width:0;height:0;transform-style:preserve-3d;transform:rotateX(-9deg) rotateY(0);animation:tmSpin 56s linear infinite;will-change:transform}
.tm-ring.is-hold{animation-play-state:paused}
@keyframes tmSpin{to{transform:rotateX(-9deg) rotateY(-360deg)}}
.tm-ring__card{position:absolute;left:calc(var(--cw)/-2);top:calc(var(--ch)/-2);width:var(--cw);height:var(--ch);margin:0;border-radius:16px;overflow:hidden;
  transform:rotateY(calc(var(--i) * 360deg / var(--n))) translateZ(var(--R));
  background:linear-gradient(170deg,var(--lt) -40%,var(--c) 45%,#07104F 110%);box-shadow:0 0 0 1px rgba(255,255,255,.25) inset,0 14px 26px rgba(0,0,0,.35)}
.tm-ring__card img{display:block;width:100%;height:calc(var(--ch) - 34px);object-fit:cover;object-position:50% 20%;max-width:none}
.tm-ring__card figcaption{position:absolute;left:0;right:0;bottom:0;padding:5px 6px 6px;background:rgba(4,10,51,.82);text-align:center;line-height:1.1}
.tm-ring__card b{display:block;color:#fff;font-size:.78rem}
.tm-ring__card span{display:block;color:var(--lt);font-size:.58rem;font-weight:600;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.tm-stage__core{position:absolute;left:50%;top:44%;transform:translate(-50%,-50%);background:#fff;border-radius:14px;padding:8px 12px;box-shadow:0 18px 40px rgba(0,0,0,.4),0 0 0 6px rgba(255,255,255,.08);animation:tmBob 5s ease-in-out infinite}
.tm-stage__core img{display:block;width:150px;height:auto}
@keyframes tmBob{50%{transform:translate(-50%,calc(-50% - 8px))}}
.tm-stage__floor{position:absolute;left:50%;bottom:8px;width:72%;height:46px;transform:translateX(-50%);border-radius:50%;background:radial-gradient(closest-side,rgba(110,224,206,.28),rgba(110,224,206,0))}

/* org */
.tm-org{background:linear-gradient(180deg,#fff,#F4F7FF)}
.tm-org__grid{display:grid;grid-template-columns:1.7fr 1fr;gap:28px;align-items:center;margin-top:10px}
.tm-tree{display:flex;flex-direction:column;align-items:center}
.tm-node{font:inherit;cursor:pointer;border:1.5px solid #E3E8F7;background:#fff;border-radius:18px;color:#07104F;transition:transform .25s,box-shadow .25s,border-color .25s}
.tm-node:hover,.tm-node.is-on,.tm-node:focus-visible{transform:translateY(-4px);border-color:var(--c);box-shadow:0 16px 30px rgba(11,34,168,.14)}
.tm-node__ic{width:38px;height:38px;border-radius:12px;display:flex;align-items:center;justify-content:center;color:#fff;background:linear-gradient(135deg,var(--c),var(--lt));box-shadow:0 4px 0 rgba(7,16,79,.18);flex:none}
.tm-node--lead{display:flex;align-items:center;gap:14px;padding:14px 18px;background:linear-gradient(135deg,#07104F,#0B22A8);color:#fff;border-color:transparent;box-shadow:0 18px 36px rgba(7,16,79,.28)}
.tm-node--lead .tm-node__t{display:flex;flex-direction:column;text-align:left}
.tm-node--lead b{font-size:1.1rem}
.tm-node--lead small{color:#F0D98F;font-weight:600}
.tm-faces{display:flex}
.tm-faces img{width:40px;height:40px;border-radius:50%;object-fit:cover;object-position:50% 18%;background:linear-gradient(135deg,#1E5BFF,#07104F);box-shadow:0 0 0 2px #fff;margin-left:-10px;max-width:none}
.tm-faces img:first-child{margin-left:0}
.tm-faces--s img{width:30px;height:30px;margin-left:-8px;background:linear-gradient(135deg,var(--lt),var(--c))}
.tm-tree__wires{width:100%;height:80px;display:block;overflow:visible}
.tm-tree__wires path{fill:none;stroke:var(--c);stroke-width:2;stroke-dasharray:5 6;opacity:.55;animation:tmFlow 1.4s linear infinite;vector-effect:non-scaling-stroke}
.tm-tree__wires path.is-on{opacity:1;stroke-width:3.5;stroke-dasharray:none}
@keyframes tmFlow{to{stroke-dashoffset:-22}}
.tm-tree__teams{display:grid;grid-template-columns:repeat(6,1fr);gap:8px;width:100%}
.tm-tree__teams .tm-node{display:flex;flex-direction:column;align-items:center;gap:7px;padding:12px 6px;text-align:center;opacity:0;transform:translateY(16px);transition:opacity .5s,transform .5s,box-shadow .25s,border-color .25s;transition-delay:calc(var(--i)*80ms)}
.tm-org.is-in .tm-tree__teams .tm-node{opacity:1;transform:none}
.tm-org.is-in .tm-tree__teams .tm-node:hover,.tm-org.is-in .tm-tree__teams .tm-node.is-on{transform:translateY(-4px)}
.tm-tree__teams b{font-size:.82rem;line-height:1.15}
.tm-tree__teams small{font-size:.72rem;color:#5A6386;font-weight:600}
.tm-mix{display:flex;flex-direction:column;align-items:center;gap:14px;padding:20px;border-radius:22px;background:#fff;border:1px solid #E3E8F7;box-shadow:0 20px 44px rgba(11,34,168,.08)}
.tm-donut{position:relative;width:200px;height:200px}
.tm-donut svg{width:100%;height:100%;transform:rotate(-90deg)}
.tm-donut__bg{fill:none;stroke:#EEF2FC;stroke-width:22}
.tm-donut__arc{fill:none;stroke-width:22;transition:stroke-dasharray 1s cubic-bezier(.2,.8,.2,1),stroke-width .2s;cursor:pointer}
.tm-donut__arc.is-on{stroke-width:30}
.tm-donut__c{position:absolute;inset:0;display:flex;flex-direction:column;align-items:center;justify-content:center;text-align:center;padding:40px}
.tm-donut__c b{font-size:2.2rem;font-weight:800;color:#07104F;line-height:1}
.tm-donut__c span{font-size:.75rem;color:#5A6386;font-weight:600}
.tm-legend{list-style:none;margin:0;padding:0;width:100%;display:flex;flex-direction:column;gap:4px}
.tm-legend button{width:100%;display:grid;grid-template-columns:10px 1fr auto;grid-template-rows:auto 4px;column-gap:8px;row-gap:3px;align-items:center;padding:5px 8px;border:0;border-radius:9px;background:none;font:inherit;font-size:.84rem;color:#26305C;cursor:pointer;text-align:left}
.tm-legend li.is-on button,.tm-legend button:hover{background:#F2F5FF}
.tm-legend i{width:10px;height:10px;border-radius:3px}
.tm-legend b{color:#07104F}
.tm-legend em{grid-column:2/4;height:4px;border-radius:3px;background:#EEF2FC;overflow:hidden}
.tm-legend s{display:block;height:100%;border-radius:3px}

/* people grid */
.tm-people{scroll-margin-top:80px}
.tm-filter{display:flex;flex-wrap:wrap;gap:12px;align-items:center;justify-content:space-between;margin:6px 0 26px}
.tm-tabs{display:flex;flex-wrap:wrap;gap:8px}
.tm-tab{display:inline-flex;align-items:center;gap:7px;padding:9px 14px;border-radius:999px;border:1.5px solid #DCE3F7;background:#fff;font:inherit;font-weight:700;font-size:.86rem;color:#07104F;cursor:pointer;transition:all .2s}
.tm-tab em{font-style:normal;font-size:.72rem;padding:1px 7px;border-radius:999px;background:#EEF2FC;color:#0B22A8}
.tm-tab:hover{border-color:var(--c)}
.tm-tab.is-on{background:linear-gradient(135deg,var(--c),var(--lt));border-color:transparent;color:#fff;box-shadow:0 10px 22px rgba(11,34,168,.2)}
.tm-tab.is-on em{background:rgba(255,255,255,.25);color:#fff}
.tm-search{display:flex;align-items:center;gap:8px;padding:0 14px;border-radius:999px;border:1.5px solid #DCE3F7;background:#fff;color:#5A6386;min-width:240px}
.tm-search:focus-within{border-color:#1E5BFF;box-shadow:0 0 0 4px rgba(30,91,255,.12)}
.tm-search input{border:0;outline:0;font:inherit;padding:10px 0;flex:1;background:none;color:#07104F;min-width:0}
.tm-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(230px,1fr));gap:22px 18px}
.tm-card{perspective:900px;--rx:0deg;--ry:0deg;--gx:50%;animation:tmIn .5s cubic-bezier(.2,.8,.2,1) both;animation-delay:calc(var(--i)*45ms)}
@keyframes tmIn{from{opacity:0;transform:translateY(18px) scale(.97)}}
.tm-card__in{height:100%;display:flex;flex-direction:column;border-radius:22px;background:#fff;border:1px solid #E3E8F7;transform:rotateX(var(--rx)) rotateY(var(--ry));transform-style:preserve-3d;transition:transform .25s ease-out,box-shadow .3s;box-shadow:0 10px 26px rgba(11,34,168,.08)}
.tm-card:hover .tm-card__in{box-shadow:0 26px 50px rgba(11,34,168,.18)}
.tm-card__stage{position:relative;height:230px;border-radius:22px 22px 0 0;overflow:hidden;transform-style:preserve-3d;
  background:radial-gradient(120% 90% at var(--gx) 0%,var(--lt) 0%,var(--c) 48%,#07104F 100%)}
.tm-card__rings{position:absolute;left:50%;top:44%;width:260px;height:260px;margin:-130px 0 0 -130px;border-radius:50%;background:repeating-radial-gradient(circle,rgba(255,255,255,.14) 0 1px,rgba(255,255,255,0) 1px 26px);transition:transform .6s}
.tm-card:hover .tm-card__rings{transform:scale(1.12) rotate(20deg)}
.tm-card__img{position:absolute;left:50%;bottom:0;width:232px;height:232px;max-width:none;transform:translateX(-50%) translateZ(30px);transition:transform .45s cubic-bezier(.2,.8,.2,1);object-fit:cover;filter:drop-shadow(0 10px 18px rgba(4,10,51,.35))}
.tm-card:hover .tm-card__img{transform:translateX(-50%) translateZ(30px) scale(1.06)}
.tm-card__team{position:absolute;left:12px;top:12px;display:inline-flex;align-items:center;gap:5px;padding:4px 9px;border-radius:999px;background:rgba(255,255,255,.92);color:var(--c);font-size:.7rem;font-weight:800;z-index:2;box-shadow:0 4px 10px rgba(0,0,0,.15)}
.tm-card__play{position:absolute;right:12px;bottom:12px;z-index:2;width:46px;height:46px;border-radius:50%;border:0;cursor:pointer;display:flex;align-items:center;justify-content:center;color:#fff;background:#FF2D2D;box-shadow:0 0 0 0 rgba(255,45,45,.6),0 8px 18px rgba(0,0,0,.35);animation:tmPulse 2.4s ease-out infinite;transition:transform .2s}
.tm-card__play:hover{transform:scale(1.1)}
.tm-card__play svg{margin-left:2px}
@keyframes tmPulse{70%{box-shadow:0 0 0 14px rgba(255,45,45,0),0 8px 18px rgba(0,0,0,.35)}100%{box-shadow:0 0 0 0 rgba(255,45,45,0),0 8px 18px rgba(0,0,0,.35)}}
.tm-card__body{display:flex;flex-direction:column;gap:5px;padding:15px 16px 16px;flex:1}
.tm-card__body h3{font-size:1.12rem;color:#07104F;letter-spacing:-.01em}
.tm-card__role{font-size:.85rem;font-weight:600;color:var(--c);line-height:1.3;min-height:2.2em}
.tm-card__mail{display:flex;align-items:center;gap:6px;font-size:.78rem;color:#5A6386;text-decoration:none;min-width:0}
.tm-card__mail span{white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.tm-card__mail:hover{color:#0B22A8}
.tm-card__links{display:flex;align-items:center;gap:8px;margin-top:auto;padding-top:8px}
.tm-ic{width:36px;height:36px;border-radius:11px;display:flex;align-items:center;justify-content:center;border:1px solid #DCE3F7;color:#0B22A8;background:#F6F8FF;transition:all .2s;flex:none}
.tm-ic--li:hover{background:#0A66C2;border-color:#0A66C2;color:#fff;transform:translateY(-2px)}
.tm-ic--mail:hover{background:#0E9C88;border-color:#0E9C88;color:#fff;transform:translateY(-2px)}
.tm-vbtn{display:inline-flex;align-items:center;gap:6px;height:36px;padding:0 12px;border-radius:11px;border:0;cursor:pointer;font:inherit;font-weight:700;font-size:.8rem;color:#fff;background:linear-gradient(135deg,#E62117,#FF4E45);text-decoration:none;transition:transform .2s,box-shadow .2s;white-space:nowrap}
.tm-vbtn:hover{transform:translateY(-2px);box-shadow:0 8px 16px rgba(230,33,23,.3)}
.tm-vbtn--li{background:linear-gradient(135deg,#0A66C2,#2E8AE6)}
.tm-vbtn--li:hover{box-shadow:0 8px 16px rgba(10,102,194,.3)}
.tm-card--lead .tm-card__in{border-color:#F0D98F}
.tm-card--lead .tm-card__team{color:#8E6C1E}
.tm-empty{text-align:center;color:#5A6386;padding:30px}

/* videos */
.tm-vids{position:relative;overflow:hidden;color:#fff;background:radial-gradient(110% 90% at 80% 10%,#1336C9 0%,#07104F 55%,#040A33 100%);scroll-margin-top:80px}
.tm-vids__bg{position:absolute;inset:0;background:repeating-linear-gradient(160deg,rgba(110,224,206,0) 0 22px,rgba(110,224,206,.06) 22px 23px);pointer-events:none}
.tm-vids .container{position:relative}
.tm-vids__grid{display:grid;grid-template-columns:1.15fr 1fr;gap:24px;align-items:start;margin-top:10px}
.tm-feat{position:sticky;top:96px;animation:tmIn .45s cubic-bezier(.2,.8,.2,1)}
.tm-feat__screen{position:relative;aspect-ratio:16/10;border-radius:22px;overflow:hidden;background:radial-gradient(90% 90% at 50% 0%,var(--lt) 0%,var(--c) 45%,#040A33 100%);box-shadow:0 30px 60px rgba(0,0,0,.45),0 0 0 1px rgba(255,255,255,.15) inset}
.tm-feat__screen>img{position:absolute;left:50%;bottom:0;height:96%;width:auto;transform:translateX(-50%);max-width:none;filter:drop-shadow(0 16px 30px rgba(0,0,0,.4))}
.tm-feat__eq{position:absolute;left:18px;top:18px;display:flex;align-items:flex-end;gap:3px;height:22px}
.tm-feat__eq i{width:4px;border-radius:2px;background:#6EE0CE;animation:tmEq .9s ease-in-out infinite alternate;animation-delay:calc(var(--j)*-.18s);height:30%}
@keyframes tmEq{to{height:100%}}
.tm-feat__play{position:absolute;left:50%;top:50%;transform:translate(-50%,-50%);height:52px;padding:0 22px;border-radius:999px;font-size:.95rem;z-index:2;box-shadow:0 12px 30px rgba(0,0,0,.4)}
.tm-feat__play:hover{transform:translate(-50%,calc(-50% - 2px))}
.tm-feat__src{position:absolute;right:14px;top:14px;display:inline-flex;align-items:center;gap:6px;padding:4px 10px;border-radius:999px;background:rgba(0,0,0,.45);font-size:.74rem;font-weight:700}
.tm-feat__cap{display:flex;flex-wrap:wrap;align-items:baseline;gap:4px 12px;margin-top:14px}
.tm-feat__cap b{font-size:1.3rem}
.tm-feat__cap span{color:#BFD0FF;font-size:.92rem}
.tm-feat__cap em{display:inline-flex;align-items:center;gap:5px;font-style:normal;font-size:.75rem;font-weight:700;color:var(--lt);padding:3px 9px;border-radius:999px;border:1px solid rgba(255,255,255,.2)}
.tm-vlist{list-style:none;margin:0;padding:0;display:grid;grid-template-columns:1fr 1fr;gap:8px}
.tm-vlist button{width:100%;display:flex;align-items:center;gap:10px;padding:8px 10px;border-radius:14px;border:1px solid rgba(255,255,255,.14);background:rgba(255,255,255,.05);color:#fff;font:inherit;text-align:left;cursor:pointer;transition:all .2s}
.tm-vlist img{width:44px;height:44px;border-radius:12px;object-fit:cover;object-position:50% 18%;background:linear-gradient(135deg,var(--lt),var(--c));flex:none;max-width:none}
.tm-vlist span{flex:1;min-width:0;display:flex;flex-direction:column}
.tm-vlist b{font-size:.86rem;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.tm-vlist small{font-size:.72rem;color:#BFD0FF;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.tm-vlist__src{width:26px;height:26px;border-radius:50%;display:flex;align-items:center;justify-content:center;background:#E62117;flex:none;font-style:normal}
.tm-vlist__src.is-li{background:#0A66C2}
.tm-vlist li.is-on button,.tm-vlist button:hover{background:rgba(255,255,255,.14);border-color:var(--lt);transform:translateX(3px)}

/* world */
.tm-world{position:relative;overflow:hidden;background:linear-gradient(180deg,#F4F7FF,#fff);padding-bottom:0}
.tm-world__grid{display:grid;grid-template-columns:.9fr 1.3fr;gap:30px;align-items:center}
.tm-world__regs{list-style:none;margin:18px 0;padding:0;display:flex;flex-direction:column;gap:8px}
.tm-world__regs li{display:flex;align-items:center;gap:12px;padding:10px 14px;border-radius:14px;background:#fff;border:1px solid #E3E8F7;border-left:4px solid var(--c);opacity:0;transform:translateX(-14px);transition:opacity .5s,transform .5s;transition-delay:calc(var(--i)*90ms)}
.tm-world.is-in .tm-world__regs li{opacity:1;transform:none}
.tm-world__fl{display:flex}
.tm-world__fl img{width:22px;height:16px;border-radius:2px;box-shadow:0 0 0 1.5px #fff;margin-right:-5px;max-width:none}
.tm-world__regs b{flex:1;font-size:.92rem;color:#07104F;margin-left:6px}
.tm-world__regs em{font-style:normal;font-weight:800;color:#0B22A8;background:#EEF2FF;padding:2px 9px;border-radius:999px;font-size:.8rem}
.tm-world__hq{display:flex;align-items:center;gap:12px;padding:12px 14px;border-radius:16px;background:linear-gradient(120deg,#07104F,#0B22A8);color:#fff}
.tm-world__hq img{width:34px;height:25px;border-radius:4px;box-shadow:0 0 0 2px #fff;max-width:none}
.tm-world__hq b{display:block;font-size:.95rem}
.tm-world__hq span{font-size:.82rem;color:#C9D6FF}
.tm-world__map{position:relative;border-radius:24px;background:radial-gradient(120% 100% at 70% 40%,#13248F,#07104F 70%);padding:12px;box-shadow:0 30px 60px rgba(7,16,79,.25)}
.tm-world__map svg{display:block;width:100%;height:auto}
.tm-world__land path{fill:#1B2A8C;stroke:#07104F;stroke-width:.5}
.tm-world__land path.is-r{fill:#2B47C9}
.tm-arc{fill:none;stroke-width:1.2;opacity:.75;stroke-dasharray:600;stroke-dashoffset:600}
.tm-world.is-in .tm-arc{animation:tmDraw 2.2s cubic-bezier(.2,.8,.2,1) forwards,tmFlowA 3s linear 2.4s infinite;animation-delay:calc(var(--i)*70ms),calc(var(--i)*70ms + 2.4s)}
@keyframes tmDraw{to{stroke-dashoffset:0}}
@keyframes tmFlowA{from{stroke-dasharray:6 8;stroke-dashoffset:0}to{stroke-dasharray:6 8;stroke-dashoffset:-56}}
.tm-dot{opacity:.95}
.tm-hub__c{fill:#F0D98F;stroke:#fff;stroke-width:2}
.tm-hub__p{fill:none;stroke:#F0D98F;stroke-width:1.5;opacity:.7;transform-box:fill-box;transform-origin:center;animation:tmHub 2.4s ease-out infinite}
.tm-hub__p--2{animation-delay:-1.2s}
@keyframes tmHub{from{transform:scale(.4);opacity:.9}to{transform:scale(1.6);opacity:0}}
.tm-world__faces{position:absolute;left:18px;bottom:16px;display:flex;align-items:center;padding:5px 10px 5px 5px;border-radius:999px;background:rgba(255,255,255,.95);box-shadow:0 10px 24px rgba(0,0,0,.3)}
.tm-world__faces img{width:34px;height:34px;border-radius:50%;object-fit:cover;object-position:50% 18%;background:linear-gradient(135deg,#1E5BFF,#07104F);box-shadow:0 0 0 2px #fff;margin-left:-9px;max-width:none}
.tm-world__faces img:first-child{margin-left:0}
.tm-world__faces span{margin-left:8px;font-weight:800;color:#0B22A8;font-size:.85rem}
.tm-ticker{margin-top:40px;padding:14px 0;background:#07104F;overflow:hidden}
.tm-ticker__track{display:flex;width:max-content;animation:tmTick 70s linear infinite}
.tm-ticker__track>span{display:flex;gap:22px;padding-right:22px}
.tm-ticker i{display:inline-flex;align-items:center;gap:7px;font-style:normal;color:#DCE5FF;font-size:.86rem;font-weight:600;white-space:nowrap}
.tm-ticker img{width:24px;height:18px;border-radius:3px;max-width:none}
@keyframes tmTick{to{transform:translateX(-50%)}}

/* modal */
.tm-modal{position:fixed;inset:0;z-index:1000;background:rgba(4,10,51,.8);display:flex;align-items:center;justify-content:center;padding:20px;animation:tmFade .2s}
@keyframes tmFade{from{opacity:0}}
.tm-modal__box{width:min(900px,100%);border-radius:22px;overflow:hidden;background:#07104F;box-shadow:0 40px 90px rgba(0,0,0,.5);animation:tmIn .35s cubic-bezier(.2,.8,.2,1)}
.tm-modal header{display:flex;align-items:center;gap:12px;padding:12px 14px;color:#fff;background:linear-gradient(120deg,var(--c),#07104F)}
.tm-modal header img{width:48px;height:48px;border-radius:14px;object-fit:cover;object-position:50% 18%;background:linear-gradient(135deg,var(--lt),var(--c));max-width:none}
.tm-modal header div{flex:1;display:flex;flex-direction:column}
.tm-modal header span{font-size:.82rem;color:#C9D6FF}
.tm-modal header button{width:40px;height:40px;border-radius:12px;border:1px solid rgba(255,255,255,.3);background:rgba(255,255,255,.1);color:#fff;font-size:1.5rem;cursor:pointer}
.tm-modal__vid{aspect-ratio:16/9;background:#000}
.tm-modal__vid iframe{width:100%;height:100%;border:0;display:block}
.tm-modal footer{padding:10px 14px;text-align:right}
.tm-modal footer a{display:inline-flex;align-items:center;gap:6px;color:#DCE5FF;font-size:.85rem;font-weight:600;text-decoration:none}
.tm-modal footer a:hover{color:#fff;text-decoration:underline}

@media (max-width:1100px){
  .tm-hero__grid{grid-template-columns:1fr}
  .tm-stage{height:400px;--R:280px;--cw:92px;--ch:120px}
  .tm-org__grid{grid-template-columns:1fr}
  .tm-tree__teams{grid-template-columns:repeat(3,1fr)}
  .tm-tree__wires{display:none}
  .tm-node--lead{margin-bottom:14px}
  .tm-vids__grid{grid-template-columns:1fr}
  .tm-feat{position:relative;top:0}
  .tm-world__grid{grid-template-columns:1fr}
}
@media (max-width:640px){
  .tm-stats{grid-template-columns:1fr 1fr}
  .tm-stage{height:300px;--R:175px;--cw:68px;--ch:90px}
  .tm-stage__glow{width:300px;height:300px;margin:-150px 0 0 -150px}
  .tm-ring__card figcaption{padding:3px}
  .tm-ring__card b{font-size:.62rem}.tm-ring__card span{display:none}
  .tm-ring__card img{height:calc(var(--ch) - 20px)}
  .tm-stage__core img{width:104px}
  .tm-tree__teams{grid-template-columns:1fr 1fr}
  .tm-node--lead{flex-wrap:wrap;justify-content:center}
  .tm-filter{flex-direction:column;align-items:stretch}
  .tm-tabs{flex-wrap:nowrap;overflow-x:auto;padding-bottom:6px;scroll-snap-type:x mandatory}
  .tm-tab{flex:none;scroll-snap-align:start}
  .tm-search{min-width:0}
  .tm-grid{grid-template-columns:1fr 1fr;gap:14px 10px}
  .tm-card__stage{height:170px}
  .tm-card__img{width:172px;height:172px}
  .tm-card__body{padding:11px 10px 12px}
  .tm-card__body h3{font-size:.98rem}
  .tm-card__role{font-size:.76rem}
  .tm-card__mail{display:none}
  .tm-card__links{flex-wrap:wrap;gap:6px}
  .tm-ic{width:32px;height:32px}
  .tm-vbtn{height:32px;padding:0 9px;font-size:.72rem}
