/* Forms (fm-) */
.fm{--c:#1E5BFF;--lt:#6EE0CE;--n:#07104F;--mu:#525C78;--ln:#D7DDEB;--bad:#D6334A;--ok:#0E9C88;position:relative;color:#14193D;text-align:left}
