.fm-top:before{content:"";position:absolute;right:-40px;top:-60px;width:180px;height:180px;border-radius:50%;background:radial-gradient(circle,color-mix(in srgb,var(--lt) 45%,transparent),transparent 70%)}
.fm-top__ic{position:relative;display:grid;place-items:center;width:46px;height:46px;border-radius:14px;background:linear-gradient(145deg,var(--lt),var(--c));box-shadow:0 10px 22px -10px var(--lt),inset 0 1px 0 #ffffff55;color:#fff;flex:none;animation:fmFloat 4s ease-in-out infinite}
