/* steps */
.fm-steps{list-style:none;margin:0 0 16px;padding:0;display:grid;grid-template-columns:repeat(3,1fr);gap:6px;counter-reset:s}
.fm-steps li{position:relative}
.fm-steps li+li:before{content:"";position:absolute;left:-6px;right:calc(100% - 4px);top:15px;height:2px;background:var(--ln)}
.fm-steps button{display:flex;align-items:center;gap:8px;width:100%;padding:6px 8px;border:0;border-radius:10px;background:none;font:700 .8rem var(--display);color:var(--mu);cursor:pointer;text-align:left}
.fm-steps button span{display:grid;place-items:center;flex:none;width:24px;height:24px;border-radius:50%;border:2px solid var(--ln);font:800 .74rem var(--display);background:#fff;transition:all .3s}
.fm-steps svg{width:12px;height:12px;fill:none;stroke:#fff;stroke-width:2.6;stroke-linecap:round;stroke-linejoin:round}
.fm-steps li.is-on button{color:var(--n);background:color-mix(in srgb,var(--c) 7%,#fff)}
