.fm-steps li.is-done button span{background:var(--ok);border-color:var(--ok)}
.fm-steps li.is-done button{color:var(--ok)}

/* pane */
.fm-pane{display:grid;gap:12px;animation:fmIn .35s cubic-bezier(.2,.7,.2,1) both}
.fm-pane[data-shake]{animation:fmShake .4s}
