/* ===== semantic colour tokens ===== */
:root{--c-navy:#07104F;--c-soft-blue:#E8EEFF;--c-teal:#0E9C88;--c-teal-soft:#E3F5F2;--c-green:#2F855A;--c-green-soft:#EAF6EF;--c-amber:#C99A2E;--c-amber-soft:#FBF3DF;--c-coral:#C2603F;--c-coral-soft:#FBEDE7;--c-violet:#5A3FE0;--c-violet-soft:#F1EEFD;--c-warm-grey:#F4F2EE}

/* ===== context-aware card hovers (no blanket blue fill) ===== */
:is(.hcard,.svc-card,.pillar,.why__card,.included__item,.ind-tile,.cs-card,.bcard,.dl-card,.policy-card,.portal-card,.product-card,.pstrip__item,.qc__item,.aud__item,.timeline__card,.rewards__card,.guide-card,
.rc-svc__card:not(.rc-svc__card--advisory),.rc-tk__mod,.rc-ind__item,.rc-why__mod,.rc-cap__col,.od-rec__tile,.od-meth__card,.od-use__card,.od-cap__item,.od-ind__tile,.od-plat a,.od-panel){
  --hov:var(--brand);--hov-bg:#fff;
  transition:background-color .35s ease,border-color .35s ease,box-shadow .35s ease,transform .35s cubic-bezier(.2,.7,.2,1)!important}
:is(.hcard,.svc-card,.pillar,.why__card,.included__item,.ind-tile,.cs-card,.bcard,.dl-card,.policy-card,.portal-card,.product-card,.pstrip__item,.qc__item,.aud__item,.timeline__card,.rewards__card,.guide-card,
.rc-svc__card:not(.rc-svc__card--advisory),.rc-tk__mod,.rc-ind__item,.rc-why__mod,.rc-cap__col,.od-rec__tile,.od-meth__card,.od-use__card,.od-cap__item,.od-ind__tile,.od-plat a,.od-panel):is(:hover,:focus-visible){
  background-color:var(--hov-bg)!important;border-color:var(--hov)!important;transform:translateY(-4px);
  box-shadow:inset 0 3px 0 var(--hov),0 22px 40px -28px rgba(7,16,79,.45)!important}
/* tone-aware: service areas use their own accent */
:is(.svc-card,.pillar,.product-card,.portal-card,.cs-card)[class*="tone-"]{--hov:var(--tone)}
/* research & service cards: accent border line only */
:is(.svc-card,.rc-svc__card,.cp-rel__card,.od-meth__card,.cp-prov__card,.guide-card,.included__item){--hov-bg:#fff}
/* quality & validation: soft green */
:is(.qc__item,.cp-qc__col,.od-rec__tile3,.mv-side--vision .mv-card:nth-child(1)){--hov:var(--c-green);--hov-bg:var(--c-green-soft)}
/* technology & data: violet */
:is(.product-card,.product-tile,.od-cap__item,.rc-tk__mod,.rc-cap__col,.dl-card){--hov:var(--c-violet);--hov-bg:var(--c-violet-soft)}
/* healthcare: teal */
:is(.od-panel--hc,.od-use__card:nth-child(6),.od-meth__card:nth-child(6),.cp-role:nth-child(6)){--hov:var(--c-teal);--hov-bg:var(--c-teal-soft)}
.od-panel--b2c{--hov:var(--c-teal)}
.od-panel--hc{--hov:#B07A00;--hov-bg:#FFFBF0}
/* global coverage & policy: warm amber */
:is(.policy-card,.rewards__card,.aud__item,.timeline__card){--hov:var(--c-amber);--hov-bg:var(--c-amber-soft)}
/* industries: each tile gets its own subtle accent */
:is(.ind-tile,.rc-ind__item,.od-ind__tile):nth-child(6n+1){--hov:var(--brand);--hov-bg:var(--c-soft-blue)}
:is(.ind-tile,.rc-ind__item,.od-ind__tile):nth-child(6n+2){--hov:var(--c-teal);--hov-bg:var(--c-teal-soft)}
:is(.ind-tile,.rc-ind__item,.od-ind__tile):nth-child(6n+3){--hov:var(--c-amber);--hov-bg:var(--c-amber-soft)}
:is(.ind-tile,.rc-ind__item,.od-ind__tile):nth-child(6n+4){--hov:var(--c-violet);--hov-bg:var(--c-violet-soft)}
:is(.ind-tile,.rc-ind__item,.od-ind__tile):nth-child(6n+5){--hov:var(--c-coral);--hov-bg:var(--c-coral-soft)}
:is(.ind-tile,.rc-ind__item,.od-ind__tile):nth-child(6n){--hov:var(--c-green);--hov-bg:var(--c-green-soft)}
:is(.ind-tile,.rc-ind__item,.od-ind__tile):is(:hover,:focus-visible) svg{color:var(--hov)!important;transform:scale(1.12);transition:transform .3s}
/* panel cards: image zoom + arrow nudge */
:is(.portal-card,.pstrip__item,.cp-pan__src,.od-panel,.bcard) img{transition:transform .5s ease}
:is(.portal-card,.pstrip__item,.cp-pan__src,.od-panel,.bcard):hover img{transform:scale(1.05)}
:is(.hcard,.portal-card,.od-panel,.cp-pan__src,.cp-rel__card,.od-plat a,.svc-card,.pillar):hover :is(.sr__go,[class*="__go"] .rc-ico,[class*="__cta"] .rc-ico,.od-plat .rc-ico,.cp-rel__card .rc-ico){transform:translateX(4px);transition:transform .3s}
/* icons: gentle lift */
:is(.pillar,.why__card,.svc-card,.od-rec__tile,.od-meth__card,.od-cap__item,.cp-prov__card,.cp-role,.rc-tk__mod):is(:hover,:focus-visible) :is([class*="__ic"],[class*="__icon"],>.rc-ico){transform:translateY(-2px) scale(1.06);transition:transform .3s}
/* mission & vision cards keep their own palette */
.mv-side--mission .mv-card:is(:hover,:focus-visible){background:rgba(255,255,255,.12)!important;border-color:#6EE0CE!important;box-shadow:inset 3px 0 0 #6EE0CE!important;transform:translateX(4px)}
.mv-side--vision .mv-card{--hov:var(--c-teal);--hov-bg:var(--c-teal-soft)}
.bp .rc-ind__item{--hov-bg:#fff}

