.sr__scrim{position:absolute;inset:0;border:0;background:rgba(7,16,79,.45);backdrop-filter:blur(4px);-webkit-backdrop-filter:blur(4px);animation:rcFade .2s ease forwards;opacity:0}
.sr__box{position:relative;width:min(680px,100%);max-height:min(640px,calc(100vh - 140px));display:flex;flex-direction:column;background:#fff;border-radius:20px;box-shadow:0 40px 80px -30px rgba(7,16,79,.6);overflow:hidden;animation:srIn .25s cubic-bezier(.2,.7,.2,1)}
