/* ===== Experience layer ===== */

/* --- cursor: native cursor hidden only once the custom one is live; the native one returns over text fields --- */
html.has-cur,html.has-cur *{cursor:none!important}
html.has-cur :is(input:not([type=checkbox]):not([type=radio]):not([type=submit]):not([type=button]),textarea,select,[contenteditable=true],iframe){cursor:auto!important}
.cur-dot,.cur-ring{position:fixed;left:0;top:0;pointer-events:none;z-index:2147483646;opacity:0;contain:layout style}
html.has-cur .cur-dot,html.has-cur .cur-ring{opacity:1}
html.cur-out .cur-dot,html.cur-out .cur-ring{opacity:0}
.cur-dot{width:8px;height:8px;margin:-4px 0 0 -4px;border-radius:50%;background:#fff;box-shadow:0 0 0 2px #07104F;will-change:transform}
.cur-ring{width:34px;height:34px;margin:-17px 0 0 -17px;border-radius:50%;border:2px solid #fff;box-shadow:0 0 0 1px #07104F99,inset 0 0 0 1px #07104F99;will-change:transform;transition:transform .09s linear,width .2s ease,height .2s ease,margin .2s ease,background-color .2s,border-color .2s,opacity .15s}
.cur-ring.is-hover{width:46px;height:46px;margin:-23px 0 0 -23px;border-color:#6EE0CE;background:#6EE0CE2e}
.cur-ring.is-down{width:26px;height:26px;margin:-13px 0 0 -13px}
.cur-ring.is-text,.cur-dot.is-text{opacity:0!important}
.btn,.sr-btn,.dial__chip{transition:background .2s,color .2s,border-color .2s,transform .2s,translate .25s cubic-bezier(.2,.7,.2,1)!important}

/* --- light-tracking spotlight on cards --- */
:is(.hcard,.svc-card,.pillar,.why__card,.included__item,.ind-tile,.cs-card,.dl-card,.policy-card,.portal-card,.product-card,.pstrip__item,.qc__item,.aud__item,.timeline__card,.rewards__card,.rc-svc__card:not(.rc-svc__card--advisory),.rc-tk__mod,.rc-ind__item,.rc-why__mod,.od-rec__tile,.od-meth__card,.od-use__card,.od-cap__item,.od-ind__tile,.bp-use__card,.bp-who__card,.hp-use__card,.hp-spec__card,.ca-card):hover{
  background-image:radial-gradient(240px circle at var(--sx,50%) var(--sy,50%),color-mix(in srgb,var(--hov,var(--acc,#0B22A8)) 13%,transparent),transparent 70%)!important}

/* --- Certified & Accountable --- */
.ca{position:relative;padding:clamp(48px,6vw,80px) 0;background:linear-gradient(180deg,#fff 0%,#F4F6FB 100%);border-bottom:1px solid var(--line)}
.ca__head{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:clamp(16px,4vw,56px);align-items:end;margin-bottom:28px}
.ca__k{display:inline-flex;align-items:center;gap:8px;font:700 .76rem var(--body);letter-spacing:.14em;text-transform:uppercase;color:#2F855A;margin-bottom:10px}
.ca__k--light{color:#7FE0DA}
.ca h2{margin:0;font-size:clamp(1.6rem,3vw,2.3rem)}
.ca__head p{margin:0;color:var(--muted)}
.ca__grid{display:grid;grid-template-columns:repeat(3,1fr) 1.35fr;gap:14px}
.ca-card{--hov:#2F855A;position:relative;display:flex;flex-direction:column;align-items:flex-start;padding:22px;border-radius:20px;background:#fff;border:1px solid var(--line);opacity:0;transform:translateY(14px);transition:opacity .6s,transform .6s,box-shadow .35s,border-color .35s;transition-delay:calc(var(--i)*.12s),calc(var(--i)*.12s),0s,0s}
.ca.is-in .ca-card,.ca.is-in .ca-esomar{opacity:1;transform:none}
.ca-card:hover{border-color:#2F855A;box-shadow:0 22px 44px -30px rgba(47,133,90,.6);transform:translateY(-4px)!important}
.ca-card__badge{position:relative;width:88px;height:88px;display:grid;place-items:center;margin-bottom:14px}
.ca-card__badge .cert{margin:0;width:72px;height:72px;display:grid;place-items:center}
.ca-card__badge .cert img,.ca-card__badge .cert svg{width:72px;height:72px;object-fit:contain}
.ca-card__badge .cert figcaption{display:none}
.ca-card__ring{position:absolute;inset:0;border-radius:50%;background:conic-gradient(from 0deg,#2F855A,#12A3A3,#1E6BFF,transparent 70%,#2F855A);-webkit-mask:radial-gradient(farthest-side,transparent calc(100% - 2px),#000 calc(100% - 1.5px));mask:radial-gradient(farthest-side,transparent calc(100% - 2px),#000 calc(100% - 1.5px));animation:rcSpin 9s linear infinite;opacity:.55;transition:opacity .3s}
.ca-card:hover .ca-card__ring{opacity:1;animation-duration:3s}
.ca-card__ok{position:absolute;top:18px;right:18px;display:inline-flex;align-items:center;gap:4px;padding:4px 9px;border-radius:999px;background:#EAF6EF;color:#2F855A;font:700 .7rem var(--body)}
.ca-card__code{font:800 1.12rem var(--display);color:var(--ink)}
.ca-card__t{font:600 .86rem var(--display);color:#2F855A;margin:2px 0 8px}
.ca-card p{margin:0;font-size:.86rem;color:var(--muted);line-height:1.5}
.ca-esomar{position:relative;overflow:hidden;display:flex;flex-direction:column;justify-content:flex-end;gap:6px;padding:26px;border-radius:20px;background:linear-gradient(150deg,#07104F,#0B2C5C);color:#fff;isolation:isolate;opacity:0;transform:translateY(14px);transition:opacity .6s .36s,transform .6s .36s}
.ca-esomar:before{content:"";position:absolute;inset:-60%;z-index:-2;background:conic-gradient(from 0deg,transparent 0 60%,#7FE0DA 72%,#1E6BFF 80%,transparent 90%);animation:rcSpin 7s linear infinite}
.ca-esomar:after{content:"";position:absolute;inset:1.5px;z-index:-1;border-radius:19px;background:linear-gradient(150deg,#07104F,#0B2C5C)}
.ca-esomar__net{position:absolute;right:-10px;top:-6px;width:62%;opacity:.5}
.ca-esomar__net line{stroke:#7FE0DA;stroke-width:1;opacity:.5}
.ca-esomar__net circle{fill:#7FE0DA}
.ca-esomar__logo{align-self:flex-start;padding:10px 14px;border-radius:12px;background:#fff;margin:4px 0 10px}
.ca-esomar__logo .esomar{display:block;margin:0}
.ca-esomar strong{font:800 1.25rem var(--display)}
.ca-esomar p{margin:0;color:#C8D3E6;font-size:.9rem}
.ca-esomar:hover:before{animation-duration:2.5s}

/* --- From insight to execution --- */
.ie{position:relative;overflow:hidden;background:linear-gradient(180deg,#F5F7FB 0%,#fff 100%)}
.ie__bg{position:absolute;inset:0;background-image:linear-gradient(rgba(11,34,168,.05) 1px,transparent 1px),linear-gradient(90deg,rgba(11,34,168,.05) 1px,transparent 1px);background-size:48px 48px;-webkit-mask-image:radial-gradient(ellipse at 50% 55%,#000 0%,transparent 70%);mask-image:radial-gradient(ellipse at 50% 55%,#000 0%,transparent 70%)}
.ie .container{position:relative}
.ie__head{text-align:center;max-width:760px;margin:0 auto 22px}
.ie__k{display:inline-block;font:700 .76rem var(--body);letter-spacing:.14em;text-transform:uppercase;color:#12A3A3;margin-bottom:10px}
.ie__head h2{font-size:clamp(2rem,4.2vw,3.2rem);margin-bottom:.3em}
.ie__head p{font-size:1.15rem;color:var(--muted);margin:0}
.ie__head em{font-style:normal;color:var(--ink);font-weight:600;background:linear-gradient(transparent 62%,rgba(227,160,19,.28) 62%)}
.ie__phases{list-style:none;margin:0 auto 18px;padding:0;display:flex;justify-content:center;flex-wrap:wrap;gap:6px}
.ie__phases li{padding:6px 12px;border-radius:999px;font:700 .74rem var(--body);letter-spacing:.08em;text-transform:uppercase;color:#97A0B5;background:#fff;border:1px solid var(--line);transition:all .4s}
.ie__phases li:not(:last-child):after{content:"→";margin-left:8px;color:#C5CCDA}
.ie__phases li.is-on{color:#fff;background:var(--ink);border-color:var(--ink)}
.ie__stage{position:relative;perspective:1400px}
.ie__layer{position:absolute;left:3%;right:3%;border-radius:28px;background:#E8EEFF;transform:rotateX(16deg)}
.ie__layer--1{top:24px;bottom:-14px;opacity:.6}
.ie__layer--2{left:6%;right:6%;top:40px;bottom:-28px;opacity:.35;background:#DCE5FF}
.ie__board{position:relative;border-radius:28px;background:linear-gradient(160deg,#07104F,#0B1A78 60%,#0B2C5C);padding:24px 12px 30px;transform:rotateX(10deg);transform-origin:50% 100%;box-shadow:0 50px 80px -50px rgba(7,16,79,.8);overflow:visible}
.ie__svg{width:100%;height:auto;display:block}
.ie__track{fill:none;stroke:rgba(255,255,255,.14);stroke-width:3;stroke-dasharray:2 8;stroke-linecap:round}
.ie__prog{fill:none;stroke:url(#ieGrad);stroke-width:4;stroke-linecap:round;stroke-dasharray:1;transition:stroke-dashoffset .15s linear}
.ie__pt{fill:#fff}
.ie__nodes{list-style:none;margin:0;padding:0;position:absolute;inset:24px 12px 30px}
.ie__node{position:absolute;transform:translate(-50%,-50%);display:flex;flex-direction:column;align-items:center;gap:8px;outline:none;cursor:pointer}
.ie__node .ie__lbl{order:-1}
.ie__node.is-low .ie__lbl{order:1}
.ie__dot{width:48px;height:48px;border-radius:50%;display:grid;place-items:center;background:#0E1A66;border:2px solid rgba(127,166,255,.5);color:#9DB6FF;transition:all .35s cubic-bezier(.2,.7,.2,1)}
.ie__node.is-on .ie__dot{background:#fff;border-color:#7FE0DA;color:#07104F;box-shadow:0 0 0 6px rgba(127,224,218,.15)}
.ie__node.is-cur .ie__dot,.ie__node:focus-visible .ie__dot{transform:scale(1.18);box-shadow:0 0 0 8px rgba(227,160,19,.22);border-color:#E3A013}
.ie__lbl{font:600 .9rem var(--display);color:#C9D3F5;white-space:nowrap;transition:color .3s}
.ie__lbl b{font:800 .7rem var(--body);color:#7FE0DA;margin-right:6px}
.ie__node.is-on .ie__lbl{color:#fff}
.ie__detail{position:relative;z-index:2;display:grid;grid-template-columns:auto 1fr auto;gap:18px;align-items:center;max-width:760px;margin:-22px auto 0;padding:18px 24px;border-radius:18px;background:#fff;border:1px solid var(--line);box-shadow:0 24px 50px -30px rgba(7,16,79,.55);animation:rcPanel .35s ease}
.ie__dn{font:800 2rem/1 var(--display);color:#12A3A3}
.ie__detail strong{font:700 1.1rem var(--display)}
.ie__detail p{margin:2px 0 0;color:var(--muted);font-size:.95rem}
.ie__phase{padding:6px 12px;border-radius:999px;background:#FBF3DF;color:#8A6000;font:700 .74rem var(--body);letter-spacing:.06em;text-transform:uppercase}
.ie__mob{display:none}
.ie__cta{margin-top:30px}

/* --- Values ecosystem --- */
.val{background:radial-gradient(800px 500px at 20% 40%,#EEF2FF 0%,transparent 60%),#fff;overflow:hidden}
.val__head{text-align:center;max-width:720px;margin:0 auto 20px}
.val__k{display:inline-block;font:700 .76rem var(--body);letter-spacing:.14em;text-transform:uppercase;color:#5A3FE0;margin-bottom:8px}
.val__head p{color:var(--muted);margin:0}
.val__wrap{display:grid;grid-template-columns:minmax(0,1.1fr) minmax(0,.9fr);gap:clamp(20px,4vw,56px);align-items:center}
.val__wrap>*{min-width:0}
.val__eco svg{width:100%;max-width:560px;display:block;margin:auto;overflow:visible}
.val__orbit{fill:none;stroke:#DDE2EC;stroke-dasharray:2 6;transform-origin:260px 260px;animation:rcSpin 120s linear infinite}
.val__orbit--in{stroke:#E8ECF4;stroke-dasharray:none;animation:none}
.val__spoke{stroke:#C9D2E6;stroke-width:1;transition:stroke .3s,stroke-width .3s}
.val__spoke.is-on{stroke:var(--c);stroke-width:2.5}
.val__chord{stroke:#E3E7EF;stroke-width:1}
.val__pkt{fill:#12A3A3}
.val__node{cursor:pointer;outline:none;opacity:0;transition:opacity .5s;transition-delay:calc(var(--i)*.06s)}
.val.is-in .val__node{opacity:1}
.val__bub{fill:#fff;stroke:var(--c);stroke-width:1.5;transition:fill .3s,r .3s}
.val__node foreignObject{color:var(--c);pointer-events:none;transition:color .3s}
.val__num{font:800 9px var(--display);fill:#97A0B5;pointer-events:none}
.val__node:hover .val__bub,.val__node.is-on .val__bub{fill:var(--c)}
.val__node.is-on .val__bub{r:36}
.val__node:hover foreignObject,.val__node.is-on foreignObject{color:#fff}
.val__node.is-on .val__num,.val__node:hover .val__num{fill:#fff}
.val__node:focus-visible .val__bub{stroke:#E3A013;stroke-width:3}
.val__core{fill:#07104F}
.val__corering{fill:none;stroke:#7FA6FF;stroke-width:2;transform-box:fill-box;transform-origin:center;animation:rcPulse 3.4s ease-out infinite}
.val__ct{font:800 14px var(--display);letter-spacing:.14em;fill:#fff}
.val__detail{position:relative;padding:clamp(24px,3vw,36px);border-radius:24px;background:#fff;border:1px solid var(--line);border-top:5px solid var(--c);box-shadow:0 30px 60px -44px rgba(7,16,79,.6);animation:rcPanel .4s ease;overflow:hidden}
.val__n{font:800 2.6rem/1 var(--display);color:var(--c)}
.val__n i{font-style:normal;font-size:1rem;color:#97A0B5}
.val__ic{position:absolute;top:24px;right:24px;width:52px;height:52px;border-radius:16px;display:grid;place-items:center;background:color-mix(in srgb,var(--c) 12%,#fff);color:var(--c)}
.val__detail h3{font-size:clamp(1.3rem,2.2vw,1.7rem);margin:12px 0 10px}
.val__detail p{color:var(--muted);font-size:1rem;line-height:1.65;margin:0 0 20px}
.val__nav{display:flex;align-items:center;gap:12px}
.val__nav>button{width:40px;height:40px;border-radius:50%;border:1px solid var(--line);background:#fff;color:var(--ink);font-size:1rem}
.val__nav>button:hover{border-color:var(--c);color:var(--c)}
.val__pips{display:flex;gap:5px;flex:1;justify-content:center}
.val__pips button{width:8px;height:8px;border-radius:50%;border:0;padding:0;background:#DDE2EC;transition:all .3s}
.val__pips button.is-on{width:22px;border-radius:4px;background:var(--c)}
.val__chips{display:flex;flex-wrap:wrap;justify-content:center;gap:6px;margin-top:22px}
.val__chips button{padding:7px 12px;border-radius:999px;border:1px solid var(--line);background:#fff;font-size:.82rem;font-weight:600;color:var(--muted);transition:all .25s}
.val__chips button:hover{border-color:var(--c);color:var(--c)}
.val__chips button.is-on{background:var(--c);border-color:var(--c);color:#fff}
.val__acc{display:none}

@media (max-width:1100px){
  .ca__grid{grid-template-columns:repeat(3,1fr)}
  .ca-esomar{grid-column:1/-1;min-height:200px}
  .ie__lbl{font-size:.78rem}
}
@media (max-width:900px){
  .ca__head,.val__wrap{grid-template-columns:1fr}
  .ie__board,.ie__layer,.ie__phases,.ie__detail{display:none}
  .ie__mob{display:grid;list-style:none;margin:0;padding:0;gap:0;position:relative}
  .ie__mob:before{content:"";position:absolute;left:23px;top:24px;bottom:24px;width:2px;background:linear-gradient(#1E6BFF,#12A3A3,#E3A013)}
  .ie__mob li{display:flex;gap:16px;padding:10px 0;position:relative;opacity:.4;transition:opacity .5s}
  .ie__mob li.is-on{opacity:1}
  .ie__mob .ie__dot{flex:none;position:relative;z-index:1}
  .ie__mob li.is-on .ie__dot{background:#fff;color:#07104F;border-color:#12A3A3}
  .ie__mob strong{display:block;font:700 1rem var(--display)}
  .ie__mob p{margin:2px 0 0;font-size:.9rem;color:var(--muted)}
  .val__eco svg{max-width:420px}
}
@media (max-width:640px){
  .ca__grid{grid-template-columns:1fr}
  .val__eco,.val__detail,.val__chips{display:none}
  .val__acc{display:grid;gap:8px}
  .val__acc details{border-radius:14px;border:1px solid var(--line);border-left:4px solid var(--c);background:#fff;overflow:hidden}
  .val__acc summary{display:flex;align-items:center;gap:10px;padding:14px 16px;font:700 .98rem var(--display);cursor:pointer;list-style:none}
  .val__acc summary::-webkit-details-marker{display:none}
  .val__acc summary span{font:800 .8rem var(--display);color:var(--c)}
  .val__acc summary .rc-ico{color:var(--c)}
  .val__acc p{margin:0;padding:0 16px 16px;color:var(--muted);font-size:.92rem}
}
@media (prefers-reduced-motion:reduce){
  .ca-card__ring,.ca-esomar:before,.val__orbit,.val__corering{animation:none!important}
  .ca-card,.ca-esomar,.val__node{opacity:1!important;transform:none!important}
}

/* --- performance --- */
.is-offscreen,.is-offscreen *,.is-offscreen *::before,.is-offscreen *::after,html.is-hidden-tab *{animation-play-state:paused!important}
/* expensive blur effects replaced with near-opaque fills */
*{-webkit-backdrop-filter:none!important;backdrop-filter:none!important}

/* promote continuously moving decorative layers to the compositor */
.hh-cube,.rc-spin,.dl-orbit,.dl-orbit img,.dl-stack__b,.mot-stream__track,.mot-net__node,.tm-ticker__track,.hm-marq,.br-seal__ring{will-change:transform}

/* ===== Navigation: translucent blue glass menus + tab interactions ===== */
.nav__link{position:relative;overflow:hidden;isolation:isolate;transition:color .25s,background-color .25s,box-shadow .25s,transform .2s}
.nav__link:hover{background:rgba(30,91,255,.08);color:#0B22A8}
.nav__link:active{transform:scale(.95)}
.nav__link.active{background:linear-gradient(135deg,rgba(30,91,255,.14),rgba(14,156,136,.10));color:#0B22A8;box-shadow:inset 0 0 0 1px rgba(30,91,255,.22)}
.nav__link--hl.active{background:linear-gradient(135deg,#0B22A8,#1E5BFF);color:#fff;box-shadow:0 6px 16px -8px rgba(11,34,168,.7)}
.nav__link::after{content:"";position:absolute;left:50%;bottom:4px;width:0;height:2px;border-radius:2px;background:linear-gradient(90deg,#1E5BFF,#6EE0CE);transform:translateX(-50%);transition:width .3s cubic-bezier(.2,.7,.2,1)}
.nav__link:hover::after,.nav__item.is-open .nav__link::after{width:42%}
.nav__link.active::after{width:0}
.nav__item.is-open .nav__link{background:rgba(30,91,255,.12);color:#0B22A8}
.nav__item.is-open .nav__link--hl{color:#0B22A8}
.nav__link .caret{transition:transform .3s}
.nav__item.is-open .caret{transform:rotate(225deg) translate(-2px,-2px);opacity:1}

/* tap ripple (nav tabs, menu items, drawer links) */
.nx-rip{position:absolute;border-radius:50%;pointer-events:none;transform:scale(0);opacity:.55;background:radial-gradient(circle,rgba(110,224,206,.9),rgba(30,91,255,.35) 60%,transparent 70%);animation:nxRip .6s ease-out forwards;z-index:0}
@keyframes nxRip{to{transform:scale(1);opacity:0}}

/* the panel: blue, see-through, blurred */
.mega{background:linear-gradient(135deg,rgba(11,34,168,.80),rgba(7,16,79,.86) 60%,rgba(14,80,120,.82));-webkit-backdrop-filter:blur(18px) saturate(1.4)!important;backdrop-filter:blur(18px) saturate(1.4)!important;border-top:1px solid rgba(255,255,255,.16);box-shadow:0 40px 70px -30px rgba(7,16,79,.75),inset 0 1px 0 rgba(255,255,255,.08);color:#fff;animation:nxDrop .35s cubic-bezier(.2,.8,.2,1)}
.mega::before{content:"";position:absolute;inset:0;pointer-events:none;background:radial-gradient(600px 220px at 15% 0%,rgba(30,91,255,.35),transparent 70%),radial-gradient(500px 220px at 90% 100%,rgba(110,224,206,.16),transparent 70%)}
.mega>*{position:relative}
@keyframes nxDrop{from{opacity:0;transform:translateY(-10px)}}
.mega__scrim{background:rgba(7,16,79,.30)}

/* small menus: About, Products, Portals, Downloads */
.mega__product{position:relative;overflow:hidden;isolation:isolate;background:rgba(255,255,255,.07);border:1px solid rgba(255,255,255,.14);border-radius:18px;color:#fff;transition:transform .35s cubic-bezier(.2,.8,.2,1),background-color .3s,border-color .3s,box-shadow .35s;animation:nxIn .45s cubic-bezier(.2,.8,.2,1) both}
.mega__product:nth-child(2){animation-delay:.05s}.mega__product:nth-child(3){animation-delay:.1s}.mega__product:nth-child(4){animation-delay:.15s}.mega__product:nth-child(5){animation-delay:.2s}.mega__product:nth-child(6){animation-delay:.25s}
@keyframes nxIn{from{opacity:0;transform:translateY(14px) scale(.98)}}
.mega__product strong{color:#fff;padding-right:28px}
.mega__product span{color:rgba(220,230,255,.78)}
.mega__product::before{content:"";position:absolute;inset:0;z-index:-1;background:linear-gradient(110deg,transparent 30%,rgba(255,255,255,.16) 50%,transparent 70%);transform:translateX(-120%);transition:transform .7s cubic-bezier(.2,.7,.2,1)}
.mega__product::after{content:"→";position:absolute;top:16px;right:18px;width:28px;height:28px;display:grid;place-items:center;border-radius:50%;font-weight:700;color:#07104F;background:#6EE0CE;opacity:0;transform:translateX(-8px) scale(.8);transition:opacity .3s,transform .35s cubic-bezier(.2,.8,.2,1)}
.mega__product:hover,.mega__product:focus-visible{background:rgba(30,91,255,.30);border-color:rgba(110,224,206,.55);transform:translateY(-4px);box-shadow:0 18px 34px -18px rgba(0,0,0,.6),0 0 0 1px rgba(110,224,206,.25),0 0 28px -6px rgba(30,91,255,.6)}
.mega__product:hover::before{transform:translateX(120%)}
.mega__product:hover::after,.mega__product:focus-visible::after{opacity:1;transform:none}
.mega__product:active{transform:translateY(-1px) scale(.98)}
.mega__product:hover span{color:#fff}
.mega__product.active{border-color:rgba(240,217,143,.7);background:rgba(240,217,143,.10)}
.mega__portal{border-left:1px solid rgba(255,255,255,.14);box-shadow:inset 4px 0 0 var(--tone)}
.mega__portal .mega__logo{background:#fff;padding:6px 10px;border-radius:10px;height:46px;width:auto;margin-bottom:10px;box-shadow:0 6px 14px -8px rgba(0,0,0,.5)}

/* services mega grid */
.mega__grid .mega__col{animation:nxIn .45s cubic-bezier(.2,.8,.2,1) both}
.mega__grid .mega__col:nth-child(2){animation-delay:.06s}.mega__grid .mega__col:nth-child(3){animation-delay:.12s}.mega__grid .mega__col:nth-child(4){animation-delay:.18s}
.mega__head{color:#fff;border-bottom-color:rgba(255,255,255,.18);position:relative;transition:color .25s}
.mega__head::after{content:"";position:absolute;left:0;bottom:-3px;height:3px;width:34%;border-radius:3px;background:var(--tone);transition:width .45s cubic-bezier(.2,.8,.2,1)}
.mega__col:hover .mega__head::after{width:100%}
.mega__head:hover{color:#F0D98F}
.mega__icon{background:rgba(255,255,255,.12);box-shadow:inset 0 0 0 1px rgba(255,255,255,.18)}
.mega__col li a{position:relative;color:rgba(220,230,255,.8);border-radius:8px;padding:4px 8px;margin:0 -8px;transition:color .2s,background-color .2s,padding .25s}
.mega__col li a:hover,.mega__col li a:focus-visible{color:#fff;text-decoration:none;background:rgba(255,255,255,.09);padding-left:14px}
.mega__col li a::before{content:"";position:absolute;left:4px;top:50%;width:4px;height:4px;margin-top:-2px;border-radius:50%;background:#6EE0CE;opacity:0;transition:opacity .2s}
.mega__col li a:hover::before{opacity:1}
.mega__col li a.active{color:#F0D98F}
.mega a:focus-visible{outline:2px solid #6EE0CE;outline-offset:2px}
.mega{scrollbar-color:rgba(255,255,255,.3) transparent}

/* mobile drawer links get the same press feedback */
.drawer__link,.drawer__sub a{position:relative;overflow:hidden;transition:background-color .2s,color .2s}
.drawer__link:active,.drawer__sub a:active{background:rgba(30,91,255,.1)}

/* browsers without backdrop blur: keep the panel readable */
@supports not ((-webkit-backdrop-filter:blur(1px)) or (backdrop-filter:blur(1px))){.mega{background:linear-gradient(135deg,rgba(11,34,168,.96),rgba(7,16,79,.97))}}

@media (prefers-reduced-motion:reduce){
  .mega,.mega__product,.mega__grid .mega__col{animation:none}
  .nx-rip{display:none}
  .mega__product,.mega__product::before,.mega__product::after,.nav__link,.nav__link::after{transition:none}
}
/* a blurred header is a backdrop root: drop its blur while a menu is open so the panel can blur the page */
.header.has-menu{-webkit-backdrop-filter:none;backdrop-filter:none;background:#fff}
.mega__col li a,.mega__head{overflow:hidden}


/* ===== Typography system: Manrope (display/headings) + Inter (body/UI) ===== */
:root{--display:"Manrope","Segoe UI",system-ui,-apple-system,sans-serif;--body:"Inter","Segoe UI",system-ui,-apple-system,sans-serif}
html,body{font-family:var(--body);font-weight:400;line-height:1.65;-webkit-font-smoothing:antialiased;text-rendering:optimizeLegibility;font-feature-settings:"cv11","ss01"}
p,li,dd,td,th,blockquote{font-family:var(--body)}
h1,h2,h3,h4,h5,h6{font-family:var(--display);font-style:normal}
h1{font-weight:800;letter-spacing:-.03em;line-height:1.06}
h2{font-weight:700;letter-spacing:-.022em;line-height:1.15}
h3{font-weight:600;letter-spacing:-.012em;line-height:1.25}
h4,h5,h6{font-weight:600;line-height:1.3}
/* navigation */
.header nav a,.header nav button,.drawer a,.drawer button,.nav__item>a,.nav__item>button{font-family:var(--body);font-weight:500}
.header nav a.active,.header nav a[aria-current]{font-weight:600}
/* buttons & CTAs */
.btn,a.btn,button.btn,.fm-go,.fm-chip,[class*="__cta"] .btn{font-family:var(--body)!important;font-weight:600!important;letter-spacing:0}
/* forms & labels */
label,legend,.fm label,.fm-f label,.fm legend{font-family:var(--body);font-weight:500}
input,select,textarea,button{font-family:var(--body)}
/* footer */
.footer,.footer p,.footer a,.footer li{font-family:var(--body);font-weight:400}
.footer h3,.footer h4{font-family:var(--display);font-weight:600}
/* no decorative italics */
em,i:not([class]){font-style:normal}

